INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sağ Ol Ben Selamet', 'sen-sag-ol-ben-selamet-murat-demir-673zr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilemedin sen beni

Kadrimi, kıymetimi

Al git merhametini

Seni artık istemem

Mademki çıktın namert

Sen sağ ol ben selamet

Ne sevildin ne saydın

Keşke hiç olmasaydın

Çekil git batsın adın

Seni artık istemem

Mademki çıktın namert

Sen sağ ol ben selamet

Ne güneşsin ne aysın

Sanmaki olmayansın

Kalbim yanarsa yansın

Seni artık istemem

Mademki çıktın namert

Sen sağ ol ben selamet', 'Bilemedin sen beni Kadrimi, kıymetimi Al git merhametini Seni artık istemem Mademki çıktın namert Sen sağ ol ben selamet Ne sevildin ne sayd...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-sag-ol-ben-selamet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayacaksın', 'unutamayacaksin-i-brahim-ugur-toprak-97hx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Senden kurtulmak için

Gideceğim'' demiştin

''Ben bu şehirden''

Yollar senin sevgili.

Nereye istersen,

Oraya gitmekte serbestsin.

Ama bil ki,

Söküp atmadıkça kalbini,

Varolduğu yerden

Benden kurtulamayacaksın

Dünyanın öbür ucuna da gitsen.

Çünkü, benimle atacak kalbin.

Ne yapsan, ne etsen,

Anılar gelecek sürekli peşinden.

Ve sen,

Unutamayacaksın! ..

06.08.04/Cuma

14:55/İzmir', '''Senden kurtulmak için Gideceğim'' demiştin ''Ben bu şehirden'' Yollar senin sevgili. Nereye istersen, Oraya gitmekte serbestsin. Ama bil ki, S...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutamayacaksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Korkan Dev', 'asktan-korkan-dev-nihal-eryurek-wpifi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devasa cüsseli bir adamdı o.

Buruktu sesi,gözleri buğulu.

sanki,

romantik bir devdi.

Korkuyordu aşktan.

ve sevda dendi mi,

düşünmeden atılıyordu  ön saflara.

''ben'' severim,beni sevmeseniz de olur,

diyenlerdendi.

Oysa,

kendine çılgınca aşık olanı seçseydi,

gecenin karanlığında yitecekti bedenleri.

oysa,

vazgeçse inadından,

yasak aşk da bile huzur bulacaktı.

hiç görmemiştim korkak dev.

bizim dev,korkaktı.', 'Devasa cüsseli bir adamdı o. Buruktu sesi,gözleri buğulu. sanki, romantik bir devdi. Korkuyordu aşktan. ve sevda dendi mi, düşünmeden atılıy...', ARRAY['Türk Edebiyatı','Şiir','Nihal Eryürek']::text[], 8.5, '{"poet":"Nihal Eryürek","poet_slug":"nihal-eryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asktan-korkan-dev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Şu Fincanın Haline', 'bak-su-fincanin-haline-nihal-eryurek-44ssu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayata kümüşlüğüm çıkmadı falımda.

Sen yoktun,

balık yoktu,

yol yoktu....

kabarmıştı yüreğim,sıkkın.

karamsardı gönlüm,bıkkın.

yorulmuştu çalışmaktan,yılgın.

falcı bile ağladı fincanımın haline.

Telve çığlık şığlığa.

2003-Akhisar', 'Hayata kümüşlüğüm çıkmadı falımda. Sen yoktun, balık yoktu, yol yoktu.... kabarmıştı yüreğim,sıkkın. karamsardı gönlüm,bıkkın. yorulmuştu ça...', ARRAY['Türk Edebiyatı','Şiir','Nihal Eryürek']::text[], 8.5, '{"poet":"Nihal Eryürek","poet_slug":"nihal-eryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bak-su-fincanin-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Yeri Ağarırken', 'tan-yeri-agarirken-i-brahim-ugur-toprak-ft8w6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbetin hüznü, gece çöker burada.

Hele, hava soğuyup, yağmur da yağınca

Sen gör o zaman, kalplerde açılan yarayı.

Sen gör o zaman, çekilen bunca acıyı

Bir dokunursan onlara,

Bin ah işitirsin.

Duyguları aynıdır hepsinin,

Sıla özlemi, ana hasreti.

Herkes dertlidir, herkes garip.

Herkes aynı dertten muzdarip.

Kardeş hasreti, dost özlemi.

Saatler dolmaz.

Gurbet elde sabah hiç olmaz.

Beklersin, beklersin güneşi,

Ama doğmaz.

Derken,

Bir yağmur başlar göz pınarlarından

Ve çoğalarak hüzün denizine akan.

Sonra, kuşları görürsün

Yurduna dönen.

Tam tan yeri ağarırken.

Ve işte o anda,

Bir hüzün kaplar ruhunu.

Kulaklarındaki yalnızlığının uğultusu.

Bir çocuk görürsün sonra sokakta.

Yağmurdan büsbütün ıslanan.

Bir türkü tutturmuş söyler, gözleri nemli.

Bakışlarından okunur, sılaya dair hasreti.

O küçük çocuk yüreğidir, hızla çarpan.

Sözlerinde sitem vardır, gözlerinde nem.

Kalbinde hiç eksilmeyen bir özlem.

Ve bu hep böyle sürüp gidecek

Ta ki bir gün, sılaya dönülünceye dek 

06.04.99/Salı

00:48/Tekirdağ', 'Gurbetin hüznü, gece çöker burada. Hele, hava soğuyup, yağmur da yağınca Sen gör o zaman, kalplerde açılan yarayı. Sen gör o zaman, çekilen ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tan-yeri-agarirken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Dikeni', 'gulun-dikeni-i-brahim-ugur-toprak-iey08', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş oldum

Sabahlarına doğdum

Günün ilk ışığı oldum

Serildim yatağına

Sevgi oldum

Düştüm aklına

Gökkuşağında bir renk oldum

Gözlerinde bitiverdim

Kayan bir yıldız oldum

Dileğine girdim

Hep hayalin olmak istedim

Birden dünyanda kayboluverdim

Mehtap oldum gecede

Yansıdım yıldızda gözlerine

Yakamoz oldum denizde

Süzüldüm yavaşça tenine

Esen tatlı bir rüzgardım

Girip bedenini sardım

Derken mutluluk oldum

İçine sığamadım, taştım

Bazen de yağmur oldum

Aktım gözlerinden damla damla

Ve bülbül oldum sonunda

Dikeni battı gülün boynuma

Aktı kanlarım damla damla

Boyadı beyaz gülü ala

Süzüldü kanlar yaprağına

Su oldu aktı toprağına

Gülü sevdim

Lakin katlanamadım dikenine

Yar etmedi Tanrım

Beni bir türlü sevdiğime

Aldı beni benden

Seni yakalayamadan

Kopardı seni benden

Daha kavuşamadan

Kaldıramadım başımı dertten

Bir diğerini verdi, henüz biri bitmeden

Bülbülü öldüren değil mi

Gülün dikeni? 

Sen de sevsene 

Seni seveni

Bülbül oldum, gözlerim yolda

Haydi! Gel de, bu gülü soldurma.

30.04.98/Perşembe

00:01/Tekirdağ', 'Güneş oldum Sabahlarına doğdum Günün ilk ışığı oldum Serildim yatağına Sevgi oldum Düştüm aklına Gökkuşağında bir renk oldum Gözlerinde biti...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gulun-dikeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarıyorum Vazgeçme', 'yalvariyorum-vazgecme-metin-kose-mzuok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzü ağlarken 

Bomboş sokaklarda 

Sırılsıklam dolanıyorsan 

Bütün kapıların kapandığı 

Bu kayıp şehirde 

Umutla döndüğün köşelerden

Bir boşluk karşılıyorsa seni 

Ellerin boş kalıyorsa

Yine de vazgeçme 

Yalvarıyorum vazgeçme 

Biliyorum 

Bir köşede bulacaksın 

Biliyorum

Ben de seni arıyorum...

09.08.2004

Bakanlıklar/Ankara

11.38', 'Gökyüzü ağlarken  Bomboş sokaklarda  Sırılsıklam dolanıyorsan  Bütün kapıların kapandığı  Bu kayıp şehirde  Umutla döndüğün köşelerden Bir b...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalvariyorum-vazgecme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçip Giden Günlerim', 'gecip-giden-gunlerim-i-brahim-ugur-toprak-6sr16', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün daha ağarıyor karşı kıyıdan

Ümitlerim yeşeriyor onunla tekrardan

Dinecek bu hasret, bitecek bu özlem

Ben yine seni, yine yolunu gözlüyorum

Güneş yükselirken göğe

Martılar gene balık peşinde

Pike yapıp, dalıyor denize

Bense, onları izliyorum hüzünle

Koca bir gün bitmek üzere

Güneş batmak üzre sevgilim

Ümitlerim kaldı yine

Bir başka bahara

Ümitsiz bir bekleyiş de olsa

Ben seni, gene bekleyeceğim

Güneş dağların ardında yine

Ayın gölgesi vuruyor artık denize

Üç beş yıldız, bu gece de gökyüzünde

Bense, hala seni düşünüyorum

Bir günü daha bitirdim 

Sensiz ama seninle

Güneşi de batırdım

Yalnız ama seninle

İşte! Böyle sevdiğim

Geçip gidiyor günlerim

Seni sensiz yaşayarak

Seni kalbimde taşıyarak

27.03.98/Cuma

23:38/Tekirdağ', 'Bir gün daha ağarıyor karşı kıyıdan Ümitlerim yeşeriyor onunla tekrardan Dinecek bu hasret, bitecek bu özlem Ben yine seni, yine yolunu gözl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gecip-giden-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşarsın', 'sasarsin-hakki-hakan-kaya-isxwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana kalbimi açmaya gelirken

Şaşarsın geçtiğim yolları görsen

Bir damla sevdaya aşkla yürürken

Şaşarsın kırdığım dalları görsen

Aşıklar ilhamını aldı benden

Bin dertle yananlar huzurlu senden

Sevda uğruna beklediğim yerden

Şaşarsın kaçtığım kolları görsen

Ölümse sevgili beni seçin

Sevda tarlasında ömrümü biçin

Karanlıkta yürüdüm aşkın için

Şaşarsın verdiğim yılları görsen

Gülü vermeli bülbülün yanına

Acı sürmemeli sevda tadına

Çabalamadan olmaz aşk adına

Şaşarsın geçtiğim çölleri görsen', 'Sana kalbimi açmaya gelirken Şaşarsın geçtiğim yolları görsen Bir damla sevdaya aşkla yürürken Şaşarsın kırdığım dalları görsen Aşıklar ilha...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sasarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretine İnat', 'hasretine-i-nat-burak-killioglu-2o981', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zihnim bulandı durduk yere,

Geleceğimden korktum.

Belirsizlik endişelendirir ya insanı,

Öylece bir tedirginlik sardı

Geleceğinden korktum.

En büyük mutluluğun

Koskocaman bir kabusa dönüşmesiydin.

Kendimden korkmadığım kadar

Korktum senden.

Ve kendimi sevmediğim ölçüde

Sana bağlandım.

Korkularıyla yüzleşmeli insan...

Apansızın çıksan karşıma

Ölesiye korksam,

Korkudan dolmalı gözlerim.

Ne yalan söyleyeyim,

Korkudan değil ama

Sevincimden ağlasam.

Islansa yüreğim, hasretine inat...', 'Zihnim bulandı durduk yere, Geleceğimden korktum. Belirsizlik endişelendirir ya insanı, Öylece bir tedirginlik sardı Geleceğinden korktum. E...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hasretine-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertelenmişlik', 'ertelenmislik-ozgur-doran-iceoj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkları erteledik

                                            küçük korkular 

                             için

Yalnızlığın kısır         döngüsünde

             daha   b ü y ü k 

Acılar 

                       varolduğunu bile 

                                                      bile', 'Aşkları erteledik                                             küçük korkular                               için Yalnızlığın kısır         dö...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ertelenmislik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Habersiz', 'senden-habersiz-mustafa-yigit-morpheus-6wupo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elimde resmin, yüreğimde sen

Ağlıyorum sana, senden habersiz

Sensiz geçen yıllara inat ben

Ağlıyorum sana, senden habersiz

Yüreğimde aşkım dağlara gitsem

Geçtiğin yollara, yüzümü sürsem

Sevdalo gönüllere gözyaşı dölsem

Ağlıyorum sana, senden habersiz

Yaralı bir ceylansın, aşkın dağında

Koparılmamış gülsün, gönül bağında

Bu sonsuz yılların, sevda çağında

Ağlıyorum sana, senden habersiz

Barış güvercinisin, göklerde uçan

Sevda çiçeğisin, gönüllerde açan

Bir kelebeksin, sevdalara koşan

Ağlıyorum sana, senden habersiz

Durağın gönlünün umut ışığı

Gönüllere taht kuran sevda aşığı

Pas tutan gönlümün yegane aşkı

Ağlıyorum sana, senden habersiz

 Mustafa Yiğit (Morpheus)', 'Elimde resmin, yüreğimde sen Ağlıyorum sana, senden habersiz Sensiz geçen yıllara inat ben Ağlıyorum sana, senden habersiz Yüreğimde aşkım d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senden-habersiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veli Emmi', 'veli-emmi-cafer-petek-u3dga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susuz ırmaklarda yundum

Hergece aymadı beni üşümeler

Aymadı her sabah

Yatağımda ölü güvercinler buluşum

Solgun bir nisan akşamıydı

Mevsimler yaşadım fukara mevsimler

Mevsimleri fukara yaşadım

Aymadı beni toprağa eğilen çiçek başları

Anaç kirpidir şimdi gelmez dokunmalara

Yüreğimde yüreğin kuru bir daldır

Tutuşmalara gebedir

Kızgın kumlarda yalın ayak

Dudaklarım susuzluğun aynasıdır

Bir yanım sevimsiz ölümlerle çoğalır

Bir yanım ateş çemberinde

Silahsızım

Toprağa değmez alnım

Secdelerim ayak üstü yaşıyoruz ya

Hayat hep akşamüstü

Kırık dökük ağır aksak

Yaşamayabilemiyoruz

Sesinde bülbüller oynaşan adam

Yelatan’dan cehennem deresi’ne

Hangi ardıca dokunsam

Dalına asılı türkülerin

Dökülür avuçlarıma

Delihasan’da tuz taşlarında kurumuş

Umutlarına değende gözyaşlarım

Çıkınını buldum bir kekliğin kırık kanadında

Yol ortasında bir meşe bastonla

Hayata direnen adam

Kim cesaret edebilir ki anlamaya seni

Ya ikimiz

Bir adam

Eder miyiz

Veli emmi

Ahh veli emmi', 'Susuz ırmaklarda yundum Hergece aymadı beni üşümeler Aymadı her sabah Yatağımda ölü güvercinler buluşum Solgun bir nisan akşamıydı Mevsimler...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/veli-emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-mustafa-yigit-morpheus-66p5o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz bu ellerin

Tadı yok geçen günlerin

Telefondaki gel diyişin

İnan kulaklarımda çınlıyor

Hüzünlü hüzünlü bakışların

Saçlarımı ağır ağır okşayışın

Ayrıldığımız andaki ağlayışın

İnan gözümden hiç gitmiyor

Ne olur gitme deyişin

Ben çıkana kadar bekleyişin

Arkamdan el sallayışın

Hiçbir zaman aklımdan çıkmıyor

Geceleri rüyamda görüyorum

Ellerini uzatıp gel diyorsun

Ellerimi sana doğru uzatıyorum

Seni her şeyden çok seviyorum

 Mustafa Yiğit (Morpheus)', 'Sensiz bu ellerin Tadı yok geçen günlerin Telefondaki gel diyişin İnan kulaklarımda çınlıyor Hüzünlü hüzünlü bakışların Saçlarımı ağır ağır ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdigim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemem', 'sevemem-mustafa-yigit-morpheus-hgd7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin olduğu yerde yıldız istemem

Sevginin olduğu yerde nefret istemem

Mutluluğun olduğu yerde ayrılmayı istemem

Dünya güzelide olsa senden başkasını sevemem

Sen benim için çöl ortasında su gibisin

Uzaklarda olsanda yine benim sevdiğimsin

Umudum, hasretim her şeyim sensin

Cenneti verselerde senden başkasını sevemem

Bülbül güle hasret, gül kokusunda varsın

Balık suya hasret, su damlasında varsın

İnsan yaşamaya hasret, kalp atışında varsın

Dünyalar benim olsada senden başkasını sevemem

Her uçan kuş aşkımızı söylüyor

İnan yağan yağmur sevgimizi fısıldıyor

Tüm şiir ve şarkılar sevdamızı konuşuyor

İdam sehpasınada çıksam senden başkasını sevemem

 Mustafa Yiğit (Morpheus)', 'Güneşin olduğu yerde yıldız istemem Sevginin olduğu yerde nefret istemem Mutluluğun olduğu yerde ayrılmayı istemem Dünya güzelide olsa sende...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Çarem Ah', 'ah-carem-ah-taha-nur-zwm4l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah çarem ah! Bu gece seni kâlbimde sakladım.

Hep orada kalmanı öyle istedim ki,

Kâlbimi yumruk gibi yaptım.

Ah çarem ah! Parçaladın kâlbimi,

Aktın, damarlarıma aktın...

Ah çarem ah! Bu gece damarlarımda,

Geç saatlere kadar, kan yerine aktın.

Ah çarem ah! Yaktın, ta içimi yaktın...

Ah çarem ah! Bu gece seni damarlarımda sakladım.

Orada, hep orada kalacağını sandım.

Ama sen, damarlarımı kurutup da gözlerime aktın.

Ah çarem ah! Yaktın, ta içimi yaktın...

Ah çarem ah! Bu gece gözlerimde,

Geç saatlere kadar, sen vardın.

Kapalı tuttum gözlerimi, 

Akmayasın diye.

Ah çarem ah! Çok iyi yumdum gözlerimi,

Ama sen yine yol buldun.

Aktın, ta beynime aktın...

Ah çarem ah! Yaktın, ta içimi yaktın...

Ah çarem ah! Bu gece beynimin kıvrımlarında,

Geç saatlere kadar, dolaştın dolaştın.

Beynimin kıvrımlarında sen,

Kıvrım kıvrım kıvranan ben.

Ah çarem ah! Çok korktum. 

Delirmekten değil.

Kıvrımlardan da akarsın diye...

Ah çarem ah! Yine yol buldun, aktın.

Beynimin kıvrımlarını önce kuruttun,

Sonra adını yazdın.

Arkanda, bir mecnun bıraktın.

Sen sonsuzluğa aktın...

Ah çarem ah! Mecnun oldum,

Ama mutluyum.

Çünkü, sonsuzluktan akıp gitmen,

Artık olası değil...', 'Ah çarem ah! Bu gece seni kâlbimde sakladım. Hep orada kalmanı öyle istedim ki, Kâlbimi yumruk gibi yaptım. Ah çarem ah! Parçaladın kâlbimi,...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ah-carem-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-i-dris-halil-kabalci-ry085', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı sende öğrendim, yiğitliği sende,

Bir başka oluyor insan seni görende,

İsmimi sorarsan Kabalcıoğlu Halil derler,

Aşkı sende öğrendim, yiğitliği sende,

Çocukluğum ve gençliğim, bir ömür boyum,

Özlemlerim sende kaldı, sende köyüm,

Yalnızlıktan kurşun attığım yerler,

Sevdayı sende öğrendim, öteleri sende.', 'Aşkı sende öğrendim, yiğitliği sende, Bir başka oluyor insan seni görende, İsmimi sorarsan Kabalcıoğlu Halil derler, Aşkı sende öğrendim, yi...', ARRAY['Türk Edebiyatı','Şiir','İdris Halil Kabalcı']::text[], 8.5, '{"poet":"İdris Halil Kabalcı","poet_slug":"i-dris-halil-kabalci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/memleketim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunay Akın', 'sunay-akin-emre-senkal-d2pyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Niçin oynuyorsun kelimelerle

Kelimeler çocuğunmu senin

Yada sokak çocuğumu tüm kelimeler

Ve sen çok mu seviyorsun sokak çocuklarını

Niçin sen onlarla oynadıkça

Biz seviniyoruz

Niçin bir çikolata tadı var ağzımda

Sen onların kafasını her okşadığında', 'Niçin oynuyorsun kelimelerle Kelimeler çocuğunmu senin Yada sokak çocuğumu tüm kelimeler Ve sen çok mu seviyorsun sokak çocuklarını Niçin se...', ARRAY['Türk Edebiyatı','Şiir','Emre Şenkal']::text[], 8.5, '{"poet":"Emre Şenkal","poet_slug":"emre-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sunay-akin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-ozgur-doran-bm0ks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soluk birer resim oluyor 

              geçen her yeni 

                                   gün

          sana dair 

                              kayıtların

                                        tutulmadığı

Issız sokaklarında 

                           çimen yeşili rüzgarların 

oyun oynadığı 

                           kent eskisiyim 

                                artık

Yokluğunla çoğalan 

                                mutluluklar 

                                                        arıyorum', 'Soluk birer resim oluyor                geçen her yeni                                     gün           sana dair                          ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoklugun-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustalarım Şairler-Ozanlar', 'ustalarim-sairler-ozanlar-mustafa-toga-rafzm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçükken Yunus Emre, Karacaoğlan, Pir Sultan Abdal, 

Ve Dadaloğlu’nun şiirlerini ezberlerdim.

Kafiye, durak, redif, nakarat derken,

Bolca okudum Yahya Kemal Beyatlı’dan.

Unutmadım Faruk Nafiz Çamlıbel’le Fazıl Hüsnü Dağlarca’yı

Ílham aldım her zaman Orhan Veli, Cahit Külebi’den.

Íşte güçlü kalemler Nazım Hikmet, Necip Fazıl Kısakürek

Saf Türkçe kullanmaya çalıştım Cahit Sıtkı Tarancı gibi,

Hiciv kaptım Ümit Yaşar Oğuzcan’dan.

Sıkça Ceyhun Atuf Kansu’yla, Aşık Veysel’e baktım

Dağarcığımı tıka basa doldurdum.

Şiirden düzyazıya, röportajdan öyküye

Akıp gitti kalemimin ucundan.

Behçet Necatigil, Sabahattin Kudret Aksal gibi

Daha nice ismini yazamadığım 

Genç şairler yetişti,

Necati Cumali, Oktay Rifat, Can Yücel ve de Ali Püsküllüoğlu.

Bunların hepsi birbirinden değerli

Türk şiirinin gözbebeği,

Ustalarım,

Şairler.

SÖZÜN ÖZÜ: 

İlim, akrabalar tarafından yağma edilemeyen, hırsızlar tarafından çalınamayan ve başkaları ile paylaşılınca yegâne servettir. (Bhavabbuti)', 'Küçükken Yunus Emre, Karacaoğlan, Pir Sultan Abdal,  Ve Dadaloğlu’nun şiirlerini ezberlerdim. Kafiye, durak, redif, nakarat derken, Bolca ok...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ustalarim-sairler-ozanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Sana Kaçarım', 'benden-sana-kacarim-necmi-unsal-17fke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutuşmuş bu sinem,  kora dönmüş.

Lalezara gönlümü  açarım.

Gözlerimde fer hasretle sönmüş.

Düşmüşüm bir sevdaya, nâçârım.

Gönlüm deniz, tayfurla savruldum.

Benden sana, benlikten kaçarım.

Zerre zerre seninle kavruldum.

Hamdım yandım, sevgiler saçarım.

Yetsin artık, bu hasretler bitsin! 

Visal için sana el açarım.

Yoluna bu canım  kurban gitsin.

Şahadetten yana dil açarım.

9 Haziran 2004 Çarşamba, Danimarka-Køge 20.53

4+6', 'Tutuşmuş bu sinem,  kora dönmüş. Lalezara gönlümü  açarım. Gözlerimde fer hasretle sönmüş. Düşmüşüm bir sevdaya, nâçârım. Gönlüm deniz, tayf...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benden-sana-kacarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Non-Existence', 'non-existence-ozgur-doran-wkm9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuş atımı mesafelerde

Nefes alıp vermeyi unuttuğum 

Zamanlar

İnce bir çizgidir 

                        yokoluş', 'Bir kuş atımı mesafelerde Nefes alıp vermeyi unuttuğum  Zamanlar İnce bir çizgidir                          yokoluş...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/non-existence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemiyorum', 'sevemiyorum-mustafa-yigit-morpheus-ariir', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbim param parça, gönlümse buruk

Dünyadan bir zevk alamıyorum

Kanlı yaşla doldu gözlerim

Sevgilim artık seni göremiyorum

Kalbim artık sevgilere kapandı

Gönlüm hayattan bıktı usandı

Deli gönlüm ne kadar da dayandı

Sevgilim artık seni sevemiyorum

Ağlamakdan gözlerim görmez oldu

Peşinde koşmakdan ayaklarım yoruldu

Sen gittikden sonra saçlarım akla doldu

Sevgilim artık peşinden gelemiyorum

 Mustafa Yiğit (Morpheus)', 'Kalbim param parça, gönlümse buruk Dünyadan bir zevk alamıyorum Kanlı yaşla doldu gözlerim Sevgilim artık seni göremiyorum Kalbim artık sevg...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevemiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi Sermet Bey', 'i-lahi-sermet-bey-zemci-cetinkaya-87akr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birazdan gelecek Sermet Bey

Akşamın bu vaktinde

Yine kazandığı son paraları anlatacak.

Ve haklı olarak onun

Ne şu nisan yağmuru umurunda

Ne şu salkım söğüt.

Birazdan gelecek Sermet bey

Girmeden almanca çeviri dersine

Beyaz arabasından

Ve beyaz arabasının sony teybinden bahsedecek.

Ve haklı olarak onun

Ne şu elma gözlü at umurunda

Ne şu sakar oğlak.

Birazdan gelecek Sermet bey

Son hazırlıklarını yaparken

Fermuarlı çantasını açıp bir taraftan 

Döviz kurlarını söyleyecek.

Ve haklı olarak onun

Ne taşralı öğrencisi Murtaza''nın aşkı umurunda

Ne de Murtaza''ya bîgâne kentsoylu Serap''ın kumral saçları.', 'Birazdan gelecek Sermet Bey Akşamın bu vaktinde Yine kazandığı son paraları anlatacak. Ve haklı olarak onun Ne şu nisan yağmuru umurunda Ne ...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ilahi-sermet-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Denizi', 'sevgi-denizi-mustafa-yigit-morpheus-9z0v1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamıyorum güzelim sen beni sevmesende

Söz geçiremiyorum şu çileli gönlüme

Sahip olamıyorum deli gibi atan kalbime

Hep seni bekliyorum ıssız bir sevgi denizinde

Umutlarımı saldım dört bir tarafa

Açtım ellerimi yalvarıyorum rabbıma

Hep seni bekliyorum bak sabırla

Deryayı andıran ıssız bir sevgi denizinde

Umutsuzluğa yer yok divane gönlümde

Sanki bir nursun ağlayan gözlerimde

Mecnunun leylasını beklediği gibi bende

Hep seni bekliyorum ıssız bir sevgi denizinde

Şu divane gönlüm kanatlanıp uçacak şimdi

Uçup gül bahcesine konacak şimdi

Uyuma güzelim yanına gelecek şimdi

Sensiz boğulacağım ıssız bir sevgi denizinde

 Mustafa Yiğit (Morpheus)', 'Unutamıyorum güzelim sen beni sevmesende Söz geçiremiyorum şu çileli gönlüme Sahip olamıyorum deli gibi atan kalbime Hep seni bekliyorum ıss...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-denizi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küf Yosunu', 'kuf-yosunu-hatice-ari-dx93b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim adım Kara Deniz,

Adım çıkmış dertli deniz,

Ah bilseniz, bir bilseniz,

Dertler bende derya deniz,

Gemim mi battı dersiniz? 

Bu da sağ kolum Marmara,

Bir ayağı Bandırmada,

Boğazı dilim ucunda

Altlı üstlü boğuşuruz,

Kuzuları değişiriz,

Yumşaktır huyumuz bizim,

Tuzsuzdur suyumuz bizim,

Peki derdin ne, derseniz

Derdimizi demek lazım.

Hamsilerim salkım söğüt,

Palamutum, mezgitim var; 

Hem ürkektir, hem de çevik,

Kefallerim trilyonluk,

At ağını kaptan çabuk,

Çok açılma gelgitim var,

Dalyanlarım ağı yarar,

Söylüyorum, sana zarar,

Lezzetlidir beyaz eti,

Havyarı da etiketi.

Biraz tembel levreğim var,

Derin  sularımda yaşar

Kaya ovuğ, batık kavuğ,

Yaşlanan ayırır yolu

İstersen ızgara yap ye,

İstersen buğuyu dene.

Damağında kalır tadı,

Bundandır ateş pahası.

Sardalyalar sürü sürü,

Orkinozum iri iri,

Yavrularım kışın yazın,

İşte böyle oğlum kızım,

Avlama vakitsiz onu,

Avlamazsan alın geri,

Döktüğün onca emeği.

Bana derler Rıza Kaptan,

Şu gördüğün eski takam,

Üç çocuğum, bir de anam,

Kimsem yok ki, arka çıkan,

Tüm ekmeğim Kara Deniz,

Vakitsiz de avlanmayız; 

Lakin gene azdır avım,

Çöpünüzü akıtmayın,

Benim güzel yarenlerim,

Kuzu ölür, derya ağlar,

Dalgalar ciğerimi dağlar

Daha lafı uzatmayın,

Anam der ki, torunuylan,

''Rastgele kaptan! '' ardımdan.

Benim özüm Arı şair,

Sözüm şu meclise dair,

Yosun küf kokmuş, mavi kir; 

Ne sen aç kal, ne kalemi kır,

Söyleneni görmez hakir,

Bilinçli insan gerekir...', 'Benim adım Kara Deniz, Adım çıkmış dertli deniz, Ah bilseniz, bir bilseniz, Dertler bende derya deniz, Gemim mi battı dersiniz?  Bu da sağ k...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/kuf-yosunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-mustafa-yigit-morpheus-jhlbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzandı kollarım sensiz boşluğa

Kendimi bir türlü avutamadım

Her güneş doğuşunda baktım ufuklara

Sensizliğe bir türlü alışamadım

İsmini yazdım tüm ağaçlara

Hep seni anlattım uçan kuşlara

Haykırmak istedim yüce dağlara

Gururum mani oldu haykıramadım

Yağan yağmurda hayalini gördüm

Mavi bulutlara resmini çizdim

Bu canımı yalnız sana adadım

Ölmeyi denedim başaramadım

Senden uzakta hayaller kuruyorum

Bir gün kavuşuruz diye kendimi avutuyorum

Esen yellere hep seni soruyorum

Hasretine bir türlüalışamadım

Sen yanımda yoksun dünyam bom boş şimdi

Bana teselli verecek bir arkadaşım yok ki

Sende beni sevsen ne olur sanki

Sensiz bu gurbetele alışamadım

Sevgilim böyle dönmez bu devran

Mutlaka çıkar sanada bir darbe vuran

Sende benim halime düştüğün zaman

Sevgilim üzülmene dayanamam.

 Mustafa Yiğit (Morpheus)', 'Uzandı kollarım sensiz boşluğa Kendimi bir türlü avutamadım Her güneş doğuşunda baktım ufuklara Sensizliğe bir türlü alışamadım İsmini yazdı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgilim-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim1', 'sevgilim1-mustafa-yigit-morpheus-i4i6v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi gökyüzünü bulutlar sardı

Senin hasretinin beni sardığı gibi

Uçan kuşlar semada hep yalnız kaldı

Senden uzakta yalnız kaldığım gibi

Karanlık çöktü gündüzlerime

Hiç bakan yok artık gözlerime

Hasret kaldım bembeyaz tenine

Bülbülün güle hasret kaldığı gibi

Burada ağaçlar birer birer sarardı

Yalnızca bir sevda ağacı kaldı

İnan hasretin bağrımı deldi

Okun hedefini deldiği gibi

Siyah saçlarım bembeyaz oldu

Bana olan sevgine şimdi ne oldu

Senin sevgi anlayışın demek buydu

Seven kalplerin taş olduğu gibi

 Mustafa Yiğit (Morpheus)', 'Mavi gökyüzünü bulutlar sardı Senin hasretinin beni sardığı gibi Uçan kuşlar semada hep yalnız kaldı Senden uzakta yalnız kaldığım gibi Kara...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgilim1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim2', 'sevgilim2-mustafa-yigit-morpheus-xpaiv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir akşam vakti geldin aklıma

Düşünürüm sevgilim sen olmasanda

Gece uyurken girdin rüyama

Görürüm sevgilim sen olmasanda

Gün boyunda aklımdan çıkmıyorsun

Çağırıyorum seni ama duymuyorsun

Bekliyorum ama sen gelmiyorsun

Gözlerim sevgilim sen gelmesende

Şimdi ankarada hava soğudu

Sen yoksun diye zaman durdu

Durağım bilmem ne oldu

Ağlarım sevgilim sen görmesende

 Mustafa Yiğit (Morpheus)', 'Bir akşam vakti geldin aklıma Düşünürüm sevgilim sen olmasanda Gece uyurken girdin rüyama Görürüm sevgilim sen olmasanda Gün boyunda aklımda...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgilim2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim3', 'sevgilim3-mustafa-yigit-morpheus-i3yey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin yanında iken

Mutlulukdan uçuyordum ben

Şimdi senden uzakdayım

Aklımdan çıkmıyorsun sen

Ellerinden tutuyordum

Hep gözlerine bakıyordum

Şimdi ise ağlıyorum

Yanımda neden yoksun sen

Gurbetel ayırdı bizi

Özlüyorum geçen günlerimizi

Unutamıyorum sevgimizi

Gözümde tütüyorsun sen

Durağım fazla düşünme

Her gün yola çıkıp bekleme

Gelmiyorum diye üzülme

Bir gün kapını çalacağım ben

 Mustafa Yiğit (Morpheus)', 'Senin yanında iken Mutlulukdan uçuyordum ben Şimdi senden uzakdayım Aklımdan çıkmıyorsun sen Ellerinden tutuyordum Hep gözlerine bakıyordum ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgilim3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim4', 'sevgilim4-mustafa-yigit-morpheus-lo2du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sil gözyaşlarını kimse görmesin

Senin ağladığını kimse bilmesin

Kilitle kalbini kimse çalmasın

Benim döneceğim güne kadar

Bağla elelrini kimse tutmasın

Kapa gözlerini kimse bakmasın

Gösterme yüzünü kimse sevmesin

Benim döneceğim güne kadar

Gezme kimselerle aptal desinler

Konuşma kimselerle yabani desinler

Görüşme kimselerle çirkin desinler

Benim döneceğim güne kadar

Yarin nerede derlerse ankarada dersin

Benim döneceğim günü beklersin

Günün birinde gelecek dersin

Benim döneceğim güne kadar

 Mustafa Yiğit (Morpheus)', 'Sil gözyaşlarını kimse görmesin Senin ağladığını kimse bilmesin Kilitle kalbini kimse çalmasın Benim döneceğim güne kadar Bağla elelrini kim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgilim4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarif Köyüm', 'zarif-koyum-mustafa-toga-a4qjt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl methedeyim seni ben köyüm

Sana kimse doymamış ben nerden doyum

Kıvrım kıvrım akar ardından suyun

Üç beş evle cennete dönmüşsün köyüm.

Uzaktan bakınca tam bir çiftliksin

Ağa yok sen de hür ve ifritsin

Ísmin Kısahasan acaba kimsin? 

Onsekizlik kız gibi güzelsin köyüm.

Anam babam hep sende yaşadı

Kumarcısı çok idi gören şaşardı

Bebeler de tozlu yolda koşardı

Cennetten bir köşe olmuşsun köyüm.

Bahçesi çoktur benim köyümün

Öğretmeni doktoruyla vardır âlimin

Çok pahalıdır toprağında dönümün

Zengin bir dul gibi naziksin köyüm.

Aşağıçiyanlı’ya bağlı küçük bir yersin

Toga’m zarif köyünü dünyalar duysun

Kısahasanlı toprağı bire bin versin

Bereketli topraklara sahipsin köyüm.

www.togamedya.tr.gg

Kısahasanlı / KADÍRLÍ

SÖZÜN ÖZÜ: 

Yerinde söz söylemesini bilen, özür dilemek zorunda kalmaz.', 'Nasıl methedeyim seni ben köyüm Sana kimse doymamış ben nerden doyum Kıvrım kıvrım akar ardından suyun Üç beş evle cennete dönmüşsün köyüm. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zarif-koyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim5', 'sevgilim5-mustafa-yigit-morpheus-02tr3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çölün ortasında çiçek gibisin

Baharda uçuşan kelebeğimsin

Yıllar geçsede yine benimsin

Kalbime işledim sökemem seni

Şelale misali gönlüme aktın

Yanardağ miseli kalbimde patladın

Aşkınla, cehennem ateşine attın

Cayır cayır yansamda bırakmam seni

Mecnun gibi yollara düşürdün

Kerem gibi yaşarken öldürdün

Yaban ellerde boynumu büktün

Uzaklarda olsanda unutmam seni

Aşkımın yüzünden zindana atsalarda

Bedenimi bin parçaya ayırsalarda

Çarmığa gerip bağlasalarda

Akan her kan damlasında ararım seni

Zindanda kalmaktan çürüse bedenim

İsmini söylemekden tutulsa dilim

Ferhat misali kül olsa bedenim

Her kül taneciğinde ararım seniİ

30 yaşında delirdi deselerde

Sevgimden ötürü hor görselerde

Her geçem günlerde umudum sönsede

Soğuk gecelerde beklerim seni

Sürgüne gönderselerde beni

Asla yok edemnezler sevgini

Ok ile parçalasalar kalbimi

Parçalanan kalplerde ararım seni

Vahşi ormanlarda yamyamlarla kalsam

Senden uzaklarda resminle avunsam

Görmesinler diye gizlice ağlasam

Akan gözyaşlarımda ararım seni

 Mustafa Yiğit (Morpheus)', 'Çölün ortasında çiçek gibisin Baharda uçuşan kelebeğimsin Yıllar geçsede yine benimsin Kalbime işledim sökemem seni Şelale misali gönlüme ak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevgilim5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İzmirsin', 'sen-i-zmirsin-nail-yavuz-43apd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEN İZMİRSİN 

beşbin yaşındaki sevgili 

hayallere sığmayan görkeminle 

daha dün girdin ergenlik çağına.. 

sen efsanelerde, 

Amazon Kraliçesi Mir''in kurduğu, 

İonyalı Tantolosun çizip karısı SİMİRNA''ya sunduğu, 

büyük şair Homerosun doğduğu, 

Victor Hugo''nun prensesi olan, 

kent değil misin? 

ihanetlerde öldürülen,

yüreğim gibi talan edilip yağmalanan kaç kez... 

şarap selinde Agora, 

saklamadı mı gülümseyişini, 

acılarının ardına.. 

yitik düşlerin yurdu, 

buz renkli sabahlardaki, 

güneşli maviliklerde, 

hep cepheden baktım sana, 

güne ağaran tutkularımla.. 

ürkek bir akşam üstü, 

denize dalar gibi, 

düşmek isterken aşka, 

eşkiya yalnızlık çöktü omuzlarıma.. 

sonbahar sarısı bu kenti sırtlayp 

derinine düştüm gecenin... 

körfezin gizemlerinde, 

bir şeyler yok olurken, 

duman karası bulutlar çöktü, 

şehrin üstüne.. 

günler boyu yasak aşklar taşındı kente, 

Hamesis''in Mabedinde damıtılan günahlar, 

Meles Çayının kirine karıştı, 

kaç sevdanın külünü savurdu Forbes Köşkü.. 

palmiyeli gecelerin gölgeleri yollardayken.. 

sağır caddelerinden geçtim tarihin... 

Şair Eşref kulak vermedi Abdülhamit''e, 

yazdı yazacaklarını... 

Belkahveden gelecek nal sesleri bekleniyor, 

Hasan Tahsin saate bakıyor, 

ilk kurşunu attı atacak.. 

yürekleri ağızlarında güvercinlerin... 

Cumhuriyet Meydanı''nda ki atlını ilk hedefi belli.. 

yangın yerini yeşile boyadın Behcet Uz, 

bu kenti kimler boğazladı? 

kim işledi bu cinayetleri? 

biliyor musun Behcet Bey kim? ! ! 

Kordon Boyunun kolyesini çalanlar, 

tarih hala cılız Meles Çayında akıyor... 

biliyorsun, 

günlerden ayrılıktı, 

saçlarının rüzgara karışan isyanıyla, 

tek başına, 

ÇEKİP GİDEN SENDİN.. 

yuttu geceler Ege''nin mavisini 

bir acı çöreklendi şehrin akşamlarına.. 

şimdi, 

hangi şehrin sabahında, 

hangi camdan bakıyorsun tan ağartılarına, 

saçlarında onca yağmurun ıslandığı serinlikte.. 

uzak şehrimdesin sen, 

seninle olmak, 

omuz omuza yürümek vardı, 

bu yorgun İzmir gecelerinde.. 

yeni sevgiler yaratamadım, 

ihanetleri bıçaklayıp, 

kendime giden bir tunel kazdım.. 

özlemleri demirledi Alsancak Limanı, 

yalnızlığın ışıkları yandı gözlerimde, 

çoğalırken karanlık köşeleri kentin, 

çaresizlik çöktü kaldırım taşlarına.. 

kök saldı tabanlarım sokaklara.. 

gecelerin tuzağına düştü..... 

sen kentlerce uzağımdasın, 

bu şehrin bir köşesinde, 

son sokak feneri oluşum, 

yaralıyor beni, 

düşüyorum ayrılıkların müzmin anaforuna.. 

şimdi İnciraltı''n da yıkanan gölgende, 

anılarımı öldürüyorum, 

ay buluta dalarken, 

denizin gözlerinden öpüp, 

üşümesin diye şehrin üstüne örtüyorum.. 

en son sen yıkmıştın giderken, 

yıkıldığım o yerdeyim hala, 

bindörtyüzsekseniki Muzaffer İzgü, 

bindörtyüzelliüç Gazi Kadınlar Sokağı''nda, 

yokluğunun günlüğünü tutuyorum... 

acaba sen bir yalan mıydın? 

gurbet düğümledi yolları, 

yanlış adreslerde duran sensin, 

kapıyı çarpıp gidecek olansa gençliğin, 

hüzzam bir fasılda, 

hicrana takılan benim, 

ellerimde kalansa bir ömür toplamı.. 

birazdan, 

körfez vapurunun küpeştesinde, 

martılar uçuşacak, 

inip kalkacaklar su birikintilerine.. 

kırık dökük masalarda mumlar yanacak, 

ve şamdanlarda eriyecek umutlarım, 

seni esecek rüzgar, 

iç çekecek Alsancak''ın mağrur evleri, 

solungaçlı yüzlerle, 

çocukluk anılarının jübilesini yapacak fahişeler.. 

az sonra 

varoşlarındaki çatısız evlerin penceresinde ışıklar solacak, 

gözyaşlarıyla yıkanıp karanlığa gömülecek.. 

dönüp arkama baktığım da, 

Konak iskelesin son vapura binerken, 

fakülte yıllarımdan kalma, 

haki renkli parkamla, 

militan günlerim gelecek aklıma.. 

yine anılarda, 

Hüseyin Yurttaş''n *saat İzmir sularında*, 

akşamcı mekanımız, 

İkinci Beyler Sokağında ki Bodrum Meyhanesi''nde, 

bakışlarımızı içerken, 

dudaklarımızda uçuşan, 

mutluluk şarkıları olacak... 

şimdi anımsıyorum, 

yağmurlarla sevişen ikindilerde, 

Mustafa İzmirli''nin, 

Pasaporttaki nargileli kahvesinde, 

oynadığımız tavlayı, 

büyülü doğan güneşli günlerde, 

dudaklarımıza avare ıslıkları yerleştirip, 

Cumhuriyet alanına sığmayan düşlerimizle.. 

Kordonboyundaki öpüşmelerimizi, 

Tayyare Sinaması kaçamaklarımızı, 

ilk buluştuğumuz Yosun Pastanesi''ni, 

yine ilk şehiriçi seyahatimizde, denize köpük köpük tüküren, 

Karşıyaka Vapurunun güvertesinde, yakamozlara ışığını, 

değdirirken yıldızlar.. şubat yağmurlarında ıslanışımızı.. 

peki sen anısıyormusun, 

Kadifekale''den ilk ışıklarını yaktığımız Karşıyaka''yı, 

Balıkçı Sığınağı''nda ki Efes Gemisinde, 

içimizde Papaz Yalısının hüznüyle, 

bir kaç saati kalmışları bırakıp, 

düşlere dalıp gitmelerimizi... 

elbette, 

yaşlanıyoruz çoğaldıkça anılar.. 

evet, 

tenha sokaklarında bu şehrin, 

sen yoksun ya, 

gölgen bile yok ya, 

bir fotoğraf gibi yırtıp atasım geliyor kenti.. 

bu kente saçların dolaşmış olabilir mi? 

boyuna yollara bakışım neden? 

sisler kuşatıyor her yanı, 

anlımdaki bozuk el yazısına siyah çelenk bırakıp, 

topuklarımda yılların birikmiş ağrıları, 

arkamdan koşturan hayallerim, 

ve beynimdeki darp izleriyle, 

BENDE TERKEDECEĞİM BU KENTİ.. 

bu kent yalnızlığım kadar büyük değil.. 

biliyorum, 

bu koca şehirde her şey var, 

bir biz yokuz, 

ne kalır ki geriye, 

fotoğraflar ve anılarla sokaklarda asılı gülüşlerimiz dışında.. 

bir gün değişecek, 

gözlerimizde topladığımız yağmur bulutlarıyla, 

buluşacağız bu şehrin ortasında, 

biliyorsun, 

hiç bir acı sürmez sonsuza dek... 

şimdi, 

yaralı şehrimin, 

kül grisi sokaklarında, 

yorgun bir adamla birlikte, 

yalnızlığın adımları dolaşıyor, 

buza yazılan düşler üşürken, 

Sahil Evleri''ndeki salaş meyhane, 

bir kanunun mızrabında ağlayacak, 

hiç bir dalgakıran direnemiyecek isyanıma, 

yıkacak bütün bentlerini, 

yüreklerimiz aynı saate kurulduğunda, 

gurbetten firar edip, 

İKİMİZDE DÖNECEĞİZ BU KENTE.. 

geç kalmışlığın acısını paylaşacağız.. 

düşlere sığmayan, 

düş bozumlarında... 

ZATEN BİZ YOKTUK 

KİMSESİZDİ İZMİR 

EVET 

İZMİR''İ YAZDIM YANINDA SENİ 

SENİ YAZDIM BÜYÜK HARFLERLE 

İZMİR''İ YAZDIM ALTI ÇİZİLİ 

SENİNLE İZMİRİZ 

NE ZAMAN İZMİR''İ DÜŞÜNSEM 

İÇİNDEN SEN ÇIKIYORSUN 

İZMİR İÇİN NE YAZSAM 

SENİ YAZIYORUM 

S E N İ Z M İ R S İ N 

NAİL YAVUZ 

Sen İzmirsin adlı şiir kitabımdan...............', 'SEN İZMİRSİN  beşbin yaşındaki sevgili  hayallere sığmayan görkeminle  daha dün girdin ergenlik çağına..  sen efsanelerde,  Amazon Kraliçesi...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":196,"source_url":"https://www.antoloji.com/sen-izmirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Anadoluyum', 'ben-anadoluyum-tuncer-tas-yfc6y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben anadoluyum

bağrımda sevdalar saklarım

leyla gibi gece kerem gibi yanık

ferhat olur yüreğimi dağ beller delerim

mecnun olur su diye serabını içerim

yunus olur sevdam benden içeri derim

ben anadoluyum

sen benim hızır paşam

pir sultan olur Sivas’ta

yüreğime başkaldırır

her gece dar ağacına geçerim

karacaoğlan olur sazım niyetine sevdamı sırtlar

bu şehri terk ederim

ben anadoluyum

sen benim zeusum venüsüm aresim erosum

sen benim gerçek tanrım

eğer gelmezsen

anadolu yüreğim de

sana da bir yer seçerim

ben anadoluyum

nice efsaneler saklıdır bağrımda

senden bile geçerim

ama sen yine de gel

yoksa sokrates olur yüzüğümde ki zehiri içerim

25 Mayıs 04', 'ben anadoluyum bağrımda sevdalar saklarım leyla gibi gece kerem gibi yanık ferhat olur yüreğimi dağ beller delerim mecnun olur su diye serab...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Taş']::text[], 8.5, '{"poet":"Tuncer Taş","poet_slug":"tuncer-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-anadoluyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abartıyormuyum yoksa?', 'abartiyormuyum-yoksa-sair-abban-66fjv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akif''le ŞEHİT leri kıskanıyorum

Niye bilirmisiniz? 

Yedi kollu süreyyayı istiyorum

Bana verebilirmisiniz? 

Fazıl''a söylemeyin kaldırımlarla ilişkimi

Söylemeyin yarime onlarla seviştiğimi

Akif benim, Fazıl benim herkesin inadına

Sığınayım bırakın gölgenizin altına

Ve bir akşam rüyama girin..mest olayım

O girift bilmecenin cevabını bulayım

''Nedir? '' diye sorarsan Üstazım bana sorun

Kurumuş, akmayan Sakarya''ya bakıyorum

Sen demiştin Fazıl Bey, Sakarya ters akıyor diye

Geçemedik önünü Sakarya kurudu işte.

Şehitleri sen saydın destanı sen yazdın Akif

Bilmiyor torunları (BA)   nedir,? Nedir (ELİF) ? 

Söyleyecek çok şey var yetişmiyor lugatım

Affedin şu fakiri sizsiniz lugatşahım', 'Akif''le ŞEHİT leri kıskanıyorum Niye bilirmisiniz?  Yedi kollu süreyyayı istiyorum Bana verebilirmisiniz?  Fazıl''a söylemeyin kaldırımlarla ...', ARRAY['Türk Edebiyatı','Şiir','Şair Abban']::text[], 8.5, '{"poet":"Şair Abban","poet_slug":"sair-abban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/abartiyormuyum-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baltık Mit''inden Eski Bir Tanrıya Ağıt', 'baltik-mit-inden-eski-bir-tanriya-agit-ahmet-ferit-cosan-285px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçerilerinde gizliden gizliye semirttiğin o sır,

Aziz olsun can bilinen gözyaşları,

Saydam camlara iğnelenmiş kelebekler misal.

Gurur ki meziyettir ecdadın her vesile kulaklara fısıldadığı,

Vakur şekilde tecelli etti davranışının orta yerindeki pırlanta aynada.

Çileler kokan ünlemlerle ayağa kaldırmak isterdim cümlealemi canyoldaşım,

haber eylemek için bulutlu bir gökyüzü misal kuzeylere yittiğini.

Yavanlıktan muzdarip olmuş, garipsediğim dilimlenmiş onca sönük ruhcağızlara,

Dinletmek isterdim kuytularda mırıldandığın hasret türkülerini.

Sadece sevdin oysa,

yalnız sevdin, kimseciklersiz yalnız sevdin.

Ve ulu dağların doruklarını sunakları eylemiş şaman cadılar gibi,

hunharca bıçakladılar kalbini,

oluk oluk şiir akarak çıkarttığın kalbini kaptırdığın çehreleri güzeller.

Ve inan bana kardeşim gözlerimin derinlerine bakarak,

meğer ki Kremlin''in sivri şapellerini ellerine geçirebilseler,

Bu Allahsızlar onlarla dahi deşerlerdi yüreğini.

Soban bir yüz oldu, yanan ellerinse ruhun belki,

güneşlerin söndü sandın nice sabahlarında, tüm ötücülerin kırıldı,

Yağmurların hiç susmadı, temize dair ne varsa taşırken

Ve tam da bu demlerinde işte

“Boşver be! ”

diyen bir dost bile silüeti ile ferahlatamadı loş hayatını.

Vakittir işte serivermek için sana ait olupta

hayatımda paslanmaya bırakıp, teslim etmeye kıyamadığım onca anıları, hayalleri.

Al senin olanlar senin olsun yeniden, sen ki dikenli çelmelere takılmış çokça

Azametli bir dağ gibi karşımda sabırla dikilirken.

Özürlerim ovaları örtecek kadar çok ve yavandır,

Gözyaşı şarabımdan içmeden geçmez tıkanmış boğazlarından.

Bil ki kardeşim bu biçare günah çıkarma teşebbüsüm,

Bir nebze seni bunca üzenler, hep seni itenler adınadır.

15 Ocak/11.00 pm

2004 /Gebze

Valhalla''daki tüm emeklilere selam olsun...', 'İçerilerinde gizliden gizliye semirttiğin o sır, Aziz olsun can bilinen gözyaşları, Saydam camlara iğnelenmiş kelebekler misal. Gurur ki mez...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/baltik-mit-inden-eski-bir-tanriya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizma...', 'aforizma-ahmet-ferit-cosan-irjj6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Paris sokaklarında 

Dolaşmadım şimdiye dek.

Hayallerim dışında.

Fakat, küçümsemeyin hayalleri.

Ne de olsa, bu izbe hayatta

Ayakta tutan bizleri,

Gerçeklerimizden çok

Hayallerimiz değil mi?', 'Paris sokaklarında  Dolaşmadım şimdiye dek. Hayallerim dışında. Fakat, küçümsemeyin hayalleri. Ne de olsa, bu izbe hayatta Ayakta tutan bizl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aforizma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatmak ve Anlamak...', 'anlatmak-ve-anlamak-i-brahim-ethem-bingul-4kmng', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bülbüller ötecek

Bekliyorum

Bu viranede...

Gönül şenlenecek

İçiyorum

Su gibi mey

Bu meyhanede...

Karanlık bitecek

Biliyorum

Gökyüzü

Yıldızlarını üstüme dökecek

Şu gök kübbede

Mahsun kalbim de gülecek

İstiyorum

Yâr gelmeli

Güldürmeli

Şenlik olmalı kalbimde...

-

-

Bülbüller ötüyor

Duyuyorum...

Gönül sarhoş olmuş

Fark ediyorum...

Ay ve yıldızları

Seyrediyorum...

Hüznümü istiyorlar

Vermiyorum...

Onsuz olamam

Çünkü Yâr hep onunla

Anlatabiliyor muyum? ...

www.iebingul.com', 'Bülbüller ötecek Bekliyorum Bu viranede... Gönül şenlenecek İçiyorum Su gibi mey Bu meyhanede... Karanlık bitecek Biliyorum Gökyüzü Yıldızla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/anlatmak-ve-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-hifzi-ozbekmez-xrae3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbet ellerinden bir haber geldi

Dediler ki yarin bekliyor seni

Çektiği hasretin Bağrını deldi

Ciğerinde köze ekliyor seni

Gözündeki yaşlar durmadan akmış

Geleceksin diye yollara bakmış

Senden başkacada seveni yokmuş

Aklına fikrine yüklüyor seni

Yüreği burkulmuş yaşlı gözleri

Hıçkırığa dönmüş lafı sözleri

Allahım kavuştur diyor bizleri

Sinende gül gibi saklıyor seni

Bu aşkın eşi yok koca fezada

Bir yönü olsa da cefa ezada

Latif yargılansa ağır cezada

Suçsuzdur diyerek aklıyor seni

9 Ağustos 2004 saat:16:00', 'Gurbet ellerinden bir haber geldi Dediler ki yarin bekliyor seni Çektiği hasretin Bağrını deldi Ciğerinde köze ekliyor seni Gözündeki yaşlar...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımın bitiği yerde...', 'aklimin-bitigi-yerde-emirhan-bala-vfbsp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kıl payı zamanlar içimde kalan, 

akordunu yapamadığım acılarımı 

____________________gömdüm... 

çizik çizik tırnak izlerinde kalan, 

saramadığım yaralarımı 

____________________sardım... 

kısık bağırtılarımın arasında kalan, 

sevda nağmelerimi 

____________________çaldım... 

buğulu gözlerin hapsinde kalan, 

kançanağı göz yaşlarımı 

____________________boğdum... 

saklının gizem kokan sonsuzluğunu, 

aklımın bittiği yerde 

____________________buldum...', 'kıl payı zamanlar içimde kalan,  akordunu yapamadığım acılarımı  ____________________gömdüm...  çizik çizik tırnak izlerinde kalan,  saramad...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aklimin-bitigi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak İstanbul', 'uzak-i-stanbul-nurettin-ozdemir-nbzjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu maviyi biliyorum, Boğaz''dan,

Ne güzel yakışmış gözlerinize.

''Mirgün'' çınarlarından bu yeşil,

Öylesine kanat germiş denize.

Belki temmuz sıcağıdır bu sarı,

Tutuşmuş yamaçlarında Küçüksu''yun.

Belki de uçuşan ekim yaprakları,

Altın rüzgarında bir uykunun.

Bu ışık, tuğrasındaydı Fatih''in,

Şimdi bakışlarını aydınlatan.

Bu rüzgar hep eserdi Çamlıca''da,

Bize gençlik günlerimizi hatırlatan.

Her halin bir semtin güzelliğidir.

Bu bakış, bu göğüs, bu dudak, bu el...

Bu, içimde büyüyen özlemindir,

İstanbul gibisin, uzak ve güzel.', 'Bu maviyi biliyorum, Boğaz''dan, Ne güzel yakışmış gözlerinize. ''Mirgün'' çınarlarından bu yeşil, Öylesine kanat germiş denize. Belki temmuz s...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzak-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Akşamı', 'bir-yaz-aksami-murat-demir-9w63o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine bir yaz akşamında

Kurulu masamın başucuna kurulmuş

Yine sensiz, yine gözlerim yollar da,

Demlenirim.

Evimin balkonunda,

Güneşe bakarken  kızıllığının gölgesinde

Çırpınışını seyrederek,

Sanki; sıkıntısı var benim gibi,

Giderse gelmeyecek...', 'Yine bir yaz akşamında Kurulu masamın başucuna kurulmuş Yine sensiz, yine gözlerim yollar da, Demlenirim. Evimin balkonunda, Güneşe bakarken...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yaz-aksami-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-yasin-kandemir-inua4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz sessiz,yürür giderim

Ben dumansız vapur,yağmursuz sonbahar,

Sırtında heybesi gamsız dervişim,

Alır başımı çeker giderim......

Ben rüzgar olurum,sen deniz,

Alırım sakinliğini,bozar giderim.....

Savrulur dalgaların,kumsalı döverek,

Martıların boğulur,can çekişerek......

Ben en amansız dalga,sen en sarp kaya,

Alırım heybetini,yıkar giderim......

Kum gibi dağılırsın,düşersin avuçlarıma,

Küllerini enginliğe salar giderim......

Ben yıldırım olurum,sen orman,

Öfkemle düşerim en derin yamacına,

Tutuşursun yanarsın alev alev

Kıvılcımlar salınır bağrına

Alevinle yanar giderim...........

Not:Bu şiir sevgili dostum Muhammet Akman tarafından üzerinde değişiklik yapmak ve daha geniş kitlelere ulaştırmak üzere yayınlamak için bana verilmişti.Şimdi kendisi de Antoloji ailesine katılıyor.Umarım hakettiği ilgiyi görür.', 'Sessiz sessiz,yürür giderim Ben dumansız vapur,yağmursuz sonbahar, Sırtında heybesi gamsız dervişim, Alır başımı çeker giderim...... Ben rüz...', ARRAY['Türk Edebiyatı','Şiir','Yasin Kandemir']::text[], 8.5, '{"poet":"Yasin Kandemir","poet_slug":"yasin-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/giderim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 6', 'rubai-6-emirhan-bala-mihte', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaşamak varken canan''ı canda..

ısıtmaksa yüreklerimi koynumuzda,

boşuna yoketmek sevda tılsımını, 

ölmeden saklı zamanda...', 'yaşamak varken canan''ı canda.. ısıtmaksa yüreklerimi koynumuzda, boşuna yoketmek sevda tılsımını,  ölmeden saklı zamanda......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-6-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim6', 'sevgilim6-mustafa-yigit-morpheus-doakn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatırlarmısın sevgilim tanışmamızı

Bir bahar günüydü, kuşlar öterken

Piknik yaparken karşılaşmıştık

Dereler şırıl şırıl akıyordu

Ağaçlar sanki bizim için açıyordu

O anda anlamamıştım duygularımı

Geçici bir heves sanmıştım

Güzelliğin karşısında şaşırmış

Ne yapacağımı unutmuştum

Benim halime bakıp, alay ederek

Aptal demiştin bana

Şimdi düşünüyorumda 

Hak veriyorum sana

O anda ben gerçekten aptallaşmıştım

Hatırlarmısın sevgilim

İlk çıktığımız günü

Sanki her yer toz pembeydi

Seninle konuşmak için yanına gelirken

O kadar çok heyecanlanmıştım  ki

Ellerim titreyerek yanına gelmiştim

Ama bir türlü seninle konuşamayıp

Bir kez daha aptal durumuna düşmüştüm

Günler geçtikce biz arkadaş olmuştuk

Ne kadarda mutluyduk beraber iken

Birbirimizi görmeden duramıyorduk

Ve sevgilim inan bana 

Sevginle ben aptallaşıyordum

Ve sevgilim hatırlarmısın

O kahrolası ayrıldığımız günü

Hava karanlıktı, hemde zifiri karanlık

El ele geziyorduk o kimsesiz parkta

Birden sen ayrılalım demiştin

Nedenini bilmiyorum

Ama dünyam kararmıştı

O günden sonra, sanki yaşayan ölü gibiyim

Yıllardır karanlıklarda inan bana

Hep seni bekliyorum

Aydınlık dünyamı kararttığın gibi

Karanlık dünyamı sevgilim

Aydınlatmanı istiyorum

 Mustafa Yiğit (Morpheus)', 'Hatırlarmısın sevgilim tanışmamızı Bir bahar günüydü, kuşlar öterken Piknik yaparken karşılaşmıştık Dereler şırıl şırıl akıyordu Ağaçlar san...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sevgilim6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim7', 'sevgilim7-mustafa-yigit-morpheus-rnwr5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığın en derin noktasında

Herkes yatmış aşk uykusuna

Sevenlerin rüyasında

Mutlulukların kucağında

Hıçkırıklarla uyanan

Sabahın erken saatlerinde

Uykusuzluğuna yanan

Sevdasına ağlayan

Perişan haline bakmayıp

Aşkına, sevdiğine, kelebeğine

Canında can bildiğine

Sevdasını 

Gözyaşları ile yollayan

Nice aşıklar

Vardır bilirmisin

Sana bu satırları 

Sabahın erken saatlerinde

Yazıyorum

Tüm sevenlere

Armağan ediyorum

Sevdalarını ölümüne yaşayanlar

Kendinden bir şeyler bulanlar

Benim aşkımıda 

Bilsinler istiyorum

Gözlerimde tomurcuklar birikti

Resmine baktıkca hüzünleniyorum

Ağlıyorum; 

Ama gözyaşlarımda sen varsın

Kaybetmek istemiyorum, tutamıyorum

Birer birer düşüyor

Yorganlarıma

Sana yanıyorum

Aşkına susuyorum

Rüyalar bile artık düşman oldu 

Mutluluğu çok görüyorlar bana

En güzel rüyam seni gelinlik içerisinde görmek

Ama

Hayır istemiyorum

Yanımda sen yoksun

Kollarım yine boşluğu sarıyor

Hayalin karşımda gülümsüyor

Evet diyorsun evleniyorum

Kendimi tutamıyorum

Benim değilsin artık

Ne kötü

Oysa

Ne hayaller kurmuştum ben seninle

Başkasının olmak varmıydı

Böyle habersizce

Evlenmişsin rüyalarda görüyorum

Ve sana

Kavuşamadığım yıllara yanıyorum

Ben böyle aşkından kavrulsamda

Sana mutluluklar 

Diliyorum.

 Mustafa Yiğit (Morpheus)', 'Karanlığın en derin noktasında Herkes yatmış aşk uykusuna Sevenlerin rüyasında Mutlulukların kucağında Hıçkırıklarla uyanan Sabahın erken sa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sevgilim7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminler Ettiğimiz', 'yeminler-ettigimiz-cafer-tayyar-ozkan-y5trq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zoruna mı gitti, kızınca söylediğim,

Kim bilir, neler düşünürsün şimdi.

Sen gelir misin acep sevdiceğim? 

Yeminler içtiğimiz yere şimdi...

Boşuna mı tuttum, yıllarca özlemini,

Kim bilir, kimin koynundasın şimdi.

Sen çeker misin acep matemini? 

Yeminler ettiğimiz yerde şimdi...

13 Temmuz 2003 Ankara', 'Zoruna mı gitti, kızınca söylediğim, Kim bilir, neler düşünürsün şimdi. Sen gelir misin acep sevdiceğim?  Yeminler içtiğimiz yere şimdi... B...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeminler-ettigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarlar Yıkarlar ve Çıkarlar', 'yakarlar-yikarlar-ve-cikarlar-muammer-celik-shglj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'utanmazlıklarıdır en büyük zırhları 

utanmazlıktan birbirlerini de kırarlar 

her işin içinden bir bahane ile çıkarlar… 

o ”çıkarlar” değil mi işte, 

uğruna yeri göğü yakarlar! ... 

içinde kadınlar 

erkekler

çocuklar

yaşlılar …

içinde tüm İNSANLAR ve CANLILAR... 

utanmıyorum 

utanmayacağım 

onların yanlışından

vuracağım yüzlerine hatasını... 

İĞRENECEĞİM  SADECE

ve 

KUSACAĞIM ÜSTLERİNE

MİDEMİN EKŞİYEN SANCISINI! ...

BirDeli

06.08.2004', 'utanmazlıklarıdır en büyük zırhları  utanmazlıktan birbirlerini de kırarlar  her işin içinden bir bahane ile çıkarlar…  o ”çıkarlar” değil m...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakarlar-yikarlar-ve-cikarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-i-hsan-dinibutun-u34q1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben her akşam

Bu kahrolası şarabı içiyorsam

Taa ciğerime çekiyorsam zehrini dumanın

Ve...

Vuruyorsam kırılasıca başımı duvarlara

Kahrolası resmini yapamıyorsam eğer

Söyliyemiyorsam o hüzzam şarkıları

Uzun hava çekemiyorsam ağlayarak

Kırılsın elim,

Tutulsun dilim,

Tükensin nefesim....

S O N......', 'Ben her akşam Bu kahrolası şarabı içiyorsam Taa ciğerime çekiyorsam zehrini dumanın Ve... Vuruyorsam kırılasıca başımı duvarlara Kahrolası r...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-i-hsan-dinibutun-59sjg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ve ben

Ellerimiz ve gözlerimiz

Her şeyimiz, hayallerimiz

Gitti, güvertesinde bir geminin

İçinde değiliz yazık

Kor her yanımız

İlk değil bu yangınımız

Nede son olacak biliyoruz

Ahh kahpe felek ahhh! ..

Lime lime doğradın ikimizi

Ateşlere attın

Yanıyoruz

Ne Aşkımız kaldı, ne sevdamız

Aldık başımızı gidiyoruz...', 'Sen ve ben Ellerimiz ve gözlerimiz Her şeyimiz, hayallerimiz Gitti, güvertesinde bir geminin İçinde değiliz yazık Kor her yanımız İlk değil ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ve-ben-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme, Kal', 'gitme-kal-nurettin-ozdemir-ah48z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgar dalları eğsin, sen eğilme sakın.

Hüzün nedir, ayrılık ne, sen bilme sakın.

Ey sevgili, bu gönül bahçelerinden

Kimler giderse gitsin, sen gitme sakın.', 'Rüzgar dalları eğsin, sen eğilme sakın. Hüzün nedir, ayrılık ne, sen bilme sakın. Ey sevgili, bu gönül bahçelerinden Kimler giderse gitsin, ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gitme-kal-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Hülyaları', 'yalnizlik-hulyalari-nurettin-ozdemir-t1nz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Sen çocuktun ve o şehir küçüktü.

Vişne dallarında arzularımız,

Alnımıza konan bir öpücüktü.

Rüyasını bile göremediğim

Bahçelerin yıkık duvarlarından

Eğildiğin sular, köpük köpüktü.

II

Bilmem böyle mahzun düşündüğüm ne? 

Gurbet akşamları kirpiklerime

Bulutlar dokunup geçiyor gibi.

O zümrüt masalı unutmuşum ben.

Gözlerinin garip güzelliğinden

Sular çalıvermiş güzelliğini.

III

Bu tenha yolların beklediği kim? 

Bir şeyler getirir gibi her mevsim

Unuttuğum şehrin bahçelerinden.

Elbet hatırlarsın garipliğimi

Sesimi duyarsan bir akşamüstü

Yetim İstanbul''un kubbelerinden.

IV

Çiçekler söylüyor son şarkımızı.

Arzular vişneler kadar kırmızı,

Umutlar dalların yeşilliğinde.

Seslerden, renklerden ve kokulardan,

Bir dönüş gibisin eski yollardan

Sonbaharın altın serinliğinde.', 'I Sen çocuktun ve o şehir küçüktü. Vişne dallarında arzularımız, Alnımıza konan bir öpücüktü. Rüyasını bile göremediğim Bahçelerin yıkık duv...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizlik-hulyalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram', 'sigaram-mustafa-yigit-morpheus-ovoeh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dert ortağım sigaram

Sensiz geçen gecelerde

Hep seni arıyorum

Yazdığım tüm hecelerde

Yokluğun kabus gibiİ

Çadır kurdu yüreğime

Şimdi ise yanıyorum

Sensiz geçen senelere

Güneş ilk defa doğdu

Hüzün dolu gönlüme

Telefonum çalmaz oldu

Sensiz olduğum günlerde

Günler geçermi bilmem

Sensiz olduğum saatlerde

Kalemim yazmaz oldu

Senin olmadığın yerde

Hayat zindan artık bana

Sen yoksan hayatımda

Saatler acımaz oldu

Aşkınla yanan morpheusa

 Mustafa Yiğit (Morpheus)', 'Dert ortağım sigaram Sensiz geçen gecelerde Hep seni arıyorum Yazdığım tüm hecelerde Yokluğun kabus gibiİ Çadır kurdu yüreğime Şimdi ise yan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sigaram-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden bu kadar', 'benden-bu-kadar-omer-aydin-qdckn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygularımı zincire vurdum,daha fazla ağlatmasın diye

Kilit astım kapılarına gönlümün,kimseler girmesin diye

Anılarımı,ta baştan sildim geçmişi yaşatmasınlar diye

Şu bitkin bedenimi emanetçiye bıraktım,beni taşımaktan yorulmasın diye

Yoruldu bacaklarım,boş hayaller peşinde koşmaktan,gidemiyorum

Gözlerim yoruldu,gerçek sevgiyi aramaktan,artık göremiyorum

Gönlüm kırık,kalbim yaralı,gücüm yetmedi saramıyorum

O kadar uzaktayım''ki sevdiklerimden,istesemde kavuşamıyorum

Sevdiğim kadar sevildiğimede inanmak hakkımdır sandım

Sevdiklerime mutluluğu yaşatayım derken,bende unutdum

Sahip olmak için her şeyimi verdim,yinede yenildim

Mutluluk hakkım değilmiş,geçde olsa bunu anladım', 'Duygularımı zincire vurdum,daha fazla ağlatmasın diye Kilit astım kapılarına gönlümün,kimseler girmesin diye Anılarımı,ta baştan sildim geçm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aydın']::text[], 8.5, '{"poet":"Ömer Aydın","poet_slug":"omer-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benden-bu-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sabahı', 'i-stanbul-sabahi-nurettin-ozdemir-gz4kl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu aydınlık, bakışlarının güneşe vurmasıdır.

Bunlar saç değil, sarı güllerin savrulmasıdır.

Ne bahar, ne sonsuz mavilik, zamanı güzel kılan,

Kalbimin ansızın gözlerine vurulmasıdır.

Garip telaş.. uçarı gönül.. hülyalı saatler.. hepsi boş! 

Özlenen, bir sualin bir bakışta sorulmasıdır.

Bu, fırtınadan arta kalmış beyaz köpükler,

içimdeki çılgın denizlerin durulmasıdır.

Asıl çekilmez olan hayatın yükü değil,

İnsanın bir amansız koşuda yorulmasıdır.', 'Bu aydınlık, bakışlarının güneşe vurmasıdır. Bunlar saç değil, sarı güllerin savrulmasıdır. Ne bahar, ne sonsuz mavilik, zamanı güzel kılan,...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-mustafa-yigit-morpheus-zfjhx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu meyhane köşelerinde

Düşüne, düşüne bu hale geldim

Durmadan yaktığım sigara ateşine

Baka baka bu hale geldim

Havaya baktım hava sisli

Yola baktım yol engebeli

Yare baktım oda çok nazlı

Çeke çeke bu hale geldim

Hava sisli, yol ise uzun

Sıcakta durduğunu gördünmü buzun

Sevdasını eller alırmış mutsuzun

Ağlaya ağlaya bu hale geldim

Şans yıldızım bir gün olsun doğmadı

Kader bir gün olsun yüzüme hiç gülmedi

Kaçan mutluluklar geri gelmedi

Kovalaya kovalaya bu hale geldim

 Mustafa Yiğit (Morpheus)', 'Şu meyhane köşelerinde Düşüne, düşüne bu hale geldim Durmadan yaktığım sigara ateşine Baka baka bu hale geldim Havaya baktım hava sisli Yola...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sitem-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-erdal-sayil-dbwi2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstemiyorum, ne seni; 

Ne düşünmek hayalini...

Resminle beraber yanık; 

Cismini de unutuyorum artık...

Ses yok, nefes yok senden,

Demek herşeyiyle gidiyor giden; 

Gönül sıkılıyor istenmeyenden...

Bir sevginin böyle kopuyor bağı; 

Seven ayrılıyor sevgilisinden...

Sözlerimi de yutuyorum artık; 

Bir daha söyleyeyim eski sevdigim; 

Müjde seni unutuyorum artık...', 'İstemiyorum, ne seni;  Ne düşünmek hayalini... Resminle beraber yanık;  Cismini de unutuyorum artık... Ses yok, nefes yok senden, Demek herş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmak-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Oyunu', 'hayat-oyunu-i-hsan-dinibutun-iy6p7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I. Perde

Üç perdelik bir oyundur hayat

İlk perdesi doğum...

Deli gençlik yılları

II. Perde

Aşk, çile, keder! ..

Hepsi ikinci perdede var

Ahh ikinci perde! ..

Kolay oyun oynanır

Bu perdede maskeler takılır

Sahte yüzler, sahte gülüşler

İkinci perdede yaşanır

Sevdaları tatlıdır haa,

Gerçek sevda gibidir

Yalan dolan aşklar boldur

Gözyaşı katarsın bir kaç damla o kadar! .

Al sana bir ''Peri masalı''

Beyaz atlı prensler

Çiçekten taçlı prensesler

Bu perdede birbirini bekler

Şarkılar söylenir, yollar gözlenir

Aşk üstüne...

III. Perde

Son''u Bekleyenler

Üçüncü perde sondur

Son hayaller yaşanır

Maskeler yoktur artık

Sahte yüzler, sahte gülüşler 

Bu perdede sökmez

Sevdalar gerçektir

Aşk''lar olgun

Ne beyaz atlı prensler vardır artık

Ne de çiçekten taçlı prensesler

Yol yerine toprak gözlenir

İlahiler söylenir şarkı yerine

Bir telaş içindedir gönül

Vuslatı bekler

Yalanın yerini gerçek alır

Bir parça bez, bir avuç toprak

Oyunun sonu bu perdede yaşanır

Biraz sonra perde kapanır

Artık açılmayacak! ...', 'I. Perde Üç perdelik bir oyundur hayat İlk perdesi doğum... Deli gençlik yılları II. Perde Aşk, çile, keder! .. Hepsi ikinci perdede var Ahh...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hayat-oyunu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melodiler Farklı', 'melodiler-farkli-talip-kaplan-gussw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadar basit yaşıyoruz hayatı

Senaryo aynı, roller başka başka

Yine o köhne, yıkık hamam

Kirlenmiş, kırık bir tas

Hep yüzeysel geçiliyor derinler

Kaymağını alıp sütü dökercesine

Görünenler tekrarlanıyor yaşayarak

Bilinenler aranmıyor düşüncelerde

Film aynı, görüntüler değişik

Bardakta ya da tasta, ikisi de su

Bisiklete motor takmışlar

Taksi almış, faytonun yerini

Firenlenmiş, yerinde sayılmış

Sazımız yine yedi telli

Üzerleri işlenmiş, notalar aynı

Yine saz sesi, melodiler farklı

Tekerrürden ibaret yaşantılar

Aynı görüntünün farklı renkleri

Arayış değil bu düşünceler

Ondan bundan kopya, özenti...

(27 Ocak 1994)', 'Ne kadar basit yaşıyoruz hayatı Senaryo aynı, roller başka başka Yine o köhne, yıkık hamam Kirlenmiş, kırık bir tas Hep yüzeysel geçiliyor d...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/melodiler-farkli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Elveda', 'son-elveda-mustafa-yigit-morpheus-6y24v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni bırakıp uzaklara gitme sakın

Yaban ellerde boynumu bükme sakın

Bir çiçek gibi dalımdan koparma sakın

Hadi söz ver, bu son elveda olsun

Gözlerin başka gözlere bakmasın

Ellerin yabancı elleri tutmasın

Sonsuz aşkın beni ağlatmasın

Hadi söz ver, bu son elveda olsun

Sevginden beni mahrum etmeyesin

Tüm güzelliğinle yabancı gönüle girmeyesin

Başka erkeklere gönül vermeyesin

Hadi söz ver, bu son elveda olsun

Uzaklarda olsamda sakın unutmayasın

Bir kağıt gibi yırtıp atmayasın

Sözlerinle beni aldatmayasın

Hadi söz ver, bu son elveda olsun

 Mustafa Yiğit (Morpheus)', 'Beni bırakıp uzaklara gitme sakın Yaban ellerde boynumu bükme sakın Bir çiçek gibi dalımdan koparma sakın Hadi söz ver, bu son elveda olsun ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-elveda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonradan unutmak daha zor...', 'sonradan-unutmak-daha-zor-vedat-ezer-qeu2g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ı

Sonradan unutmak daha zor...

ilk acıyla birlikte o boğuşma,o keşmekeş anında unutursan,büyük iş

sonrası yok deme,

sonrası daha acı...

II

bir aşk daha kendi cinayetini tasarlıyor,

henüz ilk dönemeçte...

....

ve ben,

güzel bir Paris akşamı gibi girdiğim o şehirden,

yıkık bir Bağdat gibi acıyla ayrılıyorum şimdi...

ııı

kaç kez kanadın kendine açık kalp ameliyatlarında

kaçını unuttun? 

kimdi mabedine usulca girip

aşk bulaştıran,seviştiğimiz yatağı sıcak tutan kimdi?', 'ı Sonradan unutmak daha zor... ilk acıyla birlikte o boğuşma,o keşmekeş anında unutursan,büyük iş sonrası yok deme, sonrası daha acı... II b...', ARRAY['Türk Edebiyatı','Şiir','Vedat Ezer']::text[], 8.5, '{"poet":"Vedat Ezer","poet_slug":"vedat-ezer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonradan-unutmak-daha-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Belki.../..Yeniden..', 'bir-gun-belki-yeniden-hasan-basri-kale-5l8do', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç ümidim yok ama; 

geçerse 

beni bitirmeden zaman

ve biterse

sensiz günler

kimbilir 

belki o ân

gözlerin gözlerimde

kayboluverir de 

dayanılmaz acımla

tekrar 

''merhaba'' 

derim sana...!', 'hiç ümidim yok ama;  geçerse  beni bitirmeden zaman ve biterse sensiz günler kimbilir  belki o ân gözlerin gözlerimde kayboluverir de  dayan...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-belki-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün yollarımız kesişirse...', 'bir-gun-yollarimiz-kesisirse-yusuf-ziya-leblebici-p4pev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün yollarımız kesişirse

gözlerimizden tanırız birbirimizi.

Unutmadım, maviydi gözlerin

denizler barınırdı içinde

dalgalar şımarır,

yakamozlar coşardı.

Huzur bulurdum gözlerinin içinde

yaşadıklarımızın aksine.

Her kovalamacanın ardından

kapına geldiğimde

gizlenirdim maviliklerine...

Tutsaklığım,

demir parmaklıklara değil sanaydı

Ürkmezdim siren seslerinden

gözlerinin içindeyken.

Ellerinden tuttuğumda

vücuduma verilmiş elektriklerin zıttına

daha farklıydı sıcaklığın...

Ayrıldığımız o gün

hem hüzün, hem de sevinç vardı bende.

Senden kopmanın acısını

benim çekeceklerimi görmemenin

sevinciyle bastırdım.

Sanki, göğsümden kurşunu

bıçakla çıkarır gibi

koparttım seni içimden...

Bir gün yollarımız kesişirse

gözlerimizden tanırız birbirimizi.

Bana baktığında kısardın gözlerini

sanki mavilikleri kıskanırcasına.

Derinliklerine çağırırdın beni

kumsallardan süzülüp de sana karışırcasına.

Tenine girerdim,

ter olup göğsünden akarcasına...

Yıllar geçti aradan,

yeşil parkam yok artık.

Bıyıklarım kesik, saçlarımda aklık.

O senin tanıdığın delikanlının zıttına

sanki boyum da kısalmış

inan, o eski sevgilin kalmamış.

Sen de değişmişsindir mutlaka.

Saçların, boyun, kilon

yıllara ezilmiştir, geçtiğin yollara...

Ama; 

Bir gün yollarımız kesişirse

gözlerimizden tanırız birbirimizi.

Belki yine buluşuruz o mavi denizde...', 'Bir gün yollarımız kesişirse gözlerimizden tanırız birbirimizi. Unutmadım, maviydi gözlerin denizler barınırdı içinde dalgalar şımarır, yaka...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-gun-yollarimiz-kesisirse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-mustafa-yigit-morpheus-ixds7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretin bağladı kollarımı

Özlemin sardı her yanımı

Kimse okşamaz oldu saçlarımı

Beni öldürdü o son mektubun

Bilmiyorum günahım sevmekmi

Sevipte özlemini çekmekmi

Gece gündüz hep düşünmekmi

Beni kahretti o son mektubun

Sana kavuşacağım günü bekliyordum

Senden uzakta özlemini çekiyordum

Resmine bakarak ağlıyordum

Beni mahvetti o son mektubun

Senden hatıra yalnızca resmin kaldı

O güzel günlerimiz mazide kaldı

Verdiğin güllerin kokusu seni hatırlattı

Yaşama sevincimi kırdı o son mektubun

 Mustafa Yiğit (Morpheus)', 'Hasretin bağladı kollarımı Özlemin sardı her yanımı Kimse okşamaz oldu saçlarımı Beni öldürdü o son mektubun Bilmiyorum günahım sevmekmi Sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-mektup-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Göç Masalı', 'bir-goc-masali-murat-tali-mspfk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rivayet odur ki 

sürgün Tunceli''de boy vermiş 

kesmişler dallarından 

savurmuşlar 

bir hasat mevsiminde 

göçmen bir kuşun kanatlarında 

düşüvermişiz 

Bingöl''ün  eteklerine 

ve olmuşuz 

Erzurum''un bir yaban gülü 

sonra 

orası da olmamış 

olamamış yuva 

yeniden hasada vermiş kendini 

bedenler 

yine bir sürgün 

yine bir göçmen kuş gidişi 

ve şehri İstanbul. 

şimdi gidecek bir yer yok 

binlerce sürgün çiçekle 

bir aradayız işte 

herkes yabancı 

herkes bir göçmen kuşun kanadında düşüverdi 

buraya 

üzerimizde biçerdöverler 

biz her gün yeniden yeniden doğuyoruz 

bir göçmen kuşa özlem devam ediyor 

halen 

kim bilir 

bir gün 

geriye döneceğiz 

bizi getiren o kuşun 

kanadında', 'Rivayet odur ki  sürgün Tunceli''de boy vermiş  kesmişler dallarından  savurmuşlar  bir hasat mevsiminde  göçmen bir kuşun kanatlarında  düşü...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-goc-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde çar mı var...', 'gozlerinde-car-mi-var-yusuf-ziya-leblebici-qfu81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlarında kar mı var

Tepesinde har mı var

Dönüp de bak dünyaya

Gözlerinde çar mı var

Yangın olmayan duman

Ateşten de çok yaman

Düşünmeden savrulan

Sözdür bizleri vuran

Yanlışını farkedip

Kızaran bir nar mı var

Seni senden kıskanıp

Anlayan bir yar mı var

İnsana insan gibi

Vereceksin değeri

Dost bildiğin yoldaşı

Seveceksin can gibi

Nur arama soysuzda

Utanmazda ar mı var

Bak sağına soluna

Sularda bir zar mı var', 'Dağlarında kar mı var Tepesinde har mı var Dönüp de bak dünyaya Gözlerinde çar mı var Yangın olmayan duman Ateşten de çok yaman Düşünmeden s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerinde-car-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin için', 'senin-icin-omer-aydin-pw9j1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıtırdım, damla damla kanımı

İsteseydin düşünmeden verirdim canımı,

Senin için silerdim en güzel anılarımı,

Ama senin gibi,kesmeye kalkmazdım dostluğun damarını

İsteseydin,ateş olur yanar kül olur savrulurdum,

Ağaç olur kurur,yaprak olur dökülürdüm,

Çamur gibi akan bir sel bile olsam,senin için durulurdum,

Ama senin gibi kesmeye kalkmazdım dostluğun damarını

Hayatı bilmeyen biri değilsinki anlatayım,

Çocuk değilsinki kucağıma alıp avutayım,

Kitap değilsinki,açıp açıp okuyayım,

Senin kadar gaddar değilimki,duyguları hiçe sayayım...', 'Akıtırdım, damla damla kanımı İsteseydin düşünmeden verirdim canımı, Senin için silerdim en güzel anılarımı, Ama senin gibi,kesmeye kalkmazd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aydın']::text[], 8.5, '{"poet":"Ömer Aydın","poet_slug":"omer-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli İçin', 'teselli-i-cin-mustafa-yigit-morpheus-st6ug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzandı kollarım sensiz boşluğa

Tut ellerimden teselli için

Hergün mektup soruyorum postacıya

Bir mektup yaz teselli için

Beni gurbetellerde habersiz bırakma

Sana gönül veren garibi fazla ağlatma

Hayalini görüyorum her gün ufukta

Bir resim gönder teselli için

Uçan her kuştan haber bekliyorum

Dünyada yalnız seni seviyorum

Seni hatırladıkca hep ağlıyorum

Bir hediye gönder teselli için

Halbim herşeyiyle sana bağlandıI

Gözlerim senden başka kimseye bakmadı

Ellerim yalnız senin saçını okşadı

Saçının telini gönder teselli için

O kara gözlerine canım feda olsun

İnşallah bir gün sende benim olursun

Dünyada mutluluğu benimle bulursun

Düğün davetiyemizi gönder teselli için

 Mustafa Yiğit (Morpheus)', 'Uzandı kollarım sensiz boşluğa Tut ellerimden teselli için Hergün mektup soruyorum postacıya Bir mektup yaz teselli için Beni gurbetellerde ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/teselli-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serenad', 'serenad-i-hsan-dinibutun-4vift', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Menekşem,

Benim çabuk küsen,

Kolay barışan çiçeğim..

Seni öyle özlüyorum ki,

Bunu, herşeyde

Sana anlatmak istiyorum.

Sen, hislerimin prensesi

Hayallerimin kraliçesi

Beni düşlerinde gör..

Hayallerinde tut,

Ama hep uzakta

Erişilmeyecek bir yerde kal

Beni hasretinle yak

Kavur yokluğunla öldür beni

Bana dokunmadan ve beni,

Öylece uçurumlara at! ..

Vücudum parçalansın

Her parçası 

Ateş gibi yakan bir cemreye dönsün

ve.. senin en bakir yerlerine düşsün

Gözlerin ok gibi yüreğimi parçalasın

ve... ben paramparça

Mabedi vücuduna saplanayım

Titre hiç durmadan

Bana dökül çağlayarak

Irmaklar gibi al beni

Tekrar kollarınla sar

Göreceksin, içimde

Sana ait bir şey var

Bir gemi çıkacak limanından

Denizlere açılacak

Sevdalar saracak dört yanını

Dökülecek Aşk damlacıkları

Her yanını yakacak

Aşk''a doymayacak Aşk tanrıları

Bu Aşk iksiri, hayat suyu diyecekler

Asırlar geçsede değişmiyecek Aşk''ın adı

Damağında kalacak içenin tadı

Menekşem,

Çabuk küsen

Kolay barışan çiçeğim

Seni öyle özlüyorumki

Bunu herşeyde sana

Anlatmak istiyorum..

Seni çok seviyorum', 'Menekşem, Benim çabuk küsen, Kolay barışan çiçeğim.. Seni öyle özlüyorum ki, Bunu, herşeyde Sana anlatmak istiyorum. Sen, hislerimin prenses...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/serenad-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam', 'turnam-mustafa-yigit-morpheus-kd2xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Turnam selam söyle ceylan gözlü yare

Beni bu diyarda sakın unutmasın

Bir selamını, bir mektubunu, resminide

Fazla bekletmesin hemen yollasın

Turnam sen bilirsin benim sevgimi

Söylede korusun o güzelliğini

Bir yüzünü, bir gözünü, teninide

Sakın ha sararıp soldurmasın

Turnam bekleme tez haber eyle

Onun aşkı ile döndüm divaneye

Selvi boyunu, güzel huyunu bir de

İnce belini sakın bozmasın

Turnam senden haber bekliyorum

İnan onu ölümüne seviyorum

Gece rüyalarımda bile görüyorum

Söyle Durağı hep hatırlasın

 Mustafa Yiğit (Morpheus)', 'Turnam selam söyle ceylan gözlü yare Beni bu diyarda sakın unutmasın Bir selamını, bir mektubunu, resminide Fazla bekletmesin hemen yollasın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/turnam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dulana', 'dulana-i-smet-barlioglu-p87nr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mahallenin en yaşlı kadınıydı Dulana,

Ödül konsa yeridir doğumunu bulana.

Derler ki; “Yaşı yüzon, belki daha da yüksek”,

Kimse bilmez gerçeği, nerden bilip söylesek.

Kendi bile bilmiyor ne zaman doğduğunu,

Kendisini Dünya ‘da ne zaman bulduğunu.

Okumuş yazmış değil, eli kalem tutmamış,

Çağında okul yokmuş, kimse de okutmamış.

Harf bilmez, hesap bilmez, çok yüzeysel bilgisi,

Başına tavan çeksen sanır ağaç gölgesi.

İlk savaşta çocukmuş, ikincisinde gelin,

Eşi şehit olunca düşmüş eline elin.

Sahipler ölüp gitmiş, bu kalmış başkasına,

Felek bunu az görüp yapışmış yakasına.

Bu kez bir karı-koca kalkıp kol-kanat germiş,

Onu ana belleyip evlad gibi severmiş.

Derken koca da ölmüş, kalmış yalnız ikisi,

Bizimki fazla yaşlı, obiri genç irisi.

Davranmış gelin gibi, sanki o da anası,

Muhtaç etmemiş ele yeri cennet olası.

Gelin eksiksiz melek, Dulana ondan melek,

Bu kız demiş kadına; “Sana Dulana diyek”.

Yaşlı ninenin adı böyle olmuş Dulana,

Bu ad yeterli olmuş arayana sorana.

Dulana bir avuçluk, tıpkı bir çocuk kadar,

Değnekten farksız kollar, cılız-mılız ayaklar.

Beden uzun yılların çilesini yüklenmiş,

Deri-meri çekilmiş, etleri tiftiklenmiş.

Görmesi hayal-mayal, diş-miş zaten arama,

Avurdu geçer olmuş giderek avurduna.

Yüz güzel değil ama sevimli mi sevimli,

Yüzündeki çizgiler ılımlı mı ılımlı.

Dünyada görülmemiş kızdığı Dulana ‘nın,

Güldükçe güller açmış üstünde yanağının.

Gırtlağından aşağı haram lokma inmemiş,

Onun lanet ettiği dünyada görülmemiş.

Sabah-akşam dualı iki solgun dudağı,

Ruhu melekler gibi, gönlü cennet şafağı.

Az verirsen az yiyor, vermezsen hiç yemiyor,

Acından ölse bile feryat-meryat etmiyor.

Herkesler mutlu sanır, çünkü o hiç sızlanmaz,

Aklından geçenleri tek bir kimse anlamaz.

Elleri efsunludur, acılara dermandır,

Dokunduğu yerlerde acı tozla dumandır.

Bu yüzden ona gelir sağı-solu ağrıyan,

Ben bunu elden duydum, gerçeği Hak ‘ka ayan.

Kur ‘an ezberindedir, okur gündüz ve gece,

Versen de okuyamaz, iş yazıya gelince.

Yazıları seçemez, seçse de okuyamaz, 

Oturduğu yerlerde kılar beş vakit namaz.

Oruçtur Ramazan ‘da, oruçtur Üç Aylar ‘da,

Diniyle, imanıyla yol almış zamanlarda.

Mahallede kim varsa Dulana büyütmüştür,

İyiliği, doğruyu herkese öğretmiştir.

Kimini avutmuştur ninnisiyle kundakta,

Kimini sallamıştır beşiklerde, hamakta.

Kimine mama vermiş, kimine dua etmiş,

Kimisini güneşte dal olup gölgelemiş.

Kimini evlendirmiş hayırlı dualarla,

Kimini sevindirmiş verdiği kınalarla.

Kimini barıştırmış, kiminden yana çıkmış,

Kimine hastalıkta candan-yürekten bakmış.

Bilir bebekliğini en yaşlı erkeklerin,

Dulana uğurudur, kısmetidir evlerin.

Bu nedenle indinde ne bey vardır ne paşa,

Unvansız hitap eder bütün kavim-kardaşa.

Ona erkekler “Oğul”, ona kadınlar “Kız” dır,

Dulana insanlara sevgi saçan yıldızdır.

Babasından kormayan çekinir Dulana ‘dan,

Çünkü yola o sokar asla azarlamadan.

Dulana yaşı ile yüreklerde bir acı,

Dul ana mahallenin her derdinin ilacı.

Söz ettiğim mahalle bir yerli mahalledir,

Mahalledeki evler köhne köhne evlerdir.

Evlerin arasında yer almaz modern bina,

Hepsi harap, eskidir, başka sıfat arama.

Çokları tek odalı ve belki de mutfaklı,

Tek bina bulamazsın iki katlı üç katlı.

Bazısında mutfak yok, çoklarında tuvalet,

“Banyo var mı? ” diyerek istersen gel sual et.

Anında söyleyeyim: banyo yoktur evlerde,

Milletin yıkandığı tek hamam var çevrede.

Eskiden kalma birşey, adı “Saray Hamamı”,

Sadece mahalleli hamamın yıkananı.

Yalnız Salı günleri bu hamam kadınlara,

Diğer günler sadece erkek girer hamama.

Erkeklerle birlikte oğlanlara serbesttir,

Zira; “Oğlan” dediğin ne de olsa erkektir.

Kadınlar yanlarında büyük oğlan sokamaz,

Beş yaşından büyüğü patron hamama almaz.

Alsa da; tüm kadınlar hor görür anasını,

Hamamın taslarıyla kırarlar kafasını.

Çünkü kadın hamamda erkek sinek istemez,

“Namahrem” dir; erinden gayrıya görünemez.

Dulana yalnız gider hamama Salı günü,

Aynen uygular durur atadan gördüğünü.

Bohçası elindedir o bükülmüş beliyle,

Sarıp sarmalamıştır başını yemeniyle.

Üstü-başı yamalı, omuzunda atkısı,

Melek gibi haliyle dünyanın en tatlısı.

“Gelin” der durur ama el kızıdır evdeki,

Çok gelmek ister ama para çıkışmaz belki.

Her ne hal, ne durumsa; gidemez Dulana ‘yla,

Elden gelse öderdi hakkını, yıkamayla.

Zaten kimse yıkamaz hamamda Dulana ‘yı,

Zira; kadın hamamı bir tür düğün alayı.

Her kadın yanı sıra götürür bir kaç kızı,

Ona sıra gelmez ki düşünsünler yalnızı.

Haksız da sayılmazlar; sular az, hamam küçük,

Hemen sular kesilir yıkansa bir kaç büyük

Sular sürekli akmaz, keserler ve açarlar,

Bir yetersiz kazanla bir mahalle yıkarlar.

Bu yüzdem Dulana da yıkanır tek başına,

Oturup bir köşeye veya göbek taşına.

Yıkanmak da ne demek, işte didinir durur,

Başına, bedenine ne lif ne sabun vurur.

Örseler o pörsümüş elleriyle canını,

İki de bir ıslatır soğuk suyla alnını.

Darlandığı çok olur kalabalık hamamda, 

kimse bakıp etmez ki; o nasıl bir külhanda.

Yürekler cız cız eder hamamdan çıkılınca,

Bu zavallı yaşlının haline bakılınca.

Ne yazık ki; iş bitmiş, el-ayak yorulmuştur,

Sanırsın ki; bu dünya bu düzen kurulmuştur.

Yükün fazlalığından kimse düşünmez eli,

Bu dünya böyle gelmiş, böyle gider demeli.

“Seni severim ama elimde imkanım yok,

Konuk ederim ama verecek mekanım yok.

Yoluna canım feda ama elim kandadır,

Yüreğim senin ama bilmem ki ne yandadır.

Sen mutlu ol, uzak ol, ancak o zaman iyi,

Ne ben seni çekeyim, ne sen düşün, çek beni.”

Manca Ali kasaptır, Kalkan Musa gardiyan,

Kara Rüstem toptancı, tahıl satar tercihan.

Losyon İbo berberdir, Mitil Cevat da bekçi,

Lazım Enver yemişçi, Torlak Rıza gömlekçi.

Tokmak Kazım davulcu, Bulut Ahmet mübaşir,

İtfaiyeci Neşet, kalaycı Sarı Beşir.

Canım Arif boş gezer, gücü var da işi yok,

Derviş Memo camcıdır, elması var, dişi yok.

Bu sevimli insanlar yaşarlar mahallede,

Toplanıp gülüşürler her gün başka köşede.

İşe giderler gündüz, kahveye geceleri,

Tümü de insanlıkta birbirinden ileri.

Bunlar bazan kuzudur, kuzudan daha kuzu,

Avucunla tuz versen; inan, yalarlar tuzu.

Yerinde efelerden daha efe olurlar,

Yerinde namus için derhal adam vururlar.

Sevgileri ateştir, değse yakar yüreği,

Öfkeleri kılıçtır, keser atar direği.

Tüm bunlar büyümüştür Dulana ‘nın elinde,

Süt dökmüş kedi olur hepsi onun önünde.

Tümünün kemiğinde Dulana ‘nın emeği,

Tümünün kursağında en çok onun yemeği.

Dulana ‘nın ninnisi tümünün kulağında,

Nicesini taşımış sırtında, kucağında.

Bu yüzdendir hepsi de Dulana ‘ya minnettar,

Dulana baş üstünde tutulacak emektar.

Ağır yükü altında tümü onun hakkının,

Her saniye ararlar çaresini bir bunun.

Amaçlar Dulana ‘ya bir hizmette bulunmak,

Bu zavallı kadından hayır dualar almak.

Dediler: “Bekleyelim, gün ola harman ola,

Elbet bir gün hizmete fırsat verir Dulana.”

Tüm evlerde erkekler kadınlarla anlaştı,

Kadınlar planlardan çok gülüştü, hoşlaştı.

Dediler: “Biz yapmadık, hiç olmazsa siz yapın,

Bir huzur yüzü görsün hiç olmazsa bu kadın.

Ne ayıp ne de günah, size namahrem değil,

Anaya hizmet etmek oğula haram değil.

O zaten et parçası, bir torba kuru kemik,

Hem dua alırsınız, hem anlatır gülerik.”

Erkeklerin planı Dulana ‘yı yıkamak,

Nineyi mutlu edip hayırlı dua almak.

Kadınlar yapamazsa yapsın bari erkekler,

İnsan yapabilenden kalkıp hizmeti bekler.

Fakat bilse Dulana; bu işe razı olmaz,

Ömrünce kirli kalsa er eliyle yıkanmaz.

Üstelik Salı günü kadınların hamamı,

Pazardan başka günler herkes geçim hamalı.

Elverişli gün Pazar, zira erkekler evde,

O gün vakit öldürür her biri bir köşede.

Dulana ‘nınsa günü oldum olası Salı,

Nasıl edip ne edip nineyi kandırmalı? 

Buldular çaresini, görev düştü geline,

O verdi bohçasını Dulana ‘nın eline.

Hamam için tas verdi, lif verdi, sabun verdi,

Keseyle tarak verdi, havluyla zıbın verdi.

Dulana güleryüzle dedi: “Gelin Salı mı? 

Ne çabuk çıkıp geldi kadınların hamamı.

Sanki aynen dün gibi geçen gittiğim hamam,

Nasıl da tükeniyor bu ömrümüz durmadan.

Günlerim şaş-beş oldu, yiyip içtiğim öyle,

Demek aklım eskimiş, günler geçerken böyle.

Hani eski topraktım? İnan ki hepsi yalan,

Ölümü bekliyorum bu dünyada durmadan.”

Kavradı bohçasını, çıktı evden dışarı,

Pusu kurmuş köşede iki yaşlı haşarı.

İlk seçtiği o oldu, gardiyan Kalkan Musa,

Yürüdü ona doğru kumlara basa basa.

Dedi ki. “Ulan oğul, bu gün günlerden nedir? 

Ben gün-mün şaşırmazdım bilmem kaçbir senedir.”

Gardiyan ciddi ciddi dedi: “Nene salıdır,

Senin bunca yaşlanman bizlerin vebalıdır.

Biz yorduk, hırpaladık seni yıllardan beri,

Nenem, bu Losyon İbo, tanıdın mı berberi? ”

Berber dedi: “He nenem, koyulmuşsun sen yola,

Belli ki gidiyorsun Salı günü hamama.

Ver nenem, hiç olmazsa bohçanı taşıyayım,

Benim güzel nenemden hayır dua alayım.”

Derken bu iki bıçkın girdiler kollarına,

Nineyi götürdüler kadınlar hamamına.

Güya ki; ayrıldılar onu içeri verip,

Gerçekte; soyundular hemen hamama girip.

Hamamcının üstünde bir naylon kombinezon,

Ne yapsın ki baldırda, bacakta kıllar uzun.

Hem de bıyıklı geldi az biraz Dulana ‘ya,

Ama gerek görmedi üzerinde durmaya.

Manca Ali giymişti bir uzunca bol fistan,

Tokmak Kazım maşlahlı, kökeni Arabistan.

Havlunun bir ucunu attığından omuza,

Romalı senatöre dönmüştü Torlak Rıza.

Ve daha da nicesi, tümü kadına dönmüş,

Yararı varmış gibi kimi de ruj sürünmüş.

Dulana görür ama gördüğü şöyle-böyle,

O az biraz benzetsin gerisini sen söyle.

Bundan yararlanarak Kara Rüstem sırıttı,

Nine inansın diye kadın gibi kırıttı.

Herbiri fıkırdadı ta öteden beriden,

O anda ince bir ses yükseldi ileriden.

Dedi: “Aman hanımlar, bu gün hamam kıvamda,

Görülmemiş bugün bu, tek çocuk yok hamamda.

Madem ki yıkanacak tek şey kendi başımız,

O halde Dulana ‘yı yıkamaktır işimiz.”

Kadınsı kahkahalar ta kubbeye yükseldi.

Soyunma yerlerinde kim varsa öne geldi.

Dulana ‘yı soydular, peştemala sardılar,

Küçük bir bebek gibi alıp kucakladılar.

Taşıdılar içeri nazıyla oynayarak,

Oturttular kurnaya başında toplanarak.

Ne türküler, şarkılar, ne kadınsı çığlıklar,

Ne yumuşak tutuşlar, ne candan yakınlıklar.

Kimisi saç tararken kimisi keseledi,

Ne bir parça incitti, ne kalkıp örseledi.

Kese bir pamuk oldu Dulana ‘nın üstünde,

Kuştüyü oldu sabun Kalaycı ‘nın elinde.

Su ne soğuk ne sıcak, sanki serin gülsuyu,

Hamam cana getirdi binbir güzel duyguyu.

Nine az bunaldı mı gelsin hemen soğukluk,

Gözlerde parıltılar, yüreklerde burukluk.

Havlunun biri gitti, biri geldi öteden,

Sanki yağmur yağmıştı mermere lavantadan.

Azıcık ıslanan havlu yenilendi anında,

Dulana sultan oldu erkekler hamamında.

Havlular dolduruldu bir kurnanın içine,

Başkaları asıldı kurna kitabesine.

Kurna tahta çevrildi, oturtuldu Dulana,

Şuruplar dolduruldu pırıl pırıl taslara

Taht yapılan kurnada o içip serinlerken,

Bir cümbüştür başladı göbek taşında, derken.

Tokmak Kazım boynuna asıverdi davulu,

Gardiyan zurna etti elindeki kavalı.

Kimisi çengi oldu, kimisi de rakkase,

Hepsi birden verdiler ol hamamda ses sese.

Göbek atıp döndüler önünde Dulana ‘nın,

Haddi hesabı yoktu orada kıvıranın.

Dulana bilmiyordu, hamamda mı, nerdedir,

Belki hamamda değil, düpedüz cennettedir.

Şu kız huri, bu peri, şunlar cennet hatunu,

Bulup çıkaramadı masalın hududunu.

Sezer gibi olsa da bazısında bir bıyık,

Engel olup duruyor anlamaya o kılık.

Fistanlı herif olmaz ama kadın sakallı,

“Sakallı karı olmaz, hadi uçtum akıllı.”

“Şu herif Necla mıdır, ya da Necla şu herif,”

Sorsalar anlatamaz, hatta edemez tarif.

Bir aralık seslendi: “Sen misin kız Hediye? 

Aman kız, kadınlığı yükledin mi kediye? ”

Herif olsun, ya karı, Dulana çok mutluydu,

Bulutlar içindeydi, yarından umutluydu.

Yılların yorgunluğu silinip erimişti,

Sanki Allah nineye yeniden can vermişti.

Havlulara sardılar bu kere ilahiyle,

Dulana helallaştı o yüce Allahıyla.

Dedi: “Senden hoşnutum, sen benden hoşnut musun? 

Merak ederdim rabbim, beni unutmuş musun? 

Sana şükürler olsun; cennet verdin dünyada,

Böyle cennet arasam bulamazdım rüyada.”

Nineyi tekbirlerle alıp kuruladılar,

Yüzünü gülsuyuyla gayet bol yıkadılar.

Giyinince bohçayı alıp ele yürüdü,

Hamamcı parasını iterek geri verdi.

Nine kapıya çıktı, ki; iki er bekleşir,

İtfaiyeci Neşet, kalaycı Sarı Beşir.

Girdiler kollarına, götürdüler nineyi,

O anda bir efsane fethetti mahalleyi.

Dediler: “Dulana ‘yı yıkamış sırf huriler,

Önünde halay tutmuş bütün cinler, periler.

(Hikmet BARLIOĞLU (1933/2003)  ''nun

MÜHENDİS BEY isimli Şiirsel Gülmeceler ''inden > 38-50/100)', 'Mahallenin en yaşlı kadınıydı Dulana, Ödül konsa yeridir doğumunu bulana. Derler ki; “Yaşı yüzon, belki daha da yüksek”, Kimse bilmez gerçeğ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":300,"source_url":"https://www.antoloji.com/dulana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-nurettin-ozdemir-6nd2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce bir eylül geçti bakışlarımdan, sırılsıklam.

Uçuşan bulutlarla deli-divane bir gökyüzü geçti.

Geçti son ışıklarıyla bir güneş, bir kocaman gül,

Bir kuru dal, bir sarı yaprak, bir durgun su.

Islak kanatlarında umut taşıyan muhacir kuşlar geçti.

Sonra bir ekim geçti, ölümsüz sevgilerle dolu dizgin.

Eteklerinde yazdan artakalmış körpe çimenler geçti.

Geçti en güzel yüzüyle asil ve mağrur bir kadın; 

Dağılmış saçlar, buğulu gözler, dudaklar, eller..

Ilık sesinde ışık çağlarından uğultular geçti.

Bir sonbahar geçti, yaprakların altın parıltısında.

İki hayal gibi iki yürek geçti bir tepeden.

Geçti, sonsuzluğa uzanmış elleriyle nurdan bir çocuk.

Hür çığlığında mavi, mor, yeşil, turuncu ve sarı

Ve bir renk çağlayanından beyaz duygular geçti.

Nihayet zaman geçti, pençesinde çırpınan bir kuş...

Zalim saatler, günler, aylar, mevsimler geçti.

Geçti yenilmez kahramanlar.. O eski tanrılar...

Kıyısız deniz, ufuksuz gök, orman ve sonrasızlık

Ve çöl sabahlarında uyanılmış derin uykular geçti.', 'Önce bir eylül geçti bakışlarımdan, sırılsıklam. Uçuşan bulutlarla deli-divane bir gökyüzü geçti. Geçti son ışıklarıyla bir güneş, bir kocam...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonbahar-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmış', 'varmis-mustafa-yigit-morpheus-724x0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takdiri ilahi ile geldim dünyaya

Meğerse gelişimde bir sebep varmış

Büyük bir şevkle içtim aşk şarabını

Meğerse içişimde bir sebep varmış

Aşık oldum bir kıza tevafuken

Gece gündüz onu düşünüyorum mecburen

Uyuyamaz oldum sevdasından

Meğer sevdalanmamın bir sebebi varmış

Bu dünyanın zevkini aldım

Gönlümce yaşadım istediğimi yaptım

Gönlümce güldüm, coştum, eğlendim

Dünyada eğlenmemin bir sebebi varmış

Sebebi şudur, dünya fani

Bir insanoğlu olurmu kani

Sende öleceksin her insan gibi

Bu dünyanında bir sonu varmış

 Mustafa Yiğit (Morpheus)', 'Takdiri ilahi ile geldim dünyaya Meğerse gelişimde bir sebep varmış Büyük bir şevkle içtim aşk şarabını Meğerse içişimde bir sebep varmış Aş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/varmis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara kedi boz yılana saldırdı', 'kara-kedi-boz-yilana-saldirdi-seyhmus-sait-aydin-6e8ze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara kedi boz yılana saldırdı 

Tüylerini kabarttı 

Dikti gözlerini bir noktaya 

O meşhur sesini yükseltti 

Tısssssladı 

Boz yılan tehlikedeydi 

Dilini çıkarttı 

Salladı saga sola 

Tısss sesini ıslıkladı 

Biliyordu boz yılan 

Kara kedi kendinden korkar 

Kendinin alacagı tırnak yarası 

Katlanacak ona canı pahası 

Geldiğinde üstüne kedi 

Can alıcı yerine akıtmak zehirini 

Sarılıp belini kırmakta cabası 

Kedi anladı yılanın düşüncesini 

Bir filim gibi geçirdi kafasından 

Yaşamının öncesini. 

Bir eli yagda bir eli balda 

Gündüz lüks koltukta salonda 

Evin erkegi yoksa 

Geceleri 

Hanım koynunda. 

okşanıyor başı. 

Karar verdi 

Çizdirmeden karizmayı 

Bitirmeli bu savaşı. 

Boz yılan anladı kedinin düşüncesini 

Onada zor gelecekti tırnak acısı 

Biliyordu yaman olur sancısı 

Son bir kez bakıştılar göz göze 

Kedi kirpi dikeni olan yelelerini indirdi 

İki adım geriledi. 

Boz yılan ıslıgını çaldı kediye 

Hadi git işine dedi. 

Ortak çıkarları vardı ikisininde 

Birinin yaşamı saraylarda 

Diğerinin uçsuz bucaksız kırlarda, 

Danışıklı dögüş gibiydi kavgaları 

Pastadan daha fazla pay almaktı 

Hırlamaları 

İş postu deldirmeye gelince 

Deldiler düm yasaları 

İkisininde lüks yaşamdı kaygıları.', 'Kara kedi boz yılana saldırdı  Tüylerini kabarttı  Dikti gözlerini bir noktaya  O meşhur sesini yükseltti  Tısssssladı  Boz yılan tehlikedey...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kara-kedi-boz-yilana-saldirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalılar Dost Bana', 'sevdalilar-dost-bana-i-hsan-dinibutun-lriqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler sözlü bana

Gündüzler hayran

Dost bana sevgililer,

Sevdalılar dost

Ağıtlar alın terim,

Hoyratlar elim

Türküler dilim benim,

Ezgiler sevgim

Susadım, çölde gibi

Susadım Aşk''a

Eline bir uzansam,

Tutamam asla

Uzak bir Aşk bu,

Çok uzak bana

Yıldızlar daha yakın,

Ahhh bir ulaşsam

Biraz yakın ol bana, 

Yaklaş biraz yanıma

Sanki ölmeyecekmişim,

Dokunsam saçlarına

Sevdalılar dost bana,

Sevgililer dost

Geceler sözlü bana,

Gündüzler hayran', 'Geceler sözlü bana Gündüzler hayran Dost bana sevgililer, Sevdalılar dost Ağıtlar alın terim, Hoyratlar elim Türküler dilim benim, Ezgiler s...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdalilar-dost-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluş', 'kurtulus-nurettin-ozdemir-qavno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzellik mavide, yeşilde değil; denizdedir.

Giden geminin ardında kalan o köpükten izdedir.

Kalbim çırpınarak düşüyorsa maviliklere,

Kurtarmak onu sevdiceğim, elinizdedir!', 'Güzellik mavide, yeşilde değil; denizdedir. Giden geminin ardında kalan o köpükten izdedir. Kalbim çırpınarak düşüyorsa maviliklere, Kurtarm...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kurtulus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-mustafa-yigit-morpheus-cexpl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gündüz hayalimde gece düşümde

Beni bu sevdaya attın vefasız

Cennet gibi diye cehennem ateşinde

Kurumuş odun gibi, yaktın vefasız

Kalbin başka söyler dilin bir başka

O yalanların beni düşürdü aşka

Öyle güzelsinki doyamıyorum sana

İçmeden sarhoş, ettin vefasız

Sözlerinle beni bağladın kendine

Söyle nasıl dayanayım hasretine

İsyan eder oldum artık kaderime

Beni bir serseri, yaptın vefasız

Hasretinle beni sürdün aknaraya

Sevilmek nasıl bir duygu anlatsana

Durak seni kalpten sevdi ama

Sen beni hiç, sevemedin vefasız

 Mustafa Yiğit (Morpheus)', 'Gündüz hayalimde gece düşümde Beni bu sevdaya attın vefasız Cennet gibi diye cehennem ateşinde Kurumuş odun gibi, yaktın vefasız Kalbin başk...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vefasiz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadımki..', 'yasamadimki-omer-aydin-66032', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerimdeki kırışıklığı,alnımdaki çizgileri,

Bana sorma ben çizmedimki.

Başımdaki saçı,ağzımdaki dişi,

Bana sorma ben dökmedimki..

Çoluk çocuk sorma bana,

O kadar yaşlanmadımki,

Sorma bana gençliğimi,

Hiç YAŞAMADIMKİ....', 'Ellerimdeki kırışıklığı,alnımdaki çizgileri, Bana sorma ben çizmedimki. Başımdaki saçı,ağzımdaki dişi, Bana sorma ben dökmedimki.. Çoluk çoc...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aydın']::text[], 8.5, '{"poet":"Ömer Aydın","poet_slug":"omer-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamadimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız1', 'vefasiz1-mustafa-yigit-morpheus-zfef7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgilin aklına geldiği zaman

Dumanlı dağlara bakarak ağlama

Bir selam dahi göndermiyorsa

Boşver de gitsin, sen üzülme

Seviyorum diye sakın utanma

Aşk karşılıklıdır bunu unutma

Seni eğer başkasıyla aldatıyorsa

Bir zalime gönül vermişim dersin

Sana sorarlarsa bu aşk nasıldı diye

İyiydi de acın bilinmesin

Ne kadar büyük derdin olsada 

İyi görün düşmanların anlamasın

Durağım unutma sende seversin

Bir ömür boyu yolunu beklersin

Seni değil başkasını severse

Soranlara ne yapalım vefasızmış dersin

 Mustafa Yiğit (Morpheus)', 'Sevgilin aklına geldiği zaman Dumanlı dağlara bakarak ağlama Bir selam dahi göndermiyorsa Boşver de gitsin, sen üzülme Seviyorum diye sakın ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vefasiz1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-mustafa-yigit-morpheus-sndd0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bu satırları 

Gecenin ıssız karanlığında yazıyorum

Gökyüzünde yıldızlar 

Etrafa ışık saçmaz oldu

Kalbimi aydınlatan güneş 

Sen yoksun diye doğmaz oldu

Dışarda rüzgar esiyor

Seni, kokunu ve sevgini

Alıp götürüyor benden

Ulaşamıyorum,

Tutmak istiyorum, tutamıyorum

Ellerimden bir kuş misali

Uçup gidiyorsun göklere

Kayboluyorsun

Gecenin ıssız karanlığında

Gözlerimde toplanan

Ve bu kahrolası gecenin 

Ayazında,

Toprağa düşen gözyaşlarımı

Göremiyorsun.

Göremiyorsun, 

Arkanda nasıl bir kalp bıraktığını

Parçalanmış,

Yıkılmış,

Mahvolmuş.

Ay bile küsmüş artık

Aydınlatmıyor gecelerimi

Sen yoksun ya herkes bana dargın

Her şey bana kırgın

Üşüyorum.

Kollarım sarıyor sensiz geceleri

Avunamıyorum, ısınamıyorum

Beni ısıtabilecek

Bir yarimde yok artık

Bilinmez yerlere gitti

Gecenin ıssız karanlığında

Beni karanlıklarda bırakıp gitti

Yasak sevdalar denizinde

Teknesiz, sandalsız 

Bırakıp gitti

Gecenin ıssız karanlığında

Karanlıklarda bırakıp

Yeni umutlara,

Yeni aşklara, kanat açarak gitti.

 Mustafa Yiğit (Morpheus)', 'Sana bu satırları  Gecenin ıssız karanlığında yazıyorum Gökyüzünde yıldızlar  Etrafa ışık saçmaz oldu Kalbimi aydınlatan güneş  Sen yoksun d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yalnizlik-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Sevda', 'yasak-sevda-mustafa-yigit-morpheus-qjrod', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdalara yelken açtım

Hayat denizinde

Fırtınalara yakalandım

Sevda çöllerinde

Aşkıma ulaşamıyorum 

Gönül bahcesinde

Sevdalar artık

Umutlarda kaldı

Yeşertemedim çöllerde,

Sıcaktan kavruldu

Öyle aşklar vardır

Kavuşamazlar, buluşamazlar

Ama,

Yıllarca sevdalarından yanarlar

Benimde sevdam 

Öyle işte

Umutsuzca bir sevda

Yani 

Yasak sevda

Buluşmamız, kavuşmamız 

İmkansız

Sevdalar paylaşıldıkca değil

Yaşandıkca unutulmaz

Ölesiye yaşamak

Cıldırasıya hissetmek gerekir

Ulaşılmaz bir aşk bu

O başka kollarda

Mutlulukdan uçuyorken

Ben zindan köşelerinde

Yasak sevdama yanıyorum

Çöl ortasında 

Gül yetiştirmeye çalışıyorum

Aşkın denizinde

Boğulmadan ilerliyorum

Gözyaşlarıma hasret katıp

Sevda denizinde yelken açıyorum

Sevda çöllerinde 

Sevdamı arıyorum

Sevda yüklü bulutlardan

Akan yağmurlarda

Yasak aşkımı arıyorum

Kimsenin ulaşamadığı

Yalçın kayalarda 

Yasak sevdama yanıyorum

 Mustafa Yiğit (Morpheus)', 'Sevdalara yelken açtım Hayat denizinde Fırtınalara yakalandım Sevda çöllerinde Aşkıma ulaşamıyorum  Gönül bahcesinde Sevdalar artık Umutlard...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yasak-sevda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş Yavaş', 'yavas-yavas-mustafa-yigit-morpheus-u5rm0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Selvi boyuna kurban olduğum

Bekletme yolları gel yavaş yavaş

Yalnız şunu bilki sana vurgunum

Akan gözyaşlarımı sil yavaş yavaş

Senden uzaklarda hep böyleyim

Yeterki iste hemen öleyim

Kız senin için canım vereyim

Sende artık beni sev yavaş yavaş

Senden haber alamadım bak yine

Bir kabus gibi çöktün gönlüme

Senin yokluğunu anlatamıyorum kalbime

Artık şu kalbime gir yavaş yavaş

Bir haber göndersen dağları düz ederim

Ferhat misali kayaları delerim

Sen sevmesende ben yine seni severim

Sende artık Durağı sev yavaş yavaş

 Mustafa Yiğit (Morpheus)', 'Selvi boyuna kurban olduğum Bekletme yolları gel yavaş yavaş Yalnız şunu bilki sana vurgunum Akan gözyaşlarımı sil yavaş yavaş Senden uzakla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yavas-yavas-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Sen', 'yuregimde-sen-mustafa-yigit-morpheus-msbdm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum kimsenin bilmediği yerlere

Gözlerimde hasret, yüreğimde sen

Düştüm sonu olmayan gurbet ellere

Gözlerimde hasret, yüreğimde sen

Gözyaşlarım yerinde duramaz oldu

Sevda çöllerinde çiçeğim soldu

Hasret vapuru limana uğramaz oldu

Direğinde hasret, dumanında sen

Aşk güvercinim yuvasını bulamıyor

Gönül ağacında bir dal arıyor

Gurbet ağacı yollarını bağlıyor

Dallarında hasret, yaprağında sen

Dağ başında gezen yaralı ceylan

Yüce dağlarda yarini bulsan

Çektiğin hasretlikle sinene sarsan

Ellerimde hasret, kollarımda sen

Bir ceylan vurulmuş bağrı yaralı

Durak gülmez oldu senden ayrı kalalı

O ince belini yabancı eller saralı

Gözlerimde yaş, yüreğimde sen

 Mustafa Yiğit (Morpheus)', 'Gidiyorum kimsenin bilmediği yerlere Gözlerimde hasret, yüreğimde sen Düştüm sonu olmayan gurbet ellere Gözlerimde hasret, yüreğimde sen Göz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuregimde-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atışma', 'atisma-i-lyas-ozmen-a8so4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duyduk Türkmen Yurdu Eskişehir''de 

Kanatsız kuyruksuz uçanlar varmış 

Kıspetsiz dolaşıp ermeydanında 

Rakipsiz kürsüye çıkanlar varmış 

Aşıklar anlarmış adam hasından 

Alimin ilminden cahil hırsından 

Güya biçarenin titrek sesinden 

Korkupta meydandan kaçanlar varmış 

Kimini öldürüp kimini vurup 

Kimine kiloyla bir yedek bulup 

Sabit''le Ceylan''ı kenara koyup

Kibirle kendinden geçenler varmış 

Üç beş satır yazmış garip fukara 

Meydanı boş bulmuş atıyor nara 

Pehlivan Özmen''e gelince sıra 

Korkudan dizüstü çökenler varmış 

ÖZMENEM huyumdur çatmam çürüğe 

Değer vermem kıyafete çarığa 

Sizin elde benim gibi çırağa 

Muhabbetle kucak açanlar varmış 

(ÖNEMLİ NOT:Mustafa Ceylan ve Antalya GÜLLÜK Dergisi

 Grubu üyelerinden Rasim Ustamızın atışmasına iştirak için

 yazdım,yalnız bu konuda tecrübesiz olduğum için bilmeden 

 bir hatam olduysa burada kendisinden ve bütün şiir sevenlerden

 affımı dilerim.SAYGILARIMLA)', 'Duyduk Türkmen Yurdu Eskişehir''de  Kanatsız kuyruksuz uçanlar varmış  Kıspetsiz dolaşıp ermeydanında  Rakipsiz kürsüye çıkanlar varmış  Aşık...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/atisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizginli Hayat', 'dizginli-hayat-i-hsan-uncuoglu-r938b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gücünü kuvvetini gökten bildir 

Ağzınla kuş tutan mecliste yerin 

Ser seril serpilip zaman ol sergile 

Ağacında yaprak kitabında sahife 

Karınca kaderince dal düşünceye, 

*** 

Kardeşlerde bile sır dünyası ayrı ayrı 

Bir‘var’ bir ‘yok’ değişik algılanır gayret et 

İki tel saçla kel başa süslü tanım altüst karışık 

Yığınla binbir yorum yazı tura bin çeşit savaş 

İnsan benli yıldız yalnız kendiyle sarmaş dolaş, 

*** 

Gözleri kapalı eleğin altına mil geçmez 

Karanlıkta gün için her yakada avuç aç 

Boş çekirdek tohumla toprak yeşermez 

Her geçitten diğerine köprü olan insan 

Sağlam kök sal üstte türlü ağaç dal budak 

Elde terazi yaşanan dünya dizginli hayat bak 

Antika bu öyle hikaye ki altı üstü allak bullak,', 'Gücünü kuvvetini gökten bildir  Ağzınla kuş tutan mecliste yerin  Ser seril serpilip zaman ol sergile  Ağacında yaprak kitabında sahife  Kar...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dizginli-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sana Son Şiirim', 'bu-sana-son-siirim-abdil-yasaroglu-bdvfo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün, bir gün gideceğim bu şehirden

Bir sabah hayalinle uyanmayacağım artık, 

Tüm üzüntülerini, olumsuzluklarını

bana yaşattığın o bitmek bilmez acıları 

Depremde yok olmuş bir şehir gibi 

bende yok edeceğim…

‘Aldırma’ demeyeceğim günden güne, 

Boynumu büküp, içimi içime çekip 

Bu da geçer her şey güzel olacak diye 

kandırmayacağım kendimi…

Bindiğim otobüslerde,

yemek yediğim yerlerde hatırlamayacağım seni,

Yağmurlu günlerde 

olmayan seni aramayacağım sokaklarda sırılsıklam,

Sümbüller için dolaşmayacağım kırdan kıra 

Hele birde çekilip usulca odama 

Sevinçlerimi, sana olan aşkımı, sevgimi 

Dökmeyeceğim kalemimle satırlarıma…

Yoksun artık! , bugün senin en mutlu günün,

Sevinçlerin var, 

Umutlarının gerçekleştiği sevinçlerin.

Beni sormaya hakkın yok,

Her zaman söylediğin hedeflerim var daima.

Bitmek bilmez, umut dolu, dürüst hedeflerim… 

Ama bilesin ki yâr son hedefim 

Senin için, 

Beni bir kalemde silip, 

umutlarının gerçekleştiği 

o beni kaybettiren, 

galip gelen o “değer” var ya  o “değer”

İşte o “değer”le 

Bir geceliğine satın alacağım seni…', 'Bir gün, bir gün gideceğim bu şehirden Bir sabah hayalinle uyanmayacağım artık,  Tüm üzüntülerini, olumsuzluklarını bana yaşattığın o bitmek...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-sana-son-siirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Insan', 'once-insan-mehmet-isikoglu-xc1cm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seven açsın kapımızı

Anlasınlar yapımızı

Tüm insanlar dosttur bize

Ayrılıklar kalpte sızı

İnsanadır bizde saygı

Ayrımcılık büyük kaygı

Yaratıklar hep kutsaldır

Olmaz bundan güzel duygu

Bu duyguyu paylaşalım

Beraberce kaynaşalım

Hamur aynı maya aynı

Bir zeminde uylaşalım.', 'Seven açsın kapımızı Anlasınlar yapımızı Tüm insanlar dosttur bize Ayrılıklar kalpte sızı İnsanadır bizde saygı Ayrımcılık büyük kaygı Yarat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/once-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehri Terk Etmek', 'sehri-terk-etmek-abdil-yasaroglu-wb866', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin hiç bu şehirden 

Ardına bile bakmadan 

Aileni, sevdiklerini, dostlarını arkadaşlarını

Hiçe sayarak terk etmek  geldi mi? 

Senin hiç bugün sevdiğinin, gönül verdiğinin 

Canını canına katıp dağları devirdiğin

Yârın, her şeyinin 

Evleneceği geldi mi?', 'Senin hiç bu şehirden  Ardına bile bakmadan  Aileni, sevdiklerini, dostlarını arkadaşlarını Hiçe sayarak terk etmek  geldi mi?  Senin hiç bu...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehri-terk-etmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Top Yuvarlak', 'top-yuvarlak-i-hsan-uncuoglu-pywxq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anam mutfaktan çıkmaz 

Musluk başından ayrılmaz 

Babam maç kaçırmaz delisi 

Koltukta uyur oynar hevesli 

Sahada şiir yazar o çok yetenekli 

Her takımın hakemi aşk meselesi, 

*** 

Babam topçudur ezeldenberi 

Rüzgarı geçer topa tutar kaleyi 

Her attığı karavana şaşırır kaleci 

Kıralı gelse hakeme o görünmez 

Papatya çiğnemez karınca ezmez 

Dünyaya benzeri bir daha gelmez, 

*** 

Aileden kalma derim 

Hakem ne bilmezdim 

Bir iki def’a hatırımda 

Top oynardım çayırda 

Çocuklukta güreşirdim 

Omuzumda püf duysam 

Yerden yere düşerdim, 

*** 

Kuyruklu saç sakal 

Elde değil elim boş 

Dilim sürçer sağa sola 

Kör oluyorum oyunda 

Sol ayakla bir rövöşeta 

Top’la hakemi gör havada, 

*** 

Sağ ayağım eşsiz kuvvetli 

Kafa toplarımın yok misli 

Ağ yırtar şutum sanki mermi 

Kıvrak çalımlar atarken ben 

Ayağımla taraftara hava atarım 

Alkışlara zıplarım yeri göğü sallarım, 

*** 

Artık bir taneyim birinci ligde yerim 

Pas alınca sahada karış karış gezerim 

Benden topu alanı görmesin gözlerim 

Oyun atanı devirirde çimhalıya sererim 

Bunda ne var sanki hakem tırt düdük çalar 

Elim topa değse bilmem kırmızı kart bana çıkar,', 'Anam mutfaktan çıkmaz  Musluk başından ayrılmaz  Babam maç kaçırmaz delisi  Koltukta uyur oynar hevesli  Sahada şiir yazar o çok yetenekli  ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/top-yuvarlak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Çiçekçeri', 'ruya-cicekceri-mehmet-isikoglu-flly5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensin şiirlerin tek kahramanı

Sensin hassas yerin özel sultanı

Taştı sabır taşı zorlar yapıyı

Bekletme yetiştir acil dermanı

Özel hazırlanmış duruyor yerin

Kışları sımsıcak yazları serin

Hissetsen açılır kitli kapılar

Aynıdır kaynağı o sezgilerin

At bir yastık gönlümdeki döşeğe

Rüya çiçeklerim bekliyor seni

Bal yaparsın içimdeki peteğe

İşlersin ruhuma sevgi deseni.', 'Sensin şiirlerin tek kahramanı Sensin hassas yerin özel sultanı Taştı sabır taşı zorlar yapıyı Bekletme yetiştir acil dermanı Özel hazırlanm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruya-cicekceri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diken ve Gül-2', 'diken-ve-gul-2-muhammed-i-kbal-baysal-ldaaj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adındır kalbimde yine sensiz bu sabah

bahtsız bir dikenim güle sığındım bu sabah

anladım anlamaktan ötesi günah

yine bir köşe başındayım yine korkuyorum

yine en zayıf  anımda

kaderimle karşı karşıyayım

kulluğumda binbir kusur

belki bu yüzden kederin aranan simasıyım

belki bu yüzden şeytanlar arar beni

anlatamam düştüğüm kuyuyu

melekler en çaresiz anımda buldu beni

bu sefer kovulmasam kapından

eşiği rahmet olan dergahından

ümitsize yeryok 

kararsıza dert çok

istemektende ziyade 

ne verirsen amenna

bu seferde ayırma dergahından

girenleri hep bahtiyarlar kapından

ne kadere sitem gelmeyene gelderim

nederim görünenlerin en bahtsızı benim

bana korku salan o en tatlı korku

o korku bu korkağın belki yaşam umudu

gözlerinden görmesem boşa değil inancım

belki bir kere elimden tutsan belki yürüsek

ozaman anlarım  anın en hayırlısıyım

şu an varlığına herşeyden çok muhtacım

o perdeleri arala ilk gördüğün varlığım

topladım tüm gücümü emrimde sağ ve sol cenah

en güzel olsun diye büyüteceğim şiirimi

ve bekle ey gül daha bitmedi...

bekle biiznillah', 'Adındır kalbimde yine sensiz bu sabah bahtsız bir dikenim güle sığındım bu sabah anladım anlamaktan ötesi günah yine bir köşe başındayım yin...', ARRAY['Türk Edebiyatı','Şiir','Muhammed İkbal Baysal']::text[], 8.5, '{"poet":"Muhammed İkbal Baysal","poet_slug":"muhammed-i-kbal-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/diken-ve-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Köyüm', 'benim-koyum-mustafa-toga-b33wb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çukurova’nın ortasında

Kurulusun benim köyüm.

Toros dağlarına karşı

Duruyorsun benim köyüm. 

Kışın çamur, yazın tozdan

Sivrisinek kaynar sazdan

Akar çayın dar boğazdan

Tarlaların sular köyüm.

Çakıllıdır köyün yolu

Ağaçlıktır sağı solu

Kışın vurur köy dolu

Kodamandır benim köyüm.

Susam, bugdaydır tarlası

Bolluk, bereket yuvası

Pamuk doludur ovası

Seçiliyor benim köyüm.

Çiftçiliktir mesleğimiz

Okuyorda gençlerimiz

Subay, doktor, hemşiremiz

Mutlu musun benim köyüm.

Bahçelerin, bağlarınla

Pamuk dopdolu tarlanla

Köten, pulluk, motorunla

Yaşıyorsun benim köyüm.

Kısahasanlı’dır adı

Toga’ma sevgisi kaldı

Kadirli ilçemiz oldu

Ne şirindir benim köyüm.

www.togamedya.tr.gg

1975 - Kadirli / ADANA

SÖZÜN ÖZÜ:

Çok bildiğini sanan çok yanılır. Bin bilirsen de yine bir bilene danış.', 'Çukurova’nın ortasında Kurulusun benim köyüm. Toros dağlarına karşı Duruyorsun benim köyüm.  Kışın çamur, yazın tozdan Sivrisinek kaynar saz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/benim-koyum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyetini Gör Kalbinde', 'niyetini-gor-kalbinde-oguzkan-bolukbasi-f35vp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte diyorum işte

Kimimiz iş''te

Kimimiz..

Do, re,mi,fa

sol,la

manın sırası mı

si, do

lana yar dolana

İşte diyorum işte', 'İşte diyorum işte Kimimiz iş''te Kimimiz.. Do, re,mi,fa sol,la manın sırası mı si, do lana yar dolana İşte diyorum işte...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/niyetini-gor-kalbinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Dostum', 'i-ste-boyle-dostum-ali-fikri-karadeniz-6zfvy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte böyle Dostum

Sorma bana

Sorma nasıl bu derde düştüm

Bir sevdaya tutuldum

Gece gündüz yandım tutuştum...

Bir gece kapım çalındı

Karşımda bir güneş vardı

İlk defa gözlerimin kamaştığını hissettim

Sanki.. Sanki bir elmanın iki yarım parçasıydık

Birlikte ağladık, birlikte dertleştik...

Kopamıyorduk bir birimizden

Arada aşk büyüyordu sevgimizden

Her şey belliydi gözlerimizden

Biz bulutlarda dolaşıyorduk...

Sonra; 

Sonra araya ailem girdi

Onlar bir türlü kabul etmedi

Beni ben olarak görmedi

Avuçlarımdan kalbim uçup gitti...

İşte böyle Dostum; işte böyle

Tam üç yıl bekledim

Kan kustum, kan içtim

Hiç kimseye belli etmedim

Bedenim yandı, ben bittim...

Dayanmıyordu yüreğim çoğu zaman

Damarım, kanım, içimdeki canım

Bir ceketimi, bir kefenimi hazırladım

Dağlara gidiyordum adım adım...

Bir gece

Bir gece karşıma dikildi

''Sen nereye gidiyorsun? '' dedi

Yalvardım ''gideyim'' diye

''Hayır.. Gidemezsin'' dedi

Beni bırakmıyacağına söz verdi...

Dostuuum; 

Ben O''na tapmıştım

Ben O''na inanmıştım

Ben O''na kanmıştım

Artık O''nun için vardım...

Damarlarımı kestiler bir bir

Günü, güneşi göremedim

Her şeye katlandım da o 15 gün var ya

Anlatmıyacağım, korkma...

Peki; 

Peki madem istiyorsun acımı anla

Dörttane iğne vurdular tam şurama

Sanki içime gaz doldurdular da

Çakmağı çaktılar

Yandı bedenim, tutuştu tenim...

Hiç bu kadar dua etmemiştim kurtulmak için

Acılara katlandım O''na kavuşmak için

Bir kuş olmuştum adeta,

Bir bulut, bir rüzgar....

Her şey yolunda gidiyordu, her şey

Hazırlanıyordum hayatımda tatmadığım yaz''a

Dostlarımı, arkadaşlarımı

Yapıyordum düğünüme hazırlıklarımı...

İşte böyle Dostum

Sonrasını sorma bana....

Bunu sana nasıl anlatacağım ama

Her yüceliğin bir bedeli olurmuş sonunda...

Sonra kabuslar başlamıştı

Aldığım haber beni sarsmıştı

İnanmak istemiyordum duyduklarıma

Çünki başka birisi vardı kolunda...

Yine de.. Yine de bekledim

Sesimi çıkartmadım ''görör'' dedim

Adamın fikri neyse, zikri belliydi

Kör olmuş gözleri bunu görmedi

Ah Dostum

Şiirler yazdım adına

Şarkılar söyledim tenine

Dua''lar ettim kalbine

Yaş gününde beni terk etti...

San ki o an dünyam kararmıştı

İşte bu kalp O''ndan hatıra kaldı

Yatakta olduğuma bakma sen benim

''Hey hemşire... Bana bir zehir getir yeniden

Damarıma enjekte et aniden''...

İşte böyle Dostum... İşte böyle

Sen üzülme

Sadece uykusuzum dün geceden

Gözlerimi kalaylamışlar

Boynuma bir halka takmışlar

Ve ay''ın yerine beni asmışlar...! ! !', 'İşte böyle Dostum Sorma bana Sorma nasıl bu derde düştüm Bir sevdaya tutuldum Gece gündüz yandım tutuştum... Bir gece kapım çalındı Karşımda...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/iste-boyle-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni unut', 'beni-unut-sair-kertenkelecim-vozor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilim! 

Yine gece oldu İstanbul''da.

Günden geriye kalan yalnızca keder 

biraz da umut...

Uykusuzluk ile boğuşurken terli yatağımda

son sözün yankılanır; 

Beni unut, beni unut, beni unut...', 'Sevgilim!  Yine gece oldu İstanbul''da. Günden geriye kalan yalnızca keder  biraz da umut... Uykusuzluk ile boğuşurken terli yatağımda son sö...', ARRAY['Türk Edebiyatı','Şiir','Şair Kertenkelecim']::text[], 8.5, '{"poet":"Şair Kertenkelecim","poet_slug":"sair-kertenkelecim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beni-unut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Hayallerim...', 'hayallerim-erdal-asik-aokpn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuşlarımı özledim gelmediler

Kanatsız kanatları

Kanlar içinde

Uçamadılar 

Yorgun bitap düştüler

Köşelere tünediler

Fırtınaları 

Yağmurları geçemediler 

Acılar içinde çığlıkları

Ağladılar

Ağlamaları

Duyulmadı

Ermediler 

Erişemediler

Hepsi yollarda öldüler! ..', 'Kuşlarımı özledim gelmediler Kanatsız kanatları Kanlar içinde Uçamadılar  Yorgun bitap düştüler Köşelere tünediler Fırtınaları  Yağmurları g...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayallerim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K ''larda', 'k-larda-ali-gencay-79f1n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanayan eşmelerden içtim aşk şarabını

Kelimelerimin cesurluğu sarhoşluğumda

Kaçıncı cesaretim bu,kaçıncı intiharım

Kaçma benden güneşi alacağım kollarıma

Kudurmuşluğun adı mikrobik kalın kitaplarda

Kaçmak istiyorum tabanımı delen acılarla

Kaçıncı isyanım bu,kaçıncı firarım içtimalarda

Korkma benden beyazlar saçamam saçlarına

Kuytusuna büründüğüm alacakaranlıklarda

Koca,devasa canavar yarattım korkularımla

Kaçıncı uçuklayışı bu,kaçıncı sızı dudaklarımda

Kaçır beni korkuyorum çöl kurusu yokluklarında

Kahırların dizildiği tane,tane hüzün sofrasında

Kursağım düğümleniyor kaskatı sevdalarında

Kaçıncı düğümlenişi bu,kaçıncı yutkunuşlarda

Kahrolası boğazım yapma bunu açım ben sevdaya

Kuru yaprak düş! kaderin bu mevsim sonbaharda

Kıyamam çıplaklığına adımızın kazındığı ağaçlarda

Kaçıncı sonbahar bu,kaçıncı baltalanışı acımasızca

Köklerini sal bana tutunacağım,uyanacağım baharda', 'Kanayan eşmelerden içtim aşk şarabını Kelimelerimin cesurluğu sarhoşluğumda Kaçıncı cesaretim bu,kaçıncı intiharım Kaçma benden güneşi alaca...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/k-larda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-i-smail-kulahci-k1lmk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke deniz olsaydım, dalga dalga çarpsaydım gönlüne 

Her dalgada biraz daha,biraz daha işleseydim yüregine

Kıyıya çarptığım her dalgada, bir damla yani benden bir parça 

Dokunsaydı tenine ve ürperseydin

Bende sen her ürperdiğinde, sana her dokunuşumda 

Yavaş yavaş işleseydim yüregine 

İşte o zaman deniz çıldırırdı,dalga dalga büyürdü her seferinde.

Sana biraz daha yaklaşabilmek için

Keşke rüzgar olsaydım 

Her estiğimde,saçlarını okşasaydım

Her estiğimde,tenine dokunsaydım 

Vücudunun her yerinde beni hissetseydin

Her estiğimde biraz daha işleseydim tenine 

Ben her estiğimde ve sen her nefes aldığında

Yüreğine doğru biraz daha işleseydim

İşleyipte birdaha çıkmamacasına 

Ve oradan bütün vücuduna yayılsaydım 

Bütünleşseydim seninle herşeyim sen olsaydın

Keşke ben masmavi bir gökyüzü olsaydım 

her kafanı kaldırdığında ve her ufka baktığında beni görseydin 

her bana baktığında bütün maviliğimle izliyor olsaydım seni

işte o zaman gökyüzü sonsuza dek hep mavi kalırdı

Ve her gece oluşunda, canın gökyüzündeki yıldızları seyretmek istediğinde 

Bana baksaydın ve yıldız gözlerinin milyarlarcasını görseydin 

Benim içimde kendinden bir parça bulsaydın

İşte o zaman gökyüzü milyarlarca sen dolardı

her baktığında gökyüzüne, saatlerce beni seyretseydin

Ve saatlerce kendi gözlerini seyrederdin, benim içimde yüreğimde 

keşke ben bir toprak olsaydım 

her adımında seninle olsaydım 

her nereye gitsen ben hep seninle olsaydım

her yürüdüğünde her koştuğunda ve her durakladığında 

yani senin her anında seninle birlikte olsaydım 

Sonsuza dek hiç  ayrılmasaydım 

her adımını attığında, topuğundan girip karışsaydım kanına 

kanının her kabine uğradığında, oraya sıkıca sarılsaydım

ağır ağır işleseydim her adımında kalbine, yüreğine 

keşke ben ne deniz,ne rüzgar,ne gökyüzü nede toprak olsaydım 

sadece ben olsaydım,sadece ben 

sonsuza dek her an birlikte olsaydık

delicesine sevseydik birdirimizi 

belki çocukcasına ama ölürcesine 

bizi ne rüzdar,nedeniz,ne gökyüzü nede toprak ayırabilirdi

ne olurdu birbirimizi sonsuza dek sevseydik ve ölünceye kadar ayrılmasaydık ne olurdu birtanem 

NE OLURDU?', 'Keşke deniz olsaydım, dalga dalga çarpsaydım gönlüne  Her dalgada biraz daha,biraz daha işleseydim yüregine Kıyıya çarptığım her dalgada, bi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/keske-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini tanı', 'kendini-tani-omer-aydin-0y6wx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostluğu hafife alma,dost olamazsın,

Kimseyi küçük görme,sende büyüyemezsin,

Ağlamayı bilmiyorsan,gülmeyide öğrenemezsin,

Kendini çok iyi tanı,yoksa kaybolursun.

Kadehlerde,şarkılarda arama gücü,ancak sarhoş olursun,

Boşluğa merdiven dayama,çıkamaz yarım kalırsın,

Hak nedir bilmez isen,haksızlığı damarında bulursun

Kendini çok iyi tanı,yoksa kaybolursun.', 'Dostluğu hafife alma,dost olamazsın, Kimseyi küçük görme,sende büyüyemezsin, Ağlamayı bilmiyorsan,gülmeyide öğrenemezsin, Kendini çok iyi ta...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aydın']::text[], 8.5, '{"poet":"Ömer Aydın","poet_slug":"omer-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kendini-tani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşardık bebeğim, yaşardık (2)', 'yasardik-bebegim-yasardik-2-mutlu-ayar-3slse', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben baktıkça çingenelere 

Sevgimiz atıyordu tüm kalpleri kıskandırarak 

Onların kokusuyla anlıyorduk yaşamanın vazgeçilmezliğini 

Onların çocukları vardı üstü başı pis yırtık 

Sen kendine bakardın bir, ben kendime 

Gök ve yer arasında ne kadar paktık 

anlardık 

Yaşadığımız kentte bir yanardağ yoktu 

aslında olsa dahi kaçacak bir yerimizde 

Sen bana bakardın bir, ben sana 

Mırıldanırdı gözlerimiz birbirimize 

kaçınılmaz bir tehlikeydik buralara 

İnsanlar kendilerine bakarlardı bir 

biz kendimize, ama dedim ya 

Kaçacak yerleri yoktu 

Beraberken unutmazdık en küçük şeyleri 

Bir yaşam kazınırdı aklımıza 

sabahleyin bir gemi gözükse ufukta 

öğleyin bir karınca yuvası bozulsa yanlışlıkla 

geceleyin bir çocuk kaybolsa karışıklıkta 

Bir ölüm kazınırdı aklımıza 

Beslenirdik yaşamın küçük armağanlarıyla 

Beslerdik serçelerimizi! 

Ölümlerden zevk alınır mı? Biz alırdık 

Mevlitlerde dağıtılan tek bir lokum aşkına 

aslından biz gerçekte serçeydik 

Yüreğimiz ağzımıza en yakın yerde 

elimizde olsa küçücük bir solucan sevdasına 

Yem olurduk duvar dibinde aç kediye 

beslenmez miydi ki yaşam				

küçük mucizelerle! 

Sen camdan bir tığ alıp gözünü kırpmadan 

ışıkları örer dururdun saatlerce tek tek 

sonra, çok sonra, işte bu derdin, bu işte 

Bu derdin bizim giyineceğimiz 

elimde olsa inanmak istemezdim 

Bir doğuma şahit olur gibi 

yufka bir yüreğe sığınır gibi 

azgın dalgalarda boğulur gibi 

yaşamak okunurdu gözlerinden 

ilmek ilmek...', 'Ben baktıkça çingenelere  Sevgimiz atıyordu tüm kalpleri kıskandırarak  Onların kokusuyla anlıyorduk yaşamanın vazgeçilmezliğini  Onların ço...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasardik-bebegim-yasardik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı özlüyorum', 'bahari-ozluyorum-omer-aydin-kv0cu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taze bir fidandım,çiçek açmak isterken,

Güneş''ine aldanıp,rüzgarına kapıldım kırıldım erken

Üzerimi kaplayan karmış meğer,üşüdüm ısınacağımı sanarken,

Zamansızmı açtım,yoksa kışmı geldi erken

Kök salıp,kol atmak istiyorum kırılmaksızın,

Çağlayanlar gibi çoşarak akmak istiyorum susmaksızın,

Kuşlar gibi uçmak,kuzular gibi koşmak istiyorum yorulmaksızın,

Biliyorum çok şey hayel ediyorum ama elimde değil,baharı ÖZLÜYORUM..', 'Taze bir fidandım,çiçek açmak isterken, Güneş''ine aldanıp,rüzgarına kapıldım kırıldım erken Üzerimi kaplayan karmış meğer,üşüdüm ısınacağımı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Aydın']::text[], 8.5, '{"poet":"Ömer Aydın","poet_slug":"omer-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahari-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Manzara', 'hazin-manzara-kamber-bal-rhvwc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yığın yığın insanlar gördüm

Her biri, birinden telaşlı

Kimi yürek söker kimi ateşli

Yarına koşar kibi

Asılmış darağacına bir ulu beyin

Meydan okurcasına

Kimi bakar kederli,

Kimi ulur ahenkli

Tarihi döver gibi

Yol kenarında yumulmak bilmeyen bir el; 

El ki, yarı boynu bükük

Kimi üç beş atar,

Kimi bakıp geçer

Yürekleri kökünden burulur gibi

Yusuf misali kör kuyuda bir çift göz,

Ne sağ solu-ne de sol sağı görür

Ararlar aynı umudu

Taa gardiyan odasın girene dek

Masumum der gibi....', 'Yığın yığın insanlar gördüm Her biri, birinden telaşlı Kimi yürek söker kimi ateşli Yarına koşar kibi Asılmış darağacına bir ulu beyin Meyda...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hazin-manzara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuh', 'yuh-i-lyas-ozmen-v66a0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabit Ustam şiir yazmış

Manasını çözdüysem yuh

Beni yerden yere çalmış

Zerre kadar kızdıysam yuh

Dolaştırmış doğru yolu

Karıştırmış sağı solu

Ben ömrümde Allah kulu

Bile-bile üzdüysem yuh

Ben yazarım ilhamımla

Eksik noksan kelamımla

Dert ortağım kalemimle

Yanlış bir şey yazdıysam yuh

Söyle kimdir hocaların

Okunmuyor hecelerin

Senin gibi nicelerin

Mezarını kazdıysam yuh

Ömrüm geçti yazmak ile

Kör kuyuyu kazmak ile

Hal böyleyken bile bile

Bir gün boşa gezdiysem yuh

Şer görüpte kınamayıp

Toy görüpte sınamayıp

Usta çırak tanımayıp

Aşık olup azdıysam yuh

Olaylara şaşı bakan

Doğrulara karşı çıkan

Kalbi kaya dili diken

İNCE''lerden bezdiysem yuh

(Meydan şiirime bir şiirle cevap veren Sabit İNCE Ustaya

 cevaben yazılmıştır.Sayın Ustanın şiirini merak edenler

 Mustafa Ceylan ve Antalya GÜLLÜK Dergisi Grubunun

 mesajlar sayfasından okuyabilirler.Ayrıca burda yayınlamayı

doğru bulmadım.SAYGILARIMLA)', 'Sabit Ustam şiir yazmış Manasını çözdüysem yuh Beni yerden yere çalmış Zerre kadar kızdıysam yuh Dolaştırmış doğru yolu Karıştırmış sağı sol...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yuh-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işte Firar Ediyor Yine Kalbim', 'iste-firar-ediyor-yine-kalbim-karahan-yilmaz-m95qd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1

Her yürek bir limana benzer

Gemiler gelir, gemiler gider

Gitme ey kaptan! 

O liman seni degil beni bekler

2

Sen gidince başlayan rüzgar

Mırıldanıp durdu sabaha kadar

Işte firar ediyor yine kalbim

Belki birazdan kapını çalar..

3

Biliyorsun aşkların en güzelidir

Bir sevda ağacında yaprak olmak

Yıldızları gökyüzünden indirip

Bozkırları yeşile boyamak...

4

Mevsimler günleri alıp götürüyordu

Solgun renkleri kalıyordu geride gecenin

Seni düşündükçe zaman duruyordu

Aşkı tanımlıyordu sanki gözlerin..

5

Bu sevda sevda değil

Sanki bir talan

Sensiz geçen günlere

Nasıl dayanır insan..

Söyle hangi şarkı

Anlatabilir bu akşamı

Öyle bir şey ki

Deli ediyor insanı..', '1 Her yürek bir limana benzer Gemiler gelir, gemiler gider Gitme ey kaptan!  O liman seni degil beni bekler 2 Sen gidince başlayan rüzgar Mı...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iste-firar-ediyor-yine-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Akşamları', 'paris-aksamlari-karahan-yilmaz-z9wbz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökyüzü susuyor

Geceyi okşuyor bulutlar

Paris derin bir uykuya dalmış

Dansediyor alnında yıldızlar

Sokaklar soyunmuş,

Caddeler yarı çıplak

Tarih sein’i ayartıyor

Zamanla şakalaşarak

Kaldırımlar bomboş

Sokak lambaları sarhoş

Fahişeler aşkı tanımlıyorlar

Paris’in yorgun gözlerinde.', 'Gökyüzü susuyor Geceyi okşuyor bulutlar Paris derin bir uykuya dalmış Dansediyor alnında yıldızlar Sokaklar soyunmuş, Caddeler yarı çıplak T...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/paris-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yüklü Gemi', 'sevda-yuklu-gemi-karahan-yilmaz-19v04', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Içimde bir sevda ırmağı akıp gider

Sen düştükçe aklıma

Dünya tersine döner

Sevmeye görsün insan bir kere

Her akşam yeni bir aşka hüküm giyer

Yüreğim sevda yüklü bir gemidir

Açılır sonsuz mavi ufuklara doğru

Mavi ufuklarda bir güneş yükselir

Soyunur sevdiğim kadınların ruhu', 'Içimde bir sevda ırmağı akıp gider Sen düştükçe aklıma Dünya tersine döner Sevmeye görsün insan bir kere Her akşam yeni bir aşka hüküm giyer...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevda-yuklu-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusu', 'pusu-metin-yalti-dg1wv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...................................Bir Devrimcinin Ölümü

Bir günün gecesinde 

geç saatlerin son çeyreğinde

bir korku duydu birden

derinlerinde yüreğinin

sokağın yalnızlığıncaydı

soğuk bir terleme

üşüyüp ürpermek gibi bir duyguydu

yenilginin ezikliğini duydu.

Kararlı kalkan ellerindeki

soğuk namlu kusunca alev alev

kusunca kurşunları

tükenir sanmışlardı

yüreğindeki sıcaklık

gözlerindeki yaşama sevinci

''sevidir devrimcinin direnci''

izlenmişti gün boyu

belirsiz gölgelerce

her köşede, her yerde varmışlar gibi

nereye gitse suskun bakışlar

aynı anlamı taşıyordular

bugün 

bu gece

birazdan geleceğiz dercesine

donuk ve soğuktular.

Yüreğini saran duygu

bilinçlendi.Korkmamaktı bu.

olüm nereden ve nasıl gelirse gelsin

yiğitçe karşılayacaktı

ona bırakırlarsa eğer

''seviyorum seni'' diyecek kadar

''seviyorum Türkiye'' bir zaman

-sevgilisiyle başbaşa bir zaman-

ölüm o zaman

dudaklarındaki tebessümdü.

duyuyordu ölümü

olüm koltuğundaki kitaptı

bir o kadar yakındı.

her köşede karşılamış 

gölge gölge gülmüşlerdi

soluk gülüşlerle dolu yüzlerini

parlatıyordu soğuk terleri

belleğine korkuyu işletmek içinmiydi? 

kanlı dişlerle bezenmiş yüzleri

ama bilmiyorlardı

''korkmak yok,yılmak asla''

kararıydı.

Bir günün gecesinde

saatlerin son çeyreğinde

susturup bir kurşunla yüreğini

öldürmek istediler

gözlerindeki yaşama sevincini...

Düştü yere

yıkılan bir çınar gibi

uzadı cesedi sokağın yalnızlığınca

kapanan gözlerinde sevinç dondu

dudaklarındaki gülümseme

ölüme inat duruyordu.

yorgundu.

Şimdi uyuyordu

baktılar ürperdiler

sanki yaşıyordu...

20,12,78 Şişli', '...................................Bir Devrimcinin Ölümü Bir günün gecesinde  geç saatlerin son çeyreğinde bir korku duydu birden derinlerin...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/pusu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşlerimi Garson Kıza Bıraktım', 'guluslerimi-garson-kiza-biraktim-karahan-yilmaz-o89i0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gar karşısında bir kahvede

Oturup seni bekledim saatlerce

Gülüşlerimi garson kıza bıraktım

Sevdamı yolladım adresine

Aşklarımı sürgüne gönderiyorum

Bir çizgi çekiyorum eskilerin üstüne

Kendime yeni bir adres arıyorum

Asıyorum gözlerimi gar kulesine

Israrla arama beni diyorsun,

Açıyorsun içimde derin bir yara

Yüreğimi yine sağırlaştırıyorsun

Terkediyorsun beni yalnızlıklarıma

Biliyorum hayatımın kördüğümüsün

Seni çözmek kolay olmayacak

Oysa günlerdir mırıldanıp duruyorum

Bir başkadır seni sende yaşamak', 'Gar karşısında bir kahvede Oturup seni bekledim saatlerce Gülüşlerimi garson kıza bıraktım Sevdamı yolladım adresine Aşklarımı sürgüne gönde...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guluslerimi-garson-kiza-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli ''Şarkı Sözü''', 'melankoli-sarki-sozu-metin-yalti-bpkdx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül ne kadar boş

gönül başıboş

içim boş

koy olsun bu gönül sarhoş

başım dönsün

dünya dönsün

ben olayım berduş

karım ol benim 

atıl kollarıma koş

ki dolsun varlığınla içim

dolsun düşüncelerinle kafam

sıyrılsın berduşluktan

bu seven 

bu sarhoş

bu yorgun

bu yalnız adam.

Gönül ne kadar hoş

dünya bir o kadar boş

ki değil bir kadeh

doldurmuyor bin kadeh.

gene de  dünya bir başka

yıllanmış en eski şarap sanki

insanlıksa en büyük sarhoş.

insanlık büyük sarhoş

ama sakisi kadehi yok

yaşam öyle bir ağaç ki

dalı var yaprağı çiçeği yok

2,8,77', 'Gönül ne kadar boş gönül başıboş içim boş koy olsun bu gönül sarhoş başım dönsün dünya dönsün ben olayım berduş karım ol benim  atıl kolları...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/melankoli-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmedi', 'kimse-bilmedi-ahmet-aksoy-wg6qe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gemiler kalktı durmadan fidanlıkdan

güneş karanlık yol boyu gürbüz

ağıtlar yakıldı gelenin ardından

kimse bilmedi neden yağmur

kimse bilmedi neden deniz

kimse bilmedi neden buhar

çan kulesi yıkıldı bir kez daha

acılar demlendi sıyrıldı kadınlardan

bir koyun katıldı çöle doğru yalnız

kimse bilmedi neden doğum

kimse bilmedi neden ölüm

kimse bilmedi neden yaşam', 'gemiler kalktı durmadan fidanlıkdan güneş karanlık yol boyu gürbüz ağıtlar yakıldı gelenin ardından kimse bilmedi neden yağmur kimse bilmedi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimse-bilmedi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenime Mektup', 'ogretmenime-mektup-kamber-bal-m3tlw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğmak

           nedir? 

Büyümeyi öğret.

Büyümek

            nedir? 

Yaşamayı öğret.

Sustum hep.

Kelimelerim

darağacı oldu

mısralarım ise

birer 

halka

    sen; 

susma! 

 susma malısın! 

konuşmayı

öğret bana.

Konuşmak mı? 

konuşuyorum ya işte

                          hem de

                              için

                                   için

Gülme bana kardeşim 

Yok ki dilim

            yok! 

Yaşamayı öğret.

Dinmedi hiç göz yaşlarım

devrilmedi

               dar ağacım

                                suçum? 

Bütün insanlar yoldaşım

                           budur işte 

                            ayaklanışım.

Gülmeyi öğret.

Kemirildi içim

kurnazlıkla,

               zalimlikle,

                             hainlikle

kof kaldım sevgiden yana

sevmeyi öğret.

Ukala dediler her dirilişimde

bir kıl

        kopardım diye 

                          domuzdan

o halde, saygıyı öğret.

Şefkate,

              sevgine,

                           sana

özlem duyduğum

yüreğimin 

            en

              yalnızlığında

Anneyi öğret.

Korku 

         kıvılcımı sarıyorsa

yüreğimin harmanını

sanmayın ki,

                değildir temkinden

Ola ki sinsilerin sözlerini

 telkin dendir.

Koş

     ve 

       o zaman

hırçınlaşmayı öğret.

Sevgili canım öğretmenim

    .............

.............................

                 1989', 'Doğmak            nedir?  Büyümeyi öğret. Büyümek             nedir?  Yaşamayı öğret. Sustum hep. Kelimelerim darağacı oldu mısralarım ise b...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/ogretmenime-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Sözler', 'kayip-sozler-i-hsan-dinibutun-fpwe0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazdığım sözleri bir bir aradım

Sevgilim sormadık dost bırakmadım

Kıyıya köşeye her yana baktım

Bir türlü onlara rastlayamadım

Oturdum ağladım geçen yıllara

Birlikte yaşanan güzel anlara

Baktıkça sararmış fotoğraflara

Hıçkırdım sessizce hatıralara', 'Yazdığım sözleri bir bir aradım Sevgilim sormadık dost bırakmadım Kıyıya köşeye her yana baktım Bir türlü onlara rastlayamadım Oturdum ağlad...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayip-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sussak..', 'sussak-tulay-eker-gv9yz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgen..

Gölgeme eş olsa

Uzansa boylu boyunca

Günbatımında kavuşsa

Gülümcanla uzansak

O çalsa biz sussak 

Konuşmasak yıldızlar ağlasa

Biz ıslansak..

Gözlerin dokunsa

Yüreğime, rayiha koksa

İçli içli çağlasa sevgi

Aksa dereler boyu

Hasretlerimin suyu

Zerdali olsa,narçiçeği açsa

Yüzümde,güneşin saçakları gibi

Sarsa tenimi aydınlık

Sarmaşık misali sarılsa

Sen olsan sen sadece

Gözlerin sevse...sussak

Bir ömür bitse

Hep biz kalsak sevgimizle.', 'Gölgen.. Gölgeme eş olsa Uzansa boylu boyunca Günbatımında kavuşsa Gülümcanla uzansak O çalsa biz sussak  Konuşmasak yıldızlar ağlasa Biz ıs...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sussak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-i-hsan-dinibutun-w770t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevme dedim deli gönlüm yanarsın

Aşk bu, elde değil ağlarsın

Melek değil

Bir derya gülü gördüğün

Engindir denizi

Bir girsen çıkamazsın

Kaybolursun dalgalarda

Kendini bulamazsın

Maceraya değermi? 

Geçmiş yarısı ömrün

Çok acılar çekersin

Yarası yakar bir gün

Melek değil

Bir derya gülü gördüğün

Engindir denizi

Bir girsen çıkamazsın

Kaybolursun dalgalarda

Kendini bulamazsın', 'Sevme dedim deli gönlüm yanarsın Aşk bu, elde değil ağlarsın Melek değil Bir derya gülü gördüğün Engindir denizi Bir girsen çıkamazsın Kaybo...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deli-gonlum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Ben', 'bendeki-ben-bedihi-kazim-nasuhbeyoglu-35xpg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni benden sorma, bendeki beni, 

Beni bilmeyene açabilmek zor. 

O ki görmüyorsun gözü vereni,

Seninle gerçeğe geçebilmek zor.

Bir dünya yüklüyüm dümeni kuyruk,

Bir dünya yüklüyüm başına buyruk, 

Bir dünya yüklüyüm gerçeğe çevrik,

Bir dünya yüklüyüm uçabilmek zor.

Beni açmaz senin yaptığın dünya, 

Bana gelmez senin taptığın dünya, 

Beni bulmaz senin saptığın dünya, 

Dünyamdan dünyana geçebilmek zor.

1970', 'Beni benden sorma, bendeki beni,  Beni bilmeyene açabilmek zor.  O ki görmüyorsun gözü vereni, Seninle gerçeğe geçebilmek zor. Bir dünya yük...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bendeki-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak İsterim', 'unutmak-i-sterim-bedihi-kazim-nasuhbeyoglu-bhe5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmak isterim düşündüğümü, 

Unutmaz bu acı,sargındır bana. 

Çözdükçe karışır derdin  düğümü, 

Keder içten içe girgindir bana.

Unutmak isterim atılan taşı, 

Unutmak isterim dünkü savaşı, 

Beynini karnında taşıyan şaşı,

Unutmaz ne halse kırgındır bana.

Unutmak isterim,olmuş olanı,

Unutmak isterim hamı,yalanı, 

Unutmak isterim,dönen plânı, 

Unutmaz o beni,vurgundur bana.

Sisli sabahlarla,gamlı geceler, 

Yorgun hayalimi kurar kurcalar,

Bir dert,bir kördüğüm tüm bilmeceler, 

Her gün hüzün çeken bir gündür bana.

Güçsüz kollarımla ağır hayatı,

Taşımaz bilirim yürek niyeti, 

Gel dese giderim; yok ki daveti, 

Ölüm şu günlerde dargındır bana.

Taş  diken  dinlemem,sana  dönerim, 

Sende tükenirim, sende yanarım, 

Bir acı yarayım, durmaz kanarım, 

Bu  dünya hayatı  sürgündür bana.

	

			18/9/1970', 'Unutmak isterim düşündüğümü,  Unutmaz bu acı,sargındır bana.  Çözdükçe karışır derdin  düğümü,  Keder içten içe girgindir bana. Unutmak iste...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/unutmak-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmiştin', 'sen-gelmistin-metin-yalti-l58na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açar bir kitabı okursun

Satırlar boyu akla kara arasında

devinir ve yorulurlar gözlerin

Ya biter okuman

Veya sen

birara kaldırırsın başını kitaptan.

hep o aralara nedense

-ya da bana öyle gelir-

Voltaj yükselir, ışık bir artarki

Kamaşırlar gözlerin ışığa boğulmaktan...

Dün okuduğım kitaptan

kaldırdım başımı bir ara

her yan aydınlandı birden

gözlerim kamaştılar

gene voltajdan sandım

sen gelmiştin.

16/09/79 Mecidiyeköy', 'Açar bir kitabı okursun Satırlar boyu akla kara arasında devinir ve yorulurlar gözlerin Ya biter okuman Veya sen birara kaldırırsın başını k...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gelmistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüğüm Her Kadın', 'gordugum-her-kadin-i-hsan-dinibutun-b8wck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her kadın bir parça senden

Biri kaşın, biri gözün, biri bakışın

Her biri yakıyor beni derinden

Biri sevdan, biri Aşk''ın, biri ateşin

Gördüğüm her kadın bir parça senden

Biri boyun, biri posun, birisi huyun

Her biri alıyor bir parça benden

Biri yüzün, biri tenin, biri nefesin

Kimi senin gibi yürür yollarda

Kiminin saçları düşer kaşına

Kimi her haliyle senin havanda

Biri ağzın, biri dilin, birisi sözün', 'Gördüğüm her kadın bir parça senden Biri kaşın, biri gözün, biri bakışın Her biri yakıyor beni derinden Biri sevdan, biri Aşk''ın, biri ateşi...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gordugum-her-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümsüzdür', 'hukumsuzdur-hurrem-yalcin-d1d9z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir hüzün anımda

eski İstanbul sokaklarında

yitirdiğim

göz yaşlarım 

hükümsüzdür...

bulan

insaniyet namına

atıversin

lütfen çöpe! 

09 Ağustos 2004', 'bir hüzün anımda eski İstanbul sokaklarında yitirdiğim göz yaşlarım  hükümsüzdür... bulan insaniyet namına atıversin lütfen çöpe!  09 Ağusto...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hukumsuzdur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-i-hsan-dinibutun-zynlf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah gözümde tatlı gülüşün

Saçların, kaşların, mahzun duruşun

Gece yatağımda, uykumda düşüm

Seni düşünerek bitiyor ömrüm

Her yeni günüme, inan senle başlarım

Besmele niyetine hep ismini anarım

Aşk''ı bir Tanrı''ya birde sana duyarım

Dönersen  Dünya''yı inan cennet sayarım

Sana olan Aşk''ımı işte böyle anlattım

İnan bana bir tanem hiç abartmadım

Senden başka kimseye böyle şeyler yazmadım

Senin için cehennemde seve seve yanarım', 'Her sabah gözümde tatlı gülüşün Saçların, kaşların, mahzun duruşun Gece yatağımda, uykumda düşüm Seni düşünerek bitiyor ömrüm Her yeni günüm...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayal-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemez', 'sevemez-abdullah-atay-mk64r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kelebekler çiçeği

dalgalar denizi

sevemez

seni sevdiğim kadar...

ağaçlar yaprağı

geceyi yıldızlar

sevemez

seni sevdiğim kadar....

melekler cenneti

ırmaklar ovayı

asla sevemez

seni sevdiğim kadar...

gül dalını

yağmuru topraklar

hiç sevemez

seni sevdiğim kadar...

şair şiirini

hiç mi hiç sevemez

seni sevdiğim kadar....

leyla mecnu’nu

ferhat şirin’i

inan ki sevemez

seni sevdiğim kadar....', 'kelebekler çiçeği dalgalar denizi sevemez seni sevdiğim kadar... ağaçlar yaprağı geceyi yıldızlar sevemez seni sevdiğim kadar.... melekler c...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevemez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-i-hsan-dinibutun-5fq1z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül kapımı kime açarsam

Fark etmiyor inan yerin dolmuyor

Kalbimi ne kadar Aşk''a zorlasam

Sevmiyor kimseyi, seni arıyor

Seninki boş bir umut derim kendime

Gidenler dönmezki boşa bekleme

Seni sevmeyeni, sende isteme

Dinlemiyor gönül, seni arıyor

Gönül bu, vurulmuş vazgeçmiyorki

Ne desem, ne yapsam, dinlemiyorki

Kollarında başkasını, istemiyorki

Girdiği her kalpte seni arıyor', 'Gönül kapımı kime açarsam Fark etmiyor inan yerin dolmuyor Kalbimi ne kadar Aşk''a zorlasam Sevmiyor kimseyi, seni arıyor Seninki boş bir umu...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulakların Çınlasın', 'kulaklarin-cinlasin-i-hsan-dinibutun-3h0rg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çınlasın kulakların, andıkça seni

Belki hatırlarsın eski günleri

Kaybettim sanma sakın, ben ümidimi

Yıllarca bekliyeceğim geri dönmeni

Uzun zaman oldu, hiç aramadın

Yanımdan geçtinde, dönüp bakmadın

Oysa her anımı ben, seninle yaşarım

Her gece hayalini sarar yatarım

Çınlasın kulakların, andıkça seni

Belki hatırlarsın eski günleri', 'Çınlasın kulakların, andıkça seni Belki hatırlarsın eski günleri Kaybettim sanma sakın, ben ümidimi Yıllarca bekliyeceğim geri dönmeni Uzun ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kulaklarin-cinlasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-*- D i y a r - ı...G u r b e t....!', 'd-i-y-a-r-i-g-u-r-b-e-t-metin-eser-87ole', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu diyar-ı gurbete, bir defa düşmeye gör,

Çeker seni ibrete, yaramı deşmeye gör,

Gelmeyen bir pişmansa, gelenin halini sor,

Vatan dediğim toprak, bana nasıl kokar sor.

Almanya’sı ne ise; Avustralya’sı da odur,

Akşam hüzün basınca, yak bir türkü de otur,

Memleketin ekmeği, buram buram tüter de,

Vatan dediğim toprak, deva olur her derde.

Ne anan var ne eşin, uzaktadır can bacın,

Beklersin bitsin işin, başına konsun tacın,

Çalışıp didinince, istersin paran olsun,

Vatan dediğim toprak, her dâim duan olsun.

Hasret kalırsın dosta, bir selâma muhtaçsın,

Minareden okunan, bir ezana muhtaçsın,

Mis kokulu bayrağa, yanıp ta eriyorsun,

Vatan dediğim toprak, rüyama giriyorsun.

Allah için üç kelâm, edebilmek uğruna,

Yüzlerce kilometre, dağları aşıyorsun,

Sonra gönül çoşupta, dostluk bağı uğruna,

Sarılıp telefona, neleri yaşıyorsun...

Özlem bitmiyor hiç de, hasret sönmüyor içte,

Bak görürsün o zaman, hele gurbeti iç de,

Her saniye büyüyor, yangını volkan gibi,

Vatan dediğim toprak, yürekte yangın gibi,

Ey dost anlamaz isen, hiç zorlama kendini,

Bu mananın ifhamı, aşar senin bendini,

Çıkarsan günün biri, vatanın sınırından,

Bu sözlerim geçmeli, mutlaka hatırından.

10.08.04 / Frankfurt', 'Şu diyar-ı gurbete, bir defa düşmeye gör, Çeker seni ibrete, yaramı deşmeye gör, Gelmeyen bir pişmansa, gelenin halini sor, Vatan dediğim to...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/d-i-y-a-r-i-g-u-r-b-e-t-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lola ya Mektuplar 1', 'lola-ya-mektuplar-1-baykal-kaanalp-jpkyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'henüz çok erkenken

sıcaklığın,kokun,güzelliğin

üzerime sinmişken

yazayım dedim sana

ilk mektubumu

herhangi bir ateşle

kavrulmadan

şekiller belirginleşmeden

neyi? nasıl? niçin? istediğimi

istemediğimi bilmeden

yazayım dedim

belki senin bu satırları

hiç okumayacak olman

biraz içimi burkuyor ama

olsun önemli olan benim

yazmam,seni yazmam

aslında seni yazabilir miyim? 

kalemim buna yeterli

gücü bulabilir mi? 

hiç bilmiyorum

ama en azından

deneyip görmeliyim

kalemimin gücünü

sana olan,tutkumu

yazabileceğimi görmeliyim', 'henüz çok erkenken sıcaklığın,kokun,güzelliğin üzerime sinmişken yazayım dedim sana ilk mektubumu herhangi bir ateşle kavrulmadan şekiller b...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/lola-ya-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayabildiklerimizi,Yaşadık İşte', 'yasayabildiklerimizi-yasadik-i-ste-baykal-kaanalp-t7b4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşayabildiklerimizi,yaşadık işte

vurdumduymaz sağır sultana bile

duyurduk çığırtgan sesimizi

sessizliğimizi bozan,şen şakrak

gülüşlerimizi saklamadık kimseden

kimseye gütmedik kin,husumet

paylaştık ne varsa aşka dair

aşk için,sevgi için,mutluluk için

taşımaya çalıştık yorgunluklarımızı

değerdi ama,değdi ama yorulduğumuza

ardından konuşmadık sevmediklerimizin

sevdiklerimizi biraz kıskandık ama

olsun,o kadar olsun,bu bile bizim

dostluğumuzu perçinler, koyvermez

boşluğa,boşlukta kalmaz anılar

yaşayabileceklerimizi,yaşadık işte

ertelemedik,kaçmadık,kaçırmadık

gözlerimizi,güzelliklere bakmaktan

sebeblerimiz vardı,üzüntülü hallerimizi

bile,yok etmek için,saklamak için', 'yaşayabildiklerimizi,yaşadık işte vurdumduymaz sağır sultana bile duyurduk çığırtgan sesimizi sessizliğimizi bozan,şen şakrak gülüşlerimizi ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasayabildiklerimizi-yasadik-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gelmeyecek', 'o-gelmeyecek-baykal-kaanalp-0py06', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bekle dedim gölgeye

ayrılırsan bir yere

kulağını bükerim

biliyorum o gelmeyecek

ama ben yine de beklerim

gönlümü gere gere', 'bekle dedim gölgeye ayrılırsan bir yere kulağını bükerim biliyorum o gelmeyecek ama ben yine de beklerim gönlümü gere gere...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-gelmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An', 'an-hakan-liman-oltnb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak geleceğim 

senin ellerinde şekillensin

Bırak geçmişim 

sıcak yağmurlarla silinsin

Bırak güneş bugün doğup 

bugün batsın

Anı yaşa sevgilim

Gülümse bulutlara..

Eylül 2000', 'Bırak geleceğim  senin ellerinde şekillensin Bırak geçmişim  sıcak yağmurlarla silinsin Bırak güneş bugün doğup  bugün batsın Anı yaşa sevgi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/an-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-hakan-liman-offxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman, 

      sana emrediyorum, dur! 

Sonsuzluğu yaşamalıyım artık

Çocukluğumu yitirmeden büyümeliyim

Zaman,

      sana yalvarıyorum, dur! 

Eylül 2000', 'Zaman,        sana emrediyorum, dur!  Sonsuzluğu yaşamalıyım artık Çocukluğumu yitirmeden büyümeliyim Zaman,       sana yalvarıyorum, dur!  ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sonsuzluk-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Nokta', 'i-ki-nokta-hakan-liman-jcrpe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deli çocuk yine uyanık

Çocuk yine sarhoş

Ve yine söz vermemesi gerektiğini bildiği halde verdiği sözleri

							tutmuyor..

Yine ağlıyor..

Yine sigara içiyor..

Gelecek kaygısı yok

Ertesi gün umurunda değil

Yarın diye bir şey yok..

Yarın gidecekler ve yarın gelecekler önemsiz..

Önemli olan bugün gidenler

		ve bugün gelenler..

Ne nokta koyuyor

	ne de üç nokta..

Hep iki nokta koyuyor cümlelerin sonuna..

Hüzün ve mutluluk arasında

Yaşam ve ölüm arasında kalmış

	o ikinci noktayı koyup bırakıyor..

Ne son sözü söylüyor

Ne de devamını bekliyor..

Her şeyde olduğu gibi,

-müzikte şiirde sahnede ve aşkta-

Yarım bırakıyor

Noktalama işaretlerini de..

İki nokta yetiyor ona..

Güçlü olduğunu sanıyor

Büyüdüğünü söylüyor

Ama yalan söylüyor..

Güçsüzler ve çocuklar ağlar..

Söylenmemiş şarkıları var

Yazılmamış mısraları cebinde..

Düzen içinde sıkışıp kalan bireylerse 

			onu anlamıyor..

Herkes ona küçük,

Her yer ona dar,

Her ses ona sessizlik geliyor..

Çölde bir kaktüs gibi yalnız

Ve istiklal caddesindeki sokak lambaları kadar

				gereksiz görüyor kendini..

Küfrediyor hayata..

Küfrediyor yalnızlığa..

Küfrediyor güneşe..

Aşka, kavgaya, dostluğa, barışa, kuşlara, vapurlara

	sosyalizme, faşizme, kapitalizme,

  	                            ve bütün  -izmlere..

“Ben varım” diyor

	gerisi boş..

Aile, okul, arkadaşlar boş..

Yaşanacak tek bir yer var

Orası için de erken daha..

Cenneti düşleyip cehennemlik yaşıyor..

Her şeyi biliyor

	bildiğini gizliyor..

Susuyor..

Sustukça ağlıyor..

Ağladıkça susuyor..

Sevilmek istiyor biraz,

Sevmek istiyor..

İlgi bekliyor..

O yalnız..

O mutsuz..

O korkak..

O boşlukta..

Boşluk onda..

	

Ekim 2001', 'Deli çocuk yine uyanık Çocuk yine sarhoş Ve yine söz vermemesi gerektiğini bildiği halde verdiği sözleri 							tutmuyor.. Yine ağlıyor.. Yi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/iki-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntiharsal Yaklaşımlar', 'i-ntiharsal-yaklasimlar-hakan-liman-p6s86', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çekiliyorum aranızdan

sizin yarattığınız dünyayı

size bırakıyorum

korkmayın

zararım dokunmaz size

tek başıma

sessizce gidiyorum

git

tim..

01.02.2002', 'çekiliyorum aranızdan sizin yarattığınız dünyayı size bırakıyorum korkmayın zararım dokunmaz size tek başıma sessizce gidiyorum git tim.. 01...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/intiharsal-yaklasimlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Creep -düzyazı-', 'creep-duzyazi-hakan-liman-6do6x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoktandır, bilmediği bir sebepten baş ağrısı çekiyordu. Sanki kafatasının içinde tamtam çalan yerliler vardı. Çektiği uykusuzluğu giderebilmek için bir dolu hap kullandı. Sarhoş olup sızabilmek için sabahlara kadar içti. Ama fayda etmiyordu. Sezgileri ona hayatın başka yerlerde devam ettiğini, insanların gülüp eğlendiğini ve artık dışarı çıkması gerektiğini söylerken, o ısrarla evden dışarı adımını atmıyordu. Bir buçuk ay olmuştu insan yüzü görmeyeli. Sakalları uzamış, zaten çirkin olan yüzünü iyiden iyiye kaplamıştı. Kafasında kurduğu binlerce senaryo yüzünden delirmek üzereydi. Ortada sorun yokken sorun yaratma konusunda oldukça becerikli ve istekliydi. Kirlenmiş ruhunu böyle temizleyeceğini düşünüyordu belki de. İnsanlardan kaçarak, saklanarak.. 

Günlerdir aynı şarkıyı dinliyor, önceden odanın bir köşesine yığdığı kepekli bisküviler sayesinde ayakta durabiliyordu. Bazen ayağa kalkıp kendi kendine konuşuyor, bazen de sahnedeki bir aktör gibi seyircilere bir şeyler anlatıyordu. Kül tablası niyetine kullandığı tencere ağzına kadar dolmuş ve odayı leş gibi kokutmuştu. Zaten küçücük olan pencerelerin tüm perdelerini kapattığı için gündüzleri sadece loş bir mor ışık giriyordu içeri. Geceleri ise tavanına yapıştırdığı fosforlu yıldızlarla avunuyordu. 

Yaşam ile ölüm arasındaki ince çizgi üzerinde yürüyen bir cambazdı o. Savaşı kaybetmiş ve bunu hazmedememiş bir komutan, aldığı yaralarla yaşamaya alışamamış bir gaziydi. Yüzüne kapanan kapıların sayısını unutmuş bir dilenci çocuk hüznüyle savurdu rüzgara, sakladığı sonbaharın küllerini. Hiçbir rüzgar üşütemezdi artık ellerini..', 'Çoktandır, bilmediği bir sebepten baş ağrısı çekiyordu. Sanki kafatasının içinde tamtam çalan yerliler vardı. Çektiği uykusuzluğu giderebilm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/creep-duzyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Şiir', 'bos-siir-hakan-liman-vybaj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bomboş her şey 

Sokaklar, evler, masalar boş

Yollarda ayak izlerim dururken 

Gökyüzü her zaman boş

Ellerim boş, kalbim boş, yatağım bomboş

Havada sanki bir tılsım var bugün

Rüzgar tüylerimi diken diken ediyor

Üşüdüğümü belli etmemek için

Elimi cebime de atmıyorum

Zaten cebim kalbimden daha boş

Yollar boş

Masalar boş

Kalbim boş

Cebim bomboş

Neden bilmem ama

Sinemada yanımdaki koltuk hep boş! 

24.10.98', 'Bomboş her şey  Sokaklar, evler, masalar boş Yollarda ayak izlerim dururken  Gökyüzü her zaman boş Ellerim boş, kalbim boş, yatağım bomboş H...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bos-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-hakan-liman-0h9az', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahnede bir çocuk var,

Tam ortada..

Bağdaş kurmuş oturuyor..

Gözleri faltaşı gibi açılmış

En arkadaki koltuğa bakıyor..

Ağlamıyor

Ama yanakları ıslak,

Üşümüyor

Ama dizleri titriyor..

Sen kalk o en arkadaki koltuktan,

Karanlığın içinde parla,

Yavaşça sahneye doğru yürü ve dur..

Tam sahnenin önünde dur..

Elini uzat ve çocuğu tutmaya çalış..

Onun örümcek ağı bağlamış ellerine,

Onun kırmızı yanaklarına,

Onun çatlamış dudaklarına dokun..

Sonra.. 

Sen de çık sahneye

Ve onu ayağa kaldır..

Çünkü ayakları üstünde duramaz sensiz..

Çabuk olun

Hadi selam verin

Perde az sonra kapanacak

Ve boş koltuklar sizi ayakta alkışlayacak..

16.12.98', 'Sahnede bir çocuk var, Tam ortada.. Bağdaş kurmuş oturuyor.. Gözleri faltaşı gibi açılmış En arkadaki koltuğa bakıyor.. Ağlamıyor Ama yanakl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oyun-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyit', 'beyit-hakan-liman-kn7cg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çengelli iğne günü yaşamayı seviyor

Sevinebilirsin küçük dostum, hayat şimdi başlıyor! 

18.12.98', 'Çengelli iğne günü yaşamayı seviyor Sevinebilirsin küçük dostum, hayat şimdi başlıyor!  18.12.98...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/beyit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah - Beyaz', 'siyah-beyaz-hakan-liman-ynmo6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah kirlenmeden önce beyazdı

Hiçbir renge karışmamış

Tertemiz bir beyaz..

Ufaklık küçük bir masal yazdı

Kırmızı yanaklarını ıslatacak kadar

Hüzünlü bir masal..

29.12.98', 'Siyah kirlenmeden önce beyazdı Hiçbir renge karışmamış Tertemiz bir beyaz.. Ufaklık küçük bir masal yazdı Kırmızı yanaklarını ıslatacak kada...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siyah-beyaz-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru İşareti', 'soru-i-sareti-hakan-liman-dhf4l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yol ne zaman bitecek

Ben ne zaman düşeceğim ayaklarının dibine

Ya da nereye kadar koşacağız birlikte

Yorulduğumda yardım edecek misin

Kan-ter içinde kalıp bir bardak su istediğimde

Benden korkup kaçacak mısın

Yoksa içimi serinletecek misin 

Bal rengi göz pınarlarınla..

Ayın on üçü Cuma günü

Merdivenin altından geçerken

Yanımda olacak mısın

Paylaşacak mısın bütün şanssızlıklarımı

Omzuna ihtiyacım olduğunu anladığında

Başımı cama yaslamama

İzin mi vereceksin

Yoksa kıyamayıp 

Kocaman bir kucak açacak mısın

Bu garibana..

Sahilde yalnız mı sayacaksın yatları

Yalnız mı üşüyeceksin teras cafe’de

Yoksa bir telefon açıp

“Sana ihtiyacım var çengelli iğne”

Diyecek misin

Keş parkta salıncakları boş görünce

Beni hatırlayacak mısın

Yazdığımız yazıları okuyacak mısın uzun uzun

Apartman girişindeki soğuk merdivenlere

Oturacak mısın yine

Caminin önündeki bankta

Yaşlı amcalara selam verecek misin

Yanında olsam da

Uzaklarda olduğumu bildiğin halde

Razı olacak mısın damla damla erimeme

Yoksa elini uzatıp 

Ayağa kaldıracak mısın sahnedeki çocuğu

Yine karmaşık şiirler yazacak mısın bana

Yoksa yeni sevgililerine yazdığın şiirleri mi okuyacaksın

Kulağının pasını silmek için

“Fırt Emin”i isteyecek misin

-belki o zaman gitarım da olur-

Sen de benimle birlikte söyleyecek misin

Bağıra çağıra

45likte çekecek miyiz kafaları

Ortalığı dağıtacak mıyız

Sonunda sarhoşluğumuza verip her şeyi 

Lafı fazla uzatmadan

Son kez “seni seviyorum” bile demeden

Susacak mıyız? ? ? 

05.01.99', 'Bu yol ne zaman bitecek Ben ne zaman düşeceğim ayaklarının dibine Ya da nereye kadar koşacağız birlikte Yorulduğumda yardım edecek misin Kan...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/soru-isareti-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel -Mavi Kuş-', 'gazel-mavi-kus-hakan-liman-2rlgq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzüyle dertleşmeyeli konuşmayı unutmuşum, besbelli

Yenilgiyi kabullendiğimden beri okşayan yok gözlerimi

Sevmeyi öğrenemediğim gibi sevilmeyi de beceremedim

Boşu boşuna yazdım belki okumakla eskimeyen şiirlerimi

Ne insanı sarhoş eden bakışlarını unutabildim

Ne de yalnız gecelerde sıcaklığını özlediğim ellerini

Mavi bir kuş olup gökyüzünü bulutlardan çaldım

Bir avcı beni vurdu, siyaha boyadı tüylerimi

Artık eskisi gibi ölümüne sevemez oldum

Kapkara bir toz bulutu kapladı kalbimin üzerini

Kaf Dağı’nın ardındaki aksakallı bilgini bir bulsam

Belki de o öğretir bana sevginin gizemini

Paylaşmaksa esas olan, o paylaşır benimle

Zeytinini, ekmeğini, hatta yaşama hevesini

Ondan bir sihirli lamba alıp dönsem İstanbul’a 

Tıpkı bir masal gibi, tıpkı bir rüya gibi

Rüyada olduğumu bildiğim halde cinimden istesem

Onun gözlerini, onun ellerini ve mavi tüylerimi

17.02.99', 'Gökyüzüyle dertleşmeyeli konuşmayı unutmuşum, besbelli Yenilgiyi kabullendiğimden beri okşayan yok gözlerimi Sevmeyi öğrenemediğim gibi sevi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gazel-mavi-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yalın Hali', 'askin-yalin-hali-hakan-liman-l1av5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke yaşamak zorunda olduğumuz aşk

Yalın halde olsaydı..

AŞKI sorgulamadan,

Olduğu gibi sevseydik..

AŞKA hiçbir şey karıştırmadan

Özünü bulabilseydik..

AŞKTA yalan dolan yoktu sözde,

Keşke biz doğruları bilseydik..

AŞKTAN hiçbir beklentimiz olmadan

Yalnızlığı da aşkın parçası görseydik..

Sadece üç harf yetiyor anlatmaya

Sade ve yalın

AŞK..

07.04.99', 'Keşke yaşamak zorunda olduğumuz aşk Yalın halde olsaydı.. AŞKI sorgulamadan, Olduğu gibi sevseydik.. AŞKA hiçbir şey karıştırmadan Özünü bul...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-yalin-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendiliğinden', 'kendiliginden-hakan-liman-rkznj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sihirli bir yolculuk başlıyor

Uzak ve nemli iklimlere doğru

Yalnızlığa alışmayı öğrenecekken

Her şey kendiliğinden oldu..

Kırmızı, sarı, pembe, beyaz

Ne kadar gül rengi varsa hepsi aklımdaydı..

Ve ayın en güzel hali dolunay

Işıklarını bana sundu sessizce..

İnsanlar sustu

Kuşlar sustu

Gitarlar, kemanlar, neyler sustu kendiliğinden..

Gözler hissetmeyi,

Dudaklar görmeyi,

Eller konuşmayı öğrendi kendiliğinden..

Savaş çocukları gülümsemeye,

Yağmur damlaları ısıtmaya,

Komedi oyunları ağlatmaya başladı kendiliğinden..

“Her şey birdenbire oldu,

Gökyüzü birdenbire

Yollar, kırlar, kediler, insanlar birdenbire..”

Böyle diyorsa şairlerin en aşığı,

Aşıkların en garibi Orhan Veli,

Mutlaka bir bildiği vardır.

Yalan değil, birdenbire..

16.05.99', 'Sihirli bir yolculuk başlıyor Uzak ve nemli iklimlere doğru Yalnızlığa alışmayı öğrenecekken Her şey kendiliğinden oldu.. Kırmızı, sarı, pem...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendiliginden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-hakan-liman-pghpn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep ilk gelen olmak

Yalnızlığı getirir yanında..

Bu yüzden sen

Ellerinde kan,

Tırnaklarında toprakla çıkacaksın oraya..

Yanında diğerleri,

Kendin gibiler olacak..

Zirvedeyken 

Yeryüzü ayaklarının dibinde

Ve ustanın sözü kazınmış olacak beynine:

“Yaşamak bir ağaç gibi tek ve hür,

Ve bir orman gibi kardeşçesine..”

04.11.99

Nazım Hikmet Ran’ın anısına..', 'Hep ilk gelen olmak Yalnızlığı getirir yanında.. Bu yüzden sen Ellerinde kan, Tırnaklarında toprakla çıkacaksın oraya.. Yanında diğerleri, K...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usta-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvallahhh... kader', 'eyvallahhh-kader-nevin-kurular-rp54a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep bir yanı eksik, bir yanı tamam

Böyle sevmeliyiz hayatı belki..

Gülü Dikeniyle sevdik eyvallah.......

Gülsüz dikenlerle   sarma yeterki....', 'Hep bir yanı eksik, bir yanı tamam Böyle sevmeliyiz hayatı belki.. Gülü Dikeniyle sevdik eyvallah....... Gülsüz dikenlerle   sarma yeterki.....', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eyvallahhh-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bir GÜN yar', 'bir-gun-yar-baykal-kaanalp-opefu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yıllar yılı sabırla bekliyorum

yağacak diye üzerime kar

sevinçlerimi birbirine ekliyorum

gelecek diye bir gün yar', 'yıllar yılı sabırla bekliyorum yağacak diye üzerime kar sevinçlerimi birbirine ekliyorum gelecek diye bir gün yar...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gun-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünde Gençliğin', 'dusunde-gencligin-ahmet-aksoy-5gqd1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızlığınla, buluştuğunda yüreğin

acılar tarihidir tenin

adeta kan sıkışır, içinde belleğin

geçer gider gözünden, geçmişin

omuzların erir, karlar gibi ilmin

açılır düşünde, cehennemin

nerededir eskiden, çağlar sevdiğin

tutulmaz bir kordur, gençliğin

ağlayan ömründür, kaybettiğin

kapını bekler, hiç beklemediğin

anlarsın yıkılarak, boşdur ellerin

solan gün, tarihidir tenin', 'yalnızlığınla, buluştuğunda yüreğin acılar tarihidir tenin adeta kan sıkışır, içinde belleğin geçer gider gözünden, geçmişin omuzların erir,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusunde-gencligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Dağbaşları', 'yuregin-dagbaslari-adnan-durmaz-u3rlu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güz kanadı

bir hazin şarkıya kesti hazan

düşürülmez bir çırpıda

bir yaprak değil bu insan

şimdi neler söylesem

ateş kesilir dizeler

şimdi neler söylesem

kanayan bir yüreğin dağbaşlarından

aydınlığa koşan doludizgin atlılar

karanlığın hendeklerini atladılar

yalın yürektiler

çığ kalemdiler

som ışıktılar

öyle pervaneler ki 

yüreklerinde ışık damıtırdılar

yakıldılar yıkıldılar kapaklandılar

bir düş gibiydiler

bu vahşet çölünde gül açan

dedik ki 

geçsin son bahar

yüreklerin dalında açan güller düşmesin.

sevgilerle örtün sevgilerle örtün

güvercinim

yüreğimin yarası 

üşümesin... 

adnan durmaz,bilirsin aşk da serseri,art yay,ank', 'güz kanadı bir hazin şarkıya kesti hazan düşürülmez bir çırpıda bir yaprak değil bu insan şimdi neler söylesem ateş kesilir dizeler şimdi ne...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuregin-dagbaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Issızda Gül Kokusu', 'col-issizda-gul-kokusu-adnan-durmaz-a4bo3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi yüreğinin en dibindeki yaraları göster bana 

Bana en derin kıvrımlarını 

Belki istediğin yanıtı veremem sorularına 

Belki sözcüklerimdeki gizem 

Teselli olmaya yetmez acılarına 

Ama paylaşmanın tadını yaşarız birlikte 

Sevincin parmak uçlarında kalan tozunu 

Acıyı paylaşmanın tuz tadını... 

Acının bile tadını almak 

Yaşamaktır 

Bilirsin bunu... 

Yıldızsız yalnızlıklarınla yaslan 

Çöl ıssız yalnızlıklarımın hasırına 

Birbirimizin yüzlerini okuyalım 

Yürek çizgilerimizi çözelim susarak 

Evet acıyım- yaralıyım- kan içindeyim 

Sevinçleri- umutları korumak için 

Direnmenin bedeli değil mi senin de acın 

Sevdayı ve yaşamı 

Sürekli keşfetmenin ataklığı değil mi 

Yalnızlığın senin de... 

Kimi zaman bilinmeyen bir dinin 

Görülmemiş dervişinin akılalmaz sabrını 

Bir biz taşıdık... 

Kimi zaman tüm dinler kovdu bizi 

Sorguladık durmaksızın ne varsa 

Dünyayı sonsuzda 

Zamanı bir anda 

Yaşamı ölümlerde 

Sevdada kavgayı sorguladık 

Kendisiyle bizim kadar hesaplaşan 

Başka bir sorgucu olmadı... 

Kuşkusuz 

Yarın başka bir ayrılıktır bu günden 

An andan ayrılıktır 

Soluk soluktan 

Yarın başka bir rüzgâr savurur seni 

Beni başka bir rüzgâr 

Derler ki: tüm maceralar 

Ayrılıklarla başlar 

Gel 

Ayrılıklardan söz edelim bu akşam 

Susalım 

Bizim ayrılıklarımızı sözcükler tanımlamaz 

Sözcükler anlatamaz özlemlerimizi 

Tıpkı bir dua gibi 

Suskun geceler gibi susalım 

Susarak konuşmayı biz kadar 

Başka kim bilebilir... 

Bakışlarımızda kavgalar- yenilgiler 

Yangın yerleri Fırtınalar 

Batan gemiler 

Yüzümüzde çizgi çizgi 

İnsanlık tarihince yazılan onca keder... 

Zulanda giz edip gizle yüzünü 

Acını coşkularla bastırmak isteyince 

Açıp açıp oku bakışlarımı 

Tıpkı benim yapacağım gibi 

Kimi zaman işkencede buluştuk 

Kimi zaman zindanda- darağacında 

Elbet gene buluşuruz 

Belki kavga- belki sevda 

Ama mutlaka coşkuda 

Yaşamın anlamı coşkuda... 

Adnan DURMAZ 

30.03.1992 

 fısıltılarla da olsa söyle,saypa yay,ank', 'Hadi yüreğinin en dibindeki yaraları göster bana  Bana en derin kıvrımlarını  Belki istediğin yanıtı veremem sorularına  Belki sözcüklerimde...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/col-issizda-gul-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Rahat Ol Ay Yüzlüm', 'sen-rahat-ol-ay-yuzlum-karahan-yilmaz-s0yio', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gemi demir atmazdı her limana böyle

Zaman trenleri durmaz oldu artık içimde

Sen rahat ol ay yüzlüm, ben beklerim

Seni beklemek mutlulugun diğer adı belkide..,

Aradım durdum seni günlerce şiirlerde

Adresim oldu imgelerin, sustum kelime kelime

Sen rahat ol ay yüzlüm, ben beklerim

Aşka verilmiş bir sözdü, bu gece gülüşün bende

Zaman aramızda bir düşman gibi dursada

Ağustos kuşları gibi kondun bu gece dallarıma

Sen rahat ol ay yüzlüm, ben beklerim

Okuduğum son romanlar aşkımızı anlatmasada..

Her aşkta insan kendini arar mutlaka

Her sevgili bir aynadır, aşk adlı bu oyunda

Sen rahat ol ay yüzlüm, ben beklerim

Son tren gelmesede bu akşam bu istasyona..

10 ağustos 2004', 'Bu gemi demir atmazdı her limana böyle Zaman trenleri durmaz oldu artık içimde Sen rahat ol ay yüzlüm, ben beklerim Seni beklemek mutlulugun...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-rahat-ol-ay-yuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanatın eline düşen virane', 'sanatin-eline-dusen-virane-akin-akca-3tj7r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I. 

Öyle dolu ki, şekilli korunmak: 

Durup düşünüyorum ve durduğum yerde, 

Toprak attım üç yüz on küsur bin dönüm, 

Hatayla dolu, ama suçla değil: 

Onun etrafında dört dönüyor, 

Işıldayan bahçemizi suluyorum. 

Tehdit karşılığı tetiklemeyen tehditler 

Ve karşılık bulabilenler, zaman geçtiğinde. 

O kadar düşündüm, bu şiddette; 

Ne yaptığımı bulamadım! 

Ve yanaşma çabalarımda -

Uğraşımın yakalanışımın- “nadiren hepsi’nde”; 

Çalıştım, tehdidi altında gölgesinin; 

Ensemde, jandarmanın ve bir sefer korktum. 

Arkana bile bakmadığın apartman sahanlığında; 

Bir an içinde parti konuklarına veda edip; 

Hızlıca çelik merdivenden çıkıp 

Beklemeksizin boşluğa kendini atıveren; 

Bir celse var, ‘toprak-tükürmez’i 

II. 

İçime kapandım yine. 

Ama bu midye çok vasıfsız. 

Onun kabuğu, bir salyangoz gibi; 

Pek kutsal bir tozlu yol, sarmal. 

İnsan içinde, insanlar. 

Otururken bakarlar, bakmadan. 

Kalkarken, bakarlar: 

Soramazlar, bilirler. 

* 

‘Kutsal-sarmal’ için bir çarşaf gerildi. 

Gülle için gelmedi ‘kutsal-sarmal’; 

Çarşafa atılsın diye, gülle - 

Kara delik’te. Vardı ‘kutsal-sarmal’. 

...''Kutsal-sarmal'': Ayrıcalık adına, 

...Değil; değil, ''dair bulunma''ya 

...Sırf var olmak için: 

...Öyle oldu, kendisi ki; 

...İçindekileri, dereceleri, unuttu. 

- 

10 Ağustos 2004 

Zarf yırtıldığında, pul yerli yerinde duruyorsa; yırtılan şafakların, dönme dolap günbatımlarına kazandırdıkları hiçbir şeydir..', 'I.  Öyle dolu ki, şekilli korunmak:  Durup düşünüyorum ve durduğum yerde,  Toprak attım üç yüz on küsur bin dönüm,  Hatayla dolu, ama suçla ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sanatin-eline-dusen-virane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 4', 'yalnizligin-ote-yakasi-4-karahan-yilmaz-s6a0e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '4

Yeni bir aşka davetiye çıkardım

Düştü tetiği kalbimin, pusulasız kaldım

Sensiz her günüm,bir yıl gibi geçti

Liman oldu hasretine hayatım...

 5

Yaslanınca dün gece sevdana kalbim

Bir kurşun gibi fırladı yerinden gözlerim

Seni sevmenin sevmek olmadığını bilseydim eğer

Severmiydim seni hiç böyle pervin.

6

Oysa nereye gitsem yanımda sen

Düşmüyor aşkın ve adın dilimden

Sensizliğe mahkum olsamda farketmez

Silemezler artık seni belleğimden..

7

Ütülü iki gömlek gibiydik aynı askıda

Aynı trende yolcuyduk, aynı uçakta

Aynı buluttan geçer, aynı boşluğa düşerdik

Aynı romanı okurduk, aynı şiirde masum bir imge

Aynı şarkıyı söylerdik, israrla ikimizde.', '4 Yeni bir aşka davetiye çıkardım Düştü tetiği kalbimin, pusulasız kaldım Sensiz her günüm,bir yıl gibi geçti Liman oldu hasretine hayatım.....', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 5', 'yalnizligin-ote-yakasi-5-karahan-yilmaz-5u81o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '8

İçimdeki şeytan soyunuyor

Sensizlik zil takmış oynuyor

Pervin aşkın bende bir deprem

Bu aşk artık sensiz olmuyor..

10

Işıkları sönmüş bir şehir gibiyim

Bekle bir sabah ansızın çıkar gelirim

Gözlerin sabırsız bir yanardağ gibi sussada

Biliyorum yenik düşecek aşkına kalbim.

11

Akşam oldu tenhalaştı yine sokaklar

Bir kadın oturmuş gözlerimde saçlarını tarar

Her akşam bir başka şarkı söyleyen bu rüzgar

Elbet bir gün bizim şarkımıza da başlar.', '8 İçimdeki şeytan soyunuyor Sensizlik zil takmış oynuyor Pervin aşkın bende bir deprem Bu aşk artık sensiz olmuyor.. 10 Işıkları sönmüş bir ...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 7', 'yalnizligin-ote-yakasi-7-karahan-yilmaz-zqvxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '12

Hani ellerin bir orman gibi susardı

Hani gözlerin yeşil bir felaket saçardı

Oysa zamansız başlayan bir fırtınaydık

                                           -seninle-

Kendi denizini arayan iki ırmak belkide.

13

Hangi hüzün anlatabilir seni

Hangi rüzgar, hangi yağmur

İşte yeni bir aşka daha başlıyorum

Kalbimin terasında  bir yer bul ve otur.

14

Kalbim bu şehirde unutulmuş eski bir sokak

Biliyorum bu gece seni düşünmek bana yasak

Gözlerin bir orman gibi yeşil yeşil sussa da

Uzak dur benden bu gece, hemde çok uzak.

15

Dağlarında zamansız esen bir rüzgardım

Gönül sarayında kendime bir yer aradım

Sahibi olmak şöyle dursun ya pervin,

Kalbine bir günlük kiracı bile olamadım..', '12 Hani ellerin bir orman gibi susardı Hani gözlerin yeşil bir felaket saçardı Oysa zamansız başlayan bir fırtınaydık                       ...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 8', 'yalnizligin-ote-yakasi-8-karahan-yilmaz-uwsw8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerde dursam orda bir kadın ölecek

Bu şehir susacak, sen susacaksın! 

Savcılar sicilime bir suç daha ekleyecek

Sen yine susacaksın, bu şehir intihar edecek

17

Sevdan içimde kaybolan eski bir şehir

Sevmek bu şehirde yaşadım diyebilmektir

Hüznün terasında sessizce beni beklerken

Kimbilir gözlerinde kaç ayrılık kurşuna dizilmiştir.

20

Gözlerinde derin uçurumlar gibi bekledim

Ben hâla bıraktığın yerde, bıraktığın gibiyim

21

Başımın üstünde aksaçlı bulut

Aşkımız için bir dilek tut

Söyle beklesin gözlerin beni

Yoksa çıldıracak içimdeki umut.', 'Nerde dursam orda bir kadın ölecek Bu şehir susacak, sen susacaksın!  Savcılar sicilime bir suç daha ekleyecek Sen yine susacaksın, bu şehir...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 9', 'yalnizligin-ote-yakasi-9-karahan-yilmaz-9egdl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '28

Biz bu insanları anladıkta,

Bu insanlar bizi anlamadı pervin

Aşkımız zamansız başlayan bir yolculuktu

Söyle beklemesin boşuna beni gözlerin.

31

Sensizliğin kollarında uyusamda

Yine sen düşüyorsun aklıma..

32

Duruşunu aşkımızın bir şifresi gibi kullan

Bir seher yeli gibi es sıra dağlarımda

Bırak düşlerin sevda ağaçlarımda asılı kalsın

Aşkı beklesin yeşil gözlerin kalbimin avlusunda 

12 mart / 22 Aralık 2001- Metz', '28 Biz bu insanları anladıkta, Bu insanlar bizi anlamadı pervin Aşkımız zamansız başlayan bir yolculuktu Söyle beklemesin boşuna beni gözler...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 1', 'yalnizligin-ote-yakasi-1-karahan-yilmaz-kpyy0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzadıkça uzuyor aramızdaki gri zamanlar

Ne sen farkındasın bunun, ne de dışardaki rüzgar

Oysa birlikte ayartmıştık seninle ayışığını,

Birlikte susmuştuk; susunca içimizdeki martılar...', 'Uzadıkça uzuyor aramızdaki gri zamanlar Ne sen farkındasın bunun, ne de dışardaki rüzgar Oysa birlikte ayartmıştık seninle ayışığını, Birlik...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Çalı', 'kor-cali-orhan-tuncay-yymel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çöl rüzgarıdır seni savuran ey kör çalı

Sonsuzluğa o üfürür yitik ruhları

Kum tepelerini sarsar tüm heybetiyle

Sonsuz ufuk şimdi kum tanecikleriyle kapalı

Kardeştirler yitik ruhlarla yalnız ruhum

Çöl fırtınaları içer derin susuzluğum

Alın beni de koynunuza fırtınalar

Şu kör çalı kadar körelmiş doyumsuzluğum', 'Çöl rüzgarıdır seni savuran ey kör çalı Sonsuzluğa o üfürür yitik ruhları Kum tepelerini sarsar tüm heybetiyle Sonsuz ufuk şimdi kum tanecik...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kor-cali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Öte Yakası 10', 'yalnizligin-ote-yakasi-10-karahan-yilmaz-l7cy8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzel şey canım

Bir şiirde ilk dize olmak

Sonra yasak bir imge gibi

Şiirin kollarında uyumak..

Seni şiirlerime almasaydım

Bu aşk bitmezdi belki böyle

Seni bir türkü gibi sevmeseydim

Sesin adres olmazdı sesime..

Sevdanı

Kalbimin duvarına

Surrealist bir tablo gibi asıyorum

Yasak bir şiir kitabı gibi

              okuyorum şimdi seni

Biterken temmuzun son günleri

Biliyorum seni anlatacak aşka dair sözlerim

Ve seni bekleyecek; 

Meçhul asker anıtı önünde

                       meçhul bir asker gibi.', 'Ne güzel şey canım Bir şiirde ilk dize olmak Sonra yasak bir imge gibi Şiirin kollarında uyumak.. Seni şiirlerime almasaydım Bu aşk bitmezdi...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizligin-ote-yakasi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç buzul dağının zirvesindeki kardelene...', 'uc-buzul-daginin-zirvesindeki-kardelene-ahmet-ferit-cosan-8kqqy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'herşeyin bir anda yitip gitmesi acı verir,

acının bile...

ve çözülür, dağılıveririm kara gecede

yürekler burkan bu gerçeğimle.

tozlarımın arasından 

renkler kadar samimi bakarım sana,

rüzgar kadar fütursuz okşarım saçlarını,

yitişim bayram olur yudumladığım her bir zaman zerreciğinde.

üzülürüm, ''aşk bu işte, kavuşamamak'' derim.

herşeyin bir anda yitmesi acı verir sevdiceğim,

seviyorum dediğin bir garip sızlanmadır sadece

yitip de gidenin ardından.

aşkın kızılı yok bu sessiz serzenişlerde,

kardeş denizlerimin içtiği misal, umudun mavisi yok.

uğraşsan, bir yakamozluk ışık dahi havalanamaz

adına sevmek dediğin bu avunmanın bağrından.

bırak mezarı olsun geceler,

ardında bıraktığın sahipsiz aşkıma,

ve rengarenk kelebekler havalansın

gecemde açmış çiçekler olan biçare mısralarımda...', 'herşeyin bir anda yitip gitmesi acı verir, acının bile... ve çözülür, dağılıveririm kara gecede yürekler burkan bu gerçeğimle. tozlarımın ar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uc-buzul-daginin-zirvesindeki-kardelene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Periler Fısıldasın Adını', 'periler-fisildasin-adini-t-l-n-ayse-kayi-6qv9i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En ucuzundan ne varsa al.

En sevmediklerini bırak yanı başıma...

Sıkıldın mı yaşamaktan, beni ölüm say; 

Düş kollarıma! 

Kederleri yakalım yağmur sussun,

Umutları biriktir kaşla göz arası...

Seril toprağa yaprak düşsün,

Beni mevsimlerden hazan say.

Şarkılar çalalım dünya duysun,

Çakıl taşlarını öğütsün deniz,

Bir kerecik unut gitsin,

Dün hiç olmamış say.

Masallar anlat devleri olmasın,

Periler fısıldasın defalarca adını 

Pabuçlarım camdan değilmiş,

Giydir gitsin ayaklarımı...

Titret mumları sönsün ışık,

Sevişmekse tenleri karıştırma işine,

Vuruldukça sevinçlerine,

Hüzün hiç doğmamış say!', 'En ucuzundan ne varsa al. En sevmediklerini bırak yanı başıma... Sıkıldın mı yaşamaktan, beni ölüm say;  Düş kollarıma!  Kederleri yakalım y...', ARRAY['Türk Edebiyatı','Şiir','Tâlân Ayşe Kayı']::text[], 8.5, '{"poet":"Tâlân Ayşe Kayı","poet_slug":"t-l-n-ayse-kayi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/periler-fisildasin-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikaha Davet', 'nikaha-davet-meral-yagcioglu-rszw5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar önce ayrılmıştık

Dost, arkadaş kalmıştık

Bir iki telefonla konuştuk

Tesadüflerle karşılaştık

Merhaba ile geçiştirdik

Sonra, yıllar uzun yıllar

Birbirini kovaladı

Hiç görüşmedik

Hiç aramadık

Bitmişti artık

Duygularımızsa yürekteki

Çöp kutusunu mekan seçmişti

Sıkı  sıkı kapanmıştı üstü

Sızdırmıyordu kokusunu 

Yıllar sonra rastladım

Evlenmemişti

Bense yeni bir mutluluk yakalamıştım

Evlenmek üzereydim

Bu rastlantıya

İkimizde sevindik aslında

Parmağımdaki yüzüğü

Gösterip nikaha,

Nikahıma davet ettim 

Birden sarsıldı bedenim

Kan beynime sıçradı

Yüreğim koşar adım atmakta

Ama gün alınmıştı bir kere

Caymak mı asla olmazdı.

O da farkındaydı her şeyin

Allak bullaktı yüzü 

Buruk bir tebessümle

Gelirim dedi içten

Son bir kez bile olsa

Gelinlikle görmek için 

”Gelirim elbet”', 'Yıllar önce ayrılmıştık Dost, arkadaş kalmıştık Bir iki telefonla konuştuk Tesadüflerle karşılaştık Merhaba ile geçiştirdik Sonra, yıllar uz...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/nikaha-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Treni', 'hayat-treni-burak-killioglu-j7gd7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni bir gün

Yine aynı tekdüzelik.

Takvimin yaprağından başka

Her şey eskisi gibi.

Hayattaki tek istikrarlı yönümüz,

Dünden yarına aynı kalan günümüz.

Ruhlarımız gibi umutlarımız da ölgün...

Daha ilk ışıklarında yitip giden gün...

Geçmiş günlerimizin

Ve birbirimizin kötü tekrarlarıyız.

Her yanımızda aynılaşmış yüzler,

Günleri bile aynı yüzsüz bedenler...

Farklılığımızken tüm zenginliğimiz,

Kendi ellerimizle günden güne

Fakirleşmişiz.

Yine de,

Aynı olmamalı her şey, aldanmamalıyız.

Her insan gibi

Her gün de farklı birbirinden.

Aksi halde, ilk istasyonda inmeli

Bu hayat treninden.', 'Yeni bir gün Yine aynı tekdüzelik. Takvimin yaprağından başka Her şey eskisi gibi. Hayattaki tek istikrarlı yönümüz, Dünden yarına aynı kala...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-treni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıraya Girmeyen Sıradan İnsan', 'siraya-girmeyen-siradan-i-nsan-oguzkan-bolukbasi-zhst4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıraya girmeyen sıradan insanların koşuşturmaları

gibidir bulutları kucaklamak……………..

Kanatsız kuşlar uçar mı dersin, öyle bir şey işte 

Gökyüzü vazgeçilmez heves her düşüşte

Hangi dolduruşun cahil cesaretinde gördüm seni

Ve sevdim 

O alaycı gülüşlerini

Belki her gördüğünü çalan gözlerindi sebebim

Kleptoman diyeceğim 

ihtiyaçsız 

mülkiyet tutkunu 

tetikleyen o orospu ruhunu……………..

Kendime bahaneler aramıyorum

Her ışığın talibiyim

Sevdanın talebesi

Yıllardır aynı sınıfta döne döne

Basmaya çalışıyorum gölgeme

Sıraya girmeyen

Sıradan bir insanım

Hiç gıpta ettiniz mi bir sokak serserisine

Vurdum duymaz

Acılardan arınmış

Mülkiyetsiz

Hiç

Oysa bu piç olmuş alemde

Var olmak dediğin ne

Bir sevdaya dolanmak sadece

Kırılıyor ışıklar

Prizmasında hayatın

Gördüğümüz yedi renk

Görmediklerimiz bizi alıp götürecek

Sen de götür buralardan beni

Ve hatta yut

Kara deliklerde yok et

Veya kollarında uyut diyeceğim

Basit kaçacak bunca deneyimden sonra

Bilinen frekanslarda yayın yapmak

Üç kızıl ötesindeyim

Sen mor ötesinde kaldın

İkimiz de görünmez olduk

Şimdi kuantum atlamalarının zamanı

Dayanabilir misin

Şiddetine yaklaşmaların

Bir füzyon tepkimesinde

Güneş olmaktır maksadımız

Yani sürekli yanmaktır

İşte tüm bunlar

Sıraya girmeyen

Sıradan bir insanın koşuşturmasıdır

Yani

Nafile ……………….', 'Sıraya girmeyen sıradan insanların koşuşturmaları gibidir bulutları kucaklamak…………….. Kanatsız kuşlar uçar mı dersin, öyle bir şey işte  Gök...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/siraya-girmeyen-siradan-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zzzzz / araP lı Şiirler', 'zzzzz-arap-li-siirler-bir-mim-kemal-ertugrul-mdo5g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '! ..araP*

Hiç bile değildi para

Ne zaman

Herşey oluverdi bir ara

Herşey hiç oldu

Paradan maada..! 

ENFLASYON*

Para var mal var

Alabilirsen al malı

Alabildiğin kadar

Lakin para çok

Değeri nerde..? 

STAGFLASYON*

Mal var para yok

Anlamadım gitti

Ne menem bi''şeydir şu

Adına ekonomi dedikleri

Hem para yoktur

Hem de değeri..! 

*Akrebin Kuyruğundan Damıtılmış Yeşil(şiirler) 

'' Stagflasyon; son 30 yıldır ekonomi terimleri arasına katılmış olan,enflasyon içinde durgunluk anlamında kullanılan bir sözcük..!', '! ..araP* Hiç bile değildi para Ne zaman Herşey oluverdi bir ara Herşey hiç oldu Paradan maada..!  ENFLASYON* Para var mal var Alabilirsen a...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zzzzz-arap-li-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-mustafa-yigit-morpheus-kyd7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bundan Aylar Öncesinde

Duygusuz Bir Kalp Taşırdım

Hiç Kimseyi Sevmeden

Serserice Yaşardım

Sevmezdim Hiç Kimseyi

Hep Hayatımı Yaşardım

Ağlayanlara Aldırmaksızın

Feryatları Duymaksızın

Neşeme Neşe Katardım

Birgün Sen Çıktın Karşıma

Öyle Masumca,

Öylesine Hislice

Taş Kalbim Parçalandı Sanki

Yerinden Fırlayacaktı

Yaşayamam Dediğim Duyguları

Yıllardır Unuttuğum, Kıskandığım

Duyguları 

Artık Ben Yaşar Oldum

Yıllardır Küllenmiş Hislerimin

İçimde Bir Yerlerde

Kırıntılarını Bularak

Gönül Sevdamı Yakaladım

Taş Kalbimi Parçaladım

Mutluluğa Gidiyorum Sandım

Oysa, 

Oysa Ne Kadar Da Yanılmışım

Yıllardır Benim Yaptıklarımı

Şimdi Sen Bana Yapıyorsun

Beni Böyle Avare, 

Beni Böyle Divane

Bırakıp Gidiyorsun

Sevdiğim, Birtanem

Nar Tanem, Can Parem

Canımda Can Bildiğim

Dünya Üç Günlük Dünya

Madem Geldik Yaşamaya

Şu Yalan Dünyada

Değermi Kalp Kırmaya

Gel Birlik Olalım

El Ele Verip, Göklere Uçalım

Mavi Bizim Rengimiz Olsun

Göklerde Yuvamız

Özgürce Yaşayalım Hayatı

Sevipte Ayrı Kalmak 

Ne Kadar Zormuş Yarabbim

Öldürüyor İnsanı

Ben Bu Çileyi Tattım

Kimse Tatmasın İstiyorum

Kırdığım Bütün Kalpler

Hepinizden Özür Diliyorum

Ey Güzel İnsanlar

Hepinize Mutluluklar Diliyorum

Ben Yine Eskisi Gibi

Kendi Yuvama

Yalçın Dağlara Gidiyorum.

 Mustafa Yiğit (Morpheus)', 'Bundan Aylar Öncesinde Duygusuz Bir Kalp Taşırdım Hiç Kimseyi Sevmeden Serserice Yaşardım Sevmezdim Hiç Kimseyi Hep Hayatımı Yaşardım Ağlaya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/gidiyorum-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-hikmet-yakisir-ozwgy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günaydın aytanem

Sabah uyandırmaya kıyamadım seni

Başucuna bir gül koydum giderken

Yaprakları seni sarsın diye

Yanına kalbimi de koydum

Yalnız hissetmemen için kendini

Alnına da bir öpücük kondurdum giderken

Seni kem gözlerden korusun diye

Birde nefesimi bıraktım sana

Tenini okşasın diye

Günaydın…

09 Ağustos 2004', 'Günaydın aytanem Sabah uyandırmaya kıyamadım seni Başucuna bir gül koydum giderken Yaprakları seni sarsın diye Yanına kalbimi de koydum Yaln...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunaydin-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozuk Düzen', 'bozuk-duzen-hikmet-yakisir-dmbrv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokak çocukları aklıma geldi

Ekmek parası için bütün gün

Allaha emanet trafikte ölmeyi göze alarak

Bir ekmek parası uğruna

Peçete-sakız satmak için ağabeylerine

Cambazlık yapan çocuklar aklıma geldikçe

Canım sıkılıyor.

Sokaklarda kalan geleceğimiz aklıma geldi

Canları pahasına alın terleri ile

Kömür karası gözleri gibi iki zeytin

Ve kuru ekmekle karınlarını doyurdukları zaman

Sevinçten parıldayan gözleri ile

Nasıl mutlu oldukları aklıma geldikçe

Canım sıkılıyor

Sokaktaki Cumhuriyet bekçileri aklıma geldi

Yaz-kış demeden

Yağmur-çamur fırtına-tipi düşünmeden

İlk buldukları merdiven boşluğunda

Yada duvar dibinde korumasız yatan

Geleceğimiz olan yavrularımız aklıma geldikçe

Canım sıkılıyor.

Sokaklarda lüks arabalarla caka satan

Servetinde bir damla alın teri olmayan

Yetim dul fakirin hakkını çalan

Fütursuzca sınırsız savurganlık yapan

Vergi vermemeyi marifet sayan

Alçaklar aklıma geldikçe

Canım sıkılıyor.

Sokaktaki fakiri, işsizi, yetimi görmeyen

Hayali ihracatla, naylon faturayla devleti soyan

Banka hortumlayarak yetimin hakkını çalan

Marifetli beylere dokunmaktan korkan

Ama saçı açık, başı örtülü,

Türban giymiş, kıçını açmış tartışması ile

Boşa zaman kaybeden şerefsizler aklıma geldikçe

Canım sıkılıyor.

07 Ağustos 2004', 'Sokak çocukları aklıma geldi Ekmek parası için bütün gün Allaha emanet trafikte ölmeyi göze alarak Bir ekmek parası uğruna Peçete-sakız satm...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bozuk-duzen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne kadar Çoksun', 'sen-ne-kadar-coksun-muharrem-yilmaz-nguvs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEN NE KADAR ÇOKSUN

Yabancılaştığım hayat,

Gün geçtikçe

Bir yığın elem, bir yığın hüzün taşıyor.

Dört nala koşan atlılar geçiyor,

Göğeren yarınlarımın üzerinden.

Süngüler altında kalmış şehir,

Şehir bir hiçliğe gömülmüş,

Bir yokluğa.

Vakitsiz yağmurların ıslattığı

Sokulgan bir geceye sunuyorum yüreğimi.

Kurşunlanan kentin, gürültüsüz meydanlarından,

Sana doğru koşuyorum.

Koyvermiyor hüzün,

Ansızın boşalıyor tüm limanlar.

Şehrin meydanında,

Bir umudu, bir yüreği çarmıha geriyorlar.

Oysa ben sana yoksul yaşamlar arasından,

Nice sevda sözleri biriktirmiştim.

Doğmamış bebekler için,

Ölümden değil, 

Sevdadan söz etmeyi istedim.

Göğü maviye boyayacak umut bizimdir, 

Merhamet biziz,

Ateş biz ve aşk biziz.

Mürekkebime acı, ayrılık ve kan bulaşmış,

Dağlı bir şair gibi,

Yollara vuruyorum yüreğimi.

Şimdi alabildiğine büyüyor

İçimdeki bozkırlar.

Mesafeler uzuyor

Bak, ayaklarım kanıyor.

MUHARREM YILMAZ', 'SEN NE KADAR ÇOKSUN Yabancılaştığım hayat, Gün geçtikçe Bir yığın elem, bir yığın hüzün taşıyor. Dört nala koşan atlılar geçiyor, Göğeren ya...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Yılmaz']::text[], 8.5, '{"poet":"Muharrem Yılmaz","poet_slug":"muharrem-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-ne-kadar-coksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsa Yalnızlık Olur', 'varsa-yalnizlik-olur-muharrem-yilmaz-ns6je', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varsa yalnızlık olur

Saniye saniye ilerlerken saat,

Mevsimler sökülüyor yüreğimizden.

Akıldan hep yalnızlık geçiyor,

İçimde dolaşıp duran harfler var,

Kelimeler ve cümleler var yakalayamadığım

Bir türlü bir araya gelemeyen,

Ama var olduğunu hep bildiğim..

Manzaralar var, seyretmeye doyamadığım.

Kayıplarım var tutamadığım. 

Okyanus derinliklerine,

Dağların zirvelerine yolculuklarım, 

Küçük mağaralara kaçışlarım var. 

Gözlerimin bağışladığı,

İnci tanelerim var.

Kahkahayla avazlanan,

Uslanmaz aynalarım var.

Saatler kıpırdadıkça, 

Mevsimler sökülüyor yüreğimden,

Akıldan hep yalnızlık geçiyor.

Muharrem Yılmaz', 'Varsa yalnızlık olur Saniye saniye ilerlerken saat, Mevsimler sökülüyor yüreğimizden. Akıldan hep yalnızlık geçiyor, İçimde dolaşıp duran ha...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Yılmaz']::text[], 8.5, '{"poet":"Muharrem Yılmaz","poet_slug":"muharrem-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/varsa-yalnizlik-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Arzunla Geleceğin', 'kendi-arzunla-gelecegin-cafer-tayyar-ozkan-775bg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep seni, senin anılarını düşlerim yokluğunda,

Haram oldu ayaz gecelerim, sımsıcak soluğunda,

Sana koşan umutlarımı, her seferinde yıksanda,

Kendi arzunla geleceğin günleri bekleyeceğim...

Uyandığımda seni yanımda görürüm sabahları,

Sevapları sana yazdım, banaysa acı günahları,

Şafak vakti ta uzaklardan gönderdiğin nidaları,

Kendi arzunla geleceğin yazlara saklayacağım...

Sesini duymadığımda bilsen, nasıl kahrolduğumu,

Damarlarımda aşk virüsünün acıyla koştuğunu,

Bu canla cananın ukdeme nasıl mecbur olduğunu,

Kendi arzunla geleceğin sayfalara yazacağım...

Sürgünde olsam, vurgunda yesem asla yılmayacağım,

Unutur sanma sakın, sonunda sana kavuşacağım,

Sevmek zayıflıksa, son nefesimde bile seveceğim,

Kendi arzunla geleceğin topraklara yatacağım...

Daha dün sevda şarkıları vardı hep dudaklarında,

Bugünse hasret gözyaşları akıyor yanaklarında,

Sevgiyse, mutluluksa hepsi benimle anılarında,

Kendi arzunla geleceğin duaları edeceğim...

Zannetme ki yüzüm gülerken, yüreğim kan ağlamıyor,

Sesini duymadığımda hislerim yaslar bağlamıyor,

Gizli dileğim depreştiğinde kalbimi dağlamıyor,

Kendi arzunla geleceğin sevdanı yaşayacağım...

30 Aralık 2002 Ankara', 'Hep seni, senin anılarını düşlerim yokluğunda, Haram oldu ayaz gecelerim, sımsıcak soluğunda, Sana koşan umutlarımı, her seferinde yıksanda,...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendi-arzunla-gelecegin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Mevsimi', 'yuregimin-mevsimi-nalan-kazazoglu-t6u3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgarda dalgalar,

Devrik, kırık....

Aynalar solgun, acımasız,

Kır, kırışık.....

Yüreğimin mevsimi şiir..

Geçmez bu...

Müzmin hastalık...

Aklımsa her dem karışık....

Veremem ateşe yıldızları,

Şiirlerim onlara sarılı,

Düşlerim geceye sarmaşık....', 'Rüzgarda dalgalar, Devrik, kırık.... Aynalar solgun, acımasız, Kır, kırışık..... Yüreğimin mevsimi şiir.. Geçmez bu... Müzmin hastalık... Ak...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuregimin-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip', 'dip-mehmet-taha-dogruyol-qbrc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 've fırtına nedeniyle

bir hafta ertelenir hayat

beşiktaştaki çaycıya vurur başını

ıslatırsın her yeri...

sen ne dersen de

şemsiye güneş için

saat, bulutlar ayı dört nala geçerken

demlenirsin boğazda lakin

yosun kokmaktadır artık çaydanlık...

susarsın

bakarsın

dalgalı boğazında bir gemici düğümü

hıckırırsın, kilitlenir adem elman

kabil-i mukayese değil bu karanlık

Habili mukayese edince kendinle...

yine de çıkamazsın

hayat anlam ister

anlam veremezsin...

ta Tebrizden bir güneş arar gözlerin

gecenin karanlığında

ha görsen korkacaksın, kaçacaksın

ama ışık ister bu derinde bu yürek...

yunus olmak süzülmek ister

sıçramak ister bir nefes için

ama tutturamazsın heceyi

''son demlerin tırnakları'' batar sinene...

ihtimal zamanında tarumar ettiğin

bir tarladandır bu kıtlık

özrün karı muamma iken

zarar eder durursun

içerde çıkar zamanın bilançosu

içerde patlar

kapılar kapalı

sen kalbinde yalnız...', 've fırtına nedeniyle bir hafta ertelenir hayat beşiktaştaki çaycıya vurur başını ıslatırsın her yeri... sen ne dersen de şemsiye güneş için ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dip-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
