INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aslında İşsiz Değilim', 'ben-aslinda-i-ssiz-degilim-mehmet-sakalar-d35tb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokak lambaları teker teker yanıyor,

Temizlik işçileri güneşin aydınlığını süpürüyorlardı önce.

Kurtlar inlerine dönüyor,

Fare labirentte peyniri arıyordu.

Benim işim yok değildi,

Ben seni seviyordum.

Başka biryerde kasımpatları boy gösteriyordu,

Çöl topraklarının üzeri tozlanıyordu başka yerde.

Ressam beni çiziyor, ben poz vermiyordum.

Benim işim yok değildi,

Ben seni seviyordum.

Bulut yağarken gökyüzüne bu mart gecesinde,

Herkes birşeyler yapıyordu.

Benim işim yok değildi,

Seni düşünüyordum,

Seni sevmeye devam ediyordum.', 'Sokak lambaları teker teker yanıyor, Temizlik işçileri güneşin aydınlığını süpürüyorlardı önce. Kurtlar inlerine dönüyor, Fare labirentte pe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakalar']::text[], 8.5, '{"poet":"Mehmet Şakalar","poet_slug":"mehmet-sakalar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-aslinda-issiz-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler Acır Geçmişten', 'kelimeler-acir-gecmisten-hulya-ozdemir-az6n3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutulur kapılar açılmadan

Ayrılığın üstüne 

Çizgilerin derinliğinde

          Bir ah tutuşur dilinde

Sığınır Hicazkâr fasıllara

Meltem gecelerin 

Sıcak örtüsüne

Her seferinde

Başlar Pazartesi umutları

Yeşil bir damla düşer gözlerinden

Boz kelebeğin üstüne

Sevinci gizli

                   hasreti özlem

Günler dökülür geçmişten

Kelimeler acır

Yıkılırken ıslaklığı

Hoyrat yılların dilinde

Demlenir günahlar artık

Gözlerimizde', 'Tutulur kapılar açılmadan Ayrılığın üstüne  Çizgilerin derinliğinde           Bir ah tutuşur dilinde Sığınır Hicazkâr fasıllara Meltem gecel...', ARRAY['Türk Edebiyatı','Şiir','Hülya Özdemir']::text[], 8.5, '{"poet":"Hülya Özdemir","poet_slug":"hulya-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kelimeler-acir-gecmisten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issızım Gözlerinsiz', 'issizim-gozlerinsiz-mehmet-sakalar-jx1s9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdam ıssız bu saatte, şimdiden kopuk,

Gözlerim resimlerde gözlerini seyretmekten yorgun.

Yanaklarım ıssız üşümekte,

Nerde kuş tüyü dudakların,nerde uçurum öpücükler? 

Boğuluyorum akşamın ayazında,

Nerde sigara çeker gibi çektiğim samyeli nefesin? 

Issızım, odam ıssız,

En neşeli resimlerin bulunduğu duvarım karanlık,

Nerde sabahın geleceğini müjdeleyen saatler? 

Nerdesin? 

Alev alev yanarken içim parmaklarım titremekte,

Nerde kuru yaprak saklar gibi elllerimi avuçladığın

                                                                         ellerin? 

Sen nerdesin? 

Issızım dünyamda, ruhum ıssız.

Ne olur seni seviyorum de yine uçuk kaçık,

                                                   yine kasıtsız.', 'Sevdam ıssız bu saatte, şimdiden kopuk, Gözlerim resimlerde gözlerini seyretmekten yorgun. Yanaklarım ıssız üşümekte, Nerde kuş tüyü dudakla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakalar']::text[], 8.5, '{"poet":"Mehmet Şakalar","poet_slug":"mehmet-sakalar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/issizim-gozlerinsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palandöken', 'palandoken-hulya-ozdemir-kg1qy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gurbettir Palandöken

Çıkar mermileri namludan

Böler belaları

Yiten ayak izlerinde

Çekilir suyu Karasu''yun

Kanıma dokunur ayrılık

İzleri içime

            savrulur

                       bakışları gök yüzüne

Bir korkudur Palandöken

Haykırır doğruyu

     Yankıdır kandırır

Usulca okşar akşamı

Ceylan bakışlı ay

Eskidir şarap gibi

Gece masalı anlatıları

Yatırlar,cinler,periler

Gider de gider 

Düş fakiri yüreğimiz

Bir mahkumdur Palandöken

Gelişi meçhul,gidişi yiğit

Özlem yarası bir bakış

Bir derya

Kar beyaza atılmış

Bir umuttur Palandöken

Bir garip vakit

ikindi güneş alası

Takılmıştır sevdaya

           acımsı tadı

Bir rüyadır Palandöken

Çiçek tomurlarından kurulu şafak

Yer, gök, kar

Beyaz gelinlik içinde

Kardelen umut muştular', 'Bir gurbettir Palandöken Çıkar mermileri namludan Böler belaları Yiten ayak izlerinde Çekilir suyu Karasu''yun Kanıma dokunur ayrılık İzleri ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Özdemir']::text[], 8.5, '{"poet":"Hülya Özdemir","poet_slug":"hulya-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/palandoken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağacın Gövdesine Sarılır Tenim', 'agacin-govdesine-sarilir-tenim-hulya-ozdemir-lgtmr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esip gelme uzaklardan

      bir deli rüzgar olup

Çocuk saflığında inanılır

      olmayan dualara

Kurumş çiçeklere bırak

      acısı yaşlarda saklı gözlerini

Ellerin uzanılmaz

       Kafdağı ötededir

Düş de olsa geçemez

       denizi kuşlar

Gül karadır artık

               kader de öyle', 'Esip gelme uzaklardan       bir deli rüzgar olup Çocuk saflığında inanılır       olmayan dualara Kurumş çiçeklere bırak       acısı yaşlarda...', ARRAY['Türk Edebiyatı','Şiir','Hülya Özdemir']::text[], 8.5, '{"poet":"Hülya Özdemir","poet_slug":"hulya-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agacin-govdesine-sarilir-tenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalı Çapkını', 'yali-capkini-ahmet-ozdemir-mersin-qqzck', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurar

    Saatini aşkın

           Yalı çapkını

Uyanır nebat

         Börtü - böcek

               Vakti gelince

Yinede kanmaz

Kapar gözlerini

Döner

Karanlığa insan

Uyanmaz...', 'Kurar     Saatini aşkın            Yalı çapkını Uyanır nebat          Börtü - böcek                Vakti gelince Yinede kanmaz Kapar gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yali-capkini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Olsam', 'deniz-olsam-ahmet-ozdemir-mersin-par3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir deniz olsam

Gelse sevdiğim  nü! 

Dört mevsimde bir

Kaynar suyum, taşar

Kavrulur, yanar şehir', 'Bir deniz olsam Gelse sevdiğim  nü!  Dört mevsimde bir Kaynar suyum, taşar Kavrulur, yanar şehir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Gel', 'yagmurla-gel-ahmet-ozdemir-mersin-ncc2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim 

Yağmurla gel

Toprak koksun saçların

Burcu - burcu

Gelişinle

Bitsin aşk orucu', 'Sevgilim  Yağmurla gel Toprak koksun saçların Burcu - burcu Gelişinle Bitsin aşk orucu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmurla-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-ahmet-ozdemir-mersin-cpb3p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum! dedin ya

Dün gece eğilip kulağıma

Uçtuğum, üstünde bulutlardı

   Yediğim naneli şeker

Uyandıracak ne vardı', 'Seni seviyorum! dedin ya Dün gece eğilip kulağıma Uçtuğum, üstünde bulutlardı    Yediğim naneli şeker Uyandıracak ne vardı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dun-gece-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uç-Uç Böceği', 'uc-uc-bocegi-ahmet-ozdemir-mersin-q04a0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uç-uç böceği olsam

Konsam yakana

Ya da

Kırmızı puanlı içliğin

Sana yakın olsam

Sen kadar

Tavşan kanı çay 

İçtiğin', 'Uç-uç böceği olsam Konsam yakana Ya da Kırmızı puanlı içliğin Sana yakın olsam Sen kadar Tavşan kanı çay  İçtiğin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uc-uc-bocegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-ahmet-ozdemir-mersin-6v26a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sabır ağacım meyve verir

Ne geriye akar, su

Gençliğim gelir ne de...! 

Zaman olur,

                durulur sular da

Susar duygularım

                dost yıldızlara

Bir ölü denize

                akıyor umudum', 'Ne sabır ağacım meyve verir Ne geriye akar, su Gençliğim gelir ne de...!  Zaman olur,                 durulur sular da Susar duygularım     ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir Mersin']::text[], 8.5, '{"poet":"Ahmet Özdemir Mersin","poet_slug":"ahmet-ozdemir-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neden-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal bile diyemedim', 'hoscakal-bile-diyemedim-ercan-urcar-jauvp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bir hayvan kapanı gibiydi,

Tutumu bırakmıyordu.

Akarsu gibi olsak,

Yüzsekte boğulurduk,

Düşerdik enderinlerine dalgaların.

Hayata bir kurşun sıkılsa,

Yaseni yabeni ama birimizi alırdı,

Götürürdü yanlızlıklar ülkesine.

Sana olan dostluğumu şiirlerimle anlatacaktım.

Belki bir damla yaşolup süzülecektim gözlerinden,

Belkide seni ağlatacaktım farkına varmadan,

Şiirlerimle ağlatacaktım.

Bakacaktım ağlayan gözlerine,

Tutacaktım titreyen ellerini,

Hoşcakal diyecektim diyemedim kopamadım.

Can dostum ömer HOŞÇAKAL........

    Vefat eden arkadaşımın anısına yazılmıştır.', 'Hayat bir hayvan kapanı gibiydi, Tutumu bırakmıyordu. Akarsu gibi olsak, Yüzsekte boğulurduk, Düşerdik enderinlerine dalgaların. Hayata bir ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Urçar']::text[], 8.5, '{"poet":"Ercan Urçar","poet_slug":"ercan-urcar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hoscakal-bile-diyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim sar beni', 'annecigim-sar-beni-umut-gungor-n94wo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anneciğim sar beni,

Sıcacık yüreğinle,

Üşüyorum sar beni,

Isıt ninnilerinle.

Kollarında ısınayım,

Kanadına al annem,

Soğuktan korunayım,

Yüreğine sar annem.', 'Anneciğim sar beni, Sıcacık yüreğinle, Üşüyorum sar beni, Isıt ninnilerinle. Kollarında ısınayım, Kanadına al annem, Soğuktan korunayım, Yür...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/annecigim-sar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kızım var adı Hilal', 'bir-kizim-var-adi-hilal-umut-gungor-866im', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kızım var adı Hilal,

Yanakları almı al,

Canım yavrum kızım Hilal,

Çok şükür yüce rabbime.

Akşam boynuma koşunca,

Dünya bizim olur onla,

Hilalimle biz coşunca,

Gökler kanat açar sanki.

Henüz daha dört yaşında,

Evimizin gülü Hilal,

Henüz daha dört yaşında,

Yuvamızın gülü Hilal.

Büyük oğlum Safa Eren,

Vatan için o Alperen,

Diğer oğlum Yunus Emre,

Vatan için o Alperen,

Herkes çocuğuyla bulsun huzur,

Hatam varsa bulman kusur,

Çocuklar evin nurudur,

Rabbim korusun cümlesini.', 'Bir kızım var adı Hilal, Yanakları almı al, Canım yavrum kızım Hilal, Çok şükür yüce rabbime. Akşam boynuma koşunca, Dünya bizim olur onla, ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-kizim-var-adi-hilal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Göz Altında...', 'duslerim-goz-altinda-batuhan-batu-ekslp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş hapsedilmiş anne; 

demir beş sıra uzanıyor, 

bir bir batıyor yüreğime...

beş yerimden kan fışkırıyor, 

şavaşlarım geliyor aklıma, 

erkekçe... 

namus için,özğürlük uğruna, 

pusularım şimdi yetim kaldı, 

söyle ben ne yapayım anne... 

Ay mevzilenmiş katran karası geceye, 

düşlerim göz altında,

Kancıklar, 

kavgaya çağırıyor, 

elimde kör bıçağımda yok, 

silahsız,tütünsüz, çarpışıyorum, 

Devrilmeden.. 

siper ediyorum göğsümü, 

kırmızıya bürünüyor beş parmaklık, 

diz boyu olmuş oda da, 

ben hala kalanların derdin deyim,

Yetim kalmasın dağlar, 

BORAN bensiz uçmasın, 

mor menekşeler yas tutmasın, 

bebekler baba hasretiyle yanıp tutuşmasın, 

şiirler yarım kalmasın, 

topraksız kalmasın yurdum diyorum, 

daha ne yapayım Anne? 

Ölüyorum.....', 'Güneş hapsedilmiş anne;  demir beş sıra uzanıyor,  bir bir batıyor yüreğime... beş yerimden kan fışkırıyor,  şavaşlarım geliyor aklıma,  erk...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/duslerim-goz-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Kıymetini', 'bil-kiymetini-celal-oymak-5p4qx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir martının kanadına kon

özgür ol kuşlar gibi

bulutlara takılarak

git uzaklara

rüzgarla düş bir hevesin peşine

bir elinde dört mevsimin

yediveren gülleri

diğerinde

sevda yarası karanfiller

tut zamanın dizginlerinden

uğra bütün limanlara

durup bakmadan arkana

bil ki dirilmez ölü çiçekler

yarın desen

hiç bilinmez

iyisi mi yormadan kendini

elindeki demetin

bil kıymetini', 'bir martının kanadına kon özgür ol kuşlar gibi bulutlara takılarak git uzaklara rüzgarla düş bir hevesin peşine bir elinde dört mevsimin yed...', ARRAY['Türk Edebiyatı','Şiir','Celal Oymak']::text[], 8.5, '{"poet":"Celal Oymak","poet_slug":"celal-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bil-kiymetini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Her Zaman', 'sevgi-her-zaman-celal-oymak-917f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'söylenirim

kendi kendime

seselenirim

cümle canlıya

sevdasız yaşanmaz

güneş kadar

toprak kadar

su kadar

yaşam yolunda

aş da aşk da gerekli

biri damarımda

akan kan

öbürü onu sarmalayan can

sevgi her zaman', 'söylenirim kendi kendime seselenirim cümle canlıya sevdasız yaşanmaz güneş kadar toprak kadar su kadar yaşam yolunda aş da aşk da gerekli bi...', ARRAY['Türk Edebiyatı','Şiir','Celal Oymak']::text[], 8.5, '{"poet":"Celal Oymak","poet_slug":"celal-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-her-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serdengeçtim yardan geçtim yılmadım', 'serdengectim-yardan-gectim-yilmadim-umut-gungor-gtslx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serdengeçtim yardan geçtim yılmadım,

Cayan caysın ben davamdan caymadım,

Engel gördüm pusu gördüm durmadım,

Yürek dersen mangal gibi duruyor.

Serdengeçtim vatan için duramam,

Kalan kalsın ben davamdan kalamam,

Vatandan bayraktan ayrı kalamam,

Ay yıldızı kaptım düşman üstüne.', 'Serdengeçtim yardan geçtim yılmadım, Cayan caysın ben davamdan caymadım, Engel gördüm pusu gördüm durmadım, Yürek dersen mangal gibi duruyor...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serdengectim-yardan-gectim-yilmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gazeli', 'sevda-gazeli-celal-oymak-fn3w6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beyaz karanfil söz dinletemez

kan ağlayan ikizine

aşkı kimse bilemez

girmedikçe sevda denizine

Mecnun''un aşkı tazelenir

rastladıkça Leyla''nın izine

gökyüzünde asılı duran bulut

kimine gölgedir, sevdayı çağrıştırır kimine

candan bir sesleniş, tatlı bir gülüş

sevgiliye sunulmuş en güzel hazine', 'beyaz karanfil söz dinletemez kan ağlayan ikizine aşkı kimse bilemez girmedikçe sevda denizine Mecnun''un aşkı tazelenir rastladıkça Leyla''nı...', ARRAY['Türk Edebiyatı','Şiir','Celal Oymak']::text[], 8.5, '{"poet":"Celal Oymak","poet_slug":"celal-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-gazeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdi Araya', 'girdi-araya-celal-oymak-0o5ii', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'özlemler dayanınca kapıya

yolculuk girdi araya

en yoğun deminde sevdanın

ayrılık girdi araya

yaprak düşerken mevsiminden

acılar, hüzünler girdi araya

bir çay içimi oh demeden

anılar girdi araya

yaşanırken huzurlu bir an

ölüm girdi araya', 'özlemler dayanınca kapıya yolculuk girdi araya en yoğun deminde sevdanın ayrılık girdi araya yaprak düşerken mevsiminden acılar, hüzünler gi...', ARRAY['Türk Edebiyatı','Şiir','Celal Oymak']::text[], 8.5, '{"poet":"Celal Oymak","poet_slug":"celal-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/girdi-araya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir nöbet için', 'bir-nobet-icin-umut-gungor-zg3d7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir nöbet için geldi dünyaya,

Çalıştı çabaladı bir nöbet için,

Bir nöbet için geldi dünyaya,

Vurdu vuruldu bir nöbet için.

Vatan dedi koştu askere,

Anne baba bekler teskere,

Gelmez oldu kaldı teskere,

Evlat şehid oldu bir nöbet için.

Çağırın Mehmedim bende geleyim,

O kutlu şerbetten bende içeyim,

Vatan için candan serdengeçeyim,

Bende şehid olayım bir nöbet için.', 'Bir nöbet için geldi dünyaya, Çalıştı çabaladı bir nöbet için, Bir nöbet için geldi dünyaya, Vurdu vuruldu bir nöbet için. Vatan dedi koştu ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-nobet-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerim Dilsiz', 'gecelerim-dilsiz-orhun-basat-qvxf3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Kimsen ya da her ne isen

Sol yanımdaki sızılardasın hep 

Hüzünlerimi mayalıyorum seninle 

Hoşuma gidiyor..

Sen de ölüyormusun geceleri benimle

İçim öyle diyor..

II

Bir özlem çiziyor gecemi ince yerinden 

- sen gibi - 

İçimden ağlara sürüklenen 

Balık sürüleri geçiyor 

Derinden 

İçimin en yoksul yerinden..

Şeytan sofralarında açlığım..

III

Güne çalıyor gözlerim 

Uykuyu sıyırıp göz bebeklerimden 

Yalnız gezinmelerimde 

Sevda bıkkını sokaklarında şehrinizin..

Ellerim dokunduğunda ellerinize 

- Tuhaftır – unutuyorum rengini denizin..

IV

Rüzgar çatlağı dudaklarınızdan 

Bir hüzün havalanıyor  bir  kaval sesiyle

Ve kırık ışıklar bir resim çiziyor  kıyıya

Gecenin son nefesiyle 

Esrik eskimelerde yanıyor düş..

V

Bilirdim 

Sessizliğini sevmektense

Sensizliği sevmeyi 

Konuşmalara hasret 

Kıskacında dikey ölümlerin ..

Harfleri yitikti çığlıklarınızın 

Nedense..

VI

Ne ben ilk kurbandım 

Ne de ilk cinayetiydi gecenin 

Kan kurusu duvarlardaydı yüzüm

Üstü ustura yaralarıyla dolu resmin 

Çizeri bir engerekti kesin..

Zehirlemişti dokununca hüznüm..

VII

Kıblesiz gecelerimde

En dindar hıçkırıklarında yalınlığın

Zifir zindan soluklanışlarında hüznün 

Yedi kat gök gibi üstüme çökmüş karanlığın 

Rahminde umutsuz bir tohumdu sensiz yeni gün..

VIII

Sen hüznümün bedeni 

Sen paletimde her renkte özlemim 

Gecemin teni 

Hiç bir sevince değişilmez matemim 

Yüreğimin ayrık otu 

Baktığım her yerde bitenim..

Bensizim / sensizim 

“ korkularım, titremelerim ”

Çeyiz sandığımdaki acı..

IX

Dışa vurumlarında sevdanın 

Soya çekimi gizlidir hüznün 

Ne dinlenir ne dillenir acılarım / bilemezsin 

Bir yılkı atıyım suskun kıyılarınızda 

Bulutlar yağmur yüklü değil 

Kendi içine titriyor zaman

Söz 

Bir daha geçmem kapınızdan 

X

Sana dokunamadığım an

Gecelerim dilsiz 

Günlerim kötürüm

Bil ki 

Mezar taşımda adım olmayacak 

Bir sabah unuttuğunuzdan..', 'I Kimsen ya da her ne isen Sol yanımdaki sızılardasın hep  Hüzünlerimi mayalıyorum seninle  Hoşuma gidiyor.. Sen de ölüyormusun geceleri ben...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/gecelerim-dilsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir ağladı', 'sehir-agladi-ferit-teksoy-w0vvq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün gök delindi sanki aniden

Düşen dolulardan camlar kırıldı

Bir anda sel oldu şehrin gözleri

Yokluğuna sevdiğim şehir ağladı

Şimşekler gürledi çığlık çığlığa

Sanırsın aniden gökler yarıldı

Sağnak oldu yağdı ağıtcasına

Sensizliğe sevdiğim şehir ağladı

Karardı tüm şehir geceler gibi

Gün ortası sanki gece bastırdı

Göz yaşı değildi yağan..göz yağdı

Özlemine sevdiğim şehir ağladı

Bugün şehir benim anladım onu

Derbeder dolaştım paylaştım ağıdını

Gözyaşlarım karıştı taşkın akan suyuna

Hem ben ağladım bugün,hem de şehir ağladı

10 Ağustos 2004', 'Bu gün gök delindi sanki aniden Düşen dolulardan camlar kırıldı Bir anda sel oldu şehrin gözleri Yokluğuna sevdiğim şehir ağladı Şimşekler g...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sehir-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hep Sevdim', 'seni-hep-sevdim-i-smail-kulahci-jd1qn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni hep sevdim ve hep seveceğim 

Yüzüme bakmasanda 

Bırakıp gitsende 

Ben seni hep sevdim ve hep seveceğim 

Bir ırmağın denize ulaşması gibi

Bir kuşun ilk kez ayaklanması gibi

Saf ve temiz

Ben seni hep sevdim ve hep seveceğim 

Ben seni hep sevdim ve hep seveceğim 

Beni ne kadar üzsende 

Beni ne kadar kırsanda 

Ben seni hep sevdim ve hep seveceğim

Yıldızların ucunda kalbimin parçaları takılı olsada 

Bir yanım hep parçalı 

Bir yanım hep eksik olsada

Bir yanım sen olsan ve onu alıp götürsende

Ben seni hep sevdim ve hep seveceğim

Seni seveceğim sonsuza dek 

Senin beni unutmana rağmen

Seni senden habersiz seveceğim 

Doğum günlerini kutluyacağım senden habersiz

Ve sonra o gün gelecek 

Sana olan sevgimi topraklar paylaşacak

ben seni sevdim ve seni severek ölecegim', 'Ben seni hep sevdim ve hep seveceğim  Yüzüme bakmasanda  Bırakıp gitsende  Ben seni hep sevdim ve hep seveceğim  Bir ırmağın denize ulaşması...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-hep-sevdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme Tekerlemeler', 'deneme-tekerlemeler-rahim-tas-wm6c8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tekerlemeler

        -  Evli evliye evliya evli olmaz demiş. 

        -  Şu hemşire senin hemşeri, bu hemşeri benim hemşire. 

        -  Hataylı hattatın hat hatasından harita hatalı olmuş, hatta harita harika harita olmaktan çıkmış.

        -  Gözü çekik kaçık kaçak ile açık saçık kaçak kaçık kekik çekiçledi. 

        -  Sanatı sansürlenen sanık sandaletini sanal sandalın sandalyesinde sanıp sansasyon yarattı. 

        -  Şanslı şefin elinde şeker şişesi, şeker şoseye düşer seker şefin neşesi gider şivesi beter. 

        -  Ham hamala hamak haram hamam harman. 

        -  Adam akıllı adama a kıllı demiş adamakıllı dayak yemiş. 

        -  Midilli mi dilli dilli mi dilli. 

        -  Yeni imaj, pasajda röportaj plajda masaj meşe masada mesaj…

10.8.2004', 'Tekerlemeler         -  Evli evliye evliya evli olmaz demiş.          -  Şu hemşire senin hemşeri, bu hemşeri benim hemşire.          -  Hat...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deneme-tekerlemeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler kuzusuna', 'anneler-kuzusuna-umut-gungor-v3oc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anneler kuzusuna,

Hayran hayran sarılır,

Anneler yavrusuna,

Kuş olur kanatlanır.

Annenin kuzusuyuz,

Yaşımız kaç olsada,

Annenin yavrusuyuz,

Yaşımız kaç olsada.

Titrerler üstümüze,

Gözü gibi korurlar,

Titrerler üstümüze,

Sanki melek olurlar.

Anneler anneler,

Keşke üzülmeseler,

Güzel günler görseler,

Her evlat hayırlı olsa.', 'Anneler kuzusuna, Hayran hayran sarılır, Anneler yavrusuna, Kuş olur kanatlanır. Annenin kuzusuyuz, Yaşımız kaç olsada, Annenin yavrusuyuz, ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anneler-kuzusuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-i-smail-kulahci-8hc4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün geride kalanlara

Dönüp baktığında

Beni göremeyeceksin

Geride sadece hatıralar kalacak 

Bakıp ağlayacaksın

Geride kalan acı

Geride kalan heyecanlı, hatıralara

Anacaksın lise sıralarını

Anacaksın hatıraları, arkadaşları

Ama o arkada beni göremeyeceksin

Niye mi? 

'''' Hiç ardına bakma kırallar önden gider''''

Diye bir söz vardır BİLİRMİSİN', 'Birgün geride kalanlara Dönüp baktığında Beni göremeyeceksin Geride sadece hatıralar kalacak  Bakıp ağlayacaksın Geride kalan acı Geride kal...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilirmisin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulu Camlar Kütüphanesi II', 'bugulu-camlar-kutuphanesi-ii-ahmet-capa-8exh6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göklere sıcaklığın izini bırakır gibi,

Bu şehrin bacalarından kömür kokusu sızardı,

Sızlardı ciğerleri bütün kuşların,

neylesinler ufaktı hepsinin kanatları.

Bir otel odasında, hohlayarak ısıttığım ellerimle

Buğulu camlar kütüphanesine resmini çizdim kuşların,

Perdelere bir balık gibi takılırken ışıkları.

Ay, şimdi en kızgın mevsimindedir karanlıkların.

bütün albümlerde bağırırken fotoğraflar,

Pimi çoktan çekilmiştir artık mazi bombasının…

Mesela şu koltukta oturmuşluğun,

Yürümüşlüğün halıda yorgun ayaklarınla,

Ve bir akşamüstü yürek kapının kapanmışlığı,

Ve benim çıldırmışlığım kapının arkasında…

Bir zamanlar,

aşkın çayında eritirken kalbimizin şekerini,

şimdi kirpiklerimin salıncağında tuzlu bir sıvı sallanmakta.

Hayatın en tenha istasyonunda bıraktın sevdanın ellerini.

Şimdi o da,

zalim bir trenin altına kendini atmakta.

Bu ayrılığın ağır emaneti kala kala 

şu istasyonda yalnız bıraktığın bir adamın boynuna mı asılmalıdır

Demek gidiyorsun,

O zaman bu boyun ta omuzlarımdan kopmalıdır…

Giderken raylarını senfonisi ezberletir gibi kalana,

Emre hazır katil bir tetikçiydi son sözlerin,

Yavaşça araladı karanlık bir boşluğu dudakların,

Söylenmemiş sözcükler mezarlığından uyandı bütün kelimeler.

Ağzının şarjöründe tek bir kurşun

Dilinin namlusundan bir elveda mermisi gibi patladı…

Ve buğulu camlar kütüphanesinde,

parçalandı kuşların kanatları…

(10.08.2004 İst.)', 'Göklere sıcaklığın izini bırakır gibi, Bu şehrin bacalarından kömür kokusu sızardı, Sızlardı ciğerleri bütün kuşların, neylesinler ufaktı he...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bugulu-camlar-kutuphanesi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dingin', 'dingin-oguzkan-bolukbasi-cn3ti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürüyorum  ışıklarında kentin

Derin karanlığında gecenin

Kahverengi değil mi senin gözlerin

Seçemiyorum ışıklar gözümü kamaştırıyor

Sarhoş muyum

Sanmıyorum çakır keyif kalktım masadan

Şişenin dibini bulmadan

Yürüyorum 

Kaldırımlarda alabildiğine tamirat var

Taşlara takılıyorum

Tutma beni düşmeyeceğim

Yada tut beni düşeceğim

Bu ne kararsızlıktır 

Kararsızlıklarımı seviyorum

Çünkü ne yapacağım bilinmiyor gizli kalıyorum

Şimdi bir deniz olmalıydı

Dalgalı falan

İyot kokmalıydı gece ben efkarımı bölüşmeliydim

Bir sigara yakmalıydım derinden çekmeliydim dumanı içime

Sen gibi

Beni dinleyen bir başka çakır keyif yanıma oturmalıydı

Ona her şeyi anlatmalıydım

Her şey dediğim bir sensin bir de sen

Kırk hikayem olmalıydı ayılarınki gibi

Kırkı da aynı 

Dinleyen bıkmalıydı

Anlatan ben

En çok ayıları severim o yüzden

Dümdüz yelesiz kırıtmasız harbi

Hani şöyle adam gibi

Yürüyorum ışıklarında kentin

Derin karanlığında gecenin

30.07.2003', 'Yürüyorum  ışıklarında kentin Derin karanlığında gecenin Kahverengi değil mi senin gözlerin Seçemiyorum ışıklar gözümü kamaştırıyor Sarhoş m...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dingin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Değiliz Hiç Birimiz.', 'masum-degiliz-hic-birimiz-murat-nail-guney-tqvt2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda için koca ömrü nasıl tüketiverdik,

Sevgimiz için oysa nelere gögüs gerdik,

Sevdiğimiz olmazsa hayat olmasın derdik,

Bu yüzden suçluyuz, masum değiliz hiç birimiz...

Uzak iken hasretten bitmiyordu geceler,

Kavuşunca unutuldu sevgi dolu heceler,

Şimdi zehir gibi sözler yüreğimizi deler,

Ayrıldık suçluyuz masum değiliz hiç birimiz...

Yıktık gurur uğruna sevgi dolu düşleri,

Tükettik tüm baharları, yaşıyoruz kışları,

Akmıyor gözümüzden mutluluk gözyaşları,

Unuttuk, suçluyuz masum değiliz hiç birimiz...

Yaralı bu yürekler, hep acılara gebe,

Çaresiz kaderimizle oynuyoruz körebe,

Birimiz gurbette kaldık, diğerimiz göçebe,

İkimiz de suçluyuz, masum değiliz hiç birimiz...

Hazan yaprakları gibi öylesine savrulduk,

Ne gururdan vazgeçtik,ne çileden yorulduk,

Daha ne kadar sürecek bu meçhule yolculuk,

Sevmiştik, suçluyuz, masum değiliz hiç birimiz..

İstanbul''lu bir şiir dostuma ithafen...

31/07/2004  saat:02:000 hatay/izmir

murat nail güney', 'Sevda için koca ömrü nasıl tüketiverdik, Sevgimiz için oysa nelere gögüs gerdik, Sevdiğimiz olmazsa hayat olmasın derdik, Bu yüzden suçluyuz...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/masum-degiliz-hic-birimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'IIII/Gece', 'iiii-gece-ali-gencay-tspko', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I- 

Günleri sundu tanrı 

Geceleriyle 

Var gör sen 

Zamanı sırtına saranları 

Uyuma! ! 

Unutma gece düşlerini satanları 

Ben alamam 

Değeri kat,kat azalanları 

II- 

Sevmedin değil mi? 

Yüreğine düşen kor değil 

Ateşi körüklenen şehvetindi 

Sevme! ! 

Aşk ateşi yok eder gecelerini 

Yaşamayı becermezsin ki 

Gündüzlerin geceye gizlediği gizemi 

Sen! ! 

Nerden bilesin ki 

III- 

Oysa ben 

Hiç becermedim sevmemeyi 

Her gece sakladığım düşleri 

Çıkardım yüreğimden 

Bir,bir sıraladım dizeleri 

Görme! ! 

Zaten gözlerin 

Beni hiç süzmedi ki 

IIII- 

Al işte! ! 

Simsiyah pelerin giydi gece 

Ne kadar gizemli 

Kareleri çapraz bilmece 

Çözme! ! 

Bilinmemeli bende ki 

Yukardan aşağı 

Kaç hece 

IIIII – 

Gidiyorum 

Kal şehvetinle 

Seni senle bilenlerle 

İnan! ! 

Dönüp bakmam gözlerine 

Düşme peşime kayıp olursun 

Karanlıklar içinde 

Yine de kıyamam 

Dayanamam hasretine', 'I-  Günleri sundu tanrı  Geceleriyle  Var gör sen  Zamanı sırtına saranları  Uyuma! !  Unutma gece düşlerini satanları  Ben alamam  Değeri k...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/iiii-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıl yalnızlığına', 'saril-yalnizligina-tan-surkent-cpka3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarıl yalnızlığa gülüm

Sevgimle yoğrulmuş yüreğin

Bir daha maya tutmaz 

Giden gelmez

Bilmezmiydin?', 'Sarıl yalnızlığa gülüm Sevgimle yoğrulmuş yüreğin Bir daha maya tutmaz  Giden gelmez Bilmezmiydin?...', ARRAY['Türk Edebiyatı','Şiir','Tan Surkent']::text[], 8.5, '{"poet":"Tan Surkent","poet_slug":"tan-surkent","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/saril-yalnizligina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çeker giderim', 'ben-ceker-giderim-i-smail-kulahci-g151f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben çeker giderim bu diyardan 

Gözü yaşlı bir ana, yıkılmış bir baba 

Bırakır giderim

Yüreği buruk bir sevgili

Hasretle yanan bir kardeş

Bırakır giderim

Ben çeker giderim bu diyardan 

Buğulu bir gecenin sabahında 

Soğuk ve yağmurlu bir gecenin ayazında

Yakar giderim ben bu şehri

Ben çeker giderim bu diyardan 

Ötüşen kuşların sesini, bir kedinin yavrusunu 

Bir ananın oğlunu, kan kardeşimi 

Hayallerimi, umutlarımı 

Benliğimi ve tüm varlığımı unutur, 

Çeker giderim bu diyardan 

Ben çeker giderim bu diyardan 

Fırtınadaki azgın dalgalardan kaçıp

Bir limana sığınan balıkçı teknesinin çaresizliğiyle

Hiç birşeyi olmayan bir dilencinin acizliğiyle

Bir yetimin ezikliğiyle

Küsen bir çocuk ve azgın bir dev gibi

Bu şehri yıkar giderim 

Ben çeker giderim bu şehirden

Arkama bile bakmadan

Yarimi, dostlarımı, anamı, babamı

Vede kız kardeşimi 

Herşeyi silip süpürüp hayatımdan 

Hasret gecesinin soğuğunda 

Sabaha karşı beş ayazında

Bütün bu şehir uyurken,

Ben usulca, sessizce

Gecenin soğukluğuyla

Çeker giderim ölüme 

Hiç kimse anlamaz yokluğumu', 'Ben çeker giderim bu diyardan  Gözü yaşlı bir ana, yıkılmış bir baba  Bırakır giderim Yüreği buruk bir sevgili Hasretle yanan bir kardeş Bır...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-ceker-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir Bana', 'gelir-bana-i-lyas-ozmen-htq5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskişehir derler yalçın kayalık

Fark etmez aşarım düz gelir bana

Bir şiir yazarım üç beş satırlık

Dağılır kayalar toz gelir bana

Yine coşmuş bülbül altın kafeste

Tavukla kuzuyla yapmış bir beste

Akordu bozulmuş o cırtlak sesle

Ne dese ne yazsa caz gelir bana

Karnımda ağrı yok hekime gitsem

Kereste göremem aynaya baksam

Ne zaman soyunup meydana çıksam

Yiğitler kaçışır kız gelir bana

Kalemi keskin ya yazdıkça yazar

Aklına gelene birşeyler düzer

Yakındır tırlatır huniyle gezer

Gecikmez haberi tez gelir bana

Aşığım aşk ile yanar tüterim

Muhabbet yok ise çeker giderim

Değişmez ezelden böyle kaderim

Beyazı isterim boz gelir bana

ÖZMENEM biçare garip bir kulum

''''GÜLLÜK'''' artık oldu benim okulum

Meyveli bir bağa düşünce yolum

İştahım kabarır haz gelir bana

(Mustafa Ceylan ve Antalya GÜLLÜK Dergisinden Sayın

 Rasim Köroğlu Hocamızın başlattığı atışmaya iştirak 

 için yazılmıştır.Yalnız sayın hocamızın hızına yetişebilmek

 için biraz aceleye geldi,bu yüzden tam kıvamına erişemeden

 kayıt yaptım şiirseverlerden ayrıca özür dilerim.) 

 ÖNEMLİ NOT:Sayın Hocamızın engin hoşgörüsüne 

                          sığınarak yazılmıştır,ayrıca belirtmek isterim.', 'Eskişehir derler yalçın kayalık Fark etmez aşarım düz gelir bana Bir şiir yazarım üç beş satırlık Dağılır kayalar toz gelir bana Yine coşmuş...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Aşk', 'buyuk-ask-i-smail-kulahci-cg7b7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güllere doladım sevgimi 

Dallra bağladım özlemimi

Rüzgara fısıldadım aşkımı

Rüzgar işitince sevgimi 

Birden fırtınalar oldu 

Kasırgalar koptu

Bir baktım şehir yok olmuş

Nerden bilebilirdim benim aşkımın 

Bu kadar büyük olabileceğini', 'Güllere doladım sevgimi  Dallra bağladım özlemimi Rüzgara fısıldadım aşkımı Rüzgar işitince sevgimi  Birden fırtınalar oldu  Kasırgalar kopt...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/buyuk-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili', 'ey-sevgili-i-smail-kulahci-a8405', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana birşeyler ver ey sevgili

Sen yokken benimle olsun 

umutlarım hayallerim olsun

Bana birşeyler ver ey sevgili

Ne bileyim bir dantel çr

Bir sevda sar yüreğime

Senin kokun olsun üzerinde 

Anlatamadığım duğgularıma tercüman 

Sen yokken yoldaş olsun yüreğime

Bana birşeyler ver ey sevgili 

Varsın, ölüm olsun! ! ! ! !', 'Bana birşeyler ver ey sevgili Sen yokken benimle olsun  umutlarım hayallerim olsun Bana birşeyler ver ey sevgili Ne bileyim bir dantel çr Bi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Külahçı']::text[], 8.5, '{"poet":"İsmail Külahçı","poet_slug":"i-smail-kulahci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ey-sevgili-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Taşra Hikâyesi... (Ş.Y. Dosyasından)', 'tasra-hik-yesi-s-y-dosyasindan-naime-erlacin-udkrg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-zarfı belirleyen mazruf; mazrufu belirleyen ise zaman…N.E.

sevemedim merkezi

katrana bulanıyordu çeperler

sığılmazdı böyle yerküreye 

taştım taşraya 

çağırıyordu gökler

kilitler pas

kilitler kan revan

söküldü cehennem kapısı 

bulutlar tebliğ edildi usuma

rezil bir kıyamete döküldüler 

durulmaz gayri buralarda

ipi çekildi mazbatanın

sözcük, imlâ ve anlamın

kabuğum bağama yük

vurdum taşkınıma

vurdum taşraya

bir içime yenildim

bir de 

içimin taşrasına

bu kaçıncı yol

kaçıncı serüven 

denize baktı Musa

yarıldı su

ana rahmi paramparça

sustu dünya

gurbet sevdalısı şiir ey! 

doğurgan ağrılarımsın araf sırtlarında

hükmümden cinnetli hükmedenim

ne kaldı geriye 

aslıma rücu edip bir pagan otağında

göçün son durağında Altay’dan tetiklenen

sözün memesinde mazruf belirlerken

“geleceğe bir mektup”* yazmaktan başka

bir içime yenildim ahh! 

bir de…

……

(*)   “Şiir, geleceğe yazılmış bir mektuptur....Mektup, ‘iki’nin eksilerek  ‘bir’ olmasıdır.”  - Hüseyin Ferhad

(10 Ağustos 2004)     - Ş.Y Dosyasından)', '-zarfı belirleyen mazruf; mazrufu belirleyen ise zaman…N.E. sevemedim merkezi katrana bulanıyordu çeperler sığılmazdı böyle yerküreye  taştı...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tasra-hikayesi-s-y-dosyasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzümde sesi var türkülerin', 'yuzumde-sesi-var-turkulerin-pelin-onay-8eb0f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kırgın ezgiler kuşağında bir kaval sesiyim 

''nenen ölsün sarı gelin'' diyor dağların adamı 

dudaklarından ırmaklar akıyor, 

güneş yanığı yüzünde hüzün çağlıyor, dertleniyorum 

kekik kokulu bir gecenin yatağına uzandım, 

dilimde susuz bir titreyiş, 

ıslatmanı bekliyorum 

kapamasın gözlerini şimal yıldızı, 

utanmıyorum yüreğimin çıplaklığından 

bu bedende nice ayrılıklar erittim, 

nicesini ellerimle besledim 

şimdi vaktidir dellenmiş kavuşmaların, 

kadınlığımı dolaptan çıkarttım, giyiniyorum 

gururuna yenik düşmüş bir bulutun göz yaşlarıdır avuçlarımdan akan 

parmakları nasır tutmasın sevginin 

gel..! Ey ayazın doruklarında siper almış sürgünüm 

bir su damlasıyım gurbet ellerde, damlıyorum 

bir sazın tellerinde okşanan sızıyım 

''değmen benim yaslı gamlı gönlüme'' diyor dağların adamı 

ellerinden notalar kayıyor, 

gece yanığı teninde sevda bileniyor, hissediyorum 

tütsü kokulu bir gecenin omzuna yaslandım 

dudaklarımda dilsiz bir huzur, 

öpmeni bekliyorum', 'kırgın ezgiler kuşağında bir kaval sesiyim  ''nenen ölsün sarı gelin'' diyor dağların adamı  dudaklarından ırmaklar akıyor,  güneş yanığı yüzü...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuzumde-sesi-var-turkulerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Kıyıda Sevgini Unutma', 'karsi-kiyida-sevgini-unutma-yuksel-ozbek-gg62p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayın ketum memesinden içiyorum geceyi,

Yeşilırmak salınarak yürürken,

Bölüveriyor şiir yoksulu kenti,kalbinden.

İnsanlar,arabalar diz dize yürümekte köprüsünde.

Eskimişliğinde geçmiş kokan,hasır

şapkalı evin önündeyim.

Kendi yaşıtı hamamın kıskanç bakışları 

altında,nehirle dans etmekte,kerpiçlerini döke döke…

Gök katlı,güneş enerjili apartmanların 

küçümseyiciliğine aldırmadan,

İnsanların çıkar kokan bakışlarına inat! 

Sarılıveriyor,nehir aşkına….

Salsa,çaça,tango da neymiş! ! 

Özün,özüne değmeli  dans dediğin! ! 

Nehir ve ev bile bunun farkında! 

Fısıltılar dalga, dalga kulağımda; 

“Tuğlamın   eklemleri  ağarmakta! ! 

direklerim deniz kokusu taşır ya,sızlamakta.

Çatım delindi,ahşap yanım ıslanmakta,

içimde taşıdığım yaşamları,

o güzel,o acı insanlı günleri

balkonum unutmakta..

Ey! Uzun soluklu ömrüm! ! 

Senden nasıl çıkarım belirsizliğe,

nasıl bırakırım, ırmağımla dansı.

Yeni aşıklara zulam kollarını açmalı,

Dayan temelim dayan….”

“Dayan “  diye kabaran bir ses eklendi,

hırçınlaşan nehirdi; 

“değer bilmezler ordusu bu insanlık, aldırma.

Aşkı yalan,kendi yalan.

Köprü  kurarlar üstüme,her şeyleri  geçer,

bir tek sevgileri kalır karşı kıyımda...”', 'Ayın ketum memesinden içiyorum geceyi, Yeşilırmak salınarak yürürken, Bölüveriyor şiir yoksulu kenti,kalbinden. İnsanlar,arabalar diz dize y...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/karsi-kiyida-sevgini-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-baykal-kaanalp-f2chz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'onulmaz bir yarasın

kalbimde

zaten bu kalp benim değil

ama olsun

sen yine de bir yarasın

kalbimde', 'onulmaz bir yarasın kalbimde zaten bu kalp benim değil ama olsun sen yine de bir yarasın kalbimde...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yara-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konçerto', 'koncerto-baykal-kaanalp-a09i9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'havada hafiften bir

piyano sesi

konçerto çalınıyor

herhalde kapılar aralık

ses hole kadar geliyor

çocuk kızgın

çocuk dargın

elinden oyuncağı alınmış gibi

bir de üstüne üstlük

sevmediği müziği

dinlemek zorunda

bırakılmış

ağlasın mı? 

kulaklarını mı? tıkasın

bilemiyor/bilmiyor

hatta kararsız

havada asılı birkaç surat

bön bön bakıyorlar

çocuğa

sanki alay eder gibiler

çocuk kızgın

çocuk dargın

elinden elme şekeri

alınmış gibi

ağlasın mı? 

kulaklarını mı? tıkasın

bilemiyor/bilmiyor

hatta kararsız

bütün husumetler

onu bulmuş gibi

her şey üzerine geliyor

sanki

belk de ona öyle geliyor

ne kadar kaçmak isterdi

şu ortamdan

keşke ölseydi

çocuk kızgın

çocuk dargın

havada ki suratlar

hala ona bakıyor

ve dalga geçiyorlar

ağlasın mı? 

kulaklarını mı? tıkasın

hiç bilmiyor/bilemiyor

hatta bilmek dahi

istemiyor', 'havada hafiften bir piyano sesi konçerto çalınıyor herhalde kapılar aralık ses hole kadar geliyor çocuk kızgın çocuk dargın elinden oyuncağı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/koncerto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susardım', 'susardim-baykal-kaanalp-tkf0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'susardım

konuşmazdım

saatlerce

susardım

konuşmazdım

günlerce

ne bir hoş sobet

ne de bir gülüş saklı

giderken bıraktığın

güllerde

susardım

konuşmazdım

saatlerce

susardım

konuşmazdım

günlerce

sözlerim seni

incitmesin diye

ellerimi uzatırım sevgiliye

söyleyecek çok şeyim

olsaydı bile

susardım

konuşmazdım

saatlerce

susardım

konuşmazdım

günlerce

birleştirdi birbirimize

bizi ellerin

yakardı,kavururdu gözlerin

uzağındaydık

sorgusuz dillerin

susardık

konuşmazdık

saatlerce

susardık

konuşmazdık

günlerce', 'susardım konuşmazdım saatlerce susardım konuşmazdım günlerce ne bir hoş sobet ne de bir gülüş saklı giderken bıraktığın güllerde susardım ko...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/susardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım ki Oralar', 'anladim-ki-oralar-nevin-kurular-rqanp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözcükler üşümüş dilinde canım

Söndürdün mü yüreğinde arzuyu

Karayel mi  reva gördüğün

Titriyor umut

Titriyor tutku

İçtiğim karsuyu.

Bugün burada yağmur var canım

Gökyüzü kara bulutlu

Rüzgar bahar dalımı kırmış

Çiçeklerim korkulu.

Anladım ki aralar ayazda can

Anladım ki ayaz var

Ağustos yağdıracak kar

Estirecek  kasırgalar...', 'Sözcükler üşümüş dilinde canım Söndürdün mü yüreğinde arzuyu Karayel mi  reva gördüğün Titriyor umut Titriyor tutku İçtiğim karsuyu. Bugün b...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anladim-ki-oralar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Adım', 'bes-adim-gencay-coskun-5xnqr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.Adım 

Çocukluğumun odalarını yıktılar 

Kapısına da duvar ördüler

Her ışığı bilinçsiz yaktığımda 

Kapıyı tekrar açacağımı 

Tek huzurlu yatağımı bulup 

Uyuyacağımı  sanırken 

Geçmişim ayak izleri yol olmuş 

Gelen geçenin kirli izlerinle eziliyordu

2. Adım 

Uzakta olmayan 

Sadece anılarımda çocukluğum odaları vardı

Fındık farelerinin sıçrayıp 

Aklımı aldığı zamanlarda 

Korkudan onları izlerken 

Çok şirin yaratıklar olduğunu öğrenmiştim 

Damlarımız akardı 

Elde leğenler 

Bir başka uyunurdu 

Yarım yamalak damla sesli 

Özel bir senfoni çalınırdı 

Gel de uyu uyabilirsen 

Garipte olsa 

Soğukta olsa 

Mutlak bir huzur vardı odalarımda 

3. Adım 

Uzaktan baktığımda 

Altmış mumluk ampulün 

Salına salına yaydığı ışığı göremeyecektim 

Çam ağacını o zamanlar çolaklaşmamış

Sağ kolu olacaktı pencere akislerinde 

Sabahın ışıkları 

Odalarıma pencerelerinden 

İçlerimizi ısıtarak 

Dikenli girecekti 

4.Adım 

Küçük alçak bodrumları vardı odalarımın 

Korkudan girememiştim 

Aslına bakacak olursam 

Bir daha o bodrumlara hiç giremeyecektim 

Ayaklarım beton griliklerinin 

Soğuk acıtan yerlerine alışamamıştı 

Tahtakurulu olsa bile 

Tahtadan döşemelerimi özlerdim.

Camlarından 

Sokakları

Komşuları 

Kuşları 

Ağaçları 

Kedileri izlediğim yerler 

Bir daha asla gelmeyecekti ama 

Beynimden de bunlar aslada silinmeyecekti 

5.Adım 

Yıkılan odalarımda 

Benden çokça parçalarımda oldu 

Yıkılmayıp bulunsa zamanlıkta 

İlkel insanlar neler yazardı dedirtecek türden 

Duvarlarına yazdığım şiirlerim vardı 

Sıvası çatlak kapatma alçı taşması 

Boyaları alacalı bulacalı 

Dağınık mı dağınık 

Benim mi ölümlük benim odalarımdı 

Sonsuz anılarım oldu 

Son Adım 

Ölene kadar 

Öldükten sonra tek adım

Yıkanları da seyredenleri de biliyorum 

Vaktin zamanında odalarımda 

Elimi eteğimi 

Taze pisliğe basılmış 

Ayakkabı tabanlarımı

Öptürmek için 

Yaratıksıları bekliyorum.', '1.Adım  Çocukluğumun odalarını yıktılar  Kapısına da duvar ördüler Her ışığı bilinçsiz yaktığımda  Kapıyı tekrar açacağımı  Tek huzurlu yata...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/bes-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nü I', 'nu-i-ahmet-aksoy-xp8cm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kör bir ışık altında

annesinin başını okşayan çocuk

kız gibi aziz

İsa kadar günahkar', 'kör bir ışık altında annesinin başını okşayan çocuk kız gibi aziz İsa kadar günahkar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihlamur kokardı', 'ihlamur-kokardi-gencay-coskun-telks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ihlamur kokardı

Demi yüreğinde 

Bir tanecik sevdamdı 

Gülcük açardı 

Yanaklarında bahar 

İç ve dış diyarlarında 

Bambaşka uçardı

Kupası elinde Kartal 

Bükülen dudaklarında 

Aklım erirdi 

Olduğu kadar

Hışırdayan bir yaprak 

Gülümseten bir oyun olurdu 

Ufacık ayaklarında 

Neye baksa 

Gün olurdu 

Neye kızsa 

Güz olurdu 

Ellerinde zaman 

Düşsü bir peri gibi 

Elinde görmediğim 

Bir değnek vardı sanki 

Yanında ayaklarım

Hep yerden kesikti 

Ihlamur kokardı 

Yollar 

Çalarken Çiçeklerini

Yakalanırdım ellerimde', 'Ihlamur kokardı Demi yüreğinde  Bir tanecik sevdamdı  Gülcük açardı  Yanaklarında bahar  İç ve dış diyarlarında  Bambaşka uçardı Kupası elin...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ihlamur-kokardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın beni', 'bulamazsin-beni-sair-shero-d0jgc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gelip de hatırlarsan beni

bir resimde

başkasının kollarında, başka aşklarda

küllenmiş sevda dağlarsa yüreğini

acılar düşerse içine

Bulamazsın beni aynı yerlerde

Bir gece gelirde hatırlarsan beni

Seni nasıl sevdiğimi

Çekersin ayrılığının bedelini

Bir resim, bir anı

Soğuk bir gece hatırlatırsa beni

Sil gözyaşlarını bulamazsın beni

Yanlış bir aşkı yaşayıp pişman olursan

Doğruyu bulup mutlu olursan

Bir gün benle karşılaşırsan

Gözlerin dolarsa

Bulamazsın o eski ben’i....', 'Bir gün gelip de hatırlarsan beni bir resimde başkasının kollarında, başka aşklarda küllenmiş sevda dağlarsa yüreğini acılar düşerse içine B...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bulamazsin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sensiz', 'ben-sensiz-sair-shero-j1zoj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niye ayrıldık biz sebepsiz? 

Anlamadık birbirimizi neden biz? 

Acılar artıyor sessiz sessiz.,

Sevmek daha zor şimdi sensiz..

Sen sevgisiz

Yaşam şimdi sebepsiz

Sen bensiz

Ben çaresiz

Yaşam şimdi nedensiz

Senle cenneti düşlerken herşeyimle

Yalnız kaldım cehennemde hiçbirşeyimle

Belki anarım seni başka bir sevgiliyle

Oysa hala muhtacım inan sevgine

Yalnızlık daha zor şimdi eski sevgiline...', 'Niye ayrıldık biz sebepsiz?  Anlamadık birbirimizi neden biz?  Acılar artıyor sessiz sessiz., Sevmek daha zor şimdi sensiz.. Sen sevgisiz Ya...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir bilsen', 'bir-bilsen-sair-shero-uh8yt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen bilemezsin sensiz yaşamanın zorluğunu

sen bilemezsin sensizliğin ne demek olduğunu

sen nerden bileceksin ayrılığın yalnızlığını

bir bilebilsen sevginin gücünü

bir gece yarısı yataktan kaldırıp

şiir yazdırabileceğini

bir görebilsen ümitsizliğimi

sen nerden bileceksin

aylar sonra bile seni sevdiğimi

içimde haykırdığım sessiz çığlıkları

keşke bilebilsen

SENİ HALA DELİ GİBİ SEVDİGİMİ...', 'sen bilemezsin sensiz yaşamanın zorluğunu sen bilemezsin sensizliğin ne demek olduğunu sen nerden bileceksin ayrılığın yalnızlığını bir bile...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-bilsen-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-sair-shero-okjht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülümse

Gözyaşları ile gülümse bana

Acılarla gülümse varsın öyle olsun

Elbette bir gün aşacağız

Bütün engelleri.

Ve yine güzel günler göreceğiz

Gülümseyeceğiz tüm acılara rağmen

Boyun eğmeyeceğiz engellere

Hayatın bütün karanlıklarına rağmen

Gülümseyeceğiz...

Hayata, bir çocuğa, Güleceğiz.

Ağlıyacağız  ayrılığımıza, yokluğumuza

Ama gene güleceğiz..

Bazen bir tebessüm dagıtacağız etrafa

İçimizdeki acılara rağmen

Bazen de kahkahalarımız çınlatacak ortalığı

Ama gene ağlayacağız

Kayıplarımıza, sevğisizliğimize

Yitik bir aşka ve bazen de bir filme

Hayatın zevk ve zehrini bir arada alacağız

Bir gün ölmek isteyip

Bir günde en mutlu kişi sayacagız

Kendimizi aşktan yana

Güleceğiz, ağlıyacağız

Ayrılığımıza, yokluğumuza ama

Gene güleceğiz...', 'Gülümse Gözyaşları ile gülümse bana Acılarla gülümse varsın öyle olsun Elbette bir gün aşacağız Bütün engelleri. Ve yine güzel günler görece...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gulumse-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan', 'seytan-ali-kilic-kakiz-qzvck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Paslı civileri aratmıyan diken ve pıtırak.

Her görkemli eylemde, hayatına ortak.

Ben senmiyim ki her gün gel, beraber kırıtak.

Çelme takan,dumansız ateşten yaratılan.

Tuzağına kim düşmüşse nâdim bin pişman.

Uğraşma vefa sağlamaz onunla barışman.

Marifetindir doğan çocuğa dürtüp ağlatmak.

Seni temizlemez  ne yağmur ne de ırmak.

İçimden geliyor, sana mel''ûn diye bağırmak.

Lesssines / 2004', 'Paslı civileri aratmıyan diken ve pıtırak. Her görkemli eylemde, hayatına ortak. Ben senmiyim ki her gün gel, beraber kırıtak. Çelme takan,d...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seytan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevdam-Filistin''im-Kerbelam', 'karasevdam-filistin-im-kerbelam-adnan-durmaz-b011k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göğüse sığmayan yüreklerin 

Yüreğe sığmayan sevdaların 

Karasevdalı insanlarıyız 

Ekmeği yaratmak kumdan 

Ölümsüz destanlar büyütmek

                           kanla 

                  Bize özgüdür 

Kaç bin yıldır 

Özgürlük kanadı yaralarımız 

Türkülerimiz yalım yalım hasretti 

Kana susamış yamyamlar geldi sonra 

Vampirler- it sürüleri- ölüm simsarları 

Katletmek için yaşama ilişkin ne varsa 

Ayakları paletli azrailler geldi 

II 

Yekinip 

       Yürümek istedi 

            Zincire vurulmuş dağlar 

Utandı çöl 

Utandı gök 

Yürümek istedi su... 

Kundaklarında ölüleriyle 

Yürümek istediler 

        Gidenlerin arkasından 

Gayri bir daha ölmeyecekti kuşlar 

Çiçekler açmayacaktı vahalarda 

Kimseler bilmezdi bu suskunluğu 

Ayrılığın böylesini kim yaşamıştı 

O gök değildi bu gök 

Bu ayaklar insan ayağı değildi 

Ölüm parmaklıydı işte elleri 

Kesindi 

Sönmüştü dağlarda ateşler 

İlkyaz gelmeyecekti onlar olmadan 

Gelmesindi! 

Dağlar 

Göğsünden vurulup, düşenlerini 

            Duyulmamış ağıtlarla bastı bağrına 

Ve onların türküsünü söyledi çöl rüzgarı 

Yalnız onlar gül açtırırdı kumda 

Sevemezdi böylesine hiç kimse anasını 

Yürekleri özgürlüğe susuzluktan çatlak 

Düştüler ey dost 

Düş

      tüler... 

Türkülerini

       Ağıtlarını 

            Namuslarını almış gidiyorlar 

Gayri onlar için 

Her yerdedir Filistin 

Her yerde savaşmaya gidiyorlar gene 

Dirilmeğe sürekli 

Yeniden dirilmeğe... 

III 

Susan benim yellerimdir 

Güllerimdir solan 

Kanarken ağıtlarda bir büyük destan 

Çölün en büyük hasreti 

Ben

      im

         dir Filistin'' de 

Anam kaldı o dağların ardında 

Kucağımda can veren yavuklumun 

         Son sözleri ürperir 

                  Silahımın söylediği ağıtta... 

Bu kan 

Bu dünyaya karşı inatla atan nabız 

Benim(dir)   Filistin'' de 

Hırsından çatlayan kalbim

      Öylesine bükük omzumda 

Dönüp bir yol 

-Hoşcakal-diyemedim dağlarıma

Giden ayakyarım olsun 

kalbim kalıyor

       kanıyor

           yanıyor

                toprağımda 

Hiç kimse anlamasa da 

Bu anka yeniden dirilmesini bilir 

Bombalar, mitralyözler bin kez parçalasa da... 

IV 

En eski zamanların yoksuluyum 

Binlerce yıllık sevdamı gömdüm sana 

Atalarım dağların ardında kaldı 

Yüzlerinde çizgi çizgi hasret teriyle 

O nazlı özgürlüğü yasayamadan 

          Yıkıntıları altında   ülkemin 

Ey kum! 

Binlerce yıllık susuzluğunu 

Irmak ırmak kanımla giderdim 

Kardeşlerim senin için vuruldu 

Vatanım

       Sevdam 

            Umudum dedim sana 

Vuruldukça hasretine 

İçimde yeniden can oldu kinin 

Gayri hiç bir gömüte sığmaz bedenim 

Ey haklı direniş destanlarının yoldaşı 

Ey Filistin! 

Sevgilim! 

Direnç kaynağım benim! 

Sana dünyanın en sevdalı türkülerini 

Ben yaktım! 

Benim gibi sevemez vatanını kimseler 

Bir yanım sende kaldı 

Bir yanım sana giden yollarda 

Karasevdam 

Filistin'' im 

Kerbelâm 

Neredesin sen! 

Neredesin sen!

Neredesin! ... 

Adnan DURMAZ 

Ekim-1982 

 

fısıltılarla da olsa söyle,saypa yay,ank', 'Göğüse sığmayan yüreklerin  Yüreğe sığmayan sevdaların  Karasevdalı insanlarıyız  Ekmeği yaratmak kumdan  Ölümsüz destanlar büyütmek        ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":115,"source_url":"https://www.antoloji.com/karasevdam-filistin-im-kerbelam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cizebilirmisin Yüreğine Beni', 'cizebilirmisin-yuregine-beni-karahan-yilmaz-hqk4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haritalardan adımı silsem

Antolojilerden şiirlerimi..

Sana sevdalı düşler getirsem

Cizebilirmisin yüreğine beni..

Gözlerinde 

         ilişilmemiş bir mavi olsam

Cıkarıp atsam

          ruhumdaki şu gürbeti

Gökyüzü gibi

sana sınırsız baksam

Sevdana ülke yapabilirmisin beni

11.08.2004', 'Haritalardan adımı silsem Antolojilerden şiirlerimi.. Sana sevdalı düşler getirsem Cizebilirmisin yüreğine beni.. Gözlerinde           ilişi...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cizebilirmisin-yuregine-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesizliğin', 'kimsesizligin-gokhan-oflazoglu-37fwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir hayat çekilip alınsa elinden,

köşeye kıstırılmış bir köpek

gibi öfkeli hala. Bütün aynalar

kırılsa evde birden, yüzün bile

olmasa gezdirdiğin.

Hiçbir açıklama yatıştırmıyorsa seni,

yürüdüğün yollar çukurlarla dolu ve

çürümedeysen gün be gün. Umut,

hala var diye mırıldandığın, karanlık

bir köşede üstüne saldıran yabancıdır; 

kimliğin, paran olmasa bile.

İşte eskiyen artık beklemediğin, 

usanmışlığın, üşengeçliğin.

Sabah uykusuz gözlerle karşıladığın,

bir başınalığın, kimsesizliğin.

11/08/2004', 'Bir hayat çekilip alınsa elinden, köşeye kıstırılmış bir köpek gibi öfkeli hala. Bütün aynalar kırılsa evde birden, yüzün bile olmasa gezdir...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimsesizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıncı Kıta', 'kacinci-kita-baris-pinar-tumer-5qblu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçim

bir duygular

 okyanusuysa

kalbim bir ada

olmalı...

ve ben bir kıta olmalıyım

öyleyse

atlaslarda bir ismim

olmalı...

ben bunca sevdayla

yüklüyken

bilmem kaçıncı kıta olmalıyım...

emin olduğumsa

ismim sen olmalı...', 'İçim bir duygular  okyanusuysa kalbim bir ada olmalı... ve ben bir kıta olmalıyım öyleyse atlaslarda bir ismim olmalı... ben bunca sevdayla ...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kacinci-kita-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçelerde', 'bahcelerde-gokhan-oflazoglu-fkegf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ses gelse derinden,

sorsa kimsin sen.

Hiçbir cevabım yok,

önemsiz bir ezgiyim

yalnızca dillerde ve 

nedense hergün yayılan

mesafelerde. İçerden

kavrarken yitikliğim,

görünsem dilsiz bahçelerde.

Boşuna salındığım yeryüzünde,

yüzüm giderek belirsiz,

karanlık gecelerde.

Beklerim; sıkıntı sanki 

demir pençe. Bu kahreden

oyun biter bir gün. Umarım,

açarım yeniden bilinmez

bahçelerde.

11/08/2004', 'Bir ses gelse derinden, sorsa kimsin sen. Hiçbir cevabım yok, önemsiz bir ezgiyim yalnızca dillerde ve  nedense hergün yayılan mesafelerde. ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bahcelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatıma İstek Kipi', 'hayatima-i-stek-kipi-mehmet-taha-dogruyol-k8thw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ayaklarına kapanırcasına özür dilesem

ait olamadığım her şeyden

zamanlarını aldığım bütün hayallerden.

suya akıttığım her damla kan için

tuzdan çatlak dudaklarımı öpen dilberden.

silsem ayak izlerimi

nerede olduğumu bilmediğim onca yerden.

kaçırarak gözlerimi

konuşamadığım, susamadığım, 

susayamadığım her damla terden.

bu sefer kandırmadan kendimi

kaçabilsem gölgesi yıkıntı kederden.

arındırsam pür olasıca başımı

hayaliyle uyuduğum sahte efserden.

hesap sorsam yapışıp yakasına

gözümden kaçan firari ferden.

uyuyabilsem kara yorganın altında

uyuyabilsem saklambaç oynamadan

vicdanımdaki nekir ile münkerden.

ayırıp gönülle maddeyi

yakamı silkip zerden

vazgeçmesem simberden.

kalbimin eline verip dizginleri

mantığımı kovalasam minberden.

ele verip tutuklatsam korkularımı

ve sonunda saflığı en çıplak bende bulsam

soyunup ben bildiğim avare-i kemterden...', 'ayaklarına kapanırcasına özür dilesem ait olamadığım her şeyden zamanlarını aldığım bütün hayallerden. suya akıttığım her damla kan için tuz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayatima-istek-kipi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-mehmet-taha-dogruyol-ei1o7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'soyunup da gel kendinden

günü gelmemiş tohum tazeliğinde

renk gibi gel

dünü yarını olmayan

kelebek gibi...

bebek gibi gel

meleklerle dans eden rüyalarında

mantığından uyanıp

duygulara bulanıp da gel...

eş gibi gel

dünyamı aydınlatan

güneş gibi...

deniz gibi gel

koynuna almaya hazır her an

yanlışıma bakmadan

günahıma aldırmadan...

bahar gibi gel

gül gibi

doğada bir desen gibi gel

sen gibi...', 'soyunup da gel kendinden günü gelmemiş tohum tazeliğinde renk gibi gel dünü yarını olmayan kelebek gibi... bebek gibi gel meleklerle dans ed...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adsiz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma I', 'muamma-i-mehmet-taha-dogruyol-hxm9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sensin aldanan

günübirlik düşlere saklanıp

sonun korkusundan

ya da dehşetinden sonsuzluğun

uzaklara

kaçarken kendinden...', 'sensin aldanan günübirlik düşlere saklanıp sonun korkusundan ya da dehşetinden sonsuzluğun uzaklara kaçarken kendinden......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/muamma-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma II', 'muamma-ii-mehmet-taha-dogruyol-wjfzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kim bilir bir gün

uyanacağız kan ter içinde

Bütün cevapları bildiğimiz

bir evrene

ve artık korkusuz olacak uykular

sağa sola dalgalanmadan durulmuş

bir gecenin ermişliğinde...', 'kim bilir bir gün uyanacağız kan ter içinde Bütün cevapları bildiğimiz bir evrene ve artık korkusuz olacak uykular sağa sola dalgalanmadan d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/muamma-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfırikiotuzyedi', 'sifirikiotuzyedi-mehmet-taha-dogruyol-c9l0f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarıldım yine kaleme

uykudaki son kalemi de

istila edince gözlerin...

Her türlü çılgınlığa bile değesice

geceleri olur olmaz dile gelesice

gözlerin...', 'Sarıldım yine kaleme uykudaki son kalemi de istila edince gözlerin... Her türlü çılgınlığa bile değesice geceleri olur olmaz dile gelesice g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sifirikiotuzyedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sersem', 'sersem-mehmet-taha-dogruyol-zmuem', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tam da koşuyordum ulaşmaya bulutlara

aklıma takılıp düşmesem tutardım da belki eteğinden

Gökyüzüne batıp, yer altında uçarken

takıldım gelinciğin peşine de uzaklaştım peteğimden

şapır şapır yürüdüm sularda

sırıl sırıl da sıklam oldu bastonumun paçası

gözümü aldı bulutun alacası

Ağlar gibi oldum, damladım da gözümden galiba biraz

fırladım yerimden ama yine sarılamadım ufka

Bile bile yanlış yapacağımı

denedim yine doğruyu inatla

sordum yine cevabını bildiğim soruyu

Heyecanlandım; şaşırdım aklımın aynasına

sonra vazgeçtim gerçekten

uyandım; döndüm yine düşler dünyasına', 'Tam da koşuyordum ulaşmaya bulutlara aklıma takılıp düşmesem tutardım da belki eteğinden Gökyüzüne batıp, yer altında uçarken takıldım gelin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sersem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filmi Başa Saramazdık', 'filmi-basa-saramazdik-can-ceylan-t8kbu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeryüzünde bir kul idik

Bir boşlukta yüzer olduk

Yedik içtik ve tükettik

Arkasından bakar olduk

Zevk-ü sefa içindeydik

Gün oldu per perişandık

Sonunu hiç düşünmedik

Başa gelince anladık

Nokta kadar kalakaldık

Zaman oldu donakaldık

Filmi bitirdiğimiz yerden

Tekrar başa saramazdık', 'Yeryüzünde bir kul idik Bir boşlukta yüzer olduk Yedik içtik ve tükettik Arkasından bakar olduk Zevk-ü sefa içindeydik Gün oldu per perişand...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/filmi-basa-saramazdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renk Körü', 'renk-koru-mehmet-taha-dogruyol-sw30i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fırça tutabilseydi elim

kalem yerine

daha fazlasını yazabilirdim

siyahla beyazdan

kırk dereden sıfat getirmeden

anlatabilirdim gülüşünü...

yanaklarından aşağı

bir gölgeye değerdi parmaklarım

sen kendinden habersiz

umarsızca tuvale yaslamışken sırtını...

fazlasıyla tutumlu bir buğday

serperdim tenine

beyazın himayesinde...

ve cimrilik değil mi

gözlerine saklardım

siyahın tümünü

olur ya belki

parlak olmaz yeterince ilk seferinde...

kırmızıyla beyazın aşkından

keskin bir pembeyle

öperdim dudaklarından...

ve her geriye çekilişimde

ihtimal bitirememiş olurdum

hemfikir olup fırçamla

doyamamış dokunmaya yüzüne

sen bundan habersiz ağlarken

zilzurna bir şiirin

rengarenk dizelerinde...', 'Fırça tutabilseydi elim kalem yerine daha fazlasını yazabilirdim siyahla beyazdan kırk dereden sıfat getirmeden anlatabilirdim gülüşünü... y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taha Doğruyol']::text[], 8.5, '{"poet":"Mehmet Taha Doğruyol","poet_slug":"mehmet-taha-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/renk-koru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta', 'uzakta-nurettin-ozdemir-xwsg9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Penceren iğdelerle örtülü,

İğde kokusuyla yıkanmış odan.

Sen ömrün bir defa açılan gülü,

Senin kokun gelir hep uzaklardan.

Hasretse; hasreti yüreğimde gör.

Şarkıysa; dilimde bütün şarkılar.

Geceyse; geceler içimde büyür.

Baharsa; istemem ben böyle bahar.', 'Penceren iğdelerle örtülü, İğde kokusuyla yıkanmış odan. Sen ömrün bir defa açılan gülü, Senin kokun gelir hep uzaklardan. Hasretse; hasreti...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzakta-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerindeki', 'gozlerindeki-nurettin-ozdemir-nhrp0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar mı, yaprak mı, ışık mı, su mu? 

Yoksa muhacir kuşlar gibi, sade,

Sonsuz maviliklere düşmek korkusu mu?', 'Bahar mı, yaprak mı, ışık mı, su mu?  Yoksa muhacir kuşlar gibi, sade, Sonsuz maviliklere düşmek korkusu mu?...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gozlerindeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmediğin', 'bilmedigin-nurettin-ozdemir-ur3jl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açılıp açılıp vuruyorsun

Gecelerin ağırlığınca.

Taş değil, yürek bu; 

Dayanmaz.

           Dedim ya,

Kader.', 'Açılıp açılıp vuruyorsun Gecelerin ağırlığınca. Taş değil, yürek bu;  Dayanmaz.            Dedim ya, Kader....', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmedigin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Damla', 'tek-damla-burak-killioglu-h492e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir anda bastıran,

Hiç beklenmedik bir anda yakalayan

Deli dolu bir yağmurdun.

Gönlünden taşarcasına yağdın. 

Kaçış yoktu senden..

Tek bir kuru yerim kalmadı yüreğimde,

İliklerime dek sana ıslandım.

Dur durak dinlemeyen,

Yüreğimi sellere veren bir yağmurdun.

Bir anda bastırmıştın,

Bir anda dindin.

Bunalan ruhumun kurtarıcısıydın,

Sadece tek bir damlaydın.', 'Bir anda bastıran, Hiç beklenmedik bir anda yakalayan Deli dolu bir yağmurdun. Gönlünden taşarcasına yağdın.  Kaçış yoktu senden.. Tek bir k...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız- I', 'yildiz-i-husamettin-gunacti-a33wc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saklama, korkma bakmam

gözlerindeki halkalara

inan umursamam

varsın vursun aklar şakaklara

      

yokluğunda adını heceler

dalarım dipsiz karanlıklara

ürperirim yıldızsızsa geceler

belki de kavuşamam şafaklara

         

fazla bir şey istemem; sadece

gökteki yıldızları indir bana

eğer itiraz ederse gece

sapla gitsin yalnızlığı bağrına...', 'saklama, korkma bakmam gözlerindeki halkalara inan umursamam varsın vursun aklar şakaklara        yokluğunda adını heceler dalarım dipsiz ka...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildiz-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar mısın?', 'hatirlar-misin-cafer-tayyar-ozkan-awgqk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın...? 

O, engin denizlere meydan okuyan,

Ağladığında yeşile dönen gözlerine,

Asırlara taş çıkartan sevdalı bakışlarımı...

Yüreğimizin kuzineye döndüğü,

Her tarafı sellerin götürdüğü,

Parmaklarına emanetimi taktığım yeri,

Kadınım olmanı, 

Muradıma sahiplik yapmanı istediğimi...

Hatırladın mı o sabahı? 

Hatırlar mısın...? 

Geceyle gündüzü ayıramayacak,

Aldığı her nefeste kokuları çekecek,

Belleğinde yaşadığı sevdayı silemeyecek,

Kalplerde onarılmaz iz bırakacak kadar,

Sevgiye haykırdığımız günlerin ardından,

Beni şaşırtan ve daha da bağlayan elbiseni,

Eti güzeli, saçlarının rengindeki aşk şarabını,

Aşkımıza yer eden unutulmaz şarkımızla,

Sonradan affını verdiğin busemi,

Ulu dergahta oturduğumuz masada,

Koskoca bardaklarla içtiğimiz çayın tadını,

Hüzünlü gözlerle ardımdan salladığın ellerini,

Seni çok seviyorum diye haykırarak ayrılığımızı...

Hatırladın mı o günü? 

Hatırlar mısın...? 

Sana bir söz verip de, sözümde durmadığımı,

Ardından beni hissederek aradığını,

Uzun ve yorgun bir yolculuğun sonunda,

Affeden gözlerle karşılayışını...

Toros’un yayla et mangalında,

Birbirimize sevgi dolu gözlerle bakışmıştık. 

Bir yer vardı hani, birbirimize sarılmıştık,

Bağlılık ve sevda yeminleri etmiştik,

Ardından o şehrin sokaklarında,

El ele tutuşup yürümüştük....

Sonrada gecenin karanlığına bürünmüş,

Yemyeşil parkın sokaklarında yürürken,

Bana sarılmak istediğini,

Bir ömür boyu ayrılmayalım sözlerini...

Hatırladın mı o akşamı? 

Hatırlar mısın...? 

Yine zemheride baharın yaşandığı,

Hasret rüzgarlarının sevdamız adına dindiği,

Martı çığlıklarının hayallerine karıştığı,

Mavi bir gecede bembeyaz gelinlik gibi,

Vapurun denizi yararak çıkarttığı köpüklere bakarak,

Sana son gelişimi...

Sevgi yuvamızda, aynı yerde beklerdim seni.

Ne zaman kapıdan adımı atsan,

Bir daha geri dönmeyecekmişçesine sarılışlarımızı...

Sen benim saçlarımı okşardın,

Sevgi dolu gözlerle sever sarardın,

Sana adeta yalvarırdım, bir daha ne olur gitme,

Ben ise muradımıza kavuşalım, aşk şerbetini,

Damarlarımıza karışana kadar içelim derdim...

Zaman dursun, bitmesin bu rüya diye yalvarırken,

Kırılamayacak sandığımız ayrılık zincirlerini kopartırcasına,

Kapıyı ardına kadar açık bırakıp hüzünle gidişini...

Göz yaşlarımızın sel olup aktığını...

Hatırlar mısın o günleri? 

Hatırlar mısın...? 

En son gün yine sana gelmiştim, 

Beni her gün koklayıp andığın yere,

Karşında saatlerce oturmuş, yığılmış kalmıştım.

Gözlerim hep seni istediği için,

Bakışlarını kaçırmıştın benden,

Güya bir daha görüşmemek üzere ayrılmıştık.

Daha beş saat olmamıştı ayrılalı ama

Yine telefondaki sesin “gitme” diyordu,

Gitme, seni bir daha görmeliyim...

Zaten göremeden duramazdık ki birbirimizi,

Hissetmeden yaşayamazdık sevgimizi,

Gün batmak üzereydi,

Ayrılık vaktinin geldiğini haber verircesine,

İçimize hasretin acısı ılık ılık inmişti,

Merdivenlerden inerken iki defa durmuştuk.

Önce sen öpmüştün,

Ardından birkaç adım sonra ben.

Kadınım gibi ol, inançlarını geri al yüreğine,

Benim büyük sevdamı o zaman anlarsın diyerek,

Islanan gözlerimle sana veda busesi gönderdiğimi...

Hatırlar mısın o anı? 

Elbette hatırlarsın canparçam...

Ben hiç unutmadım ki,

Bir an olsun belleğimden çıkarmadım ki,

Hayat, ne acılarla uğraşacak kadar uzun,

Ne de, bir gül ömrü kadar kısa...

Senden gelecek muradı,

Sevgi ve saygıyla geçecek, 

Ömür boyu sürecek vuslatı beklerim...

Hiç unutmadım ki canparçam....

Biliyorum ki, sen de unutmadın.

Unutamayacaksın da...

15 Mart 2003 Ankara', 'Hatırlar mısın...?  O, engin denizlere meydan okuyan, Ağladığında yeşile dönen gözlerine, Asırlara taş çıkartan sevdalı bakışlarımı... Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/hatirlar-misin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-naime-erlacin-yjdev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüdayinabit

gelir çoğumuz

hüdayinabit

gideriz bu alemden

dola beni gönlüne

aşkınla sar 

irfanınla sarmala 

sonrasını düşünme sen

dört mevsim yemyeşil

kök sarmaşık olurum 

neva bulur

nemalanırım içinde

toprağını arar nebatat

doğru yere ek beni! ...

(11 Ağustos 2004)', 'hüdayinabit gelir çoğumuz hüdayinabit gideriz bu alemden dola beni gönlüne aşkınla sar  irfanınla sarmala  sonrasını düşünme sen dört mevsim...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarmasik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görecek Daha Ne Kaldı! ! !', 'gorecek-daha-ne-kaldi-gullu-alemdar-fng5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine zifir karanlık bir gece

Ay vurmuyor sensiz

Kömür karası gözlerime

Akan göz yaşlarım kurudu 

Daha yakamozunu görmeden

Dön! ! 

Dön diyor içten bir sesle

Hakkı olmadığını bile bile

Ölmek istiyor! 

Sensiz bu bedende

Yaşayan ruhum

Gelmemelerine boğulmuşum

Biliyorum sonu yok 

İkameti değiştirse bile

Görecek daha ne kaldı! 

Sence...

Dertler bir dantel gibi

İlmek ilmek örüldü kaderime

Her ne yaşandıysa yaşandı

Felek...

Seni neden benden aldı

Dön! ! 

Ümidim sende kaldı...

(Gülnida)', 'Yine zifir karanlık bir gece Ay vurmuyor sensiz Kömür karası gözlerime Akan göz yaşlarım kurudu  Daha yakamozunu görmeden Dön! !  Dön diyor ...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gorecek-daha-ne-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular Kısırlaştı', 'duygular-kisirlasti-yuksel-onacan-71pgs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tadı kalmadı dostlar,

Yalnızlık ve hasretlık gibi duygular,

Kimse farkına varmak istemiyor ama

Çağı atlayandan bu yana

Sanal âlemde, devekuşu misâli,

Kayboldular...

Güfte doğmaz ki besteciler çalışır olsun,

Handir yeni bir Hüzzam şarkı 

Duymaz oldu kulaklar

İnternet-telefon birer cellat aracı

Duygular doğurgan değil,

Tümünü mezara koydular.', 'Tadı kalmadı dostlar, Yalnızlık ve hasretlık gibi duygular, Kimse farkına varmak istemiyor ama Çağı atlayandan bu yana Sanal âlemde, devekuş...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Önaçan']::text[], 8.5, '{"poet":"Yüksel Önaçan","poet_slug":"yuksel-onacan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duygular-kisirlasti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Kanatlı', 'islak-kanatli-aydin-yurtsever-cnn8u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ISLAK KANATLI

Güneş gülüyor

Çığlıklar içinde

Kaçışan yağmurlara

Bir damlacık buse de yanağıma

Sonra damlacıklar sağanağı

Özlem uçtu gitti bulutlarla

Islak kanatlı 

11.08.2004

Aydın Yurtsever', 'ISLAK KANATLI Güneş gülüyor Çığlıklar içinde Kaçışan yağmurlara Bir damlacık buse de yanağıma Sonra damlacıklar sağanağı Özlem uçtu gitti bu...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/islak-kanatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Bugün Ha Yarın', 'ha-bugun-ha-yarin-muammer-celik-x5k1k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geçiş tünelinde kaldım zamanın 

geçmişim arkamda karanlık 

geleceğim bir o kadar bulanık.... 

ara istasyonundayım zamanın 

gelir zamana durmayan trenler 

pişmanlık getirir inenler 

umuda gider binenler… 

biletsizim

kompartımanında zamanın 

kesilecektir 

faturası bir gün cezamın 

ha bugün ha yarın.... 

ha bugün ha yarını bekledim hep 

zaman hızla geçerken 

kaderin kurduğu can pazarında

pazarın tek müşterisi alacak beni de 

……..belki yarın... 

..belki yarından da yakın... 

Birdeli

06.08.2004

** Evren Özyılmaz dostun ”Geçiyor” isimli şiiri’ne teşekkürlerimle.', 'geçiş tünelinde kaldım zamanın  geçmişim arkamda karanlık  geleceğim bir o kadar bulanık....  ara istasyonundayım zamanın  gelir zamana durm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ha-bugun-ha-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam', 'i-ntikam-ahmet-aykol-k9ec7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırılmış camları gönül pencerelerimin

Donmuş kalbim içimdeki ayazlarda

Sabaha varmaz acılarım

İntikam zikir olur son soluğumda

Uyanmam girdiğim uykulardan

Sonbaharım çoktan kışa dönmüş

Bir ışık gelmez başka gönüllerden 

Bülbüllerim çoktan dut yemiş susmuş

Görmezde gözlerim savaş maviliğinden başka bir rengi

Bulamadım başkasında sendeki sıcaklığın  dengini

Kulaklarımda yankılandıkça adının harfleri

Güneş görmez gönlümün soğuk sahilleri

Uzaklaştıkça insanlardan nefretim artar

Herkezin hayatını mahfetmek gelir içimden

Bilmiyorum bu oyun sürer ne kadar

İntikam intikam almalıyım vakit geçirmeden

Yıkmalıyım hepinizi içimdeki sizden miras acılarım için

Dindirmeliyim yangınlarımı göz yaşlarınızla

Siz bilmeden kimden geldiğini bu düşmanlığın

Sizi teselli etmeliyim bir dost gibi sonra

Hepinizin acılarını izleyerek zevk duymalıyım

İntikamın serin sıcaklığını içimde duymalıyım

Kahkahalara boğulmalıyım savaş kazanmış komutan gibi

Yok etmeliyim gebertmeliyim hepinizi hepinizi hepinizi...', 'Kırılmış camları gönül pencerelerimin Donmuş kalbim içimdeki ayazlarda Sabaha varmaz acılarım İntikam zikir olur son soluğumda Uyanmam girdi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/intikam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semer satıcısı seni', 'semer-saticisi-seni-can-i-rfan-x3oyg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanlık taslayan semer satıcısı seni

Semer satıcılarından af ola amma 

Koyacak yer bile bulamadım seni ne yazık

Semeri nasıl kullandığını bilirsin  sen çok iyi…

İdare et sattıklarınla

Atmadı henüz  sigortam  bilemezsin? Hiç…

Derdim et peşinde olsa

Ne işim var senin gibi çöplükte

Derdim semer almaksa eğer

İnsan gibi insan var etrafta semer satan.

Şu kelimelere acıyorum sana yazmakla amma

Bil ki değer verdiğim can

Altın harflerle yazılacak  adı insan var yüreğimde…', 'İnsanlık taslayan semer satıcısı seni Semer satıcılarından af ola amma  Koyacak yer bile bulamadım seni ne yazık Semeri nasıl kullandığını b...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/semer-saticisi-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakıp Ağa', 'sakip-aga-mehmet-akbaba-th6ha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkiye’nin duayeni ağası,

Başınız sağ olsun,Erol SABANCI.

Merhuma biter mi halkın duası,

Başınız sağ olsun, Şevket SABANCI.

O bir lütuf idi, hak’tan vatana,

Has’lığıyla ün salmıştı cihana,

Ekmek verdi, milyonlarca insana,

Başınız sağ olsun, hısım akraba.

Kültür, eğitim, her alanda var idi,

Vatanına, milletine yâr idi,

Ağamızdan ayrılmak, çok zor idi,

Başınız sağ olsun, büyük SABANCI.

Bal akardı, dudağından dilinden,

Az mı tuttu fukaranın elinden,

Rabbim ayırmasın cennet yolundan,

Başınız sağ olsun, Dilek SABANCI.

Bir çok eseri var, bitmez tükenmez,

Taktir ilâhiden, gidenler dönmez,

Sakıp ağa içimizde, hiç ölmez,

Başınız sağ olsun, Metin SABANCI.

AKBABA’yım, saygı ile anarım,

Ölümünü duydum, akar pınarım,

Sabancılara,taziyelerimi sunarım,

Başınız sağ olsun, Türkan SABANCI.', 'Türkiye’nin duayeni ağası, Başınız sağ olsun,Erol SABANCI. Merhuma biter mi halkın duası, Başınız sağ olsun, Şevket SABANCI. O bir lütuf idi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akbaba']::text[], 8.5, '{"poet":"Mehmet Akbaba","poet_slug":"mehmet-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sakip-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim İstanbul', 'yetim-i-stanbul-nurettin-ozdemir-endlj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Çocukluğa, küçük şehirlere, ilk aşka, senin gidişine 

        ve İstanbul şehrinin yetimliğine dair...''

Bir zümrüt masaldı çocukluğumuz; 

Bembeyaz çiçekler söylerdi onu.

Nedir, bilir misin unuttuğumuz? 

Ömrün başlangıcı, masalın sonu.

Acısı duyulur bir yerimizde,

Küçük şehirleri hatırlamanın.

Bir sır gibi yaşar gözlerimizde,

Buğulu rüyası geçmiş zamanın.

Duaların narin yapraklarında,

Tanrı''nın yüzüne bakmadığı kul.

Bir ayet gibidir dudaklarımda,

Sen gidersen yetim kalır İstanbul.

Seninle güzeldi kubbeler şehri.

Senin yüzün kadar büyülü seher; 

Boğaz, sahil boyu, firuze nehri

Ve garip rüyalar içinde sefer.

Uzakta Küçüksu, Kandilli, Hisar.

Kimsesiz yollarda ayak seslerin.

Bana gülümsüyor, asırlık çınar

Dalları içinden mavi gözlerin.

Aşkın sahilinde böldük nasibi.

Yollar ölesiye bekler gölgeni.

Suyun ve toprağın sarışı gibi,

Şimdi bir başkalık sarıyor beni.

Ay, sarmaşıklardan gülmüyor artık; 

Işıklar düşmüyor sulara pul pul.

Şimdi yollarımın hepsi karanlık.

Şimdi her şeyiyle yetim İstanbul!', '''Çocukluğa, küçük şehirlere, ilk aşka, senin gidişine          ve İstanbul şehrinin yetimliğine dair...'' Bir zümrüt masaldı çocukluğumuz;  B...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yetim-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Aklımı Dağlara Sattım', 'aklimi-daglara-sattim-necmi-unsal-ag54t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uykularımın benden kaçtığı gecelerde

Onu kovalarken, sen aklıma  düşüyorsun.

Sensizlik bir kasırga isyankâr hecelerde

Yüreğimde karakış,  benimle üşüyorsun.

Tabirciler toplanıp bilmem hangi rüyamı,

Bilemem; hangi senli  ve benli düşü  yorsun! 

Yoksun,  bu hayat rüya; acaba bir hülya mı? 

Bu küreyi benimle niçin bölüşüyorsun? 

Bu gönlüm uçurumun kenarında,  virane.

Tam sana gelecekken, benimle düşüyorsun.

Ben aklımı dağlara sattım, ettin divane.

Usum dudaklarında hangi gülüşü  yorsun! 

24 Mayıs 2004 Pazartesi, Danimarka-Køge 23.51

7+7', 'Uykularımın benden kaçtığı gecelerde Onu kovalarken, sen aklıma  düşüyorsun. Sensizlik bir kasırga isyankâr hecelerde Yüreğimde karakış,  be...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aklimi-daglara-sattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup - 1', 'mektup-1-orhan-karahan-hsfds', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda ağır bir yüktür, hasretle geçen gecelerde…

	

Ve en ağır yükün bile altında ezilmeyen bu hamalın, inan sevdanın karşısında iki büklüm olur dizleri.

	

Ne yaşamak kaygısıdır, ne’de varoluşun anlatılmaz ifadesi. Sadece kavga adlı bir sevi rüzgarıdır, fırtına olup gözlerimize seriliveren şey...

	

Sen hayatında kezlerce kez yanılan, yanlış yapan adam! yetmedi değil mi bir serseri yıldızın peşinde koşmak, yetmedi değil mi yanlışlar, yanılmalar. Boş ver her zaman derim ya kaybettiklerine dönüp bakma diye, aslında her kaybediş kazançtır hayata dair…

Ve karşı yamaçlarda ipe çekilirken yıldızlar gecenin en karanlık saatinde, gelir yanı başımda durur inadıma öfkemin o sarsılmaz heybeti. Bizim yağmuru sevmeye başladığımızı zannettiğimiz andı, yitirdiklerimizin başlangıcı. Yeni yürümeye başlayan bir çocuğun parmak uçlarını sızlatan taşlar gibiydi. Sızısını kalbimizde hissettiğimiz sevincin kendisi...

	

Kendimizi anlatırken, insan tarafımızı yani, (unutma ki hepimizde önüne geçilmez hayvani tutkular vardır)   hep baharlardan bahsederiz. Ya kıştan, kar kıyametten, sıcak temmuz akşamlarından neden haber vermeyiz. 

	

Dedik ki sevda ağır bir yüktür, yok karşılığı, karşılıksızdır. Ne hüzündür, ne bir gülümseyiş, ne umut, ne yıkım. Ne de sen ve ben... Yok işte karşılığı. Ve aklının alabildiği ne varsa yokluk adına onunla adlandır sevdayı... 

Senden ezbere aldığım korkular gelir durur akşamları bu sensiz odaya şimdi. Göğsüme saklayıp ta gözlerini, uyuduğun o korku dolu gecelerde senden ezbere aldığım korkular. Bu defa olmaz derken, bir başka dala tutunmuşken oda kalır elinde, dağılıp gider bir avuç su gibi…

Son kuşların bu kenti terk etmesinin üzerinden aylar geçti ama hala kar vurmadı yıldızları, hala soğuktan üşümedi sahte gülüşlerimiz. Bir gül açardı gökyüzünde şubat akşamları, gitmezden önce sen ve sonra onu da bırakmadın dudaklarımızın kenarına. Öyle yalnız öyle sancılı ve işte öyle kederli düştü gökyüzüne yıldızlar.

	

Islık çalarak uyanıyorum her sabah uykulardan. Başımı dizlerin yerine yastığa yatırırken geceleri, çıkardığım maskemi takınıp yine gözlerime, alay edercesine bir bakış fırlatarak başlıyorum güne. 

Anılarımda kalan, senin değil benim anılarımda kalan sevdayı çıkarıp ceplerimden sigaramı yakıp, dudaklarımı uzatıyorum nikotinli bir sabaha...

Ve...', 'Sevda ağır bir yüktür, hasretle geçen gecelerde… 	 Ve en ağır yükün bile altında ezilmeyen bu hamalın, inan sevdanın karşısında iki büklüm o...', ARRAY['Türk Edebiyatı','Şiir','Orhan Karahan']::text[], 8.5, '{"poet":"Orhan Karahan","poet_slug":"orhan-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mektup-1-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup - 2', 'mektup-2-orhan-karahan-9daib', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Darmadağın bulutlar, gökyüzünde isyan var bu akşam. Bu senin türkün gibisi yok işte. Bakma bana öyle, saçlarını rüzgara vermeseydin ya. Ben rüzgar mıyım, ben rüzgar... Ellerin tutarken acılarını, namlunun ucunda ben olduğumu unuttun. Boş ver artık benim için giyinme o mavi elbiseni... 

	Darmadağın işte darmadağın hayat ve yoruldum, inan ki yoruldum, peşimde sürüklemekten gökyüzündeki bütün yıldızları. Sarı bir sonbahar uykusu bu uyuduğum, ve tel örgünün ötesine ait, bütün gördüğüm senli rüyalar. 

	Bu benim ülkem mi, çocuklar umuda taşır kaygılarını, bu benim ülkem mi? Yine aklımda dumanlı dağların kekik kokusu ve isyanım güle düştü bir Kürt kızının zeytin karası gözlerinde. Ey Fırat kardeşin Nil sessiz sedasız akıp gitmekte, öykülerin en kalabalığına doğru. Sen boşuna başını taşlara vurup ta çağlayıp durma. Kimseler duymuyor işte içimdeki isyanı. Duyan yok! Oysa sesimizin yettiğince bağırıp durmaktayız gecenin ortasına. Darmadağın bulutlar.

	Fırtınaya karışan sensizliğin sarı gölgesi değil artık, fırtınalar bile uykuya dalıp gitti namluda. Sessiz bir bebek uykusudur, aklımda ağlayan kadının gözyaşları, sessiz bir bebek uykusu anne. Rehin kaldı masallar Dicle''nin öteki yakasında. Varın söyleyin o sonbahar saçlıya, benim öykümü şimdi yıldızlar bile unuttu. Unutsun bu türküyü, unutsun bu şiiri ve duvardan indirsin artık o afişi…

Dağınık bir sızı oturur, yüreğimin en soğuk köşesinde, ellerinde zemheri ayazı buyar durur ve artık hiçbir yıldız aydınlatamaz şimdi geceyi. Darmadağın bulutlar, kırk yamalı. Benim gibi anne.', 'Darmadağın bulutlar, gökyüzünde isyan var bu akşam. Bu senin türkün gibisi yok işte. Bakma bana öyle, saçlarını rüzgara vermeseydin ya. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Karahan']::text[], 8.5, '{"poet":"Orhan Karahan","poet_slug":"orhan-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mektup-2-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklugunda seni aramak', 'yoklugunda-seni-aramak-sair-shero-gjy1d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aramak

Seni aramak

Sonbahar yapraklarında

Yaz yağmurlarında

Belki yoksun ama

Seni düşünüyorum

Seni aramak yeter

Seni beklemek

Geceyi beklemek

Alaca karanlığı

Ve yalnızlığı...', 'Aramak Seni aramak Sonbahar yapraklarında Yaz yağmurlarında Belki yoksun ama Seni düşünüyorum Seni aramak yeter Seni beklemek Geceyi bekleme...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yoklugunda-seni-aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O kadar çok özledimki', 'o-kadar-cok-ozledimki-sair-shero-12nn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni okadar çok özledimki bilemezsin hayatıma giren her isimde seni aradım ama bulamadım 

sen ısınmak için telaş verirken ben nerde kalsam diye düşünüyorum

sen uyurken ben sana mektup yazıyorum gecenin 1.30 da

sen uyurken ben uyuyamıyorum seni düşünüyorum

sen uyurken ben aglıyorum

sen uyandığında ben aglıyorum 

ben hep aglıyorum

ben aglıyorum sen gülerken 

ben mutsuzum sense mutlu yada öyle

ben acı çekiyorum kalbime attıgın her çizikte

ben seni çok özledim

ben beni sana verdim', 'seni okadar çok özledimki bilemezsin hayatıma giren her isimde seni aradım ama bulamadım  sen ısınmak için telaş verirken ben nerde kalsam d...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-kadar-cok-ozledimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün yüklü katarlar', 'huzun-yuklu-katarlar-sair-shero-ohmd9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece yarısı bir tren geçti

Penceremin önünden

Binsem sana götürür müydü? 

Yada seni bana getirir miydi? 

Nereye gidiyordu? 

Yolcuları kimdi? 

Lokomotifi hüzün yüklü katarlarımı

Çekiyordu...? 

Penceremin önünden bir tren geçti

Ben  ağladım...', 'Gece yarısı bir tren geçti Penceremin önünden Binsem sana götürür müydü?  Yada seni bana getirir miydi?  Nereye gidiyordu?  Yolcuları kimdi?...', ARRAY['Türk Edebiyatı','Şiir','Şair Shero']::text[], 8.5, '{"poet":"Şair Shero","poet_slug":"sair-shero","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-yuklu-katarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hatıra tesbih', 'bir-hatira-tesbih-arslan-arslan-68ewc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum diyorum

Nereden bilecektim ki? 

Bana...

Ya sabır çektirmek için

Tespih hediye edeceğini

Şimdi senin kokunu taşıyan

Senin güzelliğini taşıyan

Bu tespih..

Ellerimde

Neden,neden

Diye.

O tespihi çekiyorum

Beni asla avutmuyor

Sabır yerine ateşini körüklüyor

Ve hala...

İpi kopmadı biliyor musun

Ve ben

Ellerim tuttuğu sürece ona

Gözüm gibi bakacağım

Baktıkça daima

Seni anıp duracağım

Ve ömrüm oldukça

Seni sever gibi seveceğim

Arslan ARSLAN..........02.08.2004', 'Seni seviyorum diyorum Nereden bilecektim ki?  Bana... Ya sabır çektirmek için Tespih hediye edeceğini Şimdi senin kokunu taşıyan Senin güze...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-hatira-tesbih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cilve', 'cilve-semsi-dak-a7n0y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nazenin sevgilimin yumuşacık elleri 

Kul hatamı silip kapattı

Ben ona dedim ki,gençliğimin hevesi 

Ömrüm haşin ömrüne çattı.

Rüzgardan gülüşüyle büyüyen çiçekleri

Sinesinden koparıp kader yazıma attı.

Uzlaşma gözesinde kırılgan kimlikleri

Bir şımarık denkleme sattı.

Ufuk düş aydınlığı,ölüler mezarlığı,

Asalet seni aydınlatır.

Kulukları bükülmüş merhamet savarlığı,

Hayalini cama fırlatır.

İşgüzarlık okulu,işleme sakarlığı

Cam yüzün ardını sırlatır.

Sırlandırdığımız cam,yarasa yüzlüleri

Güzelin aksine ağlatır.

Dedi gözümün nuru,cilve ihtimalidir.

Sonlanmamış aşkla evlidir.

Vesvesenin hitamı,hükümün ikmalidir.

Cezbe yağmurunun selidir.

Gecelerin hırsızı,sahranın vahasıdır.

Yar cilvesinden ar içilir.

Pir İbrahim Ethem''in başlangıc atlasıdır.

Uğruna makamdan geçilir.

                       (3.10.2001,Kuyuluorta)', 'Nazenin sevgilimin yumuşacık elleri  Kul hatamı silip kapattı Ben ona dedim ki,gençliğimin hevesi  Ömrüm haşin ömrüne çattı. Rüzgardan gülüş...', ARRAY['Türk Edebiyatı','Şiir','Şemsi Dak']::text[], 8.5, '{"poet":"Şemsi Dak","poet_slug":"semsi-dak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cilve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Sarsaydın Bana Yeterdi', 'sen-beni-sarsaydin-bana-yeterdi-murat-demir-3fvws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu çekilmez dünya geniş ya da dar

Hepsi benim olsa neyime yarar

Toprak kokusunu sevdiğim kadar

Sen beni sevseydin bana yeterdi

Razıydım yanımda durup el gibi

İçimde esseydin ılık yel gibi

Elinde bir diken ya da gül gibi

Sen beni tutsaydın bana yeterdi

Tek seni sevmektir şanım şöhretim

Bir garip sevdadır gönül servetim

İnsan  şefkatiyle sayarak yetim

Sen beni sarsaydın bana yeterdi', 'Şu çekilmez dünya geniş ya da dar Hepsi benim olsa neyime yarar Toprak kokusunu sevdiğim kadar Sen beni sevseydin bana yeterdi Razıydım yanı...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-beni-sarsaydin-bana-yeterdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum''da Barlar Sokağı', 'bodrum-da-barlar-sokagi-sirma-mersin-4pqos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir adam! 

Ucuz parfüm sürmüş, saçını kendine göre moda yapmış 

Üzerinde marka giysilerin taklidi ile düşmüş

Bodrumun barlarına sokağına ayağı...

Etrafa bakan aç gözleri ile

Kadın,kız peşinde...

Gecenin karanlığına karışmış sesler

Tenle karışık ter kokuları içinde

Gürültülü müziklerin arasına

Sıkışmış bir sürü insan...

Boş boş dolanıyorlar, barlar sokağında...

Fingirdek kızlar bile

Süslenip püslenip

Tek tip giysileri ile sallınıyorlar, barlar sokağında...

6.8.04

            ''Bodrum Barlar sokağındaki gözlemlerim...''', 'Bir adam!  Ucuz parfüm sürmüş, saçını kendine göre moda yapmış  Üzerinde marka giysilerin taklidi ile düşmüş Bodrumun barlarına sokağına aya...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bodrum-da-barlar-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Gönül', 'yarali-gonul-nevzat-bayramoglu-hurdemi-bd1ue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sevdanın müşkülünü çekerek

Küsen değil misin  yaralı gönül

Aşıklar görünce boynun bükerek

Susan değil misin yaralı gönül

Arı gibi gezen güller bağında

Bir buse arayan yar dudağında

Rüzgar olup bazen hayal dağında

Esen değil misin  yaralı gönül

Coştun sığmaz oldun kendi kabına

Yüz çevirdin asıl muhatabına

Günlerdir yazılan aşk kitabına

Desen değil misin  yaralı gönül

Çekersin boş yere bunca zahmeti

Bilmezsin bir kere hatır kıymeti

Yüzüne gülenden tatlı sohbeti

Kesen değil misin  yaralı gönül

Kuş gibi çırpındın boşu boşuna  

Gidemedin bir güzelin hoşuna

Bin dert açan Hürdemi’nin başına

Be! Sen değil misin yaralı gönül', 'Her sevdanın müşkülünü çekerek Küsen değil misin  yaralı gönül Aşıklar görünce boynun bükerek Susan değil misin yaralı gönül Arı gibi gezen ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarali-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-nevzat-bayramoglu-hurdemi-7iy4b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylar oldu gelmiyorsun bir tanem

Istırap çekerim ben yokluğunda

Bağ bahçem kurudu virandır hanem

Gelemem diyorsun son mektubunda

Sensiz yaşadığım şu günler haram

Gittikçe büyüyor gönülde yaram

Dön gel ey sevdiğim bir kere saram

Gelemem diyorsun son mektubunda

Gözlerim gittiğin yola bakıyor

Baktıkça dalıyor yaşlar akıyor

Özlemin içimde canım yakıyor

Gelemem diyorsun son mektubunda

Divane oldum yar! Kimi der sersem

Geldiğin yollara gonca gül sersem

Daha gelmez misin canımı versem

Gelemem diyorsun son mektubunda

Hürdemiyim oldum Mecnun’dan beter

Gönül sarayımda baykuşlar öter

Etme gayrı dön gel bu kadar yeter

Gelemem diyorsun son mektubunda', 'Aylar oldu gelmiyorsun bir tanem Istırap çekerim ben yokluğunda Bağ bahçem kurudu virandır hanem Gelemem diyorsun son mektubunda Sensiz yaşa...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-mektubunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Elbet', 'dost-elbet-hifzi-ozbekmez-ed1b6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu devirde dostu bulmak marifet 

Ben çırağım sen ustasın tarif et 

Dostu bulamadan olsa da akşam 

Usanmadan aramak lazım elbet

Atışmalar ustalardan sorulur 

Vurdukça mızrabı kolu yorulur 

Dost dediğin sıkı sıkı sarılır 

Dost uğruna fedadır sazım elbet

Söylemiştim ben çırağım sen usta

Bu gönül yanmıştır dostluğa hasta

İsterse yaşayım Çin’de de Fas’ta

Ustaya haddimiz mi sözüm elbet

Şiirlerim vardır sevdaya dair

Ayrılık hasret gurbet ve sair

Ama bu işlerde ustalar mahir

Saygıyla doludur hep özüm elbet

Latifim aklıma gelir yazarım

Kimseye değmesin benim nazarım

Sevgi üzerine çarşı pazarım

Alnımda yazılı bu yazım elbet

Hıfzı ÖZBEKMEZ/Latifi

NOT: Ahmet Turan Altınsu ustaya saygı ve sevgilerimle', 'Bu devirde dostu bulmak marifet  Ben çırağım sen ustasın tarif et  Dostu bulamadan olsa da akşam  Usanmadan aramak lazım elbet Atışmalar ust...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dost-elbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-hifzi-ozbekmez-7oi9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cananım sevdiğim bir tanem gülüm

Hasretin canıma gel yetmeden gel

Sensizlik yerine kabulüm ölüm

Sinemde nefesim gel bitmeden gel

Hasretin cehennem yaşanmaz oldu

Dost düşman adımı bak anmaz oldu

Bitmeyen aşkımız söyle ne oldu

Ayrılık perişan gel etmeden gel

Sensin benim bu gönlümün sultanı

Diz çöktüm senden dilerim amanı

Ayrılığın canım değil zamanı

El alem halime gel gülmeden gel

Gözlerim karardı güneşim söndü

Sensiz bu hayatım çileye döndü

Görenler latifi hep deli sandı

Deli raporunu gel almadan gel

4 AĞUSTOS 2004 SAAT: 05:00', 'Cananım sevdiğim bir tanem gülüm Hasretin canıma gel yetmeden gel Sensizlik yerine kabulüm ölüm Sinemde nefesim gel bitmeden gel Hasretin ce...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Derin Saat', 'derin-saat-guclu-sonmez-zluln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arkanı dönmüş giderken

Ağladın mı göremedim

İçimde tufanlar koparken

‘Allahaısmarladık’ diyemedim

Gecenin en derin saati

Sessizlik dünde hapis kalmış

Yağmur ve gökgürültüsünün yarışı

Hepimizi ayık tutmakmış

Gecenin rengini gündüze kaçıran

Sabahı beklemeyen şimşeklere inat

Yaktım tüm lambaları ve katıldım yarışa

Televizyonu avazı çıktığı kadar bağırtarak

Açık penceremden giren her damla

Seninle yaşadığım bir anıyı taşısa

İçsem hepsini bir yudumda

Boğulmaya razıyım bu odada

Her gece en sevdiğin koltuğa oturup

Seni durmadan özlüyorum...

(Istanbul, Ağustos 2004)', 'Arkanı dönmüş giderken Ağladın mı göremedim İçimde tufanlar koparken ‘Allahaısmarladık’ diyemedim Gecenin en derin saati Sessizlik dünde hap...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/derin-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul', 'bul-abdurrahman-donmez-rll4y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gitmeni istiyorum,

bana doğru...

orada duruyor bedenim,

onu bul...

ruhum ardından gelecek,

sen bedenimi bulunca...

(adana, 11.08.2004)', 'gitmeni istiyorum, bana doğru... orada duruyor bedenim, onu bul... ruhum ardından gelecek, sen bedenimi bulunca... (adana, 11.08.2004)...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Dönmez']::text[], 8.5, '{"poet":"Abdurrahman Dönmez","poet_slug":"abdurrahman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten', 'biten-hasan-dogan-60sy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana ait ey yar! 

Gönül liginden küme düşüren gam.

Bu aşk artık ihtiyar.

Ne gözyaşı dökmeye verilecek anlam,

Ne de üzülecek bir hal var.

                                

                       GELİBOLU-2002', 'Sana ait ey yar!  Gönül liginden küme düşüren gam. Bu aşk artık ihtiyar. Ne gözyaşı dökmeye verilecek anlam, Ne de üzülecek bir hal var.    ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biten-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Benim', 'suclu-benim-hifzi-ozbekmez-liycg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdayın narına yandığım için

Suçlu benim başkasını aramam

Yalanları gerçek sandığım için

Suçlu benim başkasını aramam

Şimdi gülüyorlar benim halime

Deli diyen doladılar diline

Aşka tarif yazdım bin bir kelime 

Suçlu benim başkasını aramam

Uykumu gecemi böldüğüm için

Seni cana canan bildiğim için

Hasretinle her gün öldüğüm için

Suçlu benim başkasını aramam

Latifim demek ki tongaya düştüm

Terk edildim kaldım ortada  şaştım

Bir hayırsız için dağları aştım

Suçlu benim başkasını aramam

5 AĞUSTOS 2004 SAAT:08:00', 'Sevdayın narına yandığım için Suçlu benim başkasını aramam Yalanları gerçek sandığım için Suçlu benim başkasını aramam Şimdi gülüyorlar beni...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suclu-benim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamdasın..', 'sevdamdasin-i-nan-alver-1bxme', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüncelerimdeki yok oluşlarda,

Kaybolmayan sevdamdasın,

Geceye çöken karanlıkta,

Aklıma düşen sevdamdasın.

Hayallerime sığmayan,

Coşkun sevdamsın.

Gözümden akan yaşta

Çocukca sevdamdasın.

Beni bensizliğe iten,

Tutkulu sevdamdasın.', 'Düşüncelerimdeki yok oluşlarda, Kaybolmayan sevdamdasın, Geceye çöken karanlıkta, Aklıma düşen sevdamdasın. Hayallerime sığmayan, Coşkun sev...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdamdasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Yol', 'uzak-yol-erhan-kartal-9r2pj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzanktan duyarım ayak seslerimi

Kendi içimde dolanırım

Dolanır dururum 

Kördüğüm

Bir ucumdan tutup çekseniz,

Belki çözülürüm

Çözülürüm belki güneşe aciz buzlar gibi

Damla damla akar

Karışırım belki de aranıza', 'Uzanktan duyarım ayak seslerimi Kendi içimde dolanırım Dolanır dururum  Kördüğüm Bir ucumdan tutup çekseniz, Belki çözülürüm Çözülürüm belki...', ARRAY['Türk Edebiyatı','Şiir','Erhan Kartal']::text[], 8.5, '{"poet":"Erhan Kartal","poet_slug":"erhan-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzak-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesur Ol Sevdanda...', 'cesur-ol-sevdanda-i-nan-alver-05dw4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutsaklığı kıran bakışlarına

Gönlünde zindanlar kuran sen,

İzin ver! yüreklerimize,

Sevdamız çoşkun denizlere dönsün,

Kalıplara,şekillere sığmayan mısralara dönüşsün,

Hüzünleri ektiğin yetmedi mi? 

Bırak ekin vaktinde çıkıp gelen ben olayım,

Ektiğin hüzünleri gönlünde sonsuz sevdalara çevireyim

Kaçma! anılarla çizdiğin aşk oyunlarından,

Kalbine kurduğun sahnede başrolde ben olayım.

Gel bulalım birbirimizi,

Göklere yazalım ismimizi,

Hem gök,hem yeryüzü

Görsün cesurca sevmenin gücünü..', 'Tutsaklığı kıran bakışlarına Gönlünde zindanlar kuran sen, İzin ver! yüreklerimize, Sevdamız çoşkun denizlere dönsün, Kalıplara,şekillere sı...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cesur-ol-sevdanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ramak Kala;', 'ramak-kala-gullu-alemdar-uwqa8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat yirmi dörde kavuşmadan

Neyse ki bu günden de

Geriye kalan bana 

Üç ayrı duygu seli

Demiştim ya! 

Yeni bir güne 

Diğerinden kalma

Sevgi artıkları

Bulmak dileğiyle

Sarılın kalemlere

Dökülsün semadan

Sevgi nurları 

Açılsın Gül nidalarla

Şiir cennetinin kapıları

(Gülnida)', 'Saat yirmi dörde kavuşmadan Neyse ki bu günden de Geriye kalan bana  Üç ayrı duygu seli Demiştim ya!  Yeni bir güne  Diğerinden kalma Sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ramak-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir...', 'bir-siir-necmiye-sarpkaya-yny5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazacağım bu akşam 

Aşk sevda üzerine

Hüzünlerin olmadığı

Bir şiir yazacağım

Özlemleri bulunmayan

Ayrılıklar yaşanmayan

Gurbete uğramayan trenleri

hep sevenleri kavuşturan

Bir şiir yazacağım

Sade süssüz yalın ve gerçek...

İnsanları sevgi umut dolu ihanet tanımıyan

Bir şiir yazacağım

Aşıkların aşklarını gönlünce yaşadığı

Çiçekleri her dem taze kalan

Bir şiir yazacağım bu akşam

Sitem  efkar tanımayan

kuşları tuzaklara avcılara yakalanmayan

Bir şiir yazacağım

karanlık hüzün ve acı tanımayan

Sadece aşk ve sevda yüklü 

Bir şiir yazacağım

Bu akşam', 'Bir şiir yazacağım bu akşam  Aşk sevda üzerine Hüzünlerin olmadığı Bir şiir yazacağım Özlemleri bulunmayan Ayrılıklar yaşanmayan Gurbete uğr...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-siir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-ali-fikri-karadeniz-l8dqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutları seyrediyorum bir bir; 

Kimi siyah, kimi beyaz

Kiminin rengi bilmem ne.

Kimi sevgi yüklü,

Kimi özlem, kimi hasret

Ha bir de ihanet! 

Öylesine gelip geçiyorlar başımın üzerinden...

Bulutları seyrediyorum bir bir; 

Ellerimle tutmak istiyorum,

Pamuk gibi avuçlarıma almak,

Ve dudaklarımın arasından üflemek istiyorum

Sevgiyi Dostlarıma

Özlemi yeni aşıklara

Hasreti analara - babalara...

Bir tek; 

İhanet bende kalsın; 

Çünki o benim,

Çöl yalnızlığımda beni ıslatsın...!', 'Bulutları seyrediyorum bir bir;  Kimi siyah, kimi beyaz Kiminin rengi bilmem ne. Kimi sevgi yüklü, Kimi özlem, kimi hasret Ha bir de ihanet!...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bulutlar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın', 'i-nsanin-serkan-yildirimoglu-is1dd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen işte böyle bir an

Yüreği daralır sığmaz kabına

Silinir benliğimden sinirim

Yazası gelir kağıda insanın

Gözler kapalı donuklaşır renkler

Ağlamaklı olur yürek pınarı

Kan akmaz taşlaşır damar

İsyanlı bir sukut dilinde insanın

Devire uyu yaşamak varken

Ölümlere kafa tutmak nasipken

Yollar seni ölüme çağırıyorken

Koşmak arzusuna düşer ayakları insanın

Daha dün gibi yaşandı eylül

Bir bir asıldı dar ağacına insanlar

Kurumadan yerdeki kanı Özmenin

Bir kurşun önüne atılası gelir insanın

Bilinir ananlar tek tek ağlayacak

Çocuklar, eşler yollara baka kalacak

Gelecek kaygısı beyni kavuracak

Bırakıp her şeyi gidesi gelir insanın

Neden çok, niçinler hesap

İnsanlar kurban olmuş sistemler kasap

Uymaz yinede bize ne çarşı, ne hesap

Düzeni bozup, yıkası gelir insanın

Gönlümüze göre yer yok ise

Ölüm bahçeleri viran, gül ise

Bu gece bizlere yolculuk var ise

Durmadan gidesi gelir insanın

			10.08.2004', 'Bazen işte böyle bir an Yüreği daralır sığmaz kabına Silinir benliğimden sinirim Yazası gelir kağıda insanın Gözler kapalı donuklaşır renkle...', ARRAY['Türk Edebiyatı','Şiir','Serkan Yıldırımoğlu']::text[], 8.5, '{"poet":"Serkan Yıldırımoğlu","poet_slug":"serkan-yildirimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/insanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutmayın Beni', 'tutmayin-beni-talip-kaplan-gdpcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her koyun kendi bacağından asılır

Sen kendi urganını sağlama al

Eğer ben ipin ucunu koparırsam

Sadece tut, kaldırmaya çalışma

Ve bana tırnaklarını geçirme

Ellerinin arasından kaymama fırsat ver.

Bu arada senin ipin zaten inceldi

Koparma, sımsıkı kavrayıpta beni.

Bırak sadece ben düşeyim

Bırak sonsuz yolculuğa ben gideyim

Dipsiz düşünce çukuruna ben düşeyim

Yaydan çıkan bir ok misali,

Dönüşü olmayan yola ben gireyim.

Kurtulayım ensemdeki sabit urgandan

Kurtulayım, tutup salmayan o halattan...

(04 Şubat 1994)', 'Her koyun kendi bacağından asılır Sen kendi urganını sağlama al Eğer ben ipin ucunu koparırsam Sadece tut, kaldırmaya çalışma Ve bana tırnak...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutmayin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklugunda', 'yoklugunda-sair-oben-04dvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoklugunda geceleri sevdim en cok 

Sensiz yıldızlara bakmak bile cok zor olsada

Ama gördügünü bilmek aynı yıldızları 

İste bu teselli oluyor bana

Yine bakıyorum yıldızlara 

Ne kadar isterdim kalbimi vermek onlara

Sen dolu sıcacık kalbimi

Küt küt atardı sana

Sende görürdün gökyüzünde

Gülsem mi aglasam mı olurdun

Dolu dolu bakardı gözlerin

Kaydırırdı bakısların o yıldızı gökten 

Sunardın bana askınla

Ne güzel olurduk ya

Yoklugunda geceleri sevdim en cok', 'Yoklugunda geceleri sevdim en cok  Sensiz yıldızlara bakmak bile cok zor olsada Ama gördügünü bilmek aynı yıldızları  İste bu teselli oluyor...', ARRAY['Türk Edebiyatı','Şiir','Şair Oben']::text[], 8.5, '{"poet":"Şair Oben","poet_slug":"sair-oben","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoklugunda-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyeceğim Hayatı', 'yuruyecegim-hayati-oguzkan-bolukbasi-kcf8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kız oynayacak bahçede 

basma entarili bir kadın 

buram buram karışık kokularda 

çocuklar salya sümük 

eve geldin mi gelmedin mi 

bilen yok 

yürüyeceğim hayatı kurtulacağım 

büyüyeceğim 

pantalonum kemerli olacak 

saatim köstekli 

hayallerimi sıraya dizeceğim 

bir gün seninle 

birgün başkasıyla gezdireceğim 

yürüyeceğim hayatı kurtulacağım 

şarkıları ben çaldıracağım 

sabah olacak çiçekleri uyandıracağım 

mavi bir gömleğim olacak 

ne mavisi diye soracaklar 

benim adımın mavisi olacak 

ben maviye ad olacağım 

yürüyeceğim hayatı kurtulacağım 

anılar peşime takılacak 

her adımda anılar bir ordu gibi çoğalacak 

birileri gelecek anlatacağım 

anılarım öykü olacak 

öykü benim anılarım olacak 

yürüyeceğim hayatı kurtulacağım 

09.04.2003', 'bir kız oynayacak bahçede  basma entarili bir kadın  buram buram karışık kokularda  çocuklar salya sümük  eve geldin mi gelmedin mi  bilen y...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yuruyecegim-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın ne olduğunu Buldum', 'askin-ne-oldugunu-buldum-huseyin-cayikli-s84s6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'siz hiç aşkı yarım zamanınızda tanıdınızmı.geçen aylarda ben tanıdım...herşeyi tadıyormuş insan.sevgi nefret hüzün alçak gönüllülük...hepsini bir arada yaşıyorsunuz...savaşarak sevişmek gibi...ve aradan geçen zamanda bir şey öğretti hayat...Aşk nedir...bir mucit gibi sevindim bunun cevabını bulunca.........Aşkın anlam yükleri boşunadır...Aşk bir şehrin sokak çocukları gibi yapayalnızdır aslında...ıslanmışlığınızın suretidir yağmurlar şahittir ceketinizin haline ve yağmurlar suçludur...Aşk nedir...aşk aslında saçmalıktır...korkaklığın ve cesaretin buluştuğu tek noktadır...Aldanmışlığın sevinciyle kendinizi kandırmanızdır ve bunu bile bile her defasında tekrarlamanızdır...sabahlara kadar uyumamanız her geceyi yıldızsız kapatmanızdır...Aşk cinsellikle başlar sevişmelerin en ayıbını ve sınır tanımadan yaptığınız hayvani duygudan kaynaklanmaz...kanıtlayamazsınız bu savaşı...Aşk sevişmektir aslında hüzünle,acıyla,tenle,ruhla sevişmenizdir...Sınır tanımayan ayıp bilmeyen tek sığınağınızdır...Şimdi bana sorarsanız aşk nedir

Aşk seviştikten sonra Orgazm Olmaktır her daim yapamadığımız...', 'siz hiç aşkı yarım zamanınızda tanıdınızmı.geçen aylarda ben tanıdım...herşeyi tadıyormuş insan.sevgi nefret hüzün alçak gönüllülük...hepsin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/askin-ne-oldugunu-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Temmuz', 'on-temmuz-gulsen-senderin-gqd8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'On Temmuz akşamıydı, Kıbrıs''tan geldim sana

Bir çift yeşil göz idi, şevkle kalbimi çelen

İstanbul Ataköy''de sevgili oldun bana

Ne dert bildik ne keder, sevdaydı ngalip gelen! 

Hürriyet''in ''kelebek'' eki ile tanıştık

''BEBEK'' rumuzu ile duyguları paylaştık

Efsunkar bir sevdayla kalbten kalbe ulaştık

Ne dert bildik ne keder, sevdaydı galip gelen! 

Bindokuz yüz yetmişdört, yazıştık biz seninle

Telefon, telgraf,kaset...aşkı ördük yeminle

Yirmi dört yıl yaşadık unutulmaz sevginle

Ne dert bildik ne keder, sevdaydı galip gelen! 

Dünyada en mutlu çift bizdik sevgiyle gülen

Hoşgörü cennetinde insan kıymeti bilen

Yoktu başka sevgili biz gibi aşka ölen

Ne dert bildik ne keder, sevdaydı galip gelen! 

Yüreğimde anılar, başımda sevgi tacım

Üç yavru bir torunla; İpek Aşkım, Ağacım

Çatlamış toprak gibi sana her an muhtacım

Ne dert bildik ne keder, sevdaydı galip gelen! 

Bu gün yine ''ON TEMMUZ'' gözlerimde kanlı yaş

Selviler diyarına, sana koştum pür telaş

Yıllar geçse de bitmez tutkuna olan savaş...

Ne dert bildik ne keder, sevdaydı galip gelen! 

10.07.2004.Cumartesi

Bakırköy / İstanbul.', 'On Temmuz akşamıydı, Kıbrıs''tan geldim sana Bir çift yeşil göz idi, şevkle kalbimi çelen İstanbul Ataköy''de sevgili oldun bana Ne dert bildi...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/on-temmuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül bahçem perişan', 'gonul-bahcem-perisan-orhan-tuncay-lkqcs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbüller şakırken şen, gül bahçelerinde

Hüznünle perişan gönlüm yine sensizliğinde

Dalarım bazen bülbüllerin güllerle meşkine

Sorarım sevgili  yarim şimdi hangi gönüllerde

Yanarım, ah yanarım şu kalbimdeki ateşinle

Durduramaz kanayan yaramı bülbüller de

Akar kan gönlümden, hem dem olur güllerle

Açtırır aşk çiçeklerini tam da bu mevsimlerde

Yanarım, sorarım, ararım seni hayallerle

Teselli ararım, bulamam bülbül namelerinde', 'Bülbüller şakırken şen, gül bahçelerinde Hüznünle perişan gönlüm yine sensizliğinde Dalarım bazen bülbüllerin güllerle meşkine Sorarım sevgi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonul-bahcem-perisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 7', 'rubai-7-emirhan-bala-l18q6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şiir denirse eğer satırlarımıza, 

ilginiz bizim baştacımız. 

şair derlerse girmeden mezara, 

bilinki, gittiğimiz yerde de yazarız...', 'şiir denirse eğer satırlarımıza,  ilginiz bizim baştacımız.  şair derlerse girmeden mezara,  bilinki, gittiğimiz yerde de yazarız......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-7-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Morga Kaldırılsın...', 'sevgi-morga-kaldirilsin-i-brahim-ethem-bingul-rvg64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var olan güzellikler

İnsan eliyle

Kirlenmemeli...

İnsan benliği

Tanımalı kendini

Ve insanlığını bilmeli...

Kinin ve nefretin dişleri

Miras kalmamalı kimilerine...

Saldırmak,

Isırmak,

Parçalamak

Her dönemin vahşilerinde vardı...

İnsan,olgunluk merhalesinde

Bir arpa boyu da olsa

İleri gitmeyecekse

Adı insan olmamalıydı...

İlim ve ilerleme

Teknoloji ve gelişme

Sevgiye yön göstermeyecekse...

Sevmek ve sevilmek

Bu topraklarda boy salmayacaksa...

Sevgi

Morga kaldırılsın

Açıkta kalmasın

Kokmasın...

www.iebingul.com', 'Var olan güzellikler İnsan eliyle Kirlenmemeli... İnsan benliği Tanımalı kendini Ve insanlığını bilmeli... Kinin ve nefretin dişleri Miras k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgi-morga-kaldirilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taştan Heykelin', 'tastan-heykelin-ali-gencay-gnrye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I-

yok! ! 

yok oluyorum

her gün doğumu 

yok

olduğunda

II-

Ah! ! 

bilsen kıvranışlarımı

dokunamazsın

göz yaşlarıma

tenimin buz kesmişliği

ürpertemez ki seni

ben

taştan yontulmuş heykelim

duyamazsın 

kilit vurulmuş

mermer dudaklarım

bedenim

III-

Hani! ! 

Kaderim ya

hüzün dağının zirvesine dikilendim

göğüslenen zemherim miydi? 

yoksa sensizliğim mi? 

bilen 

bendim

kuru yeller esti

yırttı tenimi

yağmurlar yağdı tepeme de

kupkuru kesildim

sarsıldı yer

salladım sersemliğimdi

üşüdüm geceleri

ayaz değildi sebebi

sendin

IIII-

kırdılar

kollarımı,bacaklarımı

başım

kaç kıta uzakta 

bilmem

yok! ! 

yok olmayacağım

olsa da bedenim

taştan mabedinin 

temelindeyim', 'I- yok! !  yok oluyorum her gün doğumu  yok olduğunda II- Ah! !  bilsen kıvranışlarımı dokunamazsın göz yaşlarıma tenimin buz kesmişliği ürp...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/tastan-heykelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simdilerde...', 'simdilerde-belfin-esra-sen-b1u36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''çok zaman oldu ''diye basliyo artik siirlerim 

herseye gec kalmisligim var simdilerde 

ve doyulmayan, dayanilmayan, muhurlenmis, pas tutmus yasanilmisliklarim.. 

boylesine bir ozlemdir sana yazacaklarim, tatmini olmayan 

anilardan baska..

aslina bakarsan artik, 

ne takatim, nede cesaretim var 

dolu dizgin, dort nala kosusturmali, 

mavi, yeni bir aska 

simdilerde yasanilmamisliklara 

ölesiye pismanliklarim var 

'' Ay karanlik! 

bilsen nasil zehir zikkim cigaram 

yine bir cehennem var yastigimda 

gel artik! ! ''demistin bir keresinde. 

bilmem hangi sairin, kaçinci dizelerinden, bize uyan

yakismis iste.. 

çagirma beni, yorma 

bilirsin gelemem 

imkansizliklar yoluma barikat kurarda, 

yollamaz, geçirmez beni tel orgulerinden.. 

simdilerde bir imkansizliklarim varki; sen cagirma, ben gelemem... 

dunyanin herhangi bir sehrindeyim, 

sana yaziliyor tum anlami olmayan siirlerim..

simdilerde bir hasretin var 

birde, 

seni gormeden topraga karisma korkusu.. 

simdilerde bir SEN varsin 

bir hasretin 

bir pismanlik 

bir imkansizlik... 

degilmi ki sen olmadan yasayarak,

 olecegini bilen bir BEN varim, 

sen soyle! 

ben artik yoruldum 

soyle! de! 

''bu sana kocaman bir haksizlik'' 

simdilerde bir....bende yokum 

biliyorsun.......', '''çok zaman oldu ''diye basliyo artik siirlerim  herseye gec kalmisligim var simdilerde  ve doyulmayan, dayanilmayan, muhurlenmis, pas tutmus ...', ARRAY['Türk Edebiyatı','Şiir','Belfin Esra Şen']::text[], 8.5, '{"poet":"Belfin Esra Şen","poet_slug":"belfin-esra-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/simdilerde-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamadığım', 'yasayamadigim-burcu-ayan-v52va', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boğazımda düğümlenen kelimeler

Haykırmrk isteyip de içimde kalan sözcükler

Gözlerimden dökemediğim göz yaşı

Sen benim yaşayamadığımsın.

Gittikçe sonu gelmeyen yol

Düşündükçe içinde çıkamadığım sorular

Sevdikçe bitmeyen bir aşk

sen benim yaşayamadığımsın.', 'Boğazımda düğümlenen kelimeler Haykırmrk isteyip de içimde kalan sözcükler Gözlerimden dökemediğim göz yaşı Sen benim yaşayamadığımsın. Gitt...', ARRAY['Türk Edebiyatı','Şiir','Burcu Ayan']::text[], 8.5, '{"poet":"Burcu Ayan","poet_slug":"burcu-ayan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasayamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Diyeti', 'askin-diyeti-leyla-ayyildiz-g4be8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadehler sır vermezmiş...

Buz kesermiş rakı, konuşmazmış.

Şarabın gözlerine kan otursa; 

‘kızıllığım’ dermiş.

Tiril tiril yalnızlık gömleği mi üzerimdeki? 

Damarlarımda dolaşan alkole rağmen üşüyorum. 

Yüreğime kurulmuş orkestra

en içli nağmelerini çalıyor bu gece.

Gönül teli miydi titreyen? 

Yıllardır sessizce sızlarken,

bu gece en içli şarkısını yüksek sesle söylemek istiyor.

Tüm sesleri susturun,

izin verin sadece o çalsın bu gece.

Kayıp diğer yarılarını bulmak için

acımasız bir yolculuğa çıkanların 

kimileri ruhlarını pörsüttü,

kimileri ise bedenlerini...

Bir kez ‘diğer yarısını’ bulup,

kaybedenler için ise 

durum daha da kötüydü; 

onlar bir daha hiç iflah olamadılar...

Önüne setler vurulamayacak kadar hızlı akar aşkın seli,

kesemezsin.

Bir akmaya başladı mı,

durduramazsın. 

Öyle hızlı gelir ki; 

ne geleceğinden haberin vardır,

ne onu karşılamaya hazırlanmışsındır.

Kapıyı çalmadan içeri girer.

Darmadağınıksındır. 

Gözlerine bakarsın.

Yakıcı bir ateş kavurur önce.

Göğüs kafesin kanatlarına dar gelmeye başlar.

Her çırpınış dışarıdan görünecek kadar büyüktür.

Yüreğinden ılık bir kan yayılır bedenine.

İlahi bir tını şarkı söyler.

O andan itibaren tüm evren seninle barışmıştır.

İçinde tek bir leke olmayan,

evrenin en temiz duygusuyla tanışmışsındır.

İşte o aşktır. 

Artık sen, aşıksındır.

Önce; bir aşkın küllerini 

ancak yeni bir aşkın ateşi savurur, dersin,

küllenmesine yardım etmek için

üzerine başka ruhlar serpersin.

Her yeni yüz bir aldanıştır.

Her yeni söz gerçek aşkı unutturmaya çalışan 

sabun köpükleridir. 

Ruhun sağa sola çarpar. 

Canın acır. 

Bir yara sızım sızım sızlar.

Sürekli ince bir kan sızar,

durduramazsın... 

Geceler boyu hıçkırıklarla ağlarsın...

Kimi zaman başını ukalaca yukarı kaldırıp,

Aşka kafa tutmaya kalkarsın. 

Dalga geçersin tüm yaşamla.

Canın daha bir acır.

Tek bir damla içmeden

aşk şiirleri, sarhoş aşk hikayeleri yazarsın.

Burnun yeterince sürtülmüştür; 

yüreğini nadasa bırakıp,

yazgının zamanını beklersin. 

Artık bir çok baharı seve seve ıskalarsın.

Aşkla asla aşık atılmayacağını öğrenirsin.

Hiç bir iz ruhuma atılan çiziklerden

daha derin olmayacak.

Ruhumun kanadığı kadar,

hiçbir uzvum kanamayacak.

Heyy hayat! 

İşitebiliyor musun beni? 

Aşka ait olmayan ne varsa alın götürün,

uzaklaştırın benden.

Gerçek aşkın üzerine 

yeni satırlar yazdıramayacak

hiçbir yeni duygu çıkmasın karşıma.

Tüm, aşk dokunmuş masaların hesapları benden garson! 

Diğerlerini iki misli ödet.

Hatta üç, hatta dört...

Şu da aşkın diyeti,

onu da al, sonunda ödüyorum.

Eğer üstü varsa, kalsın...', 'Kadehler sır vermezmiş... Buz kesermiş rakı, konuşmazmış. Şarabın gözlerine kan otursa;  ‘kızıllığım’ dermiş. Tiril tiril yalnızlık gömleği ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/askin-diyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam şansı', 'yasam-sansi-burcu-ayan-nu0cz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birden için anlamsız bir ürpertiyle dolar

Ve yüreğin sana bir şeyler anlatmaya başlar

Bilki o anlar, bir bitişin son anlarıdır

Bir film gibi geçer yüreğinden.

Birden ''keşke'' dediklerin gelir aklına

İşte yapmak isteyip de yapamadıkların

Ya da yapmadıklarındır o keşkeler

Kısacası sürekli ertelediklerindir.

Son bir şans dilersin talihinden 

Ertelenmiş bie yaşam ağır gelir çünkü.

ama size verilen fırsatları teptiğiniz gibi

şansınızda geri yeper o anda.

Marifet son anda şans dilemek olsaydı

Keşkeler hiç olur muydu yaşamda.

İnan yaşam çok kısa ve bir şansın var.

İşte yaşamın o şansı nasıl değerlendirdiğine bağlı.', 'Birden için anlamsız bir ürpertiyle dolar Ve yüreğin sana bir şeyler anlatmaya başlar Bilki o anlar, bir bitişin son anlarıdır Bir film gibi...', ARRAY['Türk Edebiyatı','Şiir','Burcu Ayan']::text[], 8.5, '{"poet":"Burcu Ayan","poet_slug":"burcu-ayan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasam-sansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafes', 'kafes-zulfikar-yapar-kaleli-va2xf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güllere rüzgar esse bülbüle nefes gelir 

Dalında bülbül ötse güllere heves gelir 

Nerde bir bülbül görsem aklıma kafes gelir 

Kaleli hayıflanır, ağlamaklı ses gelir.', 'Güllere rüzgar esse bülbüle nefes gelir  Dalında bülbül ötse güllere heves gelir  Nerde bir bülbül görsem aklıma kafes gelir  Kaleli hayıfla...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kafes-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azcık Yağmur Yağsa', 'azcik-yagmur-yagsa-bekir-mutlu-gokcesu-07tqb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Puslu bugün hava

Benzemez Ağustos’a

Hani yazla güz ortasında

Kalmış bir karasızlıkta

Bahardan kalma yaprakları

Yemyeşil ağaçların hala

Salınırlar hafif bir rüzgarla

Durağan bir gün titreşir

“Sorgulama, koşma, yorma”

Fısıltıları ile kulaklarımda

Ortalarda kalmış gibiyim

Ortalamalarımın ortasında...

Zamanların ortasında

Mevsimlerin ortasında

Sevdaların, heyecanların

Ne varsa her şeyin ortasında...

Bir yanım baharlarda kalmış 

Güz yollarındayım sonuçta

İçimde sıkılmıyor aslında

Fakat puslu bugün hava

Benzemez Ağustos’a

Hani diyorum şöyle

Azcık yağmur yağsa...', 'Puslu bugün hava Benzemez Ağustos’a Hani yazla güz ortasında Kalmış bir karasızlıkta Bahardan kalma yaprakları Yemyeşil ağaçların hala Salın...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/azcik-yagmur-yagsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Son Sevdiğim', 'en-son-sevdigim-yuksel-kasim-p7gnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni vurduğunda on yedi yaşındaydım.

Tam on yedi yaşında…

Ne bir eksik,ne bir fazla.

Sinesinden vurulmuş

Bir serçe gibi çırpındım; 

Korkarak,ürkerek baktım alıcı dünyaya.

Sonra boş bir bakış yansıdı gözlerime…

Elveda dedim.

Elveda,en son sevdiğim

Seni ilk gördüğümde

Umut vardı gözlerinde

Yağmur hüzün olup

Değmişti saçlarına

Ve ayrılık vardı ellerinde

Ayılığa boş verdim

Ummanlar gibi gönlüm vardı

Korkmadım

Bırakmadım kendimi

Sensiz gecelerde

Yenilmedim ümitsizliğe

Aldırmadım ellerine

Bu defa yenilmem dedim kaderime

Hançerini bağrımda taşıdım

Aldırmadım sensizliğe

Ayrılığı takmadım

Ve bir gün

Bir serçe kuşundan öğrendim sevmeyi,

Kaderi öldürmeyi.

Beni vurduğunda onyedi yaşındaydım.

Tam onyedi yaşında…

Ne bir eksik,ne bir fazla.

20 Ekim 1998

Buca', 'Beni vurduğunda on yedi yaşındaydım. Tam on yedi yaşında… Ne bir eksik,ne bir fazla. Sinesinden vurulmuş Bir serçe gibi çırpındım;  Korkarak...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/en-son-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık(2)', 'yalnizlik-2-fetih-sait-akkaya-95nw2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eski bir yara gibi fotograflar

kanatır yüreğimi

her rüzgar aşkımızı alır götürür.

her yagmur gözlerin olur bugün

seni sevmek yeni yalnızlıklara gebedir

uzayıp giden yolları beklemek gibi

seviyorum seni başka yolu yok

yüreğimde yeni acılara yer var

diyetini ödemeye hazırım....

şiirlere vururum derdimi 

kimi zaman benden uzak fotoğraflarınla

günlerdir peşim sıra anılar

susmak bilmiyor; 

hep seni hatırlatıyor

şiirlerim ertlenmiş hüzünleri taşıyor

acılar sarmış beni günboyu

yinede bu kentin en tenha yeri benim kalbimdir

seni beklemekte....

en güzel anıları yazdım

sana gül aldım getiremedim

bedenimde bir ateş yandı gün boyu

seni düşünmekten......

biliyorum seni sevmek; 

yeni yalnızlıklara alışmaktır

bazen seni beklemenin yalnızlığıda güzeldir...', 'eski bir yara gibi fotograflar kanatır yüreğimi her rüzgar aşkımızı alır götürür. her yagmur gözlerin olur bugün seni sevmek yeni yalnızlıkl...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizlik-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregin yansın', 'yuregin-yansin-fetih-sait-akkaya-7k5nr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben kendimi aşkınla bildim

seni çok sevdim olesiye kadar...

senin de beni sevdiğini sanmıştım

ama...

bana olan aşkın sanki bir dumanlık sigaraymış

ve anladım ki yalancı baharım

sigaranın son dumanındabitecekmiş

sana tapan bu yürek..

acılara boğup gittiğin bu gonul

sana acımayacak 

ve

senin yaktığın sigarayı sana 

sana olan ciddi duygularımı hiçe saydığın

kalbine basacak 

basacakkii..

seninde yüregin YANSIN...', 'ben kendimi aşkınla bildim seni çok sevdim olesiye kadar... senin de beni sevdiğini sanmıştım ama... bana olan aşkın sanki bir dumanlık siga...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregin-yansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Sonsuza Kadar', 'sevgi-sonsuza-kadar-hasan-can-8jrqb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kadarmıydı bahsederken ağladığın sevgin.

Bu kadarmıydı anlatırken hayale daldığın gerçeklerin.

Neydi söylemeye çalıştığın da söyleyemediğin

Bumuydu, yada böylemiydi en büyük olan.

Deliler gibi sevmen,

Sevdiğini haykırman,

Haykırırken ağlaman,

Bunlar senden geriye kalan.

Unuttun değilmi geriye kalanları,

Yaktın o güzelim anıları,

Sildin erişilmez hatıraları,

Öldürdün bütün duyguları.

Sevda üç kuruşluk bedenler de yaşamaz,

Duygu sahte gözler de yaş olup akmaz,

Aşk bitse de yaşananlar ölmez,

Sevgi sonsuza kadar bitmez.', 'Bu kadarmıydı bahsederken ağladığın sevgin. Bu kadarmıydı anlatırken hayale daldığın gerçeklerin. Neydi söylemeye çalıştığın da söyleyemediğ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-sonsuza-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz elem doluyum', 'sensiz-elem-doluyum-fetih-sait-akkaya-350nt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgi doluyum ben fani dünyada

yine benimlesin rüyalarımda

aklımda fikrim de hemde canımda

inan ki sevgilim yalnız sen varsın

sensiz günlerde elem doluyum

hasretin azap sensizlik olüm

vücudum sen bedenim sen,kanım sen

inan ki sevgilim benliğimde sen varsın

yıllarca bekledim bir çift söz için

ağladım inledim mutsuz,umutsuz günlerim için

sen gelmeyeceksin biliyorum 

tek umudum vardı inan tek sendin 

ama 

onuda ALLAHA saklıyorum 

saklıyorum...

saklıyorum..', 'sevgi doluyum ben fani dünyada yine benimlesin rüyalarımda aklımda fikrim de hemde canımda inan ki sevgilim yalnız sen varsın sensiz günlerd...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-elem-doluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlıklarım', 'cigliklarim-hasan-can-14d31', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyduğun da çığlıklarımı

Sana benden birşeyler kalacak

Duyduğun çığlıklar unutulmaz

Kulaklarından beynine dalacak', 'Duyduğun da çığlıklarımı Sana benden birşeyler kalacak Duyduğun çığlıklar unutulmaz Kulaklarından beynine dalacak...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cigliklarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-fetih-sait-akkaya-u3nec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dost; 

saksıda çiçek

dost; 

sevgi dolu

dost; 

bir çift sözden çok sevendir,

DOST; 

senin sevdiğinden çok sevendir', 'dost;  saksıda çiçek dost;  sevgi dolu dost;  bir çift sözden çok sevendir, DOST;  senin sevdiğinden çok sevendir...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dost-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-fetih-sait-akkaya-6egq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin yokluğunda ne acılar çektim ben 

gözlerimde çiğ damlası 

gözlerimde umut paresi 

hani bir gün sende gelirde seversin diye

bırakıp gittiğin günden beri 

yarılı kalbimle 

öyle seni beklemekteyim

hani bir gün olsun 

sende gelirde bir gün olsun 

BENİ SEVERSİN DİYE', 'senin yokluğunda ne acılar çektim ben  gözlerimde çiğ damlası  gözlerimde umut paresi  hani bir gün sende gelirde seversin diye bırakıp gitt...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoklugunda-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse kıyamaz', 'kimse-kiyamaz-fetih-sait-akkaya-c9qy9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'para gerçek derlerse inanma

isyan ettim hayata

yıllar sonra..

ama 

ne sen nede ben 

kimse kıyamaz aşkımıza', 'para gerçek derlerse inanma isyan ettim hayata yıllar sonra.. ama  ne sen nede ben  kimse kıyamaz aşkımıza...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kimse-kiyamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Şehir', 'aglayan-sehir-talip-sinecikli-lat2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özledim Edirne''yi

Ağlayan şehri özledim.

Sokaklarını,caddelerini

Saraçları,çilingirleri özledim.

Yağmur altında dolaşırkn bir sigara yakmayı,

İnsanlar arasında kaybolmayı,

Sabahları sigaramla,çayımı yudumlamayı,

Edirne''nin gözyaşlarını özledim.

Sevgilimi alıp gezmek caddelerde,

Sevişmeler gizlice söğütlükte,sarayiçinde,

Kaçamak öpücükler tenha,karanlık köşelerde,

O sevgililerin hepsini özledim.

Tavla partilerimizi,bilardo turnuvalarımızı,

Dostlarımla oturup aşk için ağlamayı,

Ağlarken hüzünlü şarkılar okumayı,

''kimseye etmem şikayet,ağlarım ben halime''

Şarkılar eşliğinde kızıl şarap yuvarlamayı,

İçipte ağlamayı,

Ağlayıpta içmeyi,

Ailemi,dostlarımı,sevdiğimi özledim.

Edirnem''iözledim.

Sabahlara kadar gezip tozmayı,

Geç kalınca anamın bağırmalarını,

Babamın kaşlarını çatıp,öylece bakmasını,

Alnımı terleterek para kazanmayı,

Çalışmayı özledim.

O ağlayan şehri,

O ağlatan şehri,

Edirne''yi özledim...', 'Özledim Edirne''yi Ağlayan şehri özledim. Sokaklarını,caddelerini Saraçları,çilingirleri özledim. Yağmur altında dolaşırkn bir sigara yakmayı...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aglayan-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Saati', 'ayrilik-saati-talip-sinecikli-6nnf3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat öğleden sonra 14:25

bu saat ayrılık saati

İki sıcacık kalbin

Bir daha kavuşmamak üzere 

Ayrılık saati

İsteyerek ya da isteksiz 

Ne farkeder artık,adı ayrılık

Gözler nemli,

İki el son kez dokunuyor birbirine

dudaklar''elveda demeye yabancı

Dökülmüyor bir türlü o kelime 

Sessizlik diktatör gibi,hükmünü sürdürüyor

Ulan,yine mi ayrılık? 

Oysa ne düşleri vardı bu iki kalbin

Ne hayalleri

Fakat yenik düştüler

Dayanamadılar ayrılığın gücüne

Bırakıldı eller birlikte çaresizce

Gözler seviyorum diyordu

Sarılmak istiyordu yeniden kollar

Ama artık aralarına girmişti ayrılık

Saat öğleden sonra 14:26

Bu saat ayrıldıkları saat

İki sıcacık kalbin 

Buz kestikleri saat', 'Saat öğleden sonra 14:25 bu saat ayrılık saati İki sıcacık kalbin Bir daha kavuşmamak üzere  Ayrılık saati İsteyerek ya da isteksiz  Ne fark...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-saati-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnleyin geceler', 'i-nleyin-geceler-fetih-sait-akkaya-4s5zs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aglamayın susun susun ne olur 

benden daha dertli değilsinizki 

benden daha yalnız değilsiniz ki

inleme hayat inleme 

ben inliyim bu gecede 

karanlık ta buğu olsun iniltilerim

inleyin geceler', 'aglamayın susun susun ne olur  benden daha dertli değilsinizki  benden daha yalnız değilsiniz ki inleme hayat inleme  ben inliyim bu gecede ...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/inleyin-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz yaşamak', 'sensiz-yasamak-fetih-sait-akkaya-l81hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni sensiz yaşamak 

en kotu kader olsa gerek

ey benim hasret kokulum 

ayrılığa,göz yaşına dayanırmı yürek

gel desem gelmezsin 

ama 

ben seninleyim 

ve tek seni seviyorum', 'seni sensiz yaşamak  en kotu kader olsa gerek ey benim hasret kokulum  ayrılığa,göz yaşına dayanırmı yürek gel desem gelmezsin  ama  ben sen...', ARRAY['Türk Edebiyatı','Şiir','Fetih Sait Akkaya']::text[], 8.5, '{"poet":"Fetih Sait Akkaya","poet_slug":"fetih-sait-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-yasamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelseneyar', 'gelseneyar-diler-kasap-fow3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerdesin bir söyle Allah aşkına

Gün battı gelmedin, eyledim merak,

Gelde  halimi gör, döndüm şaşkına,

Bu akşam seninle konuşmam gerek.

Gelsen gelmesende yolun beklerim,

Bu acı dünyamda gelbe şekerim,

Naz eyle billahi, nazın çekerim,

Bu akşam seninle konuşmam gerek.

Hayat bence sensiz kederle çile,

Yanından ayrılmam dakika bile,

Herbir gidişinde bulurdum hile,

Bu akşam seninle konuşmam gerek.

Hasretin geceler candan vuruyor.

Bu acı yıllardır bende sürüyor,

Her bir şeyim sensiz abes duruyor,

Bu akşam seninle konuşmam gerek.', 'Nerdesin bir söyle Allah aşkına Gün battı gelmedin, eyledim merak, Gelde  halimi gör, döndüm şaşkına, Bu akşam seninle konuşmam gerek. Gelse...', ARRAY['Türk Edebiyatı','Şiir','Diler Kasap']::text[], 8.5, '{"poet":"Diler Kasap","poet_slug":"diler-kasap","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelseneyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Axarsanda* olur,partlayirsanda', 'axarsanda-olur-partlayirsanda-nigin-nevaderezi-ddcfx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şelaleden,qemli** şelale

''Onsekiz ''damla ayrildi,

Onyedisi uğulduyla axdi suya 

Birisi partladi birbütüne

Qanina*** qan edib

Qanila yazdi:

Mende şelaleyem

Mende uğulduyam.

-------------

*Akarsanda

**Hüzünlü

***Kanina

 Tebriz- 1378.4.''18'' Güneş yili', 'Şelaleden,qemli** şelale ''Onsekiz ''damla ayrildi, Onyedisi uğulduyla axdi suya  Birisi partladi birbütüne Qanina*** qan edib Qanila yazdi: M...', ARRAY['Türk Edebiyatı','Şiir','Nigin Nevaderezi']::text[], 8.5, '{"poet":"Nigin Nevaderezi","poet_slug":"nigin-nevaderezi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/axarsanda-olur-partlayirsanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Dağları Kar İle Duman', 'erzurum-daglari-kar-i-le-duman-bedihi-kazim-nasuhbeyoglu-pe97a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bant dinliyorum yüreğim yanık,

Bir bant dinliyorum dünyam bulanık.

Radyom neden böyle davul zurnalık? 

             

                “Erzurum dağları kar ile duman 

                Yüreğimi aldı dert ile verem.''

Gazi Palandöken bu muydu düşüm? 

Beynimi karnında taşıyor başım, 

Kutsal toprağıma düştü, DADAŞım.

                

                 “Sizde bulunmaz mı bir kurşunkalem

                   Yazam arzuhalim, yare gönderem.''

Genci ihtiyarı kucak kucağa, 

Analar bebeler girdi toprağa, 

Taş, toprak yığarak üçbin ocağa,

             

                “Erzurum dağına kara giderim 

                Ayvayı bırakıp nara giderim.''

Dilim tutuk değil, soramıyorum, 

Ben benim yaramı saramıyorum, 

Bu nasıl kâbus ki yoramıyorum? 

           

             ''Bu yerin güzeli vefalı değil,

              Vefası bulunan yara giderim.”

                                               1983', 'Bir bant dinliyorum yüreğim yanık, Bir bant dinliyorum dünyam bulanık. Radyom neden böyle davul zurnalık?                                “Er...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/erzurum-daglari-kar-ile-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaret Çalısı', 'ziyaret-calisi-bedihi-kazim-nasuhbeyoglu-i1jm5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ziyaret çalısı olmuşuz,doğru! 

Gelen çaput bağlar dallarımıza. 

Başımız toprakta, boynumuz eğri, 

Kul olduk be felek, kullarımıza.

Hürdük; kol atardık güne ışığa, 

Konuyduk; tarihe, ilham; aşığa, 

Nasıl, nerden  düştük bu  dolaşığa? 

Kim vurdu bu  bağı  kollarımıza? 

Bir kuru tas mıdır kafa dediğin 

Benim mi Yarabbi bu çürük beyin? 

Bu neyin uykusu, gündüz öğleyin! 

Kargalar gülüşür hallerimize…', 'Ziyaret çalısı olmuşuz,doğru!  Gelen çaput bağlar dallarımıza.  Başımız toprakta, boynumuz eğri,  Kul olduk be felek, kullarımıza. Hürdük; k...', ARRAY['Türk Edebiyatı','Şiir','Bedihi Kazım Nasuhbeyoğlu']::text[], 8.5, '{"poet":"Bedihi Kazım Nasuhbeyoğlu","poet_slug":"bedihi-kazim-nasuhbeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ziyaret-calisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah barış...', 'siyah-baris-emirhan-bala-35773', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'siyah barış bu, 

çöle düşen, 

gökdelenleri deviren, 

evleri kan gölüne çeviren 

siyah barış... 

ruhları çıplak bunların, 

fenerleri silah bunların, 

yuh barışlarına, 

çölde,gökdelenlerde, 

insanlara kıyanlara, 

yuh... 

siyasetleri kıvırcık bunların, 

düzenleri düzensiz bunların, 

dinleri karışık bunların, 

müslümanı,hiristiyanı,musevisi 

barışları siyah bunların... 

yuh barışlarına, 

    yuh dinlerine, 

        yuh silahlarına, 

yuh 

   olsun 

        siyah 

             barışa....', 'siyah barış bu,  çöle düşen,  gökdelenleri deviren,  evleri kan gölüne çeviren  siyah barış...  ruhları çıplak bunların,  fenerleri silah bu...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siyah-baris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Sürgün', 'surgun-sair-ahrazi-a7l7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer ki cihânda bir cennet olsa; 

Günâhın bağrına,sevap düşerdi,

Âh…diyen olmazdı böyle derinden,

Ecel de başka bir hayat yaşardı,

Ve şeytan ağlardı Son kederinden.

Eğer ki bugünde bir cennet olsa; 

Biriken yarınlar dünle yanardı,

Yutardı zamanı canlı bir kuyu,

Kudretin suyunu içen kanardı,

Bölmezdi kıyâmet bu Son uykuyu.

Eğer ki insanda bir cennet olsa; 

İnkârın içinde akıl yatardı,

Vermezdi şeytana kutlu bir günü,

İnsanın vicdânı İNSAN kadardı,

Nasılda unuttu bu ‘’Son’’sürgünü...!', 'Eğer ki cihânda bir cennet olsa;  Günâhın bağrına,sevap düşerdi, Âh…diyen olmazdı böyle derinden, Ecel de başka bir hayat yaşardı, Ve şeytan...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/surgun-269-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul', 'istanbul-sair-nadirezheri-um2e0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Hacan istanbula geldin...? 

Amma yox,benzeye bildi

Sene bir ''gurcu'' qadin

Tanri menile gicirdi! 

Gece guclu geceydi

O gece,Istanbulu icdim

Qurbetim Hotelde gudurken.', '-Hacan istanbula geldin...?  Amma yox,benzeye bildi Sene bir ''gurcu'' qadin Tanri menile gicirdi!  Gece guclu geceydi O gece,Istanbulu icdim ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/istanbul-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kekeme Aşk', 'kekeme-ask-ozer-tekin-v2kt4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski bir gülümseyiş tatında olmalı

bu gece yazacağım şiir

veya ayrılıklar tatında olmalı

En çok hüzün ayrılıklarda gizlidir

ki her ayrılık sancılı başlar.

Kekeme bir aşktan geriye kalanlar

kül oluyor kentin sokaklarında

nergiz kokusuna karışan birileri

düşüyor yollara

ve acıyı cebine koyup

yakıyor tüm anılarını

Anılar ki zulmün birer efendisidirler

ve zulüm bir ilmik gibi boynumuzda', 'Eski bir gülümseyiş tatında olmalı bu gece yazacağım şiir veya ayrılıklar tatında olmalı En çok hüzün ayrılıklarda gizlidir ki her ayrılık s...', ARRAY['Türk Edebiyatı','Şiir','Özer Tekin']::text[], 8.5, '{"poet":"Özer Tekin","poet_slug":"ozer-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kekeme-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telve’de Umutlar:? Sorguda beden :) ANLAMADIN', 'telve-de-umutlar-sorguda-beden-anlamadin-his-kaybi-mk-caz2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arsız umutlar yorgun beden

Üç vakte kadar gelir giden

Çınlıyor kulağımda Falcının sözleri

Telve’de ne umutlar tükendi; Ne falcı ne sen bunu göremedi 

Saat Sabahın beşi kuşluk vakti

Hava serin Rüzgar esiyor Sahil’de

Martılar erkenci, Bir kadın Yürüyor sahil yolunda

Bir ben aranırım  kuşluk vakti Kızkulesi düşlerinde

Bir sigara yakarım derin çekerim dumanını içime

Ağzımı acı tadı kaplarken beden yine intihar tekmil’inde 

Ey uykusu yarım kalan gece 

Düşleri eksik bırakan yanım aldatan anılarım

Sende yorgun bedenimden başka hangi umudu saklarım 

Zamanı geldi, bir öykü yazmalı gönül

Bir şiir mırıldanmalı dudaklarım 

Düşlerim sana serenat yapmalı 

Ve yıkılmalı yalnızlığım; tan ağarınca denize bırakılmalı SEN; en güzel yanım

Ahhhh Ah işte ahlar sardı bedeni 

Sana bu şiiri yazalı çok zaman oldu

Düşlerimde büyüdün mevsimlerimde yağmurla sulandın 

Güneşimle beslendin Rüzgarlarımla yaprak döktün; tükendin 

Bir beni az sevdin bir’de Rakı tadında Hayallerimi

Sarhoş yanın Hatırlarmısın inatçı tarafım sendin

Taksim’de barlarda kalırdı o gece çılgın yanın 

Bir kadıköy dolmuşunda tutardım ellerini 

Duvar dibi düşleri değil miydi benimki’si

Güneş doğmadı henüz Sahilde

Kız kulesi Hala acıtıyor bakarken ten’i

Ve bendeki cebi boş bir gelecek 

Geçmişi olmamış bir gerçek anılar ve yalnızlığım; beden tükenecek 

Ömür Kızkulesi düşlerinde Rakı sofrası muhabbetleri sensizlik hep sürecek YA GERÇEK? 

M.K. Versac Y.Tarihi: 11/08/2004 S: 21:22', 'Arsız umutlar yorgun beden Üç vakte kadar gelir giden Çınlıyor kulağımda Falcının sözleri Telve’de ne umutlar tükendi; Ne falcı ne sen bunu ...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/telve-de-umutlar-sorguda-beden-anlamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Asla Arkaya Bakmaz', 'kadin-asla-arkaya-bakmaz-rahim-tas-ivtlq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadın Asla Arkaya Bakmaz

        Seni terk ederken bir heves, bir merak, bir heyecan içindeydim. Ne bahaneler uydurmuştum. Sevgisiz, saygısız, ilgisiz derken sana, başka birinin varlığını hissetmiştin. Hakarete vardırmıştım kıskançlığını.  Ne büyük nankörlükmüş oysa benimkisi. 

        Seni terk ederken ne hale geleceğini ve hatta ne hale geleceğimi bile düşünmemişim. Zedelenen onurun, kırılan gururuna rağmen kötü dememişsin, dedirtmemişsin bana, asil davranarak. 

        Soruyorum sıkça kendime; ''iyi mi yaptım? ''Hayır, hayır! Defalarca hayır! Zaten çok sürmedi, ben de terk edildim tükenince. Dayanamadım düşük sınıflı köhne otellere. Şimdi kapsız, kacaksız, bardaksız, duvarlarında sesimin yankılandığı küçük bir evde eskiciden alınma çarşafsız bir yatakta hatalarımla yüzleşmeye çalışıyorum. 

        Yatağımı özlüyorum. Üzerinde dumanı tüten çorbanın porselen tabağını, demini almış çayı, ütülü pijamalarımı özlüyorum. Çocukları da özlüyorum, uzaktan seyretmeler tak etti canıma.  Aslında seni özlüyorum. Seni seviyormuşum anladım. Hayır, seni seviyorum. 

        Affet beni demiyorum. Bana bir şans daha ver de diyemiyorum. Dostluğuna ihtiyaç duyuyorum da diyemem. Tükettim tüm kredilerimi, biliyorum. 

        Biliyorum terk etse de terk edilse de; ''kadın asla arkaya bakmaz.'' 

11.8. 2004', 'Kadın Asla Arkaya Bakmaz         Seni terk ederken bir heves, bir merak, bir heyecan içindeydim. Ne bahaneler uydurmuştum. Sevgisiz, saygısı...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadin-asla-arkaya-bakmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enkaz', 'enkaz-nedim-saatcioglu-nlf0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömür seferinde deprem yaşadım

Canımdan bir parça enkazda kaldı

Evet tebessümü paylaştım ama

Tozpembe düşlerim hep azda kaldı

Elimin saçıma öcü bitmedi

Acının kalbime göçü bitmedi

Yumruğun kadere gücü yetmedi

Kollarım boşlukta niyazda kaldı

Cümleler döküldü dilimden ahla

Yaşamayı öğren dedi siyahla

Yokluğun tenime vurdu sabahla

Verilen tüm sözler vaazda kaldı

Unuttum mutluluk denilen faslı

Dudakta kıvrılan tebessüm paslı

Kirpikten süzülen gözyaşım yaslı

Aşk dolu cümleler hep sazda kaldı

Yoruldu ümitler yol gözlemekten 

Yoruldu yüreğim dert gizlemekten

Yoruldu hayaller hep özlemekten

Girdiğim tüm yollar çıkmazda kaldı

Yıkıldı ömrümün sevda bulvarı

Yıkıldı gönlümün kerpiç duvarı

Kurşuna dizildi aşkın havarı

Ruhumun yarısı ayazda kaldı', 'Ömür seferinde deprem yaşadım Canımdan bir parça enkazda kaldı Evet tebessümü paylaştım ama Tozpembe düşlerim hep azda kaldı Elimin saçıma ö...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/enkaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mahya-sultan-tosun-qtu34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanı olana 

İlaç gibi gelir zaman

Ya zamanı olmayana!', 'Zamanı olana  İlaç gibi gelir zaman Ya zamanı olmayana!...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/zaman-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-mahya-sultan-tosun-cyr0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülen yüzün solmasın istedim

Çünkü sevgin gözlerinde gizli,

Dilin hiç susmasın istedim

Çünkü aşkın şiirlerinde gizli,

Elinin sıcaklığı gitmesin istedim

Çünkü hislerin teninde gizli,

Kalbin hiç kırılmasın istedim

Çünkü içinde benim gizli.', 'Gülen yüzün solmasın istedim Çünkü sevgin gözlerinde gizli, Dilin hiç susmasın istedim Çünkü aşkın şiirlerinde gizli, Elinin sıcaklığı gitme...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sir-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkta Sebat...', 'askta-sebat-i-brahim-ethem-bingul-ltj54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğini bile bile

Sevgiliye sırt çevirmek

Çok acıdır,

Yakıcıdır

Bil ki aşka ihanettir..

Sevildiğin aşikârsa

Mevsim kış, yağan karsa

Şeytan, bütün güçleriyle

Ayrılığa taraftarsa

Uyma sakın şeytanlara

Şaşırtıcı,

Yalancıdır

Akıbeti felâkettir..

Güzele güzel diyenler

Sözü güzel söyleyenler

Mutlu gelecek görenler

Aşkı bilir,

Aşk ehlidir

Tavsiyesi de güzeldir

Meşrepleri muhabbettir..

Sev,

Devamlı..

Sevil,

Ol canlı..

Sevdireni

Hiç unutma,

An kalbinden heyecanlı..

Aşkta 

Sebata sebeptir...

''''Of''lu Ahmet Faruk Türkyılmaz''ın cevap şiirinden ilham''la....''''', 'Sevdiğini bile bile Sevgiliye sırt çevirmek Çok acıdır, Yakıcıdır Bil ki aşka ihanettir.. Sevildiğin aşikârsa Mevsim kış, yağan karsa Şeytan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askta-sebat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalar', 'firtinalar-ahmet-agdere-nwjjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırtınalar

Benden doğan fırtınalar 

Koparır bende ne varsa

Savurur uzaklara 

Islanır özlemim 

Yıkanır kederim 

Bir hışımlık şimşekle 

Kan saçar yüreğim 

Ben rüzgar olurum 

Rüzgar ben olur 

Bet gene solurum 

Yeryüzünde hep kin olur 

Fırtınalar 

Benden doğan fırtınalar 

Katar önüne 

Sevgi adına ne kadar garez varsa 

Ayırır kavuşan elleri 

Ağlatır arayan gözleri 

Çatır çatır yakar

Yasak aşk sefaletini 

Gezinirler sokak sokak

Görünenler birbirinden korkak

Ayrılanların suratlarında

Bayram gününden kalma bir tak! 

Fırtınalar 

Benden doğan fırtınalar 

Yakamozların ışıltısında

Yıldızların parıltısında

Nefeslerini mıhla 

Sevgililerin alınlarına kazırlar

Kalmaz sevgilide hatırat

Kaldırımlara boylu boyunca fırlat at

Fırtınalar

Benden doğan fırtınalar

Onlar bu dünyada kaldıkça

Kalmaz sevenlerde de rahat', 'Fırtınalar Benden doğan fırtınalar  Koparır bende ne varsa Savurur uzaklara  Islanır özlemim  Yıkanır kederim  Bir hışımlık şimşekle  Kan sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/firtinalar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mahya-sultan-tosun-1rfc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varlığına yetişemedim

Ölmek istedim bu yüzden

Yokluğuna erişmek için.', 'Varlığına yetişemedim Ölmek istedim bu yüzden Yokluğuna erişmek için....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/senin-icin-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Say ki Sevdiğim', 'say-ki-sevdigim-ahmet-agdere-0zi30', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Say ki sevdiğim,

Hiç sevmedin beni,

Her geçişinde caddede

Karşında sıradan bir beden.

Işımadı gözlerin,

Titremedi,

Gözlerimiz kesişirken.

Her gece

Tanrıya ettiğin duan

Tüm evrene aitti

Ve 

Rüyalarına giren

Uzaklarda bir artistti

Sen ona tutkun bir hayran,

O ise uzaklarda gezendi.

Say ki sevdiğim,

Kar taneleriydik

Ağustos ortasında

Yeryüzüne

Düşmeye hazırlanan

Sen bana sarıldın

Ben sana

Minik kar taneleri

Muhtaçtı buna

Düştük

Eridik

Düştük 

Eridik

Ve sonunda

Tükendik! 

Say ki sevdiğim,

Okuduk

Kendi kitabımızı

Bir varmışla başladı

Bir yokmuşla devam etti

Zevklendik her sayfada

Yaşadık doya doya

Her sayfanın zerafeti

Bir hiçti senin yanında

Lakin,

Yazdık 

Okuduk

Ve 

Bir çırpıda bitirdik

Yaşanan bir ömür gibi! 

 Say ki sevdiğim,

Mahkumduk 

Engin kızgın bir çöle.

O öfkeli harabede

Sen bana serap

Ben sana..

Muhtaçtık rüyaya.

Şehvetle içtik birbirimizi

Ve uyandık ansızın

Özlenen suyu bulmamızla.

Kavrulduk

Yangınlarında gezdik

Aşkın ve şehvetin

Gün geldi uyandık

Uyandık artık sevdiğim!', 'Say ki sevdiğim, Hiç sevmedin beni, Her geçişinde caddede Karşında sıradan bir beden. Işımadı gözlerin, Titremedi, Gözlerimiz kesişirken. He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/say-ki-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmek', 'gulmek-mahya-sultan-tosun-byrlx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülüşünle doğuyor gün

Gönlüm gülüşünle ısınıyor

Gülüyorum gülüşünle.

Gülmezsen eğer

Gün gece olur,

Günüm sensiz geçer

Günün bensiz geçer.', 'Gülüşünle doğuyor gün Gönlüm gülüşünle ısınıyor Gülüyorum gülüşünle. Gülmezsen eğer Gün gece olur, Günüm sensiz geçer Günün bensiz geçer....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gulmek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-mahya-sultan-tosun-t6csu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün batımında izliyordum seni

Çalıştın, çabaladın,

Kan ter içinde kaldın

Gene de güneşin batışını durduramadın.', 'Gün batımında izliyordum seni Çalıştın, çabaladın, Kan ter içinde kaldın Gene de güneşin batışını durduramadın....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasam-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte', 'sensizlikte-metehan-ayhan-6istr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşünürüm; yokluğunda.

Gözlerin gelir aklıma; yıldızlar gibi parlak. 

Gözlerine baktığım zamanları hatırlarım; gözlerinde kendimi gördüğümü. 

Sonra gülümsersin bana; tarifsiz, eşsiz, sevgi dolu! 

Birden kokunu duyarım; gülümserim, aklım gider başımdan. 

Kapatırım gözlerimi; bana sım sıkı sarılışların gelir aklıma. 

İşte o zaman içimde bir ağrı; bedenimi saran. 

Derken hüzünlündiğin anlar gelir aklıma; duygularım artar. 

Bakışların değişir birden; dudak büküşlerin. 

Oysa ne güzel yakışıyor sana; eşsiz gülüşün. 

Derin iç çekişlerim gelir aklıma; kalbim daha hızlı çarpar. 

Öpüşmelerimiz; tatlı, yumuşak, sevdalı.

Elerini düşünürüm; gözyaşlarımı silen, şevkatli.

Derken ağlamak isterim; göğsüne yaslanıp.

SAna sarılmak; sonsuza kadar ve hep yanın da olmak.

Sıcaklağını hissederim; ellerinin, bedeninin, yüreğinin.

Tenini özlerim; yumuşak, kışkırtıcı.

Bakışmalar gelir aklıma; sessiz haykırışlar.

Sesini duymak isterim; kalbim biraz olsun serinler.

Gecelerimi seninle geçiririm; usanmadan hayaller kurarım, hayallerim de Sen.

Her günü seninle bitirir; her sabaha tekrar seninle başlarım.

Sevdama; yeni sevdalar katarım.

Yaşadıklarım neyse; ben seninle yaşayamadıklarıma yanarım.

Zordur katlanmak ayrılıklara; severken bu kadar.

Tek faydası; insanın ruhunu eğitmek olduğuna inanırım.

Sensizlik...

Sensizlik gelir aklıma; her şeyden beter! 

Kalabalık içinde; kimsesizlik, çaresizlik.

Bazen kuş olmak isterim; kanat çırpmak Sana.

Sessiz sedasız; senden haber almak, bir kez olsun görebilmek.

Merak ederim sonra; hep zormudur! bu mudur sevmek.

Eğer derim şimdi olmazsa; gerçekmidir öbür dünya.

Kendi kendime derim; Ne zor şeymiş Seni sevmek! 

Şairin dediği gibi; ''Bu derde düşmeden önce''', 'Seni düşünürüm; yokluğunda. Gözlerin gelir aklıma; yıldızlar gibi parlak.  Gözlerine baktığım zamanları hatırlarım; gözlerinde kendimi gördü...', ARRAY['Türk Edebiyatı','Şiir','Metehan Ayhan']::text[], 8.5, '{"poet":"Metehan Ayhan","poet_slug":"metehan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sensizlikte-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Gece', 'seninle-gece-mahya-sultan-tosun-3fqnv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni görmek yetiyor

Uykusuz gecelerin hesabını

Gözlerimden sormaya.', 'Seni görmek yetiyor Uykusuz gecelerin hesabını Gözlerimden sormaya....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seninle-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mahya-sultan-tosun-v06cj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalplerimiz bir kutu içinde 

Açmaya korkuyorum

Başka gönüllere 

Yürek olurlar diye...', 'Kalplerimiz bir kutu içinde  Açmaya korkuyorum Başka gönüllere  Yürek olurlar diye......', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-263-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüşün Rengi', 'opusun-rengi-neser-selman-z6ar1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rengi nedir aşkın

Karış toprağın belli

Dolanarak bürünür renklerine heves

Seslenir güller ateşiyle 

Kararır dallar  gece misali

Öpüşün rengi nedir erirken

Geceyi yaran sessizliğin belli

Canlı tabloyu süsler..

Badem gözler,kiraz dudaklar

Sarmaşık olmuştur renklerinde hırs..', 'Rengi nedir aşkın Karış toprağın belli Dolanarak bürünür renklerine heves Seslenir güller ateşiyle  Kararır dallar  gece misali Öpüşün rengi...', ARRAY['Türk Edebiyatı','Şiir','Neşer Selman']::text[], 8.5, '{"poet":"Neşer Selman","poet_slug":"neser-selman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/opusun-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islığınla Gidişler Astın', 'isliginla-gidisler-astin-ahmet-capa-4s4qm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nereden aldın bu zalim şarkının notalarını 

Islığınla, gidişler astın bu evin kapılarına.

Sol yanımdan yavaşça süzüldü kanlarım

Sağanak yağmurlu bir Kasım Akşamında.

Dökülen talaşlar gibi parçalandı yüreklerimiz

Biz feleğin rendesinden geçtik aslında,

Bakışlarını şu paletin hangi rengiyle boyasam

Ve tuvalin neresine kondursam dudaklarını.

En olur olmaz yerinden yırtıldı göğsümün ortası

Bilmem ki şu hayal çuvaldızıyla

hangi sağlam urganlardan örsem aşkın kazağını.

Kapatmaya tenezzül edilmemiş bir kapının

açık bırakılan ihanetinde vurulmuştum.

Ayaklarının gergin yayından fırladığında gidişin

Bir elma kurdu gibi

büyüdü gecenin içinde vınlayan sesi.

En acı ayrılık okunu,

kanlar içinde kulağımda taşırım şimdi.

Hayatının filminde hangi kareyi işgal etmişimdir kimbilir.

Ve hangi montajlanmış bir hayat kalıntısıdır anılarına yaslanan

En acıklı sahneyi ustaca oynadım,

bir vasiyet yazarken rıhtımın ayaklarında.

ve şimdi, kıyısında çırpınırken bir dalga gibi

bıraktım elimde ki incileri yorularak.

Bu son nefesti lâkin tükendi ağzımda yavaşça

yüreğinin kızgın kumlarında sessizce boğularak.

Bakışlarının zokasını yutmuş zavallı gözbebeklerim

Küflenmiş tavanlara 

uykumu kirpiklerimden astım.

Acılar suyuna bandırdım gönlümün yanan ekmeğini,

Bilmem ki,

yüreğimin kırık tuğlaları 

hangi sıvası dökülmüş duvarların kalıntısıdır.

Anaç bir gece, sancılar içinde doğururken sabahı

Ben ateşi kendimi yakarak söndürdüm.

Sıcak bir köze göğsümü patlatarak tükürdüm ciğerlerimi,

Bilir misin sevgili

bu dumanlar hangi gidişin ateşten dansıdır.

(11.08.2004 İst.)', 'Nereden aldın bu zalim şarkının notalarını  Islığınla, gidişler astın bu evin kapılarına. Sol yanımdan yavaşça süzüldü kanlarım Sağanak yağm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/isliginla-gidisler-astin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-erzincanli-kurt-ay7vk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir seyler yapmak istiyorum bugün. 

Ayaklarimi yerden kesecek, beni benden alip bambaska yerlere götürecek bir seyler... 

Dokunmak istiyorum bugün yildizlara, takilmak istiyorum kuslarin kanatlarina, 

Söyle bir uzanip rahatlamak bulutlarin üzerinde. 

Günes''i, Ay''i kucaklamak, 

Masmavi, dupduru denizleri, okyanuslari içmek bir nefeste 

Solumak su havayi öylesine derinden 

Çiçeklerin bütün renklerini 

Yesilin bütün tonlarini görmek bir anda 

Haykirmak istiyorum tüm acilara 

Meydan okumak istiyorum kanayan yaralarima 

Söyle bir omuz atmak istiyorum esmek isteyen det rüzgarlarima. 

Bugün bir seyler yapmak istiyorum... 

Sevdiklerim yanimda olsun istiyorum bugün. 

Güzelliklerin tümünü yasamak istiyorum. 

Okumak istiyorum her kelimesini, her hecesini gözlerin. 

Anlamak beyinlerdeki firtinalari 

Yasamak beraberce mutlulugu ve hüznü. 

Dalarken gözlerim ufuklara 

Yasarken huzurun doruklarý nda 

Gezerken adim adim her köseyi, her caddeyi 

Hissetmek istiyorum en güzeli, en safi... 

Gecenin karanligini, gündüzün aydinligini seviyorum. 

Seviyorum akasya kokusunu 

Seviyorum yesili, maviyi, pembeyi... 

Bülbülün ötüsünü, 

Insanlarin gülümseyisini seviyorum. 

Bir seyler yapmak istiyorum bugün 

Bugün Mutlu Olmuk Istiyorum...', 'Bir seyler yapmak istiyorum bugün.  Ayaklarimi yerden kesecek, beni benden alip bambaska yerlere götürecek bir seyler...  Dokunmak istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Erzincanli Kurt']::text[], 8.5, '{"poet":"Erzincanli Kurt","poet_slug":"erzincanli-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istiyorum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül hapishanem', 'gonul-hapishanem-tayfun-karakas-0krp1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül hapishanem 

Yine hayata küsmüş kendimi gönül hapishaneme hapsedip karanlık soğuk ve küçük camında kalınca demirleri olan soğuk nemli zindana kilitlemiş anahtarı da çok uğraşarak alabileceğim belki de alamayacağım uzaklıktaki bir yere fırlatıp atmıştım. Dışarıdaki yağmurla karışık havanın ve fırtınanın beni etkileyemeyeceği bir ruh haliyle kendime işkence etmekteydim.

Gündüzleri sevmediğim için zor geçiyor geceleri rahatlayabildiğim ve sevdiğim için çabucak geçiyordu ama kendimle yaptığım savaşı ne kazanacak nede tamamen kaybedecek bir hamle yapabiliyor nede gördüğüm kabus sona eriyordu.

Sende yoktun ortalıkta ama nasıl isterdim bilir misin gelmeni gelipte beni sen kurtarmalıydın yoktun geleceğe de benzemiyordun. Gökyüzünün rengi değişmiş rüzgarlar serinletmez olmuş çiçeklerin rengi solmuş, öyle değişmişti ki dünya içim yanarken doya doya içtiğim suyun bile tadı yoktu. Hiçbir şey düzelmeyecek ben kendimi hapsettiğim bu zindanda yapa yalnız yok olacaktım. Ama her şeyin sebebi sendin belki de sen olsan gökyüzü daha mavi olacak asi rüzgarlar serin bir melteme dönüşecek çiçekler apayrı daha canlı milyonlarca tonda açacaktı.

Gönül hapishanemin anahtarı gözlerindi o kocaman pırıl pırıl gözlerin sen gelsen bitecekti mahpusluk zaten senin cellatlığınla asılmaya bile razıydım. Çünkü yaşanmıyordu artık hayat.

İnandırmıştım kendimi sana ve senin her şeyi değiştireceğine gözümde devleşmiş devleştikçe de seni daha bi sevmiştim. Sen gelince her şey sona erecekti. Her şey seninle güzelleşecek zindan kapısı açılınca ben sana sende bana kavuşacaktın. Ellerim ellerine değdiğinde tüm düzeni değişecekti dünyanın ve mutluluk benim olacaktı. 

Sen yine kapkara ve kocaman bakacaktın, gözlerinle güldüğünü veya sövdüğünü ben anlarım, gelirken gün ışığına biraz mutluluk gözyaşı karıştır getir yürek yaramı iyileştirecek tek çare gözlerindir ve kendi hapishanesindeki bu esir senindir ve senin için yazılan en güzel şiir hapishanede seni bekleyen esirindir.

Her şeyin sebebi sen ve tek çaremde sendin. Gönül kapımı açamayacak ve hatta celladım dahi olamayacaksan gelme. Gelme her şeyi sana bağlamışken bir şey yapamazsan dağılır bu yürek.

Gelişinle batacaksa gönül gemim bırak hayalinle belki vuslat limanına giderim.

Aşkını tanyerine sakladıysan eğer üzülme gün doğmadan ben dağlarda olacağım.', 'Gönül hapishanem  Yine hayata küsmüş kendimi gönül hapishaneme hapsedip karanlık soğuk ve küçük camında kalınca demirleri olan soğuk nemli z...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Karakaş']::text[], 8.5, '{"poet":"Tayfun Karakaş","poet_slug":"tayfun-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonul-hapishanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefe / Şerefine', 'serefe-serefine-hurrem-yalcin-nv9il', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaderime

boyun

eğiyorum,

sana

elveda

diyorum,

onunla

mutluluk

diliyorum,

çok

delice

biliyorum,

kendi hançerimi

yüreğimin incesine

ellerimle saplıyorum,

bak

canım

şimdi

kadehinde,

kaldır

kadehini

şerefime,

öylesine

şaşkın

bakma

yüzüme,

ne

bekliyordun

söylesene,

ben

seni

sevmiştim

ölesiye,

ŞEREFE / ŞEREFİNE

HAYATTA ve ÖLÜMDE

ŞEREFLİCE

...

..

.

11 Ağustos 2004', 'kaderime boyun eğiyorum, sana elveda diyorum, onunla mutluluk diliyorum, çok delice biliyorum, kendi hançerimi yüreğimin incesine ellerimle ...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/serefe-serefine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş...', 'bekleyis-umut-gul-m6aei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklemek zordur 

bir otobüsü, bir treni 

bir yolcuyu beklemek 

saniyeler saat, saatler asır olur 

birbiri ardına yanar. 

söner sigaralar, 

sık sık değiştirilir, 

karıncalanan ayaklar, 

kah gülümser, 

kah asılır suratlar, 

tren göründüğünde uzaktan 

yada otobüs. 

el sallanır, yüzler güler, 

beklenen yolcu göründüğünde 

pencereden, 

hele inmeye başladığında 

merdivenlerden... 

unutulur çileli bekleyiş, 

efkarın yerini alır gülümseyiş 

beklenen... 

değiyorsa beklemeye eğer', 'Beklemek zordur  bir otobüsü, bir treni  bir yolcuyu beklemek  saniyeler saat, saatler asır olur  birbiri ardına yanar.  söner sigaralar,  s...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekleyis-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-*-* P a m u k...T ı k a l ı...K u l a k l a r....!', 'p-a-m-u-k-t-i-k-a-l-i-k-u-l-a-k-l-a-r-metin-eser-4v4el', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'soyun diyor kadın yüzüme bakmadan 

çırçıplak bir bedendir günün tam ortasında, 

güneş yakmakta teni dünden daha da beter, 

bir alkış kopuyor yine tavan arasında, 

sus diyor kulaklarım ve sözüm ''artık yeter...'' 

. 

sus diyorum adama işaret ederek, 

yoksa başınıza taş yağacak gökten, 

bir kelime düşünceme dolanır hevesli, 

söyleyemem dilim lâl olur hepten... 

sus diyor kapılar ve caddenin ayak sesi... 

. 

sev diyor şeytan aldırma çapulcuya, 

kramp giriyor yüreğime atmasa öleceğim, 

ızdırap sızıyor, sesim boğuk bir uğultu, 

bir ekmeğim olsa sadece sana böleceğim, 

sus diyor yürek, değmez taş ve çakıllara, 

. 

kalk diyor içim yürü ve koş gaziliğe, 

çamura bulanmışsın bencilliğinle be adam, 

elinde kör kılıcın savur kendi cahilliğine, 

almışsın cellat ipini sanki görevin idam, 

sus diyor insafım, bakma aptalın sözüne, 

. 

kov diyorum hayalden, sil hepsini beyninden, 

pörsümüş bedenlerin değeri olmazmış hiç, 

bir köprünün çürümüş ayak üstü caddesinden 

karşıya sağlam geçen maalesef olmazmış hiç, 

sus diyor kelâmım, 

......çek üstüne bir çizgi kırmızı kaleminden. 

. 

arzu haykırır içte, çıkmak ister meydana, 

karanlık bir odada göz kırpıyor hatıram, 

görmüyorum elbette, bu bir hayal sadece, 

az sonra çalsa da çıngıraklı şu saat, 

sus diyor iyiliğim, 

......bu bir rüya sadece sonu kabusa gebe.. 

. 

koku çeker kendine, gelir gül bataklığından, 

parmaklarım acıyor, gülün son firâkından, 

dikeni batmış zehirli kan damlar iftirakından, 

söylemem manzarayı, göründü perde arkası, 

ve sus diyor kâinat, yoksa kıyamet kopacak. 

. 

s u s u y o r u m...c e h a l e t e, 

......s u s u y o r u m...s e f a l e t e, 

............s u s u y o r u m...h ı y a n e t e, 

..................s u s u y o r u m...c i n a y e t e, 

. 

Ç ü n k ü...b i l i y o r u m, 

......körelen gözlerin anlattığını, 

............dilsiz kelimelerin ne yaptığını, 

..................üstelik sağır kulaklarının 

............p a m u k l a...t ı k a n d ı ğ ı n ı... 

......s u s u y o r u m, 

Ç ü n k ü...b i l i y o r u m.

12.08.04 / Frankfurt', 'soyun diyor kadın yüzüme bakmadan  çırçıplak bir bedendir günün tam ortasında,  güneş yakmakta teni dünden daha da beter,  bir alkış kopuyor...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/p-a-m-u-k-t-i-k-a-l-i-k-u-l-a-k-l-a-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaygılarım Vardı', 'kaygilarim-vardi-baykal-kaanalp-bad0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaygılarım vardı

dostumun üzerinde

süpüremediğim

bir nefeste

kaygılarım vardı

biçimsizliğini yontamadığım

ne kadar uğraşsamda

çile çeker gibiydi

çekip giderken adımlarım

kaygılarımı da yüklenmiştim

sırtıma

ağır ve hantaldılar

kaygılarım vardı

dostumun üzerine

kepenek kepenek yağan

bir dolusu da

dışarıda bekleyen

kaygılarım vardı

yüreğimde

çekip çıkaramadığım

kesip atamadığım', 'kaygılarım vardı dostumun üzerinde süpüremediğim bir nefeste kaygılarım vardı biçimsizliğini yontamadığım ne kadar uğraşsamda çile çeker gib...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaygilarim-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey', 'hey-baykal-kaanalp-ox0cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hey

çocuklar

çekilin

koru kenarından

elleşmeyin narları

çekilin oradan

ben size

bağırıp çığırmaktan yoruldum

siz çalıp çırpmaktan

yorulmadınız

geleceğimi

umutlarımı

hayallerimi', 'hey çocuklar çekilin koru kenarından elleşmeyin narları çekilin oradan ben size bağırıp çığırmaktan yoruldum siz çalıp çırpmaktan yorulmadın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hey-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terket', 'terket-baykal-kaanalp-e05r8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geçip giderse

beni anmadığın halde

hayalim yanıbaşından

tükenirse

tükenmez sandığın

içi yağmur dolu

kara kaplı

bulut kümeleri

terket

zaten birlikte olmadığın

beni

ve düşlerini

o umut bağladığın

karşılık alamadığın

düşlerini', 'geçip giderse beni anmadığın halde hayalim yanıbaşından tükenirse tükenmez sandığın içi yağmur dolu kara kaplı bulut kümeleri terket zaten b...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/terket-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lola ya Mektuplar 2', 'lola-ya-mektuplar-2-baykal-kaanalp-ejp7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gün çok mutluyum

sana yazabileceğimi

görmekten dolayı

sana yazmak istediğim

o kadar çok şey var ki! 

hangisinden başlamalıyım

öncelikle sen neyi

okumak istersin? 

herhangi bir önceliğin

var mıdır? önemsediğin

değer verdiğin

hayatında

bunu sana sorarak

öğrenmek zorundayım

beni affet

seni sana sormadan

keşfedemediğim,o kadar

sıkı bir kuyumcu

olamadığım için affet

ama inan ki o

tatlı gülümseyişin

gönül okşayışın

iyi kalpli bir insan olduğunu

bana hemen söylüyor

tabii ki bence de öyle

parmakların dokunmaktan

korkar gibi

sanki hiç incitmek istemez

sevdiklerini

sevmediklerini', 'bu gün çok mutluyum sana yazabileceğimi görmekten dolayı sana yazmak istediğim o kadar çok şey var ki!  hangisinden başlamalıyım öncelikle s...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/lola-ya-mektuplar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özmenem''e', 'ozmenem-e-sabit-i-nce-tdvba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir gibi birkaç kelam, 

Yazdıyısam affet İlyas. 

Özmenem''e haktan selam, 

Verdiyisem affet İlyas. 

Manası yok ki çözesin, 

Şuaralarla gezesin, 

İnce''ye niye kızasın, 

Gerdiyisem affet İlyas. 

Dolaştırmam doğru yolu, 

Karıştırmam sağı, solu, 

Bir garip Allah''ın kulu, 

Kırdıyısam Affet İlyas. 

İlhamından ilham aldım, 

Kelamını doğru buldum, 

Kalemine hayran oldum, 

Sorduyusam affet İlyas. 

Aşık Zavallı hocamdır, 

gündüzlerim de gecemdir, 

Üç harf dilimde hecemdir, 

Yardıyısam affet İlyas. 

Kör kuyuyu kaza kaza, 

Ust''olmuşsun yaza yaza, 

Çırak olsak bizler size, 

Vardıyısam affet İlyas. 

Şer görüp de kızmadıysan, 

Gerçekleri yazmadıysan, 

Oyunları bozmadıysan, 

Vurduyusam affet İlyas. 

Dilimde diken gördüysen, 

Kalbimde kaya kırdıysan, 

İnce''cik hüküm verdiysen, 

Yorduyusam affet İlyas. 

Sabit İnce Kayseri 9.8.2004', 'Şiir gibi birkaç kelam,  Yazdıyısam affet İlyas.  Özmenem''e haktan selam,  Verdiyisem affet İlyas.  Manası yok ki çözesin,  Şuaralarla gezes...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ozmenem-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neville-1', 'neville-1-akin-akca-0725g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Anlayacak bir şey kalmayana kadar, hiçbir şeyi anlamayan adam! …” (!) 

-

”Işık. Ondan uzak durmalıydılar.” 

“Işık yoktu kardeşim. Sadece ateş vardı.” 

“Saçma. Neville karanlıkta göremez.” 

“Bunu ona söyle.” 

“Bizim ışıkta gördüğümüz kadar görür. Kesinlikle iyi görüyor.” 

M: “Bir yaratık... karanlıktan kurtulamayacağı bir yerde yakalanmış. Yalnız. yüzlercesine karşı tek başına. 

Yaşamak için anılarından başka bir şeyi yok. Aletleri, arabaları, silahları, hilelerinden başka hiçbir şeyi yok. 

Ama yine de bütün aile onu oradan alaşağı edemiyor.” 

- “Beyazların cennetinden, değil mi kardeşim? ” 

M: “Eski yöntemleri unut kardeşim. Bütün nefretlerini, bütün acılarını. Unut. Sadece… Ailenin bir olduğunu hatırla. Ama o, şu şey…şu çarkın yaratığı… cehennemin motorlarının ve makinalarının efendisi… 

- “Görüyorum. Biz solucanlar gibi saklanıp çürürken… onu aydınlıkta yaşarken görüyorum. Sen ne görüyorsun kardeşim? ” 

M: “Yok edilecek kardeşim, o yok edilecek. Ama silahlarla, makinalarla, yasaklanmış, kötü şeylerle…dünyayı yok eden araçlarla değil. Dünya’yı. Dünya’yı yok ettiler….

M:Bütün bu hayatları, ateşle ve imanımızla arındırdık kardeşlerim… ve işimize devam etmeliyiz. İnancımızla dünyayı temizleyeceğiz…

Neville aşağıya inecek ve yargılanıp günahlarının cezasını çekmek için… ailenin huzuruna çıkacak…

işte temizleme aracımız kardeşlerim. Hiçbir şey ateşten daha iyi temizleyemez.” 

	(Omega Man) 

- - 

intro

Canlılığın kurtuluşu ve bir bilim adamının kanı. Gariptir, yoğruluşu karakterinin Robert Neville’nin; Bir bilim kadını ve kocası ile şairane:

Sanki dolanmışlardı bu dolambaçlı şehrin sokaklarının dönmedolabının daha bir buzdolabı aksinde…

Senaryonun mucitleri; 70’li yıllardaki…. Macera 30 yıl önce başladı! ! 

*

Yalan Inferno, nefret makinalarının tüysüz lordu! Tepede oturuyor, şehre hakim, yüksek binaların! .. Tekerleğin çömez, yalan efendisi! Tekerlek çağının! ...

“Hi, big brother. How’s your ass? ” 

Senin söylediğin, bu kadar düzmece midir, (onlar, o vampirler..)  Aynaya televizyondaki bakıp demecini verdiğin? –

“Hi, big brother:“ belki daha da çok, seni yakmak için -teknoloji düşmanlığı güdenler..  bitmişken şu ya da bu ….

Serum’u da ve işin garibi, kabul etmeyenler -Taş atarak öldürmek için bekleyenler dışarıda seni! ......... 

Tenteyi açarsan; kilitsiz, (Gün ışığına gebe, kendi üstünden kaldırırsan..)

İkinci kat-ranzan''da da olabilirsin, terasta; pencere açık, güneşlenebilirsin: 

Işık, terketmeyen bir dosttur. Karanlığın, serum almaya bile yanaşmayan; denetleyen, insafsız yargıçlarını... birleştiren ışığı, kapkara güncelerden. 

Böcek gibi görmek, tedavi kabul görmeyenleri.. ya da taş/ mızrak atanları /el bombalarına karşı.. 

uygarlıktır evet, ama vampirlerden gelmişti ilk hareket.

Böcekler gibi kaçışmışlardı çünkü, jeneratörün yakıtını doldurunca sen; evin aşağısında ve teki sızmaya çalışıyordu eve.

Birden açıldığında ışıklar, deliği  bulamadı kaçacak mevki.. balkonda kalan ve daldı içeri, körlemesine saldırdı 

bu gecenin beyaz gözlüsü ve anında öldürüldü! 

Taş atan vampirler, yakaladıklarını yakan vampirler ve/ fakat! . Makinalara düşman vampirler, sadece bekliyor karanlıkta: 

Çeliği büken insanlar; yine onu edimsiz süzecek olanlar... 

Jonathan M., maliyeci eskisi, aslında inatçı bir elbise askısı: bir tuzak”la onurlandırmamıştı Neville! Ona sesleniyorum şimdi: 

(Parçalamakla sen sanat eserlerini ve bilimsel aygıtları -ve onca yıldır, kendince yaşamak uğruna sağdan soldan toplanan …

Ve insan canları eklendi buna, önemlisi! !)  Düştün kendi hazırladığın tuzağına, züğürdün..

“Oyunun son aşaması her zaman sürprizlerle doludur, değil mi? ” 

“Dünya’nın başaramamasına üzüldüm.”: Hadi işimize bakalım. 

“Sanki sarı tuğlalı yoldayız da cadıyı görmeye gidiyoruz.”:

Lisa, evet, bu sözleri söyleyen ile düşürdün tuzağa onu ve kandırdığını da…..

a. 

Omega; O bir bilim adamı, ama helikopteri düştü; 

Görevinin başında helikopter pilotu virüs kapınca.

Sığınağından ayrı düştü; ilk işiydi, aşı kendisine yaptı, 

Ulaştığı nokta, artık Los Angeles ya da de ki sen New york’ta…

… Bir araba, boş sokaklarında kalıntılarının uygarlığın 

Teybe taktı kasedi romantik bir blues esintisi 

Apartmanların içinde yığınla onlardan birinin, bir gölge

Vurmak istedi, aşağıdan ateş etti.

Gölgesi altında sanatın –müziğin:ateş eden Neville’di.

Doğmadı Omega Adam, ''araba galerisi-işletmeni''. 

Fakat düştü iş başa: Daldı içeri; 

Olmasa bile pek ‘gıcır’, yeni bir tane kaptı, 

''Yollarda -istemsiz- sürüyen''den: 

Camları, kaportası pek tozluydu. 

(''Mazinin ak mezar taşı, neşter sağanakları''nda; 

Ne olursa olsun, ''ödün verilmeyen bir arka plan'' - 

Olumsuz anılarımızın da, arkasındayız)

Fırlıyor yeni arabasıyla ve bir süre sonra duracak … 

: “Gerçekten çok güzel dostum. Son üç günde geçirdiğim... değişimi fark etmelisin. baktım, gördüm, aslında neyin önemli 

olduğunu... gerçekten anladım. Hep beraber mutlu bir şekilde yaşayamıyorsak... sokakta yürümekten korkuyorsak... 

birine gülümsemekten korkuyorsak... buna yaşamak denir mi? ” 

: Sardığın makara başa, tiyatroda; 

Sana, gösterir eski Woodstock günlerini... 

Eğlenceli bir açık hava konseri... 

İzle! tek seyirci, kendisi... 

İzliyor, rahat yayılırken koltuklara... 

Patlamış mısırı, Omega Adam''ın -ama- yok: 

Sinema teknisyeni O; 

Hem de seyircisi, bu koskoca boş salonun - 

Neyi izliyor, izleyici olarak, onu sormalı; 

Ancak işte, yaşıyor -ve aktör de; 

Oyuncusu artık ama, kendi yaşantısının. 

Uygarlığın verdiği bir çeşit ödün bir yerde; 

Teleferiği taşıyan tellerden sürtünmenin etkisiyle

Saçılan kıymık mızraklar, biz savaştıkça! ! ! 

Zerafet incecik, incecik alevleniyor.

Bir gidiş, saygı duyulması gerekli.

Arabanın teybine koydu içli-içten müziğini,

Sonra yukarı gökdelenlerden birinde bir pencere şiddetle açıldığında

Ki Madison Square olmalı; 

Sarıldı makinalısına ve o, parmaklardan ateş aldı –

ankesörlerin sokaktaki, zangırdayıp

Tüm ortalığı inletmesinden önceydi …

: Sanırsın ki bir barbar -

ama yalnız ve güçlü, konuşur evinde heykel arkadaşıyla:

(Tom Hanks’in Wilson ile konuşması gibi Away’de,

cehennemin sürücüsü bu bilim adamı mı sizce?) 

“Hi, an other day, another die..”

“Bugün şanslıydım, neredeyse başaracaktı…”

- (ama bu bir bilim adamı) 

ve beton evinde, yaşıyor dağ gibi yüksek bir yerde –

kasvet yolunun yücelttiği Bathory gibi.

Böyle müze güzel mi? 

Canlıları barındıran bir mezarlık:

L€aV€, L€aV€ m€ al0n€! ! ! …….

Çalan birden sirenleri, bomboş sokakta, 

Uluorta, ankesörlü telefonların; 

Uyandırdı, yaşayanları ölü! 

: ''Gecenin-güneş gözlüklü''leri'' gelecek diye korkmak - 

Evet: Fazlalar sayıca; 

kaç evine, basırdı gece 

-Ona saldırdı, (Neville’e)  onu rahat bırakmayanlar 

''Gece-gören''ler: Yarasalar, ateş yakıyor - 

Gündüz''ün körleri,..tutam! 

-Körükledikçe hava'', kararmaya: 

“Tanrım! ! 

hava kararmaya başladı! ...” 

Yürüyor boş sokaklarda; bir kalıntı, capcanlı. 

Ateş ederken -gelenlere sorgusuz, üzerine 

-Güneşe bakamayanlar''a... 

Onların aralarında konuştuklarını 

Duymuş muydu acaba? işitmese bile, uzaktan; 

Onlar, ''makinalara karşı bir uygarlıktan. 

Neville''e saldıran, evine girerken 

(Bir şaklaban; üç, beş)

De, yine değil mi, bu yamyamlar… 

* 

… “6306 ‘Rimini, bir sabah koşusunda vardı bulvara

Durdu ve bir kez bağırdı; bomboş, 

Yankılandı, şehrin tümünde. 

b. 

Bir içkili anında ve karanlık bir köşede - 

Salonunda, ardına kadar açık pencereli evinin; 

Işıklar gezinen salonu için, 

onlarla arasına, 

cam koymaya gerek görmediği dört duvarın

-Yakaladılar, yaşamaya uğraşanı; 

büyüleyeceklerdi ileride Lisa’yı, soktular onu ve içeri! 

‘Gece görenler’:

‘Gece görenler’: 

Şimdi….. çilenin huzurunda! ..........

“Orada yatan, bilim adamlarının, bankacıların, 

işadamlarının… çarkı döndürenlerin sonuncusu. 

Çarkın araçlarını onun gibi kullanıyor muyuz? 

O aileden mi? ” 

“Hayır.” 

“Kutsal cemiyetten mi? ” 

“Hayır.” 

“O halde o ne? ” 

“Şeytan (kötülük)  ” 

“Ölüler dünyasına ait o. Burada yeri yok. 

Üstüne petrol ve elektrik kokusu sinmiş… 

Sen geçmişten kalan bir süprüntüsün! ”:

(Geceleyin bu gözlüklerin ardından suçlamak 

Kolaydır makinaları ya da yaşayan tek bilim adamını. 

Ama tan ağartısıyla kaçışanlar izbeye; 

Sorgu yargıcını bırakırlar tekrar tekrar, ışıkta.) 

Siyah kukuletalıların ve gecenin güneş gözlüklüleri’nin 

“Şeytan” diyerek lanse ettikleri, hep bir ağızdan, 

Zifiri karanlığa kendi gözleriyle bakabilen son 

bilim adamını -Komutanlarının demeçleri ardından 

- ama ışıklar açıldı! ve engizisyon ertelendi! 

Büyük bir futbol stadyumuymuş burası! 

Giysi dükkanında gördüğü ve kendinden kaçan 

O zenci kadın kurtardı vampirlerinden karanlığın, onu! 

Kukuletalı meşalelilerin yok onu yakalamalarının artık bir yolu …

* 

“the more we inject, the more serum we get.” 

İnsanların kurtarmak hayatını, zordur; 

Hele, soğuk bir hücrede: 

“Pekala, turnikeyi çıkar.” 

- (Kan vermek için)  bir şişe yetecek mi? ” 

”Bu birinci sınıf Anglosakson kanı, canım.” 

 :) 

: “Diğer doktorlar icat edene kadar… 

Var olmayan hastalıklara tedaviler bulmaya çalışan… 

Sıra dışı bir doktordum… 

Şimdi şehirde bir tek ben kaldım… 

… Mümkün olduğunca sık kan alacağım. 

Yalnızca onu pompalamaya devam etmeliyiz. 

Ne kadar süreceğini bilmiyorum 

…Ama işe yararsa, o zaman Richie 

Daha fazla antikor için kaynak olacak. 

Ne kadar çok insana enjekte edersek 

O kadar çok serum elde ederiz. 

Ve bu da bittiğinde bebeğim, gideceğiz… 

”Ölülerin kemiklerini kaybettiği sıçan vadisi’nden 

Çıkıp gideceğiz…” 

: T.S.Eliot, şair olduğu kadar iyi de bir kahinmiş: 

Çorak Ülke; 

Bu onu rahatlatıyor mu merak ediyorum.” 

c. 

Evine girdiler ''gece’nin güneş gözlüklüleri'' 

Ve yaşamak için gerekli edevatı; teybini, hepsini: 

Ya da kırdılar, serum şişelerinin onun …

Neville’di de, bir uygarlıktan - 

Doğaya gidecek olan -barajlara karşı: 

“Üzerine baraj kurulmamış” bir yere doğru! ! …..

Ancak, “bu defa yılana sarılmıyoruz! ”, bahçesinde cennetin: 

İşte buna çok güldüm: 

Ne olacaksa, her vakit olurken zaten; 

Doğum kontrol haplarını, bari kullanalım. 

”Memurları sayımın”, yolda (! !) 

*

Halbuki sanat eserlerini, baltalarla parçalatmıştı şu Jonathan, Matthias; 

Ama Neville’yi -dolaylı olarak, Lisa’yla- alt etti 

şarkı serenatında büyüleyerek. Müzik bir sanatsa; yalan olan ışıktır:

Bu bir yalandır! ! ! Böceklerin yalanı! ! 

: Ele geçirdiler Lisa’yı, gözleri onun artık yok: 

''Gece-gören''ler, Lisa''yı vampirleştirenler, 

Sayesinde onun, istem dışı; 

Omega Adam’ın; Robert Neville’nin

sızanlar evine: 

(Küllerinden, teknolojinin yıkıntılarının 

Makinalara karşı bir yürüyüşü başlatan, 

Çok kuru bir soğuk: yürüyüş ''uygarlıkta nemli'', 

Fakat umut değildir asla kasvetli)

Kan serumu’nu, hazırladığı Omega Adam''ın - 

Yaşam veren -onun koynunda buldu, Lisa; 

O, artık bir vampirken... 

''Birinci-kıdemli''sinin, ''sahte-gün görenler''in; 

Omega, Matthias’tan göğsüne mızrak yiyen... 

Vampirden, Ay iliştiren duraksız gel-gitlerinden çatısından gecenin! 

(Lisa’yı çağırıp büyüledi serenatında Matthias

ve Neville, dikkat kesilen Lisa’ya,Matthias’tan 

göğsüne mızrak yiyen...) 

Son nefesinde, sabaha kadar ölmeyip 

Serum şişesiyle beklemenin, koynunda sakladığı - 

Veremezken anlam, durumu, onun 

(O tanımaz durumdayken, onu)

-Onu, Lisa''yı... hayata verdi yeniden:

Ölürken bile, hayat bahşetti yeryüzüne! ! ! 

- - 

“Blok 5500’de küçük bir marketi yağmaladıklarına dair izler vardı… yiyecek için… Marketteki fiyatlara bakınca süpermarkete giderler diye düşünürsün… 

“Robert, sen şeytansın. Ben aileden biriyim… Üzgünüm. Sen aileyi… anlayamazsın.

- - - 

Charton Heston''un oynadığı '' The Omega Man'' filmi''ne bir gönderme 

Çift tırnak içindekiler filmden laflar 

İkinci cd’deki trailer üzerine yazdığım kıtalar da mevcut

Film hakkında arka plan 

Pazar geceleri caddeler boş olduğunda Los Angeles’ta çekilmiş. Yönetmen Boris Sagal. Charlton Heston, filmdeki kendi karakterini “killer ape” sözüyle bir ölçüde bağdaştırıyor. Charlton Heston, filmde kullanıyor gözükeceği bilimsel cihazların ne anlama geldiğini ve isimlerini sette ayrı ayrı soruyor, öğreniyor. Filmdeki atmosferi anlamak açısından, filmdeki bir lafında; Matthias ve adamları, Robert Neville evinde jeneratörü doldurmayı unuttuğu zaman ışıkların sönmesi ve Lisa’ya kendini savunması için  silah atan Omega Man’in (Lisa tarafından)  ‘bunun ne olduğunun sorulması üzerine’ cevabı “Comfort”. Filmde Lisa, doğum kontrol haplarını tozlu raflardan bulup

gösterince sergilediği kahkaha müthişti :)

başta yazdığım “bilim kadını” ve “şair”, filme esin olan ve/ya da hazırlayan kişiler. 

Bazı düzeltmeler ve eklemeler yaptım.. saygılar', '“Anlayacak bir şey kalmayana kadar, hiçbir şeyi anlamayan adam! …” (!)  - ”Işık. Ondan uzak durmalıydılar.”  “Işık yoktu kardeşim. Sadece at...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":241,"source_url":"https://www.antoloji.com/neville-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-hakan-liman-95phg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geri dönmeyeceklerini bile bile

Neden ağlarız ki

Eski aşklara

Güneş batmıştır

Kuşlar gitmiştir

Artık

Ve gece

Tüm güzelliğiyle

Gözümüzün önündedir

O siyah üstüne beyaz desenli gökyüzü

Bizimdir

Sabah yeniden doğacağını bile bile

Neden ağlarız ki 

Güneşin ardından

11.08.04', 'Geri dönmeyeceklerini bile bile Neden ağlarız ki Eski aşklara Güneş batmıştır Kuşlar gitmiştir Artık Ve gece Tüm güzelliğiyle Gözümüzün önün...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/neden-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bumerang II', 'bumerang-ii-ahmet-aksoy-6f33o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'soyunan nehir eflatun zamanlarda

hüküm giymiş bir gelindir

öylesine uzar ki dilim dilim diyorum

ay yanlış anlar geceyi

kaç katre taşır içim

sudan sebeplerde elem verir

anlam zincir ellerimde

anlatamam kastettiğim nedir', 'soyunan nehir eflatun zamanlarda hüküm giymiş bir gelindir öylesine uzar ki dilim dilim diyorum ay yanlış anlar geceyi kaç katre taşır içim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bumerang-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narsist', 'narsist-akin-akca-pgb2r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendine bakmayan bir çiçek,

Nehre bakıyor ha? 

Bir merak, mantık adına; 

Ne görüyor? 

Süzüyor

Ve adına ya, bilgi diyor …

Süzen akıl ve böyle …

Kordonlar oluşuyor

Arasında hücrelerinin beynin,

Ama sonra kinin:

Geri kılana, seni; “seni muktedir kılan

Nedir? ” diyor …

Kendiyle çapraşık ya 

Aslında; takıl, 

‘Hisseden’ 

Karmaş''madan, veriyor.

-', 'Kendine bakmayan bir çiçek, Nehre bakıyor ha?  Bir merak, mantık adına;  Ne görüyor?  Süzüyor Ve adına ya, bilgi diyor … Süzen akıl ve böyle...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/narsist-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Zaman Hikayeleri', 'gecmis-zaman-hikayeleri-oguzkan-bolukbasi-9taak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geçmiş zaman hikayelerinde ne arar insan

kendinin başka odalardan çıkacağını mı sanır

ya da kokuların değişeceğini mi kokladığı çiçeklerde

veya bir gülümseme mi arar ya da bir yaşanılmamış hüzün

en güzel yerinde öykümüzün

karşımıza kimin çıkmasını isteriz

hayat bir kuş misali özetidir

küçücüktük büyüdük

takla güvercinleri de yuvaya döner

kartallar da

yuvalarımızı mı ararız geçmiş zaman hikayelerinde

belki de özlemlerin koynunda yuvalanırız

kaç sayfaya sığar yazsak hayatımız

kaç değişik öykümüz vardır

masallardan gayrı yaşanmamış

seni seviyorum dediğimiz kaç yürekte kuşlar havalanmıştır

kaç yürekte kuşlar yaralanmıştır

geçmiş zaman hikayelerinde biz

günahlarımızı çıkarırız

çırılçıplak kalırız

günahsız 

üşürüz', 'geçmiş zaman hikayelerinde ne arar insan kendinin başka odalardan çıkacağını mı sanır ya da kokuların değişeceğini mi kokladığı çiçeklerde v...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecmis-zaman-hikayeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-sair-nadirezheri-4wudg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Men daglarin emoglusu sandim cignini

Dedim o derin goz deniz elcisidir

Ve gumanlar dumanidi

Aza-aza sevdim

Caya-caya opdum

Oxudum azdiglarimi

Oynadim caydiglarimi

Men daglarin emoglusu sandim cignini

Ve caydiglarimla

Azdiglarimla xosam.

(Guney Azerbaycan-Tebriz)', 'Men daglarin emoglusu sandim cignini Dedim o derin goz deniz elcisidir Ve gumanlar dumanidi Aza-aza sevdim Caya-caya opdum Oxudum azdiglarim...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dostuma-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişik* gecelerim!', 'pisik-gecelerim-sair-nadirezheri-e7q90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Quşbazlara diyeceyem

Quşbazlara

Damlarda yubanmiş** quşbazlara

Neçün günü günden eskik gelir quşlarim

Neçun? 

Ax bu ''çox bilmiş''***pişik gecelerim

Ax bu çox bilmiş pişik gecelerim

Pişte! ****

Gör nece alir,dişlerine quşlarimi

Pişte! 

Gör nece ekir***** ümüdlerimi

Siz ne bilirsiniz qemimi

Quşbazlara diyeceyem

Quşbazlara.! 

*Kedi

**Gecikmiş

***Zeki,Riyakar

****Kedileri kovmak için bir çesşid ses

*****Kayb edir

Bu şiir Tebrizin Adine hefteliyinde yayinlanmişdir(yaz 80 güneş yili)

Erdebil-2001', 'Quşbazlara diyeceyem Quşbazlara Damlarda yubanmiş** quşbazlara Neçün günü günden eskik gelir quşlarim Neçun?  Ax bu ''çox bilmiş''***pişik gec...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pisik-gecelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasbelkader', 'hasbelkader-cafer-tayyar-ozkan-zr2la', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharda sineme ektiğin 

nefesi çekiyorum hala,

Umudun zerresi eksilmeden,

Bir an olsun baş kaldırmadım,

Umutla çıkıp, hüsrana uğradığım yolda.

Sevdam sevdan olalı, bilmedi böylesi sevdayı.

Kalbe sevdan dolalı, çekmedi ölesi cefayı.

Nasip olmadı, 

Aşk tacını giymek bunca zamanda.

Umutla kapına gelen murat, 

atılır mıydı hiç yabana? 

Vuslat makamında, 

şarkılar bestelemiştik seninle.

Hasretten dolar gözlerim, 

kalbe girdiğin hazandan bu yana...

Tutmuyorum artık, 

alacağın ahların çetelesini.

Ah keşke! diyeceğin anların gelecek.

Hasbelkader kırınca, 

sahibinin gerçek zincirini.

Dile gelmeyen hasretin 

O vakit karagözlün asla cana girmeyecek...

Gönül dünyasının tek hakimi değiliz,

Bir yudum sevgi için,

yıllar boyu bekleriz.

Haksızlığa maruz kalsak da,

Yine de vefa köprüsünden dönmeyiz...

Yine sana geldim, 

hasretle okşadım yüzünü.

Aynı lokmayı, 

aynı mekanı paylaştık.

Bir yanım sar, 

diğer yanımsa git! dedi durdu.

Lakin bir ukdemle geldiğim yerden,

Yaşayan ukdemi arzularla bırakıp, 

Onur ve şerefimle gitmek...

Ukde uğruna yapamadım... 

08 Mayıs 2004 Bursa', 'Baharda sineme ektiğin  nefesi çekiyorum hala, Umudun zerresi eksilmeden, Bir an olsun baş kaldırmadım, Umutla çıkıp, hüsrana uğradığım yold...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hasbelkader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat-ı Bî-Mânâ', 'hayat-i-b-m-n-zemci-cetinkaya-aed2z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim demiş ağladık kim demiş güldük

Ruhumuza gerçek bir şey dolmadı.

Gün batarken doğduk seherde öldük

Güneş doğdu ama sabah olmadı.

Zaman akıp gitti nehir misali

Gaflet içmişiz ki zehir misali

Gönül bir harabe şehir misali

Baykuşlardan başka kimse kalmadı.', 'Kim demiş ağladık kim demiş güldük Ruhumuza gerçek bir şey dolmadı. Gün batarken doğduk seherde öldük Güneş doğdu ama sabah olmadı. Zaman ak...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-i-bi-mana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maska (Bu menem cirkinlerin boyugu!)', 'maska-bu-menem-cirkinlerin-boyugu-sair-nadirezheri-7a11b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu menem

Cirkinlerin boyugu! 

Alni aciq

Atilmislarin taj-i seri

Bir nagil ki musafirxanalarda qalir

Ve tapanmiram evimi

Xiyavanlar ad deyisir

Ve her kim meni gorur

Maskasini

Imtehan edir

Ohoy! 

Eyri-eyri baxanlar! 

Ciban tek sixirsiz meni maskaniza fiskiracagam

Hele ''pisik*bezeyin''...! 

*Kedi

(Guney Azerbaycan-Erdebil-2000)', 'Bu menem Cirkinlerin boyugu!  Alni aciq Atilmislarin taj-i seri Bir nagil ki musafirxanalarda qalir Ve tapanmiram evimi Xiyavanlar ad deyisi...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/maska-bu-menem-cirkinlerin-boyugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişkinin Türküsü', 'celiskinin-turkusu-zemci-cetinkaya-g8mvy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyanıkken binbir mihnete düştüm

Düşte aydım kâşâneler içinde.

Mabetlere girdim sarhoş dolaştım,

Ayık gezdim meyhaneler içinde.

Hüsrana sarıldım, budur zaferim; 

Bayramlar, bayramlar yevm-i kederim.

Akıllıyken bağlı olan ellerim

Zincirsizdir divaneler içinde.

Her dağın başında rüzgâr bulunur,

Zemheriden sonra  bahar bulunur,

Bu âlemde herkese yar bulunur

Benim yarim efsaneler içinde.

Ne hikmeti bildim ne de sanatı

Farkedince yüzüm kırdım miratı.

Hızır''ın sunduğu ab-ı hayatı

İçemedim peymaneler içinde.

Hevesim kalmadı kemanda yayda

Işık ummuyorum ggüneşte ayda

Şu saki-i felek meclis-i meyde

Beni kovdu mestaneler içinde.', 'Uyanıkken binbir mihnete düştüm Düşte aydım kâşâneler içinde. Mabetlere girdim sarhoş dolaştım, Ayık gezdim meyhaneler içinde. Hüsrana sarıl...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/celiskinin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlerin&Düşüncelerin Süpernovası', 'sozlerin-dusuncelerin-supernovasi-ahmet-ferit-cosan-owg1a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İmgeler çorbam,

Olanca yakamozuyla

Los Angelos''a, bolca kırmızı neonlu,

İzbe bir otel odasına,

Taze kesilmiş bilekten,

Özgürlüğe delilercesine akan,

Damarlardaki sıcacık kana,

Kütür kütür çırpınışlarıyla,

Habire boşluğa kan pompalayan 

Delişmen yüreğe,

Çeliyor aklımıda,

Çağırıyor ötelere yekpare vücudu ve ruhu.

Dumanlanmış kafadan,

Etrafa kör bıçaklar gibi savrulan

Dumanlı bakışlar.

Lavoboda kaybolan can.

Titrek ekranda hayaller satan bir adam,

Ve Basra''da boy veren kan kuleleri,

İhtimal, Los Angelos''un neşeli palmiyeleri üzerine

Kara bir mühür misal basılmış

Şafaktan fırlayıvermiş bu güneşin kızıllığı,

Kulelerin pıhtılı sanrılarından.

Yurdumun güzelim coğrafyasından,

Hırslı istencimle uzaklaşmam,

Zavallı şiirimde boktan Los Angelos mizansenini kullanmam,

Boşuna değil sevgili okuyucu.

Sürreal karmaşam, 

Merkezine çekiyor nefsimi,

Koyu bir girdap misal an ve an.

El verin, yardım dilenen elime,

Uzattığım o kara delikten.

Ve aslı birer katar olan,

Şiir sonundaki noktalar trenine nazar eyleyin.

Atlayın herhangi birisine,

Ülkeme,

Gözyaşları diyarına sefer eyleyin.

O zamandır ki sınırlarımdan girmişsinizdir,

Bir gözyaşı olup, çorak topraklarıma akmışsınızdır,

Medet ummuştur zavallı şair,

Ötelerden gelecek ferahlığa, esenliğe.

Merhemler aramıştır, nazar eylenen dizelerde,

Çelişkilerin kemirdiği zihnine sürmeye.

Sanıldığı gibi değil hiç,

Bir kul şair olsa olsa,

Aslen tanrıdır okuyucu,

Bu izbe şiirin tüm köhne sokaklarında.

Titreyen köpek gözleriyle bekler şair,

Şiiri, emekle okumanın veridği ağır yükle şereflensin diye.

Yarasa kulaklarıyla ses verir geceye,

Kuşatmada kolu kopan esmer gence yaktığı ağıt,

Duyuldu mu, 

Yoksa akisleri mi yalar

Kara duvarlarını ıssız gecenin diye.

Kuldur şair,

Tanrısıdır şiirin okuyucu,

Esenliğe kavuşturur kurumuş

toprakların, kavruk mutsuzluğunu.

Ve el verir biçare gönlün 

Acziyetle büyüyen tüm serzenişlerine.

Bir hiç yazılanlar kağıda,

Boşlukta haykırıştır can havliyle,

Kimselerin, görmediği,

Kokmadığı,

Yücelere kök salan biteviye,

Canım kardelendir.

Kuldur namlu ucunda duran zavallı çocuk,

Şiirdir, eti parçalayan her bir sıcak metal parçası,

Şairdir katil, ömürleri söndürür,

Katildir şair, mısralara noktalardan set çekerde,

Kendi şiirlerini, kendi pisliğinde boğarak öldürür...................

Çuf Çuf Çuf

Çuf

Teşekkürler.

İmgece:

Dize:En derin yalnızlıklarıma giden tozlu, bozuk şoseleri hayatımın.

Nokta: Son, the end, fin, Yitim, merkez

Acı: Yalnızlığında yaşadığın ıstıraplı farkındalık, kalabalıkta yiten sesin

Şair:Hiçkimse, varolmayan, idea.', 'İmgeler çorbam, Olanca yakamozuyla Los Angelos''a, bolca kırmızı neonlu, İzbe bir otel odasına, Taze kesilmiş bilekten, Özgürlüğe delilercesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/sozlerin-dusuncelerin-supernovasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Gelebilirmisin', 'benimle-gelebilirmisin-necmiye-sarpkaya-j87xa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zümrütü-anka kuşunun kanatlarındaki incileri

Toplayabilir misin kaf dağının ardında 

Çılgınca kanat çırpan martıları kovalıyabilir misin 

Deniz kıyılarında deniz kıyılarında

Sayabilir misin ki ağlayan yıldızları yalnız gecelerim de

Zümrüt rengi şafakları karşılayabilir misin  benimle 

Balta girmemiş kuytu ormanlarda 

Aşk merdivenleri toplayabilir misin benimle 

Kırlarda tutsak olmuş papatyalara

Sorabilir misin ahu-zarımı acılarımı

Gülistanlarıma çiy damlaları gibi dökülen 

Gözyaşlarıma dokunabilir misin 

Oturabilir misin yaylalarımda kurulan

Halil İbrahim sofralarına benimle

Ayaklarını denize sallandırıp bekleyebilir misin 

İskelelerde göz kırpan yakamozlarımı bekleyebilir misin

Karanlıklarıma gelebilir misin balığın karnındaki Yunus gibi

Tufanımdan sonra Nuh''un gemisine binebilir misin korkusuzca

Gelebilir misin uçsuz bucaksız çöllerime Kerem gibi serap uğruna 

Rakseden kankırmızısı gelincikleri toplayabilir misin benimle! 

Gelebilir misin ürperten baharıma 

Yakan yazıma

Donduran kışıma

Olabilir misin benim kadar özgür çılgın olabilir misin! ! ! !', 'Zümrütü-anka kuşunun kanatlarındaki incileri Toplayabilir misin kaf dağının ardında  Çılgınca kanat çırpan martıları kovalıyabilir misin  De...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benimle-gelebilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın1', 'sen-varsin1-mustafa-yigit-morpheus-di7tz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdimi Anlattım Garip Sazıma

Perdede, Mızrapta, Tellerde Sen Varsın

Ne Zamandır Uğramadım Yurduma

Havasında, Suyunda, Yolunda Sen Varsın

İçli İçli Ağlayan Deli Yağmur

Hiç Dönüp Bakmıyor Ne Kadar Mağrur

Gökyüzünü Kapladı Büyük Bir Gurur

Güneşde, Yıldızda, Ayda Sen Varsın

Dünya Gidiyor Bilmem Nereye

Hedeflediğim Güne Varırım Diye

Ferhat Kayaları Deliyor, Şirine Hediye

Leylada, Şirinde, Aslıda Sen Varsın

Yolunu Şaşırıp Çöllere Düşmüş

Mecnun Hayalini Leylada Bulmuş

Canına Can, Gönlüne Neşe Katmış

Kalplerde, Gözlerde, Dillerde Sen Varsın

Her Tarafı Yakan Ateşe Bir Bak

Ferhatı Küle Çeviriyor Yakarak

Benden Uzaklaşıyor Gönlümü Yıkarak

Ateşde, Közde, Dumanda Sen Varsın

Aşk Odunda Yalnız Kaldım Ne Çare

Durağa Melhem Olamadın Biçare

Hayat Ne Güzel Oluyor, İnsanları Sevince

Zamanda, Yanımda, Anımda Sen Varsın

 Mustafa Yiğit (Morpheus)', 'Derdimi Anlattım Garip Sazıma Perdede, Mızrapta, Tellerde Sen Varsın Ne Zamandır Uğramadım Yurduma Havasında, Suyunda, Yolunda Sen Varsın İç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-varsin1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp gitme', 'birakip-gitme-sair-errool-84a6s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece olmuş kimin umrunda… 

Kim bilirki senin yalnızlığını 

Bir eli tutup kalbine götürmenin hazzını 

Kim bilirki hissedeceğin o sıcaklığı 

Kimin umrunda ki 

Tutacağın elin parmaklarını en ince ayrıntısına kadar 

İncelemenin verdiği coşku… 

Kimse bilmez yalnızlığımı 

Kimse inanmaz sensiz olduğuma 

Benimlesin ama… 

Sadece amalar var 

Onlar da yalnızlar… 

Gel artık 

Tut şu ellerimden,kalbine götür 

Sarıl,kokunu bırak. 

Gözlerindeki gülümsemeyi bırak 

Kalbini bırak 

Bana,kendini bırak… 

Bırak ama bırakıp gitme….', 'Gece olmuş kimin umrunda…  Kim bilirki senin yalnızlığını  Bir eli tutup kalbine götürmenin hazzını  Kim bilirki hissedeceğin o sıcaklığı  K...', ARRAY['Türk Edebiyatı','Şiir','Şair Errool']::text[], 8.5, '{"poet":"Şair Errool","poet_slug":"sair-errool","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birakip-gitme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-sair-errool-5oqe5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülümse

Ama sadece gülümse

Gülümse ki

Dünyalar benim olsun

Sakın sevdiğini

Söyleme bana

Kaldırmaz bunu yüreğim

Gülümsemen bile 

Yeterken bana

Gülümse sevgili

Ama sadece gülümse

öyle bir an olsun ki...

hem seni kucaklayayayım

hemde aynı anda ölümü..

öyle bir an olsun ki...

hem ay doğsun hemde aynı anda güneş

imkansızlıklar içinde bir dünya olsada

sen sadece benimle ol benim ol...', 'Gülümse Ama sadece gülümse Gülümse ki Dünyalar benim olsun Sakın sevdiğini Söyleme bana Kaldırmaz bunu yüreğim Gülümsemen bile  Yeterken ban...', ARRAY['Türk Edebiyatı','Şiir','Şair Errool']::text[], 8.5, '{"poet":"Şair Errool","poet_slug":"sair-errool","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gulumse-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz', 'sonsuz-nigin-nevaderezi-rtzve', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seferi bir estekenle qonaqlardin

Dodağimdan soyunan gereyli sahilinde 

Indi lal axir

Damarlarim üzümlüyünde

Qatar zirvesi

Ve her seher bir ömür köhnelir

Kipriklerim gişesinde

O qapiciqlarda

Qatar satilanda

Meni qaldir durağlar körpeliyine

Meni bastir poçtapulu arxasinda

Mektubu qisalt

Gelecek indisinde.

Tebriz-2002', 'Seferi bir estekenle qonaqlardin Dodağimdan soyunan gereyli sahilinde  Indi lal axir Damarlarim üzümlüyünde Qatar zirvesi Ve her seher bir ö...', ARRAY['Türk Edebiyatı','Şiir','Nigin Nevaderezi']::text[], 8.5, '{"poet":"Nigin Nevaderezi","poet_slug":"nigin-nevaderezi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonsuz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-abdil-yasaroglu-k2193', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün....

İşte bugün; 

Aldın beni benden,

Taa girdin şu içime,

En hazin en çıkılmayacak bölümünde,

Benimle yaşadın,

Benimle acılara baş koydun,

Benimle daldın uzaklara,

Oysa, oysa sen yoktun.

Sevgim sana ulaşılamayan ilah gibi büyük

Bir anne sıcaklığı gibi derin,

Ve anlatılamayacak kadar özeldi,

Ve ben seni hala yaşıyordum içimde,

Olmayan seni anlatıyordum,

Dostlarıma sevdiklerime...

Gel artık yâr, bitiresin acıları,

Güneş ol doğ bende', 'Bugün.... İşte bugün;  Aldın beni benden, Taa girdin şu içime, En hazin en çıkılmayacak bölümünde, Benimle yaşadın, Benimle acılara baş koyd...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni ve Beni Arıyorum', 'seni-ve-beni-ariyorum-abdil-yasaroglu-jdd1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine gece yarısı,

Gözlerim ışığı bulamıyor,

Karanlıklara bakıyorum,

Çıkamıyorum zindandan,

Kendimi arıyorum,

Seni arıyorum

Yoksun........! 

Benliğime oturmuş iki kelime,

Bu geceler devam ettikçe,

Bu ay ışığı içimde hüküm sürdükçe,

İçimdeki acı dinmeyecek

Ama ne olursa olsun, vazgeçmiyeceğim

Seni aramaya devam edeceğim...', 'Yine gece yarısı, Gözlerim ışığı bulamıyor, Karanlıklara bakıyorum, Çıkamıyorum zindandan, Kendimi arıyorum, Seni arıyorum Yoksun........!  ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-ve-beni-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardan', 'uzaklardan-abdil-yasaroglu-rr0u9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Uzaklardan”, çok ‘uzaklardan’ sevdim onu,

Tıpkı bir çocuğun ekmek istemesi, reçel yemesi gibi,

Bilmemiş değerimi, yanlış anlamış beni...

Yanlış bir batağa saplandım diye...

Dostlarımla, sevdiğim yarla konuşmuş, dert yanmış,

Küfretmiş bana,

Güvenmiş, her şeyi olurmuşum ama,

Yanlış yapmışım ona

Bilmezler Abdil’in boynu bükük olacağını

Düşünemezler, kötü gönlünde yok, iyi niyetli olduğunu,

Her zaman da iyi niyetten kaybedip, kullanıldığını...

Dinle ey dost dinle 

Meğerse beni o ‘uzaklardan’ hiç tanıyamamış', '“Uzaklardan”, çok ‘uzaklardan’ sevdim onu, Tıpkı bir çocuğun ekmek istemesi, reçel yemesi gibi, Bilmemiş değerimi, yanlış anlamış beni... Ya...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yaşaroğlu']::text[], 8.5, '{"poet":"Abdil Yaşaroğlu","poet_slug":"abdil-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzaklardan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seninle', 'hep-seninle-adem-kunt-7ynow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçerdeyim,yalnız,kimsesiz,

Duvarlar soğuk,gece sessiz…

Etrafımda dolanıyor yokluğunun gölgesi…

Yaşamak bu mu,sensiz gölgesiz…

Sana gelmeyi bende istiyorum,

ciğerlerim parçalanırcasına koşarak…

Ama farzet bir rüzgarım ben,

hafif açık pencerenden,

perdeyi aralayarak odana giren…

Sonra yanına uzanan usulca,

soğuk soğuk sana dokunan

ve seni ısıtan benim…

Farkında değil misin? 

Dudaklarını yalayarak,

boğazından içeri ciğerlerine dolan,

ılık nefes benim…

Gözlerini kapadığında,

karşında ben varım…

Kollarının arasına aldığın,

yorgan benim…

Başını koyduğun yastık,

her gece rüyana girende ben! 

Ben senin her şeyinim,

beni tanıdın mı? 

Sabahları seni ben uyandırırım,

öperek yanağından…

Gözünü açtıysan duvara bak,

duvarda ben…

Hadi kalk lavaboya git,

benimle yüzünü yıka,

vur yüzüne beni soğuk soğuk,

saçlarını ısla hafiften,

kaldır başını aynaya bak,

beni göreceksin! ..

Sakın,sakın yüzünü silme,

bırak buharlaşıncaya kadar,

yanaklarından,dudaklarından,

doyasıya öpeyim…', 'İçerdeyim,yalnız,kimsesiz, Duvarlar soğuk,gece sessiz… Etrafımda dolanıyor yokluğunun gölgesi… Yaşamak bu mu,sensiz gölgesiz… Sana gelmeyi b...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hep-seninle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyam Duygularım ve Ben - 14', 'dunyam-duygularim-ve-ben-14-ozden-cakmak-6b21g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç bir yeri sevmiyorum artık

Sensiz gidilen,

Ayaklarım beni hep

İlk gittiğimiz yere çekiyor.

Sensizde gitsem oraya

Hatıralarım bana yetiyor.

Ama gecelerim......

Hep uykusuz, hep sensiz geçiyor.

Ne olur geri dön birtanem

Kalbim seni çok özlüyor', 'Hiç bir yeri sevmiyorum artık Sensiz gidilen, Ayaklarım beni hep İlk gittiğimiz yere çekiyor. Sensizde gitsem oraya Hatıralarım bana yetiyor...', ARRAY['Türk Edebiyatı','Şiir','Özden Çakmak']::text[], 8.5, '{"poet":"Özden Çakmak","poet_slug":"ozden-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dunyam-duygularim-ve-ben-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Tralles*', 'tralles-i-brahim-dikmen-2-rj4cp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice medeniyetlerin beşiği,

buram buram tarih kokar,

toprağı,dağı,taşı.

mehmetlerin kanıyla ıslandı,

üzerine ayla yıldız saplandı,

onlarca cenklerin meydanı.

onu antik kent tralles yapan,

karacasu''da afrodisias,

üzeri sırla kaplı,kayıp şehir.

sultanhisar''da niysa,

festivaller şehri.

karyalıların vatanıydı,

büyük menderes havzası.

didim''de altın sarısı kumuyla,

tanrıların şehri,didima.

söke ve çevresinde,

niceleri var medeniyetlerin,

milet ve piriene.

agorası ve görkemli amfisiyle.

bir ucundan diğerine,

asırlarca evsahipliği yapmış,

onlarca uygarlığın beşiği,

verimli toprakları ve her karışı,

ve ona hayat veren cansuyu,

büyük menderes ırmağı.

tarihe nam slmış efeleri,

yörük oğulları özbeöz türk,

korkusuz çete ayşeleri,

yiğit yörük ali efesi,

yedi düvele nam salmış,

çakırcalı mehmet efesi.

osmanlıya kafa tutan,

atçalı kel mehmeti.

bizler onların kızanları,

yiğitlerin torunlarıyız.

ve onlardan miras bize,

Tralless,antik kent,

sen,egenin gözbebeği.', 'Nice medeniyetlerin beşiği, buram buram tarih kokar, toprağı,dağı,taşı. mehmetlerin kanıyla ıslandı, üzerine ayla yıldız saplandı, onlarca c...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/tralles-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çay Bahçesi', 'bir-cay-bahcesi-mehmet-emin-ozturk-gs60n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çay bahçesindeyim

Sigaranın dumanını çekiyorum içime

Çocuklar çocukluğunu yaşamakta

Yan masada kadınlar

Akşam yemeğini düşünüyorlar

Ne tuhaf

Vakitlerden akşam vakti

Karşı masada dört genç kız

Kahkalalar atıyorlar aldırmadan etrafa

Alaycı bakışlarda hepsi

Bir anne çocuğuna haykırıyor

Çocukluğunu unutmuş gibi

Sizin anlayacağınız

Herkez kendi aleminde...

09/08/2004    20:25 suları', 'Bir çay bahçesindeyim Sigaranın dumanını çekiyorum içime Çocuklar çocukluğunu yaşamakta Yan masada kadınlar Akşam yemeğini düşünüyorlar Ne t...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-cay-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür (Bağışlar mısın?)', 'ozur-bagislar-misin-zulfikar-yapar-kaleli-tekpm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Bir özlem gök gözün, maral bakışın

Kapına gelmişim, bağışlar mısın? 

Baharı dondurur türkü yakışın

Sevdanı bölmüşüm, bağışlar mısın? 

Hayali cihanda devran sürmüşüm

Hafızama nakış nakış örmüşüm

Gözümü açmışım, seni görmüşüm

Bir seni bilmişim, bağışlar mısın? 

Zaferin şafağı gönle doğarken

Çoban yıldızından az daha erken

Bunca gülünecek maskara varken

Ben sana gülmüşüm, bağışlar mısın? 

Kan yüreğe ince ince sızıyor

Talih yaman, her hesabı bozuyor

Ozanlar bu güne ağıt yazıyor

Gözümü silmişim, bağışlar mısın? 

Can verdik, taç bildik kutluluğunu

Burca dikemedik kutlu tuğunu

Senin zaferini, mutluluğunu

Görmeden ölmüşüm, bağışlar mısın?', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Bir özlem gök gözün, maral bakışın Kapına gelmişim, bağışlar mısın?  Baharı dondurur türk...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozur-bagislar-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolarım Gözlerinde', 'dolarim-gozlerinde-muammer-celik-f3nfm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o zaman coktan gitmiş olacağım 

toz kaplanmış izlerime bastığında 

gözlerinde çoktan dolmuş olacağım

rengi solmuş hayalime baktığında

BirDeli

05.08.2004', 'o zaman coktan gitmiş olacağım  toz kaplanmış izlerime bastığında  gözlerinde çoktan dolmuş olacağım rengi solmuş hayalime baktığında BirDel...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dolarim-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Güzeldir', 'hayat-guzeldir-nilgun-tas-hk0w0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki güzellikleri anlatmaya olsaydı geceler eş,

Kimbilir asla doğmazdı belki de güneş.

Anladım ki, hiçbir şey uğruna kafa yormaya değmez,

Değen şeyler de zaten insanı karamsarlığa sürüklemez...

Hayat bence labirentlerle dolu bir manzara,

Sanki gittikçe boşalan bir makara.

İnsan şöyle bir durup, soluklanmalı arada,

Yaşadıklarını düşünüp, bakmalı ardına...

En büyük güzellik, zorluklara rağmen yılmayıp içten bir gülüştür,

Doğruluk ve dürüstlük gonüldeki gonca, yüzdeki güldür.

Güzellikler gelip geçici, hayat bir düştür,

Unutmamak lazım ki, kelebeğin ömrü bile birkaç gündür...

Nil''den inciler... 10.08.2004', 'Yüreğimdeki güzellikleri anlatmaya olsaydı geceler eş, Kimbilir asla doğmazdı belki de güneş. Anladım ki, hiçbir şey uğruna kafa yormaya değ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Taş']::text[], 8.5, '{"poet":"Nilgün Taş","poet_slug":"nilgun-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Kere Sensiz', 'sonsuz-kere-sensiz-esin-ege-kmafq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün sensiz bitiyor ufukta bu akşam

Ve sensiz bir gece başlayacak birazdan 

Ve daha kaç gün batımı, Kaç gece, Kaç sabah sensiz 

Sensiz başlayacak ve bitecek

Sensiz...

Sonsuz kere sensiz 

Sen yoksun ki

Ne anlamı var bu güzelim İstanbul akşamlarının

Ne anlamı var sabah doğacak umut yüklü aydınlık güneşin

Her akşam suladığım sardunyaların, hanımellerinin ne anlamı var

Ne anlamı var ince belli bardakta içmeye doyamadığım çayımın

Tadını senle paylaşamıyorsam

Değmiyorsa bardağımın ucuna dudaklarının ıslağı

Ne anlamı var dalgın ve sensiz seyrettiğim dingin boğazın sularının

Ne anlamı var göğümde uçuşan ötüşen martıların

Ne anlamı var soluduğum havanın

Sonsuz kere sensiz yaşanan hayatın ne anlamı var...

Ne anlamı var ada vapurundan martılara simit atmanın

Ne anlamı var sensizlikten yorgun düşüp

Biçare yanlız yattığım yatağın

Sabah kalktığımda yanımda sen yoksan

Sonsuz kere sensiz yaşanan hayatın ne anlamı var

Ne anlamı var el uzattığım zavallının hayır duasının

Ne anlamı var sonsuz içimde taşıdığım merhametin

Ne anlamı var içimdeki bilgeliğin

Ne anlamı var söyleyin sana sunulmamış bir hayatın

Beraber paylaşılmayan güzelliklerin

Aşkın tutkunun arzuların ne anlamı var

Sonsuz kere sensiz yaşanan hayatın ne anlamı var

Ben feda etmişim bir ömrü bal gözlüm sana

Şikayetim senden değil hep kaderden yana 

Öyle yada böyle kaçınılmaz sona doğru gidiyorum sensiz

Takvimden her sayfa için bir ömür gidiyor

Varsın gitsin giden bin ömrüm olsun sana

Sonsuz kere sensiz yaşanan hayatın ne anlamı var...

Ben yanlız

Ben sensiz

Ben çaresiz

Ben Sonsuz Kere Sensiz...', 'Gün sensiz bitiyor ufukta bu akşam Ve sensiz bir gece başlayacak birazdan  Ve daha kaç gün batımı, Kaç gece, Kaç sabah sensiz  Sensiz başlay...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sonsuz-kere-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sızı', 'son-sizi-ahmet-ayaz-zl9g2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saadet benden uzak semalarda uçarken,

Son sızı saçlarımdan sıkıca bağlamıştı.

Nağmeler canlanarak hayalimden geçerken,

Gözlerim sevgiliye yaş döküp ağlamıştı.

Bir bakış bir heyecan can evimden vuruyor,

Sevgiler filizlenmiş büyüyerek  duruyor.

Yamandır kara sevda dudaklarım kuruyor,

Yılların ötesinde bağrımı dağlamıştı.

Gülmeyin şairlere kaderde bir yazıdır,

Ben O''na aşık oldum sorma kimin kızıdır.

Ayaz''ım yüreğimde ilk ve son bir sızıdır,

Daha çok küçük yaşta karalar bağlamıştı.

HÜZÜN VE RÜYA 2002', 'Saadet benden uzak semalarda uçarken, Son sızı saçlarımdan sıkıca bağlamıştı. Nağmeler canlanarak hayalimden geçerken, Gözlerim sevgiliye ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ayaz']::text[], 8.5, '{"poet":"Ahmet Ayaz","poet_slug":"ahmet-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki KenTiN HiKaYeSi,', 'i-ki-kentin-hikayesi-mine-ozdemirtas-mmw4b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iki şehri birbirine itiyoruz nicedir.

kımıldamıyorlar değil mi? 

bu sabah yokladım hasretini

yerinde yeller esiyor.

sen mi saklandın,

ben mi düşürdüm seni.? 

belki de bilerek değiştirmişsindir kilidin göbeğini! 

suskun çeşmelerin 

sebilinde kururken susuzluk

çatlamış dudaklara

dadanmak zorundamıydı uçuk? 

acımıyor desem / anlarsın ki yalan söylediğimi.? 

aynı buluttan kopup apayrı yerlere

düşerken taneleri

gelişi gibi hep ıslak mı gider yağmur

yıkayarak yerleri? 

iki yakası bir araya gelmiyor işte

neden iliklemek zorundayız ki düğmeleri? 

10/08/2004', 'iki şehri birbirine itiyoruz nicedir. kımıldamıyorlar değil mi?  bu sabah yokladım hasretini yerinde yeller esiyor. sen mi saklandın, ben mi...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iki-kentin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer', 'esmer-nurettin-ozdemir-prxgr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hafiften esmeli bu rüzgar, hafiften.

Bu yağmur inceden yağmalı, böylece.

Bu şehir sarhoş olmalı her saat.

Bu caddeler alabildiğine benim.

Benim için kalkmalı bu tren.

Bu vapur benim için demir almalı.

Beni beklemeli her yolculuk.

Ben gitmeliyim en uzak diyarlara.

Ben esmeliyim rüzgar yerine denizden.

Ben çekilmeliyim kaleye bayrak diye.

Bu ışıklar benim için yanıp sönmeli.

Benim için çiçek açmalı cümle ağaçlar.

Cümle meyvelerin usaresi ben olmalıyım.

Yıldızlar bana göz kırpmalıdır uzaktan.

Ben selamlamalıyım çapkınca gökyüzünü.

Ay benim için doğmalı, güneş benim için...

Ben hükmetmeliyim yedi iklim mevsimlere.

Benim avuçlarımda esir olmalıdır zaman.

Ben söylemeliyim en garip şarkıları.

En çetin emirleri ben vermeliyim ordulara.

En çetin azapları ben duymalıyım.

Bende toplanmalı kimsesizlerin hüznü.

Bende yaşamalı bunca garipliği yetimlerin.

Benden geçmeli toprağa giden yollar.

Tohum bende çatlamalı, bereket bende...

Ben karanlık olmalıyım gözlerin gibi.

Ben değiştirmeliyim kaderini yolcuların.

Bende can vermeli ölmesini bilenler.

Benden sorulmalı suallerin en korkuncu,

En kabadayısı, en cevapsızı...

Ben duymalıyım dehşetini insanların.

Ben çıkmalıyım Allah''ın huzuruna.

Her şeyin yalan olduğunu ben bilmeliyim.

Benim namım okunmalı gerçek üstünde.

Ben sarhoş olmalıyım Esmerim sarhoş! 

Rüzgar gibi hafiften, yağmur gibi inceden...

Bir el değiştirmeli renkleri birer birer.

Benim ayakucumda tükenmeli geceler.

Ben sarhoş olmalıyım Esmerim, sarhoş!', 'Hafiften esmeli bu rüzgar, hafiften. Bu yağmur inceden yağmalı, böylece. Bu şehir sarhoş olmalı her saat. Bu caddeler alabildiğine benim. Be...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/esmer-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Var mı?', 'bir-dost-var-mi-necmi-unsal-0ugic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne  çektiysek biz, ucub  ve bu  kibirden  çektik. 

Gül  fidanını ezdik, diken tohumu ektik.

Ömürler geçti boşa, nurdan günaha sektik.

Başın belası nefsi,  hep ezen bir dost var mı? 

Allah bizim rabbimiz, O mutlak Settar, rezzak.

Tüm noksan sıfatlardan beridir,  hem de  uzak.

Şeytanın mahareti, kullara sinsi tuzak.

İblisin  hilesini hep sezen bir dost var mı? 

Allah bize bizden, şah damarımızdan yakın.

Artık ey kardeş! İman, cennet zineti takın.

Sök gaflet zincirini, kula kulluktan sakın.

Nefsin hor cefasından, bezen bir dost var mı? 

Kavrulup durur küfür çölünde inkar kumu.

Gönül harmanı yelsiz,  bu gözler de kuru mu? 

Bu insan oğlunun ne ki mahşerde durumu? 

Bu garipler yurdunda çok gezen bir dost var mı? 

14 Mayıs 2004 Cuma, Danimarka-Køge 22.44

7+7', 'Ne  çektiysek biz, ucub  ve bu  kibirden  çektik.  Gül  fidanını ezdik, diken tohumu ektik. Ömürler geçti boşa, nurdan günaha sektik. Başın ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-dost-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-nurettin-ozdemir-5ux00', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne sen geliyorsun çocuğum o eski bahçelerden,

Ne de aşkın o sıcak nağmeleri.

Bizi kim kurtaracak bu karanlık gecelerden? 

Ve söyle, kim yenecek bu yenilmez kaderi?', 'Ne sen geliyorsun çocuğum o eski bahçelerden, Ne de aşkın o sıcak nağmeleri. Bizi kim kurtaracak bu karanlık gecelerden?  Ve söyle, kim yene...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kader-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-nurettin-ozdemir-nhsgt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekliyorum seni camlardan, yorgun.

Şarkılar hep o eski makamlardan, yorgun.

Gelince sabahlar gibiyim çocuğum! 

Gidince, akşamlardan yorgun.', 'Bekliyorum seni camlardan, yorgun. Şarkılar hep o eski makamlardan, yorgun. Gelince sabahlar gibiyim çocuğum!  Gidince, akşamlardan yorgun....', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yorgun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asit Yağmurları', 'asit-yagmurlari-gul-bahtiyar-ikudo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asit yağmurları yağardı, ben çocukken,

Lekeli gözyaşlarını bırakırdı gökyüzü kendiliğinden,

Para ve petrol kokusuyla kararan kalplerden,

Masum cesetler yağardı paramparça olmuş bedenlerden,

Asit yağmurları yağardı Adana semalarından,

Körfez savaşında bombalar patlarken taa derinlerde,

Gökyüzü sevmediği bu siyah renkle çatışırken,

Balıklar ve martılar kıyıya vururdu ceset ceset,

Hiç sevmediği bu kıyılara yanaşmak bile dilemezken,

Asit yağmurları akardı yerlerden,

Alabildiğince çamurlu ve siyah.

Asit yağmurları yağardı masum canlar alınırken,

Dul,yetim ve öksüzlerin sesleri  rüzgarda ağıt ağıt nağmelenirken,

Asit yağmurları yağardı ben küçükken.

Asit yağmurları yağardı savaşın anlamını bile bilmezken,

Küçücük yüreğimi bu insanlık dramı sızlatırken.

Hayat tiyatrosunun gerçek sahneleri perde perde izlenirken,

Ateş düştüğü yeri yakar misali,

Seyirciler tek tek siler bu savaşın izlerini kendilerinden.

Şehitlerin acıları mızrak gibi delip geçer anne ve eşlerin yüreğinden,

Bir haykırış sesi yükselir “neden” sorusunun cevabı için inlerken.

Mezar taşlarını sulamak için asit yağmurları yağarken,

Galip taraf başarılı  bir şekilde tarihe altın harflerle adını  kazırken,

Mağlup taraf bu insanlık dramının yaralarını sarmaya çalışır inceden inceden.

Savaşta patlatılan rafinelilerden katman katman buharlaşan petrol karışıp gökyüzüne.

Asit yağmurları olup yağar benim için ölenler nerede derken? 

Asit yağmurları yağar gözleri yakan,

Asit yağmurları yağar insanlığı siyaha boyayan,

Asit yağmurları yağar hak-adalet kavramlarını arayan,

Asit yağmurları yağar “neden neden” diye bir yakarış olup,

 İnsanlığın üzerine lekelerini bırakırken.', 'Asit yağmurları yağardı, ben çocukken, Lekeli gözyaşlarını bırakırdı gökyüzü kendiliğinden, Para ve petrol kokusuyla kararan kalplerden, Mas...', ARRAY['Türk Edebiyatı','Şiir','Gül Bahtiyar']::text[], 8.5, '{"poet":"Gül Bahtiyar","poet_slug":"gul-bahtiyar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/asit-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle İnsan Oğlu Bekle Sıranı', 'bekle-i-nsan-oglu-bekle-sirani-murat-demir-wfyr7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateş almış yanar canlar gören yok

İnsanların feryadını duyan yok

Hadi sende; yeter artık diyen yok

Bekle insan oğlu bekle sıranı

Hazırlık yap sarmak için yaranı

Hala savaş dersin sen bu işgale

Bak güzelim vatan geldi ne hale

Kanı seven dönüp bakmaz suale

Bekle insan oğlu bekle sıranı

Hazırlık yap sarmak için yaranı

Sanma yalnız benim selam okunur

Dur; sanada bir gün ucu dokunur

Bana vuran sana daha çok vurur

Bekle insan oğlu bekle sıranı

Hazırlık yap sarmak için yaranı

Şarapneller başımızda uçuşur

Ölen ölür ölmeyenler koşuşur

Bedenimde kalp titreyip can üşür

Bekle insan oğlu bekle sıranı

Hazırlık yap sarmak için yaranı

Murat der ki insanlığım şüphede

Düşman gelmiş öldürüyor, dost nerde

Öyle ya da böyle, bir gün bir yerde

Bekle insan oğlu bekle sıranı

Hazırlık yap sarmak için yaranı', 'Ateş almış yanar canlar gören yok İnsanların feryadını duyan yok Hadi sende; yeter artık diyen yok Bekle insan oğlu bekle sıranı Hazırlık ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bekle-insan-oglu-bekle-sirani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben bende değilim', 'ben-bende-degilim-umut-gungor-m8lb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamaya alış artık benimle,

Bedenim uzak kalbim seninle,

Beni andığında tatlı dilinle,

Sana çok yakınım unutma beni.

Kovsanda gidecek gibi değilim,

Ben kalben bile bende değilim,

Vazgeç inadından sevip sevilelim,

Sana uzak değilim unutma beni.

Avutmaya çalışma çocukmuş gibi,

Ben susuz kalmış çiçeğin dibi,

Karda açan kardelen çiçeği gibi,

Yüreğine sor iyi bilecektir.', 'Yaşamaya alış artık benimle, Bedenim uzak kalbim seninle, Beni andığında tatlı dilinle, Sana çok yakınım unutma beni. Kovsanda gidecek gibi ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bende-degilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıksız Sabahlara Merhaba...', 'isiksiz-sabahlara-merhaba-i-brahim-ethem-bingul-8i4tq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haziranda savrulan küllerim

Ağustosta toplanıp cenderelere girecek

Cehennem zindanlarında,prangalarda yürek...

Yağmurların gözyaşında saklı adın

Toprağın neminde beyaz lâleler suskun

Sabun köpüğü bakışlar melül ve dalgın...

Dağların kuytu mağaralarında

Tütünlü yalnız akşamlara

Seni bulamayacağım gönül yollarına

Işıksız sabahlara merhaba...', 'Haziranda savrulan küllerim Ağustosta toplanıp cenderelere girecek Cehennem zindanlarında,prangalarda yürek... Yağmurların gözyaşında saklı ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/isiksiz-sabahlara-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha sen yüreği konuşturmadın', 'daha-sen-yuregi-konusturmadin-umut-gungor-llqgo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha sen yüreği konuşturmadın,

Bir türlü onları konuşturmadın,

Gönlünden korkuyu savuşturmadın,

Yürek kilidini açmadın gitti.

Arzuları kafesledin gönlüne,

Acımadın geçip giden ömrüne,

Bir çarptın kapıyı yürek sözlüne,

Yürek düğümünü çözmedin gitti.

Kaçıyorsun yine aşık olmaktan,

Korkuyorsun dallarıma konmaktan,

Çektiğin belli saçın yolmaktan,

Yürek çiçeğini saçmadın gitti.

Yürek dilin açılmazmı bilemem,

Sensiz gözyaşımı asla silemem,

Sevda köprüsünden yalnız geçemem,

Şu yürek dilini açmadın gitti.', 'Daha sen yüreği konuşturmadın, Bir türlü onları konuşturmadın, Gönlünden korkuyu savuşturmadın, Yürek kilidini açmadın gitti. Arzuları kafes...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daha-sen-yuregi-konusturmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan deli gönül uyan,', 'uyan-deli-gonul-uyan-umut-gungor-idwtr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyan deli gönül uyan,

Korkma yok bizleri duyan,

Bir güzel olsa yıkayıp yuyan,

Dillerimiz şakırdı inanki.

Aç kulağını yürek sesine,

Senin derdin elalemin nesine,

Canmı serdin sevgi sesine,

Harcıyorsun ömrünü inanki.

Bir türlü keyfine bakamazmısın,

El ense bir güzel yatamazmısın,

Zevkleri cefaya çatamazmısın,

Desene gönül senle işim zor.

Bir daha uyandırmam bilesin,

Bindiğin rüyalardan inesin,

Al mendil gözyaşını silesin,

Uyanmazsan seninle işim zor.', 'Uyan deli gönül uyan, Korkma yok bizleri duyan, Bir güzel olsa yıkayıp yuyan, Dillerimiz şakırdı inanki. Aç kulağını yürek sesine, Senin der...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyan-deli-gonul-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kaçıyorum...', 'senden-kaciyorum-tulay-sustam-uf1es', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Topladım bavulumu gidiyorum

Senden çok uzak bir şehirde

Seni (g)   özlüyorum

Yalın ayak yürüyorum kar üstünde

Buralar da sensiz üşüyorum

Bir tepe de seni (g)   izliyorum

Dostlar soruyor ''deli yürek'' nereye? 

Yüreğimden değil, yârdan kaçıyorum

Gidişime bir türkü yakıyorsun 

Erzincan''lıymış adı Tülay...

Ben seni her şeye rağmen... seviyorum...

Seni seviyorum

Seni seviyor

Seni sevi

Seni sev

Seni.....', 'Topladım bavulumu gidiyorum Senden çok uzak bir şehirde Seni (g)   özlüyorum Yalın ayak yürüyorum kar üstünde Buralar da sensiz üşüyorum Bir...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-kaciyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atsız Ata', 'atsiz-ata-orkun-isik-kqfsu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine tutuştu kıvılcımlar 

yanmakta buram buram 

gidiyorken atsızın otağına 

anlamını yitiriyor dünyam 

tut ellerimden ey kürşad ata 

beni koşsunlar ötüken denen ata 

yelesinde son bulsun muradım 

yüreğim türklük için ata ata...', 'yine tutuştu kıvılcımlar  yanmakta buram buram  gidiyorken atsızın otağına  anlamını yitiriyor dünyam  tut ellerimden ey kürşad ata  beni ko...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/atsiz-ata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye?', 'niye-hasan-dogan-ezgfk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben zaten sana kurban olmuştum,

Niye canım bildiğimi benden alıyorsun? 

Ben zaten senin için ölürüm demiştim,

Niye hançeri sen saplıyorsun? 

Sen istedin diye çok uzaklardan gelmiştim,

Niye bir adım da sen gelmiyorsun? 

Canım,birtanem,herşeyim sensin demiştim, 

Niye yüzüme bakamıyorsun? 

Sana uzak sahillerden taşlar getirmiştim,

Niye onlarla hayal çerçevemi kırıyorsun? 

Canım seni çok seviyorum demiştim,

Niye sevgime güvenmiyorsun? 

Şimdi gözyaşlarım,ah bu gözyaşlarım,

Alemdeki tüm dalgalarla bir olmuş göğsüme vuruyor,

Ölüyorum Ey Aşkım! Niye seyirci kalıyorsun? 



                 09.08.04.    AKSARAY', 'Ben zaten sana kurban olmuştum, Niye canım bildiğimi benden alıyorsun?  Ben zaten senin için ölürüm demiştim, Niye hançeri sen saplıyorsun? ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niye-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Aslı Yok Yaylası', 'askin-asli-yok-yaylasi-bekir-mutlu-gokcesu-ansa4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben üşürken

Yokluğuna

Aşkın 

Aslı yok yaylasında

Bazen

Hiç bir bağı olmamak

Bile

O kadar çok şey ki

Aslında...

Köşe başındaki simitçi

Yanındaki boyacı

Gazeteci, çaycı

Öteki, beriki...

Sabahları 

Tepende turlayan martı

Radyodaki şarkı...

Hepsi, hepsi

Daha yakın sana...

Ya ben öylemi? 

Tutabilir misin? 

Uzatsam ellerimi...

Görebilir misin? 

Gözlerimdeki seni...

Silebilir misin? 

Parmak uçlarınla

Sensizliğimi...', 'Ben üşürken Yokluğuna Aşkın  Aslı yok yaylasında Bazen Hiç bir bağı olmamak Bile O kadar çok şey ki Aslında... Köşe başındaki simitçi Yanınd...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/askin-asli-yok-yaylasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim', 'mevsim-ali-gencay-8ng8v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karaçalı 

Devedikeni

Kanayan eller 

Lal olmuş diller

Sen düşler eskiten! ! 

Sorduğun zaman

Çok değil iki hece

Altı üstü

Dört mevsim

Yıllar! ! 

I- Bahar

Çiçekler giyinmelisin 

Açmalı

Elbisende

Gül_i zarlar

Saçlarında 

Yalancı papatyalar

Yağmurlar yağacak

Islanacak saçların

Yeşerecek yüreğinde çimenler

Kumrular yatacak yumurtaya

Çıkacak

Çirken ördekten kuğular

Uçurmalısın 

Uğurlarla böceklerini

Onlar gelir sana

Kucağında

El değmemiş 

Baharlar

II- Yaz

Anlatmayacağım

Birkaç hece

Sıcağı hiç sevmedim

Güneşin öcü

Kavrulan tenler

Kaçışan bedenler

Bunaldım! ! 

hasretim

Özlemim

Diğer mevsimler

III- Sonbahar

İşte benim

Sıyrıldım yangınlardan

Sarılarla

Ben geldim

Hasat zamanım

Ektiğimi biçmeliyim

Atayım kendimi hıyabanlara

Adım,adım yaklaşmalıyım

Sana! ! 

Ayaklarıma takılan gazeller

Dilimde hüzzamlarla

Geceleri ayrı güzeldir

Ayın şavkını kızıl

Sanırsın

Yangınlarda

Ayrılıklar mevsimi

Sonbahar

Sen doğmalarımdan önceki

En güzel ölümümsün

IIII- Kış

Örtün! ! 

Üzerimi yanıyorum

Avut beni kar

Ben siyahların adamıyım

Önce saçlarıma düşsün

Beyazlar

Donmalı en ayazında

En büyük sevdalar

Açacak biliyorum

Bağrımın tam ortasından

Kardelenler arsızca

Gömüm beni

Kefenim kardan

Lahitimi dikin

Buzdan

Yeniden dirileceğim

Fışkıracağım

Topraktan', 'Karaçalı  Devedikeni Kanayan eller  Lal olmuş diller Sen düşler eskiten! !  Sorduğun zaman Çok değil iki hece Altı üstü Dört mevsim Yıllar! ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/mevsim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Bir Bilsen', 'bir-sen-bir-bilsen-hasan-can-9yp2j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Giderken ardından bakındım, sen görmedin.

Ağlamaklıydım, gidiyordun, beni terkediyordun,

Bile bile yüreğimi ateşe atıyordun,

Severken delicesine acımadan gidiyordun.

Aslın da görmüştün ardından baktığımı

Hissetmiştin çünkü sende sevmiştin

Benim halimden birtek sen anlardın

Birtek sen bilirdin yaralı yüreğimin sancısını

Acıyla çırpınışını....

Bir sen vardın, senden önce de 

Sonra yine sen olacaksın.

Sonbahar yaprakları düşecek,

Ne sevdalar geçecek,

Ne hayaller bitecek,

Ne umutlar tükenecek bu yolda,

Bir sen, birtek sen bitmeyeceksin.', 'Giderken ardından bakındım, sen görmedin. Ağlamaklıydım, gidiyordun, beni terkediyordun, Bile bile yüreğimi ateşe atıyordun, Severken delice...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sen-bir-bilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Işıklar Şehrinde Bir Kız', 'mor-isiklar-sehrinde-bir-kiz-necmettin-davulcu-x89jx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güzeldi

inci gözlerle bakardı dünyaya

		       gülerdi

gül açardı gözleri gülünce

mor ışıklar şehrinde

	yağmurda gezerdi akşamları

                                   sevdaydı

sevda kokardı

sevda tutardı elleri

bir çiğ tanesiydi gözleri

		parlardı

içinde bir küçük çocuk olurdu hep

hüzün kokardı aslında

kocaman yüreğiyle

mor ışıklı şehirde yaşardı', 'güzeldi inci gözlerle bakardı dünyaya 		       gülerdi gül açardı gözleri gülünce mor ışıklar şehrinde 	yağmurda gezerdi akşamları          ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mor-isiklar-sehrinde-bir-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyze', 'teyze-i-smet-barlioglu-6dsy0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-1-

Hay ''lardan kazanmış da Huy ''lara vermemişti,

Hasan Tahsin Yıldırım kötü gün görmemişti.

Bilmiyordu dünyada bir denge olduğunu,

Kefeden eksilenin yerine konduğunu.

Sanıyordu hesaplar öte dünyanın işi,

Adamın düşüncesi kırabilmek kirişi.

Kaç köşeyi dönmüştü sayısı hiç bilinmez,

Bilmiyordu kandırmak insanı iflah etmez.

Derler ki; var dünyada çok sağlam muhasebe,

Onun işi dengedir sen onu bilmesen de.

Kimden ne eksilirse o olur alacaklı,

Kim fazladan alırsa o olur verecekli.

Eksik tamamlanmazsa; fazlalar verilmezse; 

O hesabı düzeltir, borçlular düzeltmezse.

Hasan Tahsin Yıldırım böyle olmuştu zengin,

''Hasan Tahsin'' dediğin şişelerden çıkan cin.

Yani bir tek mikropken oldu koca bir ejder,

Hem de öyle ejder ki; denizi versen içer.

Amansızca öğütür taşı koysan önüne,

Vantuzlarla yapışır önünde gördüğüne.

Az zamanda bu adam kurdu döviz bürosu,

Başlamıştı ötmeye piyasada borusu.

Taşıyordu parayı bankaya vagonlarla,

Depoladı parayı şurya-burya tonlarla.

Ele güveni yoktu, işi kendi yapardı,

Parasına can verir, ilah gibi tapardı.

Öyle çalışırdı ki; sanki resmi daire,

Çalışma saatinden asla vermezdi fire.

İş içinde kat ''iyyen tuvalete gitmezdi,

Paydos-maydos etmeden yemek-memek yemezdi.

Çöpe baksa; çöp olur onun gözünde para,

Para diye bakardı taşlara, topraklara.

Evi-barkı da yoktu bu zengin muhteremin,

Kalırdı odasında istediği otelin.

Çoluk-çocuğu yoktu, zaten umursamazdı,

Sokakta tek kadına, tek bir kıza bakmazdı.

Aklı-fikri paraydı, aldığı soluk para,

Parasız selam bile vermezdi insanlara.

-2-

Bir gün geldi büroya genç irisi bir adam,

Kıl kadar farkı yoktu Yunanlı ilahlardan.

Genç adam fildişinden bir çehre sahibiydi,

Simsiyah saçlarıyla tıpkı artist gibiydi.

Çok kibar giyinmişti, uysaldı davranışı,

Denizlerden farksızdı o masmavi bakışı.

Bir ferahlık, soyluluk yer almıştı sesinde,

Gülün kokusu vardı taptaze nefesinde.

Gülümseyince çıktı inci dişler ortaya,

Bambaşka bir atmosfer iniverdi büroya.

Dedi: ''Affedersiniz, görüşmek istiyorum,

Vaktinizi almaktan çekinip ürküyorum.

Fakat işim önemli, karınız söz konusu,

Bana vakit ayırmak iyi olur doğrusu.

Ziyaretim ilgili yirmimilyon dolarla,

Benim başım hoş değil zıpçıktı bürolarla.

Büronuz çok ciddiymiş, çok duydum şöhretini,

Lütfen değerlendirin benim ziyaretimi.

Efendim, bir teyzem var; cimri, titiz bir bunak,

Asla mümkün olmuyor bu kadına yaranmak.

Allah çocuk vermemiş; kendisi dul kadındır,

Sağolası yine de vicdanlı bir hatundur.

Ben öksüz olduğumdan beni evlad edindi,

İnanın sayesinde ben çok rahat ettimdi.

Teyzemin işlerini bizzat takip ederim,

Yapması gerekeni bizzat ben öğütlerim.

Fakat aksi insandır, kimseye güven duymaz,

Karun kadar zengindir, bankaya para koymaz.

Kar etmeyi pek sever, sinekten yağ çıkarır,

Çıkarına az bassan kıyametler koparır.

Zengin olduğu halde tam hizmetçi kılıklı,

Zaten altmış yaşında, güçsüz ve hastalıklı.

Bilirsiniz; paranın hiç değeri kalmadı,

O kadar kemer sıktık enflasyon azalmadı.

Yani tasarruf etmek en büyük enayilik,

Zira para eriyor durdukça, ilik ilik.

Teyzemin yaşı fazla, yatırım vız geliyor,

Haliyle parası da durduk yerde eriyor.

O düşünmez bunları ama ben düşünürüm,

Çünkü geleceğimi bu servette görürüm.

Teyzem ölüp gidince servet bana kalacak,

O nedenşe bu işe biraz katkım olacak.

Diyeceğim şudur ki; ben dolar peşindeyim,

Yarın için planlar yapacak yaşımdayım.

Teyzemi ikna ettim; eşanjman yaptıracak,

Türk parası vererek biraz dolar alacak.

Talep ettiği dolar şimdilik yirmimilyon,

Bakalım neler saklar öbür yüzde madalyon.

Mayayı saldım gitti, inşallah yoğurt tutsun,

Öyle kar alınız ki; sizi bir yıl korutsun.

Tavuklar esirgenmez kaz gelecek yerlerden,

Yeğenler de geçinsin yaşlanmış teyzelerden.

Demiştim; hastalıklı, yaşlı ve cimri teyzem,

Ben onu döviz için buraya getiremem.

Mecburen gitmeliyiz dövizle ayağına,

Jesttir ki yapmalıyız bu varlıklı kadına.

Yirmimilyon doları çantaya yerleştirin,

Çantanız elinizde benimle eve gelin.

Alın Türk lirasını, teslim edin dövizi,

Teyzem abad eylesin hem beni hem de sizi.''

Hasan Tahsin doldurdu çantaya dolarları,

İndiler inişleri, çıktılar yokuşları.

Yürüyüş on dakika, onbeş dakika sürdü,

Derken yaşlı teyzenin evi-barkı göründü.

Ev tek katlı bir evdi, benziyordu villaya,

Birkaç tık-tak vurdular çift kanatlı kapıya.

Kapıyı teyze açtı, yaşlı, modern bir kadın,

Yüzü-gözü buruşuk, tam Osmanlı bir hatun.

Süsünden, giyiminden belliydi soyluluğu,

Tutumu koymaktaydı ortaya ululuğu.

Dedi: ''Demek geldiniz, buyurun içeriye,

Çok fazla geciktiniz, artık bilmem ki niye.

Buyurun, geçin, geçin, bir kahve pişireyim,

Kahvemizi içerken paketleri göreyim.

İçeriye geçerek girdiler bir odaya,

Odada çok şey yoktu; bir duvarda bir ayna.

Yerde bir-iki kilim, birkaç kirlenmiş koltuk,

Duvarda birkaç resim, hem çok eski hem soluk.

Başka şey de arama; teyze yaşlı. Gerekmez,

Zira; yaşlı terazi herbir yükü çekemez.

Erkeklerin herbiri bir yer bulup oturdu,

Yaşlı, güngörmüş teyze kahveleri getirdi.

Hal ve hatır sordular kahveleri içerek,

Kadın yerinden kalktı paketi isteyerek.

Dövizci çantasından çıkardı paketleri,

Onları sarmaladı teyzemizin elleri.

Kadın saymadı bile paketteki dövizi,

Kayıtsızca gezindi üstünde iki gözü.

Duvardaki küçücük dolabı tutup açtı,

Pakete hiç bakmadan içeriye bıraktı.

Dedi: ''Borcum ne size? Ne kadar vereceğim? 

Türk parası olarak peşin ödeyeceğim.

Dövizci gülümsedi: ''Beşyüzmilyar ediyor,

Onların değerini yeğeniniz biliyor.''

Kadın gülerek dedi: ''Parayı getireyim,

Bana makbuz da verin, sizden rica edeyim.''

Kadın anahtarları koydu dolap üstünde,

Sonra odadan çıktı iki eli böğründe.

Dövizci hazıladı vereceği makbuzu,

Delikanlı dedi ki: ''Affediniz domuzu,

Kimseye güveni yok, çöp alsa makbuz ister,

Sanki bütün insanlar ya katil, ya gangster.

Sanki kadın serveti mezara götürecek,

Ahrette zebaniye makbuz ibraz edecek.''

Güldüler, gülüştüler, hayli sohbet ettiler,

Teyze görünsün diye bir hayli beklediler.

Delikanlı gülerek ''Şuna bakayım.'' dedi,

''Ya para sayıyordur ya kuyruğu titretti.

Keyfinize bakınız, ben şimdi getiririm,

Geciktiği içn de özürler diletirim.''

Dövizci çok rahattı, zira; dolap önünde,

Üstelik anahtarlar destesiyle üstünde.

En küçük pürüz çıksa, alırdı dolarları,

Gelenler olmayınca çevirdi anahtarı.

Dolabı açıp baktı, inanmadı duruma,

Dolabın dibi yoktu, inme indi adama.

Ya dolarlar? Onlar yok. Yel wsiyor yerinde,

Kasılmalar başladı adamın ellerinde.

Öyle bir haykırdı ki; tavanlar yere indi,

Ne bir kapı açıldı, ne bir kimse gçründü.

Fırladı ki odadan, ev zaten tek odalı,

Sanki yüzyıllar geçmiş hırsızlar kaybolalı.

Ev önünde kükrerken rastladı bir adama,

Adam dedi: ''Bu evi kiraladık onlara.

Ne bileyim a beyim, güya teyze-yeğenmiş,

Baksana, namussuzlar evi çoktan terketmiş.

Yalnız iki gün oldu bu ev kiralanalı,

Böyle iş görmedim ben, ev sahibi olalı.''

Birlikte duvarları dışardan yokladılar,

Dolap hizasındaki kanala rastladılar.

Adam dedi: ''Vay anam, duvarımı delmişler,

Dolabın yam içinden dışarı yol vermişler.

Her ne koysan dolaba haydi yallah dışarı,

Rabbim neden yarattın bu kötü insanları? ''

Dövizci saç-baş yoldu, hırladı, inildedi,

Çektiği ızdıraptan yer kalktı, gök gümledi.

Dedi: ''Tanıman gerek ikisinden birini,

Birini bir buldummu bulurum obirini.''

Ev sahibi dediki: ''Kadını biliyorum,

Arada bir tepeye çıkarken görüyorum.

Sanırım ki; bu kadın Huzurevi ''nde falan,

Çünkü başka yol geçmez o tepenin oradan.

Gördüğümde, kadının file vardı elinde,

İnan ki se; o kadın mutlak Huzurevi ''nde.''

Dövizciye gün doğdu, ışıklandı gözleri,

Toplanan insanları yardı, itti elleri.

Zaten polis gelmişti kalabalığı görüp,

Dağıttı topluluğu birkaç düdük öttürüp.

Problem anlatıldı, bilinenler söylendi,

Olanlar sık dokundu, ince ince elendi.

Ev sahibi, dövizci, polis bindi otoya,

Huzurevi ''ne doğru hemen çıkıldı yola.

Az gitti uz gittier Huzurevi ''ne kadar,

İlk soluğu müdürün odasında aldılar.

Öyküler yenilendi, herkes aydınlatıldı,

Teyzenin macerası tümüyle anlatıldı.

Teyze hanım bulundu ve çağrıldı makama,

Bütün gözler dikildi orta yaşlı hatuna.

Herkese tatlı tatlı gülümsüyordu kadın,

Tavrında yeri vardı, merhametin, şefkatin.

Herkesle tokalaştı birşey olmamış gibi,

Hepsine gülüyordu yorgun gözlerin içi.

Müdür dedi: ''Yalnızdır. Yok dünyada kimsesi,

Bu hanım evimizin inanın, bir tanesi.

Adı Müzeyyen Hanım, kendisi Yerköylü ''dür,

Seçkindir, sevecendir, hassas ruhlu biridir.

Yanında bulur onu her kim darda kalırsa,

Dışarı çıkıp gezer canı çok sıkılınca.

Herkese yardım eder, herlese yakınlaşır,

İşlediği mendiller elden ele dolaşır.

Eline her ne geçse yemeyip biriktirir,

En içten sevgilerle ona-buna yedirir.

Ak sütte leke olur, bu hanımda olamaz; 

İşi-gücü şükretmek, oruç tutmak ve namaz.''

Hasan Tahsin haykırdı: ''Bu kadın o Teyze ''dir! ..

Ben elleri bilemem, tek tezgahı bizedir! ..''

Dedi: ''Sen almadın mı ellerimden paketi,

Götürüp atmadın mı o dolaptan içeri? ''

Kadın gülümseyerek yaklaştı dövizciye,

Dedi: ''Bugün rastladım ben o evde bu beye.

Oluyor iki-üç gün, bir gençle karşılaştım,

Yürüdü bana doğru, onunla selamlaştım.

Elimdeki filede meyve ve sebze vardı,

Yük yaşlı bedenimi çok incitir, zorlardı.

Delikanlı uzanıp aldı filemi elden,

Belli ki; hoşlanmıştı genç adam biraz benden.

Teyzesi vefat etmiş, mezarına gidermiş,

Vefat eden teyzesi tıpkı bana benzermiş.

Beni ilk gördüğünde zannetmiş ki; ben oyum,

Bunları öğrenince kırıldı elim-kolum.

Yakışıklı bir gençti acıdım zavallıya,

Yokmuş bir tek kimsesi, şu zalim dünya bu ya.

Lokantada çalışıp yaparmış yüksek tahsil,

İnce narin bir beden, baldan tatlı güzel dil.

Parklarda yatıyormuş; otele yok parası,

Bekara kiralık ev el vermez, kahrolası.

Dedi ''Bana yardım et, teyzemmiş gibi davran,

Kiralık ev bulayım, böyle istiyor devran.''

İnsanlık ölmüş mü ya? Yaptım dediklerini,

Bularak kiraladık şu adamın evini.

Döndüm binbir neş ''eyle ben bu Huzurevi ''ne,

Sevincimden sığmadı yüreğim içerime.

Biliyordum öyle genç kimseye pek yük olmaz,

Elin garibanının tek ricası kırılmaz.

Yaptığım doğru değil fakat hayırlı işti,

Yoksa delikanlının ömrü kayıp gitmişti.

Telefonla aradı ertesi gün gariban,

Dedi: ''Teyzem, dardayım, muhtacım sana, aman.''

Varıp gittim yanına, sordum problemini,

Görüverdim bu yüzden döşediği evini.

Birkaç koltuğu vardı, bir-iki de kilimi,

Merhamet pençesine almıştı yüreğimi.

Evi tek odalıydı, biz öyle kiraladık,

Hem yeterdi o gence, hem başka bulamadık.

Delikanlı dedi ki: ''Bugün hocam gelecek,

Yazdığı kitapları bu fakire verecek.

Bilmiyor ki; gariban, pis garsonun biriyim,

Fakat onun gözünde tüm gençlerin piriyim.

Aman teyzem. ben senden fazla birşey istemem,

Senin gibi meleğe hiç bir yük yükleyemem.

İstediğim şudur ki; hocamı hoş karşıla,

Gerekeni almışım, bize kahve hazırla.

''Göreyim paketleri'' De, odaya girerken,

Vereceği paketi al kahveyi içerken.

Pakette kitaplar var, hocamın eserleri,

Parayla ölçülemez hiçbirinin değeri.

Onları götürüp koy bin özenle dolaba,

Dolabın kapağını yine özenle kapa.

Anahtarı hiç alma dolabın üzerinden,

Güvensizlik sayarak çok üzülür derinden.

Hocam şakayı sever, şakacıya can verir,

Şakayı beğenirse gülücükler gönderir.

Şakacıktan sen de ki; ''Ne kadar vereceğim? 

Türk parası olarak peşin ödeyeceğim.

Umarım ki sana der: ''Borcunuz beşyüzmilyar''.

Zaten bir-iki kitap hiç eder mi o kadar? 

Yani anla ki; şaka, gülümse, çık odadan,

Yollan Huzurevi ''ne çıkar çıkmaz binadan.

Yalvarırım yardım et, yapıver bana bunu,

İnan ki sen olursun mutlak cennet hatunu.''

Yaptık dediklerini. İstediği nedir ki? 

Birini mutlu etmek atla deve değil ki.

Çocuk iyi bir çocuk, soylu yerin evladı,

Yüreğim ricasına hiç fazla dayanmadı.

Benim yaptığım budur, bir hata mı yapmışım? 

Sanmayın ki; ömrümde yanlış adım atmışım.''

Anlaşıldı ki; kadın, hırsıza değil ortak,

Yalnız hayır işlemiş kalkıp aldatılarak.

Sorup soruşturdular, kadının bilgisi yok,

Yapılan hırsızlıkla kat ''iyyen ilgisi yok.

Adını bilemiyor üçkağıtçı hırsızın,

Bir tür oyuncak olmuş elinde vicdansızın.

Tek bildiği; o gencin bir gariban olduğu,

Geçimin çarklarında ezilip boğulduğu.

İnanmış ki; kimsesiz, zavallı delikanlı,

Ömrü azap içinde hep feryatlı-figanlı.

Beklemiş, görememiş hiç kimseden iyilik,

Kendine^''İmdat'' demiş ömründe ilk seferlik.

Bir aylık kira vermiş evinin sahibine,

Taksitle borca girmiş koltuklarla kilime.

Dikili fidanı yok merhametsiz dünyada,

Serveti iki kitap, onlar da o dolapta.

Alınmamalı gencin iftirayla günahı,

Kalmaz asla kimsede garibanların ahı.

Özetle; hırsız kayıp. Polis dedi: ''Çıkalım,

Merkeze uğrayarak olayı anlatalım.''

Ev sahibi zararsız, hatta karlı durumda,

Dövizciyi sormayın, çok efkarlı durumda.

Ah ediyor Allah ''a, temiz adammış gibi,

Çevreye saldırıyor kuyruğu yanmış gibi.

Bilmez ki; basamağı çıkmak gerek tek ve tek,

Üçer-beşer çıkanlar düşer yelemyelpirdek.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

MÜHENDİS BEY isimli Şiirsel Gülmeceler ''inden > 73-85/100)', '-1- Hay ''lardan kazanmış da Huy ''lara vermemişti, Hasan Tahsin Yıldırım kötü gün görmemişti. Bilmiyordu dünyada bir denge olduğunu, Kefeden ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":314,"source_url":"https://www.antoloji.com/teyze-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tezgahı', 'ask-tezgahi-mehmet-isikoglu-wf2er', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir yazmadım yar okudum seni

Bir aşk tezgahında dokudum seni

Dolaştı mekiğe kızıl saçların

Çözerken dilimde şakıdım seni

Dokundun içime sen desen desen

Ne kadar şahane oldu bir görsen

Seyreder dalarım engin hayale

Gönlümün gözdesi gül motifi sen

Resmin gönül atlasında bir nakış

Tüm hisler ayakta tutuyor alkış

Oluştu bir tablo yoktur benzeri

Çözdü kör düğümü içten bir bakış

Almanya/Köln', 'Şiir yazmadım yar okudum seni Bir aşk tezgahında dokudum seni Dolaştı mekiğe kızıl saçların Çözerken dilimde şakıdım seni Dokundun içime sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-tezgahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlik Bunun Neresinde', 'sairlik-bunun-neresinde-naime-erlacin-j3tzh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'maşuka yazılmaz şiir

aşka yazılır 

şart olmadıkça 

yok sayılır 

ikinci tekil şahıs 

ruhumdur kor misali tenine değen 

yüreğinden öperken şiirin gizinde

''ben'' derken 

''sen'' demektir lisanım

ister alınır 

ister alınmazsın üstüne

ne anlarsan 

dilim odur işte

yazdırmak dost 

ya da maşuk işi

ki fesleğenler fışkırtır 

iğdenin kurumuş gövdesinden

şairlik bunun neresinde! 

(12 Ağustos 2004)', 'maşuka yazılmaz şiir aşka yazılır  şart olmadıkça  yok sayılır  ikinci tekil şahıs  ruhumdur kor misali tenine değen  yüreğinden öperken şii...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sairlik-bunun-neresinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeliyle Doğar Güneş Yüzüme...', 'seher-yeliyle-dogar-gunes-yuzume-muammer-celik-sghw9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilirim o seherin yelini

kıpır kıpır eder isanın içini

semadan açılan pencereden 

süzülen ilahi nur gibidir

güneşin ilk ışınları

ısıtır insanin içini ve dışını...

İşte tam o zaman kabarır 

duygular mahmur gözlerde

savurur bir tekme ile insan

ne yatağı kalır ne yorganı...

o zaman 

Vurur dalgalar yüreğin duvarına 

ve 

bir mahsunluk cöker dudakların kenarına... 

bedene yansır ruhun aşk ile depreşmesi

seher yelinin serinliği ile 

günün ilk ışıklarıyla

harekete geçer içtima içinde organlar

kiminde bir kelebek kıpırtısı

kiminde masumca bir başkaldırı

kiminde boşalır şelale gibi sular

açılıverince barajın kapakları... 

sulamak ister sanki 

seherle başlayan bedenin ateşini

zayıflamıştır artık irade

ala-uykulu mahmur gözlerde

ayyuka kalkar kendiliğinden

insanın kalçaları, tutunur göklerde... 

düşüncelere dalar

düşlemeye başlar 

sevgi, aşk ve duygular...

yumuşacık dokunuşlarında 

hisseder kendini sevgilinin

kapatır gözlerini 

ve sevişir alevleriyle bedeninin... 

nazlıdır insan o zaman

kaçınır yerinden kalkmaktan 

açmak istemez gözlerini 

bu muhteşem mahmurluktan... 

çilingir sofrasıyla gelsin ister sevgiliyi

dudaklarına sımsıcacık bir buse beklerken

yanaklarına bir gülkurusu konunsun isterken…

açılır gözleri aniden

fırlayıp yatağından

giyinir ne bulduysa hemen

”nefret ediyorum yaaa,  kalkıp işe gitmekten! ...” 

BirDeli

12.08.2004', 'bilirim o seherin yelini kıpır kıpır eder isanın içini semadan açılan pencereden  süzülen ilahi nur gibidir güneşin ilk ışınları ısıtır insa...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seher-yeliyle-dogar-gunes-yuzume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-nurettin-ozdemir-gwfvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Bir uykudan bir uykuya geçmek güzel.

Durgun sudan coşkun suya geçmek güzel.

Bir bahçeden bir bahçeye geçer gibi,

Aşka, o büyük duyguya geçmek güzel.

II

Güzel, her çağda güzel, bugün de dün de güzel.

Bir sanatkar gözünün gördüğü günde güzel.

Senin ellerinin sihrine değmişse eğer,

Yalnız hayat değil çocuğum, ölüm de güzel.', 'I Bir uykudan bir uykuya geçmek güzel. Durgun sudan coşkun suya geçmek güzel. Bir bahçeden bir bahçeye geçer gibi, Aşka, o büyük duyguya geç...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guzel-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir umut olmalı', 'bir-umut-olmali-arslan-arslan-erxqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollar kolay ayrılsa da

Yüreklerdeki sevda kül olsa da

Dil yalan söylerken kalp inkar etse de

İçimizde hep bir umut olmalı

Yazılanları silgi ile silerken defterden

Kinle nefretle,sitemle ayrılmak neden

Yaşanan hayat kopyalanırken kalp ile beyine

İçimizde hep bir umut olmalı

Seven asla sevdiğine etmez sitem

Sitemi aslında kendinedir her zaman

Hayata küsmüş kahretmiş olsa da inan

İçimizde hep bir umut olmalı

Geçmişte olsa bir merhaba,bir selam

Seveni mutlu eder inan bu değer

Yaptıklarımız insanı heder eder her an

İçimizde hep bir umut olmalı

Güzel günler bitmiş geride kalmış gözyaşı

Dostça ayrılarak yaşamak isterdim bu anı

Nerede olursan ol yüreğim yaşar seni

İçimizde hep bir umut olmalı

Arslan ARSLAN..........12.08.2004.....10:45', 'Yollar kolay ayrılsa da Yüreklerdeki sevda kül olsa da Dil yalan söylerken kalp inkar etse de İçimizde hep bir umut olmalı Yazılanları silgi...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-umut-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski bir masal', 'eski-bir-masal-betul-turk-ym0qi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutmasini bilmedigim anlatilan masallar

Icindeki yalan baharlarina sarildigim

Solmayan ciceklerini kokladigim

O günlere verdim cocuklugumu

Gündüzlere karisan yildiz perileri

Verdikleri toz pembe sözlerine

Sarkilarinin bitmeyen nesesine

O seslere verdim kulaklarimi

Yazlari kisi getirmez olan masallar

Donmayan nehirlerine baktigim

Yaprak dökmeyen rüzgarindayim

Iste ben bu deftere yaziliyim

(24.03.1998 almanya)', 'Unutmasini bilmedigim anlatilan masallar Icindeki yalan baharlarina sarildigim Solmayan ciceklerini kokladigim O günlere verdim cocuklugumu ...', ARRAY['Türk Edebiyatı','Şiir','Betül Türk']::text[], 8.5, '{"poet":"Betül Türk","poet_slug":"betul-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eski-bir-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkunç Çağrı', 'korkunc-cagri-nurettin-ozdemir-dftz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gerilmiş oksan, dur! 

                                  Çıkma! 

Atılmış kurşunsan, dur! 

                                   Vurma! 

Boşanmış zamansan, dur! 

                                    Akma! 

Çevrilmiş nazarsan, dur! 

                                    Bakma! 

Bakma, geceler boyunca büyüyen yalnızlığıma! 

Tek bir ağaç gibi dal budak salan garipliğime bakma! 

Bir yüreği bin yerinden bölen hasret içindeyim; 

Yüreğim bin yerinden bölünmüş seni bekliyor.

Gerilmiş ok ol! 

                                   Gel! 

Atılmış kurşun ol! 

                                   Gel! 

Çevrilmiş nazar ol! 

                                   Gel! 

Boşanmış zaman ol! 

                                   Gel! 

Gel ey mesafeler ötesinde yaşayan çocuk! 

Gecede kalmış tek bir ışık ol! Gel! 

Ömür seninle güzeldir.', 'Gerilmiş oksan, dur!                                    Çıkma!  Atılmış kurşunsan, dur!                                     Vurma!  Boşanmış...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korkunc-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık Yumağı', 'pismanlik-yumagi-aysel-coban-t1ols', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kuyunun içine atıldım

Karanlık, kuytu, çıldırtan sessizlik

Sessizlik böler benliğimi

Sessizliğin sesi, çağırır geçmişi

Geçmişin sessizliği, körleştirir gözlerimi

Bakarım kurdeşen olmuş hatalara

Neye baksan, gelecek, sonbahar yıkıntısı

Nereye gitsen pişmanlık, hüzün

Neye el atsan acı bir çelişki

Niye diye sorsan cevapsız hatıralar

Uzanırım kimsesiz pişmanlığıma

Bir pişmanlık yumağı atılır

Bir ucu elimde, çektikçe uzayan anlar

Ben ofladıkça bitmeyen yüzler

Ben kahrettikçe çoğalan yalnızlık

Diğer bir uç bırakılır yüzüme

Yakınlaştıkça, düşler dolanır boynuma

Gördükçe kaçışlar başlar, çaresiz

Kaçtıkça özlemler kaybolur, ümitsiz

Bir uç yukarı çekerken 

Diğer uç boğar beni.', 'Bir kuyunun içine atıldım Karanlık, kuytu, çıldırtan sessizlik Sessizlik böler benliğimi Sessizliğin sesi, çağırır geçmişi Geçmişin sessizli...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pismanlik-yumagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kat Kat Acı', 'kat-kat-aci-hande-yilmaz-hft49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '7 kat et kokusu sinmiş insanlara,

derilere, derinlere ve ruhlara.

7 kat silmiş,

7 kat ovmuşum ellerimle,

tırnaklarım kan dolasıya...

tüm 7 kat ve ben

gece karanlık 

gece kör 

gece al (!) 

ve ben metanetsiz

ben temiz

ama git gide ala boyanan (!) 

(Ağustos 2004)', '7 kat et kokusu sinmiş insanlara, derilere, derinlere ve ruhlara. 7 kat silmiş, 7 kat ovmuşum ellerimle, tırnaklarım kan dolasıya... tüm 7 k...', ARRAY['Türk Edebiyatı','Şiir','Hande Yılmaz']::text[], 8.5, '{"poet":"Hande Yılmaz","poet_slug":"hande-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kat-kat-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Gözlerinde', 'siyah-gozlerinde-salih-nurettin-cevik-li3nc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlkin gecesinde kayboldum gözlerinin 

Her gece zifiri karanlıklar gibi çökerdi yüreğime 

Hilal kaşlarının altında zeytin tanelerini andıran kara gözlerin 

Aysız gecelerde hüzün yağmurları gibi düşerdin kuruyan toprağıma 

Ahu gözlerine simsiyah sürmeler çeker,bir de alımlı alımlı bakardın hayata 

Bilsen ne de yakışırdı; yay kaşlarına kader çizgilerini anımsatan kalem çekişlerin 

Her uzandığımda sana saçlarının rüzgarında savururdu beni zaman 

Sensiz geçen gecelerimde limanlar arardım soğuk bedenimi yaslayacak 

Sonra uçurumlara savrulurken tutunurdum yine sana 

Her gecem gündüzüm seninle dopdolu geçerdi 

Ellerime sığmaz olurdu gülüşlerin kaçıracağımı zanneder sımsıkı tutardım avuçlarımı 

Öylesine sıcak bakardın ki gözlerime kavrulurdu yüreğimde göz bebeklerim 

Ne zaman buğulansa gözlerim benim yerime mercan taneleri gibi süzülürdü yanaklarına göz yaşların 

Ne zaman daralsa yüreğim gül bahçende miski amber sunardın içime 

Ne güzel geçerdi seninle zaman; gülmeyi ağlamayı ve sevmeyi seninle seviyordum 

hayatı seviyordum seninle seni bilmem ama ben sana alıştığımdan beridir çok mutluyum 

Çünkü karşılıksız gülmeyi sevmeyi öğretmiştin bana 

Ve kimse senin kadar gülmüyor artık 

Adını gül koymuştum senin 

Daim gülüyor gülleri kıskandırıyordun her mevsim', 'İlkin gecesinde kayboldum gözlerinin  Her gece zifiri karanlıklar gibi çökerdi yüreğime  Hilal kaşlarının altında zeytin tanelerini andıran ...', ARRAY['Türk Edebiyatı','Şiir','Salih Nurettin Çevik']::text[], 8.5, '{"poet":"Salih Nurettin Çevik","poet_slug":"salih-nurettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siyah-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-mustafa-yigit-morpheus-aqce9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başımın Dumanı Hiç Bitmiyor

Senden Uzakta Gurbet Çekilmiyor

Gözlerim Hep Yollara Bakıyor

Güller İçerisinde, Bir Tanesin ANAM

Yanımda  Yoksun, Hayatım Sanki Zindan

Söyle Başka Varmı Seven Candan

Kaç Yıl Oldu, Bakarım Sana Uzaktan

Günlerim Yıl Oldu, Geçmiyor ANAM

Bu Canımı Adadım Senin Yoluna

Dünyayı Feda Ederim Senin Uğruna

Gözlerindeki Tebessüm Yetiyor Oğluna

Canımı Sen Verdin, Sana Adadım ANAM

Özlemin Sardı Tüm Cihanı Alemi

Sen Yoksun Ya Göremiyorum Sabahı

Sana Ulaşmak İçin, Arşınlıyorum Yolları

Tuttu Gurbet Beni, Bırakmıyor ANAM

Özlemin Artık Tak Etti Canıma

Her Çalışta Koşar Oldum Kapıya

Felç Uğruyor Sanki Ayaklarıma

Ayaklarım Kilitlendi, Gitmiyor ANAM

Senden Başka Seven, Menfaat İçin Sever

Gurbette Durağa Düşen, Dertlerle Keder

Senden Ayrı Kalmak Ölümden Beter

İnat Etti Azrail Canımı, Almıyor ANAM

 Mustafa Yiğit (Morpheus)', 'Başımın Dumanı Hiç Bitmiyor Senden Uzakta Gurbet Çekilmiyor Gözlerim Hep Yollara Bakıyor Güller İçerisinde, Bir Tanesin ANAM Yanımda  Yoksun...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anam-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Kız', 'can-kiz-salih-nurettin-cevik-mbvfa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim... 

yalnız seni sevdim 

yüreğinde kor olmayı, 

ateşinde kül olmayı sevdim. 

karanlık gecelerime ay ışığı, 

yıldız olup avuçlarıma düşmeni sevdim. 

mehtabı olmanı sevdim kalbimin 

bir gülü sevdim; birde seni can kız 

Sevdim... 

seni sen olmanı sevdim 

aşkını sevdim tutuşmuş yüreğimde 

gamlı gönlüme yoldaş 

sırdaşı olmanı sevdim yüreğimin, 

canıma can olmanı sevdim. 

yaşamayı sevdim hasretini, 

ağlamayı sevdim. gülmeyi seninle can kız 

Sevdim... 

seni sevdim 

kara gözlerini ellerini sevdim. 

bir gülü sevdim birde seniz 

gül sendin gonca gonca gönlümde 

vurgun gönlüm güle, ben sana sevdalı can kız 

aradım... sen yoktun 

yalnız gözlerin vardı açan güllerde 

yalnızım yapayalnız kimsesiz sokak ortasında 

gecelerim karanlık, odam sessiz, ağlıyor duvarlar 

sen yoksun, ellerin yok sarıp sarmalayan, 

güller açmıyor, kokmuyor yapraklar 

gün sendin her sabah yeniden doğan 

ve akşam sendin dönüşen aya 

bakmıyor gözlerim seninle etrafa 

yoldaşı olmuyor, konuşmuyor kulaklarım sesinle can kız 

gel bul beni; içimi aydınlat, bir şeyler söyle 

gecenin karanlığı kalksın üstümden 

dilim çözülsün kalbim söylesin aşktan yana ne varsa 

ruhuna fısıldasın en güzel kelimeleri 

nerdesin nerelerdesin 

kıskanıyorum seni saran geceyi ve gündüzü 

havayı ve suyu baktığın yerleri, zerreyi 

gel nerelerdesin 

özlemin çoğaltır sürgünlerini yüreğimin 

uzat kuşanayım dirilten bakışlarını 

azat bulsun işgal yüreğim seninle 

nerdesin nerelerdesin 

yüreğim seni çağırır gözlerim seni arar 

ellerim tutmak ister ellerini 

vurgun yemiş yüreğim yokluğunda 

can paramparça can garip can öksüz 

gel nerelerdesin 

bak ağlıyor gözlerim 

sevdam ağlıyor, 

ben ağlıyorum can kız', 'Sevdim...  yalnız seni sevdim  yüreğinde kor olmayı,  ateşinde kül olmayı sevdim.  karanlık gecelerime ay ışığı,  yıldız olup avuçlarıma düş...', ARRAY['Türk Edebiyatı','Şiir','Salih Nurettin Çevik']::text[], 8.5, '{"poet":"Salih Nurettin Çevik","poet_slug":"salih-nurettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/can-kiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhlar İsyankar', 'ruhlar-i-syankar-salih-ozalasan-fajba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıkıldı habersiz birer, birer

Beni aldatan dev aynaları

Yok/oldular bütün sevenler

Kalanlar dev aynasının parçaları

Bir merkebim bile yokken

Mahmuzlamışım beyaz atları

Gönül yaşım yirmi beş derken

Belime çökmüş zamanın kamburları

Aldatmışım serseri yüreğimi

Sihirli aynalarda yaşamışım aşkları

Kaybettim beyaz atlı prensliğimi

Kel göründü taraklarda göremedim saçlarımı

Aldatmış beni “İnsan hissettiği yaşta

Gönül asla ihtiyarlamaz diyenler”

Gönlümün kurbanı oldum aşk bir hata

Ruhlar isyankar ihtiyarlamışsa bedenler

Size bir ibret olsun Salih’in halleri

Ruhum genç seviyorum diyenler

Sevmek yetmiyor; zaman öyle değişmiş ki

Alay konusu ağaran saçlar, ihtiyar bedenler

Ben kaldırdım sizde kaldırın

Bizi aldatan dev aynalarını! ; sevenler

Üzülmesin hüsrana uğramasın

Bizleri beyaz atlı prens diye görenler

y.tarihi 12-08-04

Salih ÖZALAŞAN', 'Yıkıldı habersiz birer, birer Beni aldatan dev aynaları Yok/oldular bütün sevenler Kalanlar dev aynasının parçaları Bir merkebim bile yokken...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ruhlar-isyankar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüklenenler', 'suruklenenler-orhan-tuncay-585fe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir derin nefes çabasındaydı yolcu

Boğazında düğümlenip dolandıkça soluğu

Koşup durduğu yoldan bir geriye baksa

Bir görebilse akan şu “uzun ince yolu”

Derler ki “akan ırmakta bir kez daha yunulmaz”

Bu bir yolculuk sonu gelmeden tam durulmaz

Bilmesek de halimizi giderken gündüz gece

Bir soluk bile almazsak yaşam freni  tutmaz

Bu akıntı  böylece sürükler zavallı bizleri

Bizim rüzgarımız  süpürür arkadaki izleri

Ey yolcu, nefeslen, bir dön de bak arkana

Bak da şimdi fark et yaşanmamış olan günleri', 'Bir derin nefes çabasındaydı yolcu Boğazında düğümlenip dolandıkça soluğu Koşup durduğu yoldan bir geriye baksa Bir görebilse akan şu “uzun ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suruklenenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birkerecik', 'birkerecik-ali-fikri-karadeniz-0stbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birkerecik çıkartın şu mermer yüreğimi! 

Buzdan yatağım erisin...

24 saat yaşanmamışlıklarımı yaşayayım doyasıya

Ve bir balyozla parçalayın kalbimi

Yüreğimi yerine koymayın bir daha.......!', 'Birkerecik çıkartın şu mermer yüreğimi!  Buzdan yatağım erisin... 24 saat yaşanmamışlıklarımı yaşayayım doyasıya Ve bir balyozla parçalayın ...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/birkerecik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ark', 'ark-ali-fevzi-ixstj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbim kanayıpta akmamış bağrımda bir yumru

Adını söyler penceremde her sabah iki kumru

Gökler ağlar benim gözümle sana hep cisil cisil

Hiç değmediğim elinle göz yaşımı sen sil

Biriciğim anlatamadığım kalbimde yiterse

Tek teselli kaynağım hüznüm de biterse

Adını bilmediğim sevdalıların yattığı kara toprak

Beni sen göm hiç duymadığım dualar okuyarak

Bir gün üstümde filizlenirse bir dal

O sana aittir kimselere göstermeden al', 'Kalbim kanayıpta akmamış bağrımda bir yumru Adını söyler penceremde her sabah iki kumru Gökler ağlar benim gözümle sana hep cisil cisil Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Ali Fevzi']::text[], 8.5, '{"poet":"Ali Fevzi","poet_slug":"ali-fevzi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ark-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Varlığı', 'gonul-varligi-nurettin-ozdemir-0bgv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Emeğim, alın terim, yorgunluğumsun.

O eski yollardan dönmesini umduğumsun.

Bunca sevgi, bunca özlem sana az; 

Sen benim gönül varlığım, çocuğumsun.', 'Emeğim, alın terim, yorgunluğumsun. O eski yollardan dönmesini umduğumsun. Bunca sevgi, bunca özlem sana az;  Sen benim gönül varlığım, çocu...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonul-varligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderdim', 'gonderdim-mustafa-yigit-morpheus-xkwps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mektubuma Hasretimi Ekledim

Kederlere, Gem Vurdum Gönderdim

Hiç Kimseyi Senin Kadar Sevmedim

Yüreğime, Taş Bağladım Gönderdim

Mektubum Ulaşmadı Sıladan

Böyle Takdir Etti Yüce Yaradan

Gözlerim Âmâ Oldu Ağlamaktan

Gözyaşıma, Özlem Koydum Gönderdim

Mektubumun Kenarları Dört Köşe

Zaman Geçmez Oldu, Senden Ayrı Düşünce

Eski Cüzdanımda, Yırtık Resmini Görünce

Saçlarıma, Kar Yağdırdım Gönderdim

Mektubumun Kenarları Karalı

Şu Divane Gönlümün Sen Oldun Maralı

O İnce Belini Yabancı Eller Saralı

Dertlerime, Bin Dert Kattım Gönderdim

Mektubumun Mısaraları Sıralı

Durak Gülmez Oldu Senden Ayrı Kalalı

Sen Uzaktan Hatırımı Soralı

Şu Kalbime, Sevda Koydum Gönderdim

 Mustafa Yiğit (Morpheus)', 'Mektubuma Hasretimi Ekledim Kederlere, Gem Vurdum Gönderdim Hiç Kimseyi Senin Kadar Sevmedim Yüreğime, Taş Bağladım Gönderdim Mektubum Ulaşm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonderdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-i-lyas-ozmen-fyt9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dertli-dertli yanık-yanık

Türküler ağlatır beni

Gah uyurken gah uyanık

Türküler ağlatır beni

Titriyorsa ozan dili

İnliyorsa sazın teli

Aşk pınarı duygu seli

Türküler ağlatır beni

Ankara''lı Amasya''lı

Ege kokan Manisa''lı

Akdeniz''den Torosdağlı

Türküler ağlatır beni

Yazanını bilmediğim

Adlarını duymadığım

Ustalardan dinlediğim 

Türküler ağlatır beni

Neşet Ertaş dertli biraz

Mahsuni''de yalan olmaz

Yalınızken avaz-avaz 

Türküler ağlatır beni

Aşık Veysel garip doğmuş

Yazdığını kalpten görmüş

Yaylalardan kopup gelmiş

Türküler ağlatır beni

Aslı şiir namı koşma

Var git bülbül derdim deşme

İki gözüm iki çeşme

Türküler ağlatır beni

Özmenem der gülmeyiniz

Sizde türkü dinleyiniz

Beni deli bilmeyiniz

Türküler ağlatır beni', 'Dertli-dertli yanık-yanık Türküler ağlatır beni Gah uyurken gah uyanık Türküler ağlatır beni Titriyorsa ozan dili İnliyorsa sazın teli Aşk p...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turkuler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona Mektuplarimdan IV', 'ona-mektuplarimdan-iv-oktay-hacimusali-kywgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'IV 

ben meqopolisim 

gokdelenleri goz cikaran meqopolis 

ellerimi uzatip sarmisim Hazari 

bir elim gunahi - kebirin ten ortasinda 

yollarimdan arabalar geciyor 

ses - kuyden camlari cat - cat olmus arabalar 

uc - dort mescidim var 

bu yakinlarda bir kilise tikecekler koynumda 

icim ciz ediyor her defa kiz kulesinde hariciler resim 

cektirende 

namusuma dokunurlar sanki 

sahra tufanlari kumlari carpdikca karincanin suratina 

sirtinda tasidigi bir balaca ceyirtke qanadi 

mundar olur 

aya baxib ulayan bozqurtlar qefesinden 

melul melul bakiyor deniz kiyisindaki diskoteklere 

meni niye bu koke salmisiniz niye 

niye meni bu koke bu koke salmisiz niye 

derim corak topraklar kimi cadar - cadardi 

kim olsaydi yerime bu mektubu uzadardi 

amma uzatmiram men 

cunki gokdelenleri goz cikaran 

olu at cesedlerine bakip ta 

sokakta ruzgarlari toz koparan 

meqopolisim ben 

bir eliyle hazari sarmis 

bir eliyle de gunahi kebiri mseven 

deccal meqopolis', 'IV  ben meqopolisim  gokdelenleri goz cikaran meqopolis  ellerimi uzatip sarmisim Hazari  bir elim gunahi - kebirin ten ortasinda  yollarimd...', ARRAY['Türk Edebiyatı','Şiir','Oktay Hacimusali']::text[], 8.5, '{"poet":"Oktay Hacimusali","poet_slug":"oktay-hacimusali","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ona-mektuplarimdan-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Arama sorma bulamazsın...', 'arama-sorma-bulamazsin-erdal-asik-ur1df', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arama sorma bulamazsın 

Sokak lambalarının gölgesinde

Oturduğum kayanın dibinde

Meyhanelerin buğulu köşelerinde

Kaybolduğum şişelerin içinde

Arama sorma bulamazsın

İçtiğim sigaranın yalazında

Rüzgarında savrulan dumanında

Çaldığım kapıyı açtığında

Arama sorma bulamazsın

Ağladığımda gözyaşımda

Kalbimin hızlı atışında

Görmüyorsan baktığında

Arama sorma bulamazsın

Ben beni kaybettim

Ben beni bulamıyorum bende

Belki yüreğinin bir köşesinde

Belki de ben sende!', 'Arama sorma bulamazsın  Sokak lambalarının gölgesinde Oturduğum kayanın dibinde Meyhanelerin buğulu köşelerinde Kaybolduğum şişelerin içinde...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/arama-sorma-bulamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Absuma', 'absuma-mustafa-kaya-ffj62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A

Söz,sözden açılmışken,biraz susman gerek

çünkü söz geçiremediğim

bir sözcük getirdi beni, senin sığındığın bu yalnızlığa

ey aklımla kalbim arasında gezinen! 

unutma

serabından önce düştüm bu yola

ve(''ve'' susmaktır belki de)  

herkesin sustuğu yer...

yüzünde bir uçurum uğulduyor bütün dillerin bileşkesiyle

bil! 

aynı şeyleri söylemek susmaya başlamaktır biraz da

dönüyorum 

aklımın ayak izlerini toplayarak kendime

yalnızlığımdan başka müridim yok

ve nehirler 

denize karışınca dinlenir.

B

yıldızların kulağıma fısıldadığıydı yüzünün benden esirgediği

yüzün ki 

müfessirlerin gölgesinde uzlaştığı bir ayetti çölde



söyle dedim / beni

sevmen için ne yapayım kuşlara

dedi uzağa git...

dedim kalbini aç öylese

dedi geçmişi gördüm gelecekte

dedim ya beni

dedi sen zaten hep geçmişteydin

S

Abaküsüm çöl. Dinlenmeliyim biraz gölgemin gölgesinde

unutmayı hatırlamalı aklım biraz

biraz, çoktur belki de bana 

alın dağıtın çölü unutmayı unutanlara

ah! yaklaşıyorsun bana  kendine doğru koştukça

U

Uzağa benzeyen bir yakınsın.Bir kaç adımlıksın

yokluğunun sana kattığı anlam kadar yer kapladığın için yeryüzünde.

evrenin her yerindesin.

asi bir çocuğun ömrüdür yaşamaya kalksan kendini

bu suskunluğunla anladığını anlıyorum

sırf konuşasın diye flört ettiğim bu şiire 

bütün dillerin bileşkesiyle bakıyorsun

yine de lal diyorsun yemin ettiğim bütün değerlere

bak! 

bu yüzüne işaretlenmiş olan

Hit-ayetini üzerinde taşıyanların yazılmamış şiiridir

M-A

marifeti öldükten sonra yaşamakmış yaşayanın içinde.

aşka benzemediği için ölüm

aşk benzedi ölüme

için

için...', 'A Söz,sözden açılmışken,biraz susman gerek çünkü söz geçiremediğim bir sözcük getirdi beni, senin sığındığın bu yalnızlığa ey aklımla kalbim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaya']::text[], 8.5, '{"poet":"Mustafa Kaya","poet_slug":"mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/absuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam çöker', 'aksam-coker-bulent-guler-2-pbzgh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'meyhanelerinde 

ud çalar, defler vurur 

bir kadın şarkı söyler 

sokaklar sarhoş olur

bir tren içimden geçer 

bir deniz aklımdan

gitmek isterim 

akşam çöker 

gün kaybolur

gün olur

ıhlamur kokuları iner şehre

beşiktaşta kadınlar

zamanı işler  gergefine

bulvarda işçiler yürür

sokakta barikatlar kurulur

gitmek isterim 

akşam çöker 

yol kaybolur

bulvarlar boşalır 

şarkılar susar

gergefler çözülür 

zaman uykuda 

defler çekilince

ud çalmaz olur 

gelmek isterim sana 

akşam çöker 

haz kaybolur...', 'meyhanelerinde  ud çalar, defler vurur  bir kadın şarkı söyler  sokaklar sarhoş olur bir tren içimden geçer  bir deniz aklımdan gitmek ister...', ARRAY['Türk Edebiyatı','Şiir','Bülent Güler 2']::text[], 8.5, '{"poet":"Bülent Güler 2","poet_slug":"bulent-guler-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aksam-coker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cânân da sende', 'c-n-n-da-sende-sair-ahrazi-e8wyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Âsi bir feryâda bırakma cânı,

Câhilin aşkıyla sevme ne olur.

Cânânım demeden dinle ricânı,

Aldığın nefeste Cânân bulunur…

***', 'Âsi bir feryâda bırakma cânı, Câhilin aşkıyla sevme ne olur. Cânânım demeden dinle ricânı, Aldığın nefeste Cânân bulunur… ***...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canan-da-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ormanları hiç sorma', 'ormanlari-hic-sorma-mutlu-ayar-dt5on', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“yapraklar gülüşüm”

oysa betonadır her bakış

griler koşar göz değmemiş her yere 

asırlar geçse iyileşmez göbekteki apseler 

yaranın bilinci kendini yeniler! 

“yaprakları düşürme”

damarlarımdaki korku bir fahişe

iniltiler büyür, arzu kamçılandıkça 

süre gelen zaman 

bir kansız intihar! 

“ağaçlar sevincim”

yalnız koruculara mahsustur onlara doymak 

oysa aşklar erozyona uğrar

yaş denizine karışır kucaklarca aşk 

kaybolur yıllarca 

“ağaçları kesme”

kaldırımlar halinden memnun gözükür 

aralarında biten çiçekler onların sahte yüzüdür

şimdilerde onların sıcaklığı, okullara ve

antikacıların üstüne bürünür

Yapraklar gülüşümdür, 

ağaçlar sevincim…. Ormanlar…

Ormanları hiç sorma 

hiçbir zaman ulaşamadığım(dır) 

sevdiğim!', '“yapraklar gülüşüm” oysa betonadır her bakış griler koşar göz değmemiş her yere  asırlar geçse iyileşmez göbekteki apseler  yaranın bilinci ...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ormanlari-hic-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta', 'uc-nokta-ali-fuat-aydin-hd3yf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...

koydum işte üç noktayı,

bitiriyorum mektubu artık,

ama sen,

hiç bitmeyeceksin içimde...', '... koydum işte üç noktayı, bitiriyorum mektubu artık, ama sen, hiç bitmeyeceksin içimde......', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Aydın']::text[], 8.5, '{"poet":"Ali Fuat Aydın","poet_slug":"ali-fuat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uc-nokta-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyin Nesi', 'neyin-nesi-ali-fuat-aydin-8y1ku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hep yanımda sanmıştım

Bu ayrılık neyin nesi

Bütün sözlerine kanmıştım

Bu ayrılık neyin nesi

Sensizlik yaman bir kelime

Bakıp da benim şu halime

Dua ettim ecelime

Bu ayrılık neyin nesi', 'Seni hep yanımda sanmıştım Bu ayrılık neyin nesi Bütün sözlerine kanmıştım Bu ayrılık neyin nesi Sensizlik yaman bir kelime Bakıp da benim ş...', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Aydın']::text[], 8.5, '{"poet":"Ali Fuat Aydın","poet_slug":"ali-fuat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neyin-nesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat,o akıl sahibi kimden yana?', 'anlat-o-akil-sahibi-kimden-yana-sair-ahrazi-j9wjf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni kendimde bilen,kendini benden mi sanır,

Sanılandan sorulan,bende bilenden usanır.

(feilâtün/feilâtün/ feilâtün/feilün)

***

Not:Yukarıdaki beyitte farklı bir anlam vardır,anlaşılamayacağını düşünüyor olmama rağmen anlayanların da olacağını tahmin ediyorum.

saygılarımla', 'Beni kendimde bilen,kendini benden mi sanır, Sanılandan sorulan,bende bilenden usanır. (feilâtün/feilâtün/ feilâtün/feilün) *** Not:Yukarıda...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlat-o-akil-sahibi-kimden-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüyü Aldım Elinden', 'buyuyu-aldim-elinden-cumhur-boratav-bp046', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'büyüyü aldım elinden, 

artık yaşlanmıyorum

üstelik şarkılarını da hissetmiyorum

bak iğde kokusunu kendisine verdi

oysa ben, ya da bana benzeyen bir şey

sırf iğde kokusu için

belki dere yatağımda akıyordur hala

akıyordur, sen eminsen ben de eminim

üstelik senin söylediklerin 

çamurlaşıyordur, 

çamurum kıvamlıdır

o yüzden

büyüyü alıp elinden

kaç kere seslendim sana

düz, uyaksız

hiç bir biçime bürünmeden

-hah yalan söyledim, 

 gülerim buna

 uyaklı yürürken bile uyaksızdım-

geçen gün, 

gün son ışığını gözlerime sunarak

batarken, şiirleştim

sana ne söylersem söyleyeyim

sen ne söylersen söyle

bu oluyor

gün ışığı değdiğinde oluyor, elimde değil

gözlerim yeşilleniyor

onun gibi bir şey

ve unutma, uyaksızım', 'büyüyü aldım elinden,  artık yaşlanmıyorum üstelik şarkılarını da hissetmiyorum bak iğde kokusunu kendisine verdi oysa ben, ya da bana benze...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/buyuyu-aldim-elinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayacağım Kadın...', 'unutamayacagim-kadin-i-brahim-ethem-bingul-cvz5i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaller yelken açmış

En kara bilinmezlere

Belli ki kaçış bu

Sebebi

Maddesel sensizliğe..

Sevindir beni,

Son bir tebessümünle, sözünle

Değsin,

Gözündeki ışık,

Sözündeki öz

Gidişime..

Belki tükenişim bu an

Ya da yeni bir hayat

Mutluluğun, mutsuzluğum olsa bile

Mutluluklar sana..

Ey beyaz bahtlı,

Canı canım,

Unutamayacağım kadınım....', 'Hayaller yelken açmış En kara bilinmezlere Belli ki kaçış bu Sebebi Maddesel sensizliğe.. Sevindir beni, Son bir tebessümünle, sözünle Değsi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutamayacagim-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alfabe', 'alfabe-bekir-mutlu-gokcesu-arv9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A:aşkım

