INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim Ağlama', 'memleketim-aglama-yasar-pullu-pgak3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağların uğultusuna emanet kaderi

Kurtların yanlızlığına

Arayıp soranı bile yok

Kendi çocuklarından başka

Dost bildiği rüzgarı almış önce koynuna

Sonra orta yerinden çatlatmış güneş

Damar damar akmış acı

Yazması mavı oya

Elleri kına

Memleketim ağlama

Berlin den gelmidimi yavruların sana

Elini öpmedi mi İsrafıl yıldızkan

Böyle ikide bir başıma kalkma

Bıraktım diye seni bir başına

Sende aç koydun 

Güldürmedin yüzümü

Söyletme beni

Azmı yandım kent meydanlarında 

Hasret karlı dağlarına

Ekmek arası köfte

Hamburger olduğunda

Ağlamadım mı soframda

Sevdalandığım kadın 

Bana flörtüm diyor

Bir gecelik aşklara yenildi yavrun

Oysa bileğimi hiç bükülmez sanıyordun

Toprağım ağla ağladığınca

Bir dosttan mektup aldım bu sabah

Kanka ma diye yazmış başına

Oda değiştirmeye çalıştıklarından olmuş sonunda

Bu imansız sabahlar 

Böyle mi dokunur adama.

Toprağım ağla

Sonra o süslü cümleler kuran adamlar

Derin düşündüğüne inanan 

sığ yaşayanlar

aşka çözüm bulanlar rakı masalarında

yani yoz ürünü ülkemin

bozuk düzeni

biliyorum bunlar dinamıt gibi hayatında

toprağım korkma

çek pimini

ağlama

gözyaşını düşürdüğün dağlarda bul kendini

taşan ırmaklara Sal

çam ağaçlarına ver sesini

ama küsme

belki bizde buluruz kendimizi

bundanmıdır uçurum ettin gevdeni

bu yüzden mi en sevdiğin ay zemheri

ve çok sevdiğin içinmi bu ayda doğurdun beni', 'Dağların uğultusuna emanet kaderi Kurtların yanlızlığına Arayıp soranı bile yok Kendi çocuklarından başka Dost bildiği rüzgarı almış önce ko...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/memleketim-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Densiz', 'densiz-ahmet-aksoy-p57zn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mavi gözlerinde gecenin

saatleri alınmış duvarlar

sıradan ikindilerdim

masada buğday sarısı yapraklar

gecenin zülfü üzerime düşkün

hüznüme alınmış kan damlar

esin usturamda kalemdim

damarlarım ağlar

deli gençliğini yitirdi gün

bir kez daha öldü canlar

kaç çocuk eskittim

yapraklarda mürekkep yanar', 'mavi gözlerinde gecenin saatleri alınmış duvarlar sıradan ikindilerdim masada buğday sarısı yapraklar gecenin zülfü üzerime düşkün hüznüme a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/densiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-metin-yalti-fu44g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Issız bir tepede

Adını haykırmak istiyorum

Hava inadına sıcak

Boğazım kuru inadına

Üstüne üstlük

Rüzgarda ters esmekte...

Sana nasıl ulaşılır

Bilmem ki

Herşey inadına bana karşı.

10/07/92 Sarıyer', 'Issız bir tepede Adını haykırmak istiyorum Hava inadına sıcak Boğazım kuru inadına Üstüne üstlük Rüzgarda ters esmekte... Sana nasıl ulaşılı...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozlem-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuda', 'uykuda-metin-yalti-jkizo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykuda olduğunu bilsem

Düşlerine gireceğim

Ama bu şiiri bitirmem gerek

Rahat uyu

Uykunu bölmeyeceğim

10/07/92 yeşilyurt', 'Uykuda olduğunu bilsem Düşlerine gireceğim Ama bu şiiri bitirmem gerek Rahat uyu Uykunu bölmeyeceğim 10/07/92 yeşilyurt...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uykuda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
