INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıların Nağmesi', 'anilarin-nagmesi-cafer-tayyar-ozkan-gfzfr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yedi mevsim hasret çektim sıcak tenine,

Dilimde nakarat oldu muradın şarkıları,

Sensiz özlem dolar yalnız geçen geceme,

Düşlerimi gerçek sanıp dolarım sözlerime.

Dur daha çok yanacak gönülde aşk ateşi,

Belki de hiç kalmayacak sevdanın neşesi,

Gürül gürül akmıyor artık dilek çeşmesi,

Mahşere meze olacak anıların nağmesi.

15 Haziran 2004 İstanbul', 'Yedi mevsim hasret çektim sıcak tenine, Dilimde nakarat oldu muradın şarkıları, Sensiz özlem dolar yalnız geçen geceme, Düşlerimi gerçek san...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anilarin-nagmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmış Bir Kristaldi Gözyaşın', 'kirilmis-bir-kristaldi-gozyasin-burcak-kulahli-lg7a0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçinden binlerce yansıması geçen gökkuşağının,

Ya da sevgi dolu bir avuçta biriken denizdi,

Saklamak isterken kendini deli bir sevdadan; 

İçinde tek senin yaşadığın,

Deniz kızı.

Kırılmış bir kristaldi gözyaşın.

Paramparça olmuş,

Ama her parçasında, 

Tasavvuf saflığında senin olduğun.

Ne olursa olsun kırılmamalı gözyaşları,

Akmalı derinlere.

İçinde bir deniz yaratmalı. 

Kimi zaman durgun, 

Kimi zaman deli boranlı.

Kırılmamalı gözyaşları.

Sıcacık akmalı dışına.

Görenlerde ağlamalı, 

Senin derinindeki denizlere.

Ve herkes ağlamalı sonunda,

İçinde herkesin bir denizi olmalı kendi gözyaşından.

Sonra birleşmeli bu denizler,

İçimiz birleşmeli,

Sevgimiz,

Ve gözyaşlarımız.

Ama kırılmamalı gözyaşları

S

e

n

                                  

K                                n.

  ı                            ı

    r                        s

      ı                    ı

        l               l

          m        a

              a  m', 'İçinden binlerce yansıması geçen gökkuşağının, Ya da sevgi dolu bir avuçta biriken denizdi, Saklamak isterken kendini deli bir sevdadan;  İç...', ARRAY['Türk Edebiyatı','Şiir','Burçak Külahlı']::text[], 8.5, '{"poet":"Burçak Külahlı","poet_slug":"burcak-kulahli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kirilmis-bir-kristaldi-gozyasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah', 'siyah-burcak-kulahli-qko6g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '22.07.2004

                                                                 Trabzon-İstanbul

                                                    Her şeyi süpürebilirsin,

                                                    Sonbaharı süpüremezsin

                                                                              Ö.Asaf

-Dostuma- 

SİYAH

Turuncu bir ayrılıktı,

Uzun,korkunç,açık bir ayrılıktı.

Bir koku bıraktı,bilmediğin-içimde-,

Aşktı ve her zaman gidilen bir yalnızlıktı. 

Gülerken ben –cam-den bir aykırılığın soytarılığıyla,

Özlemekti yazılan suya ve özlemdi an(ı) lardan çalınan.

Zamanlardı,zikirdi-ismini-ve içte açan zakkum çiçekleri.

Lavlardı; Pompei’den içe akan –esrik-,

Esmer avuçlarda kanayan bir yaraydı.

.

.

.

.

Rengi belli bir ayrılıktı

.

.

.

.

.

.

SİYAH.....', '22.07.2004                                                                  Trabzon-İstanbul                                                ...', ARRAY['Türk Edebiyatı','Şiir','Burçak Külahlı']::text[], 8.5, '{"poet":"Burçak Külahlı","poet_slug":"burcak-kulahli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/siyah-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirli Şiir', 'siirli-siir-burcak-kulahli-k8cdk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçinizde olmayan şiiri hiçbir yerde bulamazsınız.

                                                                            -Shelley-

Ben şiirli yaşamak istiyorum.

Şiirle uyanmak her sabah,

Ve yüzümü şiirle yıkamak.

-Sabah kahvaltımda siyah şiir,beyaz şiir,tavşan kanı şiir olsun.-

Cebimde şiirler sokağa çıkıp vapura binmek sonra,

Martılara şiir atmak ellerimle.

Sonra şiirli bir iskelede inip,

Şiir solumak.

Üstünde şiir bulutları olan bir şehirde -yüreğim gibi-,

Şiir yağsın üstüme sağnak sağnak,

Gözler-im-den akan şiirlere inat.

Akşam masamda bir şişe şiir oldumu yeter bana.

Sonrası şiirli bir sarhoşluk.

Sonrası şiirli bir uyku.

Sonrası şiirli...

Şiirli...

Şiirli...

.

.

.

.

Ben şiirli yaşamak istiyorum...........', 'İçinizde olmayan şiiri hiçbir yerde bulamazsınız.                                                                             -Shelley- Ben ...', ARRAY['Türk Edebiyatı','Şiir','Burçak Külahlı']::text[], 8.5, '{"poet":"Burçak Külahlı","poet_slug":"burcak-kulahli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siirli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Geldim Sen Gideli Çok Olmuş', 'ben-geldim-sen-gideli-cok-olmus-burcak-kulahli-9ga9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldim,sen gideli çok olmuş,

O hep seni hatırlatan kokun kalmış sadece.

Hani gitmeyecektin.

Hani birlikte hatırlayacaktık geleceği,

Ve 

Söz vermiştin bana bekleyecektin,

Söz vermiştim sana dönecektim.

Hiç kimseler beklemezken bekleyecektin*

Beni.

Ben sözümü tuttum. 

Geldim.

Ama 

Sen gideli çok olmuş.

*K.Simanov', 'Geldim,sen gideli çok olmuş, O hep seni hatırlatan kokun kalmış sadece. Hani gitmeyecektin. Hani birlikte hatırlayacaktık geleceği, Ve  Söz ...', ARRAY['Türk Edebiyatı','Şiir','Burçak Külahlı']::text[], 8.5, '{"poet":"Burçak Külahlı","poet_slug":"burcak-kulahli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-geldim-sen-gideli-cok-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Gidiyorum', 'gunese-gidiyorum-oguzkan-bolukbasi-a7qxu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güneşe gidiyorum

tatile

bile bile

güle güle

yatacağım suya

kuma

güneşe

elimde buz gibi bir şişe maden suyu ve limon

kitabım

hem de en adisinden ve boş

düşünmeyeceğim

düşünmeyeceğim

ohhhh be diyeceğim

soğanın cücüğünü yiyeceğim

güneşe gidiyorum

onbeş gün yanacağım

marsık gibi olacağım

yüklerimi boşaltıp döneceğim

beni bekleyin', 'güneşe gidiyorum tatile bile bile güle güle yatacağım suya kuma güneşe elimde buz gibi bir şişe maden suyu ve limon kitabım hem de en adisin...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gunese-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şavaş ve Çocuk', 'savas-ve-cocuk-ali-gencay-hok2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudak ısırmalarında korku gizleyen çocuk

Urbaların yırtılmış,dudakların mor uçuk

Sığındığın damlar,köhne in cin sokaklar

Kelebek misali hayatın bir kanat uçuşluk

Büyüklerin büyüdüler ellerinde tüfekler

Ruh satarlar tanrıya,bedenler çukurlarda

Bırak  silahını tahtadan olsa da mavzer

Değilsin suçlu,bahçen tam ortası mahşer

Korku sırası onlarda  büyüyor küçük çocuk

Hava ölüm kokar delirtir insanı bu koku

Siz ölümü camdan izleyenler nerde dostluk

Savaş mantıksız oyun,durun ölmesin çocuk', 'Dudak ısırmalarında korku gizleyen çocuk Urbaların yırtılmış,dudakların mor uçuk Sığındığın damlar,köhne in cin sokaklar Kelebek misali haya...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/savas-ve-cocuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Talih', 'kor-talih-muammer-celik-e4sqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zamansız zamanlara at sürdü 

başsız bir gölge 

atının gözleri kördü 

geldi önüme düştü...

BirDeli

13.05.2004

**Fahrettin Köseoğlu Dostumun “Zamansız Zamanlar” isimli şiirine teşekkurlerimle', 'zamansız zamanlara at sürdü  başsız bir gölge  atının gözleri kördü  geldi önüme düştü... BirDeli 13.05.2004 **Fahrettin Köseoğlu Dostumun “...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kor-talih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazereti Ayrılık', 'mazereti-ayrilik-hakki-hakan-kaya-924t6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'iki ayrı dünyadan

buluşturdu bizi

firari sevda

gözlerine bakınca 

yüreğim ısındı

ne çabukta

örmeye başlamıştı

ağlarını

raslantısal yazgı

karanlığını anladım 

içindeki derin çukurun

bir kibrit alevi kadar

zayıfken

karanlığına koştum

karanlık söndürmedi

kibrit alevini

zayıfta olsa bir ışıktı

hep daha güçlü

yanmasını bekledi

korkusu

karanlığın mahkumiyeti

yaşanılanların cazibesi

belirsizliğin adıydı

ne ben yumuşadım

ne o katıydı

ayrılmak için 

birleşen iki yürek

doruğunda yaşadı

karanlığa aydınlığı

_______mazereti

_________ayrılıktı', 'iki ayrı dünyadan buluşturdu bizi firari sevda gözlerine bakınca  yüreğim ısındı ne çabukta örmeye başlamıştı ağlarını raslantısal yazgı kar...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mazereti-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaza', 'kaza-mustafa-yigit-morpheus-038kd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine Gözyaşı Hakim

Yurdumun İnsanında

Bilmem Kaç Can Yatıyor

Rayların Kucağında

Dikkatsizlik Mi, Gaflet Mi? 

Bizi Bu Kadar Üzen

Hiç Karşımıza Çıkmayacak Mı? 

Bu Kazaları Çözen

Kaç Canın Daha

Soğuk Raylara Sarılması Gerek

Analar Kaç Yıl Daha

Ağlayacaklar Feryat Ederek

Haberleri Dinlemiyorum

İçimde Bir Şeyler Kopuyor

Güzel Yurdumun Dört Bir Yanında

Her Gün Kaç Kaza Oluyor

Güzel İnsanlarımız 

Neşe İle Coşmalı

Aşarak Her Türlü Yolu

Sevenlerine Kavuşmalı

Belkide Bu Şiiri

Geç Kaleme Alıyorum

Ne Yapayım Dostlarım

Günlerdir Ağlıyorum

Elimden Bir Şey Gelmiyor

O Canları Gördükce

Dünyaya Kahrediyorum

Küçük Canlar Ağladıkca

Yaralarımız Çok Taze 

Melhem Olmuyor Bir Şey

Eğer Çare Yoksa Sende

Garip Durağım, Duygularımı Bana Geri Ver

 Mustafa Yiğit (Morpheus)', 'Yine Gözyaşı Hakim Yurdumun İnsanında Bilmem Kaç Can Yatıyor Rayların Kucağında Dikkatsizlik Mi, Gaflet Mi?  Bizi Bu Kadar Üzen Hiç Karşımız...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kaza-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın', 'anlayacaksin-murat-demir-6covd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çekil git başımdan çekil git artık

Sen, yaralı beni ne yapacaksın

İş işten geçince neyi abarttık

Derken bensizliğe alışacaksın

Birini kaybeden birini bulur

Bulamazsan zora dayanacaksın

Köle mi, sultan mı, belli mi olur

Kim bilir kimlere yar olacaksın

Sanma ki sevmeyi beceremedim

Günü geldiğinde anlayacaksın

Elimde ne varsa hep sana verdim

Git artık git daha ne alacaksın', 'Çekil git başımdan çekil git artık Sen, yaralı beni ne yapacaksın İş işten geçince neyi abarttık Derken bensizliğe alışacaksın Birini kaybed...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlayacaksin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık....', 'ayrilik-i-smail-enes-unal-fd13m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alıştım sana ben; ana kucağı gibi,

Alıştım sana ben; baba ocağı gibi,

Alıştım sana ben; yuva sıcağı gibi,

Alıştım birtanem, alıştım sana...

Ayrılık; ölümden bin beter,

Ayrılık, ömürden ömür biter,

Ayrılık; canımdan can gider,

Ayrılık; sonsuz hasrettir sana...

Alıştım sana ben; bir soluk nefes gibi,

Alıştım sana ben; cıvıl cıvıl ses gibi,

Alıştım sana ben; altından kafes gibi,

Alıştım birtanem, alıştım sana...

Ayrılık; ölümden bin beter,

Ayrılık, ömürden ömür biter,

Ayrılık; canımdan can gider,

Ayrılık; sonsuz hasrettir sana...', 'Alıştım sana ben; ana kucağı gibi, Alıştım sana ben; baba ocağı gibi, Alıştım sana ben; yuva sıcağı gibi, Alıştım birtanem, alıştım sana... ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Enes Ünal']::text[], 8.5, '{"poet":"İsmail Enes Ünal","poet_slug":"i-smail-enes-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KaNKaM DeĞiL SuÇ OrTaĞIM', 'kankam-degil-suc-ortagim-mine-ozdemirtas-i1z68', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben’i yakaladım suç üstü

aşkın dibine çömelmişti sinsice

kargacık burgacık bir el yazısıydı

alnındakiler /kömür karası

duymadı gelişimi /dalgındı

kazdığı çukura gömüyordu zamanı

ellerinde ise kan vardı.

kemiklerini saydım sırtında

ve kırbaç izlerini

upuzun bilirdim ya

bir de koskocaman gövdeli

(yanılmışım.) 

küçülmüştü görmeyeli

iki yana sallandı

önce düşecek sandım

ama sonra

kaldırdı kolunu zorla

''pençe gibiydi tırnakları''

tutundu yalnızlığa

onu /orada / öylece/kendi haline

bırakıp kaçmaktı istediğim

tam orta yerimden

İkiye ayırıyordum ki kendi mi

''benden çabuk davranıp''

yamalı cebine yerleştirdi gölgemi.

şimdi ise / suç ortağıyız sadece.''

kanka değiliz artık

'' o sayfayı kapattık. ''', 'Ben’i yakaladım suç üstü aşkın dibine çömelmişti sinsice kargacık burgacık bir el yazısıydı alnındakiler /kömür karası duymadı gelişimi /dal...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kankam-degil-suc-ortagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Güzellikte', 'i-nce-guzellikte-ali-fuat-aydin-x634m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ince giyme üşürsün

güzellikte meşhursun

sen benimsin ben senin

daha ne düşünürsün', 'ince giyme üşürsün güzellikte meşhursun sen benimsin ben senin daha ne düşünürsün...', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Aydın']::text[], 8.5, '{"poet":"Ali Fuat Aydın","poet_slug":"ali-fuat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ince-guzellikte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
