INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Düşlerimdesin*', 'duslerimdesin-i-brahim-dikmen-2-6vgax', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen,kalbimde

hazan sarısı

kasımpatları

açtıran kadın.

sana aşık

sana sevdalı

dudaklarımda

sıcaklığın,tadın.

******************

şimdi nerde

kiminlesin? 

hangi vefasız

ellerdesin? 

adın dua

hep dilimdesin

sen,benim

düşlerimdesin.

******************

açtı yine

kasımpatları

yine sensiz

geçti hazan.

her sonbahar

bekliyorum

hadi sende

oyun bozan.

***************

şimdi nerde

kiminlesin? 

hangi vefasız

ellerdesin? 

adın dua

hep dilimdesin

sen,benim

düşlerimdesin.', 'Sen,kalbimde hazan sarısı kasımpatları açtıran kadın. sana aşık sana sevdalı dudaklarımda sıcaklığın,tadın. ****************** şimdi nerde k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/duslerimdesin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavmin', 'kavmin-ozgur-doran-q5exc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gri bir hüzünde 

                           gözlerin 

