INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Çöpleri', 'kibrit-copleri-ersin-alptekin-9w6qh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Poyraz bir rüzgar gibi ilk alevleri

Hayatta insan misali,çıplak olur ölümleri

Bazen bir ormana,bir şehre kafa tutarlar

Derdini anlatmaz,içine kapanıktır kibrit çöpleri

Kutularını açar azrail olmuş insan eli

Birbirine kenetlenmiş kırk adet yürekli

Farklı sebepte farklı yerlerde intaharlar

Derdini anlatmaz,içine kapanıktır kibrit çöpleri

Medeniyet ilerlesede hep aynıdır isimleri

Fani dünyada alınlarında yazılıdır kaderleri

Küçük mekanlarında hep aynı havayı paylaşırlar

Derdini anlatmaz,içine kapanıktır kibrit çöpleri

Zifiri karanlık gecelerin aydınlığı bekleyişi

Sen yanarken bende umutsuzluk külleri

Üflersen göremezsin bendeki seni

Derdini anlatmaz,içine kapanıktır sönerken

                                                                    kibrit çöpleri

Ersin Alptekin

17.08.04', 'Poyraz bir rüzgar gibi ilk alevleri Hayatta insan misali,çıplak olur ölümleri Bazen bir ormana,bir şehre kafa tutarlar Derdini anlatmaz,için...', ARRAY['Türk Edebiyatı','Şiir','Ersin Alptekin']::text[], 8.5, '{"poet":"Ersin Alptekin","poet_slug":"ersin-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kibrit-copleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari Sevdam', 'firari-sevdam-zulfikar-yapar-kaleli-vd3x1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Baykuşa eş oldum karanlıklarda,

Arkamda uçurum, önümde duvar! 

Yıllar yılı kovdu kuraklıklarda,

“ Su” diye inlerdi namus ile ar! 

Köy deyip geçmeyin anımız orda

Anamız, babamız, canımız orda

Bir yitik sevdalı yanımız orda

Orda mutluluğun gözyaşları var.

Orada başladı en ilk sevdamız.

Orada konuldu göbek adımız

Orada yeşerdi milli davamız

Şimdi gönül kırgın, şimdi yürek dar.

Çok şey hayal kurdum, azı yaşadım

Mutluluğu bazı bazı yaşadım

Orda her sevdayı, nazı yaşadım

Dudağımda sitem, dilimde ikrar

Orada uyuyan uykusuzluğum

Orada başladı ilk susuzluğum

Orda çile deste, dert boğum boğum

Bir kahır yumağı, hep beni boğar.

Orda yalınayak teptiğim toprak

Güneşleri çalan kördüğüm toprak

Çatlak dudaklarla öptüğüm toprak

Ben ona giderim, o bana uyar.

Sevdalar yitirdi sevdalığını

Orada unuttu balık ağını

İstali tepesi, garuş dağını

Düşündükçe yüreğime kar yağar.

Orda suçlu sevdaları akladım,

Hoyrat esen yelden bile sakladım.

Baharı yokladım, güzü kokladım,

Anam orda tek keçiden süt sağar.

Gerçekler orada düşlerde nadan

Bu gönül vatandan, bu baş beladan

Hovarda hayaller dönmez sıladan

Şu firari güneş ne zaman doğar?', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Baykuşa eş oldum karanlıklarda, Arkamda uçurum, önümde duvar!  Yıllar yılı kovdu kuraklık...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/firari-sevdam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Şiiri', 'hayat-siiri-nurettin-ozdemir-cpbkm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hikmet''e:

               ''Dünyada kimseye minnet etmeden sana

               verebileceklerimin başında bu mısralar gelir.''

                                                       

Bir kaya dibinden şakırdayarak,

Akan su gibiydin gürül gürül sen.

Nerde dalga dalga rüzgarda esen

O kumral saçların? O sıcak busen,

Çalmaz oldu benden beni yakarak.

O günler ne güzel, ne sıcaktılar.

O günler hayata bağlardı beni.

Sulara aksedip kalan çehreni,

Arıyor gözlerim, nerdesin şimdi? 

Nerdesin hasreti çekilen bahar? 

Taştan taşa ahenk taşırdı sular.

Güller yanağında katmer katmerdi.

Kalbim senin için en güzel yerdi.

Aşkın yeli ılgın ılgın eserdi.

Güzelliğin neden sonuna erdi? 

Neden gözlerinde dolgun bulutlar? 

Es rüzgar! .. Erisin başımın karı.

Aksın taştan taşa ahenk sularda.

Arzum çiçek açsın bu son baharda.

Ey aşk! .. Alev alev ruhumu sar da

Bozulmuş görmesin gönül baharı.', 'Hikmet''e:                ''Dünyada kimseye minnet etmeden sana                verebileceklerimin başında bu mısralar gelir.''                 ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Gelişi', 'sevginin-gelisi-nurettin-ozdemir-973l4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonunda sevgi çıkıp geldi; ağır, olgun.

Kurulup oturdu baş köşeye, kendinden emin.

Uzanıp tuttu ellerimi, yumuşak elleriyle.

Kaldırıp seyretti beni,

                               bakışlarının tılsımlı aynasında.

-ki içlerinde güneşler doğuyordu-

Sonra bir sır gibi usulca öptü dudaklarımı.

Bir anda ışıdım, ısındım, özlem kesildim; 

Eridim, kayboldum avuçlarında.', 'Sonunda sevgi çıkıp geldi; ağır, olgun. Kurulup oturdu baş köşeye, kendinden emin. Uzanıp tuttu ellerimi, yumuşak elleriyle. Kaldırıp seyret...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevginin-gelisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Susması', 'sevginin-susmasi-nurettin-ozdemir-yxkbz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi sustu! 

Sustu bütün güzellikler.. her şey! 

Dal, yaprak, ışık, su...

Sustu, denizlerin ve ormanların uğultusu! 

İçimizdeki gür kemanların sesi sustu! 

Sustu,

Yüreklerde büyüyen yalnızlık korkusu! 

Ve çılgın davetlerin ürpertisi sustu! 

Şimdi, mahzun bakışlarımızda kaldı

Sevişmenin uzak parıltısı.', 'Sevgi sustu!  Sustu bütün güzellikler.. her şey!  Dal, yaprak, ışık, su... Sustu, denizlerin ve ormanların uğultusu!  İçimizdeki gür kemanla...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevginin-susmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha', 'daha-burak-kumdakci-6zcmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum buradan,

En’e gidiyorum.

En uzak, en derin, en karanlık, en yüksek.

Benimki hangisi daha bilmiyorum.

Seçemiyorum.

Daha yüksek bir yere gitmek istiyorum.

Daha canlı, daha kırmızı, daha pahalı.

Acının kol gezdiği ormanlara gidip,

Büyük bir hatayı zehirliyorum.

Bakın bana bakın, tek başıma ne kadar da kalabalığım.

Sığ bir hayatla, derin sulara akıyorum.

Bakıyorum inan bakıyorum,

Ama hiçbirşey göremiyorum.

Sonunu bildiğim bir filmi,

Defalarca izliyorum.

Kalp atışlarım hızlandı yine.

Görüyorum geliyorlar.

Ellerinde şarap, gözlerinde kara kuyular.

Uzun uzun gülüyorlar önce,

Hemen öldürmüyorlar.

Işığa götürün beni ışığa.

Bana bilmediğim bir şey anlatın.

Tatmadığım bir şey verin.

Zamanı verin bana zamanı,

Güneşi buradan göremiyorum.

Gidiyorum buradan,

Hiçbiryere gidiyorum.

Sonbaharın gittiği yere gidiyorum.

Daha güçlü, daha hızlı, daha sert bir yere gidiyorum.

Gidiyorum buradan,

Güneş’in gittiği yere gidiyorum.', 'Gidiyorum buradan, En’e gidiyorum. En uzak, en derin, en karanlık, en yüksek. Benimki hangisi daha bilmiyorum. Seçemiyorum. Daha yüksek bir ...', ARRAY['Türk Edebiyatı','Şiir','Burak Kumdakçı']::text[], 8.5, '{"poet":"Burak Kumdakçı","poet_slug":"burak-kumdakci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/daha-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-nurettin-ozdemir-04yke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şarkı ki cihanda bulunmaz söyleyeni.

Döndürmeye güç yetmiyor artık gideni.

''Sır vermek adetimiz değildir'' bilirsin.

Biz bir gülü sevdik çocuğum, bir de seni.', 'Bir şarkı ki cihanda bulunmaz söyleyeni. Döndürmeye güç yetmiyor artık gideni. ''Sır vermek adetimiz değildir'' bilirsin. Biz bir gülü sevdik ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sir-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
