INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâllerim', 'hay-llerim-osman-i-nci-2zsor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Meta fiziğe kafa tutacak,

Yerçemine karşı koyacak,

Beni, kuşlar gibi uçuracak,

Bir, özgürlük istiyorum...

Varılacak bir hedefi olan,

Hedefe varmak için çalışan,

Emirlerime harfiyyen uyan,

Bir, beyin istiyorum...

Dertlerle mücadele edecek,

Her zorluğa göğüs gerecek,

Ve, mutlu bir finâlle bitecek,

Bir, hayat istiyorum...

Adaleti ve insanlığı bilen,

İnsanları, mutlulukla gülen,

Evrende parmakla gösterilen,

Bir, dünya istiyorum...', 'Meta fiziğe kafa tutacak, Yerçemine karşı koyacak, Beni, kuşlar gibi uçuracak, Bir, özgürlük istiyorum... Varılacak bir hedefi olan, Hedefe ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayallerim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baca K''arası Armonisi', 'baca-k-arasi-armonisi-yusuf-sevgen-apbg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabırsızlığın dönerkoltuğunda rus ruleti yanlışlarım…

                                  çakmaktaşlarım…

her seferinde çakar…

Köşebaşların tarihi yalnızlık kadar eskidir de

üstelik köşebentlerle tıkalıdır geceler veya gelecekler

adımızı bile kazıyamadık rengi siyahlaşmış tahta masalara

belki sadece içimizden geçirdik bunları

kuşlar senden ne ister anlamazsın

duymazlaşır gözler

kulaklar körelir

dudaklar şehla

eller an’ı yazamaz iskelesinde yaşamın

an’dıkların çocukluğundaki isimlerle kalır

caddeler isim ister senden

veremezsin yeni isimler

(parmaksız güvercinler hesap sormak ister

soramaz

bunu yapanların kendi yüzüne vuran utancıyla

tanığı bile olamadın çünkü parmaklarının)    

öğrendiklerim var, ama yetinmemeliyim demeli insan

öğrenmediklerini de sığdırabilir nihayetinde kafasına

ama yanlışları değil

gülüşleri de ama kahırları değil

zenginlikleri de ama arabaları değil

bunu bilmeli tüm varlıklar; 

çakmaktaşlar da anlama varacak

nikotine ve plastiğe değil

ocak-kasım.doksanyedi.üsküdar-elmadağ', 'Sabırsızlığın dönerkoltuğunda rus ruleti yanlışlarım…                                   çakmaktaşlarım… her seferinde çakar… Köşebaşların ta...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baca-k-arasi-armonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu Lavanta', 'yolun-sonu-lavanta-yusuf-sevgen-nal66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen tersizken de

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; işçisin

terliyken de

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; güzelsin

bugün ölçtüm-biçtim

bu yolların sonu lavanta

sen çıktı bütün hepsi

temmuz.doksanaltı.istanbul', 'sen tersizken de &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; işçisin terliyken de &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; güzelsin bugün ölçtüm-biçtim bu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yolun-sonu-lavanta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Bana', 'sorma-bana-tulay-eker-cniwz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorma bana

Şarkılarımda vuslattır adın

Yedi cihan böler bağrım

Elif,lâm,mim gibi yanar aşkım

Sorma bana

Tur dağına yönelir

Simurg kuşu olur gönül pencerem

Taze gül yaprağıdır gölgem

Sorma bana

Avlunda mırra içen güvercinim

Bir ah desen bir desen

Çırpınır kanatları yüreğimin.

Sorma bana

Duha''da bedestendir işçiliğim

Lime lime işlenir sensizliğim

Üstüne ebruli kırlangıçlar çizerim

Sorma bana

Uzanıp yatar kollarım saramaz viraneyim

Yeşerecek umudum kalmadı divaneyim

Yutkunduğum yerdesin tıkanır nefeslerim.

Sorma bana

Sorma! 

Memleketim gibi hasretim

Seni sensiz yaşamaksa diyetim.

Üstüme yağmurlar yağsa da

Kuraktır yürek izlerim.', 'Sorma bana Şarkılarımda vuslattır adın Yedi cihan böler bağrım Elif,lâm,mim gibi yanar aşkım Sorma bana Tur dağına yönelir Simurg kuşu olur ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sorma-bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Kokumu', 'seviyorum-kokumu-yusuf-sevgen-n2962', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seviyorum kokumu

en çok göğsümün kokusunu; ter kokusunu

                    &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; hanımeli kokusunu

Hani atılır bazen önüne

gerilir durur, alır kokuların tümünü

mücadelededir, koklarsın direnç kokusunu

bahçededir, siner üzerine hanımeli

sonra bulur bir güzel sevgili başı; 

          &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; saçı, göğsü, dudakları

kocaman şeyleri inşa eder; 

          &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; teridir göğsünde…

En çok göğsümü severim

kokusunu…

üstelik hanımeli.

Akşam sefası orta yeri

          &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; gecekokan, kuşkonmaz…

kokmaz demeyin, o da kokar

üstelik hanımeli.

temmuz.doksanbeş.istanbul', 'Seviyorum kokumu en çok göğsümün kokusunu; ter kokusunu                     &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seviyorum-kokumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılmayan Ne Kadar Yaşar', 'anilmayan-ne-kadar-yasar-yusuf-sevgen-1xc5c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anılmayan ne kadar yaşar diyorum kendime

ve size

soysuzluğun tarihinden başlarmış göçüntüler

atılan imzalar emsalsizdir veya sıyrıktır sadece

bedene atılan çentikler yaralar bedeni

sigara yanıkları ya da

ya da görmezden gelinen özürler; 

tarihi.

haziran.doksanbeş.elmadağ.ist', 'anılmayan ne kadar yaşar diyorum kendime ve size soysuzluğun tarihinden başlarmış göçüntüler atılan imzalar emsalsizdir veya sıyrıktır sadec...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anilmayan-ne-kadar-yasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Görme Bana', 'cok-gorme-bana-osman-i-nci-nbszd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ceylanlar misali, kaçarsın benden,

Ne istersin, bu yaralı gönlümden,

Aşık olmuş, ümit bekliyor senden,

Bir ümidi, çok görme bana...

Bakışların ok gibi, kalbimi deler,

Neler çekti gönlüm, aşktan neler,

Sevdi gözlerim, karşılığını ister,

Sevilmeyi, çok görme bana...

Yıllar yılı, gülmemiş hep ağlamışım,

Belalardan, kurtulmamış hiç başım,

Bir kere olsun, mutlu olamamışım,

Mutluluğu, çok görme bana...

Bu yokluğun, ölümle eş değerde,

Ecel dolaşıyor, benim peşimde,

Gel güzelim, sen de beni sevde,

Yaşamayı, çok görme bana...', 'Ceylanlar misali, kaçarsın benden, Ne istersin, bu yaralı gönlümden, Aşık olmuş, ümit bekliyor senden, Bir ümidi, çok görme bana... Bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-gorme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Ya!', 'sen-yoksun-ya-koyulhisarli-serdar-76dn0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yoksun ya bu diyarda bir hüzün var

Dağları ağlamaklı sisli ve yalnız, 

Bulutları ağlamamak için kendini zor tutuyor

Çiçekleri hüzünle boynunu bükmüş

Güneş ısıtmamak için sebeb arıyor

Olsun gittiğin yerin güneşi burayı ısıtıyor ya! 

Şimdi horozlar sabahı farklı bir neşeyle uyandırmışlardır

Güller, kır çiçekleri en güzel renklerini giymişlerdir 

ecemiz geldi diye

Dereler şimdi şımarık akıyordur sen varsın diye! 

Baharın yeni doğan kuzuları kıpır kıpırdır

sen ordasın diye

Gittiğin yere mutluluklar ama buralarıda unutma! 

Güller açmak için seni bekliyor....', 'Sen yoksun ya bu diyarda bir hüzün var Dağları ağlamaklı sisli ve yalnız,  Bulutları ağlamamak için kendini zor tutuyor Çiçekleri hüzünle bo...', ARRAY['Türk Edebiyatı','Şiir','Koyulhisarlı Serdar']::text[], 8.5, '{"poet":"Koyulhisarlı Serdar","poet_slug":"koyulhisarli-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-ya-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefertaslarımızdan Eksik Etmemeli Cinnetleri', 'sefertaslarimizdan-eksik-etmemeli-cinnetleri-yusuf-sevgen-7mlz4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sefertaslarımızdan eksik etmemeli cinnetleri

geçerken direkli-direksiz asfaltlarımızdan

sığdıramadığımız yumruklarımıza karakalem islerimizi

vıcık vıcık akıtırız gözbebeklerinden

günün en son model arabalarının…

Cebimize doldurduğumuz eski, ahşap, toprak

göçürtülen bir bir evlerimizin taşları, topraklarıyla

çizeriz duvarlarını ucu gökte devillerin

kaydırırız istersek camlarından…

Evlerimizin penceresinden selam veren

bir türlü dişlenmeyen mumlu gecelerimizi

hatırlayanlardan isteriz bir de; 

sırf radyolu gecelerinin efsanelerini

tutar da denizde bile kaydırırız…

verirler be… vermezler mi…

(hep atmak değil)    saklamak da lazım gelir

alaaddinin sihrinden uzak

yüzyılda bir rastlanan gülüşlerimizi.

Bir kolumuza ayrılığı, bir kolumuza başlangıcı alırız

dolaşırız…

bizim değil mi? 

üstelik bir umudumuz bitiş olur

bir umudumuz yaşamak.

Yaşamak derim de

derim ama…

mayıs.doksanbeş.istanbul', 'Sefertaslarımızdan eksik etmemeli cinnetleri geçerken direkli-direksiz asfaltlarımızdan sığdıramadığımız yumruklarımıza karakalem islerimizi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sefertaslarimizdan-eksik-etmemeli-cinnetleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmem Bin Güzele', 'degismem-bin-guzele-osman-i-nci-4vtlu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni gördüğüm anda, tutuluverdim birden,

O kadar güzelsin ki, alırsın beni benden,

Yıldızlardan mı geldin, yoksa göklerden,

Ayrılamam inan, vazgeçmem asla senden... 

Küle çevirsen, yaksan, yıksan gönlümü,

Ağlatsan yıllarca, güldürmesen yüzümü,

Yine severim seni, tutarım ben sözümü,

Ateşe de atsan beni, kör de etsen gözümü...

Aşkınla dolaşır, damarlarımdaki kan,

Yokluğun bana, ölümden beter inan,

Adeta duruyor, geçmez oluyor bir an,

Karşımda seni, göremediğim zaman...

Aşığım sana, tapıyorum tüm kalbimle,

Yaşamak güzelse eğer, bil ki seninle,

Olamıyorum sensiz, bir tek gün bile,

Seviyorum inan, değişmem bin güzele...', 'Seni gördüğüm anda, tutuluverdim birden, O kadar güzelsin ki, alırsın beni benden, Yıldızlardan mı geldin, yoksa göklerden, Ayrılamam inan, ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degismem-bin-guzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Dokunabilirsiniz', 'bana-dokunabilirsiniz-yusuf-sevgen-e97uh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tinerci çocuklar’a

tepe döndü dağa

ama ben seni seviyorum, dedi

dönmedi bile dağ

hem ben daha büyüğüm, dedi

sardı bulut koca dağı

bak sardım seni,

dokunabilirsin bana.

tınmadı hem de dağ

ben çok sertim bir kere

olamazsın demir gibi.

dönerek hafif bu sefer tepe

peki ama niye böyle

tek değilsin sen koca dağ olurken

bak altına,

bizim de altımızda…

benden alıp götüren polenleri

rüzgar seni de yalıyor.

ağustos.doksandört.beşiktaş', 'tinerci çocuklar’a tepe döndü dağa ama ben seni seviyorum, dedi dönmedi bile dağ hem ben daha büyüğüm, dedi sardı bulut koca dağı bak sardım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bana-dokunabilirsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü Hediyem', 'dogum-gunu-hediyem-osman-i-nci-udu0t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki tel ağarmış saçım,

Birkaç damla gözyaşım,

Uğruna harcanan hayatım,

Sana, doğum günü hediyem...

Uykusuz geçen gecelerim,

Gerçekleşmeyen hayâllerim,

Karşılıksız kalan bu sevgim,

Sana, doğum günü hediyem...

Bana çektirdiğin çileler,

Yıktığın pembe hayâller,

Kırdığım şişeler, kadehler,

Sana, doğum günü hediyem...

Beni, bıraktığın için üzgün,

Ecelin gelsin, doğduğun gün,

Hatıralardan, bir demet hüzün,

Sana, doğum günü hediyem...', 'İki tel ağarmış saçım, Birkaç damla gözyaşım, Uğruna harcanan hayatım, Sana, doğum günü hediyem... Uykusuz geçen gecelerim, Gerçekleşmeyen h...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogum-gunu-hediyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Korkuyorum', 'sevmeye-korkuyorum-osman-i-nci-ide1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk bahçesinin, eşsiz gülü gibisin,

Görünce ruhuma, inan huzur verirsin,

Bu dünyada herşeye, güler geçersin,

Bana da gülersin diye, sevmeye korkuyorum...

Sevgi dolu hislerimi, anlatamam sana,

Değişmem dünyaları, o tatlı bakışına,

Tahammül edemem, akan gözyaşlarına,

Ağlatırım seni diye, sevmeye korkuyorum...

Böyle bir resminle, avunur garip gönlüm,

Bir kez bakınca yüzüne, dağılır hüznüm,

Koklamaya bile kıyamazken, nadide gülüm,

Kırarım seni diye, sevmeye korkuyorum...

Bana hayat verir, saçının bir tek teli,

Zamanımı yitirdim, bu sevdana düşeli,

Ben, ne divaneyim güzelim, ne de deli,

Alamam seni diye, sevmeye korkuyorum...', 'Aşk bahçesinin, eşsiz gülü gibisin, Görünce ruhuma, inan huzur verirsin, Bu dünyada herşeye, güler geçersin, Bana da gülersin diye, sevmeye ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmeye-korkuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisizlik', 'sevgisizlik-goksel-akkaya-f1f8u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVGİSİZLİK 

Gözlerim dalıyor uzaklara 

Bir mavi deniz gibi 

Arıyorum her yerde seni 

Ulaşılmaz bir yıldız gibi

Ağlıyorum kaderime 

Suçsuz bir çocuk gibi

Utanıyorum artık yalnızlıktan

Sensizlik bir hiç gibi

Göl hiç yağmur görme mişki 

Güneşin kıymetini bilsin 

Sevilen hiç sevmemişki 

Sevenin kıymetini bilsin', 'SEVGİSİZLİK  Gözlerim dalıyor uzaklara  Bir mavi deniz gibi  Arıyorum her yerde seni  Ulaşılmaz bir yıldız gibi Ağlıyorum kaderime  Suçsuz b...', ARRAY['Türk Edebiyatı','Şiir','Göksel Akkaya']::text[], 8.5, '{"poet":"Göksel Akkaya","poet_slug":"goksel-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgisizlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yüzlüm', 'seher-yuzlum-osman-i-nci-xc1vj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kara sevda ki bu, kelimelere sığmıyor,

Gözlerim senin için, inan hergün ağlıyor,

Ne yazık ki ellerim, hep böyle boş kalıyor,

Beklenen sensin seher yüzlüm, bekleyen ben...

Bir umutsun içimde, pınar gibi çağlarsın,

Elimde bir resmin, öyle de tatlı bakarsın,

Kahrolası dünyada, beni hayata bağlarsın,

Nefes sensin seher yüzlüm, soluyan ben...

Karanlık sokaklarda, bir başıma çaresiz,

Gezer dururum böyle, birtanem ben sensiz,

Yıllardır diyar, diyar sessiz, bitkin, ümitsiz,

Aranan sensin seher yüzlüm, arayan ben...

Böyle sensiz yaşamak, yetti artık canıma,

Bu nasıl yazgı imiş, lânet olsun bahtıma,

Al artık canımı diye, yalvarırım Tanrıma,

Azrail sensin seher yüzlüm, can veren ben...', 'Bir kara sevda ki bu, kelimelere sığmıyor, Gözlerim senin için, inan hergün ağlıyor, Ne yazık ki ellerim, hep böyle boş kalıyor, Beklenen se...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seher-yuzlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Anılarda Kalır', 'aklim-anilarda-kalir-zeki-ergin-b7llw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alır başımı giderim 

gecenin sessizliğinde

sevgiliden yana

o sıra

yıldızlar daha anlamlı

şarkılar daha sevecen olur 

esrik ürperişler içinde 

gözlerim gözlerine çakılı kalır

aklım anılarda kalır

_ezine 19ağus04

_dağlara ver sırtını yt:haz09', 'alır başımı giderim  gecenin sessizliğinde sevgiliden yana o sıra yıldızlar daha anlamlı şarkılar daha sevecen olur  esrik ürperişler içinde...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aklim-anilarda-kalir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Şiir', 'unutulan-siir-kamber-bal-tl96l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün gelecek sen de şiir

Benim gibi unutulacaksın

zevk alamaz olacak senden de insanoğlu

İtilip kakılacaksın

Birgün gelecek sen de şiir

Var olduğundan kuşkulanacaksın

Sanatların taa gerisinden bakarak

Gıptalı bir tavırla üzüleceksin

Bir gün gelecek sen de şiir

İnsanoğlundan uzak kalacak

Rengarenk  şu şen alemde

Nasıl var olduğuna şaşacaksın

Bir gün gelecek sen de şiir

Ellerden-gözlerden yoksun

Diğer sanatlar gibi suskun

Dünyanın haline güleceksin

Bir gün gelecek sen de şiir

Unutulmuş,bir yerde dururken

Can derdine düşen insanları görüp

Belki gülecek belki de üzüleceksin

                                          1980', 'Birgün gelecek sen de şiir Benim gibi unutulacaksın zevk alamaz olacak senden de insanoğlu İtilip kakılacaksın Birgün gelecek sen de şiir Va...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unutulan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazanan Numaralar...', 'kazanan-numaralar-i-brahim-ethem-bingul-q7nil', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir biletimiz var hepimizin,

Hayat piyangosundan

Hayat pahasına aldığımız..

Biletimizin her numarası birer hayat safhamız,

Bu biletin son numarası ise

Mezar taşımıza yazılan tarih..

O müthiş gün çekiliş yapılacak

Kazanan numaralar

Sahiplerini böylece bulacak..

Bakalım,

Büyük ikramiye kimin,

Ve diğer ödüller kimlerin

O gün belli olucak..

İşte bilet, işte can

Haydi hazırlanalım

Çekilişe az kaldı

Başlamalı heyecan...', 'Bir biletimiz var hepimizin, Hayat piyangosundan Hayat pahasına aldığımız.. Biletimizin her numarası birer hayat safhamız, Bu biletin son nu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kazanan-numaralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden`se', 'neden-se-faruk-unal-4fzcc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani dalarsin`ya bazen derinlere

Hani duymazsin`ya ne deselerde

Hani aldirmassin`yahic bir engele

Bende`de Öyle birhal var nedense

Sana agsik olmusum

Gözlerine vurulmusum

Saclarinin tellerine takilmisim

Seni sevmisim ölümüne ben

Hani zaman gecmez`ya o olmayinca

Hani istahtan kesilirsin`ya onu görmeyince

Hani bos düsünceler kurarsin`ya kendince

Bende´de öyle bir hal var nedense', 'Hani dalarsin`ya bazen derinlere Hani duymazsin`ya ne deselerde Hani aldirmassin`yahic bir engele Bende`de Öyle birhal var nedense Sana agsi...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-se-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Küstüm', 'kendime-kustum-faruk-unal-9u3n6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendime Küstüm

Barismakta istemiyorum

Kendimi bir cuval gibi

Bir köseye atmak istiyorum

Ahlar oflar cekmek istiyorum

Hasretin ta derinden

Saclarim agardi dibinden

Yaslandim biliyormusun birden', 'Kendime Küstüm Barismakta istemiyorum Kendimi bir cuval gibi Bir köseye atmak istiyorum Ahlar oflar cekmek istiyorum Hasretin ta derinden Sa...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kendime-kustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satamadim', 'satamadim-faruk-unal-occi6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde kaldi 

Satamadim hasreti

Nöbetcim oldu

Artik o benim

Hic gözümü kapamaz oldu

Uykularimi yarida koydu

Kendi hic gam yemez oldu

Beni hasretinle bogdu', 'Elimde kaldi  Satamadim hasreti Nöbetcim oldu Artik o benim Hic gözümü kapamaz oldu Uykularimi yarida koydu Kendi hic gam yemez oldu Beni ha...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/satamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El-ma', 'el-ma-ahmet-aksoy-g1hhu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '......................''Güneş kınına çekilmedi henüz''

hastaların buluştuğu duvarsız ev

dolaşırken al yuvarlar gibi ruh

içimizde saksız dünya

bir kent gibi büyürken geçmiş

iş içten ücra

............ hüsran kıyımımızda

eksik yıkıntılarda kırık dişler

elmada! şeytanın en sevdiği

bizimse kötü şans dediğimiz

uçsuz kain-atta sarnıç tenha

18.08.2004', '......................''Güneş kınına çekilmedi henüz'' hastaların buluştuğu duvarsız ev dolaşırken al yuvarlar gibi ruh içimizde saksız dünya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/el-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostdan Dosta', 'dostdan-dosta-kamber-bal-d3s0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Amenna deme her söylenen söze

Bir gün adın hiçe çıkar. Ey dost! 

Sakın koyverme kendini belirsiz ize

Varır yolun bir çıkmaza. Ey dost! 

İyi olanla yuvarlan alem-i handa

Başın dik, yüzün ak olsun cihanda

Koruyamazsan kendini her sualda

Dostların da biter bir bir.Ey dost! 

Yanlış olmasın her adımın akıbeti

Aşamazsın sonra binbir mihneti

Gerçek olana sarıl bırak ala köhneti

Kapanır yüzüne heran kapılar. Ey dost! 

Sınır tanımasın hiç hür olan zihnin

Sabrı terkeyleme,gülsün hep yüzün

Taviz verme düşmanına, bitmesin sözün

Olur ki nice sözler fethedilir.Ey dost! 

                                      

                                  1985', 'Amenna deme her söylenen söze Bir gün adın hiçe çıkar. Ey dost!  Sakın koyverme kendini belirsiz ize Varır yolun bir çıkmaza. Ey dost!  İyi ...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostdan-dosta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kolaya Gelmez', 'hayat-kolaya-gelmez-zeki-ergin-tvebq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hayat ince bir sanattır arkadaş

özene bezene yaşamak gerek

taşımalı bir de insan

kocaman bir yürek

şiir şiir 

türkü türkü yaşamalı

oya gibi işlemeli

sabırla özenle örmeli dostlukları

ve de korumalı

_ezine 19ağus04

_dağlara ver sırtını yt:haz09', 'hayat ince bir sanattır arkadaş özene bezene yaşamak gerek taşımalı bir de insan kocaman bir yürek şiir şiir  türkü türkü yaşamalı oya gibi ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayat-kolaya-gelmez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardılı çok', 'ardili-cok-zafer-zengin-etnika-dg886', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'akşam üzeri 

mide boşken gülmeyen çocuk 

kapı çalıyor 

rengi süzülmüş elleriyle 

saçlara zamk olmuş ter 

düşüne her damla 

kadın eli anne tadı gibi 

tutunuyor damağa 

biri sahip çıkmalı çocuğa 

| yarılmış damak..esmer ısırıyor herşeyi..tuzu ter yemeğin..genzi yakan su..acı ve öyküsüz | 

şimdi habersizdir 

metalin şah duruşunda 

ölümün gelişi 

ince ayarında ardılı çok 

tek tek takılıyor kanca 

sırayla 

kaçanla 

kurtulanla 

ve sarı saçlıyla 

habersiz ağlıyor 

kaçıyor 

kapı pul gibi yapışıyor dudağa 

şimdi işte 

kilitler sökülmeli 

diller çekilmeli 

bahçe düzenlenmeli 

devrim çıkıyor 

otuz yıla sığan gülüşle 

ve değirmen sancılı sesini 

rüzgara yakalatıyor 

gün sus 

resim saklan 

| eski resimler.. siyah beyaz | 

böyle kalsın 

kılıç çeliğe küsmüşken 

barış imzalansın 

ve sen hayın 

su içerken 

gülü kesmeseydin 

devrim nasıl gelir görecektin 

pisliğin gölgesisin 

mevsimler gözlerini affetsin 

| tanrı susar orda..önce ben | 

doğma ki 

peygamberler gelmesin 

g i d i n 

ö l ü n 

adını yazın 

gerekmezlerin nesi varsa 

çaputlara sarıp defnedin 

duanız sulara kalsın 

sel bassın içini 

çamurdan kokmayın 

| kör kütük şeytanın çocukları | 

sizide vuracağız 

geri alacağız 

çaldığınız ışığımızı 

ışık silahtır bize 

sürülür kör göze 

yeri gelince 

12 Ağustos 2004', 'akşam üzeri  mide boşken gülmeyen çocuk  kapı çalıyor  rengi süzülmüş elleriyle  saçlara zamk olmuş ter  düşüne her damla  kadın eli anne ta...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/ardili-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldür Beni Yak Beni', 'oldur-beni-yak-beni-kamber-bal-3zsga', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne şekerim kaldı ne de Bal''ım erimedik

Ne kalbim kaldı ne de dilim çürümedik

Her bir tenim pare pare,ruhum kaldı irimedik

Öldür beni yak beni,bir cihanda bak beni

Yeter artık çektiklerim, al gerdana tak beni

Allı yeşilli dünyam sonsuz bir zından oldu

Dost diye aldandığım dost beni derer oldu

Meğer çok sevmenin günahı bumuydu? 

Öldür beni yak beni, bir cihanda bak beni

Yeter artık emeklerim, al gerdana tak beni

Yalvarırım gece-gündüz adaletine hak diye

Ayrılmam yolundan, bir tek yolu pak diye

Eğildim işte önüne, öldür beni yak diye

Öldür beni yak bei,bir cihanda bak beni

Yeter artık tekmelendiklerim, al gerdana tak beni

Sever oldum sevdikçe,sevmek bu kadar ise

Tükendim bittim, girdikçe ak sinesine

Bir kerre olsun kulak ver inleyen şu sözüme

Öldür beni yak beni,bir cihanda bak beni

Yeter artık güldüklerim, al gerdana tak beni

                                                        1986', 'Ne şekerim kaldı ne de Bal''ım erimedik Ne kalbim kaldı ne de dilim çürümedik Her bir tenim pare pare,ruhum kaldı irimedik Öldür beni yak ben...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oldur-beni-yak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-aygul-ece-4ti2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece yarısı, 

Güzelliği bir başkadır.

Ayla söyleşmenin,

Gülle öpüşmenin,

Sıcak bir yudum çayın 

Dudakları okşaması ve….

Gül ormanına dönmesi yaraların…', 'Gece yarısı,  Güzelliği bir başkadır. Ayla söyleşmenin, Gülle öpüşmenin, Sıcak bir yudum çayın  Dudakları okşaması ve…. Gül ormanına dönmesi...', ARRAY['Türk Edebiyatı','Şiir','Aygül Ece']::text[], 8.5, '{"poet":"Aygül Ece","poet_slug":"aygul-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silindim', 'silindim-gencay-coskun-ae2xh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana öykülenirdim geceleri 

Bambaşka diyarlarda

Isırgan otu yalnızlıklarda 

Yakıcı tırmalayıcı tenlerde

Bir sokak lambası aklımı alırdı 

Senden tarafa doğru 

Doğru neredeydi bulmam lazımdı 

Bulduğum umudun silik ayak izleriydi 

Takip edecekken 

Yeminlen elektrikler kesilirdi 

Kime söylesem inanmazdı 

Anıların sayısal izleri 

Hep başa belaydı 

Nereden tutsan 

Yalan kokardı 

Sanal olan aslında hiç varolmazdı 

Fırtınada bir gemi

İçinde ben

Ve yüzme bilmemeden 

Yinede peşinden giderdim 

Ölüm tanıdık gelirdi 

Selamlaşırdık bolca

Biliyordum ve diliyordum 

Bu çıtayı bir gün atlayamayacaktım 

Buhar ferahlığında 

Zayıflatılacaktım 

İşin yoksa sil şimdi 

Yaşadığın heyecanları 

Nefes nefese canlı kanlı 

Nabız öldüren hikayeleri 

Bir çalıntı zamanda

Yenilmeyen yemekteki 

Kaçamak bakışları 

Belli belirsiz dokunmaları 

Sil silebilirsen 

Ayaksız tutarsız davranışları 

Zülfikarlar dayanmadı 

İçimdeki savaşa

Yenildim durdum

Sehpalara geleyim isterdim 

Yarasa vakitlerde 

Yalnızlıklarda silindim

Saydam oldum', 'Sana öykülenirdim geceleri  Bambaşka diyarlarda Isırgan otu yalnızlıklarda  Yakıcı tırmalayıcı tenlerde Bir sokak lambası aklımı alırdı  Sen...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/silindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Tanığı Benim', 'tek-tanigi-benim-baykal-kaanalp-mvg7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek tanığı benim 

Yasak aşkların

Vurdum duymaz onurların

Karşı konulmaz yortuların

Öncelikle sevmek gerek 

Derler

Sonrası,sonrası 

Kendi gelir

Gelmelidir

Tek tanığı benim

Sevgisiz yılların

Kaçıp giden, ellerin

Diyarına sabırsızlığın

Öncesi olmalıdır,aşkın

Derlerde inanmam

İnanmalı mıyım?', 'Tek tanığı benim  Yasak aşkların Vurdum duymaz onurların Karşı konulmaz yortuların Öncelikle sevmek gerek  Derler Sonrası,sonrası  Kendi gel...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-tanigi-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul bir haber uçururdu', 'kul-bir-haber-ucururdu-gencay-coskun-t6l97', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kul bir haber uçururdu 

Ben bir duydum 

Göktaşları sağanak halde beyinlere yağardı 

Bembeyaz kefende temiz bir kan damlası vardı

Uzanıp almak artık imkansızdı 

Toprak bizi beklerdi 

Kazaydı, falandı, filandı

Yaşadıklarımız düpedüz hikayeydi

Toprağın tadı fena halde acıydı 

Bir başkasının acısı taşıyordu içinde

Çok önceden düşerken tam içine

Pehlivan gibi yaşarsın 

Çam gibi devrilirsin boylu boyunca

Özgürlük için gökyüzü bile yetmez 

Uzay dediğin çok büyük bir hapishane 

Dünya dediğin 

Küçücük içi dolu insancık 

Kapının ardı karanlık değil aslında

Önemli olan ışığın yerini bulabilmekti 

Yaz yaprakları ansızın çıkan rüzgarlarla savrulup 

Dallarından düşerlerdi toprağa. 

Güz gibi haber vermezdi ne zaman geleceğini. 

Yoklukların yaktığı bir kandil, 

Yağıysa sere serpe umutlardı aslında. 

İki arada bir derede gidiyorsa hayat

Tutunabildiğin dalları 

Asla koparmayacaksın 

Bir dalda sen olacaksın 

Gelen diye bildiklerini 

Sıkıca tut ki 

Dosdoğru gidebilesin 

Kul bir haber uçururdu 

Hikaye vuruldu

Her hikayenin bir sonu vardı ama 

Bu hikayenin sonu daha yazılmamıştı

Yazacak ben isem asla da yazılmayacaktı.

Yazacak sensen sonunu çok yazdın aklında……

Bana uysa da uymasa da……..', 'Kul bir haber uçururdu  Ben bir duydum  Göktaşları sağanak halde beyinlere yağardı  Bembeyaz kefende temiz bir kan damlası vardı Uzanıp alma...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kul-bir-haber-ucururdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Bulduk', 'biz-bulduk-baykal-kaanalp-k4f2d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kendimiz etttik,kendimiz bulduk

toprağa su vermedik,biz solduk', 'kendimiz etttik,kendimiz bulduk toprağa su vermedik,biz solduk...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/biz-bulduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varmış,Bir Yokmuş', 'bir-varmis-bir-yokmus-baykal-kaanalp-52pxy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir varmış,bir yokmuş

yaşanmış acılar içinde

kalan sağlar çokmuş

dedem anlatırdı,bana

eski zamanı

gezdiği yerleri

nefes aldığı her anı

''anlatacak çok şey bulur

o kadar görmüş geçirmiş ki

kitaplara sığmaz heyecanı

bir gün tatlı dilli

güler yüzlü sevecen

bir gün çetin ceviz

anlaşılmaz bir ihtiyar''

ama yaşanmış bir parça

keder yok hayatında

hep mutlu,hep umutlu

yarınlarından

aslında yarına komaz

anını', 'bir varmış,bir yokmuş yaşanmış acılar içinde kalan sağlar çokmuş dedem anlatırdı,bana eski zamanı gezdiği yerleri nefes aldığı her anı ''anla...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-varmis-bir-yokmus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir garip sevdadır sensizlik', 'bir-garip-sevdadir-sensizlik-hicabi-ceylan-hkpae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzun seneler geçti üzerinden

Çıkarıp atamadım  seni kalbimden

İçimde depremler olsa da

Yer oynasa yerinden

Bilmelisin sevgili

Seni senden daha çok seviyorum ben

Coşkun sel gibiydim duruldum 

Daha gonca iken sana vuruldum

Ben hiç yanmaz idim

Aşkınla kor ateşlerde kavruldum

Bilmelisin sevgili

Geleceksin umuduyla beklemekten yoruldum

Sensiz belli değil ki adresim

Bir gün orda bir gün burda avare, avare gezerim

Ben hiç ağlamaz idim

Yokluğunda kan ağlıyor şimdi gözlerim

Bilmelisin sevgili

Gelmesen de ömrümün sonuna kadar  beklerim

Baharda kırıldı dallarım

Bir, bir döküldü bütün yapraklarım

Ben hiç solmaz idim

Yokluğunda susuzluktan yarıldı topraklarım

Gelmelisin sevgili

Tükendi ömrüm aklaştı saçlarım

Gelmelisin, gelmelisin', 'Çok uzun seneler geçti üzerinden Çıkarıp atamadım  seni kalbimden İçimde depremler olsa da Yer oynasa yerinden Bilmelisin sevgili Seni sende...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-garip-sevdadir-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baraj', 'baraj-baykal-kaanalp-9hrtl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yeni yapılmış bir baraj

tarla sulamak için

çocuklar yüzmek için

kullandılar

önce en küçükleri

atladı suya

ardından onu,aramak

için,bir başkası

sonra üçüncü çocuk

dördüncü çocuk atlamadı

hemen koştu

köylüye haber verdi

bir hafta boyunca

aradılar

bulamadılar ama

dördüncü çocuk

yüzme bilmiyordu', 'yeni yapılmış bir baraj tarla sulamak için çocuklar yüzmek için kullandılar önce en küçükleri atladı suya ardından onu,aramak için,bir başka...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baraj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irmak...', 'irmak-emirhan-bala-w0mg7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ulaşmak ırmağın saklı kaynağına, 

yıkamak her damlasıyla ruhumu, 

içmek yudum yudum doyasıya, 

kıskanırım saklı ırmağım suyunu...', 'ulaşmak ırmağın saklı kaynağına,  yıkamak her damlasıyla ruhumu,  içmek yudum yudum doyasıya,  kıskanırım saklı ırmağım suyunu......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/irmak-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açmayan Yediveren Gülleri', 'acmayan-yediveren-gulleri-nevin-kalafatoglu-6t345', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzun saçlarının olduğu zamanlardı 

gözlerinin parladığı

habersiz  gönüllerden gelen

aşk seslerini bilmediği

gönül çalanların cirit attığı günler 

ömrünün üçte birine konan ipoteklerini

ödediğini

bilemediler

iki aylık gelin feryatlarındaydı

oysa gözleri

göremedi kimseler 

yılları

sakladı hep bakışları

yaban ellerden

okunmasın diye örtündüler kirpikler

süzüldü göz yaşları hep boşluklara

mutsuzluk yıllarını beklediler

oldumu şimdi bu  nedir yaptığın

kaçamak sevgileri ektiğin saksılarda

yediveren güller

bir ömür açmadan beklediler

belki senin yüzünden', 'uzun saçlarının olduğu zamanlardı  gözlerinin parladığı habersiz  gönüllerden gelen aşk seslerini bilmediği gönül çalanların cirit attığı gü...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/acmayan-yediveren-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlanma Umut', 'nazlanma-umut-ali-bicer-80o9q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu gece ay yok

her saniye yeni bır deprem

dört yanım çöküntü

vuruyorum kendimi karanlığa

ellerim ateş 

dilim dudaklarım

bitimsiz aşk sürgünü

kranlıkta saklı güneş

karanlıkta kadınlar sevişir

çılgınca

kranlıkta çocuklar gelır dünyaya

çığlık çığlığa

ısyan

nazlanma umut 

gel düş benımle yola

çoktan başladı kavga

yürek eşiğimizden içeriye atladı sevda

gel düş benimle yola

umut

bekleme daha fazla', 'bu gece ay yok her saniye yeni bır deprem dört yanım çöküntü vuruyorum kendimi karanlığa ellerim ateş  dilim dudaklarım bitimsiz aşk sürgünü...', ARRAY['Türk Edebiyatı','Şiir','Ali Biçer']::text[], 8.5, '{"poet":"Ali Biçer","poet_slug":"ali-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nazlanma-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocamış Kadınlar', 'kocamis-kadinlar-ahmet-hakan-yilmazturk-s613l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yabanda bitmiş güldüler

Goncaları açılmadan soldular 

Soğuk vurmuş ekindiler

Başakları serpilmeden kurudular 

Yalnızlıklar evinin bekçisi

Yaşanmamış anıların nöbetçisi

Kocamış kadınlar ne duyar

Boş gülüşlerin gizli öfkesini

Kocamış kadınlar ne duyar

İç çekmelerin ürkek sesini

Yalnızlıklar evinin bekçisi

Yaşanmamış anıların nöbetçisi

Kocamış bu kadınlar, hem de çok

Sevilmeden, okşanmadan, öpülmeden

Burkulmuş bu kadınlar, hem de çok

Hayatın tam ayak bileklerinden

Yalnızlıklar evinin bekçisi

Yaşanmamış anıların nöbetçisi

Hikayeleri neydi unuttum

Dinlemek isteğim, umudum

Kardeşlikleri hatırladığım

Kutsanmış yürekleri öptüğüm

Yalnızlıklar evinin bekçisi

Yaşanmamış anıların nöbetçisi

19.08.2004', 'Yabanda bitmiş güldüler Goncaları açılmadan soldular  Soğuk vurmuş ekindiler Başakları serpilmeden kurudular  Yalnızlıklar evinin bekçisi Ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kocamis-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyurum', 'uyurum-ali-bicer-b253b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başımı kanadımın altına alır

bir serçe gibi uyurum

ürkek yüreği ağzında

başımı kanadımın altına alır

bir kartal gibi uyurum

tetik,yüreği çatal

başımı kanadımın altına almadan

bir tay gibi uyurum

çevik,hep ayakta

bir ağaç gibi

başımı maviye kor uyurum

gecenın koynunda

hem çoğul hem bir başıma

bir dağ gibi uzanırım uykuya

gözlerim doruk olur

açik,gökyüzüne dikili

giz kayaları arasında

bir kara yılanım

sarılır uyurum zehrime

yaralı umut,yarı gövde

uzaklarda

içli bir kadın sesi

usul usul niniler acılarımı

öylece kıvrılır uyurum gövdemin üstüne', 'başımı kanadımın altına alır bir serçe gibi uyurum ürkek yüreği ağzında başımı kanadımın altına alır bir kartal gibi uyurum tetik,yüreği çat...', ARRAY['Türk Edebiyatı','Şiir','Ali Biçer']::text[], 8.5, '{"poet":"Ali Biçer","poet_slug":"ali-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/uyurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Firari Bulutum', 'ben-bir-firari-bulutum-karahan-yilmaz-vsfsc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir firari bulutum

Mavidir en güzel umudum

Ufuklarımda güneşler doğar

Gökyüzüdür benim yurdum

Toprağa sevdalıdır ellerim

Asi bir rüzgar olur eserim

Takar kollarıma baharları

Dünyaya özgürlükler ekerim

Uzak ve karlı dağ başlarında

Geceleri yıldız toplarım

Denizlerin köpük köpük saçlarında

Bir martı olur uçarım

6 ağustos 2004', 'Ben bir firari bulutum Mavidir en güzel umudum Ufuklarımda güneşler doğar Gökyüzüdür benim yurdum Toprağa sevdalıdır ellerim Asi bir rüzgar ...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-bir-firari-bulutum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-karahan-yilmaz-w1xwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim gözlerim

Renklerin en güzeline aç

Renklerden siyah’ ın

Siyahtaki ak’ ın

Sırrına muhtaç

Sevgilim

1978 -Nevsehir', 'Benim gözlerim Renklerin en güzeline aç Renklerden siyah’ ın Siyahtaki ak’ ın Sırrına muhtaç Sevgilim 1978 -Nevsehir...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozlerim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-karahan-yilmaz-r2wu7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey sevgili! 

Düşündün mü hiç

Ulaşılacak olanın

Nasıl çekilir özlemi

Agustos 1984', 'Ey sevgili!  Düşündün mü hiç Ulaşılacak olanın Nasıl çekilir özlemi Agustos 1984...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozlem-178-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocuklar', 'cocuklar-karahan-yilmaz-ror6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılar büyütür bizde

Cocukları anneler yerine

Ve yangından yangına koşarlar

Beşinde, altısında, yedisinde..

Eylül 1984', 'Acılar büyütür bizde Cocukları anneler yerine Ve yangından yangına koşarlar Beşinde, altısında, yedisinde.. Eylül 1984...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cocuklar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeş Yıldızlar', 'kardes-yildizlar-karahan-yilmaz-azj37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyılarımda

Ne köpüren mavi bir denizim var

Ne de başımın üstünde

Sırtını maviye dayamış bulutlar

Oysa gecenin koynundayım şimdi

Güneşi bekler alnımda  şafaklar

Evecen adımlarla yürürken dışarda şafak

Içerde gecenin kalbi ha durdu ha duracak

Tanık olun ey kardeş yıldızlar! 

Bu gece bulutlar bize saldıracak...

Subat 1985 -Metz', 'Kıyılarımda Ne köpüren mavi bir denizim var Ne de başımın üstünde Sırtını maviye dayamış bulutlar Oysa gecenin koynundayım şimdi Güneşi bekl...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kardes-yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirsel Yüreğimde', 'siirsel-yuregimde-karahan-yilmaz-clru9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir göçmen kuş gibi

Gezer dolaşırım ülkeleri

Onda bahar kokusu var

Bende şiir sevinci..

Sevgi sevgiyle sevişir

Benim şiirsel yüreğimde

Aşk bir şiirdir

Şiirleşen dizelerimde..

Açık denizler üstünde

Güneşle sevisirken ben

Bana bakar bir göçmen kuş

Cinarların tepesinden...

Bir dost gibi gelir

Bir dost gibi giderim

Cınarların gölgesinde

Oturur baharı seyrederim

Ocak 1986', 'Bir göçmen kuş gibi Gezer dolaşırım ülkeleri Onda bahar kokusu var Bende şiir sevinci.. Sevgi sevgiyle sevişir Benim şiirsel yüreğimde Aşk b...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siirsel-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borny Sokaklarında', 'borny-sokaklarinda-karahan-yilmaz-ngt8f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlıklarla boğuşa boğuşa

Yürüyorum günboyu sokaklarda

Gündüzleri güneş dolduruyorum

Geceleri yıldız koynuma…

Içimde bir yabancılık duygusu

Kemirip duruyor, umudumu

Ve dayanılmaz oluyor gün geçtikçe

Içimde ki yabancılık korkusu..

Zenci bir kızla kol kola

Dolaşıyorum borny sokaklarında

Onun renginde suç yazıyor

Benim pasaportumda...

1986 Metz

Not: Borny, metz’de fransız olmayan topluluklarin yoğun olarak yaşadıkları bir mahalllenin adıdir', 'Yalnızlıklarla boğuşa boğuşa Yürüyorum günboyu sokaklarda Gündüzleri güneş dolduruyorum Geceleri yıldız koynuma… Içimde bir yabancılık duygu...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/borny-sokaklarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşek', 'esek-cafer-yilmaz-8ctfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sun ey saki şişeden

Gimi kederden içer gimi neşeden

Ömrüm geçer heybeden

Benim eşek getmeyo getmeyo....

Geçim seçim derken gön bitti

Evde ekmek, aş, un bitti

Elde eşek aya getti

Benim eşek getmeyo getmeyo...

Üç kuruşa zar zor geçim

Evde var üç beş hetim

Ahırda ki tek servetim

Benim eşek getmeyo getmeyo...

Zabah onlan uyanırdım

Erken erken yollanırdım

Üç beş kuruş kazanırdım

Benim eşek getmeyo getmeyo...

Etim budum oydu benim

Çarşıdaki Mercedesim

Dağlardaki cipim benim

Benim eşek getmeyo getmeyo...

Kul fakirin nimeti o

Er kalkmaya sebebi o

Ele güne hizmeti o

Benim eşek getmeyo getmeyo....

                                        07/04/2004', 'Sun ey saki şişeden Gimi kederden içer gimi neşeden Ömrüm geçer heybeden Benim eşek getmeyo getmeyo.... Geçim seçim derken gön bitti Evde ek...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/esek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Türküsü', 'gunes-turkusu-karahan-yilmaz-j1rdm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben tutkunum güneşe

Güneş tutkun  herkese

Haydin gidelim çocuklar

Güneşi batmayan günlere

Alıp güneşe götürün beni

Sarıp sarmalayıp öpün beni

Haydin toplanalım çocuklar

Söyleyelim mutluluk türkülerini

Eylül 1986', 'Ben tutkunum güneşe Güneş tutkun  herkese Haydin gidelim çocuklar Güneşi batmayan günlere Alıp güneşe götürün beni Sarıp sarmalayıp öpün ben...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunes-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-karahan-yilmaz-z0xll', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dışarda bahar kokarken toprak

Içerde baharı solumak bile yasak

Sen baharı kuşanda gel sevdiğim

Baharı koklayacağım seni koklayarak', 'Dışarda bahar kokarken toprak Içerde baharı solumak bile yasak Sen baharı kuşanda gel sevdiğim Baharı koklayacağım seni koklayarak...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bahar-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soytarı', 'soytari-adnan-durmaz-e7sux', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“.............Kederinden dişleri kenetlenmiş, sakalı ak, sakalı kirli, aydınlık

yüzlü, geniş alınlı duvar dibinde güneşlenen yaşlı adama sordu:

''Bir zamanlar bu şehirde konuksever, sıcak yürekli, dost canlısı iyi

insanlar, ceren gibi, kırmızı mercan gözlü, uzun boyunlu, kalem kulaklı, suna

gibi cins atlar vardı. Onlara ne oldu? ''

Yaşlı adamdır ki, azıcık doğruldu, ak saklı kirli, titredi, yüzü eski

bir ışıkla parıldadı, derin bir aaah dedi, ciğeri söken. Aaaah! Duvara sırtını

iyice verdi.

Neden sonra gözlerini açtı:

''O iyi insanlar,'' dedi, ''o güzel atlara bindiler çekip gittiler...

Aaaah! Aaaaah! Aaaaaah! ''

                                                               Yaşar Kemal, Demirciler Çarşısı Cinayeti.



bunlar kaldı elimizde

işinize gelmese de

alır kendilerine mal ederler

onca acıdan ve fırtınadan

               sana kalan efkarı

alır ayaklar altına

soyarlar anlamından

hançer keskini dillerinden

bilgiç manalar vermeye çalıştıkları

bön bakışlarından tanı onları

bir garip güruh ki

bakarsın solcu

bakarsın sağcı

düpedüz yağcı

elleri kirden çıkmaz

periskoptur kulakları

soy

ta

rı

sahtiyan gülüşlerinden tanı onları

anlamazlar kitabi tarafından hiçbir şeyin

okumadan alim

doğuştan şair

bütün incelikler onların tekelinde

aşk bile onlar için var

devran onların devranı

kara kara kargalar

aslında binyıllardır iktidardalar

müdürse

bir üstüne

memursa 

amirine

mutlaka yaltaklanacak

kendinden alt basamağın başında

zulüm yumruğu

iyilik onların tekelinde

güzellik onlar için

sevgi diye sunarlar nefreti

ve vatanseverlik ayaklarına

satarlar memleketi

iyi gözle onları

Haramzade  elin öpüp

Dem oldu tükürdüler

her yerde

her zaman 

hazır ve nazır

hangi parti iktidarda

onlar onun militanı

ama kelimelerin altında

bir hazin pislik akar

sözcükler sapsarı

soy

ta

rı

romayı yakışını

onlar alkışladı nöronun

hüseyini katledenin

ardındaki sürüydüler

ve yeni gelen iktidarlarda

en ön safta yürüdüler

alkışladılar da celladı

devir değişince

kurbandan yana höykürdüler

şimşir taraktırlar

kel başa

sütten çıkmış kaşık

dolaşık

bulaşık

padişahım

çok yaşa

devranla birlikte değişip

eski sahiplerine ürdüler

karanlık geçmişlerini

hahramanlık öyküleriyle

kamuflaj yaparak anlatırlar

oysa ihanetler bırakmışlar arkalarında

ve fakat zamanımızda

alenidirler gün gibi

yakında

kurarlarsa

daltarak partisini

şaşırmamalı

insanlık tarihinde

görülmemiş kadar çok

bok

ortalıkta kıvıl kıvıl 

kaynıyorlar

ağıtlara bile

göbek atıp

oynuyorlar

bir garip güruh ki

bakarsın solcu

bakarsın sağcı

düpedüz yağcı

elleri kirden çıkmaz

periskoptur kulakları

soy

ta

rı

adnan durmaz', '“.............Kederinden dişleri kenetlenmiş, sakalı ak, sakalı kirli, aydınlık yüzlü, geniş alınlı duvar dibinde güneşlenen yaşlı adama sor...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/soytari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Duvar Diplerinde', 'tas-duvar-diplerinde-karahan-yilmaz-c7kd3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kondu sokaklarının birinde

Gün gelip nöbet tutacağim yine

Ve yıldızları alıp koynuma

Kıvrılıp yatacağım bir köşede

Tutulurken günlerin  nöbeti

Kireç kokulu taş duvar diplerinde

Yoksulluğun üstünü örteceğim

Üstümden çıkardığım ceketimle..

Subat 1987', 'Kondu sokaklarının birinde Gün gelip nöbet tutacağim yine Ve yıldızları alıp koynuma Kıvrılıp yatacağım bir köşede Tutulurken günlerin  nöbe...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tas-duvar-diplerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Güneş Kokuyor', 'ellerim-gunes-kokuyor-karahan-yilmaz-org15', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şiirde bir dizeyim

Her dizede bir imge

Bazen dağlara dayarım sırtımı

Bazen ufuktaki güneşe

Ellerim güneş kokuyor

Ayaklarım toprak

Saçlarımda yıldızlar akıyor

Gözlerim sanki bir şafak

Örtün şu bulutları üstüme

Üşümesin koynuma aldığım  bahar

Ve söyleyin saçlarımı tarasın

Saçlarımda akan o yıldızlar..', 'Her şiirde bir dizeyim Her dizede bir imge Bazen dağlara dayarım sırtımı Bazen ufuktaki güneşe Ellerim güneş kokuyor Ayaklarım toprak Saçlar...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellerim-gunes-kokuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karapınar', 'karapinar-sinan-gundog-ywvlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekinler sararmıştır,şimdi köyümde

Er geç biçilecek gün dönümünde

Sergiciler toplanmıştır cami önünde 

Bekle beni Karapınar; döneceğim günün birinde

Giderken dam önüne kavurur sıcak

Ağrı çöker dizlere saplanır bıçak

Biçilen ekinler harmanlanacak

Patoz olur, seç çekeriz,çuvallarız kucak kucak

Yenipınar yaz kış gürül gürül akıyor

Kezban ebe çıkmış yarenlerden bakıyor

Deste çekmekten geldim alnımdan ter akıyor

Şimdi köyde olsam keşke; köy burnumda tütüyor

Salı,çarşamba,cuma Ahmet gider pazara

Abdullah minibüsle takılır arkasına

Kimi traktörüyle gider mal pazara

Çimento,keçi,koyun doldururlar arabaya

Selami ile Sabrinin kavgası yeter artar

Selami holding oldu serviste yapar

Sabri Selamiden müşteri kapar

Rekabet Büyür gider kıyamet kopar

Şaban dede abdest almış cıgara sarar

Yanına vardınmıydı oğullardan dert yanar

İçli içli anlatır derdine derman arar

Gözümde tüter oldu güzelim Karapınar

Akşam üstü kahvede oynardık oyun

Kahvenin önünden geçer sürüyle koyun

Sulu Hüseyin çay getirir içinde doyun

Ayaklı gazeteler kahvede yapıyor yayın

Hacıların Mustafadır köyün ayaklı gazetesi

Herşeyden haber alır kuvvetli vericisi

Telefon Ayşe,çelgenlerin Şerife köyün kadın habercisi

Rütük kapatmış sanki sirkeli Bekdeşin çıkmıyor sesi

Sağa sola bakar Çiçek mustafa söver durmadan

Deli Kadir rahat etmez öküzüne vurmadan

Kızlar sudan geliyor yenipınardan

Söylen nasıl vazgeçeyim Karapınar''dan

YER:İSTANBUL/Ataşehir', 'Ekinler sararmıştır,şimdi köyümde Er geç biçilecek gün dönümünde Sergiciler toplanmıştır cami önünde  Bekle beni Karapınar; döneceğim günün ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Gündoğ']::text[], 8.5, '{"poet":"Sinan Gündoğ","poet_slug":"sinan-gundog","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/karapinar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-faruk-tak-ic615', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç

keşke demeyen varmıdır

her şey olup bittikten sonra 

ve devam ederken yaşam

keşke

demek kadar kolay olsaydı

hatalardan dönmek

önemi kalırmıydı yanlışların

alt alta sıralayıp

bu az yanlış

bu çok yanlış diyerek

seçebilseydik keşkeleri

keşke', 'hiç keşke demeyen varmıdır her şey olup bittikten sonra  ve devam ederken yaşam keşke demek kadar kolay olsaydı hatalardan dönmek önemi kalı...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/keske-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küflü Gözlerine', 'kuflu-gozlerine-cafer-kurtoglu-2cazw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'rütubetli hücrelerimi isyan bürüdü

bu son bakışım olacak küflü gözlerine

yüreğimin derinliğine boranlar düşdü

bu son bakışım olacak küflü gözlerine

damarımdan kanım çekiliyor damla damla

mecal kalmadı derman aradım bakışınla

granit kayaya mıhlandı yüreğim sevdanla

bu son bakışım olacak küflü gözlerine

seni anışta gülleri ısırganlar sardı

bülbül ah eder çiçekler kızala boyandı

cilvelerin ızdırap verdi gönlüm daraldı

bu son bakışım olacak küflü gözlerine

kevser ırmağında huzurlar ararken düşüm

sellerine karışıp bulandı benim gönlüm

gözlerinin ürpertisiyle tükendi ömrüm

bu son bakışım olacak küflü gözlerine', 'rütubetli hücrelerimi isyan bürüdü bu son bakışım olacak küflü gözlerine yüreğimin derinliğine boranlar düşdü bu son bakışım olacak küflü gö...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuflu-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Dolu', 'deli-dolu-faruk-tak-8hnu4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolu dolu yaşamak isterdi

Deli dolu yaşıyor

Sığındığı küçük yalanlar büyüdü,görmedi

Ama dostlarını sevdi dost gibi

Düş kurdu biriktirdi.Kurdu,kurdu biriktirdi

Düşlerini hep başka yaşamlara erteledi

Çalçene sohbetler yaptı.Çok konuştu çok; boş boş

Ama dostlarını sevdi dost gibi

Yırtık pırtık bohçasından ezberlenmiş öyküler çıkarttı

Anlattı,anlattı,anlattı

Dinlemeyenleri dürttü yeni baştan anlattı

Ama dostlarını sevdi dost gibi

Şişmanladın dediler,gaz dedi

Rejim yap dediler,pazartesi dedi

Kızdı yedi,sevindi yedi; pazartesiler hiç gelmedi

Ama dostlarını sevdi dost gibi

Onun kalıpları vardı,iyilik kötülük adına

Kalıba uymayanlar ne çoktu

Ne çok sövmek zorundayım demedi,sövdü

Ama dostlarını sevdi dost gibi

Toparlan dediler.Boşver dedi; güldü dolu dolu

Vazgeç yalandan dediler.En büyük yalanını söyledi

Anam avradım olsun daha yalan yok dedi

Ama dostlarını sevdi dost gibi

Dolu dolu yaşamak isterdi

Deli dolu yaşıyor', 'Dolu dolu yaşamak isterdi Deli dolu yaşıyor Sığındığı küçük yalanlar büyüdü,görmedi Ama dostlarını sevdi dost gibi Düş kurdu biriktirdi.Kurd...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/deli-dolu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Sabahı', 'bahar-sabahi-cafer-kurtoglu-rjjqc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüreğim tanık oldu bu sevdaya

bahar sabahı daldım gözlerine

gönlüme kök saldı açan akasya

bahar sabahı daldım gözlerine

çılgınca yaşadığımız aşklara

hayran hayran bakar Cleopatra

yeniden gömülür şuh sevdalara

bahar sabahı daldım gözlerine

yüreğime damar damar sokuldun

doruklarda yaslı kerem''in buldun

züleyha aşk tutsağıdır yusuf''un

bahar sabahı daldım gözlerine

güller sunar tablodan mona lisa

yüreğimi dağlar sihirli bir asa

derindir gönlün kuyusu ben oysa

bahar sabahı daldım gözlerine', 'yüreğim tanık oldu bu sevdaya bahar sabahı daldım gözlerine gönlüme kök saldı açan akasya bahar sabahı daldım gözlerine çılgınca yaşadığımız...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahar-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sel', 'sel-faruk-tak-95t01', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zor olan beklemek biliyorum

Direncinin sınırlarını zorladığınıda

Gözlerinde biriktirdiğin pınarların

Bendini yıkmasından korkuyorum', 'Zor olan beklemek biliyorum Direncinin sınırlarını zorladığınıda Gözlerinde biriktirdiğin pınarların Bendini yıkmasından korkuyorum...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerküklü Türkmenem', 'kerkuklu-turkmenem-cafer-kurtoglu-qcqh1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gönlümde tutuşur kızıl elma

sevdayla yanan kerküklü türkmenem

ışıklardan sevgiler yansır başbuğuma

sevdayla yanan kerküklü türkmenem

meydan boş kalmasın koştur atları

yetim bırakırsın soylu aşkları

yüreğimde sızlar tanrı dağları

sevdayla yanan kerküklü türkmenem

ısırganlar sarıyor gülistanı

hoyrat eller tutmasın bu sevdanı

bulursun bende sızlayan yaranı

sevdayla yanan kerküklü türkmenem

musul ve kerkük''ten ah''larım gelir

gözümden akar maveraünnehir

ulu ülküsü olmayan ne bilir

sevdayla yanan kerküklü türkmenem', 'gönlümde tutuşur kızıl elma sevdayla yanan kerküklü türkmenem ışıklardan sevgiler yansır başbuğuma sevdayla yanan kerküklü türkmenem meydan ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kerkuklu-turkmenem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dursun', 'dursun-faruk-tak-ys6fy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak dursun

Ay(han) larda gün batarken

Belaltı fıkralar çıkınında,

Bırak dursun

Son kadeh rakı masada

Demindedir artık sözcükler

Saç etrafa', 'Bırak dursun Ay(han) larda gün batarken Belaltı fıkralar çıkınında, Bırak dursun Son kadeh rakı masada Demindedir artık sözcükler Saç etrafa...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihten Geleceğe Türk', 'tarihten-gelecege-turk-taha-nur-uxl52', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adım Türk, namım Osman,

Göğsüm kabarık, alnım aktır.

Şanım büyük, boyum Kayhan,

Göğsüm kabarık, alnım aktır.

Orta Asya’da doğmuş,

Ergenekon’u bulmuşuz,

Medeniyetler kurmuş,

Kültürler yaşatmışız.

Mevcuden çoğalmış,

Ergenekon’a sığmamışız.

Yeni diyar aramış,

Ergenekon’dan çıkmışız.

Yurt aramaya koyulmuş,

Dört yana dağılmışız.

Anadolu’yu bulmuş,

Beyliğimizi kurmuşuz.

Yeni yurdumuzda dostumuz,

Arkadaşımız, kardeşimiz,

Bizlerle beraber olmuş,

Bunlara huzur vermişiz.

Yeni yurdumuzda düşmanımız,

Hainlerimiz, belalılarımız,

Bize karşı olmuş,

Bunları rezil etmişiz.

Yurdumuzu yeşertmiş,

Güzelliklerle süslemişiz,

Harabeleri düzeltmiş,

Gülşen etmişiz.

Yeni medeniyet kurmuş,

Şuur vermişiz.

Zihinleri doldurmuş,

Hakikati sunmuşuz.

Hak düşmanıyla savaşmışız,

Nice ufuk açmışız.

Karanlığı delmiş,

Aydınlık etmişiz.

Hakkı, adaleti yaymış,

İnsanlık için çalışmışız.

İslam’a öncülük etmiş,

Felah için uğraşmışız.

İlim, irfan yapmış,

Alimler yetiştirmişiz.

Fikir aktarmış,

Huzur vermişiz.

Nizamı sürdürmüş,

Epeyce ilerletmişiz.

Bir zaman gelmiş,

Artık ilerlemez olmuşuz.

Bu yüzden eski düşmanlarımız,

Düşman olmuş dostlarımız,

Hepsi de birlik olmuş,

Aralarında paylaşılmışız.

Bağımsızlığı kaybetmişiz,

Zulümle karşılaşmışız.

Kurtulma çareleri aramış,

Kuvveti imanda bulmuşuz.

Genç ihtiyar savaşmış,

Milli kuvvet olmuşuz.

Yeniden kükremiş,

Düşmanı denize dökmüşüz.

Dünyaya hür gelmiş,

Hür yaşayacağız.

Düşman çok uğraşmış,

Hep hezimete uğratmışız.

Dost olana dostuz,

Huzur veririz.

Düşmana düşmanız,

Korku veririz.

Sulh için savaşırız,

Sulhtan yanayız.

Savaşta savaşçıyız,

Savaşa karşıyız.

İnsan değer veririz,

Haklara saygılıyız.

Hak ile yaşarız,

Hakkımızı çiğnetmeyiz.

Adım Türk, namım Osman,

Göğsüm kabarık, alnım aktır.

Şanım büyük, boyum Kayhan,

Göğsüm kabarık, alnım aktır.', 'Adım Türk, namım Osman, Göğsüm kabarık, alnım aktır. Şanım büyük, boyum Kayhan, Göğsüm kabarık, alnım aktır. Orta Asya’da doğmuş, Ergenekon’...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/tarihten-gelecege-turk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimler', 'kimler-taha-nur-ziys9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkma diyorlar bana.

Ben korkmayım da kimler korksun? 

Bakma diyorlar canana.

Ben bakmayım da kimler baksın? 

Bülbüle garip garip ötme deseler.

Güle de tomurcuğu açma deseler.

Bana da Hakk’ı anlatma deseler.

Ben anlatmayayım da kimler anlatsın? 

İlkbahara gitme derler.

Kışa da gelme derler.

Bana da sevme derler.

Ben sevmeyeyim de kimler sevsin? 

Alime ilim yapma deseler.

Şaire de şiir yazma deseler.

Bana da İslam’ı yaşama deseler.

Ben yaşamayayım da kimler yaşasın? 

Cambaza ipte oynama derler.

Haylaza itle dolaşma derler.

Bana da ilimle uğraşma derler.

Ben uğraşmayayım da kimler uğraşsın? 

Sarı altın kara olur mu? 

Kara kömür sarı olur mu? 

Taha Nur  hiç huzuru bulur mu? 

Ben bulmayayım da kimler bulsun?', 'Korkma diyorlar bana. Ben korkmayım da kimler korksun?  Bakma diyorlar canana. Ben bakmayım da kimler baksın?  Bülbüle garip garip ötme dese...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İslam İçin', 'i-slam-i-cin-taha-nur-3u0ys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine geldi aklıma,

Ağladım İslam için.

Düştü o kor canıma,

Sızladım İslam için.

Yolumuzu yitirdik,

Hakkımızı kaybettik,

Hani nerede o birlik.

Ararım İslam için.

Evvela baştacıydı.

Kâlplerin ilacıydı.

Her mü’mine devaydı.

Yanarım İslam için.

Onu yükselten adem.

Çalıştı didindi hem.

Ortaya çıkınca kem.

Vururum İslam için.

Taha Nur onu sever.

Ona çatanı neder? 

Ben bilirsem mahveder.

Ezerim İslam için.', 'Yine geldi aklıma, Ağladım İslam için. Düştü o kor canıma, Sızladım İslam için. Yolumuzu yitirdik, Hakkımızı kaybettik, Hani nerede o birlik...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/islam-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemyeşil Duygularla', 'yemyesil-duygularla-cafer-kurtoglu-c52j0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sıcak bakışınla damla damla eriyorum

yemyeşil duygularla hücrelerim baharda

bir gülün dudağından aşkımı sunuyorum

yemyeşil duygularla hücrelerim baharda

taze bakışınla anlamlıdır duygularım

çehresi parıltılı güzele sevdalıyım

ahu yüzlü bir kıza gönlümü kaptırmışım

yemyeşil duygularla hücrelerim baharda

aşk ateşi düşdü nazenim duygularıma

başka güneşler yansımaz sevdalı ufkuma

birer birer dikeceğim aşkını hülyama

yemyeşil duygularla hülyalarım baharda

sensiz olamam yazamam sensiz şiirimi

tadın damağımda bulurum senle zevkimi

mercan dudağınla anlatırsın sevgimi

yemyeşil duygularla hücrelerim baharda', 'sıcak bakışınla damla damla eriyorum yemyeşil duygularla hücrelerim baharda bir gülün dudağından aşkımı sunuyorum yemyeşil duygularla hücrel...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yemyesil-duygularla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dervişler', 'dervisler-taha-nur-pmf0b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar bile aşk ateşine,

Dayanamaz yanar gider.

Derviş olanın derdine,

Derviş olan ağlar gider.

Onlar aşık olmuş güle.

Bu dünyada çekse çile. 

Bir derviş düşse dile.

Ak gömleğin açar gider.

Derviş olanın bulunmaz eşi.

Zikrullahtır derviş işi.

Dervişleri inciten kişi.

Bu dünyadan naçar gider.

Aklın varsa çalış oraya.

Bu dünyada herşey boşa.

Bak dünyanın yüz karasına.

Yarın birgün sızlar gider.

Sakın ha kızma dervişe.

Gülme onların haline.

Uyma sen şeytan diline.

O dünyayı atar gider.

Bu dünya fani yoktur yaşı.

İnsan isen bil yediğin aşı.

Derviş kişi dünyanın başı.

Nehir gibi akar gider.

Derviş bırakır da gider şanını.

O gittikten sonra unuturlar adını.

Azrail almaya geldi mi canını.

Bu dünyayı tartar gider.

Taha Nur gel bu doğru yola.

Girelim derviş ile kol kola.

Zikrullah edelim ağlaya ağlaya.

Bu dünyayı sarsar gider.', 'Dağlar bile aşk ateşine, Dayanamaz yanar gider. Derviş olanın derdine, Derviş olan ağlar gider. Onlar aşık olmuş güle. Bu dünyada çekse çile...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dervisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-cafer-tayyar-ozkan-rujxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin doluyor bugün gözüme

Ummana dönmüşsün gözlerin puslu

Şarkılar çalıyor yangın gönlüme

Hicrana varmışsın sözlerin yaslı

Durulmuş halime aldanma sakın

Dileğim hücrende her an yaşamak

Sana vadettiğim sözlerim yakın

Özlemim sayende efsane yazmak

Düşlere teslimim kayıtsız şartsız

Hain duygulara dayanmaz kalbim

Gizemli hislerim yalnız anlamsız

Serzeniş sende durulmaz isyanım

Umutlar saçardın bahtsız gönlüme

Aşkımız kalbimde sanki ibadet

Çatık kaşlarınla bakma yüzüme

Göremezsin benden tek bir ihanet

Vuslatı tattığım koynu beklerken

Kaderin koynunda salıncak oldum

Yıllarca sabredip vefa gözlerken

Toprağın bağrında gelincik oldum

14 Ocak 2004 Ankara', 'Hasretin doluyor bugün gözüme Ummana dönmüşsün gözlerin puslu Şarkılar çalıyor yangın gönlüme Hicrana varmışsın sözlerin yaslı Durulmuş hali...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/serzenis-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol ile Yolcu', 'yol-ile-yolcu-taha-nur-vbhs0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yol uzayan bir ip,

Yolcu ağlayan bir garip.

Yol çeker, yolcu gider,

Böyle yazılmış keder.', 'Yol uzayan bir ip, Yolcu ağlayan bir garip. Yol çeker, yolcu gider, Böyle yazılmış keder....', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yol-ile-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim Pazarcık', 'memleketim-pazarcik-taha-nur-e97qo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıvrım kıvrım uzanır sana yollar.

Yükseldikçe yükselir dağlar.

Ziyaret Tepesi’ndeki çamlar.

Sen bir başka güzelsin Pazarcık.

Bereket saçan bir barajın var.

Kahramanlar diyarı bir Maraş’ın var.

Gönlümde teksin amma bir adaşın var.

Sen bir başka şirinsin Pazarcık.

Ovaların, toprağın bereket saçar.

Bağında, bostanında güller açar.

Aksu sende başlar, sende coşar.

Sen bir başka güzelsin Pazarcık.

Candan dost insanınla güzelsin.

Sen benim için özel mi özelsin.

Taha Nur seni hep metheylesin.

Sen bir başka şirinsin Pazarcık.', 'Kıvrım kıvrım uzanır sana yollar. Yükseldikçe yükselir dağlar. Ziyaret Tepesi’ndeki çamlar. Sen bir başka güzelsin Pazarcık. Bereket saçan b...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/memleketim-pazarcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesbitler', 'tesbitler-taha-nur-x7071', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tesbit 1

Ahlaksızlar hep alkışlanıyor, elde tutulur oldu onlar.

Çiğnendi örfüm, adetim, yutulur oldu onlar.

Tesbit 2

Toplayıp ta başına karıncaları, cinnet getirirsin.

Karıncalar gibi çalışmayı niçin hiç düşünmezsin? 

Tesbit 3

Babamın duasıdır, beni mutlu eden.

Hizmette kusura, bilin ki şeytan neden?', 'Tesbit 1 Ahlaksızlar hep alkışlanıyor, elde tutulur oldu onlar. Çiğnendi örfüm, adetim, yutulur oldu onlar. Tesbit 2 Toplayıp ta başına karı...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tesbitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Kalır', 'sakli-kalir-tunahan-ermihan-uspah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözler tükenir belki sevdiğim anlatamam

Sana sevdamı ve bir o kadar da ızdırabımı

Sana kurulan her cümlede sevdam saklı kalır

Denizin dibine gizlenmiş bir mercan gibi

Gündüzler tükenir belki sevdiğim göremem

Her sabah ufkuma doğuşunu ve dünyamı aydınlatışını

Sıcağından olgunlaşan her meyvede adın saklı kalır sevdiğim

Adam yüreğine atılan mürekkepsiz imza gibi

Yağmurlar tükenir belki sevdiğim yetişemem

Belki son düşen damla ile ıslanmaya

Bereketinden ıslanan kurak toprakta saklı kalır gülüşüm sevdiğim

O kurak toprakta açan papatyanın sırrı gibi', 'Sözler tükenir belki sevdiğim anlatamam Sana sevdamı ve bir o kadar da ızdırabımı Sana kurulan her cümlede sevdam saklı kalır Denizin dibine...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sakli-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket Hasreti', 'memleket-hasreti-taha-nur-yic4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatırımda çıkmıyor,

Özlediğim yerler,

Kâlbimde yer tutmuş,

Sevdiğim yerler.

Her yer cehennem bana,

Senden ayrıldığım zaman,

Gözümün önünden gitmiyor,

Kopamam hayır senden.

Verseler dünya dolu altını,

Veremez senin tadını,

Ben doğdum, ilk seni gördüm,

Gezdim, oynadım sende,

Ben burdayım, fakat,

Gönlüm seninle.

Annem orda, babam orda, kardeşlerim orda,

Gezdiğim, tozduğum yuvam orda.

Bu hayat bir başka, dağlar, ovalar başka,

Akan sular başka.

Gördüğüm rüya, düşündüğüm hayal,

Seninle olmayınca,

Tat vermiyor bana.', 'Hatırımda çıkmıyor, Özlediğim yerler, Kâlbimde yer tutmuş, Sevdiğim yerler. Her yer cehennem bana, Senden ayrıldığım zaman, Gözümün önünden ...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/memleket-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızır', 'hizir-taha-nur-r8911', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yetişen kim, en acımasız zamanda,

Tutup kollarından düşmesin diye.

İnanın Hızır her zaman hazır dünyada.

Görüp gözeten Rabbimizden bir hediye.', 'Yetişen kim, en acımasız zamanda, Tutup kollarından düşmesin diye. İnanın Hızır her zaman hazır dünyada. Görüp gözeten Rabbimizden bir hediy...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hizir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Kardeş', 'bak-kardes-taha-nur-cf95u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Müslimiz deriz namaz kılmayız,

Niyet etsek de oruç tutmayız.

Başımız dara girmedikçe,

Allah’a yönelip eli açmayız.

İlk hedefimiz para.

Onsuz kaldık mı atarız nara.

Bunca yıl İslamsız kaldık.

Birgün olsun atmadık nara.

Deli gibi dolaşırız dağda, kırda, bayırda.

Otlatırlar bizi koyun gibi çayırda.

Beyler gibi kral gibi yaşarız.

Asıl bizim yerimiz ahırda.

Camilere adım atmayız.

Eğlence yerlerinden hiç kalkmayız.

Oturup dinleriz sapık müziği.

Minarelerden okunana kulak asmayız.

Bizi yola getirmek ister alim.

Onu dinlemeyiz, orası malum.

Hergün boş yere vakit geçiririz.

Birgün olsun yapmayız ilim.

Baba namaz kılsa oğlu kılmaz,

İkisi de oturup beraber olmaz.

Neşeyle, zevkle geçen ömrün.

Hiçbir zaman hesabını sormaz.

Şimdilik keyifler yerinde,

Paralar ise şişkin ceplerde.

Kefene sarıldığın vakit,

Hiçbir şey kalmaz elde.

Çarşı, pazarda dünya hevesi,

Mahalle, kahvede dünya meselesi,

Meşguliyet bundan ibaret.

Hiç düşünen yok ahireti.

Yaşı ilerlemiş, kafası cahil,

Yaşı genç, ama kendi kamil.

Tersine döndün dünya,

Sonumuz belli, olacağız rezil.

Allah’ın emirleri boş gelir bize.

Kulun emirleriyle hemen eğiliriz dize.

Boş hevesler uğruna çalışır, didiniriz.

En sonunda sarılacağız o beyaz beze.', 'Müslimiz deriz namaz kılmayız, Niyet etsek de oruç tutmayız. Başımız dara girmedikçe, Allah’a yönelip eli açmayız. İlk hedefimiz para. Onsuz...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bak-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Kardeş', 'gel-kardes-taha-nur-z7emv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Müslimim deyip seni kandırma,

Fani dünya için imansız kalma.

Bak sıra bize geliyor,

Vakit geç olur, harama bakma.

Bırak at kenara o uğursuz parayı.

Bir kağıt parçasıyla sarma yarayı.

Yara ağır kağıtla sarılmaz.

Sarılsa bile dindirmez acıyı. 

Boş yere dolaşma yabanlarda.

Bu ömrün en vefalı anında.

Nefse dalıp öteye bırakma ibadeti.

Herşey sende, kuvvet ise imanda.

Camiler boş dururken,

Bu dünya akıp giderken,

Sana yar olur mu o kahve köşesi.

Alimler birbir dünyadan çekilirken.

Alimin sözlerini iyi dinle.

Gözünle değil tüm kâlbinle.

Riyakârlar boşta kalır.

Gelecek olan o ahirde.

Babanın namazı kendi kendine.

Her selin zararı kendi bendine.

Ümit bekleme hiç kimseden,

Bir umut varsa o da sende.

Bu keyifli günler gelir geçer.

Paraların da birgün suyunu çeker.

İşte o zaman berbattır halin.

Seni ne ora, ne bura ister.

Çarşı pazarın sonu tükenmez.

Ne alırsan al arzun sönmez.

Yeter artık yer kalmadı.

Kabir küçüktür eşyaların sığmaz.

Ey ihtiyar kurtul cahillikten.

Çalış genç zarar gelmez kamillikten.

Doğru dön ey dünya.

Fayda gelmez insana rezillikten.

Kulak ver hakkın emrine.

Çağırıyor o seni dine.

Eğer duymuyorsan,

Halin kötü, vay haline.', 'Müslimim deyip seni kandırma, Fani dünya için imansız kalma. Bak sıra bize geliyor, Vakit geç olur, harama bakma. Bırak at kenara o uğursuz ...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gel-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Mübarek Ramazan', 'hos-geldin-mubarek-ramazan-taha-nur-khw28', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hoş geldin alemi rahmetle dolduran.

Hoş geldin kâlpleri, gönülleri aydınlatan.

Hoş geldin nefsi, şeytanı susturan.

Hoş geldin ey mübarek Ramazan.

Sen gelince kaçar şeytan.

Sen gelince coşar iman.

Sen gelince yaşar insan.

Hoş geldin ey mübarek Ramazan.

Azıp kuduran nefisler,

Coşup taşan hisler,

Sen gelince titrer.

Hoş geldin ey mübarek Ramazan.

Mutluluk getirdin bize,

Şeytanı getirdin dize,

Işık verdin göze.

Hoş geldin ey mübarek Ramazan.', 'Hoş geldin alemi rahmetle dolduran. Hoş geldin kâlpleri, gönülleri aydınlatan. Hoş geldin nefsi, şeytanı susturan. Hoş geldin ey mübarek Ram...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hos-geldin-mubarek-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Mübarek Ramazan', 'gule-gule-mubarek-ramazan-taha-nur-klv7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onbir ayı aşıp geldin,

Bizlere mutluluk verdin,

Tüm alemi şenlendirdin.

Güle güle ey mübarek Ramazan.

Kilit vurdun nefsimize,

Işık saçtın kâlbimize,

Huzur verdin gönlümüze.

Güle güle ey mübarek Ramazan.

Sabrı, açlığı öğrettin,

Kabri, yokluğu gösterdin,

Zenginle fakiri bir ettin.

Güle güle ey mübarek Ramazan.

İnşaallah bir daha gelirsin.

Mü’mini mutlu edersin.

Tüm alemi şenlendirirsin.

Güle güle ey mübarek Ramazan.', 'Onbir ayı aşıp geldin, Bizlere mutluluk verdin, Tüm alemi şenlendirdin. Güle güle ey mübarek Ramazan. Kilit vurdun nefsimize, Işık saçtın kâ...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gule-gule-mubarek-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-taha-nur-3unnh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırk günlük çilem var.

Belki de daha fazla.

Koyu benliğim dayanır mı? 

Bilmem.

Acılarıma acırım.

Kar altında yalnız kal.

Sıcağı  soğukla karıştır.

Birgün biri diğerine benzer.

Hazırlıklıyım.

Beklenmedik işaretlere.

Kara, yağmura.

Ansızın gelen yıldırıma.

Belaya hazırım.

Upuzun geceleri,

Sigara dumanlarına boğmak,

Olmaz.

Taşırım da sırtımda.

Oturup hesabını yapacak değilim.

Gelen gelir,

Giden gider.

Kafam tertemiz olsun,

Yeter.', 'Kırk günlük çilem var. Belki de daha fazla. Koyu benliğim dayanır mı?  Bilmem. Acılarıma acırım. Kar altında yalnız kal. Sıcağı  soğukla kar...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yeter-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geldiği Zaman', 'bahar-geldigi-zaman-taha-nur-vhh4p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her taraf yemyeşile boyanır,

Bahar geldiği zaman.

Ağaçlar yapraklarla donanır,

Bahar geldiği zaman.

Gül tomurcuğunu açar,

Lale, sümbül boyun atar.

Her yer mis gibi kokar,

Bahar geldiği zaman.

Kuşlar cıvıldaşır uçar.

Koyun, kuzu meleşir oynar.

Her taraf neşeyle kaynar,

Bahar geldiği zaman.

Aşıklar alır sazı eline,

Vururlar dertli sazın teline,

Bir türkü dolar diline,

Bahar geldiği zaman.

Bir başka akar nehirler,

Bir başka ağlar kederliler,

Şarkılar söyler bülbüller,

Bahar geldiği zaman.

Uyuyan tüm mahlukat,

İlahi emirle alır hayat.

İnsan bulur bundan  tat,

Bahar geldiği zaman.

Hayatın rengi değişir,

Umutlar mutluluğa erişir,

Kuşlar uçar, kumrular sevişir,

Bahar geldiği zaman.

Geldi bahar sevindi tüm alem.

Yokolup gitti binbir elem.

Taha Nur ne geziyor elinde kalem? 

Kırlara çık, eğlen, dem bu dem.', 'Her taraf yemyeşile boyanır, Bahar geldiği zaman. Ağaçlar yapraklarla donanır, Bahar geldiği zaman. Gül tomurcuğunu açar, Lale, sümbül boyun...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bahar-geldigi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Gibi', 'i-nsan-gibi-taha-nur-ldtx5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan gibi dolaşırız, hiç utanmadan.

Bu dünya kurtulmaz İslam yaşanmadan.

Sokaklar dolusu eşkıya, bir o kadar sürüngen,

Ender bulunur haysiyetli, başı dik gezen.

Koltuğa oturunca adam oldum sanır.

Dostlar unutulur, ne hal sorulur, ne hatır? 

Namuslu yaşayanlar “enayi”lerden oldu.

Parası çok, karnı toklar “eniyi”lerden oldu.', 'İnsan gibi dolaşırız, hiç utanmadan. Bu dünya kurtulmaz İslam yaşanmadan. Sokaklar dolusu eşkıya, bir o kadar sürüngen, Ender bulunur haysiy...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insan-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mü''minin Duası', 'mu-minin-duasi-taha-nur-l5575', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya Rab, gönlüm karardığı zaman.

Bir ışık gönder kalbime.

Gözüm görmez olduğu an.

Bir aydınlık ver gözlerime.

Dilim seni söylemediği zaman,

Bir nizam ver dilime,

Kâlbim seninle olmadığı an,

Bir ilham ver kâlbime.

Ellerim sana açılmadığı zaman.

Bir kuvvet ver ellerime.

Ayaklarım sana gelmediği an,

Bir yol göster ayaklarıma.

Kulaklarım duymaz olduğu zaman.

Bir ses gönder kulaklarıma,

Nefsim azıp sapıttığı an,

Bir terbiye ver nefsime.

Burnun kokunu almadığı zaman,

Bir misk gönder burnuma.

Gönlüm seni unuttuğu an,

Bir aşk ver gönlüme.', 'Ya Rab, gönlüm karardığı zaman. Bir ışık gönder kalbime. Gözüm görmez olduğu an. Bir aydınlık ver gözlerime. Dilim seni söylemediği zaman, B...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mu-minin-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-taha-nur-w3g9x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sevinç, bu neşe, bu coşku neden? 

Sanki kara toprağa girmeyecek misin? 

Ahiret günü Hak divanında,

Yaptıklarının hesabını vermeyecek misin? 

Eğleniyorsun orda, burda, yabanda.

Düşünce yok, ibret alma yok sende.

Bilmediklerin var, anlatayım gelde.

Sanki hak olan ölümü tatmayacak mısın? 

Çöllere düşsen, aç kalsan, çile çeksen,

Yine de uslanmazsın, çünkü arsızsın.

Bir tövbe eder, bin günah işlersin.

Sanki kızıl tandırda yanmayacak mısın? 

“Bak Taha Nur, uslandı artık adem”,

Desem, yine güman eder inanmazsın.

Yolun yarısını geçtin pek azı kaldı.

Sanki yarın-birgün gitmeyecek misin?', 'Bu sevinç, bu neşe, bu coşku neden?  Sanki kara toprağa girmeyecek misin?  Ahiret günü Hak divanında, Yaptıklarının hesabını vermeyecek misi...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanki-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenişler', 'seslenisler-taha-nur-1sg13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesleniş 1

Tak saçına, bu çiçekleri sen tak,

Burcu burcu kokun gelsin uzaktan.

Bak gözlerimin, ta içine bak,

Oluk oluk yaşlar aksın yanaktan.

Sesleniş 2

Hiç duymadım ki, ılık nefesini boynumda,

Kimden öğreneyim tatlım, soluk alışlarını.

Hiç uyumadım ki, açıp sıcak koynunda,

Nerden bileyim tatlım sevip sarışlarını.', 'Sesleniş 1 Tak saçına, bu çiçekleri sen tak, Burcu burcu kokun gelsin uzaktan. Bak gözlerimin, ta içine bak, Oluk oluk yaşlar aksın yanaktan...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seslenisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Pir Deli Dokunuşun', 'pir-deli-dokunusun-nurten-altinok-m6get', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '___Muammer Çelik''e__

aşka durunca deli yürek 

serçelerden daha ürkek 

ısıt sevgiyi avuçlarında 

umarsızca göğsüne yasla 

hedef olmasın bir yaban kuşuna 

sev ki, sevginde huzur bulsun 

sev ki, bakışlarında aşkı bulsun 

sev ki, sana uzattığı elinde 

avuçlarında elini bulsun 

serçe ürkekliğindeki yüreği 

deli yüreğin mabedi olsun 

bırakma uzatılan elleri, tut 

bir güvercin yüreğidir duyduğun 

gözlerine vuruyorsa atardamarı aşkın 

susuyorsa beynindeki art bakışların 

sar sarmala öp okşa, en deli tarafın 

arşa sürüklüyordur bedenini 

haberin olsun... 

.............................................................................

Sevgili Muammer Çelik’e, şiirime esinti olan

- Pir Deli Dokunuşumla Pır Diye Uçtun- 

adlı şiiri için sonsuz teşekkürler

sevgilerimle', '___Muammer Çelik''e__ aşka durunca deli yürek  serçelerden daha ürkek  ısıt sevgiyi avuçlarında  umarsızca göğsüne yasla  hedef olmasın bir y...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pir-deli-dokunusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman Asker', 'kahraman-asker-taha-nur-81dtq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En önde uçan şu kuşa bak,

Rüzgar gibi, alev gibi coşuyor.

Düşmanı tam alnından vurarak,

Vatan aşkından dağlar aşıyor.

Türk’tür soyu, Fatihlerin torunu.

Çarpışır, savaşır tüketmez soyunu,

Hadi artık topla yiğit ordunu.

Yaz düşmanın göğsüne şanlı adını.

Alnından dökülen kanlar içinde,

Hırsından ne yapacağını bilmiyor.

Yaralı, kanlı, kıpkırmızı eliyle,

Tüfeğin tetiğini çekmeye çalışıyor.

Bayrak elinde dikecek yer arıyor.

Bir kahpe kurşunla göğsünden vuruluyor.

Diktiği bayrağı son defa öperek,

Gözü bulutlarda, uzanmış yatıyor.

Sen Atandan ibret aldın.

Göğsün kabarık, alnın aktır.

Senin tek aşkın vatan aşkıdır.

Kara toprak altında yalnız mı kaldın? 

Yine sen öndesin toprak altında,

Yerin yücedir, Allah katında.

Savaştın yiğitler gibi Vatan sathında.

Sen ölmedin, yaşıyorsun millet kâlbinde.

Onlara öldü demeyin, “Şehitler ölmez”.

Onlar yanan meşaledir hiç sönmez.

“Ya ölüm, ya kalım” der, savaştan dönmez.

Onlar kırmızı bir güldür, hiç solmaz.

Ey şehit asker toprağında rahat uyu.

Seni toprakta değil, bayrakta görüyorum.

Diktiğin şu bayrak altında seni anarak.

Mukaddes ruhuna Fatihalar gönderiyorum.', 'En önde uçan şu kuşa bak, Rüzgar gibi, alev gibi coşuyor. Düşmanı tam alnından vurarak, Vatan aşkından dağlar aşıyor. Türk’tür soyu, Fatihle...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kahraman-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalınan Saat', 'calinan-saat-taha-nur-at4qz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim çaldı saatimi? 

Yaldızlarla süslenmişti.

Miras değildi.

Kumar, şans oyunundan değil,

Bileğimin hakkıydı.

Zaman “pat” diye durdu.

Görmeli,

Taştan kulelerde böceklerin,

İhtişamlı yaşamını.

Duymalı,

Soğuk gecelerde bülbülün acısını.

Kim çaldı saatimi? 

Zaman “pat” diye durdu.

Sanki boşluğa düşen ayna.

Görüyorum, duyuyorum,

Hesaba çekiyorum kendimi.

Artık yıldızlara bakıp,

Geleceği okumak yok.

Şimdiki halim, geçmişte neydim? 

Ve nasıl olacak geleceğim? 

İşte bu en mühim.

Başımın arka cephesi,

Yani beynim.

Zonk zonkluyor.

İçimi sükun sarsa iyi.

Gömleğimle göğsüm arası,

İçin için yanıyor.

Elimle kolum bende mi? 

Bir uykuyu bulsam,

Uykuda bulsam kendimi.

Herkes uykuda,

Kol saatleri, cep saatleri,

Duvar saatleri.

Nesneler, özneler yerli yerince.

Kedi kanepede “mışıl mışıl”.

Şöminenin sıcağında fino.

Bense elleri başında,

Koyu koyu düşünen biri.

Ayağa kalsam.

Sarhoş gibi.

Kim çaldı saatimi? 

Parlayan yıldızım hani? 

Durgun bakışlı, sarışın güzel,

İçim çekmiyor seni.

Daha dündü:

“Kronometresine bakan adam,

Zamanla yarışan, insanlarla.”

İlgilendirmiyor şimdi:

“Ticarette zengin, hırslı, kibar.

Roma’yı kim yaktı? 

Niçin? 

Balona binip uçmalı buradan.

Olmuyor:

“Baba eve eli boş geldi..

Vah yazık.

Serap’ın gençliği bitti.

Yavrular için hikaye anlatan anne.

Nalan hanım avluda.

Finosu kucağında.

Pudra, ruj, allık, benlik,

Çantada.

Sinek kaydı traş.

Pek yakışmış Harun Bey’e,

Nalan Hanım Harun Bey’in kolunda.

Söylemesi ayıp,

İşler epey yolunda.

Beynim,

Yani başımın arka cephesi.

Lime lime doğranmış.

Fısıldamalar,

Falsolu kahkahalar.

Borazancı başı vakitsiz ötüyor.

Hepsinden öte,

Çatlayacak gibi alnım.

Vah gençliğim,

Vaktiyle ne rahattım.

Kim çaldı saatimi? 

Pusula kimin cebinde saklı.

“İflas eden tüccar türkü söyler”.

“Yazık”.

“Dellenmemek lazım”.

“Boşa ağlamışım”

“Ata alan Üsküdar’ı geçti.”

Ben hangisiyim? 

Kapkaçcı, totocu, yankesici ağalar, beyler.

Çekinmeden söyleyin.

Para pul aşkına söyleyin...', 'Kim çaldı saatimi?  Yaldızlarla süslenmişti. Miras değildi. Kumar, şans oyunundan değil, Bileğimin hakkıydı. Zaman “pat” diye durdu. Görmeli...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/calinan-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim', 'bekledim-aydanur-basci-s2p4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elveda deyip gitme

Mahkum etme, beni bana

Şu üç günlük dünyada 

Beni yalnız bırakma

Yalnızlık beni kahreder

Sensiz yaşamak

Ölmekten de beter

İsyan etmedim, feryat etmedim

Hep seni, seni bekledim.



1997', 'Elveda deyip gitme Mahkum etme, beni bana Şu üç günlük dünyada  Beni yalnız bırakma Yalnızlık beni kahreder Sensiz yaşamak Ölmekten de beter...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekledim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderim', 'kaderim-aydanur-basci-cws5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahrediyorum kaderime

Seni benden ayırdı diye

Vefasız bir sevgiliye

Gönlümü verdi diye

Niye diye her dakika

Kendime soruyorum

Bu kahpe kaderime

Lanetler yağdırıyorum.

1997', 'Kahrediyorum kaderime Seni benden ayırdı diye Vefasız bir sevgiliye Gönlümü verdi diye Niye diye her dakika Kendime soruyorum Bu kahpe kader...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaderim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma ki-2', 'sanma-ki-2-aydanur-basci-vkbgv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonbahar gelince

Yapraklar dökülür

Rüzgar alıp götürür

Sanma ki geri gelir

Gece olunca

Hüzün çöker

Gözlerimden yaşlar akar

Sanma ki değer

Karanlık olunca

Yıldızlar; 

Dizi dizi sıralanınca

İçlerinden biri kayarsa

Sanma ki geri gelir

2001', 'Sonbahar gelince Yapraklar dökülür Rüzgar alıp götürür Sanma ki geri gelir Gece olunca Hüzün çöker Gözlerimden yaşlar akar Sanma ki değer Ka...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Başcı']::text[], 8.5, '{"poet":"Aydanur Başcı","poet_slug":"aydanur-basci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sanma-ki-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'II/Acı', 'ii-aci-ali-gencay-s3nn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'üzerime çökün karanlıklar,aşk sizden büyük bilirdim

zifirisini sevdiğim kuytular,kara sevdayı zevk bilirdim

I-

bak bana 

ben karaçalıyım

dokun! ! 

bende kalsın sancıların

geceyi ben diye giyinen kadın

haydi giyin acılarımı 

dikenlerim kanatır damarlarını

kanın olsun canım

karanlıklar! ! 

siz ağlayın

II-

yaşam! ! 

zar oyununu

iyi tut atacağını

sen şeş 

ben beşindeyim

açılır kapılar

sen şah 

ben matımdayım

III-

gitme vakti geceye

öpme(sen)  dudaklarımdan

alnında duam ıslaklığım

sen! ! 

yılların hesabını tutan

ben! ! 

bir kaç saate yenik düşenim

biliyorsan hesabını

tut ellerimden 

yıllara meydan okuyan

yüreğim! ! 

gündüzüm sırtlanların

gece koynuma düşensin

okunu sapla yüreğime

zehir tüm bedenimde

kıvranıyorum

sen! ! 

gidişlerimde gelmelerim

kaldır eteklerini

kanıma değmemelisin

IIII-

tabanlarım kanıyor 

karalarda kan kırmızı mı? 

sessiz çığlıklarım 

kulaklarda acı duyulur mu?', 'üzerime çökün karanlıklar,aşk sizden büyük bilirdim zifirisini sevdiğim kuytular,kara sevdayı zevk bilirdim I- bak bana  ben karaçalıyım dok...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ii-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Dalıp Gider misin', 'sen-de-dalip-gider-misin-metin-kose-fs8a2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arada,  sen de dalıp gider misin

Ruhun gezer mi başka diyarlarda

Dolaşır mısın bulutların üstünde

Mesela akşam rüzgarıyla birlikte

Şöyle bir çıkar mısın ufuklara

O’nu görür müsün Kızkulesi’nde 

Bu rüyadan uyanmasam der misin

Arada,  sen de dalıp gider misin

      Ankara

(dalıp gittiğim bir zaman) 

19.08.2004', 'Arada,  sen de dalıp gider misin Ruhun gezer mi başka diyarlarda Dolaşır mısın bulutların üstünde Mesela akşam rüzgarıyla birlikte Şöyle bir...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-de-dalip-gider-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Gelsin', 'senden-gelsin-orhan-tuncay-1ea71', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şeyler ver bana yalnızlığımla paylaşayım

Acımtırak boşluğumu onunla tatlandırayım

Bir tek sana ait olmalı bana vereceklerin

Beni, yalnızlığım ve bir parçanla tamamlayayım.

Vereceğin, umut, neşe ya da sevinç olsun

Ruhumun derin karanlığını bu ışık doldursun

Yalnız zindanlarımda parıldasın gülen yüzün

Yalnızlık ürpertisi böylece sararıp solsun.

Olumlu duygular  artık sende de yitikse

Halin benim gibi perişansa, bitikse

Acılarını ver o zaman, ver bana hüzünlerini

Yalnızlığım daha çok acısın onlarla birlikte

Bir tek senden gelsin isterim gelecek olan neyse

Istırapsa, umutsa, umarsızlık, ya da neşeyse

Yalnızlığım ancak böyle huzura kavuşacak

Senden gelsin yeter ki, gelecek olan ölüm olsa bile.', 'Bir şeyler ver bana yalnızlığımla paylaşayım Acımtırak boşluğumu onunla tatlandırayım Bir tek sana ait olmalı bana vereceklerin Beni, yalnız...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgim Ondan Büyük', 'benim-sevgim-ondan-buyuk-i-smet-barlioglu-gp1gy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Solgun, ölgün fakat tatlı

Bir denizdir şatafatlı,

Sularında güneş denen

Altın yüklü gemi battı.

Bakışları kapkaradır,

Tek bir derde bin devadır,

Aşıkıyım ben yıllardır,

Canıma çok canlar kattı.

Ruhum sanki bir üfürük,

Yorgun argın ve körkütük,

Benim sevgim ondan büyük,

Çünkü nice elem tattı.

Gönlüm sanki deli, sarhoş,

Aklım, fikrim tümüyle boş,

Aşkı beni etti bir hoş,

Vahalardan çöle attı.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 77-78/100)', 'Solgun, ölgün fakat tatlı Bir denizdir şatafatlı, Sularında güneş denen Altın yüklü gemi battı. Bakışları kapkaradır, Tek bir derde bin deva...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-sevgim-ondan-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil ve Ben...', 'kandil-ve-ben-i-brahim-ethem-bingul-gnoql', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün aydınlık, gece ışık saçıyor

Kandillerden ışıl ışıl caddeler

Aydınlıklar gönüllerden taşıyor

Aydın yüzler parıldayan bir fener...

Kutluyorum kandilini her dostun

Adım adım sultan aya giderken

Aşkla yanan kalpler kandillere fon,

Yana yana yangınlara giderken...

Ben kandilde yâre selam yollarım

İstiyorum,yâri sarsın kollarım

Yârdan gelen o mektupla yoldayım

İçimde sevdalar yanıp tüterken

Kandil olup yana yana biterken...', 'Gün aydınlık, gece ışık saçıyor Kandillerden ışıl ışıl caddeler Aydınlıklar gönüllerden taşıyor Aydın yüzler parıldayan bir fener... Kutluyo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kandil-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekçilik Ediyorum Bir Eski Hatıraya', 'bekcilik-ediyorum-bir-eski-hatiraya-i-smet-barlioglu-jbabg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimi demirden parmaklıklar yaparak

Bekçilik ediyorum bir eski hatıraya.

O eşsiz hayalleri başüstünde tutarak

Bekçilik ediyorum bir eski hatıraya.

Uzun yıllardan beri duyamadım sesini,

Gerçek yerine koydum silikleşen resmini,

Elbette ki bu hasret bir gün tüketir beni,

Bekçilik ediyorum bir eski hatıraya.

Yağmur yağdığı zaman, bil ki; gözyaşlarımdır,

Sürüklenen çakıllar hep sabırtaşlarımdır,

Geçenler yıllar değil, gemcecik yaşlarımdır,

Bekçilik ediyorum bir eski hatıraya.

Esen rüzgarı dinle; konuşalım seninle,

Verdiğim selamları getirecek yeminle,

Sen bayramlar yaparken hergün kendi kendinle

Bekçilik ediyorum bir eski hatıraya.

Sedef gibi bembeyaz ellerini özledim,

Yıllarca kıyılarda her gün seni gözledim,

O eskimiş günleri süsledim, güzelledim,

Bekçilik ediyorum bir eski hatıraya.

Ben elem içindeyim başkaları gülerken,

Ellerim dualrda her gün şafak sökerken,

Karanlık gecelerde saçlarım ağarırken

Bekçilik ediyorum bir eski hatıraya.

Gelmesin bu şafaklar böyle erken sökerek,

Belimi eskisinden daha fazla bükerek,

Hayalinin önünde her gece diz çökerek

Bekçilik ediyorum bir eski hatıraya.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 79-80/100)', 'Yüreğimi demirden parmaklıklar yaparak Bekçilik ediyorum bir eski hatıraya. O eşsiz hayalleri başüstünde tutarak Bekçilik ediyorum bir eski ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bekcilik-ediyorum-bir-eski-hatiraya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Gözyaşımı Katsam Yaşına', 'kendi-gozyasimi-katsam-yasina-i-smet-barlioglu-8vzyl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızlar toplasam kalbur dolusu

Engin gökyüzünde kurarak pusu.

Çalarken sevdanın eşref borusu

Yağmur gibi serpsem senin başına.

Koparsam gülleri körpe dallardan,

Şırıltılar katsam akarsulardan,

Güzellik derlesem renkli pullardan,

Getirip her gece sersem düşüne.

Bağlardan gönlüne huzur derlesem,

Sulardan çağıltı, kumlardan desen,

En güzel şeyleri ikram eylesem,

Her türlü lezzeti katsam aşına.

Sen körpe adımlar atsan kalbimde,

Adım seslerini izlesem ben de,

Öylece yaşarken ruhun tenimde,

Yorgun kervan gibi düşsem peşine.

Yamaçlar ardından güneş doğarken,

Bir seher vaktinde yağmur yağarken,

Sen sevinç içinde sessiz ağlarken

Kendi gözyaşımı katsam yaşına.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 81-82/100)', 'Yıldızlar toplasam kalbur dolusu Engin gökyüzünde kurarak pusu. Çalarken sevdanın eşref borusu Yağmur gibi serpsem senin başına. Koparsam gü...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kendi-gozyasimi-katsam-yasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sanki Menekşesin', 'sen-sanki-meneksesin-i-smet-barlioglu-c3kfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim seni delice,

Hem de güzdüz ve gece,

Söyleyeyim gizlice

Aşkımı kulağına.

Sen sanki menekşesin,

Mutluluksun, neş ''esin,

Göz olsun ilişmesin

Mümkün mü, yaprağına? 

Yanar yanar tüterim,

Erir erir biterim,

Ömür feda ederim

Gül gibi dudağına.

Sana herşey yakışır,

Gören gözler kamaşır,

Elin değse tutuşur

Kalbimin çerağına.

Hikmet BARLIOĞLU (1933-2003)  ''nun

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 83-84/100)', 'Sevdim seni delice, Hem de güzdüz ve gece, Söyleyeyim gizlice Aşkımı kulağına. Sen sanki menekşesin, Mutluluksun, neş ''esin, Göz olsun ilişm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-sanki-meneksesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çileye Çekildim Senin Uğruna', 'cileye-cekildim-senin-ugruna-i-smet-barlioglu-7mqu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanma ki bu çilem biter tükenir,

Zaten tükense de yenisi gelir,

Çile çeken gönül aşkı öğrenir,

Çileye çekildim senin uğrunda.

Koskoca dünyamda yalnız sen varsın,

Sen de yüreğimle oyun oynarsın,

Ben yanıp giderim, sense bakarsın,

Çileye çekildim senin uğrunda.

Körpecik bir gülsün, dikenlerin var,

Yerine çileyi çekenlerin var,

Kelebek gibisin; desenlerin var,

Çileye çekildim senin uğrunda.

Sevda tek taraflı olunca yüce,

Bunu ki öğrendim artık iyice,

Sana yanıyorum gündüz ve gece,

Çileye çekildim senin uğrunda.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 85-86/100)', 'Sanma ki bu çilem biter tükenir, Zaten tükense de yenisi gelir, Çile çeken gönül aşkı öğrenir, Çileye çekildim senin uğrunda. Koskoca dünyam...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cileye-cekildim-senin-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-naime-erlacin-l1h4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rüzgar çanları yağmalardı yüreğimi

yalnızdık ışık öncesi 

yalnız evvelinde sözün

kasırganın gözünde yalnız 

tek başına kanardık 

sonsuz bekçisi bozkır türküleri ey! 

taçlanır toyon’um* adak ağaçlarınızda

eylemimiz safi dil 

safi ağıt çaputlarınızda 

uyanır iç dikenler...her biri bir şimşek

çarpar adamı

im bırakır gök yakut berraklığında 

cezbeye tutuluruz 

kızar suyumuz 

alnımızda bir mavzer

güneş durmaz patlar

güneş bilir 

güneş isyankar

acılı bozkır türküleri ey! 

tarihin tütsülediği yankıda dirilirsiniz

secdeye gelir susarız önünüzde

koynumuza gömülür med cezirleriniz

cürmümüz sonsuza bekçilik

bağışlayıcıdır lakin gök mekan

beraat’a dönüşür cezalar

ister üşüsün kainat... buza kessin yer 

balagan kapısına astım mı düşleri korkmam

en fazla karıncada biter soğuğun hükmü

omzumda aşina bir sıcaklık...sevecen 

billur dokuzlar doğar içimde 

sırça güneşe sunulur evrenin kutsal ışığı..tutkulu 

mekanlar büyütür gün... varsıllaşır cümle alem

kızıl gelincikler iner mistik nağmeye 

kızıllığına etimin

dudağımda bir damla kan 

bir damla daha aşkın rahminden şiire akan

güneş doğar

güneş yine doğar 

güneşe giderim ben…

……….

(*)               Toyon: Boy reisi

(**)              Balagan: Saha’lara (Yakutlar)     özgü kütük evi…

(19 Ağustos 2004)', 'rüzgar çanları yağmalardı yüreğimi yalnızdık ışık öncesi  yalnız evvelinde sözün kasırganın gözünde yalnız  tek başına kanardık  sonsuz bekç...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gunes-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümde İlk Defa Beraber Olduk', 'omrumde-i-lk-defa-beraber-olduk-i-smet-barlioglu-p8l6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüm yine pembe fayansta,

Sana hayran oldum herbir nüansta,

Herkesten üstünüm bugünkü şansta; 

Ömrümde ilk defa beraber olduk.

Bir ara ırmakta gülümsüyordun,

Gül olmuş güneşi özümsüyordun,

Arıydın, gülleri küçümsüyordun,

Ömrümde ilk defa beraber olduk.

Dem çeken kumruydun körpe dallarda,

Yem yiyen serçeydin toprak yollarda,

Bir mor menekşeydin ıssız kırlarda,

Ömrümde ilk defa beraber olduk.

Yağmurdun; hem ılık, hem de incecik,

Yeşil tomurcuktun; taze, körpecik,

Bazan bir ovaydın, bazan tepecik,

Ömrümde ilk defa beraber olduk.

Elimde kadehsin, kadehte şarap,

Hem kesin gerçeksin hem de bir serap,

Bir yerde günahsın, bir yerde sevap,

Ömrümde ilk defa beraber olduk.

Her neye aksetsen sanki ondasın,

Binbir renk içinde, binbir tondasın,

Bazan uyuyorsun ve odamdasın,

Ömrümde ilk defa beraber olduk.

Bazan sanıyorum yüreğim sensin,

Bazan sanıyorum sen değil, bensin,

Sen bende bedensin, bende yüreksin,

Ömrümde ilk defa beraber olduk.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 87-88/100)', 'Seni gördüm yine pembe fayansta, Sana hayran oldum herbir nüansta, Herkesten üstünüm bugünkü şansta;  Ömrümde ilk defa beraber olduk. Bir ar...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/omrumde-ilk-defa-beraber-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Geçirecek Günüm Kalmadı', 'bosa-gecirecek-gunum-kalmadi-i-smet-barlioglu-00h8j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koyma yüreğimi böyle acıda,

Benim yaşanacak ömrüm kalmadı.

Bedenim çilede, ruhum sancıda,

Boşa geçirecek günüm kalmadı

Akşamlar dert olup iner üstüme,

Ürkerek bakarım her gün ölüme,

İnanamaz oldum güleceğime,

Menzile ulaşan yolum kalmadı.

Mahşerler içinde yapayalnızım,

Pınarlar önünde yaman susuzum,

Bitkinim, yorgunum, çok uykusuzum,

El atıp tutacak dalım kalmadı.

Sevdaya düştüm de sanki ne buldum,

Elemden eleme koşup yoruldum,

Her gün alevlendim, her gün kavruldum,

Artık dayanacak halim kalmadı.

Kalbim emanette, ruhum rehinde,

Bir büyük sevdadan ne var elimde? 

Benimle ölür mü acep sevgim de? 

Sorup öğrebnecek dilim kalmadı.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 89-90/100)', 'Koyma yüreğimi böyle acıda, Benim yaşanacak ömrüm kalmadı. Bedenim çilede, ruhum sancıda, Boşa geçirecek günüm kalmadı Akşamlar dert olup in...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bosa-gecirecek-gunum-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-mustafa-toga-jqd87', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz dediler.

Adana’yı yaz dediler,

Çok sıcaktı yaz dediler.

Barajı gez, Karşıyaka, Kanal''ı

Dolaş dolaş yaz dediler.

Denize koşanlar, gölgeye sığınanlar 

Sırtından şapır şapır ter akanlar

Bir günde üç gömlek değiştirenler

Ekonomik sorunla boğuşanlar

Açlık, Íşsizlik, ekmek kavgasını

Konuş konuş yaz dediler.

Yaz dediler.

Beyaz altın bölgesini

Çiftçilerin gür sesini

Fabrikanın işçisini

Dinle dinle yaz dediler.

Haziran, Temmuz, Ağustos

34 derece sıcak görülen

Sıtmadan insan öldüren

Fakirin belin kırdıran

Tarlaları yakıp kavuran

Íşte buna yaz dediler.

Yaz dediler, yaz dediler

Çukurova''yı yaz dediler

Yazı anlat, yaz dediler.

www.togamedya.tr.gg

M.Toga / Ağustos 1976

GÜNÜN SÖZÜ: Mart kapıdan baktırır, kazma kürek yaktırır.', 'Yaz dediler. Adana’yı yaz dediler, Çok sıcaktı yaz dediler. Barajı gez, Karşıyaka, Kanal''ı Dolaş dolaş yaz dediler. Denize koşanlar, gölgeye...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yaz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-tevfik-mengulluoglu-0w4nv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Edemediğim bir yemin gibisin

Her gece dudaklarımın ucuna

Düşüyor kelimeler,

Söyleyecek gibi oluyorum

Adını...

Geceyi sensiz salmışsın yine 

Dayanmış kapıma

Kim bilir hangi sabahın 

Kollarında uyuya kalmışsın

Yalnızlığımın bahanesi mi

Yoksa yokluğun? ! 

Her sabah üstümü örttüğün

O düşlerin nerede? 

Bir çocuğun

Kimsesizliği oluyorum,ve

Yaşadıkça anlıyorum artık

Bir mıknatısın parçaları gibi,

Birleşiyor sözcükler

Seviyorum Seni...', 'Edemediğim bir yemin gibisin Her gece dudaklarımın ucuna Düşüyor kelimeler, Söyleyecek gibi oluyorum Adını... Geceyi sensiz salmışsın yine  ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kelimeler-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayazda Yüreğin', 'ayazda-yuregin-nihat-tasdemir-il1lz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savrulmuş o körpe yüreğin ayazda

	Tutunacak bir dal aramış; 

	Nafile bulamamış.

	Ve ilişmiş hain bir dala; 

                Ömrünün baharında...

	Ve o dalda harmanlanmış yüreğin

	Ki  yüreğin iki kısım iki ayrı dünya...

 	

	Bir kısım ayazda kalmış; 

	Yağmur değmiş, kar yemiş, rüzgar öpmüş.

	Palazlanmış...

	Bir kısım gölgede; güneş bile görmemiş.

	Hani dokunsan ağlayacak,

                Hani dokunsan kırılacak,

                Hala körpe, o masum haliyle…', 'Savrulmuş o körpe yüreğin ayazda 	Tutunacak bir dal aramış;  	Nafile bulamamış. 	Ve ilişmiş hain bir dala;                  Ömrünün baharınd...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayazda-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemde Aşk * 2 / 2', 'ulkemde-ask-2-2-sair-asivan-0gre0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Marifettir ya; 

Elini tuttuğun,

gözüne baktığın,

öptüğün her kadın.

Anlat gururla,

Çarpıp ikiyle...

Utançtır ya; 

Elini tuttuğun,

gözüne baktığın,

öptüğün her erkek.

Anlat utanarak

Bölüp İkiyle...', 'Marifettir ya;  Elini tuttuğun, gözüne baktığın, öptüğün her kadın. Anlat gururla, Çarpıp ikiyle... Utançtır ya;  Elini tuttuğun, gözüne bak...', ARRAY['Türk Edebiyatı','Şiir','Şair Asivan']::text[], 8.5, '{"poet":"Şair Asivan","poet_slug":"sair-asivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ulkemde-ask-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırladım', 'seni-hatirladim-sirma-mersin-7ab45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğazımda düğümlenirken

Hıçkırıklar...

Gözlerimden dökülen damlalar

Yüreğimi ıslatırken...

Uykusuz geçen gecelerin hesabına

Karaladığım dizelerde

Yalnız seni yaşadım

Seni düşündüm...

Siyah beyaz fotoğraflardan

Kırık dökük an-ılardan

Arda kalan

Koskoca yalnızlığıma

Sensizliği koydum...

Sonu olmayan bi başlangıca

Adım attığımda

Ayrılığın hüzün kokusu dağıldı

Üzerime...

İhtimallerden sonra

Sancılı sensizliğe alışamadığımı

Anladım.

Bir gün; 

Geri geldiğinde / gelirsen...

Yarım kalmış mutluluğun resmini çizeceğim,gözlerine...

19.08.04

                  ''Bir şarkının arkasından gelenler...''', 'Boğazımda düğümlenirken Hıçkırıklar... Gözlerimden dökülen damlalar Yüreğimi ıslatırken... Uykusuz geçen gecelerin hesabına Karaladığım dize...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-hatirladim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Şok', 'sok-nurten-altinok-86p26', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ses

Ah o ses

Neydi o ses! 

sesler tenle birleşince

eyvah! 

buz kesti gözlerdeki nur

keşkeler başladı

kahreden pişmanlıklar

büyü kayboldu

kaskatı bir rüzgar acımasız

tokat gibi indi hayallere

ağıtlar yakıldı yıkılmışlığa

resimler ağladı düşlerde yeşeren

sesler ağladı

geceyi bölen dürtü ağladı

umutlar öksüz 

şiirler yetim

sesler tenle birleşince 

eyvah!', 'Bir ses Ah o ses Neydi o ses!  sesler tenle birleşince eyvah!  buz kesti gözlerdeki nur keşkeler başladı kahreden pişmanlıklar büyü kayboldu...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sok-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Diyor ki', 'seytan-diyor-ki-nurten-altinok-ne4mp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi bir cevap ver 

Yanılt bendeki beni

Çözülsün kördüğümüm

Bu kuşku 

Bu şüphe

Bu bekleyiş 

Her gün öldüğüm

Hadi bir cevap ver

Yanılt içimdeki sesi

Denizlere atacağım

Kör kuyulara

Zincirlere vuracağım

Bu altıncı hissimi

Ne taşacak zamandayım / asi

Ne delisindeyim suyun 

Susuyorum

           Şeytan diyor ki...', 'Hadi bir cevap ver  Yanılt bendeki beni Çözülsün kördüğümüm Bu kuşku  Bu şüphe Bu bekleyiş  Her gün öldüğüm Hadi bir cevap ver Yanılt içimde...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seytan-diyor-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum Ya Muhammed', 'seni-ozluyorum-ya-muhammed-necmiye-sarpkaya-1da2c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni görüyorum 

Düşen bir çiy damlasında 

Rüzgarların yelkenlerinde 

Bulutların kanatlarında 

Kuşların çığlıklarında 

Seni arıyorum 

Kozanın kelebeğinde 

Narların denelerinde 

Kırlangıcın damında 

Martının kıyılarında 

Seni özlüyorum 

Billur yağmur damlalarında 

Bedevilerin çöllerinde 

Kaptanların yakamozunda

Kalbimde gönlümde buluyorum daima seni 

Ya Muhammed Mustafa (S.a.v..) 



Necmiye Sarpkaya', 'Seni görüyorum  Düşen bir çiy damlasında  Rüzgarların yelkenlerinde  Bulutların kanatlarında  Kuşların çığlıklarında  Seni arıyorum  Kozanın...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-ozluyorum-ya-muhammed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Aşkın Suyu', 'askin-suyu-nurten-altinok-nwh06', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece uyuyamazsın

Beyninde kemirgen olacağım, takıntı

Karabasan dudaklarında fırtına

Belinde zona doğurgan sancılı

Bu gece uyuyamazsın

Azadet ellerini paslı düşlerden

Coğrafyasında bütün aşklar sınırsız

Uzanıversin suyun suyuma  gizliden

Kuşatmasındaysak bir aşkın, tutkulu

Islık sesine gizlenmişsek şiirin, yasaklı

Esaret kemerine dolanmışsa sevgimiz

Gecenin mayası aşkın suyu olmalı 

Bu gece uyuyamazsın 

Koynunda sevdiğin su olmalı...', 'Bu gece uyuyamazsın Beyninde kemirgen olacağım, takıntı Karabasan dudaklarında fırtına Belinde zona doğurgan sancılı Bu gece uyuyamazsın Aza...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-suyu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsküs azığı', 'kuskus-azigi-gencay-coskun-szf53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıkmak lazım gelirdi 

Eskiye yeniye dair ne varsa

Ya da düşürülmek bulutlardan 

Yerin yedi kat dibine 

Yumruklarımda sıktığım 

Tek sıcaklığım kendi kanımdı

Gözlerimden fışkıran 

Dağları eritecek şimşeklerimdi

Eşek kadar olmuştu yalnızlığım 

Hala tozar dururdu sehpalarda 

Mor salkımlı üzümler vardı 

Uzak diyarlarda asmalarda

Huzur neşterin ucu gibi keskin yollarda

Felaketler lokma niyetine 

Küsküs azığı 

Şafağınla midemdeydi 

İki arada bir derede yaşam olmazdı 

Ya kalacaksın 

Ya gideceksin 

Ortadaki ömür 

Hep gariban 

Hep sahipsiz 

Hiç kimsesiz kalırdı 

Tahtaların yan konulmadan üstüne

Küsmeden çıkmak lazımdı 

Bu içlerin en dış kapısından 

Düşsem de bir yerlerden 

Gerçek olduğumu bir ben bilirim', 'Yıkmak lazım gelirdi  Eskiye yeniye dair ne varsa Ya da düşürülmek bulutlardan  Yerin yedi kat dibine  Yumruklarımda sıktığım  Tek sıcaklığı...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kuskus-azigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe!', 'sobe-cigdem-bir-genc-vjenk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oyun bitti...

Yağmur akıttı  makyajlarını yüzlerin

Masken düştü

Sobe! 

saklanma sırası bende....

Yum gözlerini

Hadi say

Sonsuza dek sürsün.... 

Bir

İki

Üç.

Dört............................................', 'Oyun bitti... Yağmur akıttı  makyajlarını yüzlerin Masken düştü Sobe!  saklanma sırası bende.... Yum gözlerini Hadi say Sonsuza dek sürsün.....', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sobe-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ve Hasret', 'umut-ve-hasret-necmiye-sarpkaya-hnd9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut ve Hasret 



Umudun taze kokusunu duyabilmiş

Yıldızlar ellerde ay başlar üzerinde 

Hasret  yerli yerinde 

Hüzünler gözyaşları çoktan dinmiş 

Kurak çorak topraklara dönmüş

Özlemler kara defterlerde gizlinmiş

Hiçbir acı  ebediyen sürmezmiş

Umut ve hasret hasret ve umut 

Güllerin bülbüllerinin ötme vakti de geçmiş 

Yürekler yeniden sevdiği ile bütünleşmiş 

Sevgi dolu  mutlu  gönüller

Umut dalından taze mevye koparmaya 

Haydi  taze meyve koparmaya

Necmiye Sarpkaya', 'Umut ve Hasret  Umudun taze kokusunu duyabilmiş Yıldızlar ellerde ay başlar üzerinde  Hasret  yerli yerinde  Hüzünler gözyaşları çoktan dinm...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-ve-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlemek O Senfoniyi', 'dinlemek-o-senfoniyi-zeki-ergin-knz93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ucundan 

yakalayabilmek

hayatı

sarılabilmek mi zor

sevgiliye sarılırcasına

sarılmak 

yıldızlara uzanıp

ve dokunmak 

dinlemek o senfoniyi

yüreğimizle bir hoş

bamtelimize bir dokunduğunda 

ayılır  içimizdeki sarhoş

_ezine 19ağus04

_dağlara ver sırtını yt.haz09', 'ucundan  yakalayabilmek hayatı sarılabilmek mi zor sevgiliye sarılırcasına sarılmak  yıldızlara uzanıp ve dokunmak  dinlemek o senfoniyi yür...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dinlemek-o-senfoniyi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Niye Varım', 'ben-niye-varim-birsen-i-brahimhakkioglu-i8njq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sordun mu? 

Sordun mu hiç ben niye varım? 

Yaşadın yıllar boyu

Okullar bitirdin, kitaplar devirdin

Bazen sevdin, bazen de sevildin

Mutluluk istedin bazen; elle tutulur olmasa da

Bazen güldürdün, bazen ağlattın

Bazen de düşündürdün kıvrak zekanla

Ama sordun mu? 

Sordun mu hiç? 

Ben niye varım? 

Ağaçların dallarını süsleyen yaprakların

Sonbaharın gelişiyle; dallarından düştüğünü gördüğünde

Güzeliyle,çirkiniyle,zenginiyle,fakiriyle

Bir çocuk doğarken gözlerini açtığında hayata

Bir başkasının ansızın ölümüyle

Gözlerini yumduğu şu yaşamda

Sordun mu? 

Sordun mu hiç? 

Ben niye varım? 

Bir evde düğün dernek varken

İki yaşam birleşirken

Yükselen kahkaha seslerini duyduğunda

Bir diğerinin evinde yasa bürünmüş 

Ağıtlar yakılmakta,dualar okunmakta olduğu bir zamanda

Sordun mu? 

Sordun mu hiç? 

Ben niye varım? 

Bir hikmete bedel öderken

Kimi zaman isyan edesin gelirken

Suskunluğu kendine kar sayıp

Sabretmeyi öğrenirken

Sordun mu? 

Sordun mu hiç? 

Ben niye varım? 

Çocukken küçük şeylerden mutlu olur insan

Büyüdükçe doyumsuzlaşan nefsini

Dizginlemeye çalıştığın her nefeste

Verdiğin onca emek,mücadelede

Sordun mu hiç? 

Ben niye varım? 

On bir ayın sultanı geldiğinde

Sahurdan sonra aç bıraktığın mideni

İftarda donattığın yemeklerin lezzetine varırken

Allah''ın verdiği nimetlere el açıp şükrederken

Bir diğeri iftar çadırında sırasını beklerken

Bir sıcak çorbayı içmeyi hayal ederken

Sordun mu hiç? 

Ben niye varım? 

Dondurucu bir kış soğuğunda 

Sıcak evinde lapa lapa yağan kar tanelerini seyrederken

Dışarıda soğuktan üşümüş bir fakiri

Düşünüp yüreğin sızlarken

Hayatın meşakkatli yollarından geçerken

Sordun mu hiç? 

Ben niye varım?', 'Sordun mu?  Sordun mu hiç ben niye varım?  Yaşadın yıllar boyu Okullar bitirdin, kitaplar devirdin Bazen sevdin, bazen de sevildin Mutluluk ...', ARRAY['Türk Edebiyatı','Şiir','Birsen İbrahimhakkıoğlu']::text[], 8.5, '{"poet":"Birsen İbrahimhakkıoğlu","poet_slug":"birsen-i-brahimhakkioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ben-niye-varim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Düşler', 'surgun-dusler-hatko-halil-ulutasli-gyay6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sürgün düşünür,

düşler yaratır

gece yarılanda.

Sürgün düşlerini

kucaklar,

koklar,

okşar...

Düşler, yavrusudur

sürgünün.

Büyütür,

ninni söyler uyutur.

yedirir, içirir.

Masallar anlatır,

konuşmayı öğretir.

Kanat çırpar düşler

uçmayı öğrenir...

Sürgün

uğurlar düşlerini

sonsuzluğa...

Ve

her gündüz,

sonsuzluktan parıltı

gelir...

Sürgün hazırlanır

geceye.

Ve

sürgün düşünür,

düşler yaratır,

gece yarılarında...

Sürgün düşsüz,

geceler sürgünsüz

yaşayamaz...

Ve

sürgün,

ölümüne özler

gece yarısı

düşlerini...', 'Sürgün düşünür, düşler yaratır gece yarılanda. Sürgün düşlerini kucaklar, koklar, okşar... Düşler, yavrusudur sürgünün. Büyütür, ninni söyle...', ARRAY['Türk Edebiyatı','Şiir','Hatko Halil Ulutaşlı']::text[], 8.5, '{"poet":"Hatko Halil Ulutaşlı","poet_slug":"hatko-halil-ulutasli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/surgun-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Cihandayım Ne Bendeyim', 'ne-cihandayim-ne-bendeyim-tulay-eker-9dvlt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömür denilen rüzgarın dolaştığı yerdeyim

Kavrulur can fezam bir garip mahşerdeyim

Seni aramam için mi attın yaban ellerdeyim

Zikreyle nerdesin yüreğimle secde etmekteyim

Bilmem hangi devranda hangi seherdeyim

Nur''unla bir senin gölgende ve derdindeyim

Kaldır üstümden bulutları mecnun gibi gezmekteyim

Bir yol ihsan et Allah''ım etrafında dönmekteyim

Ne cihandayım ne bendeyim söyle nerdeyim

Ne sevda ile ne de alem ile ziyadeyim.

^^Sana açmayan eli,Sana yönelmeyen yüreği,Seni anmayan dili,Seni benden uzaklaştıran herşeyi....Benden ırak kıl...^huzur çanağından bal sun^ Yarabbi..^^

Dizelerime ses olan huzurun sesine eyvallah dedim yürekten....,Regaip kandiliniz mübarek,hayırlara vesile olsun...', 'Ömür denilen rüzgarın dolaştığı yerdeyim Kavrulur can fezam bir garip mahşerdeyim Seni aramam için mi attın yaban ellerdeyim Zikreyle nerdes...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-cihandayim-ne-bendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorlar', 'bekliyorlar-mehmet-isikoglu-5y5pn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Körpecik fidanlar eller elinde 

Düşünüyor önce onlar dilinde

Birakmak doğru mu kendi halinde? 

Yok mu gerilecek bir kol onlara? 

Yok dilinde duygu  ne kadar feci 

Beyin parça  parça bilmiyor neyci 

Olur mu risk etmek bu kadar genci? 

Yok mu önerecek bir hal onlara? 

Asimile önde  kocaman öcü

Ne kadar dayanır gençliğin gücü? 

Kim olacak darda kalana öncü? 

Yok mu gösterecek bir yol onlara? 

Nedir uyuşukluk nedir bu gaflet? 

Uygun mu yarına böyle ihanet? 

Gurbette tazeler kime emanet? 

Yok mu bindirecek bir dal onlara? 

Gemi kurtarılsın yoksa batacak! 

Gül gibi gençleri gurbet yutacak

Kayboluyor nesil kim kurtaracak? 

Yok mu gönderecek bir sal onlara? 

Almanya/ Köln', 'Körpecik fidanlar eller elinde  Düşünüyor önce onlar dilinde Birakmak doğru mu kendi halinde?  Yok mu gerilecek bir kol onlara?  Yok dilinde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekliyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağam, Nerden Aşar Yolu Yaylanın?', 'agam-nerden-asar-yolu-yaylanin-nurettin-ozdemir-14nb3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Bu akşam dadaşlar bar oynadı gözbebeklerimizde.

Bu akşam seni bir daha duyduk Erzurum şehri.

Bir daha doldurduk göğsümüze

Uzak hatıralar gibi.

Bu akşam kuvvet oldun dizlerimizde.

Bu akşam ışık oldun, renk oldun, ses oldun.

Bu akşam yeniden yarattın kalbimizi.

Yeniden kaderimiz yazıldı Kop Dağı''na,

Dumlu''ya, Göktepe''ye, Palandöken''e...

Yeniden asker olduk, top olduk, tüfenk olduk.

Yeniden bağrına döndük yayla gecelerinin.

Yeniden çekildik hudut boylarına bayrak gibi.

Dalgalandık. Namımız söylendi pervasız.

Yeniden sahibi olduk bu yurdun; 

Atsız, arabasız.

II

Bir yayla gecesinde başladı ilk aşkımız,

Toprağın bağrında çatlayan tohumlar gibi.

Bir yayla gecesinde yüreklerimiz geldi avucumuza.

Bir yayla gecesinde gönül verdik, can verdik.

Bir yayla gecesinde sevdik, yaşadık ve unttuk

Nasibi.

Şimdi sen avuçlarımızdasın.

Nabzımız seni alkışlıyor durmadan.

Seni yaşıyoruz gecenin her saatinde,

Bir ömrü yaşar gibi.

III

Senin gözbebeklerinde yaylamın rengi vardır.

Senin gözlerinde yaylamın geceleri

Korkunç uçurumlar gibi karanlık ve derindir.

Korkunç uçurumlar gibi kendi kendine,

Bir türkü tutturmuşturPalandöken''den.

Bir türkü tutturmuştur; hasret kokar,

Kekik kokar, yayla kokar, yar kokar.

 Akşam olur, gölgelenir kayalar.

Akşam olur, gözlerinin rengi vurur dağlara.

Akşam olur; ne yol kalır, ne iz kalır. ne geçit.', 'I Bu akşam dadaşlar bar oynadı gözbebeklerimizde. Bu akşam seni bir daha duyduk Erzurum şehri. Bir daha doldurduk göğsümüze Uzak hatıralar g...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/agam-nerden-asar-yolu-yaylanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece, Aşk ve Ben', 'gece-ask-ve-ben-ferit-agca-ysuj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben her gece; 

Gururum bin gurur ekledim,

Seni aramayayım diye.

Yalnızlığıma bin yalnızlık kattım,

Hasretinin acısını duymayayım diye.

Gözlerime bin kelepçe vurdum,

Gözlerinin esaretinden kartulayım diye.

Her gece ben...', 'Ben her gece;  Gururum bin gurur ekledim, Seni aramayayım diye. Yalnızlığıma bin yalnızlık kattım, Hasretinin acısını duymayayım diye. Gözle...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-ask-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destanlar İçinde Aziziye', 'destanlar-i-cinde-aziziye-nurettin-ozdemir-6x25m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam yaşamak kadar güzeldi her şey.

Bu akşam gök mavi, yıldızlar uçuşuyordu.

Derinden nefes alıyordu toprak,

Vatan konuşuyordu.

Vatan konuşuyordu tabyalardan; 

Sıra dağlar dile geliyordu sırasıyla,

Şahlanmış bir zafer türküsü gibi,

Destanlar içinde Aziziye.

Destanlar içinde Aziziye, Kiremitli, Erzurum.

Destanlar içinde ve uzak bir rüyada yaşar gibi

Şevkle yaşıyordu en büyük ve en güzel gerçeği.

Şehit ruhlarıyla baş başa erlerimiz.

Bir avuç toprak üstünde konuşuyordu,

Bu akşam mavzerlerimiz.

Bu akşam mavzerlerimiz, dişimiz, tırnağımız...

Bu akşam ''Tekbir'' sesleri ve cümle varlığımız; 

Yaşlımız, delikanlımız, kızımız, kısrağımız,

Vatan uğrunda el-pençe divan, hazır-tetik! 

Bu akşam taşıyla toprağıyla konuşan

Bir kahraman dinledik.', 'Bu akşam yaşamak kadar güzeldi her şey. Bu akşam gök mavi, yıldızlar uçuşuyordu. Derinden nefes alıyordu toprak, Vatan konuşuyordu. Vatan ko...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/destanlar-icinde-aziziye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş Yavaş/2', 'yavas-yavas-2-mehmet-bozdogan-ttv6w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir damla düştü rahme

Can geldi yavaş yavaş

Kaderi çizildi alnıma

Ömür biçildi YAVAŞ YAVAŞ

Kan geldi damar verildi

Şekillendi insan yavaş yavaş

Dogdu agladı merhaba denildi

Gözünü açtı YAVAŞ YAVAŞ

İrkilip emekledi yürüdü

Konuştu can yavaş yavaş

Yıllar geçti büyüdü

Genç oldu YAVAŞ YAVAŞ

Evlendi çocuklara karıştı

Çilesi başladı yavaş yavaş

Yaşlandı yürüyemez oldu

Yolculuk başladı YAVAŞ YAVAŞ

Ölümü hiç beklemezken

Ezrail geldi yavaş yavaş

Dualar edildi can çıkarken 

Ruh ayaktan çıktı YAVAŞ YAVAŞ

Selalar verildi camilerde

Dostlar geldi yavaş yavaş

Toprak üstüne örtülünce

Sorgular başladı YAVAŞ YAVAŞ

                                                      19/06/2004', 'Bir damla düştü rahme Can geldi yavaş yavaş Kaderi çizildi alnıma Ömür biçildi YAVAŞ YAVAŞ Kan geldi damar verildi Şekillendi insan yavaş ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bozdoğan']::text[], 8.5, '{"poet":"Mehmet Bozdoğan","poet_slug":"mehmet-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yavas-yavas-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kars Kalesi''ndeki Bayrak', 'kars-kalesi-ndeki-bayrak-nurettin-ozdemir-yxgd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bayrak dalgalanıyor Kars Kalesi''nde,

Karabekir Paşa''dan yadigar kalmış.

Bir bayrak ki, günün her saatinde,

Hudut boylarına renk salmış.

Gün görmüş; ufuklar boyunca

Şafaklar gibi dalgalanmış.

Bir bayrak ki, gölgesinde yaşayan

Toprak vatanmış.

Huzur almış fetih yıllarından,

Yüksek burçlara çekilmiş.

Bir bayrak ki, yalnız milletimin

Alnından öpmek için eğilmiş.

Bir bayrak dalgalanıyor Kars Kalesi''nde,

Karabekir Paşa''nın ruhu gibi.

Bir bayrak ki, büyütmüş gölgesinde

En çetin güzelliği.

Emretmiş, mağrur ve sakin! 

Mavi göklerin kızıymış.

Bir bayrak ki, kaderin sustuğu yerde

Zaferler alın yazısıymış.

Budin''de yaşamış bir zaman,

Viyana''dan sesi gelmiş.

Bir bayrak ki, şehit ruhları üstünde 

Tanrı''ya yükselmiş.

Kars Kalesi''ndeki bayrağı

Taşıyan bilekler bükülmemiş.

Yıllar var ki, o bayraksız

Bu topraklar gülmemiş.', 'Bir bayrak dalgalanıyor Kars Kalesi''nde, Karabekir Paşa''dan yadigar kalmış. Bir bayrak ki, günün her saatinde, Hudut boylarına renk salmış. ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kars-kalesi-ndeki-bayrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Yaşayanlar', 'bende-yasayanlar-nurettin-ozdemir-l7cgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Değil gelen ve giden'',

Değil bir duman gibi dağılan rüzgarla.

Sana karşı beslediğim bir büyük sevgidir,

Yarışır dağlarla.

''Değil bir kucaklayış, sonra da gidiş'',

Bir ömür boyu sarılış, hazla.

Sen yaşarsın içimde dört mevsim, taptaze,

Baharla, yazla.

Senin şarkındır söylenen, özlemli,

Renklerin dilinde yeşil ve beyazla.

Oğullarım büyür koca dağlarda,

Hürlüğünce gelecek zamanların,

Yağmurla, güneşle, ayazla.

Ve kızım, bir gül gibi açar her seher,

Sihirle, hülyayla, nazla.

Sen gelirsin Allah''a uzanmış ellerden; 

İlahi huzur gibi,

Niyazla.', '''Değil gelen ve giden'', Değil bir duman gibi dağılan rüzgarla. Sana karşı beslediğim bir büyük sevgidir, Yarışır dağlarla. ''Değil bir kucakl...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bende-yasayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aile Ağacı', 'aile-agaci-nurettin-ozdemir-j8c3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce sen hep o temiz yüzünle yanımdasın.

Otuz yılın bitmeyen çilesine dayanmış,

İçlerinde umut dolu çoban ateşleri yanmış,

Hüzünlü bakışlarınla aydınlık ufkumdasın.

Demek, yalnız seninle hayatın tadı varmış! 

Sonra birer birer açılan tomurcuklar; 

Bir yanda Gökhan, Aslıhan,

Bir yanda Kürşat, Cengiz, Türkmen.

Bize ömrün mesut ufuklarından gülümseyen

Ve her biri ayrı bir sevgiyi kucaklayan çınar...

İşte aile ağacımız; ben, ebedi karım ve çocuklar.', 'Önce sen hep o temiz yüzünle yanımdasın. Otuz yılın bitmeyen çilesine dayanmış, İçlerinde umut dolu çoban ateşleri yanmış, Hüzünlü bakışları...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aile-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''ü Beklerken', 'gul-u-beklerken-nurettin-ozdemir-iehuw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice güller solup gitti gönül bahçemden.

Nice yaprakları savurdu acı rüzgarlar.

Şimdi bir başka Gül''ü beklemenin telaşındayım.

Şimdi yeniden başlayacak ömrümde o güzel bahar.', 'Nice güller solup gitti gönül bahçemden. Nice yaprakları savurdu acı rüzgarlar. Şimdi bir başka Gül''ü beklemenin telaşındayım. Şimdi yeniden...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-u-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-nurettin-ozdemir-nr675', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şey eriyor içimde pul pul, pırıl pırıl...

Bir özlem büyüyor ellerimde.. Mutluluk gibi...

Dağlıp kayboluyor bakışlarımda bir hüzün,

Bir kuş gibi çırpınıyor, kalbim eteklerinde

Beklerken açılmasını bir seher vakti gülün.', 'Bir şey eriyor içimde pul pul, pırıl pırıl... Bir özlem büyüyor ellerimde.. Mutluluk gibi... Dağlıp kayboluyor bakışlarımda bir hüzün, Bir k...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beklemek-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş yavaş/1', 'yavas-yavas-1-mehmet-bozdogan-htqxx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş kemale ermeden

Elden ayakyan düşmeden

Köyülere boyun bükmeden

Ecel gelsin YAVAŞ YAVAŞ

Çimenler içinde ısırgan oldum

Gül bahçesinden diken yoldum

Ormanlar içinde sahra sordum

Kendiden kaçtım YAVAŞ YAVAŞ

Dünyalıga kaptırdım kendimi 

Unuttum özümü benligimi

Bilemedim yaradılış sebebimi

Ezrail yakaladı YAVAŞ YAVAŞ

                                                         28/05/2003', 'Yaş kemale ermeden Elden ayakyan düşmeden Köyülere boyun bükmeden Ecel gelsin YAVAŞ YAVAŞ Çimenler içinde ısırgan oldum Gül bahçesinden dike...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bozdoğan']::text[], 8.5, '{"poet":"Mehmet Bozdoğan","poet_slug":"mehmet-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yavas-yavas-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin hüzün', 'hosgeldin-huzun-nazim-ercan-hf3cd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamansızlık…

Bu güne uzanan yitirilmiş yollar aylak sabahları karşılama telaşında. Bir Akrep kral ve yitmiş mutluluklar dün de. Yeni bilinmezlere açılmış kollara koşar adım yürümekte, alaca, yarı puslu sorular. Neydi beklediğim; Beklediğim neydi sana söylüyorum yüreği düş rengi olan. Yarı kör, yarı sağır, yarı dilsiz bir beden bu. Kaos’u bekliyorum. Soytarısı olmayacak zamanları belki de; Ama hükmeden zamansızlık hala bedene.

	Bitiyor…	

Bir düş yortusu bu…! Kurban edilmiş düşlerin anısına, zamana, yaşama ve bedene. Tapınmayı unutmuş bir meleği ağırlıyorum, ağlamaklı; bildiği tek şeyi de unutmuş. Neden unutulur ki bir vakit gelince hep bilinenler?  Bir sezinleyiş midir sevgi sözcükleri yoksa duyumsanışı mı sevginin; belki de ondan da öte bir şeylerin? Anlamlarını yitirmiş sıfatları ağırlıyor akıllar. Yitirilmiş anlamlara yeni sıfatlar bulmalı. 

	Merhaba…

Son bir söylem daha dünlerden bu günlere kalan. Hep koşar adım kaçılan zaman mıydı adın senin? Yumuşak arpejlerle duyumsadığım bir hüzünsüzlüğün bedelini ödeyen yeni gün. Merhaba… Tükendi çığlıkları yıldızların, Gölgesinde soluklandığım o ağaçta yok artık. O ağaç ki ne üdüğü belirsiz aşkların ev sahibi olmuştu hep. İki kırlangıç izliyor tepemde beni, iki kırlangıç iki düşsel yolcusu göklerin. 

		Hoş geldin…

	Çiçek açmayı unuttu bu yıl fesleğenler. Umutlu hüzünleri, esrik geceler ağırlıyor. Düş’üm de gördüğümdün sen, ey yüreği düş rengi olan, gözleri alaca hüzün.Bir orkide ağlamaklı, tomurcuğu hüznün ağulu, kösnül ve esrik izliyor yüreğini. Gene de kırlangıçtır yüreği hüznün, gene de kırlangıç, gene de hüzün. Sessiz bir salınışla süzülen ares’in kılıcı erosa doğru savrulan.

		Hüzün…

	Erbain yaklaşıyor, zemheriye hazırlık birkaç kanyak şişesi. Esrik düşlerin noel babası bir şaman la oynuyor. Bir kumar bu düşleri üzerine bir kumar insanların, hüzünleri üzerine bir kumar. Kim kazanırsa kazansın yitirecek olan hep düşler. Zamansızlık bitiyor hoş geldin hüzün. Firavun gözleri gecenin gene de hoş geldin hüzün. Bir mabedin sütunları dibinde ibadet te gece hoş geldin hüzün. Bulut uçuran çocukların düşlerine, dağınık saçlı uykularıma hoş geldin hüzün.

………………………

……………………..

                                                                                          19/08/2004', 'Zamansızlık… Bu güne uzanan yitirilmiş yollar aylak sabahları karşılama telaşında. Bir Akrep kral ve yitmiş mutluluklar dün de. Yeni bilinme...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hosgeldin-huzun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Demiş Aşk Beklemez Diye', 'kim-demis-ask-beklemez-diye-reyhan-sur-ibxej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nemli çakıltaşları ışırdı güldüğünde 

ah! sen ne şirindin 

sözlerin kahkaha çiçeklerine dönerdi 

karanfil kokardı ellerin...



ıssız kulübesindeyim o dağın 

kızılca güz ortasında 

en karanlık anı gecenin 

şifresini de yitirdi gözlerinde 

gözlerim.. 

ayrıkotları çoğaldı direncin köklerinde 

ürkütülmüş gölgeleri koşuyor sevinin 

rüzgar ormanlarına sürüklüyor beni 

esintisi seslerin 

bütün duvarları çatladı sabır kuyularının

zulüm bu.. 

bütün nazar boncuklarının damarları üşüyor 

seni imlediğim dizelerimde 

yine de 

çiçekleniyor mavice yabanıl sarmaşıklar 

uzanıp öpüyorlar ayı alnından 

en soylu ışıltısını yayıyor ay bu gece 

aralayıp yüreğinin çalılıklarını 

bir mabede giriyorum sanki 

öylesine sessiz 

öylesine ilahi 

aşk bekliyor kapısında... 

her yer karanfil 

gülümsüyorum.. 

bir daha 

bir daha yakıyorum sigaramı ucu ucuna 

.. d-ü-ş-ü- /nü/- y-o-r-u-m...', 'nemli çakıltaşları ışırdı güldüğünde  ah! sen ne şirindin  sözlerin kahkaha çiçeklerine dönerdi  karanfil kokardı ellerin... ıssız kulübesin...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kim-demis-ask-beklemez-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Halden Gerçeğe Çıkmak', 'kayip-halden-gercege-cikmak-necmi-unsal-44w2t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kayıp halden tam gerçeğe çıkmak,

Kendini iyi tanımaktan geçer.

Benlik putunu fütursuzca yıkmak,

Rabbini iyi tanımaktan geçer.

Tanımazsan sen arifce kendini,

Yolun kalleşten melametle geçer.

Yıkamazsan sen zarifce bendini,

Sonun ateşten nedametle geçer.

23 Haziran 2004 Çarşamba, Danimarka-Køge 18:49

5+6', 'Bu kayıp halden tam gerçeğe çıkmak, Kendini iyi tanımaktan geçer. Benlik putunu fütursuzca yıkmak, Rabbini iyi tanımaktan geçer. Tanımazsan ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kayip-halden-gercege-cikmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DöN-Me-Li-SiN', 'don-me-li-sin-mine-ozdemirtas-4issi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkmaz sokaklarda 

kaybolmuş çocuk gibisin. 

Oysa biliyorsun ki; 

bir yerin olmalı artık. 

Bir de adresin. 

bölünme kaldırımlara, 

bölünme açmazlara 

çok bilinmeyenli denklem değilsin. 

yüreğimin gözleri okuyor seni.

bir müddettir gölgelere sığınıp.... 

gizlenmedesin.

sabırla büyütüyorum suskunluğu. 

Çığ gibi. 

içindesin.

sakın fazla yuvarlanma. 

yuvarlanma sakın. /Erirsin. 

ben yokum senin kentinde. 

ben yokum senin yağmurlarında. 

dilediğin zaman, 

dilediğin tarlaya yağabilirsin. 

konuşmuyor dediğin duvarlar var ya.... 

konuşuyor bilesin 

dinliyorum geçiştirmeleri,

duyuyorum söylenmeyenleri 

Sen ki; 

nicedir 

kendi yokluğunun 

ayak seslerindesin.

Ya “ döndüm “de kurtul. 

yokluğunu bileyim senin. 

Ya da “ döndüm” de. 

de ki sana inanayım. 

bitsin sitemim. 

yorulmadın mı? 

çok uzun zamandır / 

çok ama çok uzun zamandır 

bu kısır, bu yaman, 

bu yakan, sarmalda / 

dönmelerdesin', 'Çıkmaz sokaklarda  kaybolmuş çocuk gibisin.  Oysa biliyorsun ki;  bir yerin olmalı artık.  Bir de adresin.  bölünme kaldırımlara,  bölünme a...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/don-me-li-sin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilsiz', 'dilsiz-turgay-kadiroglu-dtw0u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dile gelen bir söz 

tüm büyüyü bozacak sanki. 

yitirme endişesi uçsuz bucaksızlığı... 

korkmak alabildiğine kolay 

ve misliyle zor konuşmak... 

dile gelen bir söz 

sararmış çiçeklere birer müjde belki de, 

on bir gezegende kadim bir beklenti, 

mevsimleri bahara çıkaran bir ümit belki, 

yine de korku... 

mürekkebin kağıda ilişme korkusu 

ellerin güvercinlere erişme korkusu... 

ürkek yüreğin, 

bir gönülle kesişme arzusu... 

ya tüm büyü bozulur da 

direklerinden vurulursa gök taşları 

yağmurla karışık bir acı yağarsa göklere 

hicranın alev bendi kalkarsa ayağa ansızın 

içimdeki bu tufan dinmezse kaf dağında 

kim vermeli hesabını 

dile gelen sözün... 

kim verecek hesabını, 

gamze vadilerini 

çöl eden dilsiz sözün...', 'dile gelen bir söz  tüm büyüyü bozacak sanki.  yitirme endişesi uçsuz bucaksızlığı...  korkmak alabildiğine kolay  ve misliyle zor konuşmak....', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dilsiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Dil', 'ana-dil-mehmet-isikoglu-v9762', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğrenmektir emelim

Sağlam olur temelim

Nükte doludur dilim

Güldükçe güler insan

Sayısızca masaldan

Fıkra roman her daldan

Tatlıdır akan baldan

Aktıkça dolar insan

Biçilemez değerin

Doldurulamaz yerin

Denizler kadar derin

Daldıkça dalar insan

Öğrenmesi zor değil

Çok şirindir ana dil

Yeter ki tadını bil

Tattıkça tadar insan

Yaban ellerde hele

Sarılmak gerek dile

Yoksa gidersin sele

Kaybolur gider insan

Almanya / Köln', 'Öğrenmektir emelim Sağlam olur temelim Nükte doludur dilim Güldükçe güler insan Sayısızca masaldan Fıkra roman her daldan Tatlıdır akan bald...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ana-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zavallı Yüreğim Yanar mı Böyle?', 'zavalli-yuregim-yanar-mi-boyle-i-smet-barlioglu-1tl77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimin yaşı dizime iner

İnan, ağlamaya bir utanmasam; 

Zavallı yüreğim yanar mı böyle

Sana var gücümle sevdalanmasam? 

Bir ömür boyudur ağlar inlerim,

Kederlerle geçti bayram günlerim,

Acaba kara mı bağlar kaderim

Ben senin aşkınla hırpalanmasam? 

Bir yürek bunca mı döner külhana? 

Bir ömür böyle mi döner harmana? 

Adım düşer miydi dile, destana

Darmadağın olup parçalanmasam? 

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 91-91/100)', 'Gözlerimin yaşı dizime iner İnan, ağlamaya bir utanmasam;  Zavallı yüreğim yanar mı böyle Sana var gücümle sevdalanmasam?  Bir ömür boyudur ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zavalli-yuregim-yanar-mi-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Tam Ortasında', 'omrumun-tam-ortasinda-i-smet-barlioglu-yg01r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim ki seni gördü

Bütün akan sular durdu.

Yüreğimi alev sardı

Ömrümün tam ortasında.

Bahar gibi kokuyorsun,

Bülbül gibi şakıyorsun,

Durmuş bana bakıyorsun

Ömrümün tam ortasında.

Tıpkı ırmak gibi coştum,

Ben kendime kendim şaştım,

Bir acaip aşka düştüm

Ömrümün tam ortasında.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 92-92/100)', 'Gözlerim ki seni gördü Bütün akan sular durdu. Yüreğimi alev sardı Ömrümün tam ortasında. Bahar gibi kokuyorsun, Bülbül gibi şakıyorsun, Dur...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/omrumun-tam-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tren Gider Kars''a', 'bir-tren-gider-kars-a-muammer-hacioglu-q0k3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydarpaşa Garı''ndan bir tren gider Kars''a

geçer karlı dağlardan rayları sarsa sarsa

Kars''a sürgün gidiyor Ali''nin oğlu Durmuş

sevdiğini kaçıran arkadaşını vurmuş

gözlerindeki yaşlar sanki akan bir dere

hiçkimse yenilmemiş onun kadar kadere

ellerinde kelepçe, içinde yar hasreti

gittikçe ufalıyor ardında memleketi

Haydarpaşa Garı''ndan bir tren gider Kars''a

geçer karlı dağlardan rayları sarsa sarsa', 'Haydarpaşa Garı''ndan bir tren gider Kars''a geçer karlı dağlardan rayları sarsa sarsa Kars''a sürgün gidiyor Ali''nin oğlu Durmuş sevdiğini kaç...', ARRAY['Türk Edebiyatı','Şiir','Muammer Hacıoğlu']::text[], 8.5, '{"poet":"Muammer Hacıoğlu","poet_slug":"muammer-hacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-tren-gider-kars-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkili Güzellik', 'i-kili-guzellik-nurettin-ozdemir-1lnrq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çift alageyik bir korulukta

Ve bir dalda yan yana iki güvercin,

İki yavru ceylan bir su başında

Ve bir kayadan yükselen iki kartal,

Yarışan iki doru tay dumanlı bir yaylada

Ve bir sıra dağda gün vurmuş iki doruk,

İki alabalık hırçın sulara karşı

Ve bir koyunun ardında meleyen iki kuzu,

İki yeşil yaprak gecikmiş bir sonbaharda 

Ve asırlık bir bahçede iki tomurcuk gül,

Gerilmiş iki ok yiğit bileklerle

Ve bir namluda sırt sırta uyuyan iki mermi,

- Heyy oğul iki ok, iki mermi! 

                                               - Atılıp gitti biri.', 'Bir çift alageyik bir korulukta Ve bir dalda yan yana iki güvercin, İki yavru ceylan bir su başında Ve bir kayadan yükselen iki kartal, Yarı...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikili-guzellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madem ki Ayrıldık, Ayrılıyoruz', 'madem-ki-ayrildik-ayriliyoruz-i-smet-barlioglu-zpszc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dert olma gönlüme, darılmadan git,

Madem ki ayrıldık, ayrılıyoruz.,

Sen bana aldırma, sarılmadan git,

Madem ki ayrıldık, ayrılıyoruz.

Gitmeden gülümse; hatıra olsun,

Kalbim ana ana her gün avunsun,

Acep bundan sonra nerde olursun,

Madem ki ayrıldık, ayrılıyoruz.

Madem ki ayrıldık, ayrılıyoruz? 

Gücenme, aldırma, kızma, incinme,

Bırak beni böyle kendi halime,

Ben ölmüş kalmışım bundan sana ne,

Madem ki ayrıldık, ayrılıyoruz? 

Sorma bekler miyim kayalıklarda,

Üzülüp ağlayıp karanlıklarda,

Hiç durma, bekleme tozlu yollarda,

Madem ki ayrıldık, ayrılıyoruz.

Beni ne hatırla ne de dur düşün,

Bir aşkı mahvetti bu son gidişin,

Korkarım ki artık olmaz dönüşün

Mademki ayrıldık, ayrılıyoruz.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 93-94/100)', 'Dert olma gönlüme, darılmadan git, Madem ki ayrıldık, ayrılıyoruz., Sen bana aldırma, sarılmadan git, Madem ki ayrıldık, ayrılıyoruz. Gitmed...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/madem-ki-ayrildik-ayriliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Güllerim', 'mor-gullerim-faruk-unal-w60ob', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreyimde umutlar vardi

Bir gün bana dönersin diye

Dönüpte bana bir gün yeniden

Seni tekrar severim diye

Beni sen viran ettin

Gelde acsin mor güllerim

Cikazi olmayan yola gittin

Dönüsü yokmu gidisin`in', 'Yüreyimde umutlar vardi Bir gün bana dönersin diye Dönüpte bana bir gün yeniden Seni tekrar severim diye Beni sen viran ettin Gelde acsin mo...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mor-gullerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Sevdim Naz İçinde', 'bir-kiz-sevdim-naz-i-cinde-i-smet-barlioglu-d1s9r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Palandöken yaz içinde,

Sevilmeyen az içinde,

Bir kız sevdim naz içinde,

Bilekleri kardan aktı.

Saçlarında dağ havası,

Çiçek gibi utanması,

Sağolası, varolası

Çekinerek bana baktı.

Sırtında bir deste başak,

Bakışları çok yumuşak,

Sarı cepken, ince kuşak,

Seslenseydim duracaktı.

Rastlasaydım bir kez daha,

Sağ çıkmazdım ben sabaha.

Öyle bir düştüm ki aha

Herbir yanım yanacaktı.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 95-96/100)', 'Palandöken yaz içinde, Sevilmeyen az içinde, Bir kız sevdim naz içinde, Bilekleri kardan aktı. Saçlarında dağ havası, Çiçek gibi utanması, S...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kiz-sevdim-naz-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağsın Bu Yağmurlar Doyana Kadar', 'yagsin-bu-yagmurlar-doyana-kadar-i-smet-barlioglu-s02yu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçaklar altında kalalım böyle,

Yağsın bu yağmurlar doyana kadar.

Başın omuzumda fısılda, söyle,

Yüreğim sesini duyana kadar.

Islak saçlarında parlasın sular,

Belirsin yüzünde tatlı uykular,

Cana, dile gelsin gizli duygular,

Akşamlar, geceler olana kadar.

Yağmurlar dallara sürünüp geçsin,

Ay bulut ardından görünüp geçsin,

Bulutlat gevşeyip gerilip geçsin,

En yüksek dağları bulana kadar.

Gözünü ayırma yüzümden asla,

Ürperen yüzünü yüzüme yasla,

Kerem ''le, Mecnun ''la beni kıyasla,

Kaderim çöllere salana kadar.

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 97-98/100)', 'Saçaklar altında kalalım böyle, Yağsın bu yağmurlar doyana kadar. Başın omuzumda fısılda, söyle, Yüreğim sesini duyana kadar. Islak saçların...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagsin-bu-yagmurlar-doyana-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayib Olmasin', 'kayib-olmasin-faruk-unal-n6yv5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi denizin üstünde sallanan kücük bir gemi

Duramiyorum ayakta sallaniyorumun onun gibi

Kaderimin denizinde kayb olmusum sanki

Bulamiyorum kaderimin yolunu bir türlü

Kayb olmasin insan bir kere

Sasirir yolunu bin kere

Ceker izdirabini

Akli basina gelene kadar', 'Mavi denizin üstünde sallanan kücük bir gemi Duramiyorum ayakta sallaniyorumun onun gibi Kaderimin denizinde kayb olmusum sanki Bulamiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Ünal']::text[], 8.5, '{"poet":"Faruk Ünal","poet_slug":"faruk-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayib-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste Yeterki', 'i-ste-yeterki-mustafa-yigit-morpheus-f04sq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarlarda Sen, Ağaçlarda Ben

Nereye Esersen, Oraya Giderim

Bulutlarda Sen, Yağmurlarda Ben

Nereye Yağarsan, Oraya Düşerim

Sen Kainatı Aydınlatan Güneş

Sen Gökyüzündeki Yıldızlara Eş

Sen Aşkınla Beni Eyledin Serkeş

Nerede İstersen, Orada Kalırım

Sen Dağ Başındaki Yaralı Ceylan

Sen Bir Bakışı İle Yürekler Yakan

Sen, Yaşarken Mezarımı Kazdıran

Nereye İstersen, Oraya Yatarım

Sen Dünyanın Hayat Kaynağı

Sen Sevda Yolcularının Son Durağı

Sen Aşk Kölelerinin Sultanı

Nereye İstersen, Oraya Satayım

Sen Durağın Bitmez Çilesi

Sen Yâdellerin Aşkı Neşesi

Sen Gökyüzünün Parlayan Güneşi

Nereyi İstersen, Orayı Yakayım

 Mustafa Yiğit (Morpheus)', 'Rüzgarlarda Sen, Ağaçlarda Ben Nereye Esersen, Oraya Giderim Bulutlarda Sen, Yağmurlarda Ben Nereye Yağarsan, Oraya Düşerim Sen Kainatı Aydı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iste-yeterki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçlenme', 'i-clenme-nurettin-ozdemir-ldwdu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- Kardeşim Rahmetli Ethem''in aziz ruhuna:

                     ''Zaman aramıza girdikçe, sana daha çok                        

                                            yaklaştığımı hissediyorum.''

Yıllar geçiyor; umutsuz, kayıtsız yıllar...

Gömülüp gidiyorum hatıralara.

Acı yüklü gemiler demirliyorlar,

Yüreğimin ıssız limanlarına! 

Neden böyle çabuk kesildi hızın? 

Mavi göklerimden kaydı yıldızın.

Nasıl da karışıp gittin ansızın

Yaylaların ince dumanlarına! 

Seher rüzgarıyla bahçemde esen,

Gün vurunca yeşil dallarda yüzen,

Muhacir kuşlarla dönüp de gelsen,

Eş olsan yurdumun ceylanlarına! 

Tüter buğu buğu özlemin yerden,

Peygamberin bahçesinde güllerden,

Beş mübarek vakitte minarelerden,

Karışsan Tanrı''nın ezanlarına.

Ayetler.. hadisler.. dualarla nur...

Bir avuç toprağa ''Yasin'' okunur.

Başını kaldırıp bir baksan n''olur

Yüce dağlarına, ormanlarına.

Anadan, oğuldan, yardan uzaksın! 

O yerde ''kimsesiz'' nasıl yatarsın? 

Hep böyle hasret mi uyuyacaksın,

Aybüke''lerine, Serhan''larına? 

Ecelin oku mu bağrını deldi? 

Ölüm mü hayattan daha güzeldi? 

Heyy oğul! .. seni çok göresim geldi.

El-pençe dikilsem divanlarına! 

Yıkılmaz dağımdın, durulmaz selim.

Kırıldı kollarım, tutmuyor elim.

Nefesim kesildi, dönmüyor dilim.

Ey sabır! .. al beni ummanlarına.', '- Kardeşim Rahmetli Ethem''in aziz ruhuna:                      ''Zaman aramıza girdikçe, sana daha çok                                       ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/iclenme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nefes Alırken, Gezip Yaşarken', 'sen-nefes-alirken-gezip-yasarken-i-smet-barlioglu-c5hzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçeler bu kadar viran değildi

Sen nefes alırken, gezip yaşarken.

Geceler böylesi zindan değildi,

Sen nefes alırken, gezip yaşarken.

Her gün başbaşaydık, her gün elele,

Hiç gerek duymazdık güle, bülbüle,

Görmezdik ızdırap, görmezdik çile,

Sen nefes alırken, gezip yaşarken.

Dereler akardı şırıldayarak,

Gülerdi yıldızlar parıldayarak,

Yel eser dururdu uğuldayarak

Sen nefes alırken, gezip yaşarken.

Göl ayna olurdu mehtap altında,

Mehtaplar yansırdı yanaklarında,

Kum halı olurdu ayaklarında

Sen nefes alırken, gezip yaşarken.

Şimdi ne göller göl ne mehtap mehtap,

Tümü bir yalancı, bir hain serap,

Var mıydı içimde bunca ızdırap

Sen nefes alırken, gezip yaşarken? 

(RENKLER NEMLENİYOR DUDAKLARINDA isimli Hece Şiirler ''inden > 99-100/100)', 'Bahçeler bu kadar viran değildi Sen nefes alırken, gezip yaşarken. Geceler böylesi zindan değildi, Sen nefes alırken, gezip yaşarken. Her gü...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-nefes-alirken-gezip-yasarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pire Nuri', 'pire-nuri-yusuf-ter-1334h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaban elde gurbet yaşar

Göçer gider Pire Nuri

Engel bilmez engel aşar

Uçar gider Pire Nuri

Selam söyler Yusuf Ter’e

Sohbet kurar sıcak yer’e

Gönül verir yüz bin kere

Geçer gider Pire Nuri

Ormanların çınarından

Erciyes’in  kenarından 

Dost dağın pınarından

İçer gider Pire Nuri

Pire Nuri böyle dedi

Yusuf Ter’dir asıl adı

Damağında dostluk tadı

Saçar gider Pire Nuri

Pire Nuri bu ellerde

Namı gezer tüm dillerde

Gül misali gönüllerde

Acar gider Pire Nuri

Yusuf Ter

14/ 07/ 04  Türkiye', 'Yaban elde gurbet yaşar Göçer gider Pire Nuri Engel bilmez engel aşar Uçar gider Pire Nuri Selam söyler Yusuf Ter’e Sohbet kurar sıcak yer’e...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/pire-nuri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden Seninle Gezdiğim Yerler', 'eskiden-seninle-gezdigim-yerler-i-smet-barlioglu-hmdyx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden seninle gezdiğim yerler

Yıkılıp mahvolmuş, kavrulup solmuş.

Üstünden koşarak geçtiğin köprü

Gözümden boşanan yaşlarla dolmuş.

Nerde hayalini aksettiren su? 

Saçına taktığın papatya nerde? 

Bakışım ok gibi saplanıp kalmış

Eskiyen izinin durduğu yerde.

Yalnız yokolmayan anılar kalmış

Yorgun geçmişlerin yanında yatan

Ve bahar yerine kasırga ile

Papatyada zehir, gelincikte kan.

(HANÇER YARASI isimli Hece Şiirler ''inden > 7-7/100)', 'Eskiden seninle gezdiğim yerler Yıkılıp mahvolmuş, kavrulup solmuş. Üstünden koşarak geçtiğin köprü Gözümden boşanan yaşlarla dolmuş. Nerde ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eskiden-seninle-gezdigim-yerler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-nurettin-ozdemir-qshcd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve bir yeşil alev ufkumda yanan,

Çok eski bir şarkı dinlediğimiz.

Ömrümde seninle başlayan zaman,

Uçan kuş, doğan gün, masmavi deniz.

Dallarda bir mevsim kuş seslerinden,

Eteğinde garip, çaresiz yürek.

Bir davet geliyor gibi derinden,

Beni hem sevecek, hem öldürecek', 'Ve bir yeşil alev ufkumda yanan, Çok eski bir şarkı dinlediğimiz. Ömrümde seninle başlayan zaman, Uçan kuş, doğan gün, masmavi deniz. Dallar...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umit-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitecek Son Nefes', 'bitecek-son-nefes-hifzi-ozbekmez-hrn2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah için ne verdiysen 

O gidecek senin ile

Yazık günaha erdiysen

Söylenecek dilin ile

Artık hakka dön yüzünü

Aşkıyla doldur özünü

Seninde gönül gözünü

Açar Allah izni ile 

Tapma dünyanın malına

Günah doldurma dalına

Bir gün ölümün salına

Bineceksin bile bile

Latif koca dünya yalan

Bir gün olur gönül talan

Ömürdür her gün azalan

Bitecek son nefes ile 

18  AĞUSTOS 2004 SAAT:19:00', 'Allah için ne verdiysen  O gidecek senin ile Yazık günaha erdiysen Söylenecek dilin ile Artık hakka dön yüzünü Aşkıyla doldur özünü Seninde ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitecek-son-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Halleri', 'sevginin-halleri-nurettin-ozdemir-6re6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün çıkıp geldin eski yollardan,

Güzellik büyüdü ellerimizde.

Sihirli şarkılar söylenir oldu,

Bakışlarımızda, dillerimizde.

Pul pul, kıvrım kıvrım, ince nakışlar

İşlendi değişik hallerimizde.

Uzak bahçelerin özlemi kaldı,

Açılan kırmızı güllerimizde.

Tenhada bir kamış, tedirgin bir kuş,

Akşam saatleri göllerimizde.

Ve bir el uzanır, usulca okşar

Sevgiyi, bilinmez bir yerimizde', 'Bir gün çıkıp geldin eski yollardan, Güzellik büyüdü ellerimizde. Sihirli şarkılar söylenir oldu, Bakışlarımızda, dillerimizde. Pul pul, kıv...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevginin-halleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşım Kırka Dayandı', 'yasim-kirka-dayandi-hifzi-ozbekmez-7uig9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşım geldi bak kırklara dayandı

Bir baltaya sap olmadım arkadaş

Gönül sevdalara yandı uyandı

Bir çorbaya kap olmadım arkadaş

Çekemedim deli gönlün nazını

Çalamadım teli kırık sazımı

Çoğum yokken beğenmedim azımı

Kadir kıymet bilemedim arkadaş

13  AĞUSTOS 2004 SAAT:08:00', 'Yaşım geldi bak kırklara dayandı Bir baltaya sap olmadım arkadaş Gönül sevdalara yandı uyandı Bir çorbaya kap olmadım arkadaş Çekemedim deli...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasim-kirka-dayandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Hüznü', 'sevginin-huznu-nurettin-ozdemir-bo68g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kandilli''den geçtim dün akşamüstü; 

Aradım seni hep o eski yerde.

Özlemlerin çiçek açtığı saat,

Bir hüzün, bir telaş yorgun yürekte.

Değişik şarkılar söylenir gibi,

Tenha sokaklarda ve bahçelerde.

Bütün çeşmelerin suyu kesilmiş; 

Anladım, derman yok artık bu derde.

Perdeler usulca kımıldar, yazık.

Sevdiğim görünmez pencerelerde!', 'Kandilli''den geçtim dün akşamüstü;  Aradım seni hep o eski yerde. Özlemlerin çiçek açtığı saat, Bir hüzün, bir telaş yorgun yürekte. Değişik...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Özdemir']::text[], 8.5, '{"poet":"Nurettin Özdemir","poet_slug":"nurettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevginin-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
