INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bekler Gibisin', 'beni-bekler-gibisin-derin-oger-8t7hc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey koca şehir,sen say

ben olan ne çok gece terketmiş beni

imkansız hayallerimde yıldızlar pırıl pırıl

güneş dönüp kırmızı kırmızı gözlerime batarken

saymamışım kaç gülücük donmuş dudaklarımda

rüzgârın yönü kaç kez değişmiş,ağaçlar kaç kez çiçeğe durmuş

dinlediğim şarkılarla yaşadıkça yaşlanmış dünler

ay yalan olmuş, yarım kalmış sevdalar

ey koca şehir,sen duy

meğer gurbet ne kadar yakın

bir adımda gece nasıl da bana sadık

hüzün ve acı yüzde saklı,göz ağlamaya hazır

korkular çağırıp korkular gönderdiğim kirpiklerim arasından

kaderin gülen yüzüne aldandıkça alışılmış yalanlara

mavinin derinliğince yeşile inat sevmişim siyahı

kalbimi yorgun bulmuşum ki,içim dökülmüş........', 'ey koca şehir,sen say ben olan ne çok gece terketmiş beni imkansız hayallerimde yıldızlar pırıl pırıl güneş dönüp kırmızı kırmızı gözlerime ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-bekler-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçare', 'bicare-sair-figenyarar-bkokv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acı çekmek için 

Aşık olmak lazımmış meğerse

Mutlu olmak için de

Aşık olmak lazımmış nedense

Asıl mesele 

İnsan olmakmış biçare...', 'Acı çekmek için  Aşık olmak lazımmış meğerse Mutlu olmak için de Aşık olmak lazımmış nedense Asıl mesele  İnsan olmakmış biçare......', ARRAY['Türk Edebiyatı','Şiir','Şair Figenyarar']::text[], 8.5, '{"poet":"Şair Figenyarar","poet_slug":"sair-figenyarar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bicare-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir aşk yarası', 'bir-ask-yarasi-goksel-akkaya-rf5fa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aşk yarası

Bir aşk yarası beni bu hale koydu 

Gündüzümle gecemi isyanla doldurdu

Yazık yalanlarıyla benliğimi unutturdu 

Bak işte aşk ne hale koydu 

Ömrümden baharı çaldı 

Dertleri sırtıma tek tek yığdı 

Kutlu bir yerde hayaliyle bıraktı

Gittin gözlerim yetim kaldı

Yaprağı döküldü, gülleri soldu

Senin yüzünde hayatım viran oldu

Kader her gün sille vurdu

Bir aşk yarası beni bu hale koydu', 'Bir aşk yarası Bir aşk yarası beni bu hale koydu  Gündüzümle gecemi isyanla doldurdu Yazık yalanlarıyla benliğimi unutturdu  Bak işte aşk ne...', ARRAY['Türk Edebiyatı','Şiir','Göksel Akkaya']::text[], 8.5, '{"poet":"Göksel Akkaya","poet_slug":"goksel-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ask-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Sevda', 'kor-sevda-tunahan-ermihan-knbfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keser mi sandın adam yüreğini kör bıçaklar

Dudaklarından dökülecek bir kelime kadar

Yaralarına tuz basarda gözlerinden yaş mı akar

Gidişinin ardından bakan nemli gözler kadar

Söner mi sandın adam yüreğinin ateşi en derin denizlerde

Neron bile yakamadı Roma’yı bu kadar geçmişte

Namım sonbahar olsa da yandım her gece hasretine

Kışlara meydan okudum yangınınla yüreğim ellerimde

Biter mi sandın adam yüreğinde sevdan ömrün sonun da

Nefes almak kadar değildir bu yürekte aşktan mana

Hasretin diner mi sandın bir gece yanımda yattığın da

Bir ömre sığmaz artık bu kör sevda', 'Keser mi sandın adam yüreğini kör bıçaklar Dudaklarından dökülecek bir kelime kadar Yaralarına tuz basarda gözlerinden yaş mı akar Gidişinin...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kor-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımak ve Unutmak', 'tanimak-ve-unutmak-zuhal-aksulu-xxpg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk bana uzak

Ellerin yasak

Hayal gibiydi ellerini

Mutluluk sanmak

Er geç olacak bir şeydi

Tanımak ve unutmak', 'Mutluluk bana uzak Ellerin yasak Hayal gibiydi ellerini Mutluluk sanmak Er geç olacak bir şeydi Tanımak ve unutmak...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tanimak-ve-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-zuhal-aksulu-zr3cw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmiyorum

Günlerin sensizliğini

Gecelerin sessizliğini

Sessizlik sensizliğe dair

Özlüyorum

Bekliyorum

Günlerde gelişini

Gecelerde sevişini

Sevişin gelişine dair

Özlüyorum

Susuyorum

Günlerdir gidişine

Gecelerdir gidişine

Özlemek gidişine dair

Özlüyorum', 'Sevmiyorum Günlerin sensizliğini Gecelerin sessizliğini Sessizlik sensizliğe dair Özlüyorum Bekliyorum Günlerde gelişini Gecelerde sevişini ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozluyorum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde İki Ses', 'i-cimde-i-ki-ses-zuhal-aksulu-q7hau', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde iki ses

Dur durak bilmeden konuşuyor

Biri bağırıyor ''Git yalvar''

Diğeri susuyor ''Seni kim duyar''

İçimdeki ses 

Beni susturuyor

İçimde iki ses

Benden hesap soruyor

Biri kızgın ''Neden bıraktın''

Diğeri üzgün ''Ne yapacaktın''

İçimdeki ses 

Beni suçluyor

İçimde iki ses

Bana baskı yapıyor

Biri önde ''Benim olmalı''

Diğeri geride ''Hakkın var mı''

İçimdeki ses

Beni boğuyor', 'İçimde iki ses Dur durak bilmeden konuşuyor Biri bağırıyor ''Git yalvar'' Diğeri susuyor ''Seni kim duyar'' İçimdeki ses  Beni susturuyor İçimde...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icimde-iki-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar', 'karar-zuhal-aksulu-b7194', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş bile yakamaz tenimi

Dokunuşunun yaktığı kadar

Bİr kere tuttun ya elimi

Elim artık ellerini arar

Bu hisler kalbimde yeni mi

Aklımı alır, ruhumu sarar

Daha saramadan bedenimi

Erken geldi aldığın bu karar', 'Güneş bile yakamaz tenimi Dokunuşunun yaktığı kadar Bİr kere tuttun ya elimi Elim artık ellerini arar Bu hisler kalbimde yeni mi Aklımı alır...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-zuhal-aksulu-jwi58', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle alışmışım ki

Ellerine, dokunuşuna

Gülüşüne, dudaklarına

O güzel kokuna

Her yer sen kokuyor

Kimse senin gibi gülmüyor

Dokunmuyor

Zormuş be hocam sensizlik

Ama günler geri gelmiyor

Gerçi bu ilişkide her şey zordu

Buluşacak vaktimiz

Bir yerimiz bile yoktu

En zor olan ise

Parmakta bir yüzük

Bir de çocuktu

Bu ilişkinin ne adı vardı

Ne de bir sonu', 'Öyle alışmışım ki Ellerine, dokunuşuna Gülüşüne, dudaklarına O güzel kokuna Her yer sen kokuyor Kimse senin gibi gülmüyor Dokunmuyor Zormuş ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zor-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-zuhal-aksulu-u1xhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yıllardır bomboş yaşarken

Ansızın hayatıma girdin

Görmeyi, duymayı, bilmeyi

Bildiğim ne varsa öğrettin

Üstümüze karlar yağarken

Sen bana baharı verdin

İnsanlar soğuktan titrerken

Bir gülüşünle içimi erittin

Günler hızla geçerken

Ben kıymetini bilemedim

Sen hayatımdan giderken

Bir elveda diyemedim', 'Ben yıllardır bomboş yaşarken Ansızın hayatıma girdin Görmeyi, duymayı, bilmeyi Bildiğim ne varsa öğrettin Üstümüze karlar yağarken Sen bana...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giderken-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharımda Yoksun', 'baharimda-yoksun-zuhal-aksulu-yevj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kış günü baharım oldun

Karanlık gecelerime güneş gibi doğdun

Şimdi çiçekler açıyor ama

Baharımda yoksun', 'Bir kış günü baharım oldun Karanlık gecelerime güneş gibi doğdun Şimdi çiçekler açıyor ama Baharımda yoksun...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baharimda-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilemma', 'dilemma-zuhal-aksulu-4znst', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğru olan ne ki şu hayatta

İstediğine ulaşmak bu kadar zorken

Laleler boynunu büker karşında,

Elinden bir şey gelmez onlar solarken

Madem hayat bir ikilem, ve

Mutluluk bu kadar uzakta

Anlamı var mı ki şu hayatın

Zaten ölmüşsün yaşarken', 'Doğru olan ne ki şu hayatta İstediğine ulaşmak bu kadar zorken Laleler boynunu büker karşında, Elinden bir şey gelmez onlar solarken Madem h...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilemma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğüm', 'dugum-zuhal-aksulu-uqjr3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim nemleniyor

İçim sızlıyor

Boğazımda bir düğüm

Beni boğuyor

Ama

Ağlayamıyorum

Beni seviyor

Hayır sevmiyor

Uğrunda öldüğüm

Beni bırakıyor

Ama 

Ağlayamıyorum', 'Gözlerim nemleniyor İçim sızlıyor Boğazımda bir düğüm Beni boğuyor Ama Ağlayamıyorum Beni seviyor Hayır sevmiyor Uğrunda öldüğüm Beni bırakı...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dugum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dear Love', 'dear-love-zuhal-aksulu-br9xu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Could I be so safe

In the darkness of the night

If I''ve never seen

The beauty of your eyes light

My heart''s so small

To keep your love in

I''ll always shout to call

Your beautiful name my dear lovin''

Give your hands to share the lovin''

Be my tender be my darling

Let me taste your lips like wine

Let it be to the end of the time

Will be greatest of all

Our love, if you believe in me and hold

My hands waiting for yours

And all the secret in my soul', 'Could I be so safe In the darkness of the night If I''ve never seen The beauty of your eyes light My heart''s so small To keep your love in I''...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dear-love-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-zuhal-aksulu-omau5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaprakları dökülüyor yüreğimin

Baharın ortasında...

Zamansız açan çiçekler gibi! 

Pınarları kurudu gözlerimin

Kışın ardında....

Susuz kalan çöller gibi!', 'Yaprakları dökülüyor yüreğimin Baharın ortasında... Zamansız açan çiçekler gibi!  Pınarları kurudu gözlerimin Kışın ardında.... Susuz kalan ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zamansiz-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parçam', 'parcam-zuhal-aksulu-xn4ey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gideceğim hayatından

Kocaman bir parçamı sende bırakarak

Boşluğun öyle büyük olacak ki

Hiç kimse onu dolduramayacak...

Onu herkesten sakla olur mu

O hep seninle olacak

Payaşacak seninle saatleri günleri

Seninle byüyüp seninle yaşlanacak...', 'Gideceğim hayatından Kocaman bir parçamı sende bırakarak Boşluğun öyle büyük olacak ki Hiç kimse onu dolduramayacak... Onu herkesten sakla o...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/parcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-mehmet-ozer-ep03a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürüyorum sahilde

Dalmışım denizin rengine

Kumdan kaleler yaparım 

Dalgalar yıksalar bile

Gecelerin koynunda

Düşlerimi sayıyorum

İnan bana hiç uyumadan

Adını sayıklıyorum

Yalan söylüyorum yalan

Aslında hiç sevmiyorum seni

Hiç özlemiyorum

Ne denizi ne kumsalı

Binanın bodrum katında 

Uyumak için direniyorum', 'Yürüyorum sahilde Dalmışım denizin rengine Kumdan kaleler yaparım  Dalgalar yıksalar bile Gecelerin koynunda Düşlerimi sayıyorum İnan bana h...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayal-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Liman', 'son-liman-zuhal-aksulu-xocs0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sığındığım son liman

Artık beni kabul etmiyor

Hayatında bana yer kalmamış

Usuldan gitmek gerekiyor

Çabuk geçiyor zaman

Bir an bile geri gelmiyor

Çare yeni sulara yelken açmakmış

Ufukta yitmek gerekiyor', 'Sığındığım son liman Artık beni kabul etmiyor Hayatında bana yer kalmamış Usuldan gitmek gerekiyor Çabuk geçiyor zaman Bir an bile geri gelm...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam Ve Keder', 'gam-ve-keder-mehmet-ozer-d5wop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gamlıyım kederliyim

Sevdiğimden dertliyim

Biçare olmuş yüreğim

Dermanım olur musun

Beni sevdan ile

Yakıp kavurur musun

Geceler üstüme üstüme geliyor

İnsanlar halimi neden hiç sormuyor

Gözlerim yollarda sevdiğimi bekliyor

Gel artık bir tanem bekletme beni

Dön artık sevdiceğim özledim seni

Bir gül goncası gibi

Kopardın attın beni

Şu karanlık dünyamın 

Işığı olur musun

Benim saf gönlümde

Yoldaşım olur musun', 'Gamlıyım kederliyim Sevdiğimden dertliyim Biçare olmuş yüreğim Dermanım olur musun Beni sevdan ile Yakıp kavurur musun Geceler üstüme üstüme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gam-ve-keder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyeceğim', 'diyecegim-hifzi-ozbekmez-64tha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda sokağını biri sorarsa

O adreste kimse yok diyeceğim

Kim güzel uğruna aşka yanarsa

Başına gelenler hak diyeceğim

Bir güzel söz ile kandırırlar bak

Sevdanın uğruna yandırırlar bak

Sonunda derler ki bunlar müstahak

Gözünün önüne bak diyeceğim

Yalandır sevdayla bakan o gözler

Yalandır aşk ile söylenen sözler

Çekilir mi bunca tafralar nazlar

Resimleri de yırt yak diyeceğim

Latifim senide kurtarır Allah

Demek ki dedirdi sana illallah

Bir gün herkes anlar belki inşallah

Kıymet kadir bilen yok diyeceğim

03 AĞUSTOS 2004 SAAT: 05:00', 'Sevda sokağını biri sorarsa O adreste kimse yok diyeceğim Kim güzel uğruna aşka yanarsa Başına gelenler hak diyeceğim Bir güzel söz ile kand...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/diyecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sen Gittin', 've-sen-gittin-mehmet-ozer-gngfn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gittiğin günden beri

Yaşamaz oldu gönlüm

Senden başka hiç kimseyi

Görmez oldu iki gözüm

İsmin düşmez dilimden

Ne gece de ne gündüz de

Adını sayıklarım 

Hem düşümde hem gerçekte

Belki dönersin diye

Umut ektim şu kalbime

Yağmurlarla suluyorum

Güneşin batma vaktinde', 'Gittiğin günden beri Yaşamaz oldu gönlüm Senden başka hiç kimseyi Görmez oldu iki gözüm İsmin düşmez dilimden Ne gece de ne gündüz de Adını ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ve-sen-gittin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarda Oynamalı', 'cocuklarda-oynamali-mehmet-ozer-as5rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki yarın olmayacak

Güneş hiç doğmayacak

O gül yüzlü çocuklar

Oyun oynamayacak

Bu dünya bizim için

Yaşanmaz bir hal alacak

Sevgi dostluk arkadaşlık

Anılarda yaşayacak

Unutma ki insanız biz

Sevmeli sevilmeliyiz

Çocuklar da oynamalı

Hep beraber gülmeliyiz

El ele hep birlikte

Çiçekler içerisinde

Türküler dilimizde

Bu dünyayı sevmeliyiz

Çocuklarda oynamalı

Hep beraber gülmeliyiz.', 'Belki yarın olmayacak Güneş hiç doğmayacak O gül yüzlü çocuklar Oyun oynamayacak Bu dünya bizim için Yaşanmaz bir hal alacak Sevgi dostluk a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuklarda-oynamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Masalı', 'sevda-masali-mehmet-ozer-pudhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tatlı bir sevda masalı ve masalın kahramanları

Yemyeşil bir ağaçta koklaşan muhabbet kuşları

Gördüğümüz zaman dalgalarla oynayan yunusları

Evlendiğimiz güne davet ettik sevdiğimiz dostları', 'Tatlı bir sevda masalı ve masalın kahramanları Yemyeşil bir ağaçta koklaşan muhabbet kuşları Gördüğümüz zaman dalgalarla oynayan yunusları E...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevda-masali-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-mehmet-ozer-410l5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şöyle bir ona baktım bir de kendime

Ne için gelmiştik niye doğmuştuk

Ben kendimi bulamamıştım belki 

Ama o  insanlara doğru yaşamayı

Dürüst insanların da bu hayatta var olduğunu

Kanıtlamak için gelmişti bu dünyaya

Saftı yüreği berraktı kalbi

Kötülük düşünmeyen yegane insanlardan

İlkiydi benim için

Ömrümde görmemiştim böyle birini

Tanıma fırsatım olmamıştı hiç

Belki de dönüm noktasıydı hayatımın

Nasıl yaşayacağıma karar vermek için

Birkaç tane amaç için uğraşmakta

Sevdiklerini mutlu etme çabasında

Mağrur bir adamdı o

Hani kalıbının adamı derler ya

Allah’ına kadar delikanlı

Yada alemin kralı

İşte bu sözlerin hepsi onun için

Söylenmiş gibiydi

Böyle olmasa bile bu sözlerin hepsi

Hiç çekinmeden söylenmeliydi 

Nitekim adam gibi adamdı

Üç tane kızı vardı,üç can parçası

Hedef belliydi ayaklarının üzerinde duran

Özgürlüğünü kazanmış

Yurduna ve yurdum insanına faydalı

Genç insanlar yetiştirmek

Topluma kazandırmak

Ve bunu başardığı zaman

O eşsiz hazzı tatmak

Yaşı aşmış olmasına rağmen kırkı

Hala üretebilme çabasındaydı

Ödün vermezdi prensiplerinden

O namussuz olacağına 

Arkasından dedikodu yaptıracağına

Yeğlerdi bu hayattan yok olmayı

Dostum ne düzeninden şaş bu dünyada

Ne uğruna savaş verdiklerinden

Ve ben seni hep böyle hatırlayayım

Değişirsen eğer görme tanıma beni

Seni tanıdığım gibi anımsayayım

İyi ki doğdun, iyi ki varsın

Doğum günün kutlu olsun

Hep mesut ol arkadaşım.', 'Şöyle bir ona baktım bir de kendime Ne için gelmiştik niye doğmuştuk Ben kendimi bulamamıştım belki  Ama o  insanlara doğru yaşamayı Dürüst ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/arkadas-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Optimizasyon', 'optimizasyon-zuhal-aksulu-9sihg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanrının zamansızca önüme koyduğu

Çözümsüz bir denklemsin

Yüzlerce kısıt var ortada

Ama amaç fonksiyon yok

Ne doğrusal programlama

Ne analitik şebeke prosesi

Çözümü yok

Yok bundan ötesi

Beynimin sınırlarını zorluyorum

Amaçsızca kalbimi yoruyorum

Yetmiyor beynimin kapasitesi

Çıkamıyor kalbimin sesi

Artık pes ediyorum

Bu problemden kaçıyorum

Çözümü yok işte

Yok bundan ötesi!', 'Tanrının zamansızca önüme koyduğu Çözümsüz bir denklemsin Yüzlerce kısıt var ortada Ama amaç fonksiyon yok Ne doğrusal programlama Ne analit...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/optimizasyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''dan', 'ankara-dan-zuhal-aksulu-254ne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yabancıyım bu şehirde

Zamansız geldim

Zamansız gideceğim

Bu kaosu, koşuşturmayı

Gürültü patırtıyı

Simiti ayranı

Asık suratları

Biliyorum özleyeceğim

Misafirim ben bu şehirde

Zamansız sevdim

Zamansız öleceğim

Gelmeyen dolmuşları

Kapılmış masaları

Çaldığımız şarkıları

Güldüğümüz anları

Bırakıp gideceğim', 'Yabancıyım bu şehirde Zamansız geldim Zamansız gideceğim Bu kaosu, koşuşturmayı Gürültü patırtıyı Simiti ayranı Asık suratları Biliyorum özl...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ankara-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ellerin Olmuşsun', 'sen-ellerin-olmussun-zuhal-aksulu-o23e6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitme diyemem ki

Sevmeni bekleyemem

Sen ellerin olmuşsun

Benim ol diyemem

Seni öldüremem ki

Sensiz gülemem

Sen ellerin olmuşsun

Bin kere ölemem

Bu ateşi söndüremem ki

Aşkını kalbimden sökemem

Sen ellerin olmuşsun

Geçmişi silemem', 'Gitme diyemem ki Sevmeni bekleyemem Sen ellerin olmuşsun Benim ol diyemem Seni öldüremem ki Sensiz gülemem Sen ellerin olmuşsun Bin kere öle...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ellerin-olmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-zuhal-aksulu-rrqym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana yazmayı seviyorum

Seni yazmayı seviyorum

Seninle hayatı

Yaşamayı paylaşmayı

Nefes almayı seviyorum

Sana gelmeyi seviyorum

Seni beklemeyi seviyorum

Seninle olmayı

Saatleri paylaşmayı

Geçen her dakikayı seviyorum', 'Sana yazmayı seviyorum Seni yazmayı seviyorum Seninle hayatı Yaşamayı paylaşmayı Nefes almayı seviyorum Sana gelmeyi seviyorum Seni beklemey...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seviyorum-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaka', 'saka-zuhal-aksulu-yabnr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat ne kadar şakacı

Sen bana en büyük şakasısın

Halime bakıp gülüyorum

Başkasının oyuncağını istiyorum

Zaman ne kadar aceleci

Elimden kayan hayatımsın

BEn sadece seyrediyorum

Günden güne ölüyorum', 'Hayat ne kadar şakacı Sen bana en büyük şakasısın Halime bakıp gülüyorum Başkasının oyuncağını istiyorum Zaman ne kadar aceleci Elimden kaya...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saka-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırçın', 'hircin-zuhal-aksulu-md345', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aldırma sen sözlerime

Bırak, çek git hadi! 

Bakma sen güldüğüme

Göremezsin ağlarken beni! 

İnanma seni sevdiğime

Sen başkasını sev tabi! 

Dokunamazsın yanan kalbime

Tutma boşuna ellerimi!', 'Aldırma sen sözlerime Bırak, çek git hadi!  Bakma sen güldüğüme Göremezsin ağlarken beni!  İnanma seni sevdiğime Sen başkasını sev tabi!  Do...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hircin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Getsemani', 'getsemani-i-brahim-dikmen-07ym4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamaya değer bulduğun yanılgıdır

düşüngüler bir anlam kayması

kendinle ayırınca yolları

kaybolursun sessizliğin gürültüsünde

ve getsemani''de bir başına kalırsın

Kültablanda biriktirdiğin yalnızlığındır

yecüc mecüc duygulardır gönlünü ağartan

tenindeki bedensel yargıların sıkılışıdır

içindeki bir mülteci haykırış

ve getsemani tek tanığındır

Bir avuç gözyaşıdır rüzgara verdiğin

sebebini herkesten sakladığın

yüreğin ayak izlerinden belli ki

yolunu kaybetmişlerin uğrak yeri

ve getsemani tek hatırlayanındır', 'Yaşamaya değer bulduğun yanılgıdır düşüngüler bir anlam kayması kendinle ayırınca yolları kaybolursun sessizliğin gürültüsünde ve getsemani''...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen']::text[], 8.5, '{"poet":"İbrahim Dikmen","poet_slug":"i-brahim-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gestremani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-zuhal-aksulu-k3y3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklemek zor değil

Geleceğini bildiğimde

Doğumunu bekleyen hamile gibi

Sancılı ama

Bu sancıdan kurtulacağını bilmenin keyfiyle...

Bilmediğimde ise

İdam kararını bekleyen mahkum gibi

Sonu ya senle

Ya da sensiz günleri getirecek olan ipte...', 'Beklemek zor değil Geleceğini bildiğimde Doğumunu bekleyen hamile gibi Sancılı ama Bu sancıdan kurtulacağını bilmenin keyfiyle... Bilmediğim...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beklemek-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinim Ağrıyor', 'filistinim-agriyor-cemil-coskun-x82t0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'efkarlıyım

elli yıldır filistinim ağrıyor

duvarlar dile geldi

susan dünyaya inat

cennet vadedenler 

yarattılar filistinde cehennemi

borçluyuz hepimiz

ömrümüzden bir çeyrek

filistinli çocuklara', 'efkarlıyım elli yıldır filistinim ağrıyor duvarlar dile geldi susan dünyaya inat cennet vadedenler  yarattılar filistinde cehennemi borçluyu...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/filistinim-agriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri', 'biri-zuhal-aksulu-xq8ke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne çok isterdim

Yalnızlıktan üşümüş ellerimle

Sıcacık kalbime dokunmayı

Gecenin en kuytusunda

Buğday tenine sokulmayı

İnan hocam çok isterdim

Hayatımı aydınlatacak ışığı

Işıl ışıl gözlerinde bulmayı

Gözlerime her baktığında 

Alev alev kavrulmayı

Belki de en güçsüz anımda 

Cevapsız sorular sormayı...

Ama biri çoktan sormuş

Ben daha yanamadan kavrulmuş

Benim çaresizce arayıp durduğum ışığı

Biri sende çoktan bulmuş

Sana benden daha çok sokulmuş

Ben daha ulaşamadan

O çoktan kalbine dokunmuş

O biri var ya hocam o biri

Yüreğimdeki tomurcuğu

Daha açamadan soldurmuş

Biri benden önce

Çoktan senin olmuş...', 'Ne çok isterdim Yalnızlıktan üşümüş ellerimle Sıcacık kalbime dokunmayı Gecenin en kuytusunda Buğday tenine sokulmayı İnan hocam çok isterdi...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biri-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla İşte', 'anla-i-ste-ali-aldemir-pud6v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben anlamam

Öyle yaldızlı laflardan

Elde çiçeklerle 

Sevgiliye kur yapmaktan,

Bunu bekleme

Girsede yüreğime sancılar

Vuramam kendimi şiirlere

Seviyorum seni diyemem,

Biz yürekten severiz

Hem de mertçe kızım,

Yazmaz kitabımızda

Öyle süslü laflar,

Biz sevdik mi

....Ekmeği sever gibi

Sever gibi toprağı ve taşı,

...Denizi

.......sever

..........gibi

............severiz

Sevdiğimizi,

Bizim sevdamıza düşkünlüğümüz

Düşkünlüğü gibidir

Bir bebeğin ana memesine,

Öyle sıcak

...Öyle yürekten ve içten

...Ve

....Öylesine

........masumca,

Gözümüzden sakınırız sevdamızı

Anamıza bile söyleyemeyiz

Adını yavuklumuzun,

..Ve

...biz

....sevdik mi

......Anla işte....', 'Ben anlamam Öyle yaldızlı laflardan Elde çiçeklerle  Sevgiliye kur yapmaktan, Bunu bekleme Girsede yüreğime sancılar Vuramam kendimi şiirler...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/anla-iste-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşböceğim', 'atesbocegim-zuhal-aksulu-9lqt7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık geceme bir ışık yaktın

Birden dünyamı aydınlattın

Tıpkı geceleri parlayan ay gibi

Oradasın, ışıl ışılsın

Ulaşılması imkansızsın...

Nerde görülmüş bir yıldızın

Gökten kopup yeryüzüne indiği...

İnemezsin, inmeyeceksin

Bu karanlığı sen bilmeyeceksin

Ama ben bekleyeceğim elbet

Birgün odama bir ateşböceği girecek

Senin kadar büyük, senin kadar parlak 

Senin kadar güzel olmasa da

Biliyorum onun ışığı bana yetecek

Hem o kadar uzak olmayacak

Elimde avucumda, yanıbaşımda...

Belki de beni sevecek

Yıldızlar sevemez ki

Gökten inemez ki

Ateş böceğim elbet

İçimdeki seni söndürecek..', 'Karanlık geceme bir ışık yaktın Birden dünyamı aydınlattın Tıpkı geceleri parlayan ay gibi Oradasın, ışıl ışılsın Ulaşılması imkansızsın... ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atesbocegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Çelişkilerin Kadını -2', 'celiskilerin-kadini-2-abir-zaki-p8alq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evet dostum, 

hatırlıyor musun beni? 

anımsıyor musun kendini anlatan kadını? 

sırlarını ve gizemlerini sana taşıyan 

cesurca herşeyini anlatan 

hatta, üstadım, kötü tercihlerini bile ittiraf eden kadını! 

Aşkını ve yüceliğini anlatacak şimdi sana... 

‘Nasıl bir aşka düşmeli bu kadın’ 

diye sorarsan eğer 

şu olur cevabım, okursan eğer; 

iki insanın bütünleştiği bir aşk olmalı 

birbirini tutuşturan kıvılcım 

sonsuza dek, yanyana, iki yol yaratmalı 

ikisini aynı kavşakta buluşturmalı 

kesişmeden, paralel olmalı yolları 

ve büyük olmalı ruhsal yakınlıkları... 

Evet arkadaşım, 

Tanrısal olmalı aşkları, 

aşk kendini anlatmalı 

bedenden daha çok 

zihinden ve yürekten akmalı 

dünyevi/yalandan olmamalı 

evrensel ve tertemiz olmalı 

dayanmalı zorluklarına 

paradoksun ve çelişkilerin 

çakışmamalı çizgileri 

yanyana durmalı 

ve aynı yönde gelişmeli 

ayna olup birbirini yansıtmalı 

çatışmadan yaşamalılar aşkı 

yanlızca karşıdakinin yansıttığını görmeli 

ve onda gördüğü güzelliği sevmeli... 

Evet dostum, 

düşününce kadın erkeğini 

tatlı kişiliğinde 

sözlerin her güzelliğinde görmeli 

ruhunun her köşesinde kadının 

arzulanmalı erkek dediğin 

çalmalı yüreğini kadının 

baştan çıkarmalı 

beyninde aşk yaratmalı 

her an işgal etmeli gözleriyle 

zekice konuşmalı 

ruhuyla okşayıp, sevişmeli 

Erkeğine kilitlenmiş hissetmeli kadın kenidini 

yalnızca onu sevmek 

ve ona aşık olmak için 

bu dünyaya gelmiş olmalı 

onunla bir geçmişi 

yada geleceği olması gerekmemeli 

tüm bunlar yazılmıştır zaten yıldızlarda 

yalnızca onu düşünmek bile 

en büyük tebessümleri yaratmalı dudaklarında 

ve bir pırıltı kondurmalı gözlerine! ... 

Evet arkadaşım, 

heryerde olmalı gözleri erkeğinin 

bitirmeli kadını tamamen 

tüketmeli tüm düşlerini 

eritmeli yüreğini 

ve bulmalı ruhundaki derinliğini 

Bir şarkı, bir film, bir şiir 

anımsatmalı onu 

kalan bir ömür boyu... 

İlk akla gelen olmalı uyandığında 

sıcak bir günün başladığında 

en son kalan olmalı 

düşlere daldığında 

ve şükretmeli Yaratana 

onu yarattığı için 

ve her düşünde onu var ettiği içi... 

Çeviren: M. Çelik 

***************************************************************************************

A Woman of Contradiction...2 

Yes my friend, 

remember me? 

remember the woman I told you about? 

the woman who conveys you 

secrets and mysteries 

who dares to confess to you, 

my master, of her ill choices 

now she wants to confess 

about her love and its sublimity… 

You may ask 

what kind of love she may fall into 

I would answer by saying that 

it is a kind where two individuals are whole 

the spark of their interaction 

creates two lines that follow 

in the same curve endlessly, side by side 

their lines are parallel, 

however, they may never cross path 

their physical distance is great between them… 

Yes my friend, 

it is a divine kind of love that expresses itself 

more from the heart and the head 

than it does from the body 

purely, not earthly 

enduring the complexities of paradox 

and contradictions 

for their lines never cross or meet 

standing side by side 

curving infinitely in the same direction 

mirroring each other

without confronting 

taking only what they see 

reflected in the other

and seeing the beauty in the other… 

Yes my friend, 

when she thinks of him, 

she sees him as a delicious person 

in every sense of the word 

he is everything desired in her soul 

he has seduced her heart 

and made love to her mind 

engaging in intellectual intercourse 

with him every time… 

She feels that she was destined to be with 

with the only soul on this earth 

she was born to love 

she doesn’t need a past with him

or a future... 

for all that has already been written in the stars 

just a simple though of him 

brings the biggest smile to her lips 

and put a twinkle in her eyes… 

Yes my friend, 

he is everywhere 

he has consumed her 

consumed her thoughts…

her heart…and her very soul 

a song, a movie, a poem 

will remind her of him for the rest of her life 

he is the first thought upon waking on a brand new day 

he is her last thought before falling into wonderful dreams 

and, 

she constantly thanks the Al-Mighty 

for creating him 

and that he exists even 

in her dreams…

PS: Bu şiirim orijinali aslında bir konuşma esnasında yazılmıştı.... ‘Aşkı’ tanıtmamı istenmişti ve ben aynen yazdığım gibi anlatmıştım ve hiç bir gün bu yazımı bir ‘şiir’ olarak görmemiştim....

Ama M.Çelik in yazdığı ‘Çeviri’ yi okuduğumda onun çok büyük bir emek harcadığını gördüm, ve ‘yazımı’ şiirleştirdiği için ona çok müteşekkirim...', 'Evet dostum,  hatırlıyor musun beni?  anımsıyor musun kendini anlatan kadını?  sırlarını ve gizemlerini sana taşıyan  cesurca herşeyini anla...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":141,"source_url":"https://www.antoloji.com/celiskilerin-kadini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Ver', 'karar-ver-murat-akcay-607z8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben çok kereler yılıdım sevda vurdu.

Ben çok kereler dert çektim çilem doldu

Sevda korkutur beni anla halimi

Yüreğim yanacak mı yine neolur söyle? 

Acılara katlanmalımı? 

Yüreğine yaslanmalımı? 

Gözyaşını saklamalımı cevap ver? 

Yoksa söyle vazgeçmelimi? 

Başlamadan aşk bitmeli mi? 

İyi düşün öyle karar ver....', 'Ben çok kereler yılıdım sevda vurdu. Ben çok kereler dert çektim çilem doldu Sevda korkutur beni anla halimi Yüreğim yanacak mı yine neolur ...', ARRAY['Türk Edebiyatı','Şiir','Murat Akçay']::text[], 8.5, '{"poet":"Murat Akçay","poet_slug":"murat-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karar-ver-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deryalarda Islık Nefesin', 'deryalarda-islik-nefesin-necmi-unsal-5s9z6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zirvesi hep bembeyaz, eteği yeşil

Cıvıl cıvıl bir dağın ezgisi sesin.

Bütün cümleler kısır, zihinlerde zil

Çalıyor; deryalarda ıslık nefesin.

Sensin bu kırık kalbin son tamircisi.

Sevgin bu mısraları yazar, yeşertir.

Sensin tutuk kalemin son emircisi

Hemen şiir yazmazsam sevdan gebertir.

25 Mayıs 2004 Salı, Danimarka-Køge 18.53

7+5', 'Zirvesi hep bembeyaz, eteği yeşil Cıvıl cıvıl bir dağın ezgisi sesin. Bütün cümleler kısır, zihinlerde zil Çalıyor; deryalarda ıslık nefesin...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deryalarda-islik-nefesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-bekir-gedikoglu-pegbm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret kaldım seninle dağlarda dolaşmağa

Ben gurbette kalmışım sense benden uzakta

Sensiz sesini neylem gam doluyor ruhuma

Telefon dahi etmem ölürüm şuracıkta

Hasret kaldım seninle mehtapta dolaşmağa

Yıldızları sayarak başbaşa konuşmağa

Ellerinden tutarak gözlerine bakmağa

Allahım fazlamıdır bunları yaşamağa

Hasretinden ölürüm her gece ağlıyorum

Bu derdime çare yok tek çaredir sevdiğim

Dualarım sanadır bir mucize beklerim

Geleceksen gel artık yeterdir çektiklerim

Antalya 10 Ağustos 2004', 'Hasret kaldım seninle dağlarda dolaşmağa Ben gurbette kalmışım sense benden uzakta Sensiz sesini neylem gam doluyor ruhuma Telefon dahi etme...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasret-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüya Daha Bitti', 'bir-ruya-daha-bitti-nihat-tasdemir-bgtbs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR RÜYA DAHA BİTTİ		

	Bir rüya daha bitti tan ağarmadan,

	Hayatın tam ortasında her şey yarım yamalak

	

	Bir rüya daha bitti 

	Kim bilir kaçıncı salisesinde,

	Hayatın hangi sahnesinde.

	Ve, bir rüya daha bitti. 

	Henüz uykuya bile dalmadan…

	

				

						Nihat Taşdemir', 'BİR RÜYA DAHA BİTTİ		 	Bir rüya daha bitti tan ağarmadan, 	Hayatın tam ortasında her şey yarım yamalak 	 	Bir rüya daha bitti  	Kim bilir ka...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-ruya-daha-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Günü Kuşluk Vakti', 'eylul-gunu-kusluk-vakti-necmiye-sarpkaya-1ccdu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmem hatırlar mısın  tanışmıştık eylül günü kuşluk vakti

Heyecanlı umutlu sevinçli biraz da mahcuptuk. 

Eritmişti yüreğimi bakışların kumsalların yakıcılığı gibi

Küçücük  umutlar mutluluğun büyüğünü biriktirirse 

Öylesine mutlu umutluyduk

Saklanmıştı  bulut perdeleri ardına dolunay

Yapraklar nazlı nazlı  terk ediyordu ağaçları 

Eylül şehzade görünümlü ayıydı yılın 

Eteklerinde köpürttüğü heyecanlarla yüzümde dolaşan

Uçuk kaçık duygulara kapılırım kırılgan eylüllerde 

Güneş geceye daha hızlı koşuyor benim sana koştuğum gibi

Gündüzü bulutsuz gecesi pürüzsüz göklerden kayan yıldızlar gibi 

Doluverdin gönlüme eylül kuşluk vakti

Gözlerin heyecan hasret umut içinde ışıl ışıl 

Oysa hüzünler  akıyor içime şimdi oluk oluk 

Kaldırımların sonbahar vurgunu sarı yaprakları gibi 

Titriyorum ayrılığın zemherisinde

Erken göç eden kuş sürülerinin kanat seslerinden oluşan 

Senfoniyi dinliyorum düşüncelerden arınarak

Bir pelikan hüznüyle yürüyorum eylüllere

Metropollerin gurbet kokan ıssız sokaklarında yürüdük el ele

Yol alındı sessiz beyaz geminin memleketine 

Senin biran bile yokluğun eylül sabahı benim için 

Gönlüm günlerin gecelerin serinliğine rağmen 

Yaşıyor çöl kumları sıcaklığını 

Özlemler bitmiyor  bitmiyor kavuşmanın hazzına rağmen 

Eylül günü kuşluk vakti tanışmıştık bilmem hatırlar mısın

El ele umut ağacından taze bir meyve koparalım

her şeye rağmen eylül günü taze bir meyve 



Necmiye Sarpkaya', 'Bilmem hatırlar mısın  tanışmıştık eylül günü kuşluk vakti Heyecanlı umutlu sevinçli biraz da mahcuptuk.  Eritmişti yüreğimi bakışların kums...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/eylul-gunu-kusluk-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinç Ve Keder', 'sevinc-ve-keder-sinan-erdogan-g44sf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün yalnızdı, sevince doğunca

Sebepsiz kahroldu zaman, saatler boyunca

İnsanlar yaşamak zorunda bu dünyada

Sevgiye muhtaç ama sevmeyi seven yok

Keder, mağrur dolaşır sahibi yanında

Boynu biraz büküktür amma; 

Asidir eğilmez başı el yanında,

Sevgiye muhtaç ama sevmeyi seven yok

Gölgenin tanrısına seslenir insan bilmeden

Tanrım al bunu benden huzur ver! 

Gölgenin tanrısı kızar buna,

Keder üstüne keder verir insana

Işığın Tanrısına haykırır insan bilmeden

Tanrım kahrolsun sevgisiz yürekler

Işığın Tanrısı kızar buna,

Beyhude, tendeki ateşi körükler

Tanrım sevmekten bihaber ruhlara; 

Dolu dolu şerbetinden ver yansın. 

Bir avuç sevdanın uğruna

Bütün alem küllerinden uyansın', 'Gün yalnızdı, sevince doğunca Sebepsiz kahroldu zaman, saatler boyunca İnsanlar yaşamak zorunda bu dünyada Sevgiye muhtaç ama sevmeyi seven ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevinc-ve-keder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Bitti', 'gun-bitti-sinan-erdogan-8gmuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bitti

Şimdi baykuşların zamanı

Sessizlik çığlık çığlık

Yırtar sisli karanlıkları

Işklar sarhoş 

Yıldızlar her gecekinden daha uzak

Bin yıllık maziyi ulaştırır bana

Şimdi o yıldız kimbilir nerde

Yakınlık mı daha uzak

Uzaklık mı daha yakın

Sönmüş güneşin solgun yüzüne

Bakamam ki gözlerim yok

Geride bıraktığım onca şeye

Ağlamak fayda eder mi gidenlere

Döndürür mü boşluktan geriye herşeyimi

Seni, beni, ikimizi, geleceğimizi...

Tamam inadıma arka çıkacak kalabalıklar var

Her şey hoş güzel, etrafta insanlar var

Seni düşünmemek için yeterince konu oluyor

Bazen anlamsız dalıyor gözlerim boşluklara

Bazen de nemli bulutlara yeniliyor gözlerim

Ya da televizyon izleyip

Saçma bir espriye kahkaha bile atıyorum ama

Ya gece olupta yatağıma yatınca

Seni düşünmeme kim engel olacak

Yağan yağmuru kim susturacak

Avcumda kanayan umutlarımı kim sevecek

Sabaha kadar üşüyen sırtımı kim örtecek

Sana dönmemek için kim dizginleyecek

Senin yaşadıklarında benzer mi

Rahat uyuyabiliyor musun 

Döne döne yatak dar geliyor mu sana da

Yoksa aynı yıldıza bakıp ben gibi

Ağlamamak için gözlerini mi sıkıyorsun? 

Ben sadace yüreğimi tutsak aldım

Gerisini sana bıraktım

Gözlerimi, aklımı, ruhumu

Onlar doyasıya senle

Hem ağlıyor, hem seni düşünüyor

Hem de hayalinle sevişiyorlar özgürce

Bir yüreğim bana mahkum

Seni unutmak için

Kimselere bir daha girecek kapı açmamak için

Senin mühürlediğin yerde

Bir daha mektup okunmayacak

Hiç bir zaman buruşturulup atılmaması için

seni seviyorum deli,

Ama sevgim aşamadı bazı engelleri

Delisin, deliyim ama oda yetmedi

Seni kendimden senden bile çok sevdim ama

Bu da yetmedi

Bir mor menekşe yetti sevdamın bitmesine

Elinden kana kana içti başkaları

Alay bile ettiler benle hatırlar mısın? 

Gururumun demirden kapıları kapandı

Açılmaz kilitlerle, yüreğim üzerine

Gururmu yenmek ne sana ne başkasına nasip olmaz

Ne de bana

Sana dönmemi gururumun cenazesine bıraktım

Gelip öldürür müsün?', 'Gün bitti Şimdi baykuşların zamanı Sessizlik çığlık çığlık Yırtar sisli karanlıkları Işklar sarhoş  Yıldızlar her gecekinden daha uzak Bin y...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/gun-bitti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Aşkı', 'kis-aski-sinan-erdogan-r61gj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşüncelerime zincir mi vurdun

Senden başkası girmiyor beynimin içine

Yalnız ben miyim böylesi karmakarışık

Yoksa bütün aşıklar böyle mi? 

Bir şeyler oluyor gülün pembe gülüşüne

Dünya sanki bir başka düşünce içinde dönüyor

Yalnız ben miyim  böylesi hayatla çelişik

Birlikte baktığımız eski yıldızlar nerde? 

Hani zaman herşeyin çaresi derler ya

Bende inanmak istiyorum buna

Yalnız ben miyim Yaralı yüreği ağlamaklı

Yoksa biten her aşkın ateşi böyle mi küllenir? 

Boşvermek geliyor içimden herşeye

Bırak herşey olduğuna varsın diyorum

Yalnız ben mi kandırıyorum kendimi yalanlarla

Yoksa her üzgün aşığın tesellisi mi yalanlar? 

Duran dakikalar saatleri kovalamıyor

Yemyeşil bir sızı içimde yazdan kalma

Yalnız baharda mı aşık olunur sımsıcak

Yoksa seni kış ortası sevdim diye mi bu sitem? 

Anımsadım şimdi o günü kar bembeyaz ve saf

Tüm kirlerini temizlemişti istanbulun ve yüreğimin

Seni tanımıştım o akşam yağan kar altında

Yüreğime beyaz bir sayfa açmıştım 

Gecenin tüm soğukluğuna rağmen sımsıcak

Yalnız ben miyim geçen güzel günlere bakıp

Yüreğinden akan yaşları gözünden taşan? 

Artık ne gece o eski gece senle dopdolu

Artık ne güneş o eski güneş yüzü alev alev

Herşeye yeni bir anlam vermem gerekecek

Hayata, kendime, sözlerime, yüreğime....

Yalnız ben miyim sil baştan hayata başlayan

Yoksa her biten aşk ardından böyle mi dönülür hayata', 'Düşüncelerime zincir mi vurdun Senden başkası girmiyor beynimin içine Yalnız ben miyim böylesi karmakarışık Yoksa bütün aşıklar böyle mi?  B...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kis-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtap', 'mehtap-i-smet-barlioglu-rm95k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben olmasam neye yararsın mehtap,

Kime kimi anımsatabilirsin parıltınla,

Ormana değip dokunuşunla,

Denize inişinle? 

Ben olmasam kimi büyüleyebilirsin

Görünüşünle? 

Seni gümüş bir tepsiye benzeten benim,

Gecenin sarıçamlarıyla seni buluşturan,

Sudaki pırıltılarına hayran olan,

Seni arada bir bulutların arkasına kaydırıp çıkaran.

İnan ki; seni bana muhtaç kılmış

Yaratan.

Baştanbaşa mehtap olsan neye yararsın

Ben olmadıktan sonra? 

Ben seni görmedikten sonra? 

İstediğince vur denize, kayıklara, yelkenlere,

Ben olmadıktan sonra

Görün

Göklere,

Yerlere.

Seni ben tepelere taç ederim,

Sevgiliye ben benzetirim seni,

Ben duygulanır dururum

Dallar, yapraklar arasında gezinmenden.

Olmasa ah benim bu mahzun yüreğim; 

Çevreni kuşatmasa çilelerle yüklü gecelerim; 

Serilmese denizlerim altına çarşaf gibi; 

Geriye ne kalır mehtaplığından? 

Sevenlerin seni baş tacı edinmesi

Saflığından.

(MİTİL OSMAN isimli Serbest Şiirler ''inden > 13-14/100)', 'Ben olmasam neye yararsın mehtap, Kime kimi anımsatabilirsin parıltınla, Ormana değip dokunuşunla, Denize inişinle?  Ben olmasam kimi büyüle...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mehtap-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-sinan-erdogan-xgcjr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gülüşü bin yalana açılır gözlerinin

Her sözün bin umut eker hayal zincirlerine

Yüreksiz aslanlar kaplamış beynimin çöllerini

Umursamazlıklar içinde sarhoş bedenim 

Sineye çekemem hiç bir kötü sözü

Dilimde sivri iğneler var senden yana

Kim kem baksa yüreğimde ki saf pınarlara

Hemen geliverir isyankar cümleler dudaklarıma

Kuşkusuz sende ben gibi yapardın....

Firari gözlerimde buğulu sevdan hapis

Yağmurlu günlerde anarım sevdamızı

Solmaya yüz tutmuş bir çiçek görsem hemen

Anılarım tekrar canlanır sararmış defterden

Bir kara bulut gibi doludur gözlerim

Yağmayı bekler sağanak sağanak

Şimşeklerim gözlerimde ki kör karanlıkta saklı

Kuşkusuz, bir fırtınayı tasarlar

Umudunu yitirmiş balıklar yüzmeyi bilemez ki

Bir damla yağmur suyunda

Oysa ben boğuldum senin sığ, benim sonsuz sevdamda...', 'Her gülüşü bin yalana açılır gözlerinin Her sözün bin umut eker hayal zincirlerine Yüreksiz aslanlar kaplamış beynimin çöllerini Umursamazlı...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isyan-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-i-smet-barlioglu-c6aqk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karlar içinde başım, alevler içinde gönlüm,

Gözlerim özlemlerle dolu yaş yerine,

Ayaklarımda demirden çarıklar,

Elimde bir demir değenek,

Çocukluğumu arıyorum sürünerek.

Ah, o anamın babamın sağ olduğu günler,

Ah, o aramakla bulunmayacak günler; 

Babama dağlar kadar güvendiğim,

Anama kaleler kadar sığındığım,

Ah, o her anlatılana inandığım günler,

Ah, o gözüme dünyanın en güzel şeyleriymiş

Gibi görünen

Çirkinlikler.

Tuzları tuz, biberleri biber olan çocukluğum,

Her sabahı bir yaratılış,

Her yaratılışı bir bayram,

Her bayramı bir oyun olan çocukluğum.

Başımda esen kavakyellerim,

Anında gerçekleşen hayallerim,

Ekmek eldenl, su göldenli günlerim,

Balonlarım, toplarım, bilyelerim,

Horoz gibi besleyip yemlediğim

Horozşekerlerim.

Hamur oklavasından kılıcım,

Bakır bir tastan yapılmış gürzüm,

Söğüt dalından atım,

Devlere karşı yaptığım savaşlarım,

Atımın terkisinde kaçırdığım Kral Kızları ‘m,

Kapılarına nağralarımla dayandığım Kaf Dağı ‘m,

Kulaklarıma küpe olarak taktığım kiraz, vişne,

Titreyen ayaklarımla seni arıyorum çocukluğum,

İki gözüm iki çeşme.

(MİTİL OSMAN isimli Serbest Şiirler ''inden > 15-16/100)', 'Karlar içinde başım, alevler içinde gönlüm, Gözlerim özlemlerle dolu yaş yerine, Ayaklarımda demirden çarıklar, Elimde bir demir değenek, Ço...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cocuklugum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Emre', 'yunus-emre-i-smet-barlioglu-q9l8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Garibim… Yunus Emre ‘m…

Ilık bir seher yeli gibi bu dünyadan vurup geçenim,

Ardında sönmez alevler bırakanım,

Gönülleri yakanım,

Gözleri ağlatanım…

Neden bu sular senin gözyaşların gibi geliyor bana? 

Neden seni söylüyor bu köprü aşan ırmaklar? 

Bu yağmurlar, bu rüzgarlar,

Doğunca; güneşler,

Yağınca; karlar,

Neden bir şeyler getiriyor senden bana? 

Sağ ikeninden daha da bir sağ değil misin? 

Anlatsana.

Bir lokmaya, bir hırkaya bir ömür tüketenim,

Mürşidim, erenim,

Sözünü davranışında gösterenim,

Eli doğrum, boynu eğrim,

Bu dünyaya çırılçıplak gelip

Kervanlar yükü miras bırakanım.

Öylesine işlemişsin ki; dağa, taşa, toprağa,

Öylesine işlemişsin ki; kuruya, yaşa, yaprağa

Gayri, ondan öte gerek bile kalmamış

Konuşmana.

Sus, seni dinleyeyim akşam rüzgarlarında,

Malda, mülkte, hırkada, kürkte,

Denizdeki ayışığında dalıp dalıp çıkan kürekte,

Mezarlıklarda boy atmış gelinciklerde,

Kavaklarca uzanmış minarelerde.

Sus, seni dinleyeyim

Heryerde.

(MİTİL OSMAN isimli Serbest Şiirler ''inden > /17-18100)', 'Garibim… Yunus Emre ‘m… Ilık bir seher yeli gibi bu dünyadan vurup geçenim, Ardında sönmez alevler bırakanım, Gönülleri yakanım, Gözleri ağl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yunus-emre-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sinan-erdogan-ws2k5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen, tatmadığım duygularım,

bilemediğim umutlarımsın.

Sen, görmediğim düşlerim,

Kurmadığım hayallerimsin.

Sen dokunamadığım yüreğim,

Söyleyemediğim sırlarımsın.

Sen, duymadığım hasretim,

Açtıramadığım goncamsın.

Sen akıtmadığım kanım,

Yaşamadığım korkularımsın.

Sen, yanmadığım günahlarım,

Yazmadığım şiirimsin.

Sen bestelemediğim şarkım,

uyuyamadığım gecelerimsin.

Sen, ağlamadığım gözyaşım,

çözemediğim gizemlerimsin.

Sen söndüremedğim ateşim,

Yapmadığım hatalarımsın.

Sen, susturamadığım içimdeki ses,

İstemediğim kuşkularımsın.

Sen, gizlemediğim sevdalım,

Bende sensin, cansın.

Sen,illaki sen işte, varsın:

sebepsiz, 

hesapsız,

sualsiz,

şüphesiz,

riyasız,

zamansız,

hayasız,

Sen, herşeyimde varsın

Sen, canımda can

Tenimde ateşsin

Sen, herşeyimde varsın, olacaksın daima...', 'Sen, tatmadığım duygularım, bilemediğim umutlarımsın. Sen, görmediğim düşlerim, Kurmadığım hayallerimsin. Sen dokunamadığım yüreğim, Söyleye...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-448-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mevsimi', 'huzun-mevsimi-meltem-kaya-4znh3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehir vurmasın yalnızlığı yüzüme

Gökyüzü böyle susmasın! 

Her bahar açmaz mı dağlarda

...tomurcuklar? 

Umut ağlar mı hiç yüreklerde?', 'Bu şehir vurmasın yalnızlığı yüzüme Gökyüzü böyle susmasın!  Her bahar açmaz mı dağlarda ...tomurcuklar?  Umut ağlar mı hiç yüreklerde?...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/huzun-mevsimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarsız...', 'umarsiz-sinan-erdogan-xjs3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canıma kastı var geçmeyen saatlerin

Nefesim düğümlenir boğazıma her bir saniye

Paylaşmaya hazır değilim seni bir başka gözyaşıyla

Gözyaşımı hapsettim bu yüzden saatlere 

Şimdi ne geçiyor aklından bir bilsem

Ben nerdeyim sende seninle miyim? 

Yoksa öylesine geçmeyen zamanı 

Öylesine geçirmeye mi çalışıyorsun umarsız

Sesler bir duvar ördü önüme çığlık çığlık

Yağmur getirdiği oyuncakları dağıttı bir bir yeşile

Şen şakrak her yaprak kendi dalında 

Benim yapraklarım solmak üzere bahar ortası

Gitmeyecek biliyorum bu kezde ayaklarım

Kalmaya mahkum bu topraklarda senle

Kelepçelerin öylesine acımasız bir yerde ki

Çıkarıp atsam ölürüm, çıkarmazsam yine ölüyüm.', 'Canıma kastı var geçmeyen saatlerin Nefesim düğümlenir boğazıma her bir saniye Paylaşmaya hazır değilim seni bir başka gözyaşıyla Gözyaşımı ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umarsiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğe Özlem', 'genclige-ozlem-i-smet-barlioglu-6243l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah gençliğim…

Delikanlılığım…

Baro baro zamanım benim…

Böyle mi geçip gidecektin bir bahar seli gibi? 

Böyle mi kayacaktın rüzgar gibi, avuçlarımdan? 

Ben seni böyle mi arayacaktım

Bulunmaz Hin Kumaşı gibi? 

Böyle mi girecektin düşe dönen gündüzlerime? 

Yine ormanların sisidir ki indi

Gözlerime.

Bir türlü bilip anlayamadım

Her solukta, her adımda benden uzaklaştığını

Günlerim az gelirken yaşamaya,

Uykusuzluk, parasızlık, yorgunluk vızgelirken,

Çiçeklere, ağaçlara, ormanlara, denize,

Güneşe, aya, yıldızlara

Gönül verirken.

Boy-bosta fidanlık, serde yakışıklılık…

Bilemedim ki; gün gelip sonlar bulacak

Sultanlık.

Yaş olup yürüdün gözlerime,

Kemiklerime işledin sızı olup.

Sen; bedenimin ilk gözağrısı…

Sen; benim zorlulara ilk isyanım…

Sen; benim, yaşlılığımda sığınmaya çalıştığım

Dermanım.

Ah gençliğim…

Ah, o topun, tüfeğin işlemediği günlerim…

Ah, o denize kürek, göklere direk olduğum günlerim…

‘Bugün yerim, içerim, yarına Allah kerim.’

Dediğim günler…

Sana ne kadar yakın gelirdi, bana varılmaz gelen

Enginler.

(MİTİL OSMAN isimli Serbest Şiirler ''inden > 19-20/100)', 'Ah gençliğim… Delikanlılığım… Baro baro zamanım benim… Böyle mi geçip gidecektin bir bahar seli gibi?  Böyle mi kayacaktın rüzgar gibi, avuç...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/genclige-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gülleri taze tut', 'sen-gulleri-taze-tut-umut-gungor-6dfnr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gülleri taze tut,

Kurutma çiçeğimi,

Ümidini güçlü tut,

Bırakma yüreğimi.

Ben göklerde bulutum,

Aç gönlüne yağayım,

Dolu dolu yağmurum,

Aç kalbini yağayım.', 'Sen gülleri taze tut, Kurutma çiçeğimi, Ümidini güçlü tut, Bırakma yüreğimi. Ben göklerde bulutum, Aç gönlüne yağayım, Dolu dolu yağmurum, A...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-gulleri-taze-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit', 'sehit-i-smet-barlioglu-4wx28', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben şehidim.

Gömülmüşüm bu kutsal topraklar için

Karatoprağa,

Anlatılması olanaksız özlemler içindeyim

Güneşe, yağmura, dala, yaprağa

Ve henüz körpe baharlar içindeki gençliğime.

Beni selamlar, saygılar içinde indirdiler bir sabah vakti

Kabrime.

Bir hain kurşuna rastgelmiş zavallı yüreğim,

Yüreğimi değil,

Sevdamı, karasevdamı kurşunlamışlar,

Dönüşümü bekleyen anama, babama, yavukluma acımamışlar,

Kırmışlar kolumu-kanadımı, yarınlarımı,

Kirli bardaklarda içmek için akıtmışlar

Kanımı.

Öldüğüme mi yanarım sanıyorsunuz, vatan uğruna? 

Yanmam bre kardeşim, yanmam,

Sağ olsam; yine veririm canımı vatan için,

Yine razı olurum bu topraklara düşmeye.

‘Can’ Dediğin nedir ki; anam-babam? 

Vatan için değmez mi

Verilmeye? 

Kanım, içtiği su kadar helal olsun vatanıma,

Billur gibi suyunu içmişim ak-pak kaynaklarından,

Nur gibi güneşinde büyümüşüm, boy atmışım,

Aşını-ekmeğini yemişim.

Çok şey midir

Pusu kurmuş bir gün hainler kutsallığıma; 

Ölmüşüm? 

Ben şehidim.

Canımı verdim bu topraklara,

Canım ki; canlardan aziz,

Son soluğumu verdim son tekbirlerimle

Olmadığından verebilecek başka tek şeyim.

Yaşam için en gerekli şey can,

Candır bu kutsal vatana yapılabilecek

En büyük

İkram.

(MİTİL OSMAN isimli Serbest Şiirler ''inden > 23-24/100)', 'Ben şehidim. Gömülmüşüm bu kutsal topraklar için Karatoprağa, Anlatılması olanaksız özlemler içindeyim Güneşe, yağmura, dala, yaprağa Ve hen...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sehit-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelince Aklıma', 'sen-gelince-aklima-sinan-erdogan-km1v7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığına çare yok değil mi bitanem

Hasretin acısını yamasanda gecenin ayazına

Hemde kanata kanata saplasan iğneyi

Ne gecenin umrunda yalnızlığın ne de yıldızların...

Biliyorum çalındı hayatından bir çok güzellik

En değerli anların solup gitti sessizce

Yalnızlığına çare yok mu bu gecede? 

Kanatacakmısın yine elinde ki iğnenin ucunu

Zamanı durdurmaya ne dersin? 

Hayal değilmi sadece komik bir hayal

Zaman durmaz sende biliyorsun.

Acını çekmekten başka yol yok gibi

Sanki ben yalıtıyor gibiyim kendimi

Acımızı demeliydim.

Kusura bakma senin acın daha büyük geldi bir an

Yaşanmışlıklarda ısıtmıyor bu gece içimi

Sesini düşlüyorum, sımsıcak sesleniyor bana

Bir şiir okuyorsun adımı anmadan bu sana diye

Ben biliyorum kıskanç baykuşlara söylemediğini

Tat vermiyor yaşadığım hiç bir şey

Ne umutsuz umutlar

Ne yaşanacak yarınlar

Sen yoksun bir de ben yokum

Yokluklar içinde yok oldum bende.', 'Yalnızlığına çare yok değil mi bitanem Hasretin acısını yamasanda gecenin ayazına Hemde kanata kanata saplasan iğneyi Ne gecenin umrunda yal...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gelince-aklima-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım', 'alistim-sinan-erdogan-iqqmx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alıştım sensiz gecelerin karanlık nefesine

Alıştım yüreğimi didikleyen hasretine

Alıştım seni sadece hayallerimde sevmeye

Yinede sensiz olmuyor be bahar yüzlüm

Alıştım duygusuz ellerin değişine

Alıştım sevgisiz gözlerin gülüşüne

Alıştım kiralık tenlerin sahte sevişine

Yinede sensiz olmuyor be bahar yüzlüm

Alıştım yollarda yalnız gezmeye

Alıştım her gördüğümü sen zannetmeye

Alıştım artık geri dönmeyeceğine

Yinede sensiz olmuyor be bahar yüzlüm', 'Alıştım sensiz gecelerin karanlık nefesine Alıştım yüreğimi didikleyen hasretine Alıştım seni sadece hayallerimde sevmeye Yinede sensiz olmu...', ARRAY['Türk Edebiyatı','Şiir','Sinan Erdoğan']::text[], 8.5, '{"poet":"Sinan Erdoğan","poet_slug":"sinan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alistim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut dedin kurut gülü yaprağı', 'unut-dedin-kurut-gulu-yapragi-umut-gungor-exptp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unut dedin kurut gülü yaprağı,

Bırak git tutmasın dalı toprağı,

İstersen dersinde sevda alçağı,

Diyerek ihanet oyunundasın.

Kır diyorsun gönül çiçeğini,

Düşünme aşkının geleceğini,

Bekleme sevdanın içeceğini,

Diyerek vurgunların yolundasın.', 'Unut dedin kurut gülü yaprağı, Bırak git tutmasın dalı toprağı, İstersen dersinde sevda alçağı, Diyerek ihanet oyunundasın. Kır diyorsun gön...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unut-dedin-kurut-gulu-yapragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BIR e ulasabilmek, BIR i paylasabilmek...', 'bir-e-ulasabilmek-bir-i-paylasabilmek-hikmet-feridun-demir-liybn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''''''''Hangi zamanda yaslandı, 

Eğdi ki boynunu bir devrimci, 

Ne zaman caydı ki yüreğinden...! ?

Haldun Hakman dan alinti..''''''''''

Iste gercekleri yansitan üc cümle, bir seye inanmak, bir seyi his edebilmek, her ne olursa olsun cayamaz ki insan.. 

Eger onu günü kurtarmak icin veya günün modasi olarak görmüs ise elbetteki döner. 

Devrimin özü, baris, dostluk,paylasim,ortaklasa cevreyi paylasabilmek ve gelecek nesile yasanir bir dünya birakabilmek..

Hem yasamak hemde yasatabilmek.. 

Yoksa kan, intikam, silah, yok olmak, yok etmek, mevcudu imha etmek devrimcilikle ilgisi alakasi olmayan deyimlerdir..

Dinler doguslarinda devrimci idiler..Ama hedeflerine ulasamadilar..

Dinlerdeki devrimci ve paylasimci öz dogrultusunda gelisim devam edebilse idi, dünya daha farkli bir yerde olurdu..

Dinler yozlastirildi..

BiR, birlik olabilmek ve birlikte yasam, sevgi saygi ve paylasim ilkeleri özünden saptirildi, birileri kendi cikaralarina kullanmaya basladilar..

Asil hata bu idi.. 

BiR e ulasabilmenin yolu, birlik, sevgi, saygidan ve 

BIR i paylasabilmekten gecer..

Tembelligin burda yeri yoktur. 

Silahin ve iskallerin siddetin hele yeri hic yoktur. 

Dinin birlik cagrisi altinda, sanki iskal ve gasp politikasiymis gibi yansitilmasi, toplumun yasaminin bir parcasi olan ruhsal öze karsi tepkileri ortaya cikardi..

ve sonunda sevgi ve dostluk ilkeleri hice sayildi..

Sevginin insan yasamindaki yeri ekmek ve sudan da önemlidir..

Sevgiyi icinde barindiran bir beyin, suya ve ekmege ulasir ve onu paylasirda... 

Cogu kisi sanki devrimci olmak inacsizlikmis gibi, gadarlik ve duygusuzlukmus gibi adediyor. Tabii birilerinin de isine geliyordu, bu siyasetleri yaymak...

Devrimci öz, iste dinlerdeki BIR e ulasabilmenin özüdür.. Devrimci hareketlerde yapilan yanlisliklarda, bu özün göz ardi edilmesi ve siddet denen meredin ön plana cikarilmasi olmustur..

Bir tepkidir..Bu tepki aslinda bir sapmadir..

Ta 250 yil evvel baslayan teorik sapmalardir. Siddetle güzel olani getirmek..Ne kadar mantiksiz bir düsünce..

Siddet siddeti dogurur..

Dogan siddet de iki misli siddet uygular... 

Nasil olurda güzellikler, ülesim ve sevgi kanla yazilabilir..

Böyle bir seyin mantigi olabilirmi..

Nasil olurda, kutsal olan insan yasaminin (her canlinin da hakki olan yasama hakki)    birilerinin teorilerini dogrulamak icin gasp edilebilir veya imha edilebilir. Nasil olurda devrimciyim diye eline silahi alabilirsin..O silah birilerinin yasama hakkini imha icin icad edilmistir..

Kimse demesin ki kendi savunmam icindir..

Bizler er veya gec yasamimizi tamamlayacagiz..kimse ebedi degildir..

Ebedi olan seyler, sevgi ve ask ile ebedilestirilmis birlikten yana olan güzel duygulardir..

Bize bu güzel duygular isik tutuyor ise ve yasamimizi ve tüm yasayanlarin yasamlarini güzellestirecek seyler yapabiliyorsak o zaman devrimci bir anlamimiz vardir.. 

Abidin Dino ya sormuslar, Kominizm yikildi diye..Dino cevaplamis, olmayan sey nasil yikilir..

Evet olmadi ki hic.. 

Feodalizmin,Kapitalizimin ve Emperyalizmin bize asiladigi kültürlerin etkisinde yasayan bizler, nasil olurda paylasimciligimizdan ve BIR e ulasmaktan söz edebiliriz..

Bizler o kültürlerle daha temasda bile olamadik..o duygulari kabulullenmemiz icin..kimbilir belki daha insanligin 10000 yila ihtiyaci var..belkide daha 10 binlerce yil gerekecektir.... Güzel bir yasam icin..sevgi icin ask icin..Kendinize kendiniz icin iyi bakin..

EN  BÜYÜK DEVRIMCILER PEYGAMBERLERDI....! ! ! ! ! ! ! ! ! 

Saygilar sevgiler..''

Sevgili Haldun Hakman in '''' Sürekli Devrim Kokusu '''' siirinden esinlenme...', '''''''''Hangi zamanda yaslandı,  Eğdi ki boynunu bir devrimci,  Ne zaman caydı ki yüreğinden...! ? Haldun Hakman dan alinti..'''''''''' Iste gercekle...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-e-ulasabilmek-bir-i-paylasabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamışım', 'yasamisim-firat-yilmaz-tq49u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu mahalle benim benle yaşaya bildiğim

Bunu hep anımsadığım ve unutamadığım

Zıt bir çizgiydi hayatta.

Bende baş aktörü müydüm sandığım gibi? 

Unuttuğum yok muydu yaşayanlardan? 

Bencil oldum galiba kimi zaman.

Yapmadığım yaramazlıkları bana yükleyen bir arkadaşım vardı,

Birde sarı saçlarıyla dolandığım hayata bir kız.

Aynı sınıfa gittiğim komşunun haylaz oğlu

Kavga etmiştik bir sabah, yanlışlıkla kırmıştım kolunu.

Hasret teyzem börek yapmıştı,

Hala burnumda duran kokusunu içimize çekerek yerdik,

Birde paşa çayı yapardı bize, azımızı yakmadan içerdik

Evimizin karşısında bir park vardı

Çocuk yüreğimizle işgal etmiştik oyunlarımız için.

Büyüdüğümde bisikletim olacağı hissi hala içimde

O zaman bana haz verirdi, 

bisiklete binmek yerine koşardık bizde

Yakan top oynarken topa basmıştım bir gün

Düştüm tabi güm diye yere, kanadı da her tarafım.

Annem temizlemişti yaraları pamuktan elleriyle

İz bırakmış bak bende, bunu da yazmışım şiirime

Yani ben bir zamanlar çocukmuşum ve yaşamışım doya doya

Hüzünlerde tattım o zamanlar doğal olarak

Ve hissetmişim salise salise,

yaşadığımı anlamışım bu cehennem dünyada

2002', 'Bu mahalle benim benle yaşaya bildiğim Bunu hep anımsadığım ve unutamadığım Zıt bir çizgiydi hayatta. Bende baş aktörü müydüm sandığım gibi?...', ARRAY['Türk Edebiyatı','Şiir','Fırat Yılmaz']::text[], 8.5, '{"poet":"Fırat Yılmaz","poet_slug":"firat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasamisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M''için', 'm-icin-erdogan-ergin-7otzj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Upuzun bir ip sarılmış boynuna

Yaptıklarının ödülü bu soyuna', 'Upuzun bir ip sarılmış boynuna Yaptıklarının ödülü bu soyuna...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/m-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyı Bal Etse Güzel...', 'aciyi-bal-etse-guzel-i-brahim-ethem-bingul-8mzvy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin bitmeyen elemindeyim

Karanlığın girdabında kayboldum

Yaradan''dan yardım talebindeyim

Yârimin derdiyle bu gece soldum..

Gece benden, ben geceden dertliyim

Zaman sanki demir attı acıya

Dertlerime çare bulsun bir ilim

Tahammül zor, kalbimdeki sancıya..

Gürül gürül akan bu aşk suyunda

Dertler, veda edip sularla aksın

Sevgili şen olsun gönül yurdunda

Dilerim kalbinden mutluluk taşsın...

www.iebingul.com', 'Gecenin bitmeyen elemindeyim Karanlığın girdabında kayboldum Yaradan''dan yardım talebindeyim Yârimin derdiyle bu gece soldum.. Gece benden, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aciyi-bal-etse-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-erdogan-ergin-mlyib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorsun ya seviyorum seni, 

Direnen de yok sevgimize, 

Ne Mecnun’un çektiğini çektim, 

Ne de sen Leyla’nınkini … 

Bir peri masalı değil aşkımız, 

Ama yine de 

Büyüktür aşkımız, 

Özlediğimiz gerçektir birbirimizi 

Aşk için yeter be sevgilim.', 'Biliyorsun ya seviyorum seni,  Direnen de yok sevgimize,  Ne Mecnun’un çektiğini çektim,  Ne de sen Leyla’nınkini …  Bir peri masalı değil a...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gercek-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatsak', 'yatsak-erdogan-ergin-rcd8c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurumuş bir ağacın kökleri gibi, 

Su aramıyor ve inanmıyorsak eğer, 

Varlığın son gününde, tecellisini 

Beklesek, belki zamana değer. 

Umursamasak, yaşamayı dünyada 

Hep yatsak, yatsak, yatsak…. 

Sonra uyanmayacak mı bedenimiz? 

Sormaz mı hesap, ağrılarla? 

Ya Yaradana ne desek', 'Kurumuş bir ağacın kökleri gibi,  Su aramıyor ve inanmıyorsak eğer,  Varlığın son gününde, tecellisini  Beklesek, belki zamana değer.  Umurs...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yatsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleri..', 'geceleri-fatih-ozkonyali-bfdfk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayın şavkı vurur da yüzüme,

	    Öylece geçiririm ben geceleri.

	    Salar hicran zehrini göğsüme,

	    Öylece geçiririm ben geceleri.

             

                   Bilen olmasın içimde yanan koru,

	    Dilim de boynu bükük heceleri,

	    Gönlüm, olsun, sen bu hali koru,

	    Öylece geçiririm ben geceleri.

	    Can lüzum görmedi, ''bırak ne çıkar'',

                   Çözer dururum düğüm bilmeceleri,

	    Halime kefilim ne usanır ne bıkar,

	    Öylece geçiririm  ben geceleri.', 'Ayın şavkı vurur da yüzüme, 	    Öylece geçiririm ben geceleri. 	    Salar hicran zehrini göğsüme, 	    Öylece geçiririm ben geceleri.      ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yenice Açan Taze Goncadır', 'ask-yenice-acan-taze-goncadir-umut-gungor-s8mew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk yenice açan taze goncadır,

Bulunmayan dört yapraklı yoncadır,

Gönüle saplanan derin kancadır,

Aşk mevsimi olmayan bir çiçektir.

Düşmeyi bekleyen beşinci cemre,

Uyar gönüllerden verilen emre,

Yaşanır sığmaz yinede ömüre,

Aşk sevda ırmağında yıkanmaktır.', 'Aşk yenice açan taze goncadır, Bulunmayan dört yapraklı yoncadır, Gönüle saplanan derin kancadır, Aşk mevsimi olmayan bir çiçektir. Düşmeyi ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-yenice-acan-taze-goncadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitir Bu Aşkı', 'bitir-bu-aski-umut-gungor-vm6n7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tut kır kalemi yak kağıdı bitsin,

Savur aşk adına ne varsa yitsin,

Her dakika saattemi ölünür,

Yırt mektuplarımı yakıver gitsin.

Bu kadar fırtına bırakmaz bağır,

Sanırım duydun eh değilsin sağır,

Yardımına bütün nankörleri çağır,

Yetmezse git tüm zalimleri çağır.

Bitir bu aşkı sen güzelim bitir,

Benden ne varsa sende kaybet bitir,

Yüreği kalbimi gönlüde bitir,

Hatırayı anıyı yakıver gitsin.', 'Tut kır kalemi yak kağıdı bitsin, Savur aşk adına ne varsa yitsin, Her dakika saattemi ölünür, Yırt mektuplarımı yakıver gitsin. Bu kadar fı...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitir-bu-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Rüyası', 'ask-ruyasi-muammer-celik-pkasr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yükseklerde uçmak kadar 

derindir düşmesi 

derinliği kadardır

yalnızlık içinde üşümesi

BirDeli

05.08.2004

***Tülay Sustam Dostumun “Ben Yazdım, Sende Sil” isimli şiirine sonsuz teşekkürlerimle!', 'yükseklerde uçmak kadar  derindir düşmesi  derinliği kadardır yalnızlık içinde üşümesi BirDeli 05.08.2004 ***Tülay Sustam Dostumun “Ben Yazd...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-ruyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buldun oyuncağı', 'buldun-oyuncagi-umut-gungor-6v5bq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buldun oyuncağı oyna bakalım,

Dönüverde bir boyuna bakayım,

Denedim olmuyor nasıl çatayım,

Çok aradınmı sen bu oyuncağı.

Çevir döndür haydi kurda çalışsın,

Oyun dünyasına oda alışsın,

Ezberlet dersini iyi çalışsın,

Sahi çok aradınmı bu oyuncağı.', 'Buldun oyuncağı oyna bakalım, Dönüverde bir boyuna bakayım, Denedim olmuyor nasıl çatayım, Çok aradınmı sen bu oyuncağı. Çevir döndür haydi ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buldun-oyuncagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek Gibi Sevmek', 'erkek-gibi-sevmek-canan-palabiyik-a33aa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seveceksen erkek gibi seveceksin, 

''Seni Seviyorum'' dediğin zaman,

Gökler gürleyecek, 

Şimşekler çakacak, 

Yıldırımlar düşecek, 

Yağmurlar sel olup önüne çıkan her şeyi sürükleyecek. 

Seveceksen böyle sev dostum...

Sen sevdiğin zaman dalgalar yükselmeli,

Denizler kabarmalı,

Fırtınalar borana, 

Boranlar tayfuna, 

Tayfunlar siklona dönmeli.

Çatılar uçmalı direkler devrilmeli,

Yer gök birbirine girmeli,

Senin sevdiğini herkes böyle bilmeli. 

Sevince işte böyle seveceksin...

Devireceksin dağları,

Yıkacaksın kayaları,

Tersine akıtacaksın nehirleri,

Kurutacaksın gölleri.

Sevince işte böyle seveceksin...

Sevince, biraz da kadınına göre seveceksin... 

Kimi zaman zarif, 

Kimi duygulu, 

Kimi zaman bencil ve hoyrat,

Kimi zaman bir külhani gibi seveceksin, 

Ağzını açtığın zaman ana – avrat düz gideceksin,

Sövdüğün zaman yedi sülalesini ip gibi dizeceksin,

Sevdiğin zaman öyle bir seveceksin ki...

Kendin bile korkacaksın sevginden,

Dehşete düşeceksin ürkeceksin kendi sesinden. 

Seveceksen işte böyle seveceksin...

(Ocak 2003 / İstanbul)', 'Seveceksen erkek gibi seveceksin,  ''Seni Seviyorum'' dediğin zaman, Gökler gürleyecek,  Şimşekler çakacak,  Yıldırımlar düşecek,  Yağmurlar s...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/erkek-gibi-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzeri Duyulmaz Aşkım Var Sana', 'benzeri-duyulmaz-askim-var-sana-umut-gungor-wal0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benzeri duyulmaz aşkım var sana,

Kopyası olmayan şarkım var sana,

Sadece küçük bir şartım var sana,

Gözümden gönlümden uzakta olma.

Ferhat''ı Kerem''i geçip solladım,

Senin için şu dağları salladım,

Küçücük bir rica salıp yolladım,

Yanımdan yöremden uzakta olma.

Feryadımı gökte kuşa duyurdum,

Fermanımı gönül kuşa buyurdum,

Rüyana postalar ile uçurdum,

Gözümden kaşımdan uzakta olma.', 'Benzeri duyulmaz aşkım var sana, Kopyası olmayan şarkım var sana, Sadece küçük bir şartım var sana, Gözümden gönlümden uzakta olma. Ferhat''ı...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benzeri-duyulmaz-askim-var-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayrılı Bir Düş Sonrasında', 'sayrili-bir-dus-sonrasinda-alev-kutluozen-oq2jg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '…

bir çığlık düşer gecelerden

inceden inceye sızar kan

bilmem bu kaçıncı  yaylım ateşi

yüreğimi sızlatan

             henüz çektiremediğin

             onca zulüm varken

             bilirim…

             canımı almak istemediğini

                          kırdın kalbimi ey hayat! 

                          nasıl bağışlarım  seni…', '… bir çığlık düşer gecelerden inceden inceye sızar kan bilmem bu kaçıncı  yaylım ateşi yüreğimi sızlatan              henüz çektiremediğin  ...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sayrili-bir-dus-sonrasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantik Oyunu....', 'mantik-oyunu-hikmet-feridun-demir-izrd1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben beni seviyorum.

 Sen seni seviyorsun.

 Ben senden bir parcayim.

 Sen benden bir parcasin.

 Öyle ise sen beni seviyorsun.

 Öyle ise ben de seni seviyorum.

 Öyle ise biz onlari onlar bizleri seviyor.

 Öyle ise birimiz hepimizi, hepimiz birimizi seviyoruz.

..............

 Hikmet Feridun Demir herkesten bir parca.

 Öyle ise Hikmet Ferdiun Demir herkesi seviyor.

 :))))))))))))))))))))))))))))))))))))))))))))))))))))) 

BUNU KENDI KENDINIZE YORUMLAYABILIR VE TEKRARLIYABILIRSIN KENDI ADINIZLA...

DENEYINIZ.. COK FARKLI BIR DUYGUYA SAHIP OLUR INSAN....', 'Ben beni seviyorum.  Sen seni seviyorsun.  Ben senden bir parcayim.  Sen benden bir parcasin.  Öyle ise sen beni seviyorsun.  Öyle ise ben d...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mantik-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünce özlemiycem', 'olunce-ozlemiycem-metin-kose-5zlcx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölünce özlemiycem

Canlı cenazeleri

Dik sürüngenleri

Ölünce özlemiycem

Kirlenmiş nehirleri

Aptal dolu şehirleri

Ölünce özlemiycem

Görüpte susanları

Yiyip yiyip kusanları

Ölünce özlemiycem

Ankara

26.08.2004', 'Ölünce özlemiycem Canlı cenazeleri Dik sürüngenleri Ölünce özlemiycem Kirlenmiş nehirleri Aptal dolu şehirleri Ölünce özlemiycem Görüpte sus...', ARRAY['Türk Edebiyatı','Şiir','Metin Köse']::text[], 8.5, '{"poet":"Metin Köse","poet_slug":"metin-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olunce-ozlemiycem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeylere Takılıp Kaldı Umutlarımız', 'bir-seylere-takilip-kaldi-umutlarimiz-huseyin-tanrikulu-eg502', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şeylere takılıp kaldı umutlarımız.

Kağıtlardan yaptığımız gemiler battı, 

Ve unuttuk sevmeyi...

Şimdi ince kederler barındırıyoruz yüzümüzün en derin çizgilerinde.

Kendi başımıza senaryolar yazıp başrol oynuyoruz en dramatik sahnelerde.

Alınıyoruz yarin bir sözüyle,

Ve tüm ışıkları söndürüyoruz hayatın en anlamlı yerinde.

Bir dakika aydınlık için sürekli karanlık yaşayan ülkemde,

Elimizde umutlar çayda hüzün oynuyoruz.

Kim bilir 

Belki de budur hayatın anlamı:

Tüm dişlerimizi döküp, sadece çorba içebilmek

Ve deniz sandığımız bir bardak suya 

Birlikte bırakabilmek takma dişlerimizi; 

En huzursuz gecelerde sığındığımız ütopyalar adına...

									(2002/ANKARA)', 'Bir şeylere takılıp kaldı umutlarımız. Kağıtlardan yaptığımız gemiler battı,  Ve unuttuk sevmeyi... Şimdi ince kederler barındırıyoruz yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-seylere-takilip-kaldi-umutlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Geri', 'senden-geri-rahmi-aksoy-ov4uf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden geri saçlarım bir hayli ağardı

Yokluğunu  sığdırdığım yüreğe 

Varlığında sığardı 

Senden geri gözlerimde tufan var 

Şimdi temmuz titretiyor ellerimi 

Birkaç günde geçti birkaç yıl

şimden geri 

Birkaç günü bekliyorum birkaç yıl 

İç çeker gibi çekiyorum sigarayı 

Son duman 

Son nefestir 

Senden geri', 'Senden geri saçlarım bir hayli ağardı Yokluğunu  sığdırdığım yüreğe  Varlığında sığardı  Senden geri gözlerimde tufan var  Şimdi temmuz titr...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Aksoy']::text[], 8.5, '{"poet":"Rahmi Aksoy","poet_slug":"rahmi-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-E-cek-A-cak-', 'e-cek-a-cak-huseyin-tanrikulu-imlcw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelecek zamanlı cümleler için açıyorum artık kalemimin ucunu

“e-cek-a-cak” lara, sevgi dolu yüklemler bulmak amacındayım.

Kaç sevdaya düştüğümüz önemli değil, 

Bilakis; 

Kaç sevdadan düşmeden çıktığımız önemli.

Ve bir de anlamak önemli yazılan şeyleri

Yani sinem acırken sineme yazdığım şeyler

Anlaşıldı mı soğuk bir gecede soğuk vedalaşmalar yaşanırken? 

Aslında

Ne kadar gelecek zamanlı düşünülse de cümleler

Bir kere dilin geçmiş zamanıyla

“Çok özledim seni” denmiyorsa

-di- li geçmiş zamanla hüzün makamında

Sen istediğin kadar güzel yüklemler bul öznesi olmayan bir aşka...

										2001/ANKARA', 'Gelecek zamanlı cümleler için açıyorum artık kalemimin ucunu “e-cek-a-cak” lara, sevgi dolu yüklemler bulmak amacındayım. Kaç sevdaya düştüğ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/e-cek-a-cak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihir', 'sihir-melike-basbulbul-htyrf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saatlere kaydedilmemiş bir zaman yaşıyorduk birlikte.

Takvimlerde belirtilmemiş, sözü edilmemiş.

Ne Mart''ın 12''si, Ne de Kasım''ın 17''si.

Saat ne 9.30 ne de 12.49

Kimsenin yaşamadığı, hiç bir yerin yazmadığı 

Bir yol gidiyorduk birlikte.

Ne önde, ne arkada

Hiç bir yerde kimse yoktu.

Yalnız ''biz'' vardık, yalnız  ''biz''.

Zaman bile durmuştu o anda.

Güneş bile doğmayı sindirememişti içine

Ne ay gitti gökyüzünden,

Ne de parlayan yıldızlar.

Başında oturduğumuz şömine bile hiç sönmedi.

Sihirli bir değnek dokunmuştu sanki 

Sihirli bir değnek...

İki insana üç harf geliyordu.

Galiba bu sihre  ''AŞK'' deniyordu....', 'Saatlere kaydedilmemiş bir zaman yaşıyorduk birlikte. Takvimlerde belirtilmemiş, sözü edilmemiş. Ne Mart''ın 12''si, Ne de Kasım''ın 17''si. Saa...', ARRAY['Türk Edebiyatı','Şiir','Melike Başbülbül']::text[], 8.5, '{"poet":"Melike Başbülbül","poet_slug":"melike-basbulbul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sihir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan', 'nisan-huseyin-tanrikulu-pxjlf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereye düştüğünü bilmeyen bi nisan yağmuru altında, hangi sevdaya ağladığımın farkında olmak daha da acıtıyor içimi. Hazırlıksız, apansız bitivermiş bi nisan. Çıkılan yolculuğa hiç hazırlanmış bavullar var yanımda, içi ayrılık kokulu, biraz  naftalin beyazında. O gözler hep bana bakacak, o dudaklar hep benim dudaklarımda yavşayacak  diye düşünmenin salakça telaşından kurtulamamış bi nisan...

									(18.04.2003/ANKARA)', 'Nereye düştüğünü bilmeyen bi nisan yağmuru altında, hangi sevdaya ağladığımın farkında olmak daha da acıtıyor içimi. Hazırlıksız, apansız bi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nisan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islanayım Sevdanda', 'islanayim-sevdanda-huseyin-ciplak-6jnif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dermansız kaldım,yandım kor ateşte.

Ilık bir rüzgar eser sabahın seherinde,

Meltem kokusu gelir,ne hoştur...

Bu yola baş koyan,yine bu sevdadır.

Gel, özlem ve ayrılığı bertaraf et de gel! 

Sen bir yandan,ben bir yandan elele.

Gel buluşalım...

Sevgiler hasret oldu,yürekler boş.

Gel ki,bahar gelsin güzelim vatana.

Bu yola baş koyan,yine bu sevdadır.

Sen gelirsen güzellikler gelir,

Umut ve barış düşlenen dünyamda,

Kin, kavga silinir.

Senin sevdanı izlemek,cesarettir sevgili! 

Bu yola baş koyan,yine bu yürektir sevgili.

Sevdanın menekşesi sevgidir gülüm! 

Bil ki sevgili,

Kavganın yolunu barış saracak bir gün.

Bir gün,paylaşım,umut gelecek,

Bu yola baş koyan,yine buyürektir sevgili!', 'Dermansız kaldım,yandım kor ateşte. Ilık bir rüzgar eser sabahın seherinde, Meltem kokusu gelir,ne hoştur... Bu yola baş koyan,yine bu sevda...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çıplak']::text[], 8.5, '{"poet":"Hüseyin Çıplak","poet_slug":"huseyin-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/islanayim-sevdanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elmalı Şeker', 'elmali-seker-huseyin-tanrikulu-wjapl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynalardaki çaresiz bakışlarımıza, ıslak bahaneler uyduruyoruz elmalı şeker kıvamında

Hani yedikçe kazığı kalan avuçlarının arasında...

										(2002/ANKARA)', 'Aynalardaki çaresiz bakışlarımıza, ıslak bahaneler uyduruyoruz elmalı şeker kıvamında Hani yedikçe kazığı kalan avuçlarının arasında... 				...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/elmali-seker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Zaman Hüseyin', 'zaman-zaman-huseyin-huseyin-aksu-kb2zi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayalleri vardı bir zaman

Üzerinden geçti çok zaman

Sesiz kaldı uzun zaman

Esir oldu her zaman

Yinede sevdi zaman zaman

İnandı vazgeçmedi hiçbir zaman

Nihayet öldü son zaman', 'Hayalleri vardı bir zaman Üzerinden geçti çok zaman Sesiz kaldı uzun zaman Esir oldu her zaman Yinede sevdi zaman zaman İnandı vazgeçmedi hi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Aksu']::text[], 8.5, '{"poet":"Hüseyin Aksu","poet_slug":"huseyin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-zaman-huseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Kalmadı', 'sozum-kalmadi-tayyip-sag-xw7cp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni gördüm mızrabımda telimde,

Çiçek  oldun bahçemdeki gülümde,

Nida oldun zaman zaman dilimde,

Sana söyleyecek sözüm kalmadı.

Derdim karlı dağdan daha da yüce,

Gündüzüm karanlık geceden gece,

Sensiz geçen ömrüm ölümden nice,

Sana dayanmaya gücüm kalmadı.

Binip de gittiğin hasret treni,

Seninle beraber götürdü beni,

Bulunmaz zannetme sakın kendini,

Seni bekleyecek sabrım kalmadı.

Tayyip bu hasrete alıştı artık,

Gönül sarayımın kapısı örtük,

Sevdan kâretmiyor yüreğim yırtık,

Seni özleyecek özüm kalmadı.

                         2.3.2004', 'Seni gördüm mızrabımda telimde, Çiçek  oldun bahçemdeki gülümde, Nida oldun zaman zaman dilimde, Sana söyleyecek sözüm kalmadı. Derdim karlı...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sozum-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Değil de Nedir?', 'ask-degil-de-nedir-huseyin-tanrikulu-3ytwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir daldaki iki elma kadar bile uzak kalamıyorsam ellerine

Gözlerimdeki çocuk ıslak ıslak ağlıyorsa her gidişinde

Aşk değil de nedir peki bu hüznün adı? 

									2002/ANKARA', 'Bir daldaki iki elma kadar bile uzak kalamıyorsam ellerine Gözlerimdeki çocuk ıslak ıslak ağlıyorsa her gidişinde Aşk değil de nedir peki bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-degil-de-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Bir Gününü Bile...', 'biz-bir-gununu-bile-huseyin-tanrikulu-e3q3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz bir gününü bile yakalayamadık ama

Kaç mevsim geçti avuçlarımızdan

Kaç buluta taşıttık hüznümüzün ağırlığını

Hala aklımda yitişinin ardından bana kalan türkü

Kaçıncı nakarat bu gözlerin ıslaklığında söylenen

Şimdi hiçbir anlamı olmaz zannediyorsun kurulan cümlelerin.

Ama öyle değil,

Hala ağları çekebilirim ben mutluluğu yakalayabilmek adına.

Çünkü bir fırtına gördü diye denize küsenlerden değilim ben...

									(2003/ANKARA)', 'Biz bir gününü bile yakalayamadık ama Kaç mevsim geçti avuçlarımızdan Kaç buluta taşıttık hüznümüzün ağırlığını Hala aklımda yitişinin ardın...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biz-bir-gununu-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Ve Ondan', 'senden-ve-ondan-zulfikar-yapar-kaleli-vcsp4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbin alevine tutsağı demem 

Muhabbet ceminin mekânıyım ben 

Hasret bahçesinde gülü istemem 

Özgürlük dağının dikeniyim ben 

Ben bu memleketin divanesiyim 

Görüp yaşadığım, duyduğum ayıp 

Namus erbabının pervanesiyim 

Ülkemde hayânın hesabı kayıp 

Semanın altında, arşın üstünde 

Göçmenler evlere taşınmadılar 

Milletin yadında, devlet kastında 

Yollara yürüdük aşınmadılar 

Kalbimin içinde lambalar yanar 

Çoban kavalında hasret duygusu.

Ruhumun gecesi ışığa kanar 

Düşlerimde bir gerçeğin kaygısı 

Zehirli akreple kucaklaşarak 

Sevişmeden gönül evi seçilmez 

Çöl ve deniz, iki hasret, koşarak 

Bu yolda sende ve ondan geçilmez', 'Kalbin alevine tutsağı demem  Muhabbet ceminin mekânıyım ben  Hasret bahçesinde gülü istemem  Özgürlük dağının dikeniyim ben  Ben bu memleke...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senden-ve-ondan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten', 'ten-canan-palabiyik-04ybl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanrım! Nasıl bir duygu bu? 

Bir erkeğin tenine dokunmak... 

Bu erkek kadın için, 

Bir bedenden, bir ruhtan ötesini ifade ediyorsa... 

Çıplak, ama itici gelen bir çıplaklık değil. 

Bu ten, bu duruş, bu sadelik, 

Eski Yunan Tanrıları gibi... 

Hele o gözler... 

Ah! bana bakıyor, gözlerimin içine bakıyor, 

Ta ruhumun derinliklerine bakıyor sanki. 

Tanrım, bana yardım et! 

Bu gözlerde hiçbir duyguyu okuyamıyorum. 

Hakkımda neler düşünüyor acaba? 

O kendinden emin, 

O hiç çekinmeden ilan''ı aşk eden ben... 

Bu halimi görünce neler düşünüyordur şimdi? 

Birden omzuna dokunmak istedim. 

Ne kadar saçma! 

Neredeyse “omzuna dokunabilir miyim? ” diyecektim. 

Aklımdan geçen bu düşünce, 

Dudaklarıma bir tebessüm olarak yansıdı. 

O''da aynı şekilde bana gülümsedi. 

Bu sefer gözlerinden her duyguyu okuyordum. 

Beni seviyordu işte. 

Ruhuyla, bedeniyle kendini bana teslim etmişti. 

Elimi yavaşça kaldırdım, 

Parmak uçlarımla çıplak omuzlarına dokundum. 

Heyecandan ölüyordum. 

Sanki bütün kanım kalbime dolmuş, 

Bedenimde başka kan kalmamıştı, 

Damarlarım bu kadar kanı taşıyamayacak, 

Göğsüm yarılacak, bütün kan dışarı akacaktı. 

Üşüyordum biraz, 

Ama terliyordum da, 

O an “soğuk ter''in ne olduğunu ancak anladım. 

Omzuna dokundum ya, 

İşte o an onun bütün sıcaklığını hissettim. 

Parmaklarım buz gibiydi, 

Utandım... 

(Mayıs 2004 / İstanbul)', 'Tanrım! Nasıl bir duygu bu?  Bir erkeğin tenine dokunmak...  Bu erkek kadın için,  Bir bedenden, bir ruhtan ötesini ifade ediyorsa...  Çıpla...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ten-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhar Suya Dönüşünce...', 'buhar-suya-donusunce-huseyin-tanrikulu-jujrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buhar suya dönüşünce, usul usul senin üzerine akayım diye,

Kendi isminin üstüne yaz benimkini buğulu camlarında,

Ve silsen de izi kalsın isimlerimizin her güneş vurduğunda...

								(2001/ANKARA)', 'Buhar suya dönüşünce, usul usul senin üzerine akayım diye, Kendi isminin üstüne yaz benimkini buğulu camlarında, Ve silsen de izi kalsın isi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buhar-suya-donusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaydanlıktan Çıkan...', 'caydanliktan-cikan-huseyin-tanrikulu-4i4fb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çaydanlıktan çıkan bir buharım ben,

Bulduğu ilk cama yapışıp

Nice sevdaların baş harfini üzerinde taşıyan.

Bir yüzüğüm en güzel sözler verilirken parmağa takılan

Ve her aldatma öncesi

Dürüstlüğümden dolayı

Karışmayayım diye pis işlere

Ceket ceplerine konan

Uçmayı öğrenememiş yeni doğmuş bir serçeyim

Yere düşerken senin dallarına tutunan...

										(2001/ANKARA)', 'Çaydanlıktan çıkan bir buharım ben, Bulduğu ilk cama yapışıp Nice sevdaların baş harfini üzerinde taşıyan. Bir yüzüğüm en güzel sözler veril...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/caydanliktan-cikan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğini Söylüyorsun Ama', 'gittigini-soyluyorsun-ama-huseyin-tanrikulu-1i58o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittiğini söylüyorsun ama

Aslında ikimizde biliyorduk hiç gelmediğini

“Fazla kalmıcam geçerken uğradım” sevdalanmaları yaşadığını

Kalacağını düşündüğüm zamanlarda her yeri gözlerinin mavisine boyayan ben

Gecenin bi saatinde oturmuş

Gözlerinden damıtılmış acı içiyorum hala

Her ayrılığı boynumda bir atkı gibi taşıyan ben,

Bana bıraktığın ayrılığı yakıştıramıyorum şimdi hiçbir yerime

Oysa daha bir sürü kelime vardı ceplerimde senin için –hiç kullanılmamış-

Hepsini dağıtıyorum şimdi gelip geçen rüzgarlarla, saçma sapan cümlelerin orta yerine

Nasıl olsa oyun bitti artık, perde üzerimize kapandı

Söylemiştim sana her şairin bir intiharı var diye

İşte bu yüzden,

Biten aşklar için yarıya indirilmiş,

Mavi bir sevda bayrağının direğine asıyorum kendimi...

									(2002/ANKARA)', 'Gittiğini söylüyorsun ama Aslında ikimizde biliyorduk hiç gelmediğini “Fazla kalmıcam geçerken uğradım” sevdalanmaları yaşadığını Kalacağını...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittigini-soyluyorsun-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Dibi', 'hazan-dibi-huseyin-tanrikulu-aj58v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neresinden tutarsan tut, bir ucu elinde kalıyor hayatın

Suya düşen umutlara yüzme öğretmenin de anlamı yok

yarin ayrılığın mührünü vurup gittiği o gece sancılarında

Ayrılık çarpıyor yüzüne

Hiç bilmediğin bir şehirde, lise sevdalarının buluşma noktasında

Karşı masadaki insanlar tavuğun göğsüyle uğraşırken,

Sen kazanın dibinde buluyorsun kendini

Ve düşündüğün kadar tatlı olmuyor kazanın dibindeki ayrılık acısı

Sevdaya en meyilli zamanda

Kuşların bile döndüğü vakitlerde

Sen pılını pırtını topluyorsun bazı yüreklerden

Nerden baksan hüzün yani

Şimdi ne yazılabilir ki mutluluk adına bu turunç mevsimde

Hazan dibinden başka? 

									(2002/SAMSUN-ÇORUM)', 'Neresinden tutarsan tut, bir ucu elinde kalıyor hayatın Suya düşen umutlara yüzme öğretmenin de anlamı yok yarin ayrılığın mührünü vurup git...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazan-dibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rumeysa', 'rumeysa-cafer-petek-5mysy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'canım (ötesi var mı?)

keşke bilebilseydin

anla/

ya bilseydin

nasıl yanar yüreğim

dokunduğunda saçlarina ellerim

nasıl yanar

hayatım

ateş topları fırlatan

gözlerini gözlerimden

ellerini boynumdan

ve ayaklarını yere

ya da beni darağacından

indir

canım bilemezsin

hiçbir zaman avuçlarında

tutamadığın kar tanecikleri gibi

apak umutların

bir kapı zilinde eriyip

ateşten damlalar halinde

yapıştığında yüreğine

neden toprağın üstündese altının

daha cezbedici ve 

tahrikkar olduğunu bilemezsin

bilemezsin

henüz tazedir saçların

yorulmamıştır taranılmaktan

ve şımarmayı

oyunbozanlık etmeyi ve

nazlanmayı

en hak edecek yaştasın henüz

bilemezsin

küçüğüm bir tanem bilemezsin

yıldızlardan mahrum gecelerin

hüzünlü yanına doğru

yorgun umarsız neden

uzar sakallarım

ve değdiğinde toprağa uzayan sakallarım

bilemezsin neden

parmaklarım arasından seslenir

kızgın bazan da mütebessim

müşfik ölüm göz kırparak aynalardan

yosun gözlüm

ya sen olmasaydın

olmasaydı gözlerin öfkeme kın

saçların hayat bağım olmasaydı

ellerin ellerimde güneşten bir parça

ya sen olmasaydın

hırpalanmış yüreğimin merhemi

...ve işte küçüğüm

yetiştiğinde raflara boyun

kaybettiğinde şımarma hakkını

kalemle konuşmayı öğrendiğinde

anlaya/bileceksin

nasıl yandı yüreğim

dokunduğunda saçlarına ellerim

nasıl yandı

rumeysa', 'canım (ötesi var mı?) keşke bilebilseydin anla/ ya bilseydin nasıl yanar yüreğim dokunduğunda saçlarina ellerim nasıl yanar hayatım ateş top...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/rumeysa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR e Giderim..', 'bi-r-e-giderim-hikmet-feridun-demir-hk3sz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİR den geldim, 

BİR e giderim.

BİR i pay ederim.

Yine BİR i bulurum.

BİR e BİR eklerim.

Yine BİR  olurum.

BİR den geldim,

BİR e giderim...', 'BİR den geldim,  BİR e giderim. BİR i pay ederim. Yine BİR i bulurum. BİR e BİR eklerim. Yine BİR  olurum. BİR den geldim, BİR e giderim......', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-e-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delilik', 'delilik-burak-killioglu-vwfq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sus,

Konuşma! 

Sadece anlamsız bakın.

Belki de kurtuluş budur,

Gerisin geriye kaçmak...

Yalnızca itaat et,

Düşünmeyesin sakın

Akıl dediğin zaten

Deliliğe kapılar açmak...', 'Sus, Konuşma!  Sadece anlamsız bakın. Belki de kurtuluş budur, Gerisin geriye kaçmak... Yalnızca itaat et, Düşünmeyesin sakın Akıl dediğin z...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/delilik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gitmedikçe...', 'sen-gitmedikce-huseyin-tanrikulu-7pqpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gitmedikçe yüreğimden

İstediğin iklimine git ülkemin

Ben her yağmurla seni yüreğime yazdırabiliyorum hala

Her acıyışında içim 

Okkalı bir küfür savurup gittiğin diyara

Gamzelerinde sarhoş olabiliyorum gözlerinin siyahıyla

Aslında sorun 

Benim senin gözlerinde sarhoş olmam değil de

Senin benim gözlerimden bir yudum bile almamanda 

Ne yapalım 

Bizde susamanı beklicez

Ara sıra gelip gamzelerini gösterdiğin akşamlarda

Tabi güzel değil sevgi öksüzü bi insana böyle şeyler yazmak ama

Neylersin

Benim şair yanım 

Sana güzel kelimeler bulmak derdinde hala...

									(2002/ANKARA)', 'Sen gitmedikçe yüreğimden İstediğin iklimine git ülkemin Ben her yağmurla seni yüreğime yazdırabiliyorum hala Her acıyışında içim  Okkalı bi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gitmedikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Umutlarımı...', 'butun-umutlarimi-huseyin-tanrikulu-puf1p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün umutlarımı cebime koydum, gözlerindeki iklime koşuyorum.

Yeşil bi ölümdür şimdi ayrılığın yeni adı...', 'Bütün umutlarımı cebime koydum, gözlerindeki iklime koşuyorum. Yeşil bi ölümdür şimdi ayrılığın yeni adı......', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/butun-umutlarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Uykusamışlığıyla...', 'butun-uykusamisligiyla-huseyin-tanrikulu-bup12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün uykusamışlığıyla gelir sesin

İçimde çok eski bir yaraya dokunur

Ve ben sana bir türlü anlatamam

İçimdeki bu yaranın sensizlik kokusunu...', 'Bütün uykusamışlığıyla gelir sesin İçimde çok eski bir yaraya dokunur Ve ben sana bir türlü anlatamam İçimdeki bu yaranın sensizlik kokusunu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/butun-uykusamisligiyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Kıyısı Olan bi Hüzün...', 'denize-kiyisi-olan-bi-huzun-huseyin-tanrikulu-u774t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denize kıyısı olan bi hüzün var sinemde

Ve ben sinemdeki hüzünle

Hüzünde kelime sektiriyorum

Yüzünün unutulmaya başladığı bu alkol yüklü mevsimde...

									(19.08.2003/SAMSUN)', 'Denize kıyısı olan bi hüzün var sinemde Ve ben sinemdeki hüzünle Hüzünde kelime sektiriyorum Yüzünün unutulmaya başladığı bu alkol yüklü mev...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/denize-kiyisi-olan-bi-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüklemler Bile...', 'yuklemler-bile-huseyin-tanrikulu-ja6zx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüklemler bile yüklenmeye yanaşmazken

Elimdeki bu kadar devrik cümleyle

Nasıl anlatayım ki

Ayrılığın onulmaz yarasını? ...

										(2001/ANKARA)', 'Yüklemler bile yüklenmeye yanaşmazken Elimdeki bu kadar devrik cümleyle Nasıl anlatayım ki Ayrılığın onulmaz yarasını? ... 										(2001/A...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yuklemler-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı Sesleri Duyuyorum...', 'marti-sesleri-duyuyorum-huseyin-tanrikulu-wtg3w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Martı sesleri duyuyorum martın ortasında

Takalar geçiyor aklımdan hem de  Haymana Ovasında

Fatih’ ten bu yana karadan gitmiyor gemiler ama

Biz hala böyle tutunuyoruz hayata...

										(2002/ANKARA)', 'Martı sesleri duyuyorum martın ortasında Takalar geçiyor aklımdan hem de  Haymana Ovasında Fatih’ ten bu yana karadan gitmiyor gemiler ama B...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/marti-sesleri-duyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesadüf', 'tesaduf-huseyin-tanrikulu-zlnwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç gecedir yüzün geliyor hüznümün tam ortasına

Hangi tesadüf bu kadar yeşil olabilir ki

Ve hangi yeşil saplanabilir bi hüznün orta yerine? 

Sen istediğin kadar tesadüf de her akşam görüşmemize

Halbuki her akşam kaç otobüse binmiyorum ben içerisinde sen yoksun diye...

										(2002/ANKARA)', 'Üç gecedir yüzün geliyor hüznümün tam ortasına Hangi tesadüf bu kadar yeşil olabilir ki Ve hangi yeşil saplanabilir bi hüznün orta yerine?  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tesaduf-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Sen Değilsin', 'i-lk-sen-degilsin-huseyin-tanrikulu-zdft7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk sen değilsin yasaklayan sevgiyi

Ve ilk ben değilim yaşayan yasak bir sevgiyi

Zaten yıllar önce en güzel yanıtı vermişti

Koca bir dağın üzerine yavaş yavaş inen Ferhat’ın çekici...

									(2001/ANKARA)', 'İlk sen değilsin yasaklayan sevgiyi Ve ilk ben değilim yaşayan yasak bir sevgiyi Zaten yıllar önce en güzel yanıtı vermişti Koca bir dağın ü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-sen-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyileşmemiş Bir Yaranın...', 'i-yilesmemis-bir-yaranin-huseyin-tanrikulu-22m2g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyileşmemiş bir yaranın kabuğunu koparır gibi

Çekip gidiyorsun şimdi

Anılar kanıyor içimde

Ne zaman yağmur yağsa

Yüreğimi avuçlarıma alıp yıkıyorum gözlerinin suyu diye

Ellerim kanıyor...

									(2001/ANKARA)', 'İyileşmemiş bir yaranın kabuğunu koparır gibi Çekip gidiyorsun şimdi Anılar kanıyor içimde Ne zaman yağmur yağsa Yüreğimi avuçlarıma alıp yı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iyilesmemis-bir-yaranin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Kalkıp Gitsek Seninle', 'simdi-kalkip-gitsek-seninle-huseyin-tanrikulu-uylr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi kalkıp gitsek seninle

Aykırı bir sonbaharın yaprak desenli sahnesine

Elimiz terler mi zannediyorsun yaz sıcağında olduğu gibi? 

YALAN...

Bu kadar çabuk sevilmez bu çağda.

Saçın bir tek teliyle bağlanmıyor artık eller.

Alkol yüklü zamanlarda sarhoş sevdalar yaşıyoruz sadece,

“Seviyoruz” demelerimiz bile üç-beş bardağa meyilli, nara misali

Gözlerimin içine baka baka yüksek sesli yalanlar söyleme bana

Çünkü çeyrek asırdır seviyorum diye avaz avaz bağırdılar kulağıma

Sen beni susarak sev

Bırak dudaklarının arasından ben alayım o sözcükleri...

									(2002/ANKARA)', 'Şimdi kalkıp gitsek seninle Aykırı bir sonbaharın yaprak desenli sahnesine Elimiz terler mi zannediyorsun yaz sıcağında olduğu gibi?  YALAN....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-kalkip-gitsek-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırılsıklamdı Eylül', 'sirilsiklamdi-eylul-huseyin-tanrikulu-vzf5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırılsıklamdı Eylül gittiğinde.

Kederli bir aşkı, ayrılığın tuzuyla ovalamıştık son kez.

Hangimiz bilebilirdi ki, yaralı bir sevdaya pansuman yapılamayacağını...', 'Sırılsıklamdı Eylül gittiğinde. Kederli bir aşkı, ayrılığın tuzuyla ovalamıştık son kez. Hangimiz bilebilirdi ki, yaralı bir sevdaya pansuma...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sirilsiklamdi-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Mısra, Kaç Sayfa Sürer...', 'kac-misra-kac-sayfa-surer-huseyin-tanrikulu-hyt8b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç mısra, kaç sayfa sürer yokluğunun edebiyatı

Gidişin kaç kıçı kırık kafiye azaltır ki şiirimden? 

Fahişe yatakları gibi ıslak bir geceyi koynuma alıp,

soğuk bir yolculuk molasında unuturum nasıl olsa seni...

									(22.07.2003/ANKARA)', 'Kaç mısra, kaç sayfa sürer yokluğunun edebiyatı Gidişin kaç kıçı kırık kafiye azaltır ki şiirimden?  Fahişe yatakları gibi ıslak bir geceyi ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kac-misra-kac-sayfa-surer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesini Ektim Gül Bitti', 'sesini-ektim-gul-bitti-huseyin-tanrikulu-oif9w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ardında vakitsiz bir aşk bırakmış yaz, hüznü sonbahara meyilli

Kedere bahar istemez

Her mevsimle barışık bir hüzün yetiştirdim ben yüreğimin çorak ikliminde.

Sesini Ektim Gül Bitti...

									(2003/ANKARA)', 'Ardında vakitsiz bir aşk bırakmış yaz, hüznü sonbahara meyilli Kedere bahar istemez Her mevsimle barışık bir hüzün yetiştirdim ben yüreğimin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sesini-ektim-gul-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıp Kaçıp Saklandığım', 'kacip-kacip-saklandigim-huseyin-tanrikulu-lbmbi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçıp kaçıp saklandığım yerlerdeyim yine. İstenmediğin bi sevdanın ortasında olmak niye koymasın ki çeyrek asrı devirmiş bir insana. Sevgilinin kurduğu bir cümlede, belirtisiz bir nesneysen eğer, vakti gelmiştir artık o cümleden çıkmanın...

Ne garip, bir tek adının anlamı yolcu ediyor beni bu kentten.

El sallıyorum...', 'Kaçıp kaçıp saklandığım yerlerdeyim yine. İstenmediğin bi sevdanın ortasında olmak niye koymasın ki çeyrek asrı devirmiş bir insana. Sevgili...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Tanrıkulu']::text[], 8.5, '{"poet":"Hüseyin Tanrıkulu","poet_slug":"huseyin-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kacip-kacip-saklandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Dinsûz', 'ask-i-dins-z-cafer-bayar-jvj0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk-ı dinsuz ilen her dem nalanım

Mey-i müdamımdır derde dermanım

Gamze gamze açar feyz-i cananım

O dem vecde gelir halım, efganım

Gözümde bulutlar rahmettir; revan

Hicran gazeliylen mest olurken can

Yusuf mahsur; kuyu, zindanda zindan 

Yetiş bu imdada, ey ah-ı Ken''an

İsmet beyti yaslı, yürekte yare

Kapıyla mıhlanmış duvara lale

Şirret pazarında cevher sed pare

Sabr-ı cemil yetiş, yok başka çare                   

Yarim, cemaline muştag olmuşam

Gurbet kadehinde mestlik bulmuşam

Sûz-o güdaz olmuş, nâr’a dolmuşam

Eyyub sabrı ilen dinsûz olmuşam

Aşk-ı dinsuz ilen her dem nalanım

Mey-i müdamımdır derde dermanım

Gamze gamze açar feyz-i cananım

O dem vecde gelir halım, efganım', 'Aşk-ı dinsuz ilen her dem nalanım Mey-i müdamımdır derde dermanım Gamze gamze açar feyz-i cananım O dem vecde gelir halım, efganım Gözümde b...', ARRAY['Türk Edebiyatı','Şiir','Cafer Bayar']::text[], 8.5, '{"poet":"Cafer Bayar","poet_slug":"cafer-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-i-dinsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-cigdem-bir-genc-7g9i5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güvercinler uçuşur  göklere...

Güvercinler ki  beyaz...

Kir tutmuş kanatlarında  siyah beyaz bir resim oluverir şehirler...

Biten bir aşkın son düdüğünü çalarak  uzaklaşırken bir gemi...

Sokak kedilerinde fareleri hayrete düşürecek bir keder...

Ve sen! ! 

Tren camlarına  taş atıp kaçan haylaz çocuklar gibisin...', 'Güvercinler uçuşur  göklere... Güvercinler ki  beyaz... Kir tutmuş kanatlarında  siyah beyaz bir resim oluverir şehirler... Biten bir aşkın ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-449-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Anne ve Babamın Anısına', 'sevgili-anne-ve-babamin-anisina-tamer-ozeken-83ft8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani beni çok severdiniz,bensiz yapamazdınız.Hani benim için ümütleriniz vardı.O zaman beni bu dünyada niçin yanlız bırakıp ikinizde gittiniz.

İki aralık 1992 tarihinde telefonla biricik annemi kaybettiğimi öğrendim.

Dünyam başıma yıkıldı sandım,daha annemin acısına dayanamadan beş aralık 1992 tarihinde babasız kaldığımı öğrendim.Bir anda ikinizide kaybetmenin acısıyla,bu acımasız dünyada yanlız başıma kaldım.Annemi kaybettiğimde tam sana sığınacakken sende beni yanlız bıraktın.İşte ben bu yüzden iki ve beş aralık tarihlerini dünyamdan sildim ama 1992 senesini ömrüm boyunca unutamadım aynı anda iki acıyı beraber yaşadım.

Sevgili Anne ve Babacığım ikinizde nur içinde yatın,oğlunuz sizi hiç unutmadı.

Sevgi ve Saygılarımla oğlunuz', 'Hani beni çok severdiniz,bensiz yapamazdınız.Hani benim için ümütleriniz vardı.O zaman beni bu dünyada niçin yanlız bırakıp ikinizde gittini...', ARRAY['Türk Edebiyatı','Şiir','Tamer Özeken']::text[], 8.5, '{"poet":"Tamer Özeken","poet_slug":"tamer-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgili-anne-ve-babamin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dalgalar Yutacak Beni', 'bu-dalgalar-yutacak-beni-esin-ege-8x57a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün batıyor uzak ufuklarda şimdi

Bir denizin yosun yüklü  eteklerindeyim yapayalnız 

Çaresizim  en kötüsü

Çalacak bir kapı sığınacak bir yürek yok

İmbatmı karayelmi esiyor saçlarımda  bilmiyorum

Bildiğim tek şey korkuyorum bu gece 

Denizden ve sensizlikten korkuyorum hemde çok 

Benim tek sığınağım sendin nerdesin 

Bir liman da yok gecenin fırtınasında sığınacağım

Sahilde yürüyorum kaderime teslim

Gel ne olur

Tut ellerimden

Birazdan  deniz kabaracak

Kocaman bir dalga gelecek

Sana sevdalı başımın üzerinden geçecek 

Ve yutacak beni yalan değil

Gel ne olur

Tut ellerimden

Sen böyle değildin

Seslendim mi sesimi duyandın yangınımı gören

Bu deniz alacak beni senden içime doğuyor

Ve kim bilir hangi uzak sahillere savuracak

Bu dalgalar yutar savunmasız beni

Gel ne olur

Tut elerimi

Bu deniz kızgın bir şeylere dalgaları göğe değecek sanki

Gece çok lacivert bu akşam hiç yıldız yok

Deniz öfke yüklü mavi değil bildiğin gibi

Beni sensiz diyarlara götürecekler

Geç olmadan gel ne olur tut ellerimden', 'Gün batıyor uzak ufuklarda şimdi Bir denizin yosun yüklü  eteklerindeyim yapayalnız  Çaresizim  en kötüsü Çalacak bir kapı sığınacak bir yür...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bu-dalgalar-yutacak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-*-* Pinokyo''ya Hitâbım...!', 'pinokyo-ya-hit-bim-metin-eser-ydhb9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Beş, dört, üç, iki bir…………

Günleri saydım boncuk boncuk,

Sabırları çektim tesbih tesbih,

Yılların yorgunluğu üzerimde,

Vuslatı ne çok beklemiştim,

Depremlerden, 

..........yangınlardan çıkıp gelirken,

Nice yalnız gecelerde 

..........sabrıma sabır eklemiştim,

Ve uçurumlardan itilmişim, 

..........sırtımı döndüklerim tarafından,

Hayatın ne anlamı var ki, 

.......... “insanlık” inmiyorsa tozlu rafından…

II.

Üstüm başım yırtık pırtık,

Bedenim yıkık şehirler ertesi gibi,

Hatıralarım cebimde paramparça,

Birkaç fotoğraf kalmış maziden,

Kah siyah beyaz 

..........kah yarısı yok 

....................kah uçları yıpranmış,

..........sanki anıları çekiyor içimden…

Ben kendimi tanımaz olmuşum resimlerde

“Bu gülen adam ben miyim? ” diye 

..........soruyorum kendi kendime 

..........yüzümde hayıflanan bir ifadeyle...

III.

Sustum sonra, saatlerce 

..........bana sorulsa yıllar gibi geldi de…

Ve dedim hayıflanarak kendi kendime

“Geçmiş senden oğlum”…

Vallahi geçmiş benden, 

Gökyüzünde dilek tutmalar,

Geleceğe hayaller kurmalar,

Çılgınca sevdalar,

..........dört nala koşulan,

..........nefis dizgininde hülyalar,

..........sabahta soluklanılan geceler,

Vallahi geçmiş benden, 

Geçmiş benden, 

..........sevmenin de sevilmenin de yaşı…

“Sevmek” labirentlere dökülmüş,

çoğu zaman çıkışı ömre bedel…

Sevmek buysa, 

..........benden çoktan geçmiş”…

Yok yok aslında hiç uğramamış bana...

IV.

Heyhat ömrün yarısı mazide gizli,

Diğer yarısı ilm-i İlahi’de mahfî…

Gücüm yok, 

..........bilmediğim tuzaklarda 

....................çıkmazlarda yol aramaya…

V.

Kararım karar dostlar,

kimse anlatmasın bana “sevgi” yi,

Ben aşkımı bulmuşum, 

Yıllardır kuytularda beslediğim,

Üzerine titrediğim,

Gül üstüne gül koklamamış,

Has yüreklerin bildiği o gerçek sevgiye bağlanmışım,

O nadide sevdamla baş başa kalmak istiyorum.

Lütfen bizi yalnız bırakın…

Kimsenin anlayamadığı sevgimiz,

Tomurcuk çiçeklerimiz,

Misk-ü amber misillü kokulu bahçeler,

Yaşanmayı bekleyen hayaller,

Konuşulanlar ve konuşulmamışlar,

Sorulanlar ve sorulmamışlar,

Birbirinde kaybolmayı bekleyen gözler,

Kavuşmayı özlemiş dudaklar,

Şehvetli değil, 

..........AŞK dolu günler ve geceler, 

....................hatta yıllar bizi bekliyor…

Lütfen bizi yalnız bırakın…

Artık zili de çalmayın, 

..........kapının tokmağını da,

Çünkü evde yokuz…

Merakınız varsa paspasın altındaki notu okuyunuz…..

NOT: 

..........ballı yılların ucundan

..........birkaç gün yaşamak için,

..........sahte yüreklerin ulaşamadıkları yerlere gidiyoruz,

..........biz birbirimizi biliyoruz, 

..........yazık ki siz bilmiyorsunuz,

....................utancı yüzüne vurmuş,

....................kırmızı pinokyolar....

VI.

Unutmadan…! 

Yerde beyaz bir tas var

..........sevdamızın renginde,

İçinde aşkımızdan bir avuç bal var,

Siz gönlü fesatlık kokanlar,

Yüzünde tebessüm taşıyan 

..........ama içi kokuşanlar,

Gıybet vadilerinde tonlarca çiğ eti

..........çiğnemeden yutanlar,

Başkasının mutluluğuna 

..........burnunu sokan pinokyolar,

Alın ve yiyin, 

..........belki yürekleriniz gerçek sevginin tadına varır…

Yine de iflah olmaz iseniz,

Sözüm ağır gelecek size ama,

Şükürler olsun ki 

..........kötüler için,

..........sizin gibiler için,

..........kalpleri temizleyen “Cehennem” var…

Rabbime havale etmişim sonrasını,

Gıyabımızda konuşulanların 

..........hesabını sormasını…………(! ! !)       

26.08.04 / Eskişehir', 'I. Beş, dört, üç, iki bir………… Günleri saydım boncuk boncuk, Sabırları çektim tesbih tesbih, Yılların yorgunluğu üzerimde, Vuslatı ne çok bek...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/pinokyo-ya-hitabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Dair! ...', 'ayriliga-dair-muammer-celik-tkkbb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'başına buyruk ayrılıkların altında ezildi aşkım 

dönüşü olmayan gidişlerin ardına dizildi gözyaşım! ...

