INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Andım', 'andim-zafer-zengin-etnika-dn8kg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana

gelmiştim

türkülere

daldım

adını

andım

türkülere

katıldım

güzel

bakmıştım

orada

bıraktım

gözyaşını

türkülere

sakladım

olsaydın

