INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizler Aşkına', 'denizler-askina-yusuf-sevgen-9vl6c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün sabaha kadar çocuklarımı uyutmasam

soydursam seni düşkırıklıklarından

şarkı başlarında başlasak çaylarımıza

şarkı sonlarında denizyıldızlarımıza

yeni çocuklar yapsak denizlerden; 

denizatlarından, denizkızlarından

okyanuslarda

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; yetiştirirler

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; kendilerini

izin varsa senden

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; bir de benden

Kıyametlerimizin şerriyle kurutmazsak dünyamızı

akar ırmaklarımız uçsuz-bucaksızlığımıza

çocuklarımızsa kalır sonsuzluğa

ekim.doksanbeş.elmadağ', 'bugün sabaha kadar çocuklarımı uyutmasam soydursam seni düşkırıklıklarından şarkı başlarında başlasak çaylarımıza şarkı sonlarında denizyıld...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/denizler-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zencefil ya da Zakkum', 'zencefil-ya-da-zakkum-yusuf-sevgen-qmni6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bilgisizliğin atardamarı patlar,

gökgürültüsü yorulur

yürekler zencefile veya zakkuma eşgüdümlü

ayak sesleri duymuştum küçüklüğümde

öğrendim uzakanamdan anlamını

zencefil veya zakkumdu…

kasım.doksanbeş.istanbul', 'bilgisizliğin atardamarı patlar, gökgürültüsü yorulur yürekler zencefile veya zakkuma eşgüdümlü ayak sesleri duymuştum küçüklüğümde öğrendim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgen']::text[], 8.5, '{"poet":"Yusuf Sevgen","poet_slug":"yusuf-sevgen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zencefil-ya-da-zakkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
