INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstediğinde', 'sen-i-stediginde-zuhal-aksulu-ikmq1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel dediğin yere gelirim seninle

Öl dediğin yerde ölürüm

Bana sıcak bir gülüşün bile yeter

Ben sarhoş bir viraneyim...

Sev beni dediğinde kalbim senindir

Sus dediğinde dilsizimdir

Sen bir dakikanı geçirsen benimle

Al artık bu ömrüm senindir...', 'Gel dediğin yere gelirim seninle Öl dediğin yerde ölürüm Bana sıcak bir gülüşün bile yeter Ben sarhoş bir viraneyim... Sev beni dediğinde ka...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-istediginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-zuhal-aksulu-qqry9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bir şubat sabahı gelmişsin bu dünyaya

