INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Razıyım', 'raziyim-canan-palabiyik-6lshs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir taneme, özel''ime, can dostuma... 

Hatırla, 

Hovardalık yaptığımız akşamları, 

Birbirimizin kollarında 

Uyandığımız sabahları. 

Şimdi, 

Mısralarımda kaldı, 

Hasretin dinmeyen sesi, 

Seni yaşıyorum, seni... 

Çaresiz, 

Sıçrayarak uyandığım geceler, 

Duvarlarda gölgesini aradığım. 

Seni yaşıyorum, seni... 

Razıyım, 

Aç susuz, 

Yeter ki al götür beni... 

(02 Eylül 2004 / İstanbul)', 'Bir taneme, özel''ime, can dostuma...  Hatırla,  Hovardalık yaptığımız akşamları,  Birbirimizin kollarında  Uyandığımız sabahları.  Şimdi,  M...', ARRAY['Türk Edebiyatı','Şiir','Canan Palabıyık']::text[], 8.5, '{"poet":"Canan Palabıyık","poet_slug":"canan-palabiyik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/raziyim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Karadeniz Biraz Akdeniz', 'biraz-karadeniz-biraz-akdeniz-ertugrul-aydin-3x2tu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraz Karadeniz Biraz Akdeniz

1.

denizler aşırıdır bizim bakışlarımız 

mavinin dehşetengiz yükselişi vurunca kıyılara

yetmez bize renkli rüyalar ülkesi

artık diyojenin umrunda değil artemis

dalları volga boylarına vuran çınarların

gölgesinde yaşanır hüzne damıtılmış sevdalar

ve makiler uzar boylu boyunca

yalpalar takalar ayaza karşı

dağılır eski uygarlık izleriyle mayalanan kafalar

ben akropolün en işlek yerlerinde ayetler okurum

hiç bir işe yaramaz 

dünyanın hiç bir totemi

kül basılır yarelere

öfkeler durulur zamanın sarkacında 

tarihe dar gelir tilmizlerin ihaneti

(acılar yaşadık her yanı geçitlere kapalı

ruble için şiir yazan şairler gördü bu memleket

ve mebus isyanıyla başladı köprülere varış) 

2.

krizantemler eylülde yaralar insanı

titretir gövdeleri turunç yalnızlıklar

tundra topraklara atılır misyoner atasözleri

flu bir renk huzmesi yayılır uzaklardan

adonis ayinlerinin perişan saçlı rahibeleri

aşk kanunlarının karşısına çıkar

tevratî bir yazarın kaleminde

bir Beni israil peygamberinin

kerametine gark olur umman

yeni bir otranto seferine bilenir zağanos köprüsü

ölümün lepiska saçlarına yapışır arzular

silueti şehre vurur geçmiş asırların

ipekli yolda dokunur zamanın gergefi

paganların karanlığına karşı durur yedi kollu şamdan

yok sayılır dünyanın figüratif dalgalanmaları

opera tarihi ve rulet masasına yaklaşır 

palmiyeler arasından seslenen gitar

ah akdeniz

seni bir hiç olarak mı almalıydı havsalam

3.

kimliksiz konuştuğum meclislerde

ceneviz tacirlerinin kaypaklığını örtecek

bir tutam gül kucakladım

ey global umudu törpüleyen navarin

sustukça durulur duruldukça susarsın

ey ortaçağ şoyalyelerine sattığım cesaret

kırçıl bir veda gönder kızaran güne karşı

bukolik şiirin sularında boğulsun

dünyayı denizden dolaşan amiral

kesilsin macera yıkılsın hülagu han

bir başka nesil için çırpınsın karadeniz

Ertuğrul Aydın', 'Biraz Karadeniz Biraz Akdeniz 1. denizler aşırıdır bizim bakışlarımız  mavinin dehşetengiz yükselişi vurunca kıyılara yetmez bize renkli rüy...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/biraz-karadeniz-biraz-akdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çamurabi', 'camurabi-aynur-baydar-srdug', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanıştın biriyle

İlk soru, nerelisin ne

İçimden gelir hep

Şunları demek

Marsdan, gavuristandan, elinin köründen

Kültür ve dayanışma dernekleri

Yaşatmalı güzellikleri, adetleri

Sapmışlar amaçtan

Olmuşlar hemşehri torpilleri buluşturma yeri

Çamurabi merkezi

Hemşehri olsun da 

Çamurdan olsun meselesi

Aha da bir çamurabi terfi etti

Atayacak diğerlerini

Bilgi liyakat neyine

Getir nüfus cüzdanını hele

Bak çamurabisi

Cep telefonunda bile çalıyor memleket müziği

En koyu hemşehri 

İşte bu çamurabisi

En yüksek makama gelmeli

Hadi bakalım 

Yapın çamurdan piramidinizi

Sizden öncekilerin yaptığı gibi

Harcınız hakkaniyet değil

Yıkılacak elbet

Ziyan hepimize, devlete

Böyle giderse

Çamurabi zihniyeti bitmezse

Gelişmişlik uzak bize.', 'Tanıştın biriyle İlk soru, nerelisin ne İçimden gelir hep Şunları demek Marsdan, gavuristandan, elinin köründen Kültür ve dayanışma dernekle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/camurabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Akdeniz', 'sevgilim-akdeniz-ertugrul-aydin-6jruf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgilim Akdeniz

I. 

ihtirasla sevdim seni 

karanınkine karışmış hayatınla

çok sayıda başkaları gibi 

kuzeyden geldiğim için

kara dünyandan ayrılmaz tarihinle 

venedik parma floransa

napoli viyana iskenderun mersininle

bir denizler bütünüsün

adaların dallı budaklı kıyıların

zeytin ağaçların üzüm bağların

kürekli dev teknelerin

tüccar gemilerin denizci köylülerin

denizler kıskandıran şiirlerin

ve aradıklarını bende bulamayan 

güzellerinle sevdim seni

II.

bir başka bakardın dünyaya

süleymanın mühründen

kıtalara meydan okurdun

barbarosun dilinden

gün oldu korsanlara kaptırdın yeleni

şövalyeler birer ayrık otuydu gövdende

tezelden yıkılmış muratlara inat

günahlar boyalı hicran kokularınla

braudel’in koltuğunda duran yadınla

yazık kürek mahkumların

yankısı kırsalda şanınla 

sevdim seni

Ertuğrul Aydın', 'Sevgilim Akdeniz I.  ihtirasla sevdim seni  karanınkine karışmış hayatınla çok sayıda başkaları gibi  kuzeyden geldiğim için kara dünyandan ...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgilim-akdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Florya’da Sabah Sisleri', 'florya-da-sabah-sisleri-ertugrul-aydin-07p9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Florya’da Sabah Sisleri

1.

geceye hücumda yarışır mumyalı sükut

şehri bir kaldıraç ağzına çeker 

temkinli yalanlarla yıkanmış gök

ömürden yeni bir başak ağarır

bolşevik kostümüne bürünür yabanıl çığlık

ıslak ay mavi kasaba

ve sesli yağmur altında

tenden geçen sakallarım ürperir

bir peynir kütlesine değişilen Rafael

sonsuza yazılan sarışın komutan

kimya saçlılar galasında

kentin ortasına yerleşmiş portatif sevdalılar

emer kavafisin şiirini gitar ucundan

hız kesmişim damarıma dokunma reis

bu deniz beni kucaklayamaz 

bu üstü ölümcül sevda kokulu ormanı sevemem

bu kağıttan evler çalamaz düşlerimi

devasa yalnızlıkların koynunda 

polonya derebeyi balosuna çıkan 

kolejli kızların kıranta yüzleri

2.

sıcaklığın kendisi konfor 

borsa taburunu kurmuş güneşe

plaja abanmış kangren

umudun çerağı unutmak

ihanetin kucağı inkar

beyaz masal süsünde 

yedeğe alınmış

şarkın yaralı kuyruğu banliyö

gel geç yüreğimi ortala

vitrinlere tutunmuş güzellik

çar’a bağlı beyazlarla kolkola

3.

begonya ıtır geçer 

sahan aralığından

sofalarda ürken taflan 

savrulan çağa 

yumruk fısıldanır 

acemi nefer tadında 

ayrı bir yük alır 

her teneffüs arası 

katlanır 

sırra yakın bakan gülüş

güçlü ışıldar acıya

nefsin içeri alınan boyu

gürbüz yar’dan geçer 

kontra çirkefe yaylım kala

uzatılmış merhamet

ki kandır 

pullanmış başımızı okşayan

Ertuğrul Aydın', 'Florya’da Sabah Sisleri 1. geceye hücumda yarışır mumyalı sükut şehri bir kaldıraç ağzına çeker  temkinli yalanlarla yıkanmış gök ömürden ye...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/florya-da-sabah-sisleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DöNeNcE', 'donence-mine-ozdemirtas-xv69h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni dövmeliler etlerime / tuz basarak kanayan yerlerime

sana ıkınıp sinsice

senden / sana gebe kalmak diye/seni doğurup

vermek için ellerine

göbek bağın göbeğimde /seni bağırmalıyım sancılarla 

adaklar adanırken tütsülere 

Bak /adın fısıldıyorlar gölgelere

senin vaftizin bu / ben kasede / sen kürsüde

kutsal su halinde serpilince bedenine

sızmalıyım tenine ince ince

ta en başa çark ederken dönence

-------------------------

nereye gidiyorsun? bu senin vaftizin

kutsal aşk adına /ben kasede sen kürsüde

acı çekeceksin elbet /henüz başlamadı ki eğlence

02/09/2004', 'seni dövmeliler etlerime / tuz basarak kanayan yerlerime sana ıkınıp sinsice senden / sana gebe kalmak diye/seni doğurup vermek için ellerin...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donence-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şairin Başkadır Akdeniz’e İnişi', 'her-sairin-baskadir-akdeniz-e-i-nisi-ertugrul-aydin-1poo5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her Şairin Başkadır Akdeniz’e İnişi

a.

soğuk terler içinde

kente salınan dokunuş

öpülmüş rüya yolcusu mavi

saçaklarında lüle yalnızlığı

yanık duvarlar ucunda göz kırpan

nikel seyirler

bir çentik atar damarlarına nisanın

harptir hudutları anafora uğurlayan

mavra neyler deprenmiş dalgalara

köpük kahpedir 

tıkamaz şezlong aralıklarını

bir finikeli aryasında

şövalye mıknatıs çengeli papirüs

donanma kartal başlı kadırga

ve sonsuz yatış

b.

ada pikniğinden kalma papatyalardan

taç yap akdenizin uğrak barınaklarında

tütsülenmiş yolculuğuma

helen devrinden kalma öpücükler isterim

marsilyaya demirlemiş 

arzulu bir tramvaydan atılan geceye inat

martı çığlıkları arasında 

sana bir kucak istanbul getireceğim

Ertuğrul Aydın', 'Her Şairin Başkadır Akdeniz’e İnişi a. soğuk terler içinde kente salınan dokunuş öpülmüş rüya yolcusu mavi saçaklarında lüle yalnızlığı yanı...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/her-sairin-baskadir-akdeniz-e-inisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Çağlarda Maskelenen Sürgün', 'mutlu-caglarda-maskelenen-surgun-ertugrul-aydin-umtn2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutlu Çağlarda Maskelenen Sürgün

nabzını tuttum denizin

öç aldım mevsimlerden

ve karaya vardı isyanım 

ey tenimde uğuldayan adreslerin üzüntüsü

oğlak rengi mareşal

batık denizlere tutunan

şehrin yoksul kanatları 

dayan iliklerine kilitli

dünyalı bir rüyadan öteye

mutlu çağlarda maskelensin sürgünün

sırrı ayaklar altında evrenin

kağıtlara sığmaz daüssıla kadar

yeri yoktur kıvamında bir nisana 

ey unutulan zamanların aşılmayan kolu

çağrısına kulak as yolculukların

kazan zaferini mesafelerin

Ertuğrul Aydın', 'Mutlu Çağlarda Maskelenen Sürgün nabzını tuttum denizin öç aldım mevsimlerden ve karaya vardı isyanım  ey tenimde uğuldayan adreslerin üzünt...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mutlu-caglarda-maskelenen-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serüven Ucuz Değil', 'seruven-ucuz-degil-ertugrul-aydin-vlwcc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çaylak mevsimleri omuzlamak bana yakışmaz

peçenek kanında gömgök görüntülerin

böğürtlen sıcaklığında demirli

tutkun kara çağ için

yürek fedadır binde bir yakınlık yoluna

sürgün olsa gözlerine bir ilmik kara

kaplar kanı mut ferahlığında heyamola

yer yarılır dağ ufalır deli fişek kesilir sine

akreple terazi arasına sıkışan denge

yoklar er geç üçüncü kolu

kalsın kubbeler altına güz ertesi yolculuk

harman yeri devşir/sen rüzgar serinliğinde

mızraklar biledim engelli koşular için

ant olsun dizginsiz çığlıksız geceye

ne çelimsiz silikonlara adanmış dünya

hantal başım kuşan hala hürriyeti

akşamlar pusludur yâr/elim tabyalar donuk

buhur öyle kınalıdır sabah ezanında

ne kaval ne karnaval sade bir gülüş al

serüven ucuz değil kolay olsa da ayrılık', 'çaylak mevsimleri omuzlamak bana yakışmaz peçenek kanında gömgök görüntülerin böğürtlen sıcaklığında demirli tutkun kara çağ için yürek feda...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seruven-ucuz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykularını Alırdım Akşamcı Kızların', 'uykularini-alirdim-aksamci-kizlarin-ertugrul-aydin-r6uzm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

uykularını alırdım ilkin

akşamcı kızların

azıklarına katardım rüyalarımı

simokin mecburi değildi

karanfil vermezdim

ebedi solardı susuşları

sonra bir yol uzardı 

kanaviçe bakışlarına

bir küme yıldız kayardı

saçlarına dolanırdı yalnızlığım

beyazdı sincabiydi düşleri

yaz gelir yiterdi gülüşleri 

elpençe dururdu sıcaklığı 

uçları sararmış yapraklar arasında takvimlerin

bilgiçti deryaydı 

gecenin koynunda soluyan 

2. 

sakladım ruhumu militan merasimlerden

ki ara durakların gölgesi değdi tenine

istiridyelerin günahsızlığına şahit maviden

eylül gelir nisan gelir siyahın gözlerine', '1. uykularını alırdım ilkin akşamcı kızların azıklarına katardım rüyalarımı simokin mecburi değildi karanfil vermezdim ebedi solardı susuşla...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uykularini-alirdim-aksamci-kizlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayseri Garında Üç Dilimli Zaman', 'kayseri-garinda-uc-dilimli-zaman-ertugrul-aydin-zua40', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

	bir parça asya alır

	mısra demlerdim gagauz ırmağında

	siteler boşalırdı avuçlarıma

	bir tek

	a/saf hal/et bilirdi

		isyanın rengini

	çöl geçerdim harmanilerimle yanaşık

	camiye yardım 

	hassas bir ruh alırdı

	vites kongresi aralığında

	söz ki baş döndürürdü 

	karayolun böğrüne dek

	II.

	bir pergel ucunda yayın dokunuşu

	ne tıpırtı ne okşayış

	panjurlar arasında okyanus

	can çekişir kızıl maviye

	bir kenti omuzlarından yakalamak

	uzun tanışıklıkların mermi gücünde

	ve şiire uyanmak kadar saf

	ey enkaz yaz zehrolan dağ

	''gesi bağlarında dolanıyorum

	yitirdim yarimi aranıyorum''

	III.

	denizin saçları bir tutam ıslak

	uyanık rüyanın yolunu tutsak

	bin bir hengâme dizilir boyuna

	oyuna gelir ısırılmış şafak', 'I. 	bir parça asya alır 	mısra demlerdim gagauz ırmağında 	siteler boşalırdı avuçlarıma 	bir tek 	a/saf hal/et bilirdi 		isyanın rengini 	çö...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kayseri-garinda-uc-dilimli-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ar/da/han', 'ar-da-han-ertugrul-aydin-ytv9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dimdik yaşıyorsun yüzyıl biterken

	yüzüyor ufkunda yeni bir sayfa

	cesursun şanla biçilir kaftanın

	de ki sallansın çiğninde çiğdemler

	yoğur aç yürekleri güz harmanında

	ağır suya dök ağdalık ağrını

	şen kal''asın essin külek yelenden 

	küran atlar geçsin dere boyundan

	göz kırpsın  meralar mezbahalara

	/her ağırnasta gizlidir bir umman/

	koyver açılsın şenlik diyarı', 'dimdik yaşıyorsun yüzyıl biterken 	yüzüyor ufkunda yeni bir sayfa 	cesursun şanla biçilir kaftanın 	de ki sallansın çiğninde çiğdemler 	yoğu...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ar-da-han-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namık Hoca', 'namik-hoca-ertugrul-aydin-iriqj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'haliç''e rağmen haliç diyerek

		sıcak bir mevsimin ılıklığında yaşamak

		ve en eski zaman aşklarının 

		karanlık suçlarına ulaşmak için

		şanlı bir kumandan edasıyla

		metropol şehrin ışıklarına karşı

		iki cetvel kırmış namık hoca', 'haliç''e rağmen haliç diyerek 		sıcak bir mevsimin ılıklığında yaşamak 		ve en eski zaman aşklarının  		karanlık suçlarına ulaşmak için 		şan...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/namik-hoca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epigramma', 'epigramma-ertugrul-aydin-5lhns', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Sefaköy ve bütün denizaşırı kentler için-

		hamburg

		uzak bir parıltı saçlarında

		(yasak cinayete bilenmiş

		katmanlar kabule razı

		risk al civan yürek

		makbul taraf rind huy

		devran sav aralık dur

		adak tut zırh kuşan

		yoluna han kur ey/len)

		lâbirent ucunda sızı

		benli bir hıçkırık

		ve yaşamak 

		orhan zamanında orhan kadar', '-Sefaköy ve bütün denizaşırı kentler için- 		hamburg 		uzak bir parıltı saçlarında 		(yasak cinayete bilenmiş 		katmanlar kabule razı 		risk...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/epigramma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rıhtım Sözü', 'rihtim-sozu-ertugrul-aydin-qy62j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çevik bir rıhtım sözü dilenir

		dünyalar kucaklardım 

		mesafelerin inadına 

		bir mimoza engeli kaplar

		beyazı seyre çıkardı akşamlar

		ben uzun koridorlara sığınır

		demli çaylar içerdim

		gölgesinde hayatın', 'çevik bir rıhtım sözü dilenir 		dünyalar kucaklardım  		mesafelerin inadına  		bir mimoza engeli kaplar 		beyazı seyre çıkardı akşamlar 		be...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/rihtim-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Saçılır Ellerine Güneş', 'yorgun-sacilir-ellerine-gunes-ertugrul-aydin-9s05w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1. 

vururum kendimi yollara 

en çılgın içtenliklere adanan ritimle

kalabalıkta örselenmiş

kaç üsküdar geçti bahardan

nice baht 

kaç kıvrım yüzü gördü

yalıtkan karınca 

bir liret 

ve yüzü koyun hayat

baş aşağı kopan ip ucunda 

heyhat

demir tavında dövüldü

toprağa değdi saban

cemre düştü 

ve kovana aktı bir nehir

zehir tadında şimdi sihir

2.

sokaklar bir arpa boyu

sokaklar kırılgan 

boynuzsuz 

ıslak saçlı

çıkmazları yokuş 

yanarak geçilir 

bir sarnıç kalbinde 

uyur

kor kül alev zırh 

neşesiz adımlar ucunda 

yırtık 

kine tutkun ve hudutsuz 

oluk oluk 

koca kentin yakasında 

bitmez tükenmez 

telaş dolu itiş kaçış

hız içinde saklı rüya 

          /gümüş kara parçası/ 

aylak yolun katmanı

3.

yorgun saçılır ellerine güneş 

dökülür perçemlerin kaldırımlara

yalnız 

kara parçası ve

kıldan ince boyunlar birikir

kuşku adında

alında damla damla hüzün

ayrı kalbur içinde bizans

ve senin düşlerin

  

4.

/hangi adreslerde/

mevsim cömert uyku bölüşür

dilekler bir parça çakılır 

kaba yol neyler 

yaya çıkılım 

uygun adım yaya 

sıcak mayıs aşkına', '1.  vururum kendimi yollara  en çılgın içtenliklere adanan ritimle kalabalıkta örselenmiş kaç üsküdar geçti bahardan nice baht  kaç kıvrım y...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/yorgun-sacilir-ellerine-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlerimde Kalan Tortuyu Artıran Yok', 'sozlerimde-kalan-tortuyu-artiran-yok-ertugrul-aydin-yfpdi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sarmaşıklardı yengeci kovalayan

bulutsuz mavinin sonsuzluklarına

ki şimdi bir sevinç bırakır 

deniz ablukasında alize

kara

deniz hey

ne barikat ki en ışıltılı gülün

kızarır üzülür incinir

kiraz ülkesine geç varmak telaşıdır

yüreğimi incecik kıran

neydi ki

biraz toz yutmuş kara üstünde 

deryayı derin kılan

az kalsın 

canda tenden öteye

hey batık umut diyarı

sözlerimde kalan tortuyu artıran yok

ki hücum olsun öpülen ellerine

bilsin artık papatya yasemin leylak

ben de varım âşıklar yolu sabahına', 'sarmaşıklardı yengeci kovalayan bulutsuz mavinin sonsuzluklarına ki şimdi bir sevinç bırakır  deniz ablukasında alize kara deniz hey ne bari...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozlerimde-kalan-tortuyu-artiran-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozlarımız Dökülsün Frankfurt Sokaklarına', 'tozlarimiz-dokulsun-frankfurt-sokaklarina-ertugrul-aydin-u515w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yepyeni bir yara bıraktın

hüzün akan diyarında gönlün

kayboldun bir kervan düzünde

evren ellerinden uçuştu 

kamaştı 

perdelendi 

çılgın akşamlara doğru bir ince muştu

seyrek inen baharın 

nazik bahçesiydi kucakladığımız

sırmaydı kara kahveydi 

gülmek masal ülkesine ısmarlanmıştı

ürken adımlarında 

silkelenirdi etrafın yolları

akça bir yüreğin vardı

abat ederdi 

kendine yeten soluğun

dayanırdı yüzü koyun ninnilere serzenişin

en çok bendim seni anlayan 

inatçı bir dengeydi bu 

hep peşinden koşulan

kalk bir yol alalım 

essin yayla dumanı

tozlarımız dökülsün 

Frankfurt sokaklarına', 'yepyeni bir yara bıraktın hüzün akan diyarında gönlün kayboldun bir kervan düzünde evren ellerinden uçuştu  kamaştı  perdelendi  çılgın akşa...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tozlarimiz-dokulsun-frankfurt-sokaklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Yeğin Yekinir', 'yurek-yegin-yekinir-ertugrul-aydin-j5x34', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'a.

		kütle şahlanır rüya içinde

		kan çeker ruh toprakta canlanır

		kızarır malabadi heyecanlanır

		hasankeyf yüzü koyun

		murat boylu boyunca suskun

		harput temiz cesaret yükü

		kabarık omuzlu diyar

		en yakını kolay adımlar

		maden uygun diri cünbüşe

		yatak kınlınmış ne yazar

		

		b.

		

		usta kolay dirlik neresi

		acı dile güç katar

		bozgun bozuk nehre akar

		yürek yeğin yekinir 

		az kahır az saban

		düzgün ritim düzgün otağ

		kor zor yapışır tene

		çağır topla yekünü

		kopsun filim düşsün maske', 'a. 		kütle şahlanır rüya içinde 		kan çeker ruh toprakta canlanır 		kızarır malabadi heyecanlanır 		hasankeyf yüzü koyun 		murat boylu boyun...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Aydın']::text[], 8.5, '{"poet":"Ertuğrul Aydın","poet_slug":"ertugrul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yurek-yegin-yekinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-kazim-basekmekci-ptohq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuk gülüşlerim vardı,

Çocukluğumda.

Dizimdeki kan pantolona sinerdi de,

Ağlamayı bilmezdim.

Ne zaman büyüdüm.

Ve o kan gözümü bürüdü,

Ağlamayı öğrendim.

Çocukluğum vardı,

Ağaç dalları arasında.

Annemi üzünce kaçar,

Vişne ağaçlarına saklanırdım.

Oklavalar çedikler üzerinde şaklardı.

Ve ayağım hiç acımazdı.

Büyüdüm.

Ufacık bir kıymıkta bile,

Acının ne olduğunu gördüm.

Çocukluğumuzda,

Kavak dallarından atlarımız olurdu.

Üzerine bindiğimizde,dıgıdık... dıgıdık...

Kılıçlar sallandığında,

Battal Gazi sanardık kendimizi.

Bir atımıza verecek arpamız,

Bir de gelecekten korkumuz yoktu.

Ne zaman büyüdüm.

Geçim, benim sırtıma bindi.

Yıkıldı çocuk saltanatım.

Ruhuma korkular sindi.

Çocukluğum vardı,

Taş kaldırımlı sokaklarda.

Yağmur sularının önüne bentler kurar,

Kağıt gemiler yüzdürürdük.

Benim gemilerim,gemilerin en delikanlısıydı.

Bir gemilerime aşıktım,

Bir de ''gemilerde talim var'' şarkısına.

Ne zaman büyüdüm.

Bir yağmur damlası değince alnıma.

Gemilerim gelir aklıma.

Çocukluğumuzda,

Rüzgarlar türkü tutturur,

Biz uzun kuyruklu uçurtmalarla

Rüzgarda dans ederdik.

Kızardım,çocuksu duygularla,

Bu telleri kim çektirdi diye.

Şimdi büyüdüm,

Çocukluğumdan geriye,

Ne uçurtmalarım kaldı,

Ne de telgraf telleri...

Çocukluğumda,

Sınıfın en güzel kızına aşıktım.

Saçlarıma limon sürer,

Perçemimi öne bırakırdım.

Arada bir bana gülümserdi.

Gülüşleri benzemezdi öteki çocuklara.

Büyüdüm aşkı yakından tattım,

Kapıldım sonsuz acılara.

Çocukluğumda arkadaşlarım vardı,

Kiminin kucak dolusu oyuncağı,

Kiminin çiçekli bahçesi vardı.

Benim se hep hayallerim süsledi,dünyamı.

Yarınlar bizim! nutukları atardım.

Büyüdüm,tanıdım gerçek dünyayı.

Oyuncaklarda kaldı hayallerim.

Çocukluğumda,

Hiç bir şeyim yoktu.

Herşeyim vardı.

Ağlarsam gözlerimle,

Gülersem,yüreğimle gülerdim.

Şimdi büyüdüm.

Yüreğimle ağlıyor,

Gözlerimle gülüyorum.

Bazen kendi kendime,

Niçin büyüdüm diyorum...', 'Çocuk gülüşlerim vardı, Çocukluğumda. Dizimdeki kan pantolona sinerdi de, Ağlamayı bilmezdim. Ne zaman büyüdüm. Ve o kan gözümü bürüdü, Ağla...', ARRAY['Türk Edebiyatı','Şiir','Kazım Başekmekçi']::text[], 8.5, '{"poet":"Kazım Başekmekçi","poet_slug":"kazim-basekmekci","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/cocuklugum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakitsizdin...', 'vakitsizdin-ozgur-aysun-beksari-93g9j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlamakla yücelttiğim kendimi

Bir başkasına hazırlarken

Kahve falında bahsedildi gözlerinin ışıltısından

Kopuk insanlar arasında..

Mesafeler gerekliymiş meğer...

Ve o mesafeler öğretti bana,

Senle olamayacağımız kadar imkanlı.

Yaşanmışlığıyla karmaşık duyguların

Hırs olmuş yorumlanması..', 'Ağlamakla yücelttiğim kendimi Bir başkasına hazırlarken Kahve falında bahsedildi gözlerinin ışıltısından Kopuk insanlar arasında.. Mesafeler...', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vakitsizdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sevgi İhanet', 'ask-sevgi-i-hanet-salih-ozalasan-c7c8q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk doyumsuz bir meyve ruhun yetiştirdiği yürekten

Şiddeti ölçülmez bir deprem, tesiri fazladır toptan tüfekten

Kurtuluşa ermenin yolu geçer ancak karşılıklı sevgiden

Sevgi bir paye makbuldür verilecek her ödülden

Ebedi saadete erişileni, yaşananıdır iki yürekten

Verilmez alınır, saadete uzanan yol sevgiden

Gözlerden okunur gülücükler dökülür gamzeden

İbadete benzer sakınmalısın her türlü ihanetten

İhanet ilk adımı atar karşılıklı güvensizlikten

Haya kalkar duygular körelir beyinden

Aşk ve sevgi soyutlanır narin teninden

Nehirler akmaya başlar farkına varmadan tersinden

Engin denize varacağını geçirirken hayalinden

Tepeden tırnağa çamura batarsın eser kalmaz aşk ve sevgiden

Y tarihi 30-08-04

Salih ÖZALAŞAN

(Sevgili şiir dostları sizlere son şiirimi yazarak veda ediyorum uzun bir ara aranızda olamayacağım için üzgünüm yüreğinizde sevgiler daim ve ihanetsiz kalsın)   sonserseri', 'Aşk doyumsuz bir meyve ruhun yetiştirdiği yürekten Şiddeti ölçülmez bir deprem, tesiri fazladır toptan tüfekten Kurtuluşa ermenin yolu geçer...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-sevgi-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Şiir', 'i-kinci-siir-yasar-pullu-ip8n7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bazen acılar süzersin damarında

kaleme kan bulaşır

var ile yok arasında

gözüne yaş olur ömrün

sırtladığın hayat 

seni sırtından vurmuştur

usta işi bir söz düşer diline sonra

ustaca örülmüş bir yürek

ağzında kenetlenmiş bir diş olur sevda', 'bazen acılar süzersin damarında kaleme kan bulaşır var ile yok arasında gözüne yaş olur ömrün sırtladığın hayat  seni sırtından vurmuştur us...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ikinci-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya Tarlasındaki Bereket Alameti', 'papatya-tarlasindaki-bereket-alameti-kamber-bal-l4vln', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çil çil yanakları

papatya açmış tarlaya benziyordu

tarla bereketini ondan

o kudretini hak''dan alıyordu

gözleri doluyor,

bereket yağıyordu

hıçkırıkları gök alanın gürültüsünü boğuyor

titreyen bedeni rihter ölçeğyle yediydi

kuruyunca kızıl dudakları

kuruyordu tarlanın bereketi

ışıl ışıl gözleri

karanlıkta ayı andırıyor

efradındaki yıldızları yalıyordu

bakınca insanın yüreğinde

mecaz-i mahrumiyeler yaratıyordu

erişilmesi güç kaf dağı misali

hayalleri işgal ediyordu

ak pak elleri

dokununca,dokunulmazlığın

ateşi gibi dağlıyordu

öpülesi eller uzanıvermeye görsün

şafaklardan sökün eden

evliya kerametindeydi

billur gibi sesi

yankılanırdı yedi tepeden

selama kalkardı börtü böcekler

karınca yuvasında uyurdu ninnilerinden

bebekler dua alırdı annelerinden

bin bir marifetleri vardı

ağu ezerdi Bal teknesinde

bala katar, baldan tatlı eder,

kızılcık şerbetyle sunardı

mest olurdu cümle alem', 'çil çil yanakları papatya açmış tarlaya benziyordu tarla bereketini ondan o kudretini hak''dan alıyordu gözleri doluyor, bereket yağıyordu hı...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/papatya-tarlasindaki-bereket-alameti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığı Tutsam', 'karanligi-tutsam-talip-kaplan-u9jlr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorsam şu karanlığa sorsam

Yorgun sessizliğiyle konuşsam

Geçmiş yılların hesabını sorsam

Bir de ona kahır mektubu yazsam

Bütün yıldızları bir araya toplasam

Kendimi de onların arasına atsam

Ve, hemen sonra güneş batımından

Zifiri karanlığa meydan okusam

Koşsam şu karanlığa doğru koşsam

Boşluğun derin kollarına atılsam

Tonlarca aydınlık alsam pazardan

Karanlığın gözüne doğru saplasam

Tutsam şu karanlığı tutsam

Tutsam da bin parçaya ayırsam

Zehir saçan tırnakları arasından

Hiç değilse yalnızlığımı kurtarsam

Kalbimin derinlerindeki acılarla

Ve yüreğimde yanan ateşin ışığıyla

Gece yarısı aydınlanan şu karanlığa

Kendimi ve içimdeki seni tanıtsam

(26 Temmuz 1991)', 'Sorsam şu karanlığa sorsam Yorgun sessizliğiyle konuşsam Geçmiş yılların hesabını sorsam Bir de ona kahır mektubu yazsam Bütün yıldızları bi...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karanligi-tutsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Gözyaşı', 'bir-damla-gozyasi-talip-kaplan-hvre1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Havanın kararmasına yakın

Mazi defterini karıştıracaksın

Yıpranmış bir sayfa bulacaksın

O an beni hatırlayacaksın

Güneşin yarısı kaybolduğunda

Oturacaksın pencerenin kenarına

Bir yüz arayacaksın ufuklarda

Sesimi duyacaksın uzaklarda

Belki pişmanlık hissedeceksin

Sevmeyi deneseydim diyeceksin

Birazcık ağlayıp, üzüleceksin

Bu gece beni düşüneceksin

Üzülme sevgilim üzülme

Sen beni hiç merak etme

Bir damla yaşsam gözlerinde

Ağlayıpta yerlere düşürme

Bitmedi bende sevgin, bitmez

Hala dilimde ismin, düşmez

Yine elimde resmin, eskimez

Hep karşımda hayalin, gitmez

Sen de sev, sevilenler ölmez...

(20 Ağustos 1991)', 'Havanın kararmasına yakın Mazi defterini karıştıracaksın Yıpranmış bir sayfa bulacaksın O an beni hatırlayacaksın Güneşin yarısı kaybolduğun...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-damla-gozyasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım', 'anlatamadim-talip-kaplan-rwyb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şafağı bekleyen karanlığı

Gecelerin sonundaki sabahı

Sensizliğin verdiği acıyı

Anlatamadım yalnızlığımı

Kelimeler anlatamaz bunları

Ölümü özleyen bir canı

İçimdeki hayal kırıklığını

Anlatamadım yalnızlığımı

Titreyiş sardı dudaklarımı

Gözyaşı aldı yanaklarımı

Fallar yaktı umutlarımı

Anlatamadım yalnızlığımı

Dönüp yüzüme bakmayışını

Gözlerini benden kaçırışını

Kalbimi alıp parçalayışını

Anlatamadım yalnızlığımı

Anlatamadım aşkımı...

(27 Ağustos 1991)', 'Şafağı bekleyen karanlığı Gecelerin sonundaki sabahı Sensizliğin verdiği acıyı Anlatamadım yalnızlığımı Kelimeler anlatamaz bunları Ölümü öz...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlatamadim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-talip-kaplan-jwzth', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar essin diyorum

Bizi kavuştursun istiyorum

Ellerini arayan ellerimin

Ellerinden tutuşunu özlüyorum

    .    .    .     Seni Arıyorum

Geceler boyu düşünüyorum

Sabahlara kadar içiyorum

Gözlerini arayan gözlerimin

Gözlerine bakışını özlüyorum

    .    .    .     Seni Arıyorum

Çilekeşim ben, yorgunum

Seni bulmaktır tek arzum

Unutulmaktır korktuğum

Beni unutma yalvarıyorum

    .    .    .     Seni Seviyorum

(26 Eylül 1991)', 'Bir rüzgar essin diyorum Bizi kavuştursun istiyorum Ellerini arayan ellerimin Ellerinden tutuşunu özlüyorum     .    .    .     Seni Arıyoru...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-seviyorum-207-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel! Yada Vazgeç Gelme.!', 'gel-yada-vazgec-gelme-nevin-kurular-9lj5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi türkülere sığdırsam hislerimi

Hangi şiire asılı bıraksam……

Kaynaklarını çözüyor prangalar

Uçuşurken saadetim…

Ayağımın altına kaç renk, kaç  bulut alsam…

Kurutulmuş gözyaşımı

Midyesinde gizlediğim denizim..

Zaman gerisi dizelerde

Eski bir kemanın

Yıllanmış  tellerinde 

Şarkısını dinlediğim..

Yamaçlarına besteler serdiğim

Sen miydin 

Sen miydin  beklediğim….

Gel! yada vazgeç,

Gelme! 

Olduğun yerleri severim…

Mavi bir atlas ört  üzerine

Kıpırdatsın varlığın yalnızca şafaklarımı

Tapınırım

Hasretinin  mabedinde.', 'Hangi türkülere sığdırsam hislerimi Hangi şiire asılı bıraksam…… Kaynaklarını çözüyor prangalar Uçuşurken saadetim… Ayağımın altına kaç renk...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-yada-vazgec-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinesin Diye', 'sevinesin-diye-talip-kaplan-imbch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki birisini çok seversin

Ona sevgilim bile dersin

Beni aklına getirmezsin

Eski günleri unut gitsin

Seni hiç görmeyeceğim

Elimi resmine sürmeyeceğim

Sen sevinesin diye; 

Bu şehirden gideceğim

Sen sevinesin diye; 

Bir mum gibi söneceğim

Sen uyurken gideceğim

Sabah olmadan öleceğim

Sen sevinesin diye; 

Ruhumu alıp götüreceğim

Mezarımı derin eştireceğim

Yerin dibine gömüleceğim

    .    .    .     mutluluklar dilerim

(12 Ekim 1991)', 'Belki birisini çok seversin Ona sevgilim bile dersin Beni aklına getirmezsin Eski günleri unut gitsin Seni hiç görmeyeceğim Elimi resmine sü...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevinesin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzen Bozuldu', 'duzen-bozuldu-talip-kaplan-xm2em', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatımda düzen kalmadı

Geceleri uykum olmadı

Gözlerimin altı morlandı

Hastayım, benzim sarardı

Allerjik reaksiyon başladı

Hep aynı şeyleri yedim

Hergün patates pişirdim

Arada bir lokantaya gittim

Yemekten böcekleri temizledim

Dengesiz beslendim, tükendim

Bulaşık dağ gibi yığıldı

Bitmesi belkide imkansızdı

Benim kollarım sıvandı

Ellerim imkansızı başardı

Tas tabak tertemiz kaldı

Orhan Ferdi türkü çığırır

Benim başım çok ağrır

Ders çalışmaya vakit mi kalır

Hoca hanım sözlüye kaldırır

Talip bu sınavdan sıfır alır

(13 Aralık 1991)', 'Hayatımda düzen kalmadı Geceleri uykum olmadı Gözlerimin altı morlandı Hastayım, benzim sarardı Allerjik reaksiyon başladı Hep aynı şeyleri ...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duzen-bozuldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumu Yaşamadım Dedin Sen..', 'cocuklugumu-yasamadim-dedin-sen-nazife-abayli-5l8kt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu yaşamadım dedin sen..

Çiçek toplamadım dedin Boztepe’den.

Boztepe sırtlarında uçurtma uçurmadım dedin.

Ben de yaşamadım diyeceğim yalan olacak..

Yaşadım…

Naz yaptım,istediğimi aldırdım,şımardım…

Seninle aynı yaşta yaşadım..

Zekice,deli dolu yaşadım..

Komşumuzun kuş tüyü yastığını çaldım mesela..

Kovalamaca oynarken mahalle çocuklarına fırlattım,

Kuş tüyü yastığı…

Yastık yırtıldı,bezi amerikandı,çürümüş amerikan..

Amerikan yırtıldı,tüyler uçuştu, sokağı  doldurdu..

Başlarını koyup tüylerin üstüne,

Sokak çocukları uyudu.

Şeftali çaldım sonra komşumuzun bahçesinden,

Eteklerimi doldurdum.

Anamın bir metre patiskadan diktiği,

Kırmızı fırfırlı eteğime doldurdum…

Döktüm sokak başında şeftalileri eteğimden,

Bursa şeftalilerini,kocaman kocaman,turuncu turuncu,

Döktüm de sokak çocuklarını doyurdum..

Çocukluğumu doya doya yaşadım ben..

Komşumuzun sebze bahçesine topumu kaçırdım..

Harçlıklarımı biriktirip aldığım topumu..

Ne huysuzdu o,karakol bekçisi komşu Murtaza….

Kesti topumu,parçaladı, yenisini aldım..

Aldığım topları sokak çocuklarına fırlattım..

Sokak çocuklarının oldu topum,çocukları oynattım…

Gençliğimi yaşamadım dedin sen..

Kızları ayartmadım dedin..

Ben de yaşamadım desem yalan olacak…

Yaşadım…

Tam bir genç kız edasıyla….

Seninle aynı yaşta yaşadım..

Zekice,deli dolu yaşadım..

Komşumuzun oğlunu ayarttım mesela..

Göz kıptım ama elimi tutturmadım yemin olsun…

Sakızlar,bon bon şekerleri aldırdım ona..

Aldırdım da  sokaklara fırlattım,

Sokak çocuklarına tattırdım..

Kitaplar aldırdım sonra.

Sokak çocuklarına dağıttım,kapıştılar..

Mutlulukla tanıştılar…

Ben zaten mutluydum…

Mutluluğu okuttum onlara…

Gençliğimi doya doya yaşadım ben…

Gülleri kokladım, resimlerini yaptım..

Grafon kağıtlarını buruşturup,

Kırmızıya boyadım..

Paslı bir tel bulup,yeşile batırdım..

Bir de yaprak sardım tele,

Verdim ellerine,

Sokak çocuklarının doğum gününü kutladım..

Yüzmeyi dört yaşındayken öğrendim..

Anamdan gizli gizli kaçar yüzerdim..

Daldım denizin dibine, midye topladım.

Geceleri balık avladım..

Yaktım tenekenin altına kocaman bir ateş,

Hepsini kızarttım,

Kızarttım da sokak çocuklarını doyurdum..

Gençliğimi yaşadım ben,

Doya doya yaşadım….

Yaz başında dağlardan,

Ihlamur ağaçlarından çiçekler topladım.

Fındık topladım sonra dalından,

İncir topladım ağacından,kiraz topladım,

Pazarda sattım…

Sattım da sokak çocuklarına bayramlık aldım…

Anam babam alırdı bayramlığımı,

Yoktu ki paraya ihtiyacım….  

Nereye gidiyor insan kalabalığı dedim bir gün.

Taktım koluma bir sepet simidi,

Sanki satacakmış gibi,

Cemaatin arkasına takıldım.. 

Küçücük bedenleriyle toprağa koyulan,

Sokak çocuklarının ardından bakakaldım…

Çocukluğumu yaşamadım dedin sen..

Çiçek toplamadım dedin Boztepe’den.

Boztepe sırtlarında uçurtma uçurmadım dedin.

Onlarda uçurmadılar.!', 'Çocukluğumu yaşamadım dedin sen.. Çiçek toplamadım dedin Boztepe’den. Boztepe sırtlarında uçurtma uçurmadım dedin. Ben de yaşamadım diyeceği...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/cocuklugumu-yasamadim-dedin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Candy', 'candy-hasan-ekrem-lufr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce gülüşlerindi,

Alıp ruhumu,diyar diyar sürükleyen.

Gözlerindi sonra,

Her an neş’e dolu gülen,şen,sevecen.

Alıp aklımı başımdan,peşince sürükleyen…', 'Önce gülüşlerindi, Alıp ruhumu,diyar diyar sürükleyen. Gözlerindi sonra, Her an neş’e dolu gülen,şen,sevecen. Alıp aklımı başımdan,peşince s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/candy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-hasan-ekrem-wuwg5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoksun işte,

yanımdasın oysa biliyorum.

İçimdesin,canımdasın,nefesim değil misin…

Uzatıyorum ellerimi tutamıyorum,

Anlıyorum yoksun yine…

Oysa sensiz yaşayamam ben,

Karşımdasın işte,gözlerin bende,

Kaldırıyorum başımı birden,

Baktıkça sana kayboluyorsun..

O an; 

Anlıyorum yoksun gerçekte..

Bir inansam var olduğuna,

Vazgeçeceğim her şeyden.

Ama dalgınlık işte,sen de unutuyorsun,

Var mısın, yok musun,

Şaşırıyorsun..

Yeter, ne olur bırak bu oyunu,

Sen de biliyorsun..; Yoksun ! !', 'Yoksun işte, yanımdasın oysa biliyorum. İçimdesin,canımdasın,nefesim değil misin… Uzatıyorum ellerimi tutamıyorum, Anlıyorum yoksun yine… Oy...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoksun-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vesaire..', 'vesaire-hasan-ekrem-5caty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O büyüktü,

Kocamandı elleri,

Gözleri vardı,iri.

Saçları hafif dökük,

Sesi gürdü çoğu defa.

Gök gürlemesiydi gülüşü,

Duyan olduysa alabildiğince..

Ve önemlisi çirkindi kendince..

Bir gün O’na rastladı,

O, güzeldi.

O kadar işte,

Gerisi vesaire….', 'O büyüktü, Kocamandı elleri, Gözleri vardı,iri. Saçları hafif dökük, Sesi gürdü çoğu defa. Gök gürlemesiydi gülüşü, Duyan olduysa alabildiği...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vesaire-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamak', 'kacamak-enes-ates-phc6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir an için gözlerinde kaybolmak senin

Kendimi bulduğumda doğmak isterdim.

Sessizliğin buğusunda kayıp şehrinin

Kurak gecelerine yağmak isterdim...

İsterdim karanlığın rengi ben isem,

Aydınlığın düşmanının senin olmanı.

Senin gibi bir gülde, bir diken isem

Gövdenden çıktığımda, hemen solmanı...

Aslında benimki aşkı yuaşamak! 

Ve fanilik içinde bir kaçamaktı.

Tek gerçek sen isen, yalan olmamak,

Gerçek olup yalandan hiç kaçmamaktı...! ! ! ! ! ! !', 'Bir an için gözlerinde kaybolmak senin Kendimi bulduğumda doğmak isterdim. Sessizliğin buğusunda kayıp şehrinin Kurak gecelerine yağmak iste...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun bu..', 'oyun-bu-hasan-ekrem-ifjij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Az sonra açılır perdeler,

Yer yer alkışlarla canlanır sahne,

Ve iner,ağır ağır gözlere çekilen maskeler..

Gerçekler yalandır artık,

Yalanlarsa gerçek.

Büyür gitgide,büyür gönüle her şey,

Her şey sen olursun,ben olurum,biz oluruz..

Bir şeyler çırpınır durur içerimizde,

Öbek öbek..

Oyun bu işte; gerçeği gizlemek,

Göz boyamak,yalanı süslemek..

Yada aksi tam; 

Güneşi sökmek yerinden,

Görmeyen gözlere gösterebilmek..', 'Az sonra açılır perdeler, Yer yer alkışlarla canlanır sahne, Ve iner,ağır ağır gözlere çekilen maskeler.. Gerçekler yalandır artık, Yalanlar...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oyun-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül :-)))', 'gul-hasan-ekrem-rjo6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakta  gül be gülüm,

Gülde geç sanki ne çıkar..

Gülde güller açsın be gülüm,

Gül,kırılsa kalpler ne çıkar..', 'Bakta  gül be gülüm, Gülde geç sanki ne çıkar.. Gülde güller açsın be gülüm, Gül,kırılsa kalpler ne çıkar.....', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmak', 'i-nanmak-hasan-ekrem-1o9hc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın en güzel yanı,

İnanmaktır dilediğince.

İnanmak; o en yüce..

Rengarenk,duru ve parlak,

İyiyi,doğruyu,güzeli,

Bir sevgili gibi savunmak.

Özgürce bulutlar kadar,

Ve onlar kadar ak,

İnanmak…

Sevebilmek önyargısız,

Gülebilmek acılara..

Ezmemek ve ezdirmemek kendini,

Gerçeğe aşık olabilmek.

Can sunabilmek gerektiğinde,

Tutsak olmamak benliğe,

İnanmak…

Yaşamak doyasıya korkusuz,

Yaşamak doyasıya yalansız,

Yudumlamak her an inancı.

İnanarak yaşamak,

İşte hayatın en güzel yanı…', 'Hayatın en güzel yanı, İnanmaktır dilediğince. İnanmak; o en yüce.. Rengarenk,duru ve parlak, İyiyi,doğruyu,güzeli, Bir sevgili gibi savunma...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/inanmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olacak yani?', 'ne-olacak-yani-hasan-ekrem-132lh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tut ki seviyorum seni,

Çılgınca hem de,

Ve basit bir şey bu,

Kim bilir kaç aşığından,

Sadece birisi gibi…

Ve tut ki sevmiyorsun beni,

Ne olacak yani..?', 'Tut ki seviyorum seni, Çılgınca hem de, Ve basit bir şey bu, Kim bilir kaç aşığından, Sadece birisi gibi… Ve tut ki sevmiyorsun beni, Ne ola...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ne-olacak-yani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-hasan-ekrem-rit6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durdu şimdi tüm arzular,

Yaşamak başlıyor yeniden artık.

Benlikler bitti,dindi tutkular,

Çağrıyı canlardan,dosttan aldık..

Gülmek yalnız biz bize, haram artık,

Sevmek yalnız güzeli,olamaz artık,

Paylaşmayı bilmeli,savaş vermeli,

Duygulara zincirler dayanmaz artık..

Yitirmeli kavramlar anlamlarını,

Ne yalnız denizdir mavi olan,

Ne de çamdır,yalnız yeşil.

İnsanlar görmeli gerçek renkleri,

Gerçekler aranmalı,gözler görmeli..', 'Durdu şimdi tüm arzular, Yaşamak başlıyor yeniden artık. Benlikler bitti,dindi tutkular, Çağrıyı canlardan,dosttan aldık.. Gülmek yalnız biz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cagri-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal gözlüm', 'bal-gozlum-hasan-ekrem-f0qoc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun gözlerinde,

Kahkahasında tasasız,

Nazında sevenine kaygısız,

Bulutlar dolar benliğime…

Ve o an gider ruhum,

Titrek bir güz yaprağı olur.

Gözlerim,ellerim,dudaklarım,

Bir sevgili ister,seni düşlerim…

Özler gözlerim gözlerini,

Bal gözlüm…', 'Bir çocuğun gözlerinde, Kahkahasında tasasız, Nazında sevenine kaygısız, Bulutlar dolar benliğime… Ve o an gider ruhum, Titrek bir güz yapra...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bal-gozlum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-hasan-ekrem-6qhmr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sende kilitlendi hep yarınlar..

Umutlar,bir kara sevdada,

Güzellikler,bir silah namlusunda,

Hak,bir tüfek dipçiğinde yok oldu..

Biz,sensizlikte tükendik…

Seninle varolmuştu ilk kıvılcımlar,

Işıklar dolmuştu bütün varlığımıza.

Yaşıyorduk sevdaların en güzelini sende,

Ne güzeldi koşmak yarınlara seninle,

Gönüller sende yine,gönül seferberliğinde..

Hani ne yazacaktık kol kola birlikte,

Uçan kuşa,açan çiçeğe,gök yüzüne..,

Yaşadıksa sen geleceksin diye..

Gel artık,gel de açılsın bahtı ayın

Gel de doğsun artık güneşi yarınların…', 'Sende kilitlendi hep yarınlar.. Umutlar,bir kara sevdada, Güzellikler,bir silah namlusunda, Hak,bir tüfek dipçiğinde yok oldu.. Biz,sensizli...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gel-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak..!', 'yasak-hasan-ekrem-3esnr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi tam ortasındayız zamanların,

Bir adım değiştirecek her şeyi.

Bir adımdır hissediyoruz kıracak bağları,

Yada yıkacak kökünden tüm engelleri..

Bir tomurcuktur,bir goncadır şimdi,

Doğacak olan yarınlarımız,umutlarımız,

Çoban yıldızı çağırırken bizi o enginlere,

Güneş o enginlikler boyu sayıklamadadır..

Açıp açmamak arası düşüncelidir şimdi,

Dumanlıdır,yaşlıdır gözleri nazlı yarin.

Bir çiğ tanesi düşerde o an göz üstüne,

Büyür sonra sel olur,gönülden gönüllere..

Bir adımdır biliyoruz değiştirecek her şeyi,

Mucize değil beklediğimiz yarınlardan,

Bir sözcük, “yasak” prangaların en paslısı,

Bir sevda, inanıyoruz aklayacak yarınları…', 'Şimdi tam ortasındayız zamanların, Bir adım değiştirecek her şeyi. Bir adımdır hissediyoruz kıracak bağları, Yada yıkacak kökünden tüm engel...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasak-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl?', 'nasil-hasan-ekrem-eh2sq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dediler,

Sonludur her şey,

Ömür gibi.

Şu dalga misali anılar dolu,

Hayatta,

Gelir geçer habersiz…

O an yalnız seni düşünüp,

Dedim ki,nasıl geçer

Bir ömür onsuz,sevgisiz…', 'Dediler, Sonludur her şey, Ömür gibi. Şu dalga misali anılar dolu, Hayatta, Gelir geçer habersiz… O an yalnız seni düşünüp, Dedim ki,nasıl g...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasil-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet', 'elbet-hasan-ekrem-m78df', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir başka bahara  kaldıysa eğer,

Bunca zaman beklenen,hasat günü,

Alıştık artık demeyip elbet,

Ellerimizle dereceğiz sonsuzun gülünü…', 'Bir başka bahara  kaldıysa eğer, Bunca zaman beklenen,hasat günü, Alıştık artık demeyip elbet, Ellerimizle dereceğiz sonsuzun gülünü…...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/elbet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''can', 'o-can-hasan-ekrem-r5j94', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgarın içli bir türküsüdür şimdi, O can,

Bir melodidir kulaktan kulağa fısıldanan.

Yolunu yitirmişlere kutup yıldızıdır artık O can,

Bir yıldızdır samanyolunda parıldayan…

İlaç değildi,hekim hiç değildi bir zaman,

Onunla şifa bulur onunla yaşardı bu can,

Tanrı değildi,melek hiç değildi O can,

Fakat onunla doğdu,onunla ışık buldu can..

Keklik değildi dağlarda seken,avlanan.

Güneş değildi gökyüzünde, bulutlarla oynaşan.

Pınar değildi içildikçe doyasıya,kanılmayan.

Mutluluğun kendisiydi,varoluştu O can..

Karanlık günlerin ondördüydü,güldükçe,

Sevdalısının Aslı’sıydı,Leyla’sıydı,sevdikçe…', 'Rüzgarın içli bir türküsüdür şimdi, O can, Bir melodidir kulaktan kulağa fısıldanan. Yolunu yitirmişlere kutup yıldızıdır artık O can, Bir y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-hasan-ekrem-b1jip', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masmavi değil gökyüzü,

Bıraktığım gözlerin gibi..

Ürkek,donuk ve durgun şimdi,

Kurşundan gri..

Gökyüzü bir başka bu akşam,

Bursa’da ağlamaklı..

Ellerim aramakta ellerini,

Tenim tenine sevdalı…', 'Masmavi değil gökyüzü, Bıraktığım gözlerin gibi.. Ürkek,donuk ve durgun şimdi, Kurşundan gri.. Gökyüzü bir başka bu akşam, Bursa’da ağlamakl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Rengi', 'mutlulugun-rengi-hasan-ekrem-imshx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluğum diz  boyudur şimdi,

Güldükçe sen göz bebeklerimde..

Ümitlerim,doğmağa çeyrek kalmış,

Kar beyaz papatyalar gibidir..

Gözlerinin rengine taranmış gökyüzünde,

Bir çift güvercindir ellerin..

Ellerin,dudakların ve gözlerin..

Gözlerin; mutluluk rengincedir…', 'Mutluluğum diz  boyudur şimdi, Güldükçe sen göz bebeklerimde.. Ümitlerim,doğmağa çeyrek kalmış, Kar beyaz papatyalar gibidir.. Gözlerinin re...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutlulugun-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-hasan-ekrem-4deaf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Masmavi,

Engin denizler misali gözlerinle,

Ümitle beklediğim sen güzelim,

Hoş geldin..

Güneşleri kıskandıran,

Pırıl pırıl gülüşünle,

En güzeli çiçeklerin sen güzelim,

Hoş geldin…', 'Masmavi, Engin denizler misali gözlerinle, Ümitle beklediğim sen güzelim, Hoş geldin.. Güneşleri kıskandıran, Pırıl pırıl gülüşünle, En güze...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hosgeldin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmis meger', 'yalanmis-meger-nurten-kederoglu-ju3j1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalanmis meger 

Yalanmis meger sözlerine hep kandim

Bu aksamki bezme gelirsin sandim 

Yolladigin sadece birtane güldü canim 

Kendimi ben bir gül baginda sandim

Askin ruyaymis ne yazik ki tez uyandim

Tatliydi askinin sarabi kanamam sandim

Yoksun yanimda iste yine agliyorum canim

Birtanem sen bana hic kiyamazdin sandim

Siir_ce', 'Yalanmis meger  Yalanmis meger sözlerine hep kandim Bu aksamki bezme gelirsin sandim  Yolladigin sadece birtane güldü canim  Kendimi ben bir...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalanmis-meger-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlığım', 'acligim-hasan-ekrem-oc34g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ak güvercin gecelerde,

Parıldayan kömür karası açlığım,

Seni çaldım ben..

 

Alıp ak güvercin gecelerin koynundan,

Pamuk ovası ıssızlığının en mahrem köşelerinde,

-sinsi ve acımasız bir anofel’in

sıtma sıcağı mecburiyetinden hatta-

Soğuktan çatlamış elleriyle bir ırgatın,

Alnına kazılı gün karası yazgısından,

Ve zümrüt yeşili sürgününden çaldım, 

Açlığımı,

Sen’imi..', 'Ak güvercin gecelerde, Parıldayan kömür karası açlığım, Seni çaldım ben..   Alıp ak güvercin gecelerin koynundan, Pamuk ovası ıssızlığının e...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanildim', 'yanildim-nurten-kederoglu-jz05b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanildim 

Ben bilirim derdimde bilememisim yanildim

Ben gülerim derdimde gülemedim agladim

Ben giderim derdimde yol alipta gidemedim

Ben görürüm derdimde gözledim göremedim

Sen neredesin ey nazlim 

Seni aradim ben hep bulamadim

Bildigim neydiki ben olanlari  hepten unuttum

Güldügüm neydiki hatirlamiyorum ben unuttum

Gördügüm neydiki Ben hic birseyi taniyamadim

Gittigim yer neresiydiki oralari hatirlayamadim

 Sen neredesin ey nazlim 

Seni aradim ben hep bulamadim

YArim kaldi askim bir türlü tamamlayamadim 

Mecalim kalmadi ki artik benim aglayamadim

Yollarina düstüm gurbette ben sana varamadim

sevdigim sen neredesinki  ben seni bulamadim

Sen neredesin ey nazlim 

Seni aradim ben hep bulamadim

Siir_ce', 'Yanildim  Ben bilirim derdimde bilememisim yanildim Ben gülerim derdimde gülemedim agladim Ben giderim derdimde yol alipta gidemedim Ben gör...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yanildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-hasan-ekrem-fff95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep bir yıldız esrikliğindedir yaşamak,

Yıldızın aydınlığınca aşinadır hem bize.

Oysa biter apansız bir hayalin peşinde,

Ufukta gözler bir bitimsiz vuslatı tadarak..

Hep bir yıldız yakıcılığındadır yaşamak,

Yakındır riyaya yakıcılığı kadar, 

Ve bir o kadar ırak düşer gerçeğe.

Nedir ki bir renk yumağı kelebek ömrü,

Geçer,bir göz kırpışı gibi ve kanat çırparak..

“Ezel ve ebed bir nefestir,nefs doysa.”

Oysa,

Gece ve gündüz kadar tanıştır bize,

Gündüz kadar bir gün yarısı,

Ve gece kadar bir düş artığı…', 'Hep bir yıldız esrikliğindedir yaşamak, Yıldızın aydınlığınca aşinadır hem bize. Oysa biter apansız bir hayalin peşinde, Ufukta gözler bir b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasamak-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni baslangic', 'yeni-baslangic-nurten-kederoglu-xrpv2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni baslangic

Dünya ne kadar kücükmüs canim  degilmi bak iste yine bulustuk

Yillar gecti seni ben beni sen birbirimizi birtanem sanki unutmustuk

Nedendi birtanem ben hatirlamiyorum biz sanki ne icin  ayrilmistik

Hani cok seviyorduk canim birbirimizi ne icin biz yeminler  etmistik

Ben her seyi unuttum bir tanem sen hala olanlari  hatirliyormusun

Sarkilardan bana fal tutardin sonrada  kendine sen biliyormusun 

Neydi o eski günler nasil  mutluyduk ikimiz seninle hatirliyormsun 

Eskilere  mazi deniyor sevgilim yeni bir baslangici istiyormusun

Yeni bir baslangic diyorum askimiz bitmismiydi baslasin yeniden

Yine bulustuk diyorum ayrilmismiydik ki ikimiz  bulusalim yeniden

Sanki unutmustuk unutmak mümkünmüydü ki hatirlayalim yeniden

Sakilari bizim icin calar fallari bizim icin tutariz istermisin yeniden

Siir_ce', 'Yeni baslangic Dünya ne kadar kücükmüs canim  degilmi bak iste yine bulustuk Yillar gecti seni ben beni sen birbirimizi birtanem sanki unutm...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeni-baslangic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceviz Kabuğu', 'ceviz-kabugu-hasan-ekrem-0rhvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ardımda yokluğunun fırtınası,

Bir başka düşün peşince iz sürüp,

Ta ufka kadar süzülüp gittim..

Bir ceviz kabuğu yelkenliye açıldı,

Nar çiçeği bulanmış ıslak gözlerim..

Şimdi, sensizliğin denizlerinde,

Her anımda sana teğet geçmekteyim.

“Girdabına kapılmış bir ceviz kabuğu,

Yelkeninde umutlarım,kabuğunda ben.”

Bir başka ihtimal vardı belki de,

Kök salan toprağa,yüzü dönük güne,

Bir gülüş tadında, turuncu ve sarı,

Yaşamak da vardı,

Çiğdem misali hayatı.

Şimdi sensizliğin tam da orta yerinde,

Ve bir resimde gülen gözbebeklerinin,

Beni kavuran yangınında,

-nereden bilecektim..? -

Bir başka lodosun nöbetindeyim..', 'Ardımda yokluğunun fırtınası, Bir başka düşün peşince iz sürüp, Ta ufka kadar süzülüp gittim.. Bir ceviz kabuğu yelkenliye açıldı, Nar çiçeğ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ceviz-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talihi Kıramadım', 'talihi-kiramadim-alaz-enderin-iun2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Talihin bana uğrayacak dermanı yokmuş

Yorgunmuş sabahtan beri dolaşmaktan

Rica etti, sonra uğrasam dedi

Kıramadım...', 'Talihin bana uğrayacak dermanı yokmuş Yorgunmuş sabahtan beri dolaşmaktan Rica etti, sonra uğrasam dedi Kıramadım......', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/talihi-kiramadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol üzerine düşenler', 'yol-uzerine-dusenler-zafer-zengin-etnika-2fx38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hançerle

sivilceli sevda

şimdi yolum alabanda*

altı kilometre yol var daha

sen sevda

hançerle beni

yıkılmış tapınaklarda

sütun başlıklarıyla

bu kent yıkılacak nasılsa

| Yol uzun..Kamyoncu lokantaların da durulur..ne mi yenir..kavurma pilav elbette..kızartma..anneler pişirir sanki..

samimidir ev yemekleri gibi..modern tesislerinkine benzemez..

lezzetsizse kamyoncu yemez.. gezgin beğenmez |

sağlamsın taş duvar

sevdadan ne anlar

özgür kentler

paralarını kendi basar

yolda karakoyun var**

*alabanda antik kenti (muğla izmir yolunda uğrandı..kazı çalışmaları sürüyor

anfi tiyatro neredeyse ortaya cıkmış..yaklaşık 3000 kişilik 

kendi parası olan kentlerden..biraz ilerisinde alinda antik kenti var..görülmesi gerekli yerlerden) 

meraklısı için http://www.geziturkiye.com/html/gezimap2.asp? id=GG090200

**karakoyun dünyanın en güzel kaval ezgisi (osman aktaş''tan dinlenmeli) 

23 08 2004 datca günlüğü', 'hançerle sivilceli sevda şimdi yolum alabanda* altı kilometre yol var daha sen sevda hançerle beni yıkılmış tapınaklarda sütun başlıklarıyla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yol-uzerine-dusenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N''olacak', 'n-olacak-alaz-enderin-bcnoi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'N''olacak beklerim 

Yaz değil mi, kış değil mi elbet geçer

Bu yürek benim, bu serin akşam, 

Bu çaresizliğin demi,

Kırık dökük bu bekleyiş benim

N''olacak, yaz değil mi, kış değil mi elbet geçer...', 'N''olacak beklerim  Yaz değil mi, kış değil mi elbet geçer Bu yürek benim, bu serin akşam,  Bu çaresizliğin demi, Kırık dökük bu bekleyiş ben...', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/n-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yer Yarat Yüreğinde', 'bir-yer-yarat-yureginde-kamber-bal-zo7u4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biçare şansım tökezler durur beyhude

Ağlamaklı olsada gözlerim, selam yok dilde

Ahımı kaldı feleğin şu goncacık gülde

Ara beni bazen hiç olmazsa, o taş yüreğinde

Toprak elim taş, yüreğim ve gözlerim

Yakamozlardan beter parıldar

Çığırtkanlardan ziyade çıkar sesim

Ama nefesim

Isıtmaz seni

Isıtmaz tenini

Ve ben seni düşündükçe her gece

Ağlamaklı olurum yokluğunda

Ne olur! 

Hadi artık

Bir yer yarat 

Yüreğinde...', 'Biçare şansım tökezler durur beyhude Ağlamaklı olsada gözlerim, selam yok dilde Ahımı kaldı feleğin şu goncacık gülde Ara beni bazen hiç olm...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yer-yarat-yureginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfkende Boğulmasın Aşkın,Ağlarsın', 'ofkende-bogulmasin-askin-aglarsin-yuksel-ozbek-qou8i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Memeye aç, kapalı gözlerinle

patikadan geldin yarına.

Alasın diye kirlenen havayı,

ilk dokunuşta tanıdın acıyı,

Doğdun.

..........................................AĞLATTILAR.

Yarım kaldın büyürken,

başardıkların oldu,başaramadıkların.

öfkende boğuldu aşklar,

Korumacıydın özgürlüğe.

ne meleğe inandın,

ne şeytana tapındın.

Gülmeyi öğrenemedin,

İnsandın! ! 

........................................AĞLADIN

Yaprak dökümünde sıra sendeydi.

........................................................AĞLADILAR.', 'Memeye aç, kapalı gözlerinle patikadan geldin yarına. Alasın diye kirlenen havayı, ilk dokunuşta tanıdın acıyı, Doğdun. .......................', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ofkende-bogulmasin-askin-aglarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimi gelmemişti', 'mevsimi-gelmemisti-zafer-zengin-etnika-hetmo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanlık gemi

deniz nereye

uzak ışıklar düşüyor ellerime

ellerim sıcak

yüreğim hasret

| uzak ışıklar düşüyor gözlerime..hep bahsediyorum 

gitmeye param yetmiyor |

yakamoz diyorum

deniz senden yana

çay''a sarılıyorum

kana kana

| denizi bekledim çalmasınlar diye |

ucuz şaraplar

aklımı çalıyorlar

sarhoşken

çakırkeyf sanıyorlar

| Sonra bir dost arıyor..aklıma memleket..aklıma ankara düşüyor |

işleri bitince

teknelerde terk ediliyor gece

tekneleride bekledim

kasabadan habersizce

yazıyorum sanıyorlar

uykularıma hayal sarıyorlar

| Öyle özledim ki türküleri..içimden söylüyorum ancak..dışımdan söylesem herkes deli sanacak |

çay içtim elinden

senden haber gelince

tuzlu bile bile

ses çıkarmadım

içimi yaktım gizlice

gemilerim gelmedi gece

ölsem dedim

şu ışıklar bir sönse

kimseler görmese

| soğudum sonra..bağışladım kendimi.özgür bıraktım seni aşkla..martılar kondu başıma..saydım hepsini sonra..şiirlerim kadardı..onlarda yoksul..onlarda çakırdı

ege kıyılarına sarılmışlardı |

mevsimi gelmemişti

hüzünlenmiştim

fazla değil işte

üç günü 

eylülden istemiştim

| sallanıyor tekneler hala..sallanıyor..sallanıyor |

mırıldanıyorum 

aklımdaki şarkıları

içinde 

aşk''a dair ne varsa

gece görmüyor kendini

karanlıkta

ışığını uzatsana

22.08.2004 Datça günlüğü', 'karanlık gemi deniz nereye uzak ışıklar düşüyor ellerime ellerim sıcak yüreğim hasret | uzak ışıklar düşüyor gözlerime..hep bahsediyorum  gi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/mevsimi-gelmemisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedibinikiyüz dakika', 'yedibinikiyuz-dakika-emirhan-bala-dn8ar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sessiz satırlar devri şimdi, 

kenetlendim yalnızlığa, 

şehrimin tam ortasında kalabalıkta. 

nasıl geçer beş gün,yüz yirmi saat, 

_________________________yedibinikiyüz dakika...', 'sessiz satırlar devri şimdi,  kenetlendim yalnızlığa,  şehrimin tam ortasında kalabalıkta.  nasıl geçer beş gün,yüz yirmi saat,  ___________...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yedibinikiyuz-dakika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu', 'suclu-i-zzet-ermis-vjbcp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey aşk beni yargıla; 

Hiç işlenmemiş günahlarla.

Ey kader beni sorgula; 

Senden çaldığım mutlulukla..

Yok olan gülüşlerin hatırına,

Kahreden yalnızlığın uğruna, 

Sevda benin yüzümden kaybolmuşsa

Yargıla aşk beni,vicdanınla…

Yargıla,fakat şunu anla

Umutları korkutan biri varsa 

O  ben değildim, sakın,sanma

Bir parça mutluluk çaldımsa 

Yalvarırım geri alma.', 'Ey aşk beni yargıla;  Hiç işlenmemiş günahlarla. Ey kader beni sorgula;  Senden çaldığım mutlulukla.. Yok olan gülüşlerin hatırına, Kahreden...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/suclu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Deniz', 'olu-deniz-i-zzet-ermis-qw8aj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Martılar uçuşuyor amaçsızca

Dört taraf ölü bir deniz

Hava  berbat, kuru bir soğuk

Martılar uçuşuyor,çığlık çığlık

Kokuşmuş bir umutsuzluk

Ardından kasvet,bütün bir benlik

Gözler görmekten  bıkmış

Maviden nefret eden ölü bir deniz

Sorumluluktan kaçan ödlek bir dalga 

Denizi öldüren küçük bir ayrıntı daha 

Savruk, savruk lanet  ataklar

Denize  baş kaldıran arsız martılarda 

Ölü denizden balık mı çıkar? 

Aptal martılar,tepede ne işiniz var

Gitsenize açıklara, uçsanıza 

Kendine hayrı var mı ki? Baksanıza', 'Martılar uçuşuyor amaçsızca Dört taraf ölü bir deniz Hava  berbat, kuru bir soğuk Martılar uçuşuyor,çığlık çığlık Kokuşmuş bir umutsuzluk Ar...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olu-deniz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz nota', 'beyaz-nota-emirhan-bala-ci641', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu akşam düğün var, 

sanki sen beyazlardasın, 

varlığınla buralarda hayalin... 

bu akşam hüzün var, 

şarkının notalarındasın, 

''kelepirin'' masalarında hayalin...', 'bu akşam düğün var,  sanki sen beyazlardasın,  varlığınla buralarda hayalin...  bu akşam hüzün var,  şarkının notalarındasın,  ''kelepirin'' m...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beyaz-nota-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Bir Umut Besle', 'yureginde-bir-umut-besle-i-zzet-ermis-605p4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkarsızca,bir yürek taşıyor insan

Çıkarsızca,bir umut besliyor yinede

Kaybolup gitsen de hayallerin ötesinde

Yinede bir umut her zaman

Yakılan düşlerin dumanı

Kaplasa da  tüm duygularını

Solgun gülüşlerden kime ne

Varlık yokluk,

Hep bir  zıtlık karmaşası

Taşınan yürek ihanet etse de

Umutlar sel olup seni boğsa da

Yine de yaşıyor insan 

Bir yürek taşıyarak

Bir umut besliyor  hiç istemese de', 'Çıkarsızca,bir yürek taşıyor insan Çıkarsızca,bir umut besliyor yinede Kaybolup gitsen de hayallerin ötesinde Yinede bir umut her zaman Yakı...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yureginde-bir-umut-besle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Düşünceler', 'sensiz-dusunceler-i-zzet-ermis-kidyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün düşünürüm ben 

Düşüncelerimi elerim 

Arsız fikirlere söverim 

Utansınlar bir kere

Karanlıkları saklarım 

Gün ortasında yıldızları toplarım 

Beynim de şimşekler çakar

Sensiz düşünceleri silerim 

Haykırır tüm benliğim

Sadece seni sevmek 

İçimde,duygusu yaşamalı 

Sevginin ve ben yalnız seni severim', 'Bu gün düşünürüm ben  Düşüncelerimi elerim  Arsız fikirlere söverim  Utansınlar bir kere Karanlıkları saklarım  Gün ortasında yıldızları top...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey mezar!', 'ey-mezar-emirhan-bala-vu2lp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ey mezar! 

ne dahiler barındırırsın, 

ne sevdalar sinende. 

ne kötüleri titretmişindir sen. 

ey mezar! 

ne servetler para pul olmuştur, 

ne kuru''nun yanında yaş''lar yanmıştır, 

ne güçleri sindirmişindir sen. 

ey mezar! 

bütün bunlar, 

sana ne yazar...', 'ey mezar!  ne dahiler barındırırsın,  ne sevdalar sinende.  ne kötüleri titretmişindir sen.  ey mezar!  ne servetler para pul olmuştur,  ne ...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ey-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Kavgası', 'kan-kavgasi-i-zzet-ermis-jlqjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir süphandan bir süphana 

yankılanır deli sesler

kurşunlar havayla sevişir

gök gürültüsü gibi duyulur

yandım Allah! 

Atam pusu tutmuş, saklanır

Dam tepelerinde panayır

Bir evden diğerine mektuplar

İçinde saçma,barut tutuşur

Katledilen bir insanlık

Onursuz kavgalar ve gözler

Yaş dolar,isyanla,küfrederek

Feryat seslerinden rahatsız

Bulutlar, kaçarlar korkarak

Ağıtlar kime yakılır belli mi 

Babasının cesediyle yaşar çocuk

Kan dolmuş tüm yüreği,ne sevgi

Söndüremez, yemin etmiş, intikam yemini', 'bir süphandan bir süphana  yankılanır deli sesler kurşunlar havayla sevişir gök gürültüsü gibi duyulur yandım Allah!  Atam pusu tutmuş, sakl...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kan-kavgasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai-kıpır kıpır', 'rubai-kipir-kipir-emirhan-bala-gxzqn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynalar mı kırış kırış 

suratımın yansıması mı? 

duygularım mı kıpır kıpır, 

yüreğimin yanması mı?', 'aynalar mı kırış kırış  suratımın yansıması mı?  duygularım mı kıpır kıpır,  yüreğimin yanması mı?...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-kipir-kipir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai-yağma yok!', 'rubai-yagma-yok-emirhan-bala-c4t9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağma yok! yokluğunda cezalısın, 

hasretimin yükü katır katır, 

yağma yok! varlığında yazmalısın, 

bedeli birkac saklı satır...', 'yağma yok! yokluğunda cezalısın,  hasretimin yükü katır katır,  yağma yok! varlığında yazmalısın,  bedeli birkac saklı satır......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-yagma-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığım Şehir', 'yasadigim-sehir-i-zzet-ermis-vcbyi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur bulutları çoktan kaplamış

gökyüzü güneşe hasret,bu şehir ağlamaklı

rüzgarlar esiyor korkunç ve kısırlaşmış

bu şehir durgunluğa yalvarmaklı

yok olmuş anılar, mutlu düşünceler 

geçmişine acımaklı bu şehir

suyu akmıyor ki,kurumuş pınarlar

bir damla göz yaşına hasret bu şehir

dağları diken olmuş batıyor ciğerine 

ot bitmiyor üzerine,bu şehir sızlamaklı

yolları bile dolaşmış, bakmıyorlar yüzüne

bu şehir bir avuç toprağa kahrolmaklı', 'yağmur bulutları çoktan kaplamış gökyüzü güneşe hasret,bu şehir ağlamaklı rüzgarlar esiyor korkunç ve kısırlaşmış bu şehir durgunluğa yalvar...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasadigim-sehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklarım.', 'yapraklarim-emirhan-bala-ltnr1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'durgunum ki yaprak kıpırdamıyor 

geri gelmiyor saklı rüzgarlar, 

el yazgısına yazılmışsa eğer, 

fırtınalar tutmaz yaprakları dalında...', 'durgunum ki yaprak kıpırdamıyor  geri gelmiyor saklı rüzgarlar,  el yazgısına yazılmışsa eğer,  fırtınalar tutmaz yaprakları dalında......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yapraklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişen Şeyler', 'degisen-seyler-i-zzet-ermis-uu7qc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep aynı değil mi günler 

Önce batıyor güneş

Sonra doğuyor yıldızlar

Baharda göç eden  kuşlar

Gelirler, yine kış gelmeden 

Sevgiye,sevgiliye adanır 

Kısmen yalnız kalan duygular

Hep bir isyan hep bir çığlık 

Sevdalardan arta kalan 

Dertlerden ve kederlerdedir bolluk 

Umut seli ise koca bir yalan 

Açılırsa yine bir gün

Tendeki sevda gözeneği

Yok olur esrarlı gülüşler 

Oluşur bakışlarda yine

O tatlı anlam

Günler solmuş, geceler kör bir kuytu

İnadına özlem, sevgi denen duygu

Esir alır insanı,

Kalplerdeki siyah tonu 

Öyle olsa da kaybolmaz,

Aşkın, sevginin    yolu

Bu gün yarın hep aynı gün 

Yine aynı yıldızlar

Tepedeki yine  ay

Takvimden azalıyor

Yavaş, yavaş sayfalar

Hep aynı olsa da günler 

Değişen bir şeyler var', 'Hep aynı değil mi günler  Önce batıyor güneş Sonra doğuyor yıldızlar Baharda göç eden  kuşlar Gelirler, yine kış gelmeden  Sevgiye,sevgiliye...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/degisen-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma', 'kacma-i-zzet-ermis-b7u5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaklaşmak istedim sen üzgündün

Dokunmak istedim ellerine 

Çiçeklere büründün 

Kaçar gibisin 

Bir çiçekten bal almış

Arıya nispet uçar gibisin 

Yağmur gibisin

Yedi rengini güneşten almış

Gökkuşağına nispet uzar gidersin', 'Yaklaşmak istedim sen üzgündün Dokunmak istedim ellerine  Çiçeklere büründün  Kaçar gibisin  Bir çiçekten bal almış Arıya nispet uçar gibisi...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kacma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai-saklı gece', 'rubai-sakli-gece-emirhan-bala-i26ym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gece takvim yaprakları, 

saklı geçmişim gibi. 

bu gece yüzümün kırışıkları, 

saklı acılarım misali...', 'bu gece takvim yaprakları,  saklı geçmişim gibi.  bu gece yüzümün kırışıkları,  saklı acılarım misali......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-sakli-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-i-zzet-ermis-snc8j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutları  kıskandırır göz yaşların 

Yinede her zaman gül isterim 

Kahredersin, geçme bahar yaylasından 

Ben senin için irem bahçesinden gül isterim...', 'Bulutları  kıskandırır göz yaşların  Yinede her zaman gül isterim  Kahredersin, geçme bahar yaylasından  Ben senin için irem bahçesinden gül...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esir Ol Aşka', 'esir-ol-aska-i-zzet-ermis-uwgom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökce yürek

Binbir acılar çektik

Çifter çifter seçilip 

Sırdan kafeslere konulduk

Zor değildi esaretlik 

Kendimiz ettik kendimiz bulduk

Aşkın suçu yok

Ey aşk biz sana esir düştük..', 'Gökce yürek Binbir acılar çektik Çifter çifter seçilip  Sırdan kafeslere konulduk Zor değildi esaretlik  Kendimiz ettik kendimiz bulduk Aşkı...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/esir-ol-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetten kovulmanın nedenini buldum!', 'cennetten-kovulmanin-nedenini-buldum-onur-tekin-mwpqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cennette en ucuz şarap ne kadar

ve

indirime

gidilir mi

bir kabir azabı varsa ayrılıklarda

can sıkıntısından 

veresiye ölünür mü ki

kimler olacak başka

ben-sen-o-biz-siz ve 

onlar

ben ordayım

biliyorum

cennet çok küçük

kovulmanın nedenini buldum

yer yok.', 'Cennette en ucuz şarap ne kadar ve indirime gidilir mi bir kabir azabı varsa ayrılıklarda can sıkıntısından  veresiye ölünür mü ki kimler ol...', ARRAY['Türk Edebiyatı','Şiir','Onur Tekin']::text[], 8.5, '{"poet":"Onur Tekin","poet_slug":"onur-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cennetten-kovulmanin-nedenini-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Defa', 'i-lk-defa-i-zzet-ermis-13rzu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekilmiş bir kere

Sevda tohumları 

Körpecik yüreğine

Bilmeden anlamını

Rüyalara dalmıştı

Tutulmuştu nedensiz

Nasıl olduğunu  anlamadan

Adını koyamıyordu

Aha şurası yanıyordu

Gözleri kapalı ağlıyordu

Sesi çıkmadan hıçkıramadan

Ardı arkası kesilmedi 

Binlerce soru, cevaplar yok

Her gece arıyarak

Kendi kendine yanıtladı

Bir suçlu aradı hep

Biri yaptı sandı

Belkide haklıydı

Bu ilk değilmiydi

İlk göz ağrısı

Hem sevinçliydi

Hem ağrısı hem sızısı

Bilmeden sevmişti 

Hep bu masalda kalmıştı', 'Ekilmiş bir kere Sevda tohumları  Körpecik yüreğine Bilmeden anlamını Rüyalara dalmıştı Tutulmuştu nedensiz Nasıl olduğunu  anlamadan Adını ...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilk-defa-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları', 'gozyaslari-i-zzet-ermis-uuyax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Direnemiyorum  bir türlü 

Sanki benim değil benden ayrı

Beste beste türkü türkü

Akıp gidiyor gözyaşları

Yürekte de isyan var,yürekte de 

O da kapılmış sevda seline 

Gözlere inat, firaridir ellerde

Kayıp gidiyor gözyaşları

Bir kere başladı mı serde isyan 

Laf dinlemez artık  hiçbir yan

Göğe mağrur şahikadan

Düşüp gidiyor gözyaşları

Ben nasılım umurunda mı

Kaldıramıyorum boynum eğri

Toprağa doğru  bir seferi

Sürüp   gidiyor gözyaşları

Aşk  söyle bu mu senin adaletin

Sevdaya düşeni,neden ağlattın 

Onlar benimdi sen benden çaldın

Hesap sormaz mı gözyaşları', 'Direnemiyorum  bir türlü  Sanki benim değil benden ayrı Beste beste türkü türkü Akıp gidiyor gözyaşları Yürekte de isyan var,yürekte de  O d...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozyaslari-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Duygular', 'gizli-duygular-i-zzet-ermis-6hk9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgarla dost olmuş hasret

Penceremden esmekte

Hasrete yoldaş olmuş özlem

Bana doğru gelmekte

Bulutlara kızmış yağmur

Türküler sevdaya değil

Yağmur yağmur ağlıyor gözler

Yaşlar sevgiliye değil

Bir ittifak kurulmuş belli

Hayaller fikirler rüyalar

Hepsi anlaşmış  hepsi

Ne siyah beyaz artık dünya 

Nede renkli

Kendini gizleyen gamsız sevgili

İttifakın ardına sığınmış

Zanneder ki, ona bakan kör,duyan sağırmış

Bulutlar,ağlayan gözleri kıskanmış 

Tabiat bana taraf 

Ben kendime rakip

Sürmesin bu paradoks artık

Yeter bitsin bu takip 

Çık artık sende ittifakın ardından 

Söyle gülüm ne söyleyeceksen

İtiraf et  seviyorsan 

Ve ya sevmiyorsan', 'Rüzgarla dost olmuş hasret Penceremden esmekte Hasrete yoldaş olmuş özlem Bana doğru gelmekte Bulutlara kızmış yağmur Türküler sevdaya değil...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gizli-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Üç Kırk Beş Vapuru', 'on-uc-kirk-bes-vapuru-nazife-abayli-2m1sn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizi yırtarak geliyor Kartal vapuru,

Acelesi var belli kaptanın.

Sanki birilerini birilerine kavuşturacak.

Demir atacak az sonra Yalova limanına.

İnecekler insanlar bir bir merdivenden.

Gözüm vapurda,

Gözüm kaptanda,

Gözüm limanda,

Gözüm insanlarda.

Seni arayacağım.

Görsem o merdivenden beni arayan bakışlarla inişini,

Boynuna sarılacağım.

Öpeceğim yanaklarından insanlara aldırmadan.

Belki de yakana değecek dudaklarım kazara,

Rujumun İzi çıkacak  gömleğinin yakasına.

Ve sen gezeceksin...

Yakanda dudak izim......

Kolunda ben.....

Yüreğinde sevdam...

Yalova sokaklarında..!', 'Denizi yırtarak geliyor Kartal vapuru, Acelesi var belli kaptanın. Sanki birilerini birilerine kavuşturacak. Demir atacak az sonra Yalova li...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/on-uc-kirk-bes-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma Yüreğim', 'korkma-yuregim-i-zzet-ermis-8tzg0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dalgalan  ey yüreğim 

umutlarını senden kaçıran 

asi rüzgarlarda,

artık

hayallerimdeki boşluksun benim 

kafesinde esirken aşkın

bir masal yazıyordum aslında

yazık...

bir bitişin başlangıcındayım

sen masaldaki kahraman

kayboldun sayfaların ardında

artık...

uçur uçurtmayı,bulutlara, yüreğim

dert etme elbet gelir zaman

kendini unut arsız kahkahalarda', 'dalgalan  ey yüreğim  umutlarını senden kaçıran  asi rüzgarlarda, artık hayallerimdeki boşluksun benim  kafesinde esirken aşkın bir masal ya...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkma-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-i-zzet-ermis-u2dsy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'toz kondurmadım gülüşlere 

acıyı içime sindiren,sevişlere

yalancıda olsa umutlara 

hep aykırıydı sevda dizilimleri

sonradan sevmek, 

ve ya severken sona ulaşmak

aşkı iki kalbe bölüşmek 

sadece koyu bir ağrıdır aslında 

bir krizdir aşk,

ve toz konmamış duyguların

gizlidir yekpare tadında,', 'toz kondurmadım gülüşlere  acıyı içime sindiren,sevişlere yalancıda olsa umutlara  hep aykırıydı sevda dizilimleri sonradan sevmek,  ve ya s...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-273-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai11', 'rubai11-emirhan-bala-n30g6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'taşıyamıyor yalnızlığımı ruhum, 

bacaklarımda varis bedenim ağır. 

gözyaşlarım dudaklarıma can suyum, 

azrail yeter bekliyor beni çayır....', 'taşıyamıyor yalnızlığımı ruhum,  bacaklarımda varis bedenim ağır.  gözyaşlarım dudaklarıma can suyum,  azrail yeter bekliyor beni çayır.......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeklerden Kaçış', 'gerceklerden-kacis-i-zzet-ermis-3f8q1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir umuttur çırpınan 

içimin taa derinliklerinde

alır götürür beni yine 

gerçeklerden öteye

tutunmak için  o umuda 

hayallere göçerim

bir can çekişmenin öyküsüdür

ve son nefesinde bir umut

yalvarırcasına uzatmış ellerini

bırakmak tutmak yada,

çek kurtar diyor bir ses

kurtar yaşat diyor aslında

ama ölümü zaten belli

hayallerimi hep  kandırmış

kurut diyor başka bir ses

sana uzanmış elleri

kanat çırpar o anda

bana doğru 

bir nefret kelebeği

hisler alemindeyim

umuda yakılmış 

ağıtları dinliyorum

gerçekler yine karşımda

ne olursa osun  onlardan

kurtulamıyorum...', 'bir umuttur çırpınan  içimin taa derinliklerinde alır götürür beni yine  gerçeklerden öteye tutunmak için  o umuda  hayallere göçerim bir ca...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gerceklerden-kacis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai12', 'rubai12-emirhan-bala-hwm50', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlığım....................çekilmiyor... 

ruhum..........................daralıyor... 

son durağım...............geliyor... 

mezarım.....................açılıyor...', 'yalnızlığım....................çekilmiyor...  ruhum..........................daralıyor...  son durağım...............geliyor...  mezarım.......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurmusun', 'olurmusun-i-zzet-ermis-vsxoh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bulut olurmusun benim için

Sonsuz özlemlerimi hatırlatan 

Bir sevda damlası

Kumkum olmuş bedenimin 

Suya kavuşması

Bir bahar ol ve ya

Bende hasret kalayım,tüm canlılar gibi

Seni kıskanayım, bekleyim her kıştan sonra

Sonra kavuşalım, bu sonmuş gibi

Bir uçurtma ol, yüzdürürken gökyüzünde

Bulutlara çarpmanı izleyim

Toplar umuduyla, yıldızları 

Onlar benim artık diyeyim

Bir çarpıntı ol kalbimde

Şiddetinden sarsılayım

Unutursam eğer seni

Her hatırlatışında  yeniden öleyim', 'Bir bulut olurmusun benim için Sonsuz özlemlerimi hatırlatan  Bir sevda damlası Kumkum olmuş bedenimin  Suya kavuşması Bir bahar ol ve ya Be...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olurmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son şehir', 'son-sehir-i-zzet-ermis-0v4tt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınalar kopuyor

Başı dönmüş sana mecbur

Yüreğimin, çığlıklarından 

Bir ağrı, nöbet nöbet sızlatan 

Bir çığlık ki öylesine 

Bu şehrin duvarlarında ve içimin her köşesinde 

Çınlıyor cınlıyor, yankılanıyor

Sadece bir bakıştır 

Tepkisi gözlerimin 

Ağzımı acarsam fışkıran

Deli eden bu seslerin 

Bu hasret bir avuç su

Peşimdeki sele kavuşuyor 

Sende yoksun biliyorum 

Ne sen varsın aslında ne başkası

Aşkın bu şehirde gece  karası

Hep beter karanlıklardayım

Duvar diplerindeki konaklardayım

Bir mürekkep gecenin karasından

Aşkın … yumruklarımın ucunda

Mühür,mühür yazıyorum  duvarlara

Bu şehirdeki son yolculuğumda', 'Fırtınalar kopuyor Başı dönmüş sana mecbur Yüreğimin, çığlıklarından  Bir ağrı, nöbet nöbet sızlatan  Bir çığlık ki öylesine  Bu şehrin duva...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kambersiz Düğün Olurmu?', 'kambersiz-dugun-olurmu-kamber-bal-ysrim', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hoca uyurken yatakta

tüm ahali ayakta

gürültü kıyamet öteki sokakta

ceng-i alem eder bir aylak da

efendim lafın kısası

bize düşmeden tasası

eşikte Hoca''nını asası

ortada  hokkabazın birisi

düşmüşler yola

düşmüşler de az ileride vermişler mola

Hoca-asası bir de hokkabaz

yanlarına sokulmuş utangaç-kurnaz

Dmiş:-Hocam  ben de geleyim 

işin aslını ben de bileyim

demiş demesine de...

Hoca''dan önce hokkabaz çıkışmış

 -Ne işin var senin orada! 

orada var bir kavga

senden bize ne fayda

Hoca şöyle bir kaşını kaldırmış

Biraz süzmüş,bakışlarıyla kızmış

kavuğunu ters çevirip hokkabazı

azarlayıvermiş

-Sen ne karışırsın be adam! 

Utanmazmısın sakalından

Haberdar olmasın mı bu zatın

orada olanlardan

Utangaç-kurnaz Hoca''nın eteğine sarılmış

kendisini de yedeğine aldığı için

başlamış el etek öpmeye

Hoca da başlamış sabır bitmeye

Canmı dayanır bunca emeğe

Hoca demiş:- olurmu hiç böyle olurmu

Kambersiz düğün olurmu

Kambersiz düğün yapan hiç murat alırmı

Neyse ki dostlar karada, havada, denizde şube ve temsilcliklerimiz varda idare ediyoruz.', 'Hoca uyurken yatakta tüm ahali ayakta gürültü kıyamet öteki sokakta ceng-i alem eder bir aylak da efendim lafın kısası bize düşmeden tasası ...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kambersiz-dugun-olurmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırsız Rüzgar', 'hirsiz-ruzgar-i-zzet-ermis-jc9in', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözümde kaç damla yaş olup 

döküldüler

seni birlikte sevdiğim 

hayaller, rüyalar düşler

mevsim sonbahar güneşin son demleri

sonbaharda son yaprakların

üzerine yazdım söyleyemediklerimi

toplarken parklardan birer birer

rüzgara karşı durmuşum

rüzgar ki, sana yolladığım 

kelimeleri çalan,

o kahkahaların sahibi

uçurur yaprakları savurur gider', 'gözümde kaç damla yaş olup  döküldüler seni birlikte sevdiğim  hayaller, rüyalar düşler mevsim sonbahar güneşin son demleri sonbaharda son y...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hirsiz-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-i-zzet-ermis-gtx3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yürüdüm bilmediğim yollarda

yabancı sokaklarda

koştum…

o gözlerin peşinden

kimseyi tanımadığım bu şehirde

kendimle tanıştım

duygularım durak, durak

beklerken düşüncelerimde

yürüyordum…o gözler

düşlerimin de ötesinde 

ve hala çok uzak', 'yürüdüm bilmediğim yollarda yabancı sokaklarda koştum… o gözlerin peşinden kimseyi tanımadığım bu şehirde kendimle tanıştım duygularım durak...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozler-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-i-zzet-ermis-f9rki', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güneşin olmadığı bu garip yerde

gölgelerde yaşamaktayım

uçmaya hevesli umutların

kanatlarını taşımaktayım

hasretle bağlı birbirine

sır düğümleri atılmış ipek kanatlar

şu  kafesteki dünya üzerine

uçmak için çırpınacaklar

bir  avuç güneş getirin

gökyüzünün kalbinden

başına altın taç giydirin

alıp kaçırsın beni hayallerimin 

gölgelerinden', 'güneşin olmadığı bu garip yerde gölgelerde yaşamaktayım uçmaya hevesli umutların kanatlarını taşımaktayım hasretle bağlı birbirine sır düğüm...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ermiş']::text[], 8.5, '{"poet":"İzzet Ermiş","poet_slug":"i-zzet-ermis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/golge-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çok Boş', 'ne-cok-bos-fevzi-gunenc-x8dey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İyi geceler dileme bana 

gecenin iyisi olur mu? 

nasılsın, diye sorma… 

Nasıl olduğumu biliyorsun 

ayıp ediyorsun 

ne zaman iyi olduk ki, amacın 

iyi olmadığımı vurmak mi yüzüme? 

Kendine iyi bak deme bana 

Sen söylemezsen 

Bakmayacağım sanki kendime. 

Güle güle git de deme 

Güle güle gideyim de deli diye 

herkes gülsün mü bana? 

“Na’ber? ..” diye sorma 

Neyin haberini soruyorsun? 

Gazete miyim ben 

Haber bülteni miyim 

Ajans miyim? 

“Arkadaşların selâmi var” 

dememi bekleme benden

desem sanki onların 

selamı senin neyine? 

Ne çok boş konuşuyoruz… 

Değil mi 

ama 

bütün bu boş sözcükleri 

çıkartırsak yaşantımızdan

geriye ne kalır? . 

hiç. 

Demek ki hayatimiz boş. 

Ne hoş? ..', 'İyi geceler dileme bana  gecenin iyisi olur mu?  nasılsın, diye sorma…  Nasıl olduğumu biliyorsun  ayıp ediyorsun  ne zaman iyi olduk ki, am...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ne-cok-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kalacak', 'dus-kalacak-baykal-kaanalp-e762d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hiç düşlediğin yerde

geçmeyecek hayat

gidemeyeceğin uzaklıkları

düşleme sakın

düşünde bile olsa

uzaklaşma kendinden

emin olma geçeceğin

geçmek istediğin yoldan

hiç düşleme düşlerini

nasıl olsa düş kalacak

açılmayacak bir pencere

düşlerinin rüzgarına

ama vazgeçme yine de

boz,dağıt,yeniden kur

gerçeklere çok uzak

kalmasını beklediğin düşünü', 'hiç düşlediğin yerde geçmeyecek hayat gidemeyeceğin uzaklıkları düşleme sakın düşünde bile olsa uzaklaşma kendinden emin olma geçeceğin geçm...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dus-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-baykal-kaanalp-mbcca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hani gecenin bir vakti

delirirde rüzgar

ıslık çalar tabiatın kulağına

habercisidir bir şeylerin

bir yerden bir yere

götürmüştür

umutkarı

taşınmazları taşıyamaz yine de

devamlı uğuldatır kulakları

beklenip de gelmeyen haberler

hani rüzgarla yağmur

dost olamazlar ya,işte öyle

biri ıslaklığı sever

biri kuraklığı içten', 'hani gecenin bir vakti delirirde rüzgar ıslık çalar tabiatın kulağına habercisidir bir şeylerin bir yerden bir yere götürmüştür umutkarı taş...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruzgar-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Duası', 'denizin-duasi-servet-suner-r433f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizin Duası

Deniz; küçük bir kız çocuğu,

Gökyüzünü kaplamış yağmur bulutu.

Şimşek çakıp,gök gürleyince,

Korkup sımsıkı sarılarak teyzesine,

Yalvarıp durur  o titrek sesi ile.

Yoluy teyze,dua edelim de,

Gök kızmasın,atesini yakıp güylemesin.

Yağmuy da koykup aglamasın.

Yoluy teyze dua edelim.

Deniz den  Servet e', 'Denizin Duası Deniz; küçük bir kız çocuğu, Gökyüzünü kaplamış yağmur bulutu. Şimşek çakıp,gök gürleyince, Korkup sımsıkı sarılarak teyzesine...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/denizin-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Sevgi', 'gercek-sevgi-hasan-can-a302t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Henüz yeni tanımaya başlamıştım seni,

Hakkın da duyacağım çok şey vardı.

Düşüncelerin konusun da bilgim yoktu,

Gözlerin nasıl bakar ne söyler bilmiyordum,

Dedim ya yeni tanımaya başlamıştım.

Zaman geçtikçe anlayacaktım seni,

Hak verecektim sana belki,

Belki hiç anlamayacaktım seni,

Belki de sen beni anladığın da,

Sen haksız davranacaktın.

İçimdeki huzuru yitirecektim senin yüzünden belki,

Ben sana aşıktım sen bana değil.

Sen beni anlamayacaktın, anlamadın da.

Gerçekten sevenler her zaman kaybetmiştir,

Ve böyle devam ettikçe yine kaybedecekler...

Oldukça ağır bir yüktün üzerim de,

Senden sonra yıllar geçti ve ben hala o yükü taşıyorum.

Taşımaya devam edermiyim bilmiyorum,

Ama unutamayacağım çok şey olacaktı ilerleyen zaman da.

Üç kuruşluk insanların yanında yalvardığım zamanlar oldu,

Hiç pişmanlık duymadım sonradan.

Ta ki, o insanlara benim sevgimin büyüklüğünü anlatana dek.

Sen o insanların bir parçasısın artık,

Artık seni sadece onlar anlayabilir...

Gerçek sevgiyi sadece gerçekten sevenler bilir,

Ve gerçek sevgi sonsuz gibidir asla tükenmez.

Acılar biter ve gömülür zamanlar,

Sevgi gerçekse asla gömülmez.

Sen gerçekten sevdiğini sandın, ama yanıldın.

Keşke bu yanılgının farkına hiç varmasaydın,

Belki ozaman gerçekten severdin...', 'Henüz yeni tanımaya başlamıştım seni, Hakkın da duyacağım çok şey vardı. Düşüncelerin konusun da bilgim yoktu, Gözlerin nasıl bakar ne söyle...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gercek-sevgi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malazgirt', 'malazgirt-fahrettin-ozturk-xexem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alparslan; 

Şimdi burada ne emreden bir sultan, 

Ne de, emir alan bir asker vardır. 

Hatip; 

Sen, 

Allah’ın dini için savaşacaksın 

Allah’ın zaferini 

Senin adına yazmasını ümit ederim 

Zafer ancak Allah’ın katındadır. 

Ey Allah’ım! 

Müslüman ordularını muzaffer kıl. 

Nihayet 

Bir Cuma vakti 

Minberlerin ağacı 

Hatiplerin seslerinden inledi 

Yer yerinden oynadı haykırmalardan 

Gökyüzü toza bulandı 

Arzulu harp güçlü kılıçlardan 

Ve başı boş otlayan aygırlardan gebe kaldı 

Şimdi silahlı koruyucular 

Ölüm çayırını koruyorlar 

Ve geniş ağızlı kuyuların 

Etrafında dolaşıyorlar 

Öncüler öncülerle 

Keskin kılıçlar keskin kılıçlarla çarpıştı 

Keskin kılıçlar türkü çığırdı 

Sağlam kargılar oynadı 

Süngüler büküldü atlılar cevelan etti 

Ölüm kaseleri dolaştı dudaklarda 

Kısa boylu kargılar doğrulup saldırdı 

Ve başlar uçuştu bir bir. 

Hür bir yüzle karşıladı harp ateşini 

Vuruşma aşını lezzetli bulup 

Teskin edilecek bir sel gibi 

Yada; 

“ Gündüzü kaldıran bir gece” gibi 

Saldırdı 

Yeryüzünü kaplayan ordusuyla 

Bir beyaz ateşi andıran kılıçları 

Şimşek gibi indi düşmanın üstüne 

Birler binleri öldürdü 

Ve binlerden biri bile kurtulamadı 

O gün 

Allah, zaferini onlara indirdi. 

Bundari - Zübdet''ül vüsha vel nuhbet''ül uska dan', 'Alparslan;  Şimdi burada ne emreden bir sultan,  Ne de, emir alan bir asker vardır.  Hatip;  Sen,  Allah’ın dini için savaşacaksın  Allah’ın...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Öztürk']::text[], 8.5, '{"poet":"Fahrettin Öztürk","poet_slug":"fahrettin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/malazgirt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım Kudretine', 'muhtacim-kudretine-baykal-kaanalp-xvcq1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'asla ona söyleme

hiç bir şeyin olmadığını

muktedir olmadığını

satın almaya

satında alınmaya

asla ona söyleme

sevilmeye mhtaç olduğunu

bir maşuk tarafından

ince,narin, nazik

sakın ha,sakın

asla ona bunu söyleme

muhtacım kudretine', 'asla ona söyleme hiç bir şeyin olmadığını muktedir olmadığını satın almaya satında alınmaya asla ona söyleme sevilmeye mhtaç olduğunu bir ma...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muhtacim-kudretine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-fahrettin-ozturk-ki8ft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Sevgili dostum İbrahim Sadri EREN için” 

İbrahim! 

Bir menajer tutmuşsun kendine, 

Hayırlı olsun, 

Sağlık olsun, 

Öyle olsun. 

İstemez misin, 

Bir de stepnesi olsun. 

İşsiz kaldım, işim yok, 

“-Gücüme gidiyor” diyemiyorum, 

Gücüme gitmiyor, çünkü; 

Güçsüz kaldım, gücüm yok. 

Acılı Adana kebabı gibi, 

Her gece bir buçuk, bir buçuk diyorum, 

Programın öyle gidiyor çünkü. 

İbrahim! 

Sana hayranım, 

Seni seviyorum, 

Sana bayılıyorum, 

Seni kıskanıyorum, 

Seni görünce gözüm seğiriyor, 

Seni gördükçe tırnaklarımı yiyiyorum. 

Seni görünce dişlerimi sıkıyorum 

Bir kehribar tanesi gibi takır takır dökülüyor dişlerim. 

Öyle deme be İbrahim; 

Adam olmak kolay mı sanıyorsun, 

Adam olmak kolay değil. 

Henüz 19 yaşındayım, 

Çocukluktan çıktım ama, 

Henüz “Adam” bile olamadım. 

Yine de İbrahim, 

Biliyorsun, 

“Ben kıskanınca Adam gibi kıskanırım.” 

Yalan be İbrahim, 

Her şey yalan 

Tırnakta oje, dudakta ruj yalan. 

Malda yalan, mülkte yalan, 

Var birazda sen oyalan. 

İbrahim! 

Bu mısralar sana tanıdık gelebilir, 

Aynı zamanda başka şeylerde gelebilir, 

Sirkeciden tren gelebilir mesela, 

Troleybüste gelebilir. 

Elini kaldır bir hele, 

Bakkalın çırağı Metinde gelebilir. 

Niyetini sor bir hele bakiyim, 

- Heeey! Metin, nedir senin niyetin? 

Getirdiğin sadece, peynirle zeytin. 

Dedim ya, 

Ben henüz “Adam” olamadım İbrahim,', '“Sevgili dostum İbrahim Sadri EREN için”  İbrahim!  Bir menajer tutmuşsun kendine,  Hayırlı olsun,  Sağlık olsun,  Öyle olsun.  İstemez misi...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Öztürk']::text[], 8.5, '{"poet":"Fahrettin Öztürk","poet_slug":"fahrettin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/serzenis-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burcu Burcu', 'burcu-burcu-baykal-kaanalp-4url4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir su bardağına

doldurursun sevgini

sonra bir erkek

döker üzerine

gömleği,pantalonu

sevgisizlik kokar

burcu burcu

üzülürsün

anlaşılamadığına

ama pişman olmazsın

asla yaptığına', 'bir su bardağına doldurursun sevgini sonra bir erkek döker üzerine gömleği,pantalonu sevgisizlik kokar burcu burcu üzülürsün anlaşılamadığın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/burcu-burcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim Konuşuyor', 'hayallerim-konusuyor-zekayi-sahin-762rj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İdrak ile pençeleşen nefsim,

Tefekkürle inleyen kalbim,

Veciz sözlere hasret dilim,

Vicdanımın dar sokaklarındayım...

		

Kalbe açılan karanlık dehlizler,

Başı boş dolaşan perişan hücreler,

Diz boyunu aşan cürümler,

Gönlümün derinliklerine indim...

Ben ne kadar boşa kürek çekmişim,

Gülistana giderken dikenli yola girmişim,

Heyhat!  Kendimi kaptan zannetmişim,

Şaştım kaldım kendi kendime...

Günahına ağlayan göz yaşları, 

İçini döken ak satırları,

Hizmete koşan dinç ayakları,

Şimdi yeniden karar kıldım...

							

(Nisan 1991-Erzurum)', 'İdrak ile pençeleşen nefsim, Tefekkürle inleyen kalbim, Veciz sözlere hasret dilim, Vicdanımın dar sokaklarındayım... 		 Kalbe açılan karanl...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayallerim-konusuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata', 'hata-mehmet-selim-togluk-05x6o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstersen yerlere vur at kalbimi

Seni çok sevmeyi kendim istedim

Dilim dilim doğra şu yüreğimi

Seni sevmek gibi bir suç işledim

Eksilmesin benden dert ile bela

Gülmek haram olsun ağlamak reva

Hiç kimse olmasın derdime deva

Seni sevmek gibi bir suç işledim

Bükülsün ortadan doğrulan dizim

Bir damla mutluluk görmesin gözüm

Gönlüme eş olsun dert ile hüzün

Seni sevmek gibi bir suç işledim.

Yüreğim bir ömür acıyla yansın

Dertler bir bir gelip bana dayansın

Azrail benim de canımı alsın

Seni sevmek gibi bir suç işledim.

                                                (Akhisar - 1996)', 'İstersen yerlere vur at kalbimi Seni çok sevmeyi kendim istedim Dilim dilim doğra şu yüreğimi Seni sevmek gibi bir suç işledim Eksilmesin be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hata-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefs İle Muhabbet', 'nefs-i-le-muhabbet-zekayi-sahin-ei1aq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Doymak bilmeyen nefislere ince mesajlar''

Nefsim!  Hayatından memnun musun? 

Acı da olsa beni dinle? 

Büyük hakikatleri biliyor musun? 

Acı da olsa beni dinle! 

				

Bu gençlik elbet bir gün gidecek,

Ruhumuz terhis olup kabre girecek,

Etimiz, derimiz toprağa dökülecek,

Acı da olsa beni dinle! 

Hesap sorulacak, berzahta başlayıp,

Açığa dökülecek etti isek ne ayıp,

Vücudumuz titreyip, gözlerimiz ağlayıp,

Acı da olsa beni dinle! 

Amel defterleri havada uçuşacak,

Herkes şaşkın, heyecanlı bakışacak,

Hak ettiğine mutlaka kavuşacak,

Acı da olsa beni dinle! 

Hu sesleri dinince,

İsrafil, Sur’u üfürünce 

Âlem, kıyameti görünce,

Acı da olsa beni dinle! 

				

Amelimiz mizana vurulacak,

Tek tek hepimize sunulacak,

Kaybedende, kazananda bulunacak,

Acı da olsa beni dinle! 

Sırat; kıldan ince, kılıçtan keskin,

Mümin isen geçersin sakin,

Talihsiz isen perişan halin,

Acı da olsa beni dinle! 

Yükselirsen belki; Adn, Firdevs Cenneti’ne,

Düşersin belki; cehennem ateşine,		

Kulak ver, artık vicdanının sesine,

Acı da olsa beni dinle! 

	

(Nisan 1991-Erzurum)', '''Doymak bilmeyen nefislere ince mesajlar'' Nefsim!  Hayatından memnun musun?  Acı da olsa beni dinle?  Büyük hakikatleri biliyor musun?  Acı ...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/nefs-ile-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahillik', 'cahillik-hasan-can-3ymsz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cahilliği anlamanın en kolay yolu, sorulardan geçer. Soru soruldukça cahiller kendilerini gösteriverir.', 'Cahilliği anlamanın en kolay yolu, sorulardan geçer. Soru soruldukça cahiller kendilerini gösteriverir....', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/cahillik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra', 'hatira-mehmet-selim-togluk-mu5p5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden bir hatıra kalsın elimde

Bana bir resmini ver de öyle git

Bir sevdiğim var dı derim benim de

Üstüne bir satır yaz da öyle git

Ela gözlerine bakayım diye

Odamda duvara asayım diye

Öpüp te bağrıma basayım diye

Bir damla mutluluk ver de öyle git

Bakıp ona seni anlatacağım

Onunla maziyi dolaşacağım

Sana özlem duyup ağlayacağım

Gözümün yaşını sil de öyle git

Gidip te bir daha dönmeyeceksen

Bir damla mutluluk vermeyeceksen

Bana bir resmini çok göreceksen

Şakağımdan beni vur da öyle git

Bana vermediğin resmin altına 

Kanımla elveda yaz da öyle git', 'Senden bir hatıra kalsın elimde Bana bir resmini ver de öyle git Bir sevdiğim var dı derim benim de Üstüne bir satır yaz da öyle git Ela göz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hatira-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bomboş', 'bombos-gizem-bilgin-e2ayn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün güne bomboş bir anlam yükledim

Beklemekten belki ya da gelen sürpriz bir tatilden

Zaten yüzüme baktım sabah güzeldim

Tıpkı İstanbul gibi bembeyazdı ama güzeldim

Ve niye ise yüreğim çok daha güzeldi

Burada

Yaşanan her detayın içinde

Hayallerim kararmasın diye bir dua saklıyorum

inandığım neyse

aşksa, hayatsa, Allahımsa ya da olmayansa 

neyse içimdeki

Bir mum yaktım

Bir büyü yaptım

Ve diledim içimdeki güç adına

Tüm havasızlığın içinde nefes alabiliyorsan nedeni ben olayım diye

Ama gene yoksun... Olmuyorsun...

Ben yüreği uzakta bir adam büyütüyorum', 'Bugün güne bomboş bir anlam yükledim Beklemekten belki ya da gelen sürpriz bir tatilden Zaten yüzüme baktım sabah güzeldim Tıpkı İstanbul gi...', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bombos-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz Aşk', 'umitsiz-ask-mehmet-selim-togluk-6aluf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son günlerde halinden belli oluyor derdin

Günden güne eriyen beyaz muma dönmüşsün

Bile bile kendini ümitsiz aşka verdin

Kor ateşe benzerdin şimdi küle dönmüşsün

İsyan eder olmuşsun bu ümitsiz sevdaya

Kendini nasıl attın kahrolası belaya

Gözlerin yaşla dolmuş el açmıssın semaya

Her şeyinden vazgeçmiş dertli kula dönmüşsün

Sonunu bile bile kavuşuruz demişsin

Yeni açmış goncaydın şimdi solan çiçeksin

Saçların beyazlaşmış aşka tövbe etmişsin

Önce hayat doluydun, cansız taşa dönmüşsün.', 'Son günlerde halinden belli oluyor derdin Günden güne eriyen beyaz muma dönmüşsün Bile bile kendini ümitsiz aşka verdin Kor ateşe benzerdin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umitsiz-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat mı?', 'hayat-mi-hasan-can-xu6ol', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok sorular soruldu hayat hakkın da, bir tek cevap alını, o da ''hayat mı? ''', 'Çok sorular soruldu hayat hakkın da, bir tek cevap alını, o da ''hayat mı? ''...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hayat-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Atatürk', 'bizim-ataturk-zekayi-sahin-6dvst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Ata''nın aziz hatırasına''

Yıl 1881 Mustafa Kemâl doğdu,

Doğum ışıkları karanlığı boğdu,

Selânik’te yetişti küçük Mustafa,

Ümit ve geleceği aynı safta.

				

Devrinin en iyi eğitimini aldı,

Düşmanlara hep korku saldı,

Ölüm çanları işgalciler için çaldı,

Vatanı kurtarmaya yürekten inandı.

Yüce Türk Milleti’ne ümit saçtı,

Düşman arkasına bakmadan kaçtı, 

Bizi kurtaran cesaret ve inançtı,

Şehit mezarları nice çiçekler açtı.

		

Yüce Meclis’i açtı, Cumhuriyet’i kurdu,

Genç Türkiye’ye yenilikler sundu,

Türk’ün şanlı tarihi yeniden okundu,

Dünya’ya Türk’ün mührünü vurdu. 

	

Millete oldu, önder Atatürk,

İşte kahraman, işte dahi Türk,

Her Türk sanki bir Atatürk,

İşte, Gazi Mustafa Kemâl ATATÜRK...

(10 Kasım 2001 - MANİSA', '''Ata''nın aziz hatırasına'' Yıl 1881 Mustafa Kemâl doğdu, Doğum ışıkları karanlığı boğdu, Selânik’te yetişti küçük Mustafa, Ümit ve geleceği a...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bizim-ataturk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri', 'biri-gizem-bilgin-5o8tc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyüyen bir gölge gibi soğuk

içimizde tanrıvergisi bir hüzün

Kanatsan da kalıyor, söksen de deşsen de

ben, gece ve bu gölge

Bekliyorum

Biri gelecek...', 'Büyüyen bir gölge gibi soğuk içimizde tanrıvergisi bir hüzün Kanatsan da kalıyor, söksen de deşsen de ben, gece ve bu gölge Bekliyorum Biri ...', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biri-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-zekayi-sahin-yeug1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Dünya''nın çirkin yüzünü gözler önüne seren bir beyan''

Aldandım; dünyanın sahtekâr yüzüne,

İnandım; nefsimin şaşkın sözüne,

Eremedim; nice hakikatlerin özüne,

Çok şeyler kaybettim eyvah...

	

Ağlayamadım günahların kirine,

Birinden kaçarken yakalandım diğerine

Uçurum büyüdü, indi derine,

 Çok şeyler kaybettim eyvah...

Fazilet düşüncesi; uçtu, yok oldu,

Maneviyat eridi, kayıp çok oldu,

Bu haller; fikrime, ruhuma şok oldu,

Çok şeyler kaybettim eyvah...

				

Yunus Emre gibi olana müjdeler vardır,

Zararın neresinden dönersen kârdır,

Yüce Rab’bimiz, en büyük yardır,

Çok şeyler kaybettim eyvah...

(1991-Erzurum)', '''Dünya''nın çirkin yüzünü gözler önüne seren bir beyan'' Aldandım; dünyanın sahtekâr yüzüne, İnandım; nefsimin şaşkın sözüne, Eremedim; nice h...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eyvah-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyeceğim', 'sevmeyecegim-mehmet-selim-togluk-sstb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek başucumda tac olsa bile

Kalbime gem vurdum sevmeyeceğim

Sensiz kader bana gülmese bile

Tövbe ettim seni sevmeyeceğim

Şimdi çok mutluyum yalnız olsam da

Her gece düşümde seni sarsam da

Dünyada sevecek bir sen kalsan da

Tövbe ettim seni sevmeyeceğim

İstersen baharda çiçekler takın

İstersen geri dön diyerek yakın

Unuttum seni ben sev deme sakın

Tövbe ettim seni sevmeyeceğim

                                              (Ankara - 04.05.1987)', 'Sevmek başucumda tac olsa bile Kalbime gem vurdum sevmeyeceğim Sensiz kader bana gülmese bile Tövbe ettim seni sevmeyeceğim Şimdi çok mutluy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmeyecegim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Savaşın İntikamı', 'bir-savasin-i-ntikami-metin-soydan-lo9cg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın

Hatırlamazsın

Kim ne kadar hatırlayabilir ki

Bir çocuğun gece yarısı

Bir gün önce annesiyle birlikte gittiği pazar yerine düşen bombanın 

Gürültüsüyle birlikte yatağından çığlıklarla uyanışını

Ne kadar anlayabiliriz ki

Bir İsrail tankının namlusuna çarpan

Ve hatta çarptığı anda parçalanan taşın

Onu fırlatan en fazla on dört yaşındaki filistinli çocuğa

Ne garip bir mutluluk verdiğini

Biri bana söylesin

Bir savaş daha ne kadar kanlı olabilir

Peki savaş isteyen bir diktatörün cezası ne olmalıdır

Daha kundaktaki bebeğimi zehirlenmelidir kimyasal silahlarla

Ya da büyük umutlarla yetiştirdiği oğlu sınırda taranmalımıdır kalaşnikoflarla

Herkesin bir kini var mutlaka 

Bu yüzden bana sorarsan

Olsa olsa

Savaşta tüm çocuklarını yitirmiş bir annenin tanrısı

Boğacaktır onu akıttığı tüm kanların toplandığı bir kazanda', 'Hatırlar mısın Hatırlamazsın Kim ne kadar hatırlayabilir ki Bir çocuğun gece yarısı Bir gün önce annesiyle birlikte gittiği pazar yerine düş...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydan']::text[], 8.5, '{"poet":"Metin Soydan","poet_slug":"metin-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-savasin-intikami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinayet', 'cinayet-metin-soydan-ums6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızsan eğer,

Mutlaka ortada bir silah vardır.

Ya yalnızlık vurmuştur etrafındakileri,

Ya da sen.

Bu yüzden

Faili meçhul bir cinayettir yalnızlık.', 'Yalnızsan eğer, Mutlaka ortada bir silah vardır. Ya yalnızlık vurmuştur etrafındakileri, Ya da sen. Bu yüzden Faili meçhul bir cinayettir ya...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydan']::text[], 8.5, '{"poet":"Metin Soydan","poet_slug":"metin-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cinayet-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım Islah Et', 'allah-im-islah-et-zekayi-sahin-1lxzc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Bunalıp da, çıkış yolu nerede diyenlere! ''

Nefsim yine bulandı, 

Günah ile sulandı,

Allah’ım ıslah et! 

Ellerim duaya uzandı.

		

Nimetlerine şükredemedim,

Seni hakkıyla bilemedim,

Allah’ım ıslah et! 

Tövbe etmeye geldim.

Nefsim galip geldi,

Şeytan yolumu çeldi,

Allah’ım ıslah et! 

Kulun Sana yöneldi.

İlimde geri kaldım,

Gençliğimi harcadım,	

Allah’ım ıslah et! 

Rahmetine susadım.

(Nisan 1991-Erzurum)', '''Bunalıp da, çıkış yolu nerede diyenlere! '' Nefsim yine bulandı,  Günah ile sulandı, Allah’ım ıslah et!  Ellerim duaya uzandı. 		 Nimetlerin...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/allah-im-islah-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurlu Peygamberimiz', 'nurlu-peygamberimiz-zekayi-sahin-s2gh8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''İnsanlığın son kurtarıcısı efendimizin doğum günü anısına''

Senin için yaratıldı bu kâinat,

Selâm verdi; melekler, semâvat,

Şefâat  eyle ümmetine ey Resûl! 

Dökülüyor dudaklarımızdan salâvat...

		

Hep ümmetine rehberlik ettin,

Yüce Allah’ın yoluna sevk ettin

Şefâat eyle ümmetine ey Resûl! 

Kalbimizi, ruhumuzu sen serinlettin...

				

Cennet ile müjdeledin müminleri

Ateş ile korkuttun münkirleri, 

Şefâat eyle ümmetine ey Resûl! 

Seni arzular hakikat erleri...

				

Mübarek dilinden okudun Yüce Kur’ân’ı,

Aydınlattın; ufukları, bütün cihanı, 

Şefâat eyle ümmetine ey Resûl! 

Senin yoluna verelim bu canı...

					

(Nisan 1991-Erzurum)', '''İnsanlığın son kurtarıcısı efendimizin doğum günü anısına'' Senin için yaratıldı bu kâinat, Selâm verdi; melekler, semâvat, Şefâat  eyle ümm...', ARRAY['Türk Edebiyatı','Şiir','Zekayi Şahin']::text[], 8.5, '{"poet":"Zekayi Şahin","poet_slug":"zekayi-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nurlu-peygamberimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtılan yürek', 'yirtilan-yurek-zafer-zengin-etnika-3613u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'duydum ki

ekinler sararmadan biçilmiş meydanlar da

harman yasak

masallar anlatmayana

| görmekle ilgili..sonradan fark ediyorsun herşeyi..yazdıkların konuşamadıkların aslında..

  defalarca gittiğin yerler bile yabancı sana..insanlar tanıdık yapıyor oraları..taş..kaya..yontu

  deniz..içimize dökülen dereler ve çam ağaçları..hatta öpüşen sevgililer..ağlayan gülen çocuklar bile

  yetmiyor seni bana anlatmaya..yalnızız ikimizde..yalnızlık bile bunun farkında..rüzgarı dinle  |

söyleyecektim

beyaz ışıkları sana

gözlerin

karanlığı anlatmasa

yalnızlık bile

dayanmaz buna

yırtılan bir yürek

dikilir mi

iğne iplikle

dikilse bile

ne sürmeli

izlerine

beyaz karanlık

olamayacak

sürelim biraz yalnızlık

yaralarımıza çok ağladık

çocuklar kadar olamadık

gülsün şimdi yazın doğanlar

yakışır gözlere akan sular

omzumuzda yer var

içine dünya sığar

sarıl şimdi

göğün altında umut var

23 08 2004 datca günlüğü

Kısa bir süre yokum..görüşmek dileğiyle..sevgi..selam ve saygılar..', 'duydum ki ekinler sararmadan biçilmiş meydanlar da harman yasak masallar anlatmayana | görmekle ilgili..sonradan fark ediyorsun herşeyi..yaz...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yirtilan-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilanço', 'bilanco-mustafa-nadi-tascioglu-pok3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalınca kırk yılın bilançosuna

Hesabın içinden çıkamaz oldum

Geçip gitti yıllar boşu boşuna

Geleceği hayra yoramaz oldum

Ben de bir zamanlar gülerdim öyle

Bir ekmeği bine bölerdim şöyle

Belim bükülüp de  kalınca böyle

Yanımda kimseyi bulamaz oldum

Kaya gibi sağlam duruşum vardı

Yanlışa yavuzca vuruşum vardı

Kendime yetecek kuruşum vardı

Yanıldım, yerimde duramaz oldum 

Kaya iken sırt aradım kendime

Yanımdaki ortak sandım derdime

En sevdiğim ağrı oldu beynime

Aklımı başımda tutamaz oldum

Yanıma güvendim yarda bıraktı

Hanıma güvendim harda bıraktı

Dostuma güvendim darda bıraktı

Halimi kimseye diyemez oldum

Ne çektiğim onca derdi çileyi

Ne yalnız yaşanan onca seneyi

Altı metre yerde kaç bin geceyi

Geçirdim, parmakla sayamaz oldum

Usandım hayatın dağdağasından

Vazgeçtim ben eşin dostun hasından

Aşkın şarabını yarin tasından

İçmedim içeni bilemez oldum

Nadi; gelmez ki bu hesabın sonu? 

Yeniden değiştir, gittiğin yolu

Hesapsız önüme uzanan kolu

Pençeler içinden seçemez oldum', 'Dalınca kırk yılın bilançosuna Hesabın içinden çıkamaz oldum Geçip gitti yıllar boşu boşuna Geleceği hayra yoramaz oldum Ben de bir zamanlar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nadi Taşçıoğlu']::text[], 8.5, '{"poet":"Mustafa Nadi Taşçıoğlu","poet_slug":"mustafa-nadi-tascioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bilanco-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Emici Sokaklar....', 'kan-emici-sokaklar-zubeyde-yilmaz-ew774', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir zamanda geliyorsun ki aklıma

Ne yapacağımı bilemiyorum

Dağıtıyorum kendimi

Çakır keyf kafayla sokaklara dşüyorum...

Kısık sokak lambaları

Ürkek,titrek ve sessiz ağlamaklı

Köşede kıvrılmış yatan bir dileenci

Kaderiyle çaresiz,ısınmak için avunduğu

Elinde boş şarap şişeşi....

Şehrin sarhoşluğu zaten üstümde ağırr

Kan emici sanki sokaklar

Birer canavar olmuş

Bak,bak gör ki bizi kemiriyorlar....

sen...

Öyle bir zamanda geliyorsun ki aklıma

Bazen hırçın esen rüzgarla

Ortalığı kasıp kavururcasına...

Bazen dalga dalga,köpük köpük denizden

Ama ben kanı çekilmiş sokağın tam ortasında...

Hep aynı heyecan,hep aynı isyan

Senle olmak adına dağıtıyorum kendimi

Çaresiz sana ulaşırım diye hep yollarda,hep yollarda....

Anlamını bilemediğim,çözemediğimsin...

ve her aklıma gelişte neden kendimi sokağa attığım...

Aşkın gibi,oluşu belkide beni düşüren

Sen gibi,sevdan gibi

biraz hırçın  ve biraz deli

Kan emici sokaklar.....

                                  (12/09/1989 antalya)', 'Öyle bir zamanda geliyorsun ki aklıma Ne yapacağımı bilemiyorum Dağıtıyorum kendimi Çakır keyf kafayla sokaklara dşüyorum... Kısık sokak lam...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kan-emici-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bengal Kaplanı gölge muharebesi', 'bengal-kaplani-golge-muharebesi-akin-akca-9jtia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin aslında hor gördüğün bu gölge’; 

Gözü kara: ‘Yazık ki, sana benziyor, 

Ağır suçlayarak gidip, ses vermediğinde! ’

*

Şu sağ kolundan aşağıya, içerideki; 

Ağaçları anlatır sana:

Gösterir bir ulu ormanı, eski deyişleri anlatır; 

Hakimiyet, üzerindeki ve bugündeki …

Ve dağlara doğru sen, çıktığınca,

Hayali bir pitbull, geziniyor

Oralarda, sağ omuzda …

Ve kaşına çaktırmış iken

Temelleri -

Gölgesi çeliğin - ve kulağın kepçesi …

Aslında hepsi de,

Kalp motiflerinin yüzeyi üzeri …

Yürek fokurdar dipten, ayrılıkta; 

Derken gölgeler -ağlayacak mı- başlamaya …

: Gitmişti yürek, yeni bir temel atışa.

Yeni ama, aynı temel üzerine

Belki, bir dönem, bir rahatlama

Sergüzeştliği -acının kattığı

-Derler: “Ya, sonrası? ”,

“Acıyı mı susturdun, acıyla? ”

Ama, gölgesi bile yoktur Pitbull’un,

Ayrılıklar, daha -dönüşlü- yaşanmamışken:

Bengal kaplanı, vardır! .. Işığı ile oradadır hatta! 

-Vahşi doğanın içinde! 

Acıyla susmadı bir başka acı, demek; 

Uğruna baharlarda sulanacak, sevmek.

*

Tenin içinden fırlar, yaşamak için; 

Onun vahşi gözleri, onun azı dişleri.

Pitbull’sa, bakan nefretle; 

Savurur rüzgara, gölgesini gururla …

Gölgeler uzayamamıştı güneş ile, bu gölgelikte! 

Bu semirişte, bu Pitbull Mamut oldu fakat,

Dişleri onun uzadığında! 

Bak! şimdi, geniş bir gölgeliğe çıktı bu ikisi! 

Ner’den geldi: Pitbull, burada sanki ev sahibesi! 

Fakat Bengal Kaplanı’ysa -onun olamaz tasması! -

Ebru sanatı- bir Kızılderili dövmesi! 

İlk sıçradı tabi, Pitbull, başladı kemirgen! 

Fiskeyle yere düştü, çöreklenen, kaplanın ensesinden! 

Ayağa kalkmasını bekledi şövalye! 

Sonra bir pençe -gerçeğinden- yedi; uzandı, yerde! 

Pitbull yine uyandı, kayaların üzerine fırladılar! 

Başladılar boğuşmaya! Çevrede, ısı düşmüştü, bu esnada! 

Gök gürledi bir anda, çaktı bazı şimşekler! 

Ve ulu orta, ihtiyar meclisinden, 

Üç tane ağaç -yaşlı- devrildi! 

Değil üçünden birinin, üçünün hepsinden; 

… Altında kaldı bu bronz taş bebek! 

: Bu kaplan, onun gözleri doldu yaşla! 

Eğildi hasmının karşısında, büyük saygıyla! 

Bu nefret kusan gözleri kaparken ama fark edecekti -

Kendi göz yaşlarından önce- aynı yaşları yine, nasılsa? ! ! ...

Dayanamadı, kendini astı, sağlam kalan heyetten,

Tekine -gölgeler artık çekilmişti, gökyüzü hürdü! 

O gözlerde ilk görmüş olduğu gibi, 

Ebedi olmuştu son gördüğü de...

*

Pittbull’un geldiği, steplerle buluştuğu,

..İzbe-mahiyetli.. -hörgüç-kısrağı: 

Belki farklıca, su kaynatan savanların

-Ve sertçesine kayalık bölgeleri, steplerin! ..

: Bir dönüm noktası, sulak savanlarla kuru çöl arası; 

Kurak savanların şaşırtıcı tropik yağmur ormanları! ! …

Çölde bir vaha, adı çıkası ada! Kaplanın

Karda izini süren nefret, kuşanmamıştı tasma!', 'Senin aslında hor gördüğün bu gölge’;  Gözü kara: ‘Yazık ki, sana benziyor,  Ağır suçlayarak gidip, ses vermediğinde! ’ * Şu sağ kolundan aş...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/bengal-kaplani-golge-muharebesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çuvaldız korkuluğu', 'cuvaldiz-korkulugu-akin-akca-x8y86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bereketin; yığınından samanın

……………………………… çıkarak - 

Kozasından uçuveren 

………………. kelebek 

-Çuvaldızı fark 

………………. edebilmek, 

İğne deliğinden 

………………. geçmemek! 

~æ~

Çünkü bir gün; 

Astarından çuvaldızın, arttıran terzi:

işinde o, henüz yeniydi; ama geçit’ten hızlı seyretti …

Ve çevrilen pedallar, süratle! ki gittiği yön, her zaman ilersiydi

-Yöneldiğinde geçmişe; 

Kendini yeniledi,..kendi kişiliğinde; 

.. Yaşamdan ziyade! 

~æ~

Kuru çölün iğne deliğinden 

………………. süzülerek 

Farklı bir tüneli 

………………. deneyimlemek  -

……………………………… keşfetmek

Ve böyle, çuvaldızı!', 'Bereketin; yığınından samanın ……………………………… çıkarak -  Kozasından uçuveren  ………………. kelebek  -Çuvaldızı fark  ………………. edebilmek,  İğne deliği...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cuvaldiz-korkulugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Şairin Kafiyesine Muhtaç', 'sair-sairin-kafiyesine-muhtac-fevzi-gunenc-wb3zl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '– Babamın selamı var amca 

hepsini yedik içtik bu yaz 

bizde hiç kalmamış da 

kafiye verir misiniz biraz? .. 

– Kafiye ne oğlum 

– Uyak… 

– Ha, sunu şöyle söylesene… 

Valla bende de kalmadı çocuk 

çarşıdan alayım diyorum ama 

alınıp satılmıyor artık bu meret. 

Git, Nacar, Ayaz, Geneyikli amcanggilerden iste 

onlarda olacak çokça 

biz kendilerinden alıyoruz 

daraldıkça. 

Cimri mi onlar? .. 

Hayır hayır 

dost şair için canı bile kendilerinin değildir 

hiç küşümlenme, iste 

böler yarısını verirler 

kalsalar bile aç 

çünkü bilirler 

şair şairin kafiyesine muhtaç.', '– Babamın selamı var amca  hepsini yedik içtik bu yaz  bizde hiç kalmamış da  kafiye verir misiniz biraz? ..  – Kafiye ne oğlum  – Uyak…  – ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sair-sairin-kafiyesine-muhtac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Girdabı', 'sensizlik-girdabi-gullu-alemdar-zplo6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle zor ki bu şehri sensiz yaşamak

Oysa ki

Her köşe başında sen varsın

Sonuna varmadan giden sen! 

Önceleri derin bir sessizlik

Gidildikçe daralan sokaklar

Alır götürür beni

Sensizlik girdabında 

Yetmezmiş gibi 

Umutları yutan acı girdabı

Gelir rızanı almadan

Yüreğim de inceden bir sızı

Uzaklara dalar bu gözler

Sensizliği iklim iklim

Yaşar gider ömrüm...

Yaradan verir sabrı 

Sızıları sende kalır derinden

Bir bakarsın havalar durgun

Yanan ateş korlaşır

Ama fırtınan dinmez

Hiç ummadık anda 

Kopar gelir girdabınla

Alır götürür beni

(Gülnida)', 'Öyle zor ki bu şehri sensiz yaşamak Oysa ki Her köşe başında sen varsın Sonuna varmadan giden sen!  Önceleri derin bir sessizlik Gidildikçe ...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizlik-girdabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinem Senin', 'sinem-senin-gullu-alemdar-0io4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halimi bir gör

Halden anlamayan sevgili

Bıraktığın yadigarlar

Bile yetiyor beni yıkmaya

Açtığın yaralar kapanmıyor

Sinem kanıyor! 

Bu sızı hiç dinmiyor...

Keşke keşke biraz daha

Kalsaydın diyor bu gönül

En azından biraz daha

Ah bilemedin 

Seni kaybetme duygusu ile

Kaybetmenin arasında ki 

Kat kat daha fazla acıyı

Oysa tek gerçek vardı 

Seni sevdim hem de çok

Ağlatma artık gel

Sana ait bu yüreği al

Al senin olsun....

(Gülnida)', 'Halimi bir gör Halden anlamayan sevgili Bıraktığın yadigarlar Bile yetiyor beni yıkmaya Açtığın yaralar kapanmıyor Sinem kanıyor!  Bu sızı h...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sinem-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir acım var benim...', 'bir-acim-var-benim-sezen-coban-yqh52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir acım var benim

Bir sancım var geçmek bilmez uzun gecelerde

Ne yapsam kâr etmez

Yüzüm güler benim sanırsınız ki siz, hiç derdim yok

Öyle mutluyum sanırsınız ki; 

Ben hep kendimi kandırırım

Yıkılmaya yüz tutmuş ceviz ağaçlarına benzetirim kendimi

Her gelen bir dal kırar gider ve ardına bile bakmaz

Dağlarım içimi tek bir ses bile çıkmaz

Çünkü siz hep beni mutlu sanırsınız

Oysa ben sele kapılmış bir gemi gibiyim

Biliyorum aslında nereye gittiğimi

Sonsuzlukta kaybolurken ben

Yine gülerim

Çünkü siz hep beni mutlu sanırsınız...', 'Bir acım var benim Bir sancım var geçmek bilmez uzun gecelerde Ne yapsam kâr etmez Yüzüm güler benim sanırsınız ki siz, hiç derdim yok Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-acim-var-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüm', 'oldum-birhan-suner-a21fc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki satır gaflete

Işıl ışıl iki ömrü gömdüm,

Öldüm! 

Ayakta yiten ağaçlar; 

Ben hayatta öldüm.

Haberiniz  var mı? ? ? 

Heeeyyyyyy millet! ! ! 

Bileniniz  var mı? ? ? ? 

09.04', 'İki satır gaflete Işıl ışıl iki ömrü gömdüm, Öldüm!  Ayakta yiten ağaçlar;  Ben hayatta öldüm. Haberiniz  var mı? ? ?  Heeeyyyyyy millet! ! ...', ARRAY['Türk Edebiyatı','Şiir','Birhan Suner']::text[], 8.5, '{"poet":"Birhan Suner","poet_slug":"birhan-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oldum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümü bir açsam...', 'gozumu-bir-acsam-sezen-coban-2j7g1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümü bir açsam,sonra kapasam...Ve bir rüyaymış deyip; yine eskisi gibi seni uyusam.Yine eskisi gibi sana uyansam...!', 'Gözümü bir açsam,sonra kapasam...Ve bir rüyaymış deyip; yine eskisi gibi seni uyusam.Yine eskisi gibi sana uyansam...!...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gozumu-bir-acsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat acı demekti...', 'hayat-aci-demekti-sezen-coban-7feoj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine kâbuslarla uyandım dün gece

Hatırıma gelmişti beni bırakıp gittiğin gün

Uykum bölündü yine,bu gece,dün gece

Aklımdan atmak istedim seni

Çünkü acılıydım

Verdiğin tüm güzellikleri öyle çabuk geri aldın ki

Kirlendi bütün ümitlerim

Kan kırmızısı hüsranımı bir türlü yenemedi gençliğim

Hayat acı demekti! 

Üstüne sünger çekse de; anılarım bırakmadı beni benimle

Şimdi her gece aynı kâbus başucumda

Ve beni bırakıp gittiğin gün hatırımda!', 'Yine kâbuslarla uyandım dün gece Hatırıma gelmişti beni bırakıp gittiğin gün Uykum bölündü yine,bu gece,dün gece Aklımdan atmak istedim seni...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-aci-demekti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün ömrüm yeterse eğer...', 'birgun-omrum-yeterse-eger-sezen-coban-arhz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün ömrüm yeterse eğer; 

Zamana bakmadan,hangi senede olduğumuza aldırmadan

Yaşım ve yaşın ne olursa olsun

Sana geleceğim...

Birgün yokluğuna dayanacak kadar güçlüysem eğer; 

Yanımdaki kalabalığı hiç umursamadan

Yüzüme vuran kara ayazlara inat,

Seni sevdiğim için beni yok sayanlara inat,

Sana geleceğim...

Birgün; 

Elimde tek bir umut kalmasa da

En büyük umudum seni sayarak

İçimde ki senle beraber

Bizi beklediğine inanarak

Sana geleceğiz; bekle bizi...', 'Birgün ömrüm yeterse eğer;  Zamana bakmadan,hangi senede olduğumuza aldırmadan Yaşım ve yaşın ne olursa olsun Sana geleceğim... Birgün yoklu...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birgun-omrum-yeterse-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Ele', 'el-ele-halil-kesken-84kxi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömür yaşarım bu heyecanı

Toprağa yağacak bulutmuş gibi

Gel sen de bitirme bu güzel anı

Elini elimde unutmuş gibi

Her an gözlerimde gözlerin olsun

Yürek atışında aşkım duyulsun

Ayrılık saçını, başını yolsun

Hasret çiçeğini, kurutmuş gibi

Işığın yok etsin kara gölgemi

Varlığın ısıtsın soğuk tenimi

Çok daha sıkıca sar bedenimi

Asırlık özlemi tüketmiş gibi...', 'Bir ömür yaşarım bu heyecanı Toprağa yağacak bulutmuş gibi Gel sen de bitirme bu güzel anı Elini elimde unutmuş gibi Her an gözlerimde gözle...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/el-ele-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğret Bana', 'ogret-bana-halil-kesken-trf9g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşılıksız sevgilerden

Kurtulmayı öğret bana

Henüz hiç tanımadığım

Mutluluğu öğret bana

Yeri geldiğinde coşup

Durulmayı öğret bana

Aşkım için yola düşüp

Yorulmayı öğret bana

Mazinin göz yaşlarını

Kurutmayı öğret bana

Kavuşmak hayal olursa

Unutmayı öğret bana

Ezberledim ağlamayı

Gülmeyi de öğret bana

Yaşamaksa yaşamayı,

Ölmeyi de öğret bana', 'Karşılıksız sevgilerden Kurtulmayı öğret bana Henüz hiç tanımadığım Mutluluğu öğret bana Yeri geldiğinde coşup Durulmayı öğret bana Aşkım iç...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogret-bana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever mi Dersin?', 'sever-mi-dersin-cafer-tayyar-ozkan-cmfgz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baş koyarsın, sinemdeki tahtına,

İsyan edersin, gülmeyen bahtına,

Sevda çeşmesi, güzel gözlerine,

Umutla baksam, ışıldar mı dersin? 

Sesin kalbimde, hasretin köprüsü,

Gece bataklığı, ömür törpüsü,

Bir de korkular, eceli yenerse,

Sevgimiz saygıyı, bilir mi dersin? 

Korkunun ecele faydası olsa,

Dillerde umudun şarkısı çalsa,

Her vuslatta bin nağme yazılsa,

Ağıtlar murada, varır mı dersin? 

Kalbimizde sevdamız her an yaşar,

Gönlümüz cehenneme nispet yapar,

Gün gelir de sahibinde kalırsan,

Hüzünler buseyle, geçer mi dersin? 

Durdukça demlenir, aşkınla çayım,

İçimde senden başkasına yer yok.

İstemeden sildiğim gizli ahım,

Gün gelir kalbime, girer mi dersin? 

İnanılmaz duyguların esiriyiz,

Zemheride kardelenler gibiyiz,

Ömür boyu sabır çeken gönüller,

Özlenen sevgiyi, bulur mu dersin? 

Ufkunu sormaya, dilim varmıyor,

Melek gibisin, kollarım sarmıyor,

Sarmaşıklar ukdeme dolanırsa,

Yaralı yüreğim, sever mi dersin? 

Gönüller bilenir, sevda düşünden,

Çare tükenir, umut ülkesinden,

Vuslat şarkısının özel güftesi,

Artık kadere, yazılır mı dersin? 

Her nefesinde, adımı anarsın,

Gündüzler yetmez, gece de ağlarsın,

Yağmur misali akan göz yaşların,

Hoyrat yangını, söndürür mü dersin? 

Ömrün en güzel zamanı geçmeden,

Ektiğimiz çiçek açar mı dersin? 

Senle aldığım nefesi vermeden,

Vuslat çiçeğimiz, solar mı dersin? 

31 Aralık 2003 Ankara', 'Baş koyarsın, sinemdeki tahtına, İsyan edersin, gülmeyen bahtına, Sevda çeşmesi, güzel gözlerine, Umutla baksam, ışıldar mı dersin?  Sesin k...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sever-mi-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahitimiz', 'sahitimiz-asuman-durbin-fldcj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yıldızları şahit tutumuştuk sevgimize

ay ise sırdaş olmuşdu 

hic kimseye böylesine

sevdalanmamış olan  yüreğime

en başında ne dediysem 

ardındayım verdiğim sözlerimin 

gecelerimin ufuksuz özlemisin

rüyalarımın derya denizi

gizli dünyamsın

sevdan engınlerden büyük

dağlardan nicedir ki

su kadar hava kadar gereklisin ruhuma

olmazlarımdasın sen inanmasanda

hala bu yüreğimin sesine

tüm şehirler yasak bana

hayallerin sığınağı oldu gözyaşlarımın

aglarken bırden 

yüreğimdeki sana bakınca

gün doğdu dünyama gülümsedim

ve bir gün döneceğin günü 

hayal ettim gülümsedim

ayrılsakda biz isyan eder tüm evren

bitmez bu sevda der

sevdamıza şahit olan

yıldızlarla ay..

                         03/09/2004', 'yıldızları şahit tutumuştuk sevgimize ay ise sırdaş olmuşdu  hic kimseye böylesine sevdalanmamış olan  yüreğime en başında ne dediysem  ardı...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sahitimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitsem de Seninledir Yüreğim...', 'yitsem-de-seninledir-yuregim-ahmet-ferit-cosan-v8zd0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'onca zaman geçirdiğin

nasılsa aramaz olacak ansızın? 

günlük, insanı boğan telaşelerine yoracaksın,

yaşam derdine, geçim sıkıntılarına vereceksin

arayamamalarının tane tane dizili özürlerini..

neden sonra gelecek aklına aramak,

sormak biriki tanıdık aşinaya...

veeee

''o da kim'' diyecek çaldığın her bir kapının köle ruhlu bekçileri.

merak yapraktan süzülen çiğ gibi,

yavaş ama derinden kuvvetlice girecek ruhunun içerisine...

daireler gelecek resmiyet çelenkleri ile bezeli,

nüfus idaresine gideceksin

kayıtları sorgulatacaksın...

''böyle biri hiç varolmamış ki ''diyecekler sana

bıyıkaltından gülerek veyahut şüphe ile...

çaresizliğini izlerken kendi yüzünden

şen kahkahalarım çınlatacak 

içine asla sığamadığım

doldurulması imkansız boşluğumu.

dayanamayacağım en sonunda,

aynaya baktığın bir anda,

hani tam o gözlerine baktığın sandığın,

lakin gözlerine benim baktığım o sihirli anda işte...

''şapşal'' diye bağırarak görüneceğim gözüne...

''ben sandığınnicedir aradığın halbuki,

güldüğünde gözlerinden fışkıran umut şerhalelerinden başkası değildi ki''

diyeceğim ve yiteceğim apansız...

şaşkınlığın uzun sürmeyecek ey dost,

güleceksin inceden inceye,

yükselen, sel misali coşan bir neşe ile...

neden sonra, 

seni nicedir aramaz olanın,

seni hiç unutmadığını görecek,

kardeşinin bu vefasına iki damla gözyaşı dökeceksin...

güleceksin,

göreceksin,

yitsem de seninledir yüreğim...', 'onca zaman geçirdiğin nasılsa aramaz olacak ansızın?  günlük, insanı boğan telaşelerine yoracaksın, yaşam derdine, geçim sıkıntılarına verec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yitsem-de-seninledir-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende bir yalanmışın', 'sende-bir-yalanmisin-arslan-arslan-jpw6b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğim tek kadın sendin 

Gönlümdeki mutluluğum aşkım sendin 

Yüreğimi dağlayan’da sendin

Şu koca dünya gibi sende bir yalanmışın

Bu sevdam benden sana

Bir hatıra bir anı olarak kalsın

Zaman içinde o da senden hesap sorsun

Son pişmanlık kaderin olsun

İç çekip pişman olmak neye yarar.

Arslan ARSLAN..........02.09.2004', 'Sevdiğim tek kadın sendin  Gönlümdeki mutluluğum aşkım sendin  Yüreğimi dağlayan’da sendin Şu koca dünya gibi sende bir yalanmışın Bu sevdam...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sende-bir-yalanmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüş', 'bir-gulus-ali-aldemir-wtfco', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün kalacaksın bir başına

Çok umursamayacaksın önceleri,

Öylesine dolaşacaksın

Amaçsızca sokaklarda azade

Derken; 

Bir sokaktan geçerken

Bir çocuğun gülümsemesini duyacaksın,

...O gülüş ki öyle saf

....öyle içten

.....öyle sıcak

Bir anda içini ısıtacak

O gülüş alıp seni geçmişe götürecek,

Çocukluğun gelecek aklına

Asfaltsız,kaldırımsız

Toprak kokan yollar,

Ne kadar özlediğini farkedeceksin,

Toprak kokusunu,leylak kokulu bahçeleri,

İncir ağaçlarını,

Salkım söğütleri

Sonra kağıttan gemilerini,

Uçaklarını ve bilyelerini

Unuttuğunu duyumsayacaksın

Rengarenk topaçlarını,

Beynin dumura uğrayacak

Aptallaşacaksın bir anda,

Hasretler vuracak seni

Taraifsiz kederler içerisinde

Bileylenecek içinde özlem,

Sığmayacak için içine

Ağrılar girecek başına

Yiyip bitireceksin kendini

Yollara vuracaksın

Yollar vuracak sana savrulacaksın,

Ağlamak isteyecek ağlayamayacaksın

Seni terkettiğini farkedeceksin

Neden sonra göz yaşlarının,irkileceksin dehşetle

Kendinin de diğerlerinden farklı olmadığını,

Yüreğinin

...taşlaştığını

....katılaştığını

....acımazsızlaştığını göreceksin,

Kendi gülümseyişinle

O çocuk gülüşünün ne kadar farklı olduğunu,

Yapmacıklığını,cıvıklığını

Ve içten olmadığını

Gülmüş olmak için güldüğünü

Nice sonra anlamış olacaksın,

Bu kentin seni nasıl değiştirdiğini

Kan içip kan tükürdüğünü

Ve insan eti yediğini

...hayıflanarak

....söyleneceksin,

Kendi kendine hiç gelmeseydim kente

Hiç büyümeseydim keşke

Çocuk kalsaydım diyeceksin.', 'Bir gün kalacaksın bir başına Çok umursamayacaksın önceleri, Öylesine dolaşacaksın Amaçsızca sokaklarda azade Derken;  Bir sokaktan geçerken...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/bir-gulus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın', 'askin-asuman-durbin-jxa4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşkınla baharı getirmiştin bana

kıpkırmızı açan güler misali

tac edip takmışken başıma

hasretin dağladı yüreğimi

geçmiyor gurbetin günü

gelmiyor özlemin sonu

acarken solan kırmızı güller gibi

solmadan aşkımız

savurdu gitti rüzgar bizi 

aşkın buram buram hasret kokan

sonsuzluğuna........

  03/09/2004', 'aşkınla baharı getirmiştin bana kıpkırmızı açan güler misali tac edip takmışken başıma hasretin dağladı yüreğimi geçmiyor gurbetin günü gelm...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sevdamız', 'bizim-sevdamiz-mehmet-ozer-wy686', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim sevdamız engel tanımadı

Yağmur oldular, toprak olduk

Deniz oldular, dalga olduk

Kar oldular tipi oldular güneş olduk

Artık beraberiz mutlu olduk', 'Bizim sevdamız engel tanımadı Yağmur oldular, toprak olduk Deniz oldular, dalga olduk Kar oldular tipi oldular güneş olduk Artık beraberiz m...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bizim-sevdamiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-mehmet-ozer-kagvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yere düşen ilk kar tanesi gibi

Yağmurun en saf damlası gibi

Bebeğin yüzündeki gülücük gibi

Sevdik biz birbirimizi

Bu akşam düğünümüz var

Bekliyoruz sizleri

Kırk yıllık çınarlar eğildi 

Sevgimizin  önünde

Ozanlar türküler yaktı

Bu sevda üzerine

Dostlarım şahit olun

Aşkımızın düğününe

Kara tren gitti gelmez dediler

Ömür dediğin gelir geçer dediler

Sevgi dediğin bir avuç gül dediler

Erenlere ermişlere dualar ettik

Onlar da bizi evlendirdiler', 'Yere düşen ilk kar tanesi gibi Yağmurun en saf damlası gibi Bebeğin yüzündeki gülücük gibi Sevdik biz birbirimizi Bu akşam düğünümüz var Bek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dugun-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yiyip Şiir İçiyorlar', 'siir-yiyip-siir-i-ciyorlar-fevzi-gunenc-xizp0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Kızınca üzülecek/Kırılıp incinecek/sevilince gülecek/Çocuk Nazlı bir çiçek.//Çocuklar ilgi ister/Dosdoğru bilgi ister/Çocuğu sevgi besler/Çocuk nazlı bir çiçek//Onlarındır bal petek/Onlarındır gelecek/Zamanla büyüyecek/çocuk nazlı bir çiçek.” BÜLENT ÖZCAN

Havasından mı suyundan mı neden bilmem

hep böyle bu toprağın çocukları

baba mühendis olsun diye gönderir Cahit Saraç’ı

Almanya’ya Bern’e

O gider Mızıkacıların yaşadığı Bremen’e

tiyatro öğrenimi yapar mühendislik yerine.

Baba  Londra’ya gönderir Bülent Özcan’ı

geliştirsin diye İngilizcesini 

geliştirir o Şiirce''sini.

Neyse ki kaldırım mühendisi olmuyorlar

sanatçı oluyorlar...

Sanatçının olmuyor 

son model lüks otomobili

yatı

apartman katı

ama onlar severler yaşadıkları hayatı.

Hele şairler hele şairler

mutluluk içinde geçer onların her anı

Şair olmayanlar göremez bunu

Şiirden saraylardır şairlerin mekânı.

Gelelim senin özeline Bülent Özcan…

Görmüştüm zamanında gözlerindeki şafağı

ne doktorluk yazıyordu o şafakta

mühendislik, avukatlık, milletvekilliği ne de

büfecilik yapmaya da niyetin yoktu

babandan sonra Adliye’nin arkasındaki kulübede

Şair olacaktın sen

ille de.

Hazırladığım bir Türkçe ders kitabına

bir şiirini koymuştum zamanında

görmedin bile belki sen

kitabımı ne güzel süslemişti

o şiirin bilsen! 

Ne güzel 

senden güzel haberler almak yıllar sonra…

Evlenmişsin

ne güzel

ne güzel

bir kızın olmuş

adını Şiirsu koymuşsun

Artık senin de var nazlı bir çiçeğin

yaşamının anlamı böylece bölündü ikiye

Şiirdi eskiden tamamı

şimdi Şiirsu oldu yarımın biri.

ama sorun değil ne de olsa 

Şiirsu, şiirlerin şiiri.

Birinci yaşı kutlu olsun bu adıgüzelin

yaşamınca görmesin

tatmasın hiçbir yası

daha nice yaşlarını görebilsin anası /

babası.

Dünya küçük gerçekten

kavuşmasa da dağ dağa

kavuşur gün gelir insan insana

İş o ki

güzellikler bırakılmış olsun geride

kavuşunca

kucaklaşabilsin ayrılanlar birbiriyle.

Kollarımı açıyorum açabildiğim kadar iki yana

gece rüyanda

gündüz düşünde gördüğün kentten selamlar sana! 

Sağlık içinde şiir yiyip şiir içiyor bütün dostların

Bülert Özcan

Şaban Pala dahil, 

kaygılanma.', '“Kızınca üzülecek/Kırılıp incinecek/sevilince gülecek/Çocuk Nazlı bir çiçek.//Çocuklar ilgi ister/Dosdoğru bilgi ister/Çocuğu sevgi besler/Ç...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/siir-yiyip-siir-iciyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kap (kaç) cı...', 'kap-kac-ci-tulay-sustam-ebz3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cebimde; evime, evimden işime,

İşimden dostuma gidecek kadar param var...

Ellerimde; yetime, yetimden dula

Duldan sokak çoçuklarına verecek kadar çiçeğim var...

Allımda; dünden bugüne,

Bugünden yarına gidecek kadar çizgim var...

Gözlerimde; umuda umuttan ümide

Ümitten aydınlığa çıkacak kadar ışığım var...

Gönlümde; şehrime şehrimden memleketime

Memleketimden ülkeme yetecek kadar sevgim var... 

Kalemimde; aileme ailemden dostuma

Dostumdan aşkıma yazılacak kadar şiirlerim var...

Sen yanlış adrese geldin kap(kaç)  cı....

Benden alabileceğin hiçbir şey yok...

Yüreğim, gözlerim, ellerim, gönlüm, kalemim, cebim

Her şeyim aşkla, sevgiyle, dostlukla dolu...

Sen git benim dünyamdan... yakınımdan... uzağımdan...

Ben her şeyi yüreğimle, alın terimle kazandım

Canımı veririm, sahip olduklarımı vermem sana...

(İstanbul, 02.09.2004....SSK hastanesi bahçesi)', 'Cebimde; evime, evimden işime, İşimden dostuma gidecek kadar param var... Ellerimde; yetime, yetimden dula Duldan sokak çoçuklarına verecek ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kap-kac-ci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalarım Ol Benim', 'dalgalarim-ol-benim-olgun-ekinci-6g1nq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalarım ol benim

Kıyılarıma vur köpük köpük

Dalgalarım ol gün batımında

Ağır ve usulca yanaş kıyılarıma

Rengarenk çakıl taşları olayım

Vur köpüklerini renklerime gün ışırken

Gök kuşağı gibi yansısayım 

Üzerimde oynayan çocuklara

Sıra sıra,  kayalıklar olayım

Dalgaların doruklarıma uzansın

Yağmurlar, şelaleler gibi dökülsün üzerimden

Köpüklerinde ıslanayım

Uçsuz bucaksız kumsal olayım

Çarşaf çarşaf seril üzerime

Yaban çalıları olayım

Köpüklerin süt gibi işlesin köklerime

Dalgalarım ol benim

Kıyılarıma vur sabahın alacasında

Önce dingin, sonra sert ve çoğalarak

Köpük köpük, dalga dalga vur kıyılarıma

Sersemleyip sarhoş olayım dalgalarınla

Sabah gün ağarırken

Dinmiş dalgaların üzerin de

Çakıl taşlarında, kayalıklar da,

Uçsuz bucaksız kumsallar da 

Yarı baygın bulsunlar beni

Dalgalarım ol benim

Önce sessizce vur kıyılarıma 

Ve dinle beni

Sevdalarımı, özlemlerimi fısıldayayım sana

Dalgalarım ol benim

DALGALARIM OL BENİM

HAZİRAN 2004 - ADANA', 'Dalgalarım ol benim Kıyılarıma vur köpük köpük Dalgalarım ol gün batımında Ağır ve usulca yanaş kıyılarıma Rengarenk çakıl taşları olayım Vu...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dalgalarim-ol-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmanıma sığınırım', 'i-manima-siginirim-necmiye-sarpkaya-5hec4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hızla ilerlerken ömür denen yolda

Başımı gömdüğüm kumlardan çıkartır

Kaçırdığım fırsatlara yanarım

Cennet Meyveleri yüklü ağaç dalları 

Gelir gözlerimin önüne

Nasib olur mu bilemem 

Düşünürüm iyiliklerimi amel defterimi 

Bazısını gösteriş silmiş bazısını gıybet 

Amel defterim bomboş

Kaçan fırsatlar pişmanlıklar yakar 

Sinemi alev alev

Açılıverir dağarcık çıkınım 

Dökülür bütün hesabım ortaya 

Ne yapacağımı şaşırır 

Utançlardan kaçış ararım. 

Artık pişmanlık yaşları 

Söndürmüyor bu ateşi..... 

Her şey bitti sona geldim 

O anda birden toplanır 

Yüreğimde saklı olan 

İmanıma sığınırım 

Necmiye Sarpkaya

Necmiye Sarpkaya', 'Hızla ilerlerken ömür denen yolda Başımı gömdüğüm kumlardan çıkartır Kaçırdığım fırsatlara yanarım Cennet Meyveleri yüklü ağaç dalları  Geli...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/imanima-siginirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Son Sabahıma...', 'en-son-sabahima-sezen-coban-fygpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susadım yine sana

İçip içip te kanmayacağım,tek şey sana

Susadım bu gece,varmaz sabaha

Muhtaçlığımı gizleyemem karşında

Dudaklarım çatlamıştır,kokunu duymak isterler bu son gece

Yaralı ceylan gibidir yüreğim; 

Çırpınır durur da, bir cana hasret bekler bu son gece

Ellerimden kayıp gider gençliğim

Ne söylesem nafile,gelmez geriye bu son gece

Uğruna adadığım bir ömrün tükenişidir bu son gece; varmaz sabaha

Demiştim ya! 

Susadım yine sana

İçip içip te kanmayacağım,tek şey sana

Susadım bu gece; varmaz sabaha...', 'Susadım yine sana İçip içip te kanmayacağım,tek şey sana Susadım bu gece,varmaz sabaha Muhtaçlığımı gizleyemem karşında Dudaklarım çatlamışt...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/en-son-sabahima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sen varsın dünyada...', 'bir-sen-varsin-dunyada-sezen-coban-kkakg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin kokunu duydum dün gece

Sarıldım sana başbaşa kaldım hayalinle

Öptüm,kokladım

Bir sen vardın dünya da bir de ben  o anda

Kapatmıştık kapılarımızı

Darmadağın aşkımızı yaşıyorduk,sadece sen ve ben

Sen kendini yaşatıyordun

Ben; bitmek tükenmek bilmeyen seni...

.....

.....', 'Senin kokunu duydum dün gece Sarıldım sana başbaşa kaldım hayalinle Öptüm,kokladım Bir sen vardın dünya da bir de ben  o anda Kapatmıştık ka...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-sen-varsin-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'merhaba', 'merhaba-i-brahim-dikmen-zr06o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlara kendini sevdiremedin gitti

sonunda herkes küstü gitti

meğer bir şey yapmamışsın kimse için

bir merhaba demen yetecekti

Bir merhaba deseydin kilometreler ürkecekti

bir kelimeye bin anlam yüklenecekti

içi boş şimdi o kelimelerin içi boş

bir merhaba deseydin mana gitmeyecekti

Tüm zamanların en suçlususun sen

bir muhabbet başlamadan (mı?)     bitecekti

taşkın sular belki yatağına dönecekti

bir merhaba kimbilir kaç ömür yetecekti

Merhabayla dostun bağına rahmet inecekti

merhabasız kalan bahçelerde zakkumlar bitiverdi

merhaba ki hepimizi gönülgaha çekecekti

o merhaba denseydi kimse küsmeyecekti', 'İnsanlara kendini sevdiremedin gitti sonunda herkes küstü gitti meğer bir şey yapmamışsın kimse için bir merhaba demen yetecekti Bir merhaba...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen']::text[], 8.5, '{"poet":"İbrahim Dikmen","poet_slug":"i-brahim-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merhaba-428-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz seninle....', 'biz-seninle-sezen-coban-zodxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz seninle hep aynı havayı soluduk

Aynı topraklara bastık

Aynı şeyi düşündük,aynı şeyi hissettik

Ve biz öyle bir sevdik ki; 

Ne dünya yetti sığdırmaya,ne insanoğlu...', 'Biz seninle hep aynı havayı soluduk Aynı topraklara bastık Aynı şeyi düşündük,aynı şeyi hissettik Ve biz öyle bir sevdik ki;  Ne dünya yetti...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-seninle-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahbe Eylül....(12 Eylül ''ü Yaşayanlara..)', 'kahbe-eylul-12-eylul-u-yasayanlara-fatih-taskin-ots0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaz bitti... 

Giden yine ömürden gitti.... 

Ve işte sonunda; 

Kahbe Eylül yine geldi... 

O yıllar yeni doğmuştum.... 

Ama 

Ben yaşıma bastığımda 

Gençliğine doyamamış.... 

Sevdaları yitik kalmış... 

Aşklarına doyamamış... 

Nice canlar yokolmuştu... 

Bu giden canların sağı-solu yoktu. 

İkiside aynı terazideydi... 

Amaçları da vatan sevgisiydi. 

Belki de.... 

Belki de ilk defa yaptıklarından, 

Yapacaklarından...yapamadıklarından... 

Pişmanlık duyuyorlardı..... 

Olgunlaşıpta aradan yıllar geçince; 

Bu pişmanlıklarını itiraf ediyorlardı. 

O dönem kardeş kardeşi vururken 

Şİmdiler de düşmanlar tartışabiliyordu. 

Ve, 

İki tarafında tek temennisiydi: 

O canlar...dava adamları.... 

.............keşke................ 

Keşke ölmeseydi..... 

Ve sonunda.... 

Şu gerçeği kimse unutmadı: 

Her yılın Eylül ayı geldiğinde 

İçleri kanayan yaraydı.... 

Gönülleri yalnız kalmış fukaraydı.... 

Sevdaları dalında kurumuş yapraktı.... 

Ve.... 

Davaları onların içini kemiren yılandı... 

Ama... 

Onlar için EYLÜL daima.... 

Fahişe rahminden düşen bir piçti... 

Öyle de kaldı.... 

Öyle de kaldı.. 

siyah bereli.... 

eylül....', 'Yaz bitti...  Giden yine ömürden gitti....  Ve işte sonunda;  Kahbe Eylül yine geldi...  O yıllar yeni doğmuştum....  Ama  Ben yaşıma bastığ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kahbe-eylul-12-eylul-u-yasayanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-adulera-ayza-y79xq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok mu acı çekmek istersin

 O zaman yaşama ayak uydur

Çok mu mutlu olmak istersin

O zaman zamanı durdur

                    Kimse çözemedi daha beni

                    Bir af r i k a dayım bir gün ne pal de

                    Kimse ağlatamadı daha beni

                     Bir gün bendeyim bir gün sende

Beynimin kıvrımlarına yazıyorum seni

Ama anlam veremiyorsun bebeğim

Bağıra b a ğ ı r a yazıyorum seni içime

Ama istemiyorsun beni kelebeğim

                    Unutma! senle konuşacak çok şeyimiz var

                           Aşka kavgaya ülkeye dair

                     Unutma! senle paylaşacak çok şeyimiz var

                    Ekmeğe yarın yanağından başka her şeye dair', 'Çok mu acı çekmek istersin  O zaman yaşama ayak uydur Çok mu mutlu olmak istersin O zaman zamanı durdur                     Kimse çözemedi d...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aci-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye', 'maviye-adulera-ayza-dnyzy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşündüm de haklısın galiba

Sevmeyi beceremiyorum ben

Öğretmediler sevmeyi dünyada

Belki  öğretirsin sevilmeyi sen

            Varsayalım öğrettin bana sevilmeyi sevmeyi

            İlişkide adam gibi olmayı mücadeleyi etmeyi

            Tüm    olumsuzluklara            göğüs germeyi 

            Öğretebilir misin?  yeniden sevmeyi sevilmeyi       

Arızalıyım ben düzelmem zor olabilir

Her arızalı gibi kenara atılmak kaderimdir

Senle aşkı sevmeyi sevilmeyi yaşamak varken

Bir kenarda durmak beklemek kaderim midir?', 'Düşündüm de haklısın galiba Sevmeyi beceremiyorum ben Öğretmediler sevmeyi dünyada Belki  öğretirsin sevilmeyi sen             Varsayalım öğ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/maviye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-adulera-ayza-4mfym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç huzurum kalmadı bu günlerde

Yanıtlar da beni tatmin etmiyor

Acılarda artık bana  zevk vermiyor

Böyle olurum ben bu mevsimlerde

Haber bekliyorum sanki belki senin haberini

Bir haber olsun da yeter ki 

Zamana karşı yarıştırıyorum sevdiklerimi

 Almalıyım artık belki kendi ölüm haberimi



Sonra hiç bitmeyecek olan hesaplaşmalar

Yaşanmamış yarım yamalak dünyalar

Pişmanlıklar için çok geç artık bilmelisin

Ya dünyada yada benimle yaşarken ölmelisin

       7 nisan 2004', 'Hiç huzurum kalmadı bu günlerde Yanıtlar da beni tatmin etmiyor Acılarda artık bana  zevk vermiyor Böyle olurum ben bu mevsimlerde Haber bek...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hesaplasma-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feveran(2)', 'feveran-2-ferhat-epozdemir-8rd4h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağrı bağıran dağlardan

 ve karnı kahır kadınlardan öğrendim

 feryadı yamalı

 talihi kanamalı

 bir tarihin yankısını..

 yazgısı viran bir halktan öğrendim

 yüzleri kavruk...

 düşleri vuruk çocukların öyküsünü

 sürüklenen insanlardan

 donan ayaklardan

 ve kesilen kulaklardan duydum

 yürekleri revan  hayatların

                    savruk  serüvenlerini

 sırtları şarapnel

 elleri kınalı

 bir mevsimdi yanımızdan hızla geçen

 içimize değen bir keskin ayazdı

 ve elbette bunu birgün yazardı

                  tenimize biçilen kefen...

                            ayaklarımıza giren kangren

 artık susun istiyorum yeniden

 ve lütfen...

 biliyorum...yüzümüze düşen aklar

 ve dağlarımıza düşürdüğünüz destanlar

sizin yüzünüzden

bu sevinçler

bu seherler sizin yüzünüzden

kendinizi vurmayın böyle dizelerime

dizelerim sizin kopan dizlerinize...dilsizliğinize

dizleriniz başımın üstüne

hüznünüz gözüm üstüne

hadi düşlerinizden dönün artık

onlar müjdesiz

onlar çok hayatsız

durmayın öyle imlasız

alın ağrılarınızı

ve dönün çamurlı yollarımıza

aç karınlarımıza dönün

ağaran saçlarımıza

artık sürün kendinizi yeni bir umuda

yeni bir dünyaya

bizi ihtiyar eden bu ömürlerden çıkın

bu verem bakışlardan kopun artık

çünkü bu yüzyılda bizi kimse duymayacak

o halde dönün evinize..eviniz çok sıcak

içinize girsede böyle ansızın bir bıçak

inanın eviniz çok sıcak

ve geldiğinizde çocuklar hep size bakacak

öyle çok kaçak...

öyle çok kucak...

farzedin bir rüzgardınız

eserdiniz...

bir dağdan ötekine

bir daldan diğerine

ardınızdan morarsada umutlarımız

bileğimiz kopsada kahrından

yıkılsada evlerimiz başlarımıza

bu hayırsız zamanlar boğsada sevinçlerimizi

dönün yinede bu tensiz cephelerden...

                       bu yağlı hayatlardan

öyle bükmeyin boyunlarınızı

öyle heder olmayın

mağlup ordular gibi durmayın

o incitilmiş duruşlardan çıkın artık

silahlı yada silahsız

doğru yada yanlış..dönsenizde

inanın siz kazandınız yinede

mağlubiyet bizde yüzyıllardır bir kader

ve biliyorum bu yaşadıklarınız

                        öyle çok beter

                             öyle çok nefret

                                  öyle çok dehşet

sizin sevinçleriniz bir vakit ötede

çevirin yüzünüzü

ve unutun artık olanları

bize yapılanları

geride kalanları

belkide..ölenleri

yüreğinize giren o lanet nefeslerden çıkın

gözlerinize düşen o masum buğuyu atın

dökün içime....o burukluğu..indirin yüzüme

dönün içime hemen

                içim kan zaten...

                      içim üryan...

                           içim feveran ezelden

kimseye soramadık

kimsede bizi sormadı zaten...

bize ne oldu bu bahar....

                bu hazan.....

                      bu mevsim? 

Biz ne çok vurulduk bu yüzyıl...bilen varmı? 

Yama tutmuyor artık bu yaralı bedenlerimiz

kırıldık tek tek.....tanınmaz oldu cesetlerimiz

bir bende...

bir tende...

bir izde arandı vurulan gençliğimiz

şimdi çığ gibi önünüzdeyiz

güç sizin..

erk sizin..

dem sizin

hadi recm edin artık beni

çiğneyin özlemlerimi..

alın ayaklarınızın altına yarınlarımı

yok sayın yeniden

ben suçluyum...kazanın beni yeniden

hadi katın beni kendinize...

harmanlayın..

beni öğütün

ben kimliksizdim zaten ezelden

benim yaralarım derinden

bir kalp taşıdığımı unutun

ve savurun beni...

değiştirin...

yüzümü yakın

ve öyle sevin beni kendisizliğimden

ne kadar çok acımasızdınız bu yüzyıl...

ne kadar çok pervasız...

bu yüzyıl nasılda bu kadar kitapsız...hayasız

çocuklar nekadar çok annesiz...babasız

bu yüzyıl nekadarda çok talan rüyalarımız

yaslarımız ve yaşadıklarımız

artık bizim çok yaşlı yaşlarımız...

yani yaşadıklarımız

artık bizim yaşlılığımız...

her sevgilide nasılda dağlandı bu kadar hayatlarımız

bizim dağlanmamız

biliyorum bizim biraz dağlılığımız

bizim dağlılığımızda artık dağlanmamız....

biz yenildik bu yüzyıl...

satıldık bir pazar...

örselendik bir gece...

boğazlandık bir uyku...

                     bir gülüş...

                     bir düş...

hadi dönün artık o ince bellerden

                            o yaralı dillerden

dağlanmaya sebep dağlılığınız ve dağlarımızla...

yaslarınız

            yaşlarınız

ve yaşadıklarınızla...

artık dönün 

ve unutun olanları

kendinize bir şans dileyerek

dönün kentinize

           köylerinize

           göğüslerimize...

ve sırtınızı dönmeyi bir daha

arkanıza bakmayın bir daha....

arkası uçurum...

arkası revan...

şimdi hangimiz lal....

                kimimiz figan....? 

işte bundan bu feryat...

                   bu feveran....

                                    (Tüm haksız ve halksız savaşlara ithaftır) 

                                          

                                           06  Ağustos  2003-istanbul', 'Bağrı bağıran dağlardan  ve karnı kahır kadınlardan öğrendim  feryadı yamalı  talihi kanamalı  bir tarihin yankısını..  yazgısı viran bir ha...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Epözdemir']::text[], 8.5, '{"poet":"Ferhat Epözdemir","poet_slug":"ferhat-epozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":156,"source_url":"https://www.antoloji.com/feveran-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ali-gencay-htu99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I-

sen

denize atılan 

umut 

düşler dolu şişe 

korkma sahile vurmaktan 

nedir bu endişe

elbet biri bulur 

okur

dudaklara dökülür

hece,hece

umutların 

hayallerin 

kimse bilmez

gizemli sır

efsane

III-

korkular

neyin 

deliğinden çıkan 

ince ses

geceyi yarar 

inlercesine 

gece

pare,pare

her paresi

katran

zifirce

III-

sen

duyduğum ses

aldığım nefes

seni dinliyorum

sessiz

öylece', 'I- sen denize atılan  umut  düşler dolu şişe  korkma sahile vurmaktan  nedir bu endişe elbet biri bulur  okur dudaklara dökülür hece,hece um...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/umut-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandı', 'yandi-elcin-orhan-pea5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gür sevdam yanıyor, 

hadi ara bul bir damla su! 

içinde mavi kelebeğim saklı kozam yandı, 

çok kırılgan dallarım kırılmaz artık 

dallarım yandı 

ölü kuşlar bir kez daha can verdi 

yuvaları,

yuvasında ki yavruları yandı 

umut fidelerim, 

adın yazılı ağacım, 

öldüm dişlerim bile yandı 

ağla(r) sam yağmur yağardı 

öyle arşa ulaştı ki! 

yağmur bulutlarım bile yandı.', 'gür sevdam yanıyor,  hadi ara bul bir damla su!  içinde mavi kelebeğim saklı kozam yandı,  çok kırılgan dallarım kırılmaz artık  dallarım ya...', ARRAY['Türk Edebiyatı','Şiir','Elçin Orhan']::text[], 8.5, '{"poet":"Elçin Orhan","poet_slug":"elcin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Zaman', 'zaman-zaman-adulera-ayza-wjuok', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bütün bildiklerimi üstüste koydugum zaman

             hiç bir şey bilmedigim ortaya çıkıyor

             sensizlige alıştıgım an

             yürecigim  her an kanıyor

                             yalan olmuş her şey yalan yada dolan

                             sevdicegim yüreklim kadınım  offf aman

                             sende bildiklerini üstüste koy o zaman

                             sen düşünme takma beni bir an................', 'bütün bildiklerimi üstüste koydugum zaman              hiç bir şey bilmedigim ortaya çıkıyor              sensizlige alıştıgım an           ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaman-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Deme...', 'olmaz-deme-i-brahim-ethem-bingul-31i0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökler bulut yüklü, yağmura gebe,

Rüzgâr bu rahmete olurken ebe

Sağnak sağnak yağar yağmur üstüme

Çorak toprağımda bendeki kirden

Yaradan dilerse gülistan olur...

Güneş, doğuşunu ışıkla kutlar

Aydınlığa kavuşunca hür ruhlar

Gönülde gülümser, o sevgili yâr

Yardım eli, kuyudaki esirden

Hükümdar çıkarır,halk hayran olur...

Kalbim sabret no''lur,dilim şükre kaç

Kollarım hamle yap, at birkaç kulaç

Dertler dert küpünde olmuş bulamaç

Niceleri bu dertlerin ilminden

Her derdi bitiren bir derman bulur...

www.iebingul.com', 'Gökler bulut yüklü, yağmura gebe, Rüzgâr bu rahmete olurken ebe Sağnak sağnak yağar yağmur üstüme Çorak toprağımda bendeki kirden Yaradan di...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmaz-deme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum...', 'ariyorum-sirma-mersin-s386s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün birileri 

Bişeyleri arıyor! ...

Sevdiğini kaybedenler 

Duvara kayıp ilanı asıyorlar...

İş arayan işsiz arasına düşmüş üniversiteliler

Gazete ilanlarında iş arıyorlar...

Evde kalmışlarsa 

Evlilik köşelerinde eş arıyorlar...

Mutluluk tüten bi yuva için

Ev arayanlar...

Aranan ne çok şey var! 

Ben mi? ne arıyorum...

Yüreğimin eş ruhunu 

Beyaz traktörlü prensimi 

Sevgi tomurcukları ile 

Mutluluğuma emek verecek birini arıyorum...

Seni arıyorum 

Nerdesin? Hangi ilandasın? 

Bilmiyorum...

Kaderin yazdığı ilanda isen

Karşıma çıkmanı 

Beklemek zorundayım...

Biliyorum! ...

3.9.04 

            ''Duygularım konu arıyorken, yazıldı...''

Not: Bir dostumla yaptığımız muhabbet sonrası çıktı, ortaya... 

         Dostum''a teşekkürler...', 'Her gün birileri  Bişeyleri arıyor! ... Sevdiğini kaybedenler  Duvara kayıp ilanı asıyorlar... İş arayan işsiz arasına düşmüş üniversitelile...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ariyorum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Zaman Suskun Kalan Yanım', 'her-zaman-suskun-kalan-yanim-selim-bayrak-tkbtc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her zaman suskun kalan yanım...

Oldum olası sessizliğin rengine yanığım

Hafif bir ürperti ardından pembe bulutlu ufuklara dalan nemli gözlerle

Tinime doluşan renkli gölgelere sanığım

Suçum eylememek

Kötü günleri avaz avaz bağırıp

Önümdeki adımları sendelemek

Suçum eylemek 

Rast gele  adımlarımı

Bir amaç uğruna biçimliyormuş gibi gerinmek

Her zaman suskun kalan yanığım

Hiç adını fısıldamadığım

Her an bir ad aradığım

Adlı arabalarda uğruna dolandığımı sandığım

Sandıkta bıraktığımı sandığım anılarım

Beni nasıl da sarmaladıklarını anlamadığım

Gökyüzüne kaldırmadığım başım

Çukurları takip etmekten muzdarip baş ağrılarım

Göz ucuyla geçiştirilebilecek kavislerde

Kuytulara dadandığım

Dadalara dadanmadığım

Sal(l)  apati yarışlarda hep sonuncu gelip

Nasıl olsa hep salladığıma yandığım

Hep onu unutmaya çalışıp

Ona dolandığım

Çarşaflara özgürlük pankartımı açıp

Çarşambalara çıkamadığım

Bol keseden atıp salılarda salındığım

Sultanların salıncağında telgraflı yollarda bekçiliğe yollandığım

Cumaları hep tatile girip pazartesileri aşık olma ihtimaliyle uyandığım

Perşembeleri daha gelmeden perişanlık edebiyatına başladığım

Günlerimi biriktirip battal boy çöplere boşalttığım

Neden hep gelmediğini merak ettiğim saplantılarım

Gelmesine hiç de uğraşmadığım umutlarım

Uğraşmak zorunda kaldığım somutlarım

Adını unuttuğum soyutlarım

Soyunmak için giyindiğim gri boyutlarım

Biraz aydınlansam rengarenk olduklarına kandığım...

Seni taşımadan

Ağırlığında bunaldığım

Esamesi okunmaz masallarda

Uğruna savaştığıma inandırıldığım

İnandırıldığımdan bahisle

Temyize gitmeden kendimi akladığım..................

9 Mayıs 2004-İstanbul', 'Her zaman suskun kalan yanım... Oldum olası sessizliğin rengine yanığım Hafif bir ürperti ardından pembe bulutlu ufuklara dalan nemli gözler...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/her-zaman-suskun-kalan-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son nokta...', 'son-nokta-sah-ali-yasar-63m8o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben aslında top yekun güneşi avuçlayacaktım 

Şeytan gören yüzlere çalacaktım mükerrer 

Renk versin

Işık saçsın

Isı yaysın diye

Her cenahtan

Her canlıya

İnceden inceye…

Gökkuşağına boyayacaktım çocukların sevinçlerini

Kerhen de olsa kısır kalplerce  duyulacaktı

Suya yalın gölgesini düşürecektim baharın

Çığ gibi kopup gelecekti hüzünlü bekleyiş sonrası umut

Yeşil yankısı dalga dalga yayılacaktı…

Gezilmedik  tenhası kalmayacaktı bulutların üzerinde

Aç kurt gibi çöreklenecekti geceye ayın şavkı 

Resmedecektim mutluluğun manzarasını gitmeseydin

Gitmeseydin seni yarınlara çizecektim alengirli

Kılcal fırça işleyecektim huşu içinde aşkı…

Az kalsaydın yanımda ressam olacaktım

Gittin

Şair oldum…

Ben aslında yıldızları ulayacaktım omuzlarıma

Nirengi noktasında avunacaktım nükteli sözlerin

Perdesiz pencerelere vuracaktı günün ilk ışığı

El ermemiş şiir

Dil değmemiş türkü kıvamında

Davetsiz uyanacaktım çapağında mahmur gözlerin…

Bir topal çekirgeye duruşunu bozmayacaktı ala kuş

Medet dilenmeyecekti muhannetin kapısında yetim

Zedelenmeyecekti yüz akı onuru

Ayarsız ağızlarca itilen nimet

Gudümsüz ayaklarca tepilen kısmet

Kaybolmayacaktı kabul görmüş duaların uğuru…

Beyhude yaşama gıptayla bakılmayacaktı ahir zaman

Gaflet içinde olmayacaktı sevda varisleri

Tutacaktım boğazından meretin

Basacaktım kanı bozuk damarına

Dinime boğacaktım üstümüze sinmiş kötü nefesleri…

Yüreğini verseydin zengin kalacaktım

Aldın 

Fakir kaldım…

Ben aslında denizleri boylayacaktım katıksız

Maviyi soluyacaktım ebedi

Karın ağrısı karanlık 

Beyin törpüsü biat 

Yıkacaktım cılkı çıkmış zihniyeti 

Ödün vermeyecektim belkemiği değerlerden

Hakir görmeyecektim canı

Sevgi gönül bağı

Boş gönül it yatağı

Telli duvak süsleyecektim dört bir yanı…

Sonradan görmüşlerin borusu ötmeyecekti zil zurna 

Böyle el insaf hırpalanmayacaktı düşler

İki dudak arasında son karar

Namlunun ucunda son nokta

Böylesine kaldırımlarda donmayacaktı civan gülüşler…

Vursaydın alnımdan şehit düşecektim

Bağışladın

Esir düştüm…', 'Ben aslında top yekun güneşi avuçlayacaktım  Şeytan gören yüzlere çalacaktım mükerrer  Renk versin Işık saçsın Isı yaysın diye Her cenahtan ...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/son-nokta-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar''em', 'yar-em-huseyin-dogan-ytnxq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda''m sevda.................      ..........kara

Dertdi''m dert.........................          ......onmaz

Ateşim Ateş,

Koru''m kor.

Yar''em yara.............................              ....merhemsiz

Yar''im yar...............................                        .....bir AŞK', 'Sevda''m sevda.................      ..........kara Dertdi''m dert.........................          ......onmaz Ateşim Ateş, Koru''m kor. Yar''...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yar-em-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-hekim-coskun-0v3vf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tüm zenginlikleri

tanrı adına kendileri

kullanır,

sağdıkları ineğin

sütünden peynir,

derisinden kürk yapar, etini kurda

kuşa yem etmezler.

Ve tanrının ilahi

adaletinin; bir gün

herkesi eşit

kılacağına inanır, avuçlarını açarak

ve beklerken

sıkıldıklarında,

derin ve anlamlı ilahilerin gizemine

kendilerini bırakarak ne kadar

yakın olduklarını

düşünürler tanrıya.

Yaşam devam ederken; döndürüp

dururlar, aynı suyun dümeninde

öğütülen

buğday misali bizi.

Ve onlar mutlu olsun diye ayrı

yaşarız

hücrelerimizden.

kafa, kol, bacak

biraz da mide

taşıyorsa bedenimiz

onlar içindir.

Başkaları için kader olan acılar,

onlar için kıyametin geldiği

gündür.

Ve biz; 

Onların keyifli

yaşamlarına meze eden geleneklerimizin

tılsımlı, birazda

otoriter baskısı

altında ezilirken,

yeterlerimizden değil,

öldüklerinde

pis bir leş gibi kokmaktan korkarak gizlerler

cesetlerini

yerin dibine.', 'tüm zenginlikleri tanrı adına kendileri kullanır, sağdıkları ineğin sütünden peynir, derisinden kürk yapar, etini kurda kuşa yem etmezler. V...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/onlar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamdan- Dörtlükler', 'babamdan-dortlukler-meral-yagcioglu-1f5jd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vicdanlar

Kalkmış askıya vicdanlar kilitli kafeste

Kan kusuyor ruhlar hepsi hasta

Canavarlaşmış insanlar ne fayda

Kalmaz mazlumun ah ı çıkar aheste aheste

			Kuloğlu 1974

İnan

Bakıp da aldanma gülen gözlerime

Kalbim kan ağlıyor inan

Dünyanın tüm derdi yüreğimde

Sinem alev alev yanıyor inan

		Kuloğlu 1978

Kabus

Kabus gibi çöktü üstüme keder

Bilmem yolumun sonu nereye gider

Düşürdü bu hallere beni kader

Yeter Allah’ım çektiğim azap yeter

			Kuloğlu 1981

Yaşamak

Beyhude geçti bu fani hayat

Dön bir yol maziye bak

Neler geldi neler geçti heyhat

Her şeye rağmen güzelmiş yaşamak

		Kuloğlu 1966', 'Vicdanlar Kalkmış askıya vicdanlar kilitli kafeste Kan kusuyor ruhlar hepsi hasta Canavarlaşmış insanlar ne fayda Kalmaz mazlumun ah ı çıkar...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/babamdan-dortlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklimdasin', 'aklimdasin-oktay-hacimusali-iju2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AKLIMDASIN

Gun gunorta yerinde... 

Aklimdasin yine, 

Aklimdasin... 

Aklimdasin  dunden kalma boyat cayi isitirken 

Ve icerken yine aklimdasin. 

Yuregime iniyor ictigim cay. Oksuruyorum boguk - boguk. 

durup dolasiyorum odada 

Kokun sinmis bu daginik odamin her kuytu kosesine 

Sen olsaydin… Sen olsaydin bu daginik odam gocmen yuvasina benzemezdi. 

Annem hep soyler Oktayin odasi gocmen yuvasina benziyor - diye. 

Gercekten te oyle. Ara - sira benim de topladigim oluyor etrafi. Fakat sen baskaydin. Senin itinani gosteremiyorum saksidaki gullere bile. Soldular hep. Belli ki,hasretteler. Senin hasretinde... 

Gun gunorta yerinde... 

Aklimdasin yine, 

Aklimdasin... 

Bilmiyorum ne olduysa aniden dugum dusdu bizim askimiz. 

Ancak onceler farkliydi her sey. Bir an olsun dayanamiyordun hasretime. 

Her defasinda ben sana bir demet kirmizi gul alirdim. 

Sense koklayarak o kirmizi gulleri 

Boynuma sarilirdin cocuk gibi 

Ellerimin sicakligini duyardim avuclarimda. Solugunun gul kokusu yalar gecerdi yuzumu. 

Sana armagan ederdim yazdigim tum siirlerimi. Garipti, fakat sana da bulasmisti bu siir hastaligi. Yazmiyordun, ama nerden eline bir siir gecse, biriktirirdin hemen. Sevgi siirleriydi bunlar esasen. Anlamsiz ve abartili ibarelerle doluydular. Bahs etmezdim tum bunlardan sana. Incinirsin diye. 

Gun gunorta yerinde... 

Aklimdasin yine, 

Aklimdasin... 

Ve aniden bir kac gundur okula bile ugramadigim aklima geliyor. 

Hic disari cikmadim gidisinden bu gune. Nobet bekledim. Hatiralarinin nobetini. 

Bu da senin bana sebgimin karsiliginda verdigin deger. Asla suclamiyorum seni. 

Eninde - sonunda gidecektin. Gittin iste…

Gecenlerde senli gunlerimin anisina defterimi karistirdigimda kagitlarin arasindan buldum resmini. Arkasinda ne yaziyordu, biliyormusun? …

Neyse, moralini bozmak istemiyorum… Ancak sunu bilmeni istiyorum:aklimdan hicmi hic cikmiyorsun. Aklimdasin hep. 

Bu gun, iste su an, gun gunorta yerindeyken sen de beni hatirlayiver bir anligina. Ve dusun soyle bir bak bakalim, aniden dugum dusen askimizin dugumunu coze bilecekmisin? 

Cozdugunde bir haber yolla bana. Bekliyorum…', 'AKLIMDASIN Gun gunorta yerinde...  Aklimdasin yine,  Aklimdasin...  Aklimdasin  dunden kalma boyat cayi isitirken  Ve icerken yine aklimdasi...', ARRAY['Türk Edebiyatı','Şiir','Oktay Hacimusali']::text[], 8.5, '{"poet":"Oktay Hacimusali","poet_slug":"oktay-hacimusali","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aklimdasin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Yüzde 99', 'yuzde-99-gul-ozan-3yvny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen

şarap ve su

bahar ve güz

ateş ve buz

şeker ve tuz

ama

yüzde 99', 'sen şarap ve su bahar ve güz ateş ve buz şeker ve tuz ama yüzde 99...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuzde-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-volkan-gurses-xiagk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapat sımsıkı perdeleri

İki kez kontrol et; 

Sana bakarken parlayan gözlerimden

Işığım

Odana

Sızmasın...', 'Kapat sımsıkı perdeleri İki kez kontrol et;  Sana bakarken parlayan gözlerimden Işığım Odana Sızmasın......', ARRAY['Türk Edebiyatı','Şiir','Volkan Gürses']::text[], 8.5, '{"poet":"Volkan Gürses","poet_slug":"volkan-gurses","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunaydin-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Shakespeare Usta''ya', 'shakespeare-usta-ya-gul-ozan-95sgl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizi dinliyorum, hiç kesmeyiniz, 

bulutlanmadan, hep böyle yalın, 

açık ve duru kalın, su gibi...

Ey gözler, birikmişleri söyleyiniz.

Yüreğime güvercinlerinizi salın.

Yokluğunuz aydınlıklara pusu gibi...

Öyle seviyorum ki, siz de seviniz,

yeşil kıvrımlarını uzanan dalın,

şarap şişesinin buğusu gibi...

Öyle güzel ki gözler, renginiz,

tadını paylaşır çiçekli balın,

yönünüz, büyünün doğusu gibi...

Uykuyla beslenir, dinlenirsiniz,

Isının altında dantelden şalın,

eski bir sevdanın uykusu gibi...

Gözler, bana güneş olun ve deniz.

Hep böyle benimle, yanımda kalın.

Özlenen sevgilinin kokusu gibi...

Yüreğimi aydınlatan gözler, bilseniz,

gölgesi gibisiniz koşan hazalın,

Düşsel bir göletin kuğusu gibi...

Öyle ak yürek, ak kanat, ak alın...

(Shakespear Pîr e saygıyla...)', 'Sizi dinliyorum, hiç kesmeyiniz,  bulutlanmadan, hep böyle yalın,  açık ve duru kalın, su gibi... Ey gözler, birikmişleri söyleyiniz. Yüreği...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/shakespeare-usta-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Şahsi Tarihim sende Kayıtlı', 'sahsi-tarihim-sende-kayitli-gul-ozan-esktu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...Sade, o masmavi, kopkoyu akan su 

ve kenarındaki üç beş yeşillik değil

erguvani bir kaç dalım var Rumeli Hisarında

Martılar var bir de simidimi paylaşan

Güvercinler, dostlarım Beyazıt Meydanında

Vapurda eski birinci- yeni açık koltuklar

Fotoğraf sergileri, fuarlar, vitrin bakmalar...

Kitap raflarında dolaşan elim

Uzun zamandır beklediğim film

Pazar kahvaltıları deniz kenarında

Penye beğenmeler Salı Pazarında

Ama asıl seni özledim, çocukluk tarihim! 

Senden ayrılık zulüm... güzel Istanbul''um! 

Sen benim en unutulmaz şiirim,

Çizdiğim en güzel resim, 

duyduğum en güzel isim.

Yüreğimin içinden akıp duran nehir, 

doğup büyüdüğüm şehir.

Yaşamasam da seni doyasıya, 

gelmemişsem de aylardır

Şahsi tarihim sende kayıtlıdır!', '...Sade, o masmavi, kopkoyu akan su  ve kenarındaki üç beş yeşillik değil erguvani bir kaç dalım var Rumeli Hisarında Martılar var bir de si...', ARRAY['Türk Edebiyatı','Şiir','Gül Ozan']::text[], 8.5, '{"poet":"Gül Ozan","poet_slug":"gul-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sahsi-tarihim-sende-kayitli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin kadar', 'senin-kadar-anil-kecelioz-8mhov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ıslak kaldırımlarda bıraktım artık izini

yoksun artık benim için,hiçsin

kimbilir belki gün doğuyordur şimdi topraklarında

belki sabah olmuştur, sevinmişsindir

ama bilirsin sevmem sabah tomurcuklarını

gün yanlızca uyumayan için kıymetlidir.

hangi sözle tutuştursam kalemimi

sonu hep çıkmaz sokaklara varıyor

her şiir söylenmiş,her mısra yazılmış

senin için şiir yazmak beynimi öldürüyor

bana en iğrençlerinden satılmış

yıllarca anlatılan aynı aşk masallarından.

sevmiyorum seni hiç bilmem ne kadar

dişine dukunulmuşluğu gibi koca bir devin

çöküp depremde gitmesi gibi eski bir evin

portakal çekirdeği,yorgan düğmesi,musalla taşı

hatta yargılamak yangın gecelerini

inan hiçbiri korkutmuyor beni senin kadar.....', 'ıslak kaldırımlarda bıraktım artık izini yoksun artık benim için,hiçsin kimbilir belki gün doğuyordur şimdi topraklarında belki sabah olmuşt...', ARRAY['Türk Edebiyatı','Şiir','Anıl Keçeliöz']::text[], 8.5, '{"poet":"Anıl Keçeliöz","poet_slug":"anil-kecelioz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senin-kadar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NEŞEsiz günler', 'nesesiz-gunler-anil-kecelioz-2sf7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bazen insan yalvarıyor allaha

değiştirmek istiyor bazı şeyleri

insanları ikna etmek bu kadar zorken

tanrıyı ikna etmeyi kolay mı sandın.....', 'bazen insan yalvarıyor allaha değiştirmek istiyor bazı şeyleri insanları ikna etmek bu kadar zorken tanrıyı ikna etmeyi kolay mı sandın........', ARRAY['Türk Edebiyatı','Şiir','Anıl Keçeliöz']::text[], 8.5, '{"poet":"Anıl Keçeliöz","poet_slug":"anil-kecelioz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nesesiz-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çooooooooooook seviyorum', 'seni-cooooooooooook-seviyorum-hekim-coskun-cuaou', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çünkü sen bana yakın

beni anlayan

kollayan koruyan

ve gerektiğinde sollayansın

benden ileri gittiğinde

ya da ben senden geri kaldığımda

ellerini uzatarak yanına alansın

sen ana kadar şefkatli

bir yar kadar sevgi dolusun

seni çoooooooook seviyorum

yaşama karamsar baktığımda

azarlayan

mutlu olup şımardığımda

ayıplayansın

en çok sevdiğim nedenlerden biri

paylaşansın

seni kıskandığım anlarımda

paylaşılansın

sen yalnızlığıma kalabalık

sıkıldığımda yalnızlığımsın

sen gerektiğinde bir ana

gerekmediğinde

çok sevdiğim babamsın', 'çünkü sen bana yakın beni anlayan kollayan koruyan ve gerektiğinde sollayansın benden ileri gittiğinde ya da ben senden geri kaldığımda elle...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-cooooooooooook-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül ve Yağmur', 'eylul-ve-yagmur-abdulkadir-ogdum-9tw8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Münzevi davaların hissedar mahkemesi

Eylül! Beni en mecnun çarmıhında yargıla! 

 *

Güz beldesi gönlüme yağmış yağalı efkâr

Çektiğim elem değil, bir fikir üzgüsüdür…

Koynumda ufak ekmek, gezerim abdal, ne kâr! 

Şu ördüğüm manzumlar sevdamın türküsüdür! 

Eylül! Tomruk, yaprak, dal… Ne varsa dök nârıma

Elbet bir gün yağacak o yağmur efkârıma! 

 *

Kıskanır seni aylar, mevsimler meftun sana 

Ve sen yirmi asırdır alnındasın Hazan’ın…

Şükür, çözdüm sırrını; artık şifa masana

Yatır da, cerrahı ol bu divane ozanın! 

Eylül! Bana da derman var mı rahmet kâsende? 

Zira bu yıl Mirac da, Leyl-i Berat da sende…

 *

Bir çeyrek asır geçti, ilk gözyaşımdan beri

Ve şimdi ateşten bir gölde deviniyorum! 

Toprağımda bir benim bu sevdanın kamberi

Her düğünde başka bir hicran giyiniyorum! 

Eylül! Göster şanını, cümle cürmüm erisin

Sen ki, şu hazinenle aydan daha berisin! 

 *

Tek tesellim, her gece uyandırıp sabahı

Alnımı yasladığım eski yüzlü bir keçe.

Garipsem Allah’ım var, bekle gönlümün şahı

Düşeceğim yollara davayı berat geçe! 

Eylül! Es de güleyim, yakamoz görsün mâhım

Ve yıkansın nurunla zindan kokan sabahım! 

 * 

Safir yağmurlarıyla, beklesin aziz sıla.

Gayrı muştudur bana göklerin gürlemesi...

Eylül 2004', 'Münzevi davaların hissedar mahkemesi Eylül! Beni en mecnun çarmıhında yargıla!   * Güz beldesi gönlüme yağmış yağalı efkâr Çektiğim elem değ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Öğdüm']::text[], 8.5, '{"poet":"Abdulkadir Öğdüm","poet_slug":"abdulkadir-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/eylul-ve-yagmur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-koksal-koseoglu-uygd6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kulaklarımdan sesin, rüyalarımdan resmin,

Dudaklarımdan ismin an gelip düşse keşke,

Yaşanan tüm anılar, yersiz olan kavgalar,

Ufacık mutluluklar aklımdan çıksa keşke...

Düşünceler bırakmaz bir an olsun yakamı

Sevgimi gömdüm ama ya o yaşananları,

Hatırladıkça senle bütün anılarımı,

Yalvarırım Tanrı''ya geriye dönsen keşke...

Çok kolay bir şekilde nasılda siliverdin,

Bilmem farkındamısın beni perişan ettin

Bugün anlamasanda hatanı göreceksin,

Gördüğün anda dönüp özür dilesen keşke....', 'Kulaklarımdan sesin, rüyalarımdan resmin, Dudaklarımdan ismin an gelip düşse keşke, Yaşanan tüm anılar, yersiz olan kavgalar, Ufacık mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Köksal Köseoğlu']::text[], 8.5, '{"poet":"Köksal Köseoğlu","poet_slug":"koksal-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keske-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretini Düşündükçe', 'hasretini-dusundukce-melih-coskun-grdmy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretini düşündükçe 

Cudi''ler küçülür gözümde

Kızılırmak bir içimlik su

Bir nefesimde yıkılır şu köhnemiş dünya 

Üzerime devrilir içi boşaltılmış zaman

Hasretini düşündükçe

Yollar kısalır gözümde

Dicle''yi kurutur yüreğimdeki alev

Binlerce kez tükürürüm ölümün kalleş yüzüne 

En gerçek türkümdür bu benim 

Haykırsam uzak kalır sesim 

Oysa yazıllmış en gerçek hikayedir

Sadece eksik kalmış yüreklerin duyamadığı

Sazım kırıktır 

Yahut kopartılmıştır bütün telleri 

Üç telden anlatmaya başlarım sana bütün bildiklerimi 

Susuz dere yataklarını 

Kurutulmuş yüreğini insanlığımızın

Ne kadar sevmişsek 

O kadar hor görüldüğümüzü

Hasretini düşündükçe 

Günler uzar gider 

Zaman hoyrat bir nehirdir 

Ömrümü akıntısına bıraktığım 

Bekle beni 

Yüce dağların ardında 

Akıp giden hayat gibi bekle 

Her adımım sana uzanır 

Her adımım hayata

BEKLE BENİ 

DENİZE ULAŞIR BİR GÜN BÜTÜN NEHİRLERİM...', 'Hasretini düşündükçe  Cudi''ler küçülür gözümde Kızılırmak bir içimlik su Bir nefesimde yıkılır şu köhnemiş dünya  Üzerime devrilir içi boşal...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hasretini-dusundukce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KuŞLaR ALeMi', 'kuslar-alemi-mine-ozdemirtas-w28cm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üzgünüm aşkım,

galiba 

tuvalimizde çevre kirliliği var

epey bir zamandır aç martılar

tepemde dolanmadalar.

bilemiyorum artık

kimbilir hangi çöpe göz koydular.

son zamanlarda işi

iyice azıttılar

haberin var mı? 

önce etimden et koparıyor

sonra yükselip çığlıklar atıyorlar.

hep söylerdin ya... hani

ben farklıydım

bir başkaydı lezzetim / şeker tadında.

bu yüzden/sanırım 

derin bir şeker komasındalar

çok kötü be canım

zavallılar

sürekli kusmaktalar.

biliyormusun? 

yakında / çok yakında

çöpleri ateşe vereceğim

yatak döşek yanacaklar.

yalnız minik bir sorunum var

kuşlar aleminde adımın başına

lanetlenmiş şerhini koyacaklar

ve bilmem kaçıncı bin yılda bile

benim 

ne kadar gaddar bir kadın olduğumu 

konuşacaklar.

Ama bu Kadarcık kusur

kadı kızında da olur

değil mi canım? 

madem ki

çöplüğüme dadandılar

kömür olmanın

dayanılmaz hafifliğine de

bir zahmet

katlanacaklar.

03/09/2004', 'üzgünüm aşkım, galiba  tuvalimizde çevre kirliliği var epey bir zamandır aç martılar tepemde dolanmadalar. bilemiyorum artık kimbilir hangi ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kuslar-alemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargısız infaz...', 'yargisiz-infaz-sezen-coban-0ooil', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek dipsiz bir kuyuya bakmak gibi birşey di

Ölümün sıcak nefesini içinde hissetmek

Hergün intiharı istemek gibi birşey di

seni sevmek acılıydı...

izi kapanmaz bir yaraydı...

Seni sevmek renklerden koyu griyi seçmek gibi birşey di

kanunsuz kitaplar gibi

her satırında arananların listesi

ve sen liste başı...

O yüzden sevgili,

seni sevmek

kör kurşunlara atlamak gibi birşey di...!', 'Seni sevmek dipsiz bir kuyuya bakmak gibi birşey di Ölümün sıcak nefesini içinde hissetmek Hergün intiharı istemek gibi birşey di seni sevme...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yargisiz-infaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git artık benden...', 'git-artik-benden-sezen-coban-qlkwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak ellerimi

Geçme artık sokağımdan

Tüm sokaklar sana çıkmasın

Saatler seni geçmesin artık

Uyuyamıyorum geceleri

Bir kederdir sorma gitsin

Eski fotoğrafında kalmadı yakmak için

Hangi denize döküleceğim,bilinmez..

Git artık benden,sorma beni

Farzet ki hiç ateşe vermedik İstanbul''u

Farzet ki birer nüshaydık seninle biz

Hiç aslı olmayan.

Farzet ki dinlemedik o şarkıyı

Git artık benden,git ne olursun

öleceğim yoksa bu hüzzam kederden..', 'Bırak ellerimi Geçme artık sokağımdan Tüm sokaklar sana çıkmasın Saatler seni geçmesin artık Uyuyamıyorum geceleri Bir kederdir sorma gitsin...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/git-artik-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Bir Şeyler Var İçimizde', 'hala-bir-seyler-var-i-cimizde-mehmet-hopal-5k5qa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül okşamasını da az buçuk

Her ne kadar dizleri tutmasada 

Hala bir şeyler var içimizde

Yüreklere yürümeye.

                    13.08.2004', 'Gönül okşamasını da az buçuk Her ne kadar dizleri tutmasada  Hala bir şeyler var içimizde Yüreklere yürümeye.                     13.08.2004...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hopal']::text[], 8.5, '{"poet":"Mehmet Hopal","poet_slug":"mehmet-hopal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hala-bir-seyler-var-icimizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-hasan-can-a2f64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne sen geceler boyu,

Yıldızları taşıdın yüreğime.

Sen sabahları kahırla uyanırdın,

Ben bilirim senin çaresizliğini,

Kimse bilmez senin yaşadıklarını,

Kimse anlamaz seni geceler boyu.

Kimse göremez sessizce dökülen göz yaşlarını,

Kimse bağrına basmaz yavrusunu senin gibi.

Bir çiçekmişsin şimdi anlıyorum seni,

Bir sonbahar sabahın da doğmuşsun.

Güneş vurmamış göz yaşlarına,

Ay doğmamış umutsuz gecelerine.

Yağmurlar söndürememiş yüreğinin ateşini,

Rüzgarlar alıp götürememiş bitmeyen acılarını.

Bu isyan bitmedi sen gittiğin de anne,

Herzaman devam etti ardından sessizce...', 'Anne sen geceler boyu, Yıldızları taşıdın yüreğime. Sen sabahları kahırla uyanırdın, Ben bilirim senin çaresizliğini, Kimse bilmez senin yaş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yaz günüydü', 'bir-yaz-gunuydu-nurten-kederoglu-iu3nk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yaz günüydü

Bir yaz günüydü sen gelip benim aklima düstün

Senin askinla canim ben bir divaneye dönmüstüm

Bir güldü yolladigin gül bahcesindeyim sanmistim

Seni cok seviyorum canim ne ümitle baglanmistim

Yakamozlarla karistim 

Dalgalarla hep yaristim

Sonunda yorgun düstüm

Yoklugunla dünyaya küstüm

Sönmüs atesimi sen yeniden yaktin

Seviyorum seni dedinde neden kactin

Kalbimde bilki cok derin bir yara actin

Mutluydum dünyamda ne tok ne actim

Yakamozlarla karistim 

Dalgalarla hep yaristim

Sonunda yorgun düstüm

Yoklugunla dünyaya küstüm

Ne istedin birtanem benden günahim neydi 

Gönlümün sultani olmak bilirmisin degeri neydi

Sev dedinde sevmedimmi hatirla kavlimiz neydi

Seviyorum deyip aldatinca eline gecen neydi.

Yakamozlarla karistim 

Dalgalarla hep yaristim

Sonunda yorgun düstüm

Yoklugunla dünyaya küstüm

siir_ce', 'Bir yaz günüydü Bir yaz günüydü sen gelip benim aklima düstün Senin askinla canim ben bir divaneye dönmüstüm Bir güldü yolladigin gül bahces...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-yaz-gunuydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bir Gece Geç Bir Vakitte...', 'bir-gece-gec-bir-vakitte-cigdem-bir-genc-i2g8u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin yarısı... 

Saatler ipini koparmış  it gibi koşturuyor  önümde....

Göz kapaklarımda  bir fil sürüsünün  ağırlığı

Uyu(mu)   yorum...

Uzak  kasabalar geçiyor gözümün önünden

Bir gün doğumu...

Bir ayrılık...

Ve sonra  sen....

şehrin   kalabalıkları şimdi uykuda

ne biliyim! 

düşsel anılar biriktiriyorlardır belki sabaha

ya sen 

söyle...

hangi durağındasın gecenin?', 'Gecenin yarısı...  Saatler ipini koparmış  it gibi koşturuyor  önümde.... Göz kapaklarımda  bir fil sürüsünün  ağırlığı Uyu(mu)   yorum... U...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-gece-gec-bir-vakitte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey çocuk dinle...', 'hey-cocuk-dinle-sezen-coban-miws9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hey çocuk! 

Dinle sana söyleyeceklerim var

Mutlusun değil mi? 

Şairin dizeleride senden yana bak

Okudun mu? 

Babamı görüyorum sende biliyor musun? 

O da senin gibi gözleriyle gülerdi.

Şair onu da çok severdi..

Sen tohumusun bir yıkılmışlığın

Acıların geçmişten sana  armağan

Öyle bir gelecek yaşamalısın ki-

Ardında gülen gözler bırakan...', 'Hey çocuk!  Dinle sana söyleyeceklerim var Mutlusun değil mi?  Şairin dizeleride senden yana bak Okudun mu?  Babamı görüyorum sende biliyor ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hey-cocuk-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renk', 'renk-aydogan-duran-4l2xw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün en renkli rüyamı gördüm

içinde en renksiz sendin

ben yine eğildim

yapraklarını okşadım

hüzünle doğmuş

mutsuzlukla dolmuş

başını yere eğdin

sen yine sendin

tüm renkleri

çektin

                    gittin...', 'Bugün en renkli rüyamı gördüm içinde en renksiz sendin ben yine eğildim yapraklarını okşadım hüzünle doğmuş mutsuzlukla dolmuş başını yere e...', ARRAY['Türk Edebiyatı','Şiir','Aydoğan Duran']::text[], 8.5, '{"poet":"Aydoğan Duran","poet_slug":"aydogan-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/renk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşim ben....', 'gunesim-ben-melek-ayaz-zncee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçük bir çocuğum.

İnsanı sever,

Sevgi dağıtırım.

Kırlarda çiçek,

Dağlarda güneşim ben.

Anlamam

Din, dil, ırk, mezhep,

İçim, dışım barıştır

İnsan, insandır derim.

Güneşle, baranım ben.

Düşmanlık, kin bilmem.

Sevgi yumağıdır,

Küçük sımsıcak yüreğim.

Kahkahalı gülüşüm,

Kurak çölleri yeşertir.

Yer yurt bilmez,

Gözlerimdeki baran.

Dünya benimdir,

Minik bir yüreğim ben.

Gülü sevip,

Papatyayı koparamam.

Geveze papağana gülüp,

Serçeyi ezemem.

Söğütün dalında serinlenirken,

Gölgesiz kavağı kesemem.

Karıncaya hayranlık,

Böceklere kin duyamam.

Dost köpeği doyururken,

Kedi nankör diye aç bırakamam.

Yazlar sıcak,

Kışlar soğuk, sızlanmam

Gündüz aydınlık,

Gece karanlık düşünmem.

Yaşayan, nefes alan doğayı severim.

İnsanı, insandan ayırmam.

Küçük bir çocuğum,

Sevgi ve barış isteyen,

Sımsıcak bir güneşim ben...', 'Küçük bir çocuğum. İnsanı sever, Sevgi dağıtırım. Kırlarda çiçek, Dağlarda güneşim ben. Anlamam Din, dil, ırk, mezhep, İçim, dışım barıştır ...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gunesim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On iki iki', 'on-iki-iki-hekim-coskun-a8q1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey sen elleri bana yakın gözleri benden uzak

hey öteki

hey beriki

bir güzel olur ki on iki iki

bir güzel olur ki yaşamla ölüm arası

ve ben Keşandayım

bir tanem

birden fazlam.

dün yarı özlem doluydu

bir sayfası yalnızlığımız

gelmek istedim bir an yanına, çaresiz.

noktalar, virgüller terk etmişlerdi.

hani yalnızlığımı paylaşacak olsa

ki imkansız

ve ellerimde erimese kar tanecikleri

bir an unuttursa o sıcacık ellerini

saklayabilsem sayfalar arasında

gönül......

Ve ben keşandayım

bir tanem

birden fazlam

gün ışıdı ışıyacak

saat sabahın beşi.', 'Hey sen elleri bana yakın gözleri benden uzak hey öteki hey beriki bir güzel olur ki on iki iki bir güzel olur ki yaşamla ölüm arası ve ben ...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/on-iki-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
