INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kucağımda baharları toplayıp geldim...', 'kucagimda-baharlari-toplayip-geldim-yusuf-ziya-leblebici-xuqhx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep sen mi getirecektin güzellikleri   

Ben getirdiklerini değil seni sevdim 

Haydi, durma yerinde aç o ellerini  

Kucağımda baharları toplayıp geldim 

Kapın açık, hissetmişsin geleceğimi  

Halbuki çıkarken açık bırakan bendim  

Biliyordum yolcu edemeyeceğini  

Gözlerinden bir damla yaş inmeden geldim    

Umutlarımızı tekrar getirdim sana    

Aslında senin umudun sadece bendim 

Sana şaka yaptığımı bilmedin ama   

Sen bunu anlayamadan dönüp de geldim  

Ayrılmak kelimesi bile zor değil mi    

Bilirsin biz hiç ayrılamayız ki derdim      

Ayrılıklar  ateşten de  bir kor değil mi      

Daha sen o ateşleri yakmadan geldim   

Şarkılar kulağıından geçiyordu  hani

Bu acıyı az da olsa  tattırabildim    

Ayrılık şarkısını yaşamıştın sanki         

Daha o şarkıların sonlanmadan geldim', 'Hep sen mi getirecektin güzellikleri    Ben getirdiklerini değil seni sevdim  Haydi, durma yerinde aç o ellerini   Kucağımda baharları topla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kucagimda-baharlari-toplayip-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerin Bensiz kalacak!', 'siirlerin-bensiz-kalacak-i-lhan-sanal-k3q2e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terketme beni,

Her akşam altıda

Gözlerim dolacak!

İçim şiirsiz kalıp

Kuruyacak! 

Terketme beni; 

Yavrularım üzgün,

Evim ıssız kalacak.

Sensiz olmayacak! 

Terketme beni; 

Çocuklarım öksüz kalacak; 

Onlara yetemiyorum

Büyürken onlar

(Şiirler de büyür)

Sensiz olmayacak! 

Terketme beni; 

Sen yoksan kalem yok elimde; 

Şiirlerim sensiz,

Şiirlerin bensiz kalacak! 

Terketme beni; 

Olmuyor, denedim. 

Başkasıyla

Olmuyor! 

Terketme beni; 

Sensiz

Şiirlerim olmayacak!', 'Terketme beni, Her akşam altıda Gözlerim dolacak! İçim şiirsiz kalıp Kuruyacak!  Terketme beni;  Yavrularım üzgün, Evim ıssız kalacak. Sensi...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şanal']::text[], 8.5, '{"poet":"İlhan Şanal","poet_slug":"i-lhan-sanal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/siirlerin-bensiz-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan Kaşif', 'perisan-kasif-hulya-koroglu-50m1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sığındığım limanlarda parçalandı gemilerim

Oysa! 

Ne umutlara yelken açmıştı; 

Kaşif yüreğim...', 'Sığındığım limanlarda parçalandı gemilerim Oysa!  Ne umutlara yelken açmıştı;  Kaşif yüreğim......', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/perisan-kasif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmgelem', 'i-mgelem-i-lhan-sanal-jhfgx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Masmavi bir

Bardakta

Buz kalıpları.

İçinde 

Yavaşca çoğalan

Buz gibi su.

Zaman hızlı,

Su zamandan da hızlı; 

Ben havada iken,

Düşerken,

Düşerken buzların,

Buz suyun içine; 

Düşerken,

Yüreğim gökyüzünde

Asılı!', 'Masmavi bir Bardakta Buz kalıpları. İçinde  Yavaşca çoğalan Buz gibi su. Zaman hızlı, Su zamandan da hızlı;  Ben havada iken, Düşerken, Düşe...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şanal']::text[], 8.5, '{"poet":"İlhan Şanal","poet_slug":"i-lhan-sanal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/imgelem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Sensin', 'hangisi-sensin-hulya-koroglu-qi63c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tarafın yaz güneşi,

Bir tarafın buz dağı.

Kanat çırpmaktan yorulmuşum.

Söyle! 

Güneş misin? 

Ayaz mı?', 'Bir tarafın yaz güneşi, Bir tarafın buz dağı. Kanat çırpmaktan yorulmuşum. Söyle!  Güneş misin?  Ayaz mı?...', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hangisi-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilselerdi?', 'bir-bilselerdi-i-lhan-sanal-enfmu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiirlerle karşıladılar

Birbirlerini.

En güzel

Şiirlerle

Yürekten.

Şiire şiir,

Sevgiye sevgi.

Şiirlerle kutsadılar

Birbirlerini, sevgilerini.

Ruhlarının en minik

hücrelerine kaçtılar; 

Yine de tanıdılar

Birbirlerini; 

Birbirine kör iken gözleri.

Günün birinde

İzmir''de, Pasaport''ta

Yürüdüler dakikalarca yan yana

Dakikalarca oturdular bir bankta

Batan güneşe karşı,

Belki de lafladılar

Ayaküstü; 

Ama tanımadılar şiirlerini,

Bilemediler sevgilerini.', 'Şiirlerle karşıladılar Birbirlerini. En güzel Şiirlerle Yürekten. Şiire şiir, Sevgiye sevgi. Şiirlerle kutsadılar Birbirlerini, sevgilerini....', ARRAY['Türk Edebiyatı','Şiir','İlhan Şanal']::text[], 8.5, '{"poet":"İlhan Şanal","poet_slug":"i-lhan-sanal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-bilselerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal mı Bıraktın', 'hal-mi-biraktin-huseyin-sigirtmac-ff0mm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya efkarını sardın başıma.

Neşeye erecek hal mı bıraktın. 

Bir hasret pençesi vurdun döşüme.

İçinden geçecek  yol mu bıraktın. 

Gam kederim bitmez yüzüm gülerken.

Dostları yitirdim sevgi ararken.

Gerçeği unuttum hayal kurarken.

Kuruttun yaprağım gül mü bıraktın. 

Gözüm yolda kaldı gelmez gidenim.

Umut gördüklerim yıktı güvenim.

Düşman gibi taşa çaldı sevenim.

Kırdın fidanımı dal mı bıraktın. 

Anladım fayda yok, dost değil kimse.

Sevgi dünyasında görmedim hisse.

Sığırtmaç kalbine düştü vesvese.

Bağrına saracak kol mu bıraktın.', 'Dünya efkarını sardın başıma. Neşeye erecek hal mı bıraktın.  Bir hasret pençesi vurdun döşüme. İçinden geçecek  yol mu bıraktın.  Gam keder...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hal-mi-biraktin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Annem', 'aglama-annem-onder-beker-rgh41', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlama anam benim için, bizim için.

Herkes gibi bizde payımıza düşeni aldık.

Herkes gibi bende aldım acılardan,

Yoksulluklardan, ihanetlerden ve ne varsa daha başka.

Hepimizin hikayesi ayrı ayrı anne.

Ağlama artık hikayeleri ayrı ayrı olanlara.

Herkes gibi bizde yandık,

Saf sevdalardan geçerken.

Ağlama anne benim için.

Herkes gibi bende sevdalandım, gururlandım.

Herkes gibi onurumla yaşamaya çalıştım.

Ve herkes gibi yaşadım onurumla anne.

Ağlama artık güzel anam ağlama.

Gözlerin dalıp gitmesin gayrı uzaklara.

Bak geldim mapusluğun kuyularından.

Bak yine karnım aç dedim.

Ağlama artık anam gülsün artık güzel gözlerin.

İlk yenilen biz değildik ki hem.

Bak herkes yenilgilerden çıkmış.

Ağlama artık anam gözlerinin yaşı sende kalsın.

Ağlama artık anam

Bak yeni bir gün doğacak az sonra.

Ve biz kaldığımız yerden,

Vuracağız yüreğimizi yeni sevdalara...

(31 Ağustos 2004 / İzmit)', 'Ağlama anam benim için, bizim için. Herkes gibi bizde payımıza düşeni aldık. Herkes gibi bende aldım acılardan, Yoksulluklardan, ihanetlerde...', ARRAY['Türk Edebiyatı','Şiir','Önder Beker']::text[], 8.5, '{"poet":"Önder Beker","poet_slug":"onder-beker","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aglama-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüksek Ökçe', 'yuksek-okce-cigdem-bir-genc-sxryg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir kadın...

               suskun...

                             ve

                                  inadına geveze... 

                                                             yüksek ökçeli pabuçları

                                                                                                   bu gece...', 'bir kadın...                suskun...                              ve                                   inadına geveze...                   ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuksek-okce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Tanesi', 'uzum-tanesi-i-lhan-sanal-6hfr1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan

Üzüm tanesi

Değil.

Ölünce

Bir çok insan daha

gider

Bir yerlere.

Sevdiğini kaybedince

Kaybeder insan

Bir salkım insanı

Onunla birlikte.

İnsan değil ki

Bir tane!', 'İnsan Üzüm tanesi Değil. Ölünce Bir çok insan daha gider Bir yerlere. Sevdiğini kaybedince Kaybeder insan Bir salkım insanı Onunla birlikte....', ARRAY['Türk Edebiyatı','Şiir','İlhan Şanal']::text[], 8.5, '{"poet":"İlhan Şanal","poet_slug":"i-lhan-sanal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzum-tanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-kemal-sume-6jfxb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler karadır,

Hüznün sıcak...

Yalnızlığın sen halidir,

Can çekişen özlemim.

Zaman sorumsuzdur,

En sorunlu olduğun zamanlarda.

Uyumaya direnen göz kapaklarıma

Ve...

Bozuk çeken bir radyo istasyonuna inat

Şarkımızı dinlemeye mahkumluktan başka bir  şey değildir,

''sevmek''...

04/09/2002', 'Geceler karadır, Hüznün sıcak... Yalnızlığın sen halidir, Can çekişen özlemim. Zaman sorumsuzdur, En sorunlu olduğun zamanlarda. Uyumaya dir...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmek-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen / Ben', 'sen-ben-kemal-sume-eqorl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bir damla, bir aşığın yanağını ıslatan,

Bense tüm susamışlığıyla yanağından öpen tertemiz mendil...

Sen bir baharda gün görmeye bel bağlamış toy tomurcuk,

Bense gölgesinde tomurcuk besleyen ağacın kırık dalı...

Ve

Sen dalına tutunamayan mecalsiz yaprak,

Bense sana kucak açmış zavallı toprak...

''Saracağım ve sararacağın âna tutsak...''

04/09/2002', 'Sen bir damla, bir aşığın yanağını ıslatan, Bense tüm susamışlığıyla yanağından öpen tertemiz mendil... Sen bir baharda gün görmeye bel bağl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-ben-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben (İki)', 'ben-i-ki-i-brahim-ethem-bingul-xg765', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıların, dertlerin

Odak noktasındayım

En güzel dileklerin

Düğün sofrasındayım...

Adım, yârin dilinde

Hem uzak, hem yakınım

Bir yanım aşk ilinde

Dünya gezer bir yanım...

Dalar gözlerim,derin

Zamanı aşar gider

Gözümden incilerim

Yerlere taşar gider...

Düz yolda yorulurum,

Yokuşlarda koşarım.

Aşkta yanlıştır yorum

Aşkı aşkla yaşarım...

Ben, kalbimin gözüyle

Kalbini seyrederim

Kalp dilinin sözüyle

Senden seni isterim...

Olsa da sevdam noksan,

Olsa da aşkım yarım

Cânan için feda can

Ben onun için varım...

Yemyeşil kırlar benim

Kırda, kırık bir dal ben

Şu akarsular benim

Hayret içinde lâl ben...

Ben,

Acıların,dertlerin

Odak noktasındayım...

www.iebingul.com', 'Acıların, dertlerin Odak noktasındayım En güzel dileklerin Düğün sofrasındayım... Adım, yârin dilinde Hem uzak, hem yakınım Bir yanım aşk il...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İhtiyar Adamdır Sevdam', 'bir-i-htiyar-adamdir-sevdam-kemal-sume-ee4lj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ihtiyar adamdır sevdam...

Titreyerek yürür,

Ve

Hep korkar gölgesinden ayrılıkların...

Bir yalnızlık adına yazılmıştır kaderi...

2003', 'Bir ihtiyar adamdır sevdam... Titreyerek yürür, Ve Hep korkar gölgesinden ayrılıkların... Bir yalnızlık adına yazılmıştır kaderi... 2003...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-ihtiyar-adamdir-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-kemal-sume-jtszl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak, 

Yaşlanmaktır birazda...

Önce ömür; 

Sonra gözler dolar yaşlarla...

Yakın olur bazı zamanlar,

Ve davetsiz bir misafir gibidir,

                                                     ''Ölüm; ''

Bir alfabenin en son harfidir...

Yalanlar kendinden önceki 28 harfi...

Eylül-2003', 'Yaşamak,  Yaşlanmaktır birazda... Önce ömür;  Sonra gözler dolar yaşlarla... Yakın olur bazı zamanlar, Ve davetsiz bir misafir gibidir,     ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni De Hoş Gör Anne', 'beni-de-hos-gor-anne-necmiye-sarpkaya-bf3b9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sofranı aç 

Kalbini aç 

Lokmanı paylaş 

Doğru sözlü ol kızım

İnsanlar üzerinde Allah’ın (c.c.)

Nimetleri var sayılamayacak

Nimetlerin şuurunda olma nimetidir 

En büyüğü demiştin anne

Sesimin önünde uğulduyor sükutun çığlıkları 

Zalimi horlamak  zulmü kırmak istiyor

Yeter  demek istiyorum komploculara

Diyemiyorum anne 

Düşünüyorum Yüce Yaratıcının bildiğini 

Bunları böyle mi belletmiştin anne

Hoş gör herkesi

Dinle sev say  dedin

Ayıp dedin günah dedin

Duygularım isteklerim  önemsiz miydi anne

İçimi yakan kanatanlar karşısında 

Başkalarına saygı adına 

Sineme saplanan onca yalan

Karşısında dönüp nefsime 

Derman kabul ettin derdi 

Şikayet neyin nesi

Isıracak  dişi olan

Parçalayacak pençesi olan

Çığlıklarımı içime gömüyorum 

Hoş gör herkesi

Dinle sev say  dedin

Ayıp dedin günah dedin

Duygularım isteklerim  önemsiz miydi anne

Sesimin önünde uğulduyor sükutun çığlıkları 

Sana asaletimize layık  olduğumu düşünüyorum 

Beni de hoş gör anne hoş gör beni de 

Necmiye Sarpkaya', 'Sofranı aç  Kalbini aç  Lokmanı paylaş  Doğru sözlü ol kızım İnsanlar üzerinde Allah’ın (c.c.) Nimetleri var sayılamayacak Nimetlerin şuurun...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/beni-de-hos-gor-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlüyorum', 'dusluyorum-kemal-sume-n604d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda yüzlü insanlar düşlüyorum,

Her gülüşlerinde yeşerten baharı...

Ay yüzlü çocuklar diliyorum,

Versinler ellerinden çiçekleri...

***

Bir dağ düşlüyorum,

Her yanı bir yol...

Bir deniz düşlüyorum

Yakamozuyla içimizi parlatan...

***

Bir kadın düşlüyorum,

Kilitleri kırıp gelen...

Ve...

Bir acı düşlüyorum,

En mutlu günümüzde yitirilen.

Düşlerimde yoruluyorum seni sevmekten,

Ve bir seni düşlüyorum; 

Düşündükçe düşlerimden düşen...

Bir seni...

28/11/2001', 'Sevda yüzlü insanlar düşlüyorum, Her gülüşlerinde yeşerten baharı... Ay yüzlü çocuklar diliyorum, Versinler ellerinden çiçekleri... *** Bir ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusluyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Böyle Yazmamıştım Adını', 'hic-boyle-yazmamistim-adini-kemal-sume-tp0y9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç böyle yazmamıştım adını,

Kimsenin bu şekil gökyüzüne...

Sensizliğin karimatik yalnızlığıydı

Belki fikrimin yetisi...

İnadına sensizliğin tadını çıkartıyordu

                                                    Zaman...

Çalıyordu ömrümden belki

Farkına varmadan...

Ve...

Hasretin hasret türküleri söylüyordu

Kendi derdinden

Kime? 

Kendi de bilmiyordu garibim...

Simdi ben,

Ne sensiz o günlerin heveslisi,

Ne de yalnızlığa dostum....

Satıyorum firari yanlarımı,

''Etmese de beş kuruş.''', 'Hiç böyle yazmamıştım adını, Kimsenin bu şekil gökyüzüne... Sensizliğin karimatik yalnızlığıydı Belki fikrimin yetisi... İnadına sensizliğin...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hic-boyle-yazmamistim-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issızca', 'issizca-volkan-yoruc-cymc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutsuzluğun yamacında eser sert rüzgarlar 

Ve denizlerinde vurur sahile yorgun dalgalar 

Ben giderken bu yolun akşamında 

Issızca gelirim yanına 

Ne dağlar aşılır ne yollar aşınır 

Bir ben giderim bu yola 

Bir ben gelirim yanına 

İster dalga ol boğ beni 

İster rüzgar ol savur beni 

Yine vazgeçmem düşlerimden 

Issızca sokulurum yanına 

Sen ki tatlı bir bahar mevsimi 

Bir küçük gül tanesi 

Ben ki solgun bir güz mevsimi 

Avuçlarında sarı bir yaprak tanesi 

Tut ellerimden 

Ve bırakma asla 

İşte o zaman yeşerir 

Tomurcuklanırım avuçlarında 

Bırakma beni,unutma asla 

Zeynep diye açarken çiçeklerim 

Bilmeni tek istediğim 

Sanadır bu mutluluğa dair hislerim 

Zeynep 

Bir tatlı düş 

Bir narin çiçeksin bağrımda 

Yanına gelmek zor olsada bu uğurda 

Düşlerimle gelir 

Ve ıssızca rüzgar misali eserim saçlarına', 'Mutsuzluğun yamacında eser sert rüzgarlar  Ve denizlerinde vurur sahile yorgun dalgalar  Ben giderken bu yolun akşamında  Issızca gelirim ya...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/issizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meydandaki Postane Üçüncü Kapı', 'meydandaki-postane-ucuncu-kapi-kemal-sume-7lvyx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz...

Sessiz...

Issız...

Işıksız...

Yasaksız...

Vasıfsız...

Dahası aşkınsız bir gece,

Ve son demleri...

Sanki, akşamdan kalma bir kalp bendeki...

Meydandaki postane,

Üçüncü kapı...

Ve

Söylenen o son şarkı:

“aklımda yalnız sen varsın! ”

Gözyaşımda,

İçtiğim her yudumda,

Hatta ahım da,

Sarıldığım yılanda hatta...

Yıllarda...

Yollarda...

Yoklarda...

Yalnız ''sen'' varsın...

1999', 'Sensiz... Sessiz... Issız... Işıksız... Yasaksız... Vasıfsız... Dahası aşkınsız bir gece, Ve son demleri... Sanki, akşamdan kalma bir kalp b...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/meydandaki-postane-ucuncu-kapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yalnızlık Akşamıdır', 'bir-yalnizlik-aksamidir-kemal-sume-oeua6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlık akşamıdır,

Yorgundur saatler.. 

Yalnızlığın üçüncü çeyreğinde kalan bir şarkıya hasret,

Bekleşirken kulaklarım,

Sesin olsa gerek, hasret duyulan

Kuytu bir hayatın girizgahında...

1997', 'Bir yalnızlık akşamıdır, Yorgundur saatler..  Yalnızlığın üçüncü çeyreğinde kalan bir şarkıya hasret, Bekleşirken kulaklarım, Sesin olsa ger...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-yalnizlik-aksamidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler Yalan Söylemez!', 'gozler-yalan-soylemez-kemal-sume-vg12k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unut...

Unut ki hala bakir kalsın hislerim,

Unut ki...

Son bir kırıntısı kalsın içimde...

Uzun etme; çek git! 

Senden kalacak bir yastık, bir yorgan, bir tel saç,

Nasılsa kuruyacak menekşeler,

Öyle susuz, öyle aç...

Sabahları olmayacak,

Küllükleri dolduran hüzzam gecelerin...

Tabaklar kırılacak,

Bardak seni arayacak...

Kahvem yine taşacak örneğin...

Ardına bakma sakın, görmek istemiyorum,

Gözler yalan söylemez gülüm...

Gözler yalan söylemez...

***

Kaldırımlar seni soracak,

Sen gidince...

Bastığımız çimler şükredecek.

Duvarlardan uçacak her geçen gün kokun...

Ve yine,

Evimin anahtarını taşıyacağım cebimde...

Dertlerimi dikene,

Hayallerimi suya anlatacağım,

Alışana kadar yokluğuna...

Sensizlik iliklerime işleyecek,

Şiirlerim mana bulacak belki de...

Belki de yanacaklar bir kovanın dibinde...

***

Bir kitap alacağım,

Yalan sevgiler tüccarından,

Ve bakmayacağım gözlerine,

Dedim ya...

Gözler yalan söylemez gülüm,

Gözler yalan söylemez...

***

Gidişinde bir kuş uçuracağım göklere,

Bir dilenciye vereceğim son paramı,

Eve ekmeksiz döneceğim,

Neye yarar yemek,

Sensiz haram olacak o lokmayı...

Hadi uzun etme...

Git...

Düşünmek istemiyorum artık,

Ne olacaksa varsın olsun,

Düşündüğüm zamana yazık...

Hadi git ki görmeyeyim...

Görmeyeyim gözlerini.

Çünkü, daha iyi biliyorum artık,

Gözler yalan söylemez gülüm...

Gözler yalan söylemez...

''Söyleyemez...''

2001-11-03', 'Unut... Unut ki hala bakir kalsın hislerim, Unut ki... Son bir kırıntısı kalsın içimde... Uzun etme; çek git!  Senden kalacak bir yastık, bi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gozler-yalan-soylemez-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hor Görme Babo!', 'hor-gorme-babo-kemal-sume-c3qrk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tozlu  yollarında yürüdüm hayatın,

Dikenli...

İnce uzun,

Bir o kadar çileli...

Aklım çalışmazdı yalana,

Dilim dönmezdi...

Hor görme! 

''Yirmi iki doğumluyum; eski hesaptan...''

***

Ağlarsam sessiz ağlar,

Karalar bağlarsam, dünyayı inletirim.

Kederim,

Bir ananın şefkati kadar... Sadece...

Hor görme babo! 

''Yirmi iki doğumluyum, eski hesaptan...''

***

Ellerimi öpün,

Nasırlı çatlak ellerimi...

Öpün, tiksinmeyin...

Nicesine ekmek verdi bu eller,

Orak tuttu,ekin biçti,sap attı...

Ağustosta mendil oldu ter sildi...

Öpün baboş tiksinmeyin,

''Yirmi iki doğumluyum, eski hesaptan...''

***

Gözlerimin içine bakın,

Puslu donuk gözlerime...

Nice güzel gördü sorun,

Ve dokunun kalbime,

Dokunun ellerinizle....

Hey be! 

Kimler geldi kimler getti...

Nafile...

***

Sakın ha! 

Kırmayasınız onu,

Ve kızmayın şükürsüzlüğüme.

Hor görme be gardaş,

Dedim ya; 

''Yirmi iki doğumluyum, eski hesaptan...'' 

2001', 'Tozlu  yollarında yürüdüm hayatın, Dikenli... İnce uzun, Bir o kadar çileli... Aklım çalışmazdı yalana, Dilim dönmezdi... Hor görme!  ''Yirmi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hor-gorme-babo-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat; Sen Gidince...', 'hayat-sen-gidince-kemal-sume-fivmi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat,

Aynada hayal,

Gerçekte hayat...

Gülümseyişiymiş pembe günlerin,

Fotoğraflarda donan simalar...

Şimdi ne bir resim,

Ne de şarkılar...

Sadece bir arzunun sebebi gerek,

Yalnızlığımda...

Bir tek özün,

Bir tek sözün gerek,

Sızısının dinmesiyle depreşen yaralarıma...

Yarası bedenimde,

İçimde yarısı,

Tende gururlu,

İçimde pişman akarken kanım,

Korkuyorum! 

Ne zaman kapanacak bu yara? 

Ve ne zaman sızısı dinecek! 

O zaman sen öleceksin,

O zaman içimde...

***

Sen gidince öğrendim,

Pişmanlık duymayı,

Yanmayı...

Ve...

Sen gidince öğrendim,

Kırık kaldırımlarda dolaşmayı...

Düşündüm,

Düşündüm...

Üşüdüm soğuk kışlarda,

Yoruldum,

Yoruldum, alaycı bakışlardan,

Kendime acımayı,

Sen gidince öğrendim...

Severdim, senden ayrılmadan önce,

Gülüm demeyi,

Gülümsemeyi...

Şimdi demiyorum gülüm - semiyorum...

Bana ağlayanları,

Sen gidince öğrendim...

2001', 'Hayat, Aynada hayal, Gerçekte hayat... Gülümseyişiymiş pembe günlerin, Fotoğraflarda donan simalar... Şimdi ne bir resim, Ne de şarkılar... ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hayat-sen-gidince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Yoldaşım', 'can-yoldasim-sair-taranta-7vf2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'giderken söylediğin son türkü dudaklarımda

gidiyorum şehirden

yılların yorgunluğu alnımda

ağırlığı göz kapaklarımda

gidiyorum şehirden

yansımalar kaldı yalnızca bizden

düş kırığı kör yalnızlığı aynalarda

birlikteydik

uzaktaydık

yan yanaydık…

olmayası yaşanan zamanlarda

gün ağarırken gözlerimde

yollar aşsam sana ulaşsam

yanımda günlük aşım

yanımda arkadaşım

uzaktasın can yoldaşım

 derman kalmadı dizlerimde

bir soluk ver 

el uzat

hep seninleyim

hep sen varsın

en güzel hayal ve düşlerimde

sızlanmadım

ağlamadım

karaları bağlamadım

biliyordum vardı sonu

ve ben o sona 

sensiz vardım', 'giderken söylediğin son türkü dudaklarımda gidiyorum şehirden yılların yorgunluğu alnımda ağırlığı göz kapaklarımda gidiyorum şehirden yansı...', ARRAY['Türk Edebiyatı','Şiir','Şair Taranta']::text[], 8.5, '{"poet":"Şair Taranta","poet_slug":"sair-taranta","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/can-yoldasim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Yüreğim...', 'rubai-yuregim-emirhan-bala-xfux1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir yürek ki, 

iki kapakçık birkaç damar, 

ikiye bölünmüş halde, 

iki göz ayrı ayrı ağlar...', 'bir yürek ki,  iki kapakçık birkaç damar,  ikiye bölünmüş halde,  iki göz ayrı ayrı ağlar......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-yuregim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar Çiçektir', 'umutlar-cicektir-kemal-sume-6judb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi anlıyorum; ne demekmiş,

Sevip de sevilmemek...

Değer vermemeyi öğrendim seninle,

Hak etmeyene, hakkından fazla...

***

Zararıydı aklıma seni beklerken köşe başında

Beslediğim umudum...

Ve 

Sen çıkagelirdin aklıma her zarar verdiğimde...

***

Bugün yine,

Hadi bugün yine gel! 

İsterse yitsin şuurum...

Hadi ne olur yine gel,

Ayaklar altında gururum...

Aşkta gurur olmaz derler,

Ama aşkta...

Ne bizimkisi? 

Aşk mı, aldanış mı? 

Değer vermemeyi öğrendim seninle,

Hak etmeyene hakkından fazla...

***

Bazen bir telefon sesi,

Bazen sıcak gülüşün,

Bazen çatık kaşların,

Hatta somurtuşun...

Ne de tutarsız kalbin,

Benim için mi atıyor,

Yoksa başkasına mı? 

Ne de solgun gözlerin,

Sanki bana bakmıyor...

***

Bilir misin ne demektir,

Umut verip sonra almak? 

''Ödünç vermişçesine...''

Umutlar çiçektir,

Koparmaya gelmez onları.

Oysa, pembe açmıştı umutlarım,

Tutku, aşk, bağlılıktı adları...

Neyse...

Artık yoklar...

Vermemeyi öğrendim seninle,

Hak etmeyene, hakkından fazla değer...

Yine seninle öğreniyorum,

Aşk dediğin umut,

Çiçeklerini koparıncaya kadarmış meğer...

2000', 'Şimdi anlıyorum; ne demekmiş, Sevip de sevilmemek... Değer vermemeyi öğrendim seninle, Hak etmeyene, hakkından fazla... *** Zararıydı aklıma...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/umutlar-cicektir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmen Gerekmez', 'gormen-gerekmez-bilgun-gungor-jgeju', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sade bak

Görmen gerekmez

Ben baktığın yerde olacağım.

Sade duy

İşitmen gerekmez

Ben ‘duyduğun an’ olacağım.

Sade gül

Kahkahan gerekmez.

Ben güldüğünle var olacağım.

Sevgimle

Sade hisset beni

O an yanı başında olacağım.

                                                              26.04.2003', 'Sade bak Görmen gerekmez Ben baktığın yerde olacağım. Sade duy İşitmen gerekmez Ben ‘duyduğun an’ olacağım. Sade gül Kahkahan gerekmez. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gormen-gerekmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Saplantısı', 'hayal-saplantisi-bilgun-gungor-gmu8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendini her zaman 

Saraylarda görürdü.

Her zaman kendini

Zengin görürdü rüyalarında

Hayallerinde bir düş kapısı açılırdı.

Bu kapıdan girince

Bütün gerçekler 

Suratına haykırırdı.

Acı bir haykırışla 

Yataktan doğrulurdu. 

                                        02.07.1994', 'Kendini her zaman  Saraylarda görürdü. Her zaman kendini Zengin görürdü rüyalarında Hayallerinde bir düş kapısı açılırdı. Bu kapıdan girince...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayal-saplantisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel', 'hadi-gel-bilgun-gungor-wx90q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerden uzak 

Sevdanı bıraktın bana

Giderken tebessüm vardı

Giderken acı, dudağında

Sesten hızlı 

Seslenişler bıraktın bana

Dilim seni 

Tekrar söyledi.

Gülüşünden

Gamzeler bıraktın bana

Yanaklarımda izi kaldı

Gözlerimde gözlerinin ışığı var.

Aydınlanmak istersin sen! 

Hadi gel artık yanıma! 

