INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık', 'kirik-bilgun-gungor-kz2n4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyılardayım.

Düşmekteyim.

Tutacak kimsem yok.

Köşelerdeyim.

Sıkışmışım.

Kurtaracak kimsem yok.

Kenarlardayım.

Merkezim yanlış

Beni çok yapacak kimsem yok.

Kesilmiş gibiyim.

Kıyıdan, köşeden, kenardan

Tam değilim.

Bende kalan kırık sadece. 

                                                      20.04.2003', 'Kıyılardayım. Düşmekteyim. Tutacak kimsem yok. Köşelerdeyim. Sıkışmışım. Kurtaracak kimsem yok. Kenarlardayım. Merkezim yanlış Beni çok yapa...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkışık', 'sikisik-bilgun-gungor-pspfh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıkışmış duygular

Patlamaya yer arıyor

Tüm yürekleri dolaştı zannedersiniz

Lakin bir yürek var 

Ipıssız, eldeğmemiş

Kapısı sürgülü

Bir itimde açılır be! 

Nerde o yanardağ ağzı? 

Lavlar boşa püskürmesin! 

Burada 

Patlayacak bir yürek daha var! 

                                                        25.11.2002', 'Sıkışmış duygular Patlamaya yer arıyor Tüm yürekleri dolaştı zannedersiniz Lakin bir yürek var  Ipıssız, eldeğmemiş Kapısı sürgülü Bir itimd...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sikisik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-bilgun-gungor-on3x0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgar havalansın parmak uçlarından

Ve senle beraber dolaşsın uzun uzun

En baştan, en sona...

Hayata anlam verin önce

Çiçeğe neden çiçek 

Buluta neden bulut olduğunu sorun.

Tüm perdelerini kapatın dünyanızın

Sadece sen ve rüzgar olun yapayalnız

Karanlığın sesi duyulmasın 

Işığın rengi dokunmasın 

Periler göz kırpmasın birlikteliğinize

Hayata şekil verin sonra

Dokunun birbirinize

Rüzgar sana, sen rüzgara

Senin hissettiğin bir ılık esintidir

Tüm sevgini içine sığdırabildiğin

Dokunur ona bu sıcak

Ama iz kalır bıraktıklarından 

Başka yaşamlara

Başka sevgiler taşımak için

Hayata ses verin

Renk verin çok sonra

Sen şarkılar söyle

Gökkuşağı giyin üstüne

Rüzgar uğuldasın, ritm yapsın.

Tüm anlamları bulunca 

Tüm şekilleri yapınca

Sesler ve renkler birbirine karışınca 

Kapımı iki kez tıklatın

Birincisinde çıkamayabilirim

İkincisinde çıkarsam şayet

Size körebe öğretirim. 

                                                             21.11.2002', 'Rüzgar havalansın parmak uçlarından Ve senle beraber dolaşsın uzun uzun En baştan, en sona... Hayata anlam verin önce Çiçeğe neden çiçek  Bu...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/korebe-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar yağmıştı o gün hatırlar mısın?', 'kar-yagmisti-o-gun-hatirlar-misin-nurettin-sakin-j0015', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar yağmıştı o gün hatırlar mısın? 

Yağdıkça kar seni, o günü hatırlarım.

Üşür gibi olurum, uçmak isterim güneşlere

O an olmamış olmak orada gidişinde senin

Ya da fark edememek yağışını karın,

Anımsayamamak seni 

Bilemezsin sen…

Yağarken kar, bir de rüzgar esmişti o gün.

Kararsız kapıldıkça rüzgara bir şey

Çalkalanır ruhum.

Lodosta mürettebatsız bir gemi rotasında

Kanı karışır kalbimin.

Unutmuş olmak isterim adını, yüzünü.

Unutmak seni

Bilemezsin sen…

Sana bir gül vermiştim en son, eserken rüzgar

Rastlaştıkça bir çiçekçiyle, baştan yeşerirsin

Seni gömdüğüm yerden.

Kapar gözünü kalbim, damarlarıma kan gitmez.

Sen bitersin, kurutur beynim seni

Doğmamış olmanı isterim

Ya da doğmamış olmak

Ebedi gömmek seni

Bilemezsin sen…

Kar yağmıştı o gün hatırlar mısın? 

Bir de rüzgar esmişti o gün, 

Sana bir gül vermiştim en son.

Nereden bileceksin…

Bilemezsin sen…

30.01.2000', 'Kar yağmıştı o gün hatırlar mısın?  Yağdıkça kar seni, o günü hatırlarım. Üşür gibi olurum, uçmak isterim güneşlere O an olmamış olmak orada...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Sakin']::text[], 8.5, '{"poet":"Nurettin Sakin","poet_slug":"nurettin-sakin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kar-yagmisti-o-gun-hatirlar-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmasını bekledim günün', 'dogmasini-bekledim-gunun-nurettin-sakin-4s20i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğmasını bekledim günün

Kıpırdanışında bir yıldızın

Görmeyi bekledim.

Hüzünleniyor gibiyken gözlerim

Güzelliğini sevdim sevmenin

Sevileni bekledim.

Yanağımda kayarken yaşım

Kesilirken umudum

Umduğumu bekledim.

Aralarken ruhum hayalimi

Tadı kaçtı ömrümün

Sonunu bekledim.

25.09.1999', 'Doğmasını bekledim günün Kıpırdanışında bir yıldızın Görmeyi bekledim. Hüzünleniyor gibiyken gözlerim Güzelliğini sevdim sevmenin Sevileni b...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Sakin']::text[], 8.5, '{"poet":"Nurettin Sakin","poet_slug":"nurettin-sakin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dogmasini-bekledim-gunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
