INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Ki Doğdun Sedef''im...', 'i-yi-ki-dogdun-sedef-im-tulay-sustam-j6qbj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benim kalemimsin

................................. kimseyle paylaşamadığım

Sen en güzel çiçeksin

.................................. koklamaya kıyamadığım

Sen iyi ki doğdun, iyi ki varsın

..................................... sen benim başımın tacısın 

