INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi kovada iki balık', 'mavi-kovada-iki-balik-mustafa-sen-xp6jd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Dalgaların Senfonisi”

    nereye ait olduğunu bilemediğimiz

      mavi

         bir ezgi

            çalınıyordu kulaklarıma 

                        sallanıyordum....



bir kadın,

      yanımda

        derin bakıyordu gözleri.........



Ya nereye ait olduğunu bilmiyor,

       Ya da başka ufuklar arıyordu.....

           Bilemezdi en batının uğurlu olduğunu....

Üşümüşmüydü neydi...

       1700 feribotunda

            sıcacık baktım gözlerine...



Ürkekti,

    güzeldi memeleri

Ama hep güldük...

      Önce o anlattı 

          Sonra da ben...



Huysuz Rum kadınları konuşurken,

    Fallara karıştık tepelerde...

Ve kadın gibi kokuyordu,

     güzeldi...



Bırakıp

    dudaklarımda 

            nemli bir tebessüm 

                  döndü dalgaların senfonisine

Dünyam yemyeşildi

  Özlediğim....

      MAVİ.....

                                                               Mustafa Şen

                                                                 GÖKÇEDADA', '“Dalgaların Senfonisi”     nereye ait olduğunu bilemediğimiz       mavi          bir ezgi             çalınıyordu kulaklarıma               ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mavi-kovada-iki-balik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Dair Nefsimle Münazara', 'yare-dair-nefsimle-munazara-ahmet-ferit-cosan-2hq67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'devran devran olalı beri acep böyle devir hiç yeryüzüne geldi mi? 

öyle bir dönmekte ki çarklar, her bir insan, ayağına gelen

hayırlı şeylere dahi şüpheyle yaklaşmakta,

öyle bir sindirilmiş, üzülmüş ki kişi,

başına gelen iyi şeylere dahi güvenemez halde, güzele sevinemeden, öylece durumuna uzaktan bakmakta...

aşka bile...

sevmek seni, yani çaresizce, derhal, sualsiz teslim olmam gönlünün muhabbetine,

aşkımı değersiz kılmaz ki.

sorgulayan gözlerinle bakman aşkıma, bil ki bu yaşlı gezegende varolmuş vedahi olacak herşeyden çok üzer bu miskini...

titresin isterim gönlünün en hassas telleri, dimağına aksim düştüğünde...

bil ki ben en güzel kokulu çiçeklerin, taç yapraklarının kuytu karanlıklarında kozaya durmuş tırtılım.

onca bekleyişim senin içindir, acılarla arıtıp da gönlümü, dünyadaki en saf aşkı sana sunmaktır gayem...

ve tırtıllığım umarım ki seninle son bulacak, seninle kanat açacağım günün renklerine ve çiçeklerin başdöndüren özlerine ve gerçek olacak ''tırtılın kaderinin güzel ölmesine '' dair kehanet...

yelken misali açıp kollarımı,

sana topluyorum esen tüm rüzgarları...

biriktirdiğim şimşekler de senin içindir,

büyüttüğüm çiçekler de...

meğer ki batan güneşin 

kızıla çaldığı doğayı seyrettim uzun uzun,

bil ki bu da sanadır,

serebilmek içindir, türlü güzellikleri

miskin ruhumdan, zarif ruhuna...

ve okumuşsak eğer iki satır

emeğe dair,

paylaşmaktır amacım, 

sevgini tüm bir evrenle,

bulmaktır seni tekrar tekrar

dökülen alın terlerinde...

ve ey güzel bu çileli bekleyiş,

mahsende ki şarap misali

karanlıklarla boğulmam da senin içindir...

içimi kemirmesi mikrop gibi acıların,

güzelliklere derin derin mayalanmam,

öylece pişmem de senin içindir,

en leziz yudumumla

beni sana sunabilmek için...

08.2002', 'devran devran olalı beri acep böyle devir hiç yeryüzüne geldi mi?  öyle bir dönmekte ki çarklar, her bir insan, ayağına gelen hayırlı şeyler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yare-dair-nefsimle-munazara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Karalama * 5 *', 'oylesine-karalama-5-tulay-sustam-3h14j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben çömez şaireyim; 

Bilmem süslü sözleri...

İçim neyse dışımda o''dur benim

Yüreğimde hissettiğimi,

Beynimde düşündüğümü yazarım...

Yüreğimin aynasıdır şiirlerim

Sen delikanlım bir şairsin; 

Sözün, özün, gönlün, gözün birdir diye sevdim seni

Ama dalga geçeceksen seni sevdiğim için 

Topla bütün şairleri yanına beni anlat...

Gül halime bıyık altından, umurumda bile değil...

Sana ''delikanlım'' demiştim

İster sev, ister sevme benim sevgim ikimize de yeter.

Ben senin yerine de severim kendimi...

Sen delikanlım bir şairsin; 

Arkamdan konuşacağına...

Al kağıdını, kalemini eline... 

Beyaz sayfalara yaz beni, adımı öyle kirlet

Ama sakın silme bütün dostların okusun

Bende altına not düşerim yazdıklarının...

Ben bu şairi daha tanımadan sevdim...

Tanıdıktan sonra daha çok sevdim...

İsteyen istediğini düşünsün, ne yazacaksa yazsın

Ben sevdim, hiçbir zaman da sevdiğime pişman olmadım

Ben çömez şaireyim; 

yazdığım ve söylediğim her şeyin arkasındayım...', 'Ben çömez şaireyim;  Bilmem süslü sözleri... İçim neyse dışımda o''dur benim Yüreğimde hissettiğimi, Beynimde düşündüğümü yazarım... Yüreğimi...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oylesine-karalama-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Çorak...Lakin Aşkın', 'corak-lakin-askin-abir-zaki-xbtks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güzeldir maddi dünya; 

lakin kısır ve yalın. 

benzemez Sahra’ya; 

çölleşmiş…ama aşkın. 

sonsuz suların vaadinde, 

ekip, biçmek için. 

bilir değerini aşkın, 

bir yürek kadar. 

bir parçacık iç huzurudur aradığı 

bir de tin; 

vahanda büyümek için. 

fakat heyhat! 

lütuf sanırsan onu; 

bırakıp, 

dibinde kusursuz bir delik, 

doldur kovanı. 

sıçrat dört bir yana dilediğince; 

bolca karıştırıp, suyu. 

ve gör; 

aslında, nasıl alçalır ruhum.

Çeviren: Kadir Deniz    9/9/2004

***************************************************************************************

Barren Yet Full... 

material world is beautiful, 

yet infertile and isolated 

unlike the Sahara 

deserted, but full 

promised the eternal water 

to cultivate and reap… 

like the heart, values love 

seeks for a piece of mind 

and a piece of soul 

to be nurtured in your oasis 

………………………indeed! 

But Alas! 

if you take it for granted 

and leave an infallible hole, 

fill the pail 

splash all around as you please 

stir up the water galore, 

and see how it humbles my soul 

………………………indeed! 

September 5, 2004', 'güzeldir maddi dünya;  lakin kısır ve yalın.  benzemez Sahra’ya;  çölleşmiş…ama aşkın.  sonsuz suların vaadinde,  ekip, biçmek için.  bilir ...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/corak-lakin-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamandır Yaşanan', 'zamandir-yasanan-tahir-ozturk-4xqmk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TEMMUZ

Boşluktur

Yüreğimde dalgaların silemeyeceği

Sahil izleri

Vuslat ne kadar yakın

Ne kadar uzak ölüm

Şah damarımda pıhtılaşmayacak ayetler

Zehir zemberektir geceler

Şamdan içinde 

Bir çift mumdur gözüm.

EYLÜL

Yanmaktır

Arz-ı Mev’uttur yüreğim

Kader taşlara yazılıdır

Teknoloji

Devir 

İcattır taş

Tutunmaktır hayata.

Sabaha erişmeyi düşlemek

Mor renk üstündeki çiğ ile

Ba’sü bad’el mevt

Sana dönüktür yüzüm.

ARALIK

Rivayettir

Yazılarım beni yazmaktadır 

Aynıdır geceler

Zehir zemberek

Su yürümektedir damarlarında kayaların

Bilinir

Son nefese kadar bitmez 

Vardır söylenecek sözüm.', 'TEMMUZ Boşluktur Yüreğimde dalgaların silemeyeceği Sahil izleri Vuslat ne kadar yakın Ne kadar uzak ölüm Şah damarımda pıhtılaşmayacak ayetl...', ARRAY['Türk Edebiyatı','Şiir','Tahir Öztürk']::text[], 8.5, '{"poet":"Tahir Öztürk","poet_slug":"tahir-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zamandir-yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıçıyorum', 'siciyorum-gokmen-akyildiz-2mqg1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen beni boşver 

şişeler yar bana artık 

sen beni boşver 

her zümrüt gözlü benim artık 

sen şehrinde eğlen gönlünce 

bende yaparım kendime börülce 

''sen beni boşver'' diyorum 

ama 

barmene kızıyorum 

boş verme 

kadehimi dolu istiyorum 

her sefer içiyorum 

içiyorum.. 

yine de biliyorum 

sonunda sıçıyorum', 'sen beni boşver  şişeler yar bana artık  sen beni boşver  her zümrüt gözlü benim artık  sen şehrinde eğlen gönlünce  bende yaparım kendime b...', ARRAY['Türk Edebiyatı','Şiir','Gökmen Akyıldız']::text[], 8.5, '{"poet":"Gökmen Akyıldız","poet_slug":"gokmen-akyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siciyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimim Ben', 'kimim-ben-gokmen-akyildiz-4yvvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben hep seninken sen nerdeydin? 

bak şimdi bende kendimi kandırdım. 

kucaktan kucağa, 

yataktan yatağa akıyorum. 

görmek istemezsin şimdi beni 

ben bile utanıyorum kendimden 

hani emrah''ın annesi vardır ya 

ondan bile beterim bugün 

şimdi sende kandıramazsın beni 

sen artık o değilsin, 

bende ben değilim 

ben kimim? 

hani beni anlardın ya. 

ben beni anlamıyorum 

hadi anlat kimim ben?', 'ben hep seninken sen nerdeydin?  bak şimdi bende kendimi kandırdım.  kucaktan kucağa,  yataktan yatağa akıyorum.  görmek istemezsin şimdi be...', ARRAY['Türk Edebiyatı','Şiir','Gökmen Akyıldız']::text[], 8.5, '{"poet":"Gökmen Akyıldız","poet_slug":"gokmen-akyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimim-ben-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekti Hayat', 'gercekti-hayat-tahir-ozturk-s4elg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğday tenli, kavruk yüzlü akşamlar vardı.

 Her gün batımında kına yakılırken gökyüzüne, 

 Boğazları yakan, nefes alışları zorlaştıran

 Kömür kokuları olmazdı.. 

 Ne ozonu tabakasını delebilmiştik daha 

 Ne de televizyona esir olmuştuk..

 Yakılan çıralar eşliğinde misafirliğe gidilirdi.

 Radyolardan havadis dinlenir, 

 Radyo sanatçılarının seslendirdiği fasılların eşliğinde 

 Koyulaştırılırdı muhabbetler.

 O zamanlar bir fincan kahvenin gerçekten kırk yıl hatırı vardı. 

 Erken kalkardık sabahları babam işe giderdi ben mektebe. 

 Arkası ve dizleri yamalı pantolonlar giyerdim.

 Şimdiki gibi onur kırıcı bir şey değildi yamalar. 

 Nasıl doğruysa sözümüz öyle bozulmamıştı özümüz.

 Lastik pabuçlarımız en az iki yıl garantiliydi. 

 Asfalt yol yoktu daha, mektebe giderken taş tekmelerdik 

 Pabuçların garantisini sınamak için.

 Bazlama koyardı annem çıkınıma bir de haşlanmış yumurta.

 Öyle şimdiki gibi beslenme çantası yoktu.

 Hoş beslenme zorunluluğu da yoktu. 

 Çocuklar zaten anadan doğma besiliydi o zamanlar. 

 Artık okullu olduk şarkısı eşliğinde yol alırdık okula.

 Öğretmenler kutsaldı. 

 Hem bir baba hem bir ana olarak öğretilmişti bize... 

 Ve bir harf öğretenin kırk yıl kölesi olunurdu. 

 Gerçekten. 

 Öğle yemekleri nadiren, 

 Kahvaltı ve akşam yemekleri ailecek yenirdi.

 Geçim yine sıkıntılıydı ama ek iş yapmak zorunda değildi

 Babalar.

 Komşu komşunun külüne muhtaçtı 

 Bu düstur üzere kuruluydu ilişkiler.

 Bir yemek pişirse annem bir tabakta komşuya götürürdü.

 Kokusu gitmiştir burunlarına komşuluk hakkıdır diyerek. 

 Dört duvar arasında sıkış-tırıl-mamıştık. 

 Yeşile hasretliğimiz, düzensiz mevsimlerimiz, 

 Bereketsiz evlerimiz,besmelesiz işlerimiz yoktu o zamanlar.

 Gerçekten yoktu.', 'Buğday tenli, kavruk yüzlü akşamlar vardı.  Her gün batımında kına yakılırken gökyüzüne,   Boğazları yakan, nefes alışları zorlaştıran  Kömü...', ARRAY['Türk Edebiyatı','Şiir','Tahir Öztürk']::text[], 8.5, '{"poet":"Tahir Öztürk","poet_slug":"tahir-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gercekti-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satmadım', 'satmadim-gokmen-akyildiz-l5x0e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sensiz çok yağmur yağdı buraya 

sensiz ben çok ıslandım sokaklarda 

sıcaklığını hissettim tenimde, 

her damlada 

bak bir kış daha geldi 

ben kalbime kimseyi sokmadım 

kimseye görünmedim 

sana göründüğüm gibi 

ve ben aşkımı 

senin gibi satmadım', 'sensiz çok yağmur yağdı buraya  sensiz ben çok ıslandım sokaklarda  sıcaklığını hissettim tenimde,  her damlada  bak bir kış daha geldi  ben...', ARRAY['Türk Edebiyatı','Şiir','Gökmen Akyıldız']::text[], 8.5, '{"poet":"Gökmen Akyıldız","poet_slug":"gokmen-akyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/satmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manyel', 'manyel-reyhan-sur-u6ez5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bakmayın içten dışa 

siyahlar giydiğime

yüreğimde binlerce 

ak güvercin oynaşır

uçurtmalar balonlar 

vermişler de el ele

herkese göz kırparak

aşkımı fısıldaşır...', 'bakmayın içten dışa  siyahlar giydiğime yüreğimde binlerce  ak güvercin oynaşır uçurtmalar balonlar  vermişler de el ele herkese göz kırpara...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/manyel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
