INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olma', 'olma-erkan-yanarates-9zp51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden yine yaz, yıllar geçmiş aradan,

Çok şükür hep bakıyor yüzümüze Yaradan,

Üç günümüz var zaten gideceğiz şuradan,

Bu günleri de zehir edip olma cefakâr.

Aç kulağını dinle, seni sevdim bir kere,

Neden tuz katıyorsun aşımıza hiç yere,

İyi sor kendine bu adam kim, bura nere,

Gün bugündür maziyi boş ver olma garazkâr.

Derdim anlatılmaz ki bilmem kaç bin satırla,

Altın verseler de onmaz iki bin katırla,

Bel bağladığım sihirli sözcüğü hatırla,

Sana bunu söylemiştim bak, olma şivekâr.

Bir seviyor, bir hançer sokuyorsun kalbime,

Bugün çıkıyor, yarın giriyorsun gönlüme,

Nasıl anlatsam bu halini, yok bir kelime,

Buna sevmek diyorsan vazgeç olma hilekâr.

Erkan der ki, dualar edip kurdum yuvayı,

Ayakta dursun diye aratmadım sarayı,

Bu servete gaz döküp yakacaksan çırayı,

Al benden de o kadar derim, olma günahkâr.', 'Mevsimlerden yine yaz, yıllar geçmiş aradan, Çok şükür hep bakıyor yüzümüze Yaradan, Üç günümüz var zaten gideceğiz şuradan, Bu günleri de z...', ARRAY['Türk Edebiyatı','Şiir','Erkan Yanarateş']::text[], 8.5, '{"poet":"Erkan Yanarateş","poet_slug":"erkan-yanarates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Benim Doğum Günüm', 'bugun-benim-dogum-gunum-adem-aktas-yazgibozan-tmcyi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün Benim Doğum Günüm

Bugün benim doğum günüm...! 

Ama ben, hiçbir şey hissedemiyorum.

Bomboş bakıyorum beni yutan dünyaya

ve aşkına...

Her doğum günümde yaptığım gibi, 

yine annemi dinledim

Bu dünyaya neden ölü ve nefessiz geldiğimi

Beni hayata döndüren o hemşireyi

ve ellerini....

O eller senin ellerindi biliyorum, 

beni hayata döndüren o gözler, senindi.

Bugün benim doğum günüm

Bugün her şey iyi olmalıydı

Yüzüğümü sağ elimden çıkarıp sol elime taktığım,

tek gündü bugün...

İyi ya...! 

Daha başka ne iyi olabilirdi...? 

Daha başka ne isteyebilirdim tanrıdan...? 

Seni.....

Hani nerdesin kardelenim...? 

Neden yanımda yoksun turkuaz gözlüm...? 

Şey......... aslında.......

Bugün benim doğum günüm

Belki babamın öldüğü yaşta değilim

ama.....

Anneme evlenme teklif ettiği yaştayım..........', 'Bugün Benim Doğum Günüm Bugün benim doğum günüm...!  Ama ben, hiçbir şey hissedemiyorum. Bomboş bakıyorum beni yutan dünyaya ve aşkına... He...', ARRAY['Türk Edebiyatı','Şiir','Adem Aktaş Yazgıbozan']::text[], 8.5, '{"poet":"Adem Aktaş Yazgıbozan","poet_slug":"adem-aktas-yazgibozan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bugun-benim-dogum-gunum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dedikleri Yalanmis', 'sevda-dedikleri-yalanmis-emine-yilmaz-q0s8c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda dedikleri yalanmis…

mutluluk sabun köpügü imis avuclarimizda eriyen! 

Biz diye birsey yokmus aslinda

Hep sen ve ben varmisizda anlamamisiz…

Bana söyledigin sözler var ya,

En az;  huzuru benimle buldugun kadar yalanmis…

Basini ellerinin arasina alip

Herseyde ilkin oldugumu söylediginde,  inanmistim sana

Cocukca diyemem cünkü; cocuklar bile inanmaz bu kadarina

Aptalca inanmistim! 

Sende 

Bir kagit parcasi kadar degerim yokmus aslinda! 

Gün geldi, devran döndü

Bencillik fiskirdi yüreginden sevgi yerine

Her sözün kanatti biryerlerimi

Birer birer devirdin umutlarimi tavirlarinla

Cok gecti ama

Anladim

Senin bekledigin

Ayaklarina kapanacak bir köleydi aslinda

Simdi ben basimi iki elimin arasina hapsedip,

 sabahlara kadar düsünüyorum.

Sevgi benim neyime? 

Neyimeydi mutlulugu aramak? 

Yalnizliga alismisken,

Dost olmusken gecelerle…

Keskeleri akitmak gözlerimden yine

Neme gerekti? 

Degilmi ki her sözüm

Agir geliyor sana…

Suskunum bundan sonra! 

Ve kapiyorum yüregimin kapilarini artik. 

Ne hüznümü duyacaksin ne sevincimi bir daha.

Seninle yasayacagim fakat; 

Hayati paylastigim sen olmayacaksin asla! 

Emine Yilmaz', 'Sevda dedikleri yalanmis… mutluluk sabun köpügü imis avuclarimizda eriyen!  Biz diye birsey yokmus aslinda Hep sen ve ben varmisizda anlamam...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevda-dedikleri-yalanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Artı Bİr =Bir', 'bir-arti-bi-r-bir-talip-sinecikli-f3g3v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ben vardım,

Bir sen vardın,

Seninle beni topladım,

Bir olduk,

Senden ben çıktım,

Bir kaldım,

Benden sen çıktın,

Sıfır oldun.', 'Bir ben vardım, Bir sen vardın, Seninle beni topladım, Bir olduk, Senden ben çıktım, Bir kaldım, Benden sen çıktın, Sıfır oldun....', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-arti-bir-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini.', 'gozlerini-kemal-guzel-c170v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖZLERİNİ...! 

Güzel günleri yaşamam adına,

Seni,unutmamak adına,

Düşlerimde seni görmek adına,

Gözlerini bana ver...

Her akşam olup,güneş batanda,

Gün  olur,karanlıkta kaldığımda,

Aydın,görebilmem adına,

gözlerini bana ver...

Vaktim tamam,gidiyorum dersin bana

Ben yangın gönlümle gitme derim sana,

İllede gideceksen yıldızların diyarına,

Sana olan sevdam adına,

Sana olan aşkım adına,

Ve,bütün seven sevdalılar adına,

^^GÖZLERİNİ BANA VER...! ^^', 'GÖZLERİNİ...!  Güzel günleri yaşamam adına, Seni,unutmamak adına, Düşlerimde seni görmek adına, Gözlerini bana ver... Her akşam olup,güneş b...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş çocuğa mektuplar /Bir', 'arkadas-cocuga-mektuplar-bir-zafer-zengin-etnika-utn56', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım arkadaşım

Yine sen yoktun

Doğmamıştın

Mehtup yazayım dedim sana

Başladım karalamaya 

Bugün çok şey değişmedi

Yine cinayetler işlendi

Ajanslar haber verdi

Duyan duydu

Duymayan ölmedi

Arkadaş canım; 

Amerika yine ırakda

Telafar''da

Devam ediyor katliamlara

Hayrettir

Ölecek çok insan varmış

Türkmenler yaşıyormuş daha

Sonraya saklamışlar anlasana

Olmazsa

Belki atom silahı kullanır

Bitirirler görevlerini sonunda

Eylülle beraber

Yağmurlar geldi

Bol yağdı işte

Adı seldi

Sen doğmadın daha

Nerden bileceksin ki

Sonra biraz işkence vardı

Maden ocağı yangını

Promasyonlar

Kampanyalar

Cezada indirim

Cezada indirim ki; 

İyi halden

Hiç mahkemeye gitmeden

Adamın biri ölmüş terbiyesizlikten

Terbiye edilirken

Ölmüş birden

Çık işin içinden

Ben çıkamamışken

Sonra

Maden yangını arada kaldı

Ölen işte

Kastamonudan ondokuz candı

Hepsine duaları edildi

Dua edenler büyük adamlardı

İhmali hemen anladılardı

Diğer ölen kimdi 

Kimse anlamadı

Yemekte fasülye

Yanında pilav vardı

İçine tuz kattım

Tuzda kokmuş çok şaşırdım

İyi ki penguen değilim

Balık yemekten yargılanacaktım

Şaşırma  anlamada

Büyüyünce her şey kitaplarında

İstersen eğer 

Unutma şiirlerde yazda

Balık yemekten yargılanma

Denizin rengini mavi sanma

Denizde renk değişti

Mersin açıklarında

Sen bana bakma

Gelmediğin dünya''da

Bunlar normal hala

Diyeceklerim var arkadaş daha

Sonra yazacağım onları da

Bak büyüklerin

Ne dolaplar çeviriyor

Bu mavi lunaparkda

10.09.2004', 'Canım arkadaşım Yine sen yoktun Doğmamıştın Mehtup yazayım dedim sana Başladım karalamaya  Bugün çok şey değişmedi Yine cinayetler işlendi A...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/arkadas-cocuga-mektuplar-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğun elleri', 'cocugun-elleri-zafer-zengin-etnika-xzqp2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzün yağıyor yüzüme

Durgunluğum ondan

Komiklikler yapıp

Tarihi sallar gibi yerinden

Beni diriltme yeniden

Kokuna sür ellerimi

Bitmiş tükenmişler

Ellemesin tenimi

Sana anlatayım

Bildiğim tüm gizleri

Hüzün yağıyor yüzüme

Durgunluğum ondan

Sür ellerini umuduma

Ölüm beni almadan

Anlatacağım sana

Hayatın neresi yalan

Gittin işte

Şehri ellerime bıraktın

Açlığı susuzluğu şahit

Çocuğu bir başına bırakıp

Kim öykü yazar artık

Böyle ilhamsız kalıp

Gittin işte

tutunamam artık

Sığınacak yerler ayıp

Gülümsemen kayıp

Hayin gülüşler bırakıp

Kutlanası ölümdür şimdi

Düşecek yaprağı dalında sanıp

Sıvazlar tarihi şimdi sancılar

Yerinde mutluluk bu

Geri gelir

Ad çalar kayıplar

Yemin çalmıştım kendimden

Kan gibi akamadım

Yaprağı daldan koparamadım

Soluklanacağım biraz

Suyun var mı

Kırk yılda hatıram kaldı

Küçük çocuğun elleri

Şimdi ölümle dinlenmeli

Uyuyacağım biraz

Toprağın var mı

10.09.2004', 'Hüzün yağıyor yüzüme Durgunluğum ondan Komiklikler yapıp Tarihi sallar gibi yerinden Beni diriltme yeniden Kokuna sür ellerimi Bitmiş tükenm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/cocugun-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-harun-kuscu-u39pu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümden gönlüne yollar uladım

Sevdanı gözümle bir bir suladım

Aşkını yüreğime kaç kez doladım

Çiçeğim açıp açıp doldu dün gece

Umudun adı sen, sevdanın adı sen

Baharlar şöyle dursun yaşamanın tadı sen

Nolurdu beni bir kez anlayabilsen

Ruhumda işkence boldu dün gece', 'Gönlümden gönlüne yollar uladım Sevdanı gözümle bir bir suladım Aşkını yüreğime kaç kez doladım Çiçeğim açıp açıp doldu dün gece Umudun adı ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dun-gece-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdum Hatay', 'yurdum-hatay-fatih-mehmet-karaca-cex5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Amanos Dağlarını karşına al seyre dal

      Belen Geçidinden geç inde Amik Ovasına dal

      Oradan Antakya Şehrine kendini sal

      Antik şehrim,güzel yurdum vatanım Hatay

   

     Yazı başka,kışı başka,baharı,güzü bambaşka

      Portakal,Nar,Ayva,Yeni Dünya ne istersen birbaşka

      Denizi,ovası,dağı,müzesi yoktur başka başka

      Antik şehrim,güzel yurdum vatanım Hatay

      Saymakla tükenmez güzellikler diyarı

      Könefesi,Köftesi,Kısırı,Kabak Tatlısı

      Aranmakla bulunmaz başka hiçbir yerde

      Antik şehrim,güzel yurdum vatanım Hatay

      Türkiyemin gülü,incisi,gözdesi

      Hatayım’da Türkiyemin parçası

      Ayrılmaz Türkiyem’den Hatay’ım

      Antik şehrim,güzel yurdum vatanım Hatay

  

      Kimler geldi,kimler geçti bu yurttan

      Gelenler gidenler geldi geçti yaşandı

      Dağı,taşı,toprağı,suyu Türk Yurdu

      Antik şehrim,güzel yurdum vatanım Hatay

  

      Her taşı bir tarihtir yurdumun

      Antik şehir Hatayım’dır benim

      Dünyada dengi yoktur Hatay’ın

      Antik şehrim,güzel yurdum vatanım Hatay

      Doğu Akdeniz’in bittiği yerde

      Dünyanın gözbebeği bir yerde

      En verimlilerden Amik Ovası bu yerde

      Antik şehrim,güzel yurdum vatanım Hatay

      Eşi,dengi,benzeri yoktur Hatay’ın

      Başka hiçbir yere benzemez benim yurdum

      İnsanlar kardeşçe yaşar geçinir

     Antik şehrim,güzel yurdum vatanım Hatay

                               

                                     Fatih Mehmet KARACA

                             (02.03.1999)    Sarıkamış / Güllüce Köyü

                                                                     KARS', 'Amanos Dağlarını karşına al seyre dal       Belen Geçidinden geç inde Amik Ovasına dal       Oradan Antakya Şehrine kendini sal       Antik ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yurdum-hatay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir arayış...', 'bir-arayis-omer-faruk-girgin-eeexy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamansız ölülerin gözlerindeyim 

sıcak ve yakın...

sahipsizim...! 

ona sözüm yok diyorum 

sahipsiz çingene çadırlarında..

sonra,

ölüme yatan ihtiyara 

ikame ediyorum geçmişimi 

teni soğumuş yarınlara 

tüm bayramlık giysilerimi 

naftalin kokan bir morga bırakıyorum 

karanlık 

karanlık 

karanlık...! 

şimdi  sevmek zamanıdır diyorum 

ölüm sever  bir kadınla 

doyasıya tükenmeden askıdaki  hayallerim 

ve zamansız ölülerin saçlarındayım 

şefkat dolu ve ak...

kırılgan bir hayattı bu bir ihtimal 

geçtiğimiz selvi ağaçlı yollarda 

günler  marazi 

haftalar marazi 

işte bak 

ölü bir ozan 

musalla taşına konuyor 

her yan  kör kelebek 

musallanın gözlerinde 

zamansız ölülerin dudaklarındayım 

yürüyorum  hayali gitmiş kalabalıkların arasında 

yürüyorum soğuk...

ve ben belki bu kentin en yalnız 

kadınını arıyorum…', 'zamansız ölülerin gözlerindeyim  sıcak ve yakın... sahipsizim...!  ona sözüm yok diyorum  sahipsiz çingene çadırlarında.. sonra, ölüme yatan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şey-tan', 'sey-tan-ahmet-aksoy-i2jmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kırgın düşlerde metal

kan bulutu altında kavkı

kılıcın gölgesinde bedenler

esrik bir yolcu girdap unutkanlığı

tut-kal! zaman bir ökçedir

tutulan ve tutulmayan anlar

bir yalan bin doğruya bedeldir

büyürken elmanın azabı

yıl-an  şeytanın kuyruk sokumundan

..................uz-andı

geçti dürbününden Tanrı''nın

gözler içinde hayal

aynalar kırılsın dedi

ve açılsın zihinler

kar-an-lık devinim

duyumsar fecre sarılan eller

................ha-ya-tı

bilen bilir başta

.........ve sonda olanı', 'kırgın düşlerde metal kan bulutu altında kavkı kılıcın gölgesinde bedenler esrik bir yolcu girdap unutkanlığı tut-kal! zaman bir ökçedir tut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sey-tan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş koklanmaz', 'ates-koklanmaz-zafer-zengin-etnika-nqj2c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Harman

Yangın

Düştüm ki 

Kalkarım

Kara bahtım

Kem göze şarabım

Ağrılar sardım

Sana ağlamadım

| Bilinsin ki günah benim işim

  ha deseler küsmeyeceğim..içinize işleyeceğim

  nasıl yakılır dağlar..bir bir göstereceğim..

  sövecek ardımdan masumlar..onların bu hakkı var |

Öldürdüm

Bundan gayrı

Yanmaz olimpos ateşi

Ne de gösteririz 

Yarı insan 

Tanrılarılarınıza sevgimizi

Sana ateşti ellerim

Tutup kirletmedin

Ilık havada

Tanrılara yenilecektim

| Ateş koklanmaz..yangınlardan bilirim

  sürünme..tüm zayıflıklar tamir edilecek nasılsa

  ve yalvarma giden zamana..güçlüsün..yaşarsın bir daha |

Yeşil yanıyor

Çakmağında ateşim

Söverim

Söverim

Omzumda bir taş...

10.09.2004  /Demir harsız yanardı', 'Harman Yangın Düştüm ki  Kalkarım Kara bahtım Kem göze şarabım Ağrılar sardım Sana ağlamadım | Bilinsin ki günah benim işim   ha deseler küs...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ates-koklanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başa Dönüş Var Birde', 'basa-donus-var-birde-mehmet-emin-ozturk-cqcg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göremez olduk birbirimizi

Çalıştığım işyerimden geçmişsin

Mesaj çekmişsin okudum

Hüzünlü görmüşsün beni 

Çok hüzünlü 

Ve çok yorgun demişsin mesajın da

Bende öyleyim diye yazmışsın ardından

Korktuğumuz başımıza geldi

Dediğin gibi 

Korktuğumuzu yaşıyoruz şimdilerde

Uzağız birbirimden uzaklaşıyoruz 

Aslında uzaklaştırılıyoruz, kopartılıyoruz

Gözlerimin önünde yaşıyorum seni 

Yanı başıma oturmuş gibi 

Sohbet ediyorum şimdilerde

Hayallerde yaşamak var seni

Gerçeklerden uzak ama yanımdan gitmedin 

Her daim yanı başıma bırakıyorum hayalini

İçim çok acıyor seni özlüyorum 

Ama bu şiirimi bilemeyeceksin hiçbir zaman

Sana yazdığım bu yüreği...

Gözlerim doluyor 

Hava sıcak ve hastayım canım

Başım da öylesine bir ağrı var ki

Ama seni düşündükçe unutuyorum

Sonra apansız habersiz gelişlerin 

Geliyor aklıma

Gülümsüyorum 

Keşke yine gelebilsen 

Diyorum kendime

Gözyaşlarını döküyorsun gecelerde 

Biliyorum hem de çok iyi biliyorum

Ağlıyorsun benden gizlenerek

Görmesin diyorsun 

Üzülmeyeyim diye

Çağrılar atıyorsun bana 

Nasılsın diyerek 

Cevap vermeyeyim diyorum

Ama olmuyor be canım

Al işte doldu gözlerim

Yaşlı yine ağlıyorum

Oyuncağını kaybetmiş bebek gibi

Evet oyuncağımı aldılar elimden

Sevgilimi çaldılar benden

Kalbimi söktüler yerinden

Onu aldılar benden

Seni aldılar elimden

‘Ama vazgeçmek yok asla’ 

Demişsin mesajında 

Bilmiyorum canım

Bilemiyorum canımsın

Biterse canım bir gün 

Belki okursun satırlarımı

Haber alırsın apansız

Yorgunluğumun son demlerindeyim

Tam kendime geleyim derken

Bir bakıyorum karşımdasın

Ve tekrar başa dönmelerin eşiğindeyim..

07/09/2004		01:08 suları', 'Göremez olduk birbirimizi Çalıştığım işyerimden geçmişsin Mesaj çekmişsin okudum Hüzünlü görmüşsün beni  Çok hüzünlü  Ve çok yorgun demişsin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/basa-donus-var-birde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Vardım Bir Yoktum-2', 'bir-vardim-bir-yoktum-2-mehmet-emin-ozturk-r6ooe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Genç kıza baktı

Kız gence gülümsedi

Bakışmalar başladı

Adam içinden geçenlerle 

Kızda onu tanımanın 

Heyecanında

Kız gençten yardım istedi

Gençte büyük bir heyecanla

Kıza yardım etmeye başladı

Daha sonra ertesi gün 

Kız yine geldi aynı yere

Gence yaklaşarak merhaba dedi

Gençte hoş geldiniz diyerek 

Yerini gösterdi kıza

Genç bir yandan 

Müşteriler ile ilgileniyordu

Ama kulağı kızdan gelecek yardımda idi

Kız yine yardım istedi

Ve genç yardım etmeye başladı

Bir yandan yardım ediyordu

Diğer yandan da ona bakmanın heyecanıyla

Kendini alamıyordu 

Kendini unutuyordu

Genç tekrar diğer masalarla ilgileniyordu

Genç kızda bir yandan işlerini hallediyor diğer yandan da 

Onu izliyordu fark ettirmeden

Ve onu düşünüyordu 

İçindeki duygular ne diyerek

Genç kız geçmişteki birine benzetiyordu onu

Hayatını kurtardığı birine

Ama aradan çok yıllar geçmişti

Zaman öylesine ilerlemişti ki

Anımsayamıyordu düşüncelere dalarak gidiyordu

Sadece bir gece saatler süren izleniş

Ve de ardından birkaç kez görünüş

Bir daha da yok oluş ardından

Yılların geçmişi var geride kalan

Nasıl hatırlasın ki kız

Yıllar önceki yaşananlar

Ve şimdide karşısına çıkan 

Anlayamadığı, aslında hissedilen

Gizliden yaşanan bir heyecan

04/09/2004		02:00 suları', 'Genç kıza baktı Kız gence gülümsedi Bakışmalar başladı Adam içinden geçenlerle  Kızda onu tanımanın  Heyecanında Kız gençten yardım istedi G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-vardim-bir-yoktum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımıyorum', 'acimiyorum-zafer-zengin-etnika-r8j24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acımıyorum

Tanrıların ölümlerine

İzmaritler basıyorum ciğerlerine

Hep kızmıştım

Yine kızarım

Canları çektiğinde

İnsanların arasına inmelerine

Alın kan kusan ellerinizi

İsmimize sürmeyin lekenizi

Mitleriniz şiirin eskileri

Memedimin sizden önce söylediği

Sen memed

Çal ateşi şunlara

Al dizelerimi

Ver yurdumda çobanlara

Islatsınlar

Kavallarından akan suyla

Alın teri merhaba

Merhaba

İçinde ateş saklayan insanıma

Can /

Bir lokmam vardı can

Yazdık işte

Sen şiir san

Biraz ağla

Sonra gelsin merhaban

10.09.2004

Yeni doğan can yeğenim elifnaz''a..hoş geldin elif can dünyamıza..', 'Acımıyorum Tanrıların ölümlerine İzmaritler basıyorum ciğerlerine Hep kızmıştım Yine kızarım Canları çektiğinde İnsanların arasına inmelerin...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/acimiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Beyim', 'kucuk-beyim-baykal-kaanalp-n552j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bakışına bir sefahat

hakim

gülüşüne çok bilmişlik

gördükleri yalnız

kendinin

görmedikleri yok

pınar gibi görünür

zehir akıtır içinden

pazarlığa gelmez

almaya hiç

verilenler onundur

alamadığı yok

küçük beyim

beni de götür

deyiveren dadı

ardında kalır

yaşanmamış düşlerin

gidişi bi fiyakalı ki

sorma

burnu büyük

dengi yok belki

alışılmışın dışında

alışılmadık biçimde

salınır,kırılır beli

yanındadır elleri

sanırsınız ki deli

küçük beyim

alma beni yanına

yakışmam endamına

fiyakan buz olur

ruganların toz olur

gidemeyiz yanyana

bir mektebe

bir fakirhaneye

sende bilirsin

farklıyız,farklı

sen oturaklı

ben tumturaklı', 'bakışına bir sefahat hakim gülüşüne çok bilmişlik gördükleri yalnız kendinin görmedikleri yok pınar gibi görünür zehir akıtır içinden pazarl...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kucuk-beyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelam', 'kelam-baykal-kaanalp-d6no2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne söylediği belirsiz bir kaç kelam

vermez tanımadığı kimseye selam', 'ne söylediği belirsiz bir kaç kelam vermez tanımadığı kimseye selam...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kelam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Saatler', 'mutlu-saatler-baykal-kaanalp-e25pd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işe yaramıyor mu? şimdi

geçirdiğimiz saatler

güneş üzerimizde

batmaz mı? şimdi

kaçırdık mı? çalınmış 

aşkları,çalanları

kalbimizden, ruhumuzdan

bedenimizden,halimizden

bitti mi? tüm ayrıntılar

şehirler kabul etmez mi? 

yaşamını birlikte

yazdığımız,herbirimizi

soğudu mu? tenler

sıcaklığını koruyamaz mı? 

illa kibitmek zorunda mı? 

mutlu saatler', 'işe yaramıyor mu? şimdi geçirdiğimiz saatler güneş üzerimizde batmaz mı? şimdi kaçırdık mı? çalınmış  aşkları,çalanları kalbimizden, ruhumuz...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlu-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı Yunus', 'aykiri-yunus-erdal-cevik-6ytm8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kemiklerimi sızlatır

Boşlukta durmak.

Etim acır tenine deyince.

Soluğunun buğusudur

Yanaklarıma düşen çiğ.

Kendime gelirim,

Bir yer kanar içimde.

Eski yalnız bir han gibidir,

Aklımın koridorları.

Küçük bir kız gezinir,

Ölüm paradokslarımda

Adını fısıldayarak düşer,

Bir çeşmenin dudağından,

Yorgun bir su damlası.

Candamarına bütün evrenin.

Yunus''un kafasında canlanır,

Aykırı bir düşünce; 

İnsan aşıkmı kendine? 

Ben senide sevemezsem

Söylesene tanrı nerde?', 'Kemiklerimi sızlatır Boşlukta durmak. Etim acır tenine deyince. Soluğunun buğusudur Yanaklarıma düşen çiğ. Kendime gelirim, Bir yer kanar iç...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aykiri-yunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla', 'yagmurla-erdal-cevik-okqwg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ölünce,

Toza toprağa karışıp küçülünce,

Bir su buharıyla 

Havaya yükseleceğim.

Ve şehnine geleceğim

Bir rüzgarın dilinde.

Bir yağmur başlayacak,

Şehrinin üzerinde.

İşte o an,

Yüzünde dağılan suyu izle,

Avuçlarını ıslatan suyun içinden,

Yerle bir olup

Düşecegim

Yanaklarının üzerine.', 'Ben ölünce, Toza toprağa karışıp küçülünce, Bir su buharıyla  Havaya yükseleceğim. Ve şehnine geleceğim Bir rüzgarın dilinde. Bir yağmur baş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmurla-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupa Emeli', 'avrupa-emeli-baykal-kaanalp-qwhq3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Türkiye''nin geneli

Avrupa''dır emeli

düşünsene bir kere

bu sevdalar nereli

bunlara ne demeli

yaşam bir parça masal

çoktur görülmüş emsal

anlasana bir kere

düşünceler çok uysal

hayal etmekse yasal

bir bakış ki çok farklı

anlayışlar hesaplı

saymasana bir kere 

defterler kara kaplı

görüşler geniş çaplı', 'Türkiye''nin geneli Avrupa''dır emeli düşünsene bir kere bu sevdalar nereli bunlara ne demeli yaşam bir parça masal çoktur görülmüş emsal anla...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/avrupa-emeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin Gibi', 'yemin-gibi-erdal-cevik-cvof8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğunu anımsayınca,

Bir yemin gibi takıldı dilime; 

''Bir ağıda başlamak

İsminin bittiği yerde,

Ya da ölmek

Gittiğin yerde''', 'Yokluğunu anımsayınca, Bir yemin gibi takıldı dilime;  ''Bir ağıda başlamak İsminin bittiği yerde, Ya da ölmek Gittiğin yerde''...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yemin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-erdal-cevik-erlvz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslında

İsimsizdir

Benim şiirler

Bu yüzden

Öksüz çocuklar gibi suspus

Oturur tepelerinde

Başlık diye yazdığm

Sıkıcı kelimeler', 'Aslında İsimsizdir Benim şiirler Bu yüzden Öksüz çocuklar gibi suspus Oturur tepelerinde Başlık diye yazdığm Sıkıcı kelimeler...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isimsiz-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Tualim', 'sen-benim-tualim-sekri-vuslat-cq9uc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geçmemişte bir gece,

elimde çılgın bir fırça,

paletimde binbir renk,

sen benim tualim...

ben ateşli, ben delice,

renkler paramparça, 

anlatılamaz ki bu zevk, 

sen benim tualim...', 'geçmemişte bir gece, elimde çılgın bir fırça, paletimde binbir renk, sen benim tualim... ben ateşli, ben delice, renkler paramparça,  anlatı...', ARRAY['Türk Edebiyatı','Şiir','Sekri Vuslat']::text[], 8.5, '{"poet":"Sekri Vuslat","poet_slug":"sekri-vuslat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-benim-tualim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin dayanilmaz hafifligi', 'sevmenin-dayanilmaz-hafifligi-rengin-gardner-y0utc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hersey cekingen gulusunle basladi

Kibarliginla devam etti, askinin atesi

Gunlerce aylarca sure geldi,

Ta... ki beni sevemeyecegini anlayana dek

Elimden geleni yaptigimi saniyordum,

Seni sevdigim gibi

Beni sevmeni istiyordum,

Tabiki benimkisi bir hayaldi

Sanirim hep hayal olarak kalacak,

Gonlun  baska sevgilere acik olacak

Beni sevebilmen hayaliydi  belki

Beni sana baglayan

Bu hayalimde tukendi

Peki neden hala seviyorum seni

Neden hala aciyor kalbim sevgisizliginle

Seni sevmemeyi ogrenebilsem keske

Birgun bitecek sevgin yuregimde

Huzura kavusacak ruhum

Sen varsin dilegimde

Insallah benim gibi olur sonun

Rengincik (Rengin Gardner) 

Eylul/10/2004', 'Hersey cekingen gulusunle basladi Kibarliginla devam etti, askinin atesi Gunlerce aylarca sure geldi, Ta... ki beni sevemeyecegini anlayana ...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevmenin-dayanilmaz-hafifligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Sensizligi yasiyorum', 'senli-sensizligi-yasiyorum-rengin-gardner-8brjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Simdi umidim degilsin,

Bende eski ben degilim

Daha mutlu daha iyiyim,

Ama hala suruyor sana olan sevgim

Seni sevmem hata biliyorum,

Seni ve askimi zamana birakiyorum

Senli yada sensizde olsa,

Yarinlarimi oldugu gibi kabul ediyorum.

Rengincik (Rengin Gardner) 

Eylul/10/ 2004', 'Simdi umidim degilsin, Bende eski ben degilim Daha mutlu daha iyiyim, Ama hala suruyor sana olan sevgim Seni sevmem hata biliyorum, Seni ve ...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senli-sensizligi-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biktim seni sevmekten', 'biktim-seni-sevmekten-rengin-gardner-zbvms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiler nasil biter bilirmisin? 

Sevilen terkeder, seven umit eder,

Zamana mahkum olur ozlemler,

Aciyla suruklenir, tukenir biter.

Olmayacak duaya amin  diyemem,

Seni sevdigim gibi sevmeni bekleyemem

Hele bu saatten sonra,

Sana sevmeyi ogretemem.

Seni sana birakacagim,

Hic birsey almayacagim yanima

Belki yuregimle aglayacagim

Sensiz yasiyacagim yarinlarima', 'Sevgiler nasil biter bilirmisin?  Sevilen terkeder, seven umit eder, Zamana mahkum olur ozlemler, Aciyla suruklenir, tukenir biter. Olmayaca...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biktim-seni-sevmekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A - 02 Hani', 'a-02-hani-nilgun-yuce-ii52r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani! 

Yağmur damlalarının, 

Çiseleyerek dokunuşu, 

Vardır ya,

Tenine...

Hani! 

Soluk verir ya, 

Yeniden doğmak, 

Yaşamı kucaklamak gibi

Canına...

Hani..! 

Bilinmeyen bir senfoni başlar ya, 

Yüreginin derinliklerinde,

Ürperirsin,coşarsın, koşarsın, 

Sevgiye...

Hani! 

Sımsıkı sarılırsın ya, 

Benliğine, bedenine,

Sahiplenirsin duygularını,

Kendince...

Hani! 

Anlatabilmekse, 

Sevgiyi, duru su misali,

İşte!  Bu benim,

Yüreğimde...', 'Hani!  Yağmur damlalarının,  Çiseleyerek dokunuşu,  Vardır ya, Tenine... Hani!  Soluk verir ya,  Yeniden doğmak,  Yaşamı kucaklamak gibi Can...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/a-02-hani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kurmak Güzeldir', 'hayal-kurmak-guzeldir-nilgun-yuce-msx3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşler bahçesinde idim; 

Yine dün gece.

Hayal kurdum,

Sana dair seninle.

Gözlerimi kapatıp sessizce,

Ellerini tuttum hafifce.

Tombuldu,birazda iri

Okşamak geçti içimden herbirini.

Yavaşca; Düşledim bitimsiz bir vadi,

Akıp giden hafif bir su sesi.

Sesin sesim,

Nefesin nefesim gibi.

Okşadım saçının her telini,

Hafifce dökulmüş,seyrekleşmişti sanki...

Bir annenin elleri; Bebeğinin tenine dokunur gibi,

İncitmek istemedim; Severken seni.....', 'Düşler bahçesinde idim;  Yine dün gece. Hayal kurdum, Sana dair seninle. Gözlerimi kapatıp sessizce, Ellerini tuttum hafifce. Tombuldu,biraz...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-kurmak-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi gülü unut', 'mavi-gulu-unut-mine-gul-u0qjj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeşerttiğin o tomurcuğun açma vakti değildi ki zaten...

Hep maviye hasret

Hep geç kaldı o

Hep zamansız filizlendi.

Varsin olsun,....bosver! 

Mavi gülü unut sen

Hiç tanımadın

Hiç bilmedin

Hiç koklamadın say.

Topraklara göm istersen

Ya da denizlere fırlat

Ya da bir martıya ver

Alıp uzaklara götürsün

Yok olsun, kaybolsun

Unutulsun....

Bırak solsun

Açmadan solsun

Açarsa kanayacaktı

Biliyordu....

O yüzden gömülmenin tam vakti şimdi....! 

(Agustos 2004)', 'Yeşerttiğin o tomurcuğun açma vakti değildi ki zaten... Hep maviye hasret Hep geç kaldı o Hep zamansız filizlendi. Varsin olsun,....bosver! ...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mavi-gulu-unut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlence', 'dinlence-zafer-zengin-etnika-vf3ta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dedim kalkalım

ölmemiş

şehri terk etmiş gibi

sakin ol

aşık mısın

gül oynadı 

rüzgarında mısın

sigara duman atar içine

sancı büyür

gülüş kaybolur

ay ışığına düşünce

şimdi gidelim

şehri terk edip dinlenceye

dönmeyelim geriye

22 08 2004 datca | dinlence |', 'dedim kalkalım ölmemiş şehri terk etmiş gibi sakin ol aşık mısın gül oynadı  rüzgarında mısın sigara duman atar içine sancı büyür gülüş kayb...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dinlence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-ahmet-agdere-c2nom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dış kapıda eşik sessiz,

Sen gittiğin andan beri.

Vurulmaz kapıya sesli,

Bu dairede herşey sensiz.

Dar gelir, geniş merdiven,

Nazlı girer hava benle.

Duvar inler hasretinle,

Anar seni,''Ah sen, ah sen! ''

İçilmez çeşmeden suyu,

Kurumuş çiçekler birer...

Balık, kuş, ardından gider,

Değişti bu evin huyu..

Yatak almıyor bedeni,

Veya ruh gitmez istemez.

Gündüzler bana ''gel'' demez,

Sen gittiğin andan beri..', 'Dış kapıda eşik sessiz, Sen gittiğin andan beri. Vurulmaz kapıya sesli, Bu dairede herşey sensiz. Dar gelir, geniş merdiven, Nazlı girer hav...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ahmet-agdere-y73z8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek bir beden içinde milyarları yarattın. 

Milyarlar içinde de, yalnızları oynattın! 

Gerçek olan sonumuzun iki hecesiyle, 

Usumuzu her saniye tek tek çınlattın!', 'Tek bir beden içinde milyarları yarattın.  Milyarlar içinde de, yalnızları oynattın!  Gerçek olan sonumuzun iki hecesiyle,  Usumuzu her sani...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masmavi olmalı gidişlerin', 'masmavi-olmali-gidislerin-mine-gul-03gos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitme, dur! 

Yakışmaz mavi yüreğine

Böyle suskun 

Böyle ansızın gitme! 

Masmavi olmalı gidişlerin....

Engin denizlerin en koyu mavisiyle bakmalısın son bir kez

En berrak gökyüzünün aydınlığıyla gülümsemelisin

Sonra zarif bir martı edasıyla masmavi olmalı uçup gidişin.

Mavi yüreğini karartma 

Masmavi kal ne olursun

Tüm mavilikler seninle olsun....

(Agustos 2004)', 'Gitme, dur!  Yakışmaz mavi yüreğine Böyle suskun  Böyle ansızın gitme!  Masmavi olmalı gidişlerin.... Engin denizlerin en koyu mavisiyle bak...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/masmavi-olmali-gidislerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamalıyım Sevdamı Seninle / ss-9', 'yasamaliyim-sevdami-seninle-ss-9-nesrin-gocmen-gww9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi göklerimin şen meleği; 

gönül bahçelerimin sarhoş kokulu çiçeği..

Yitmiş yıllarımı kazandıranım,

gönlümün mabedinde anıt gibi duranım...

Hammaddesi canımın,

gerçek olmayacak düşüm,

çingene sevdam benim.

Kuşların cıvıl cıvıl öttüğü; 

kırçiçeklerinin, yabangüllerinin renklendirdiği; 

pınarlarında suların buz gibi, şırıl, şırıl aktığı; 

ve yalnızca baharların yaşandığı 

bir alemde,

yaşamalıyım sevdamı seninle.

Karlı sıradağların peş, peşe göründüğü; 

yüksek bir tepenin üzerinde

kızılderililer gibi; 

ağaçlardan, sazlıklardan, kendi ellerimizle yaptığımız bir kulübemiz olmalı; 

teknolojiden, bilimden, fenden, tüm kirliliklerden, pisliklerden uzak, 

doğanın göbeğinde, doğanın parçası olarak,

yaşamalıyım sevdamı çingenece...

Boyumuzu aşan, rüzgarlarla deniz gibi dalgalanan,

rengarenk otlar arasında saklambaç oynamalıyız.

Rüzgarda uçuşan saçlarım, savrulan eteklerim,

kahve buğusu gözlerim, çocuksu tavrımla

kovalamalıyım seni düzlüklerde, tepeliklerde.

Yakalanmalısın bana kendi isteğinle; 

alt, alta; üst, üste yuvarlanmalıyız yatağımız  yeşilliklerde....

Yoruluduğumda, üşüyen bir güvercin gibi sokulmalıyım koynuna..

Başımı göğsüne koyunca sarmalısın beni sıkıca

yabanların  tehlikelerinden sakınarak..

Okşamalısın saçlarımı, ellerimi...

Ağzımda kalan yarım sevda sözcükleriyle,

mutlu; sevgi ve güven içinde, 

dudaklarımda gülücüklerle 

uyumalıyım kollarında...



Sonsuza dek 

yaşamalıyım sevdamı çingenece

böylece, 

böyle bir yerde...

Desem ki, 

''ben böyle bir yer biliyorum, hadi gel, kaçalım seninle.. 

  Orada yaşayalım ömrümüzce''...

Tamam sevdiğim,

ne diyeceğini biliyorum.

 ''Gidemem ben'' diyeceksin.

 ''Bin engel var'' diyeceksin.

Onun için sen sus! 

Bozma büyüyü, 

bozma düşümü..

Sen söyleme, 

hiçbir şey söyleme....

(sen söyleme-9) 

11/09/2004', 'Mavi göklerimin şen meleği;  gönül bahçelerimin sarhoş kokulu çiçeği.. Yitmiş yıllarımı kazandıranım, gönlümün mabedinde anıt gibi duranım.....', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yasamaliyim-sevdami-seninle-ss-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sevgili / ss- 8', 'elveda-sevgili-ss-8-nesrin-gocmen-8bgwz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirsin elvedayı sevmem, 

kimseye veda edemem. 

Ayrılıklarım sessiz oldu şimdiye dek.

İkimiz de biliyoruz, 

sevdik biz bizi tüm gerçeklere, 

tüm ulaşılmazlıklara, 

benim tüm direnişlerime rağmen...

Sen başrolü oynayan bir yönetmendin sevda sahnesinde,

bense iyi bir oyuncu değildim. 

Senaryoya uyamıyor, saçmalıyordum. 

Geri dönüp,  baştan almak zorunda kalıyordun perdeleri...

Olmuyordu sevgili, ne kadar çaba versem, 

ne kadar istesem de olmuyordu..

O kadar yıpranmış, yıkılmıştım ki şimdiye dek,

yıkıntılar eziyordu bedenimi,  onamıyordum...

Geçmişte yaşadıklarım 

bir, bir senin de üzerinde yoğunlaşmaktaydı...

İçimden gelen  ''aynısı mı olacak'' seslerinden

kurtulamıyordum.

Dostum, arkadaşım dediklerinden

paylaşamıyordum seni.

Onlara yazdığın her bir sözcük,  her bir dize 

dayanılası değildi benim için...

Sana demeye kalktım,  büyük tepkilerinde boğuldum,

güvenmediğimle suçladın beni... 

Alışmaya çalıştım, mümkün değildi....

Sevdiğimi paylaşmayı öğrenememiştim. 

Peşinde dolaşanlar,  yüreğini sana açanlar 

her geçen gün arttıkça ben geçmişimle kavgalıydım....

Seni de hüzünlerimle boğmaya başladım.

Düşünmedim değil çoğu kere

ben de dostun olsaydım keşke...

Onlar hep benden öndeydi sahnede,

ben figüran, onlar asıl oyuncuydu, 

güzel oynuyorlardı rollerini...

Olmayacaktı sevgili  veremez olmuştum bu kaprislerin, sitemlerin ortasında 

sana istediklerini...

Ve almak istiyorum yüreğimi senden... 

Kalmaz bilirim yeri boş...

Çevrende kaç tane var benim gibi,

hatta benden de iyisi..

Bu bir ne veda, ne de kopuş senden

beni anlamaya çalış

ve sus

bir şey söyleme,

sen söyleme....

(sen söyleme-8)', 'Bilirsin elvedayı sevmem,  kimseye veda edemem.  Ayrılıklarım sessiz oldu şimdiye dek. İkimiz de biliyoruz,  sevdik biz bizi tüm gerçeklere,...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/elveda-sevgili-ss-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bacaların uçamayan baykuşu', 'bacalarin-ucamayan-baykusu-akin-akca-ha85d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A.

intro 

Kocaman, beton bir baca bu; 

(baykuşu özgür bırakarak onu 

yücelttiğini muğlaklayan)

Bir kulübe büyüklüğünde, 

karşı apartmanın yaylasında - 

terasta- sanki! 

~æ~ 

Ne var ki, yabancılık çekmez 

lir’ler, arp’lara; aslında: 

Yürek bir defa, dokunmuştur; 

yalancı, habis biçimde 

ötelendiğinde: 

Sırtına hörgüç ettiğin yelesi 

Arp’ının, sana bir Lir olduğunda: 

kolay gelsin, Çalgı Takımyıldızı; 

o halde (!)

Ne var ki, Vega’dan dem vurmaya 

başladığında; değil yürürken, 

koşarken, Arp’ı sırtlanacaksın! 

a. 

Acı,sus..pus; bir kenara pıs.. 

Pus vardı “izi sürülen is''in”..terkibinde bile! 

Puhu kuşu, vakitsiz baca temizleyicisi, bekçisi gecenin! 

Sis’e benzer gelmişti, izi sürülen 

(ama sonra, sırra kadem..)

; sana önceden, is''miş gibi gelen.. 

ama şimdi, önceden is olduğunu anladın; 

ki böylesi yeğ ve hala da onlasın … 

onun için onun izini sürdün! 

… Ateş durmaz: 

suda duran, “pim’si fitil”ini senin çektikçe 

ve uzattıkça, ve sen! .. 

: Sen, sudaki ateşi -durmayasın diye 

- alevler de seni körükler 

* 

”Moonlite Sonata” gibi. 

Kırılgan ve dilsiz: 

kel ve fodul -ve hadi sen bununla yoğrul (! !)

-ama boş hem, hem dolu: 

Ötesinde 

(bir tortu, zayıflayan; semirdikçe)

; Ölürken yaşamayı başarmak, 

yaşarken defalarca ölmek.. 

b. 

Biraz dozunu kaçırdım özgürlüğün, 

Ama olsun varsın, sarf ‘özgür irade’ adına! 

Ki tatmak: soluk alır da verir ya insan; 

Bunu zordur! :azcık sezilen uğruna 

(sezilgen bir parçacık gibi, kütlesiz - 

bir yeknesak, cisimsiz-hacimli; 

ya da hacimsiz bir cisimli, asli şekilden yoksunken)

göze almak; ‘tüm bir çarkı döndüren 

dişliler.. ’in fırçalanmamış 

(dişleri)  külfetine katlanmak..

olsa gerek, kınında bıçkı bekleten - 

yanar döner bir baş pehlivan, 

Karakucak’ta tosun eken. 

Göllerin altındaki kristalize 

donmuş gül tarlasının öbeğinde 

şahlanan güzide kır çiçeği -baharın 

- Güz’ün, kendini onlardan saymadıkça, 

ilkokul 

cetvelindeki boncuklar parmaklarına 

geçkin yine de: 

Haykırıyor enderini, aslen-asil-gül zerafeti’nin! 

* 

Kör bir yalnızlık; 

Nankörlüğü, sığdıramayanın coşkuyu! … 

-gökyüzü yapan, korkuyu- 

defalarca susturmaya çalışmıştı korkuyu! 

(Ve gitmeye çalıştı; kalmıştı, hatta ama) 

sesini fakat, süresiz; sırf kendi 

ürkekliğinin, kesmişti! 

~æ~ 

Her biri için! Ay’daki kraterlerin: 

Onların lir’lerinin, makus geçmişi; 

müjdecisiydi, kendisini hazırlayanın! 

Ve savuşturuluşunu 

göktaşlarının: 

Ne var ki, senin tekelinde 

gizli bir savunma şekli 

var gibi: 

göktaşlarını kendine çekerek yok eden; 

sırdaşlarını, itekleyerek var edebilen! ! 

(ancak, gerçekten üzen!)

-------

B.

BAŞLATAN, ÖNCEKİ KISA ORJİNALİ:

In hands, are eyes: “Fairy of the Lady”, hold my hand

and gives her softness o’sincerety 

‘Which a couple and a whole’ -

we; shall not panic

Through the attic, the chimney you desired

And ‘the very well-known-owl’ of this story -

You desired the chimney, 

through the roof, holden by the attic; 

So, sky’s coming closer … We shall not panic

Because of the attic, haven’t got a roof

ORJİNALİN TÜRKÇESİ:

a.

Gözler, taşınan avuçlarda: Masal perisi, tutmuştu elimi

Ve verir, duyguları’ndaki -yumuşaklığı samimiyetin- o ince zerafeti -

O, kör gibi kalmış samimiyeti …

Bir çift ve bir tam; 

Panik etmeyeceğiz, biz! 

*

Tavan arasından doğru, kıvrımlarına sızan baca, 

senin güzide düşlerinin ve çok iyi bilinen bir baykuş,

bu hikayenin :

Sen hayalettin bacayı, çatıdan doğru,

tavan arasının,..kazarak tutup doğrulttuğu

*

Ve evet, gökyüzü yaklaşıyor: Biz, panik etmeyeceğiz,

.. ‘Çatısı olmayan ve hücresinde yiyecek bekleyen bu tavan arası’ gerekçesiyle.

Çünkü, yalnızlık üç kere daha yalnız: (Panik etmeyeceğiz, biz!) 

Kendinden sıyrılmaya azimli, şu tavan arası; 

(kötüdür, onun her iki yana da meyil verişi) 

süzen, uğursuz bir baykuş! 

ve çatısı onun -edeceğiz onu ve, tuş! 

Tavan arasının elleri; uzandığının yüreği uğruna, çatının gözlerine -

Geçen boğazına- en güzel bir tutuş! 

Uçmak için yaşamaktan ziyade, zindansız -tavan arasız- bir çatı gibi; 

Bu tavan arası yüceltir bu evi, görkemli olur kaldırış! 

b. (A) 

Büyük beton bacayı nasıl taşır: odun evin sırtında, baykuş

(Bacayı izleyen, karşı apartmanda ve Moonlight Sonata dinlemekte) 

Ve çatı bacasından doğru tavan arasına bir de, tünemiş! 

c.

Baktı pencereden ve iğne kutusuna gitti onun eli.

Parmağına bandırdı azıcık, çeliği -kan geldi; ölçtü, biçti

ve pencereden aşağıya sarkıttı, diğer eliyle kavramış olduğu dikiş ipliğini:

‘Gecenin kopkoyu karanlık ormanı’ bereketliydi; 

İpçiği, büyüttü …

İp oldu ve sonra urgan -

‘(menkıbelerin)  gemici düğümlü birkaç sıradan’ ama ‘anlamlı izci sözü’! 

Hızla indi, yapışarak o ipe ve düştü, yuvarlandı, debelendi ve ağlayarak kalkarak …

: Başlamıştı bir sağanak o sıra, koştu ormanın içine, daha içine … 

(ve şu sıra, evdekiler uyuyordur! 

Nerede kendisi? 

Dün gibi fakat iki dakikada katetti, bir mucize! 

Ama onun anlatıyor ceylansı sekişi; var olan saçmalığı da, var edişi de!) 

Çok arkasında kaldı şimdi: dün gibi; koskoca, karanlık malikane …

- 

Ela Somit’e yazdığım yorumlardan yöneldim bu şiire. Kendisine buradan teşekkürler 

1-A kıtası, daha çok “bu” ile anlatılırken, diğer kıta daha çoğunda, “şu” ile betimleniyor.

(Bir anlamda; anlamsal ana fikre ulaşma doğrultusunda, kıtasal-gizli özneler..) 

2-Ardışık iki şiir halinde bir bütün..

------A. için açıklamalar: 

1a. Lir: bizim arp olarak bildigimiz calginin ufak, elde ta$inabilir olani. asterix serilerinde kakafonix''in elinden du$urmedigi alet. 

1b. ''bir lir bir kemanı gece olunca kıskanırmış yalnızca'' şeklinde tanımlanan kıskanç enstruman. 

2. çalgı takımyıldızı: ejderha''nın* hemen altında, yazın yükselen küçük bir yıldız kümesidir. (bkz: takımyıldız)

ismini mitolojide orfe''nin çaldığı lir''den alır. en parlak yıldızı vega''dır. 

kısaltması: lyr. 

www.eksisozluk.com', 'A. intro  Kocaman, beton bir baca bu;  (baykuşu özgür bırakarak onu  yücelttiğini muğlaklayan) Bir kulübe büyüklüğünde,  karşı apartmanın ya...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":156,"source_url":"https://www.antoloji.com/bacalarin-ucamayan-baykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anısın Artık Yüreğimde', 'bir-anisin-artik-yuregimde-mine-gul-dx08y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biraz tatlı, biraz acı, bir anısın artık yüreğimde...

Beni unut diyorsun,

Üzgünüm...

Ben seni unutmayacağım.

Unutursam biliyorum,

Yine yalan sözlere,

Sahte gülüşlere inanacağım.

Yine gerçeklerden kaçıp,

Hayal âlemlerinde dolaşacağım,

Ve yüreğimde kalan son damlayı kurutacağım.

Beni affet diyorsun,

Üzülme...

Ben seni affediyorum,

Senden nefret dahi etmiyorum, edemiyorum.

Mavinin hatırı var, kıyamam bilirsin...

Ya sen, sen kendini affedebilecek misin? 

(Eylül, 2004)', 'Biraz tatlı, biraz acı, bir anısın artık yüreğimde... Beni unut diyorsun, Üzgünüm... Ben seni unutmayacağım. Unutursam biliyorum, Yine yalan...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-anisin-artik-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miraç', 'mirac-bayram-tunca-q6ekn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geldi mi miraç kandili 

Tatlanır insanların dili 

Çünkü yad edilir Nebi 

Şenlenir ekserinin evi 

Miraç vuslatta mihenk taşı 

Miraçla göklere değdi başı

Beşer Hz. Muhammed aşığı 

Çünkü O nebilerin bile aşığı 

Ey dost gözünü gönlünü aç 

Bugün vuslat-ı ekber miraç 

Kaldır perdeyi aç ellerini aç 

İnsanlık duaya çok muhtaç 

O, cenneti cehennemi dolandı 

Tercihini bizden yana kullandı 

Alâ hediye ve müjdeler getirdi 

Kulağa küpe/başa taçtır hepsi 

Yoktur başka vuslatlarda bu tat 

Çağrıya icabet için aştı yedi kat 

Yapıldı kırılması güç rekor surat 

O’na ümmet olabilmektir murat 

Hey arkadaş aç şu gözünü gönlünü aç 

Bak bu gece yine vuslat-ı ekber miraç 

Kaldır şu gaflet perdesini aç ellerini aç 

İnsanlık dört unsur gibi duaya muhtaç 

B. Tunca/11.09,2004-08.09', 'Geldi mi miraç kandili  Tatlanır insanların dili  Çünkü yad edilir Nebi  Şenlenir ekserinin evi  Miraç vuslatta mihenk taşı  Miraçla göklere...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mirac-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemû hestên min ji bo te diherikîn', 'hem-hest-n-min-ji-bo-te-diherik-n-omer-dilsoz-kxen4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaroktiyê min gelek meraq dikir ka li pişt çiyan çi heye…

Ji nav deman derketibûm, ji nişka ve di navbera xîçikeke zirav a hizr û ramanan de gihîştibûm zaroktiya xwe. Gava ku ez hêj zarok bûm her dem keserek di dilê min de hebû, difikirîm; gelo li pişt van çiyan çi heye? Lê ev kesera xwe her dem min di dilê xwe de veşartibû. Gelek caran ji mezinan bihîstibû ku li pişt van çiyan hinek çiyayên dîtir hene û li pişt wan hinekên dîtir; li pişt wan jî mirov dijîn. Min ew mirov gelek meraq kiribûn. 

….

Lê dem û dewrana dinyayê ez mezin kiribûm; çawa ez ew qas zû mezin bûbûm ez qet pê nehesiyabûm. Lê êdî ez derketibûm pişta çiyayan û l inik mirovên dîtir ewên ku di zaroktiya xwe de min gelek meraq dikirin. Min berê ew mirovên bajarên mezin di hişê xwe de gelek cuda hesibandibûn; min li pêşberî wan ji xwe şerm dikir. Gava ku wan tiştek ji min bipirsiya zimanê min bigirê dihat û ez gelale diaxivîm. Min ew li ber çavên xwe gelek mezin kiribûn û min dixwest ku ez jî wekî wan bim. Min gelekî çavdaniya wan dikir.

Piştî salan min dê tu jî yek ji wan bajarên dûr binasiyayî. Nizanim çawa, lê dê dilê min li ser gezinga evîna te bihata gestin û minê gelek ji te hez kiriba. Lê belê minê tu caran ev yek ji te re negota. Wekî zaroktiya xwe minê tenê keserên xwe ji xwe veşartina û belkî jî ezê li benda demeke ku ez jî nizanim kengî ye rawestima. Rawestiyaneke dûvedirêj a ku dê her roj êşeke dîtir li ser kovanên min binijinta. Lê belkî jî germahiya te, awirên yên geş û kenê te yê şirîn bes bû ji bo min. Ez bi herhal gelekî kêfxweş dibûm. Min her roj ji xwe re duaya, ‘Baş e ku tu heyî’ dikir lê di rastiyê de tiştek nediguherî. Dê rojek bihata û tuyê jî li pêş çavên min mîna kefa sabûnê ji nava destê min bişemitiya û biçûya. A herî dilsoj jî minê nikaribûya tiştek bikira.    

Jixwe her tişt wê rojê eşkere bûbû. Wê roja germ. Ew roja ku ez û tu bêdeng li wê parka veder, li bin sîbera bîşengekê, li rexê birka avê rûniştibûn. Min hes dikir ku dê hinek tişt rûbidin. Ji ber ku wê rojê gotinên te gelekî sist bûn. Min seh dikir ku tu jî dê biçûya. Ev jî dê bûya dawiya jiyana min. Tirs û metirsîneke nediyar ruhê min pêçabû. Ramanên min di nava hev de dihatin û diçûn. Lê min nedikarî te rawestînim jî. Ji ber ku te biryara xwe dabû, erê, tuyê biçûya û ezê jî bi tenê mabûma. 

Hingê îfadeya dudiliyê li ser rûyê te diyar bûbû. Heçko te dixwest gelek tişt bigotina lê van tiştan dê biryara te neguhartiba. Tu wekî pelê li ber weşiyanê bi tayê xwe ve dileqiyayî û piştî demeke kin dê ji darê weşiyayî. Lê ma ew qas hêsan bû çûyîn? Ma ew qas bû her tişt, ku dê bi gotinekê bihata qedandin? Nizanim. Min qet nedizanî ka li ser dilistana te kîjan ba û bager diveziyan. Min qet nedizanî ka di nava hişê te de kîjan hizr û raman hebûn… Lê çûyîna te ya bê wext û bê sedem ji bo min gelekî dijwar bû. Qey dê roja min bêyî dîtina çavên te yên geş dest pê bikira? Qey dê êdî min tu nedîtibûya? 

Hê jî tu bêdeng bûyî û em di ber hev re dimeşiyan ber bi qonaxeke nediyar ve. Tavê êdî bi giranî tîna xwe şikandibû. Bayekî gemore dihat. Ji germa erd disincirî. Meha Tebaxê bû. Li wî bajarê navdar ê ku em gihandibûn hev êvareke dîtir hêdî hêdî xwe berdida ser jîngehê. Em bêdeng dimeşiyan. Carina min dikir li rûyê te binêriya lê te berê xwe nedida min. Tenê te li beriya xwe dinêrî û tevî hizrên kûr hêdî hêdî dimeşiyayî. Heke te li rûyê min binêriya, heke çavên min li nav çavên te biketa minê her tişt fêm bikira. Te jî ev dizanî, lewma jî tu ji min, nemaze ji çavên min ditirsiyayî. Kengî min li nav çavên te binêriya te her dem awirên xwe dişkandin û te di ber xwe de dinêrî. Tu ditirsiyayî ku ez ji te hez bikim lê ji aliyekî ve jî tu ji min bêhtir hewcedarî hezkirinekê bûyî. 

Hingê hemû hestên min ji bo te diherikîn. Lê hestên te belav bûn. Tu, ‘marî gestî ji werîs ditirsiyayî’ û ev tirsa te dibû sedema revaneyê. Tu ji hezkirinê ditirsiyayî û jê direviyayî lê gava ku te li nav çavên min dinêrî jî hestên te yên pêçaftî radiperiyan. Nizanim qey dilê te bi min dişewitî? Lê ev nebû. Ev dê nebûya. Ji ber ku evîn divê ne ji minetê bûya. Ne ji dilşewatiyê bûya. Ne jî em hêlînên revaneyên hev bûna… Na. Divê me hestên xwe ji hev re zelal bikirana… Lê, tu diçûyî. Tu li ser çûyînê bûyî. Minê tu caran ev hestên xwe ji te re venegotina. Belkî te jî nedixwest ku min vegotina. Heye ku ji bo me herduyan jî ya herî durist ev bûya? Kê dizanî… 

Ez gelekî hînî te bûbûm. Dilê min yekem car bû ev qas germ bûbû. Yekem car bû ku min dixwest bawer bikira ku dosteke min hebû. Bila xweşdivî jî nebûya, dostanî jî min diviya. Lê te behsa çûyînê dikir… Tu dê biçûya ji ber ku te hêj nedîtibû ka li pişt çiyayan çi heye. Hêj tu dê lê bigeriyayî. Li pişt çiyan. Hêj jî te dê berê xwe bida asoyên bi mijîn û te dê xopana dilê xwe li ber tîrojka asoyên nû vedaya. Tu dê hê jî li pêjna hundirê xwe bigeriyayî. Lê min ew dîtibû êdî. Êdî ez gihîştibûm pişta çiyayan û min ew raz vedîtibû di kûrahiya çavên te yên reş de. Êdî ez li pişta çiyayan bûm. 

Hingê ez bi gelek tiştan hesiyabûm; bi jiyan, man, viyan û hezkirinê. Ez têgihîştibûm ka ji ber çi mirov ji bo hezkirinekê hin dişewite. Germahî. Wekî şîrê germ ê spêdeyeke hûnik a zozanan. Wekî bayekî hûnik ê kelegerma germistanan. Ji ber ku gava min li çavên te yên geş dinêrî rajena min diperpitî, lerzîn dikete piyê min. Gava ku min li çavên te yên watekûr dinêrî ez tê de winda dibûm û hişê min ji serê min diçû. Gava ku min li çavên te yên reş dinêrî hemû razên li pişt çiyayan li ber min aşîna dibûn û ez diketim nav aramiyeke bêdawî. Min li nik te ji xwe bawer dikir. Min li nik te ji jiyanê hez dikir. Min li nik te ji xwe hez dikir. Min li nik te xem û kulên cîhanê tev ji bîr dikir. Li nik te dem tunebû; saet çawa diherikîn ez pê nedihesiyam. Ji ber ku min ji te hez dikir lê minê ev hestên xwe tu caran ji te re negota. Ji ber ku tu li ser çûyînê bûyî… Tu diçûyî! ... Tu dê biçûya û ezê jî bimirima! …

                                          Êdî min qet meraq nedikir ka li pişt çiyayan çi heye! 

15_Tebax_2004/ Amed', 'Zaroktiyê min gelek meraq dikir ka li pişt çiyan çi heye… Ji nav deman derketibûm, ji nişka ve di navbera xîçikeke zirav a hizr û ramanan de...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hemu-hesten-min-ji-bo-te-diherikin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sevdalanmak', 'sana-sevdalanmak-ali-aldemir-ejuak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vurulmak gibi tutulurca güneşe

Sevdalanırcası bir uzak yıldıza,

Arada bir gelip üstüne göğsünün

Konan esintilere buse misali,

Sevdalanmak gibi sevdalanmak hani,

Kolay iş değil bir çok bilinmeyenli

Çözümsüz denklemdir sana sevdalanmak,

Özlemesi gibi mahkumun yeşili

Ve bir sarımlık son kerelik tütünü,

İşte öyle taaa içten seni özlemek,

Tat vermiyor ki sardıklarım sen diye 

Sevdalanmaksa seninle olmalı ki

Tutulurcasına olsun sevdalanmak,

Unutulmak sende ki gibi olmalı

Ve bir başka güzel sende ki tükenmek.', 'Vurulmak gibi tutulurca güneşe Sevdalanırcası bir uzak yıldıza, Arada bir gelip üstüne göğsünün Konan esintilere buse misali, Sevdalanmak gi...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-sevdalanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınım', 'yarinim-yusuf-koc-3socd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karamsar ve hüzünlü...ama gerçek bu...! 

......................................................................

Öyle çoktular ki,

öyle yoğun..o sonu gelmeyen ümitler..

beyin hücrelerim yetmez diyordum  algılamaya,

bir dönemin kaosu..

bir dönemin baskısı..

ve o hiç terketmeyen aşağılık duygusuna rağmen..! 

Nasıl geçecek bu günler,

umularım nasıl gerçekleşecek..

neler var yarınımda...? 

mutluluk..acılar..surprizler..neler..

hazırdı yüreğim..! 

Her zaman bir koşuşturma..gelecek benim di..! 

hep bekliyordum bir sonraki zamanı..! 

yediveren gibi açılıyordu yüreğimde ümitler..

Ama gel gör ki...şimdi anladım..

günler kısaldı..

....yarınım...yarınlara kaldı..! 

Şimdi yerle bir oldu umularım..arzularım..

savaş yitiren komutan ezikliği var içimde..

zaman kalmadı onları beslemeye,

dil varmıyor..daha sonraya demeye..! 

Korkularım egemen dünyama artık..

geç kalmanın telaşı içindeyim,

ya da erken gelmiş olmanın..

ve önemi kalmadı geçen zamanın..

arzular azaldı..yoklar çoğaldı..

...yarınım..yarınlara kaldı..! !', 'Karamsar ve hüzünlü...ama gerçek bu...!  ...................................................................... Öyle çoktular ki, öyle yoğun...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yarinim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** İçimdeki Ben...', 'i-cimdeki-ben-abir-zaki-xgv8p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“nasıl bağırabilirim 

konuşamazken? 

Ve nasıl durdurabilirim sevmeyi, 

içimde bir kadının tohumu varken? ” * Gaby Brimmer 

yürekli bir ses, 

İçimdeki karanlığa tutulmuş fener; 

kavgasında ışığı çoğaltmanın. 

bir yanım hiç yılmadan; 

çırpınır ortasında, 

umutsuzluk denizinin. 

kucaklar bir yanım direncimi, 

bahşederken oyun müsaadesini. 

ve düzeltip yanlış bildiklerimi, 

saygı gösterir duyarlılığıma. 

sağaltır eski ve yeni yaralarımı; 

tadını çıkarırken ruhumun gizlerinin. 

ve 

saçar ortaya sözcükleri; 

sesime güvenerek, 

aklımdan uçup, gelen. 

…ki hepsi farkındadır gizemlerinin. 

aslolan, mertliğidir onurun; 

gerçekse; bir yansıma. 

yok vaktim ağlayıp, kızmaya; 

umutsuzca saldırırım, 

kucaklamak için yarını; 

ve dikilirim bir başıma 

kalbim arayışındayken efendisinin…

Çeviren: Kadir Deniz    9/9/2004

***************************************************************************************

The Strength Within… 

“How can I scream when I can’t talk? 

How can I stop loving with the seed of a woman inside me…? ” * Gaby Brimmer 

A voice, 

courage within…. 

the lantern into my inner darkness 

struggling to spread the light 

where a part of me, never gives up 

and dismiss the sea of despair… 

A part of me embracing my strengths 

granting the permission to play 

correcting flawed beliefs 

respecting my vulnerabilities 

healing old and current injuries 

savoring the mystery of my spirit 

And 

spilling words on the page 

trusting my voice 

soaring from my mind 

In mystical powers from within... 

For the courage of my honor is truth 

reality is just a reflection 

no time for my sadness or anger 

I desperately seek to rush to embrace the future 

for I stand among all 

while my heart seeks the maker of ME…. 

August 20, 2004', '“nasıl bağırabilirim  konuşamazken?  Ve nasıl durdurabilirim sevmeyi,  içimde bir kadının tohumu varken? ” * Gaby Brimmer  yürekli bir ses, ...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/icimdeki-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portakal', 'portakal-kenan-encin-37tc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman ekşi bir portakal yesem,

nedendir,bilmem aklıma hep sen geliyorsun,

benim,eski sevgilim....', 'Ne zaman ekşi bir portakal yesem, nedendir,bilmem aklıma hep sen geliyorsun, benim,eski sevgilim.......', ARRAY['Türk Edebiyatı','Şiir','Kenan Encin']::text[], 8.5, '{"poet":"Kenan Encin","poet_slug":"kenan-encin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/portakal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaktinden Önce', 'vaktinden-once-i-smet-barlioglu-4jejt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vaktinden önce iner oldu akşamlarım,

Vaktinden önce batar oldu güneşler,

Denizler vaktinden önce çıkar oldu denizliğinden,

Ormanlar ormanlığından,

Tepeler tepeliklerinden,

Sular suluklarından,

Kuşlar kuşluklarından,

Taşlar taşlıklarından, topraklar topraklığından,

Vakti geldiği halde, karasevdam kurtulamadı gitt

Karanlığından.

Uğursuz karanlıklar içindeyim anam-babam,

Kara düşünceler kesmiş yollarımı haramiler misali,

Beyaz kışın neden karakış olduğunu bilen düşünceler,

Çevremde beyazlıkları dökülüyor kara kara kışların,

Alıp yerlerine dikiyorum yaprak yaprak,

Bir ilkbahar gelirse; belki bana dönersin

Sanarak.

Vaktinden önce yaşlandım bir büyük karasevdada,

Elimde-ayağımda takat kalmadı,

Dilimde-damağımda lezzet,

Gözlerimde dökülecek yaş,

Gönlümce acılara dayanacak güç,

Yüreğimde Eyüp Peygamber sabrı kalmadı,

Gözlerim saçlarımın vaktinden önce

Ağardığını gördü,

İnanmadı.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 67-68/100)', 'Vaktinden önce iner oldu akşamlarım, Vaktinden önce batar oldu güneşler, Denizler vaktinden önce çıkar oldu denizliğinden, Ormanlar ormanlığ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vaktinden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdım Tanıyalı', 'tanidim-taniyali-i-smet-barlioglu-9tq3c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayalini bu sabah günün ışıklarıyla sarıp sarmaladım,

Körpe bir sıcaklık yaydım yayabildiğimce yüzüne,

Buharlarla nemlendirdim saçlarını,

Bahar kokularıyla taradım,

Yüreğim eline tutsak düştü bir kere daha,

Kurtaramadım.

Kalbim bir ömür boyudur alışmış tutsaklığına,

Çilelerine, kahırlarına, zulümlerine,

Asmışsın; asılmış, kesmişsin; kesilmiş,

Kırmışsın; kırılmış, vurmuşsun; vurulmuş,

Ne bir tek gün pes etmiş,

Ne yorulmuş.

Hayallerinle eleleyim anam-babam,

Kahrını yumuşatıyorum hayallerinle,

Hayallerin güzel, hayallerin sıcak, hayallerin uysal,

Hayallerin sevecen,

Hayallerin karasevdama sevdalı,

Hayallerin kadar bile merhametli olamadın

Tanıyalı.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 69-70/100)', 'Hayalini bu sabah günün ışıklarıyla sarıp sarmaladım, Körpe bir sıcaklık yaydım yayabildiğimce yüzüne, Buharlarla nemlendirdim saçlarını, Ba...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tanidim-taniyali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Benim Vefasız Aşklarım*', 'benim-vefasiz-asklarim-i-brahim-dikmen-2-dv32x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tövbe ettim, ben aşka,

Sevdikçe çok acı çektim.

Yüreğim ah! parçalandı,

Bir gün olsun, gülemedim.

****************************

Kalbimde hazan rüzgarı,

Hor fırtınalar kopuyor.

Aşık olamam bir daha,

Sevdikçe kalbim ağlıyor.

****************************

Allahım sana değil bu,

Bu haykırış,isyanlarım.

Sevmesini bilmeyen o,

Benim vefasız aşklarım.

****************************

Yemin ettim bir kere,

Sevemem istesemde.

Göz yaşlarım sel oldu,

Nankörleri sevdikçe.

Yüreğim parçalandı,

Namertleri sevdikçe.', 'Tövbe ettim, ben aşka, Sevdikçe çok acı çektim. Yüreğim ah! parçalandı, Bir gün olsun, gülemedim. **************************** Kalbimde haza...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/benim-vefasiz-asklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldıramazsınız', 'yildiramazsiniz-i-smet-barlioglu-f0p5t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldıramazsınız beni çilelerim…

Yıldıramazsınız beni acılarım…

Ayrılıklarım, elemlerim, yıldıramazsınız beni…

Ben Kaf Dağları ‘nı aşıyorum aşkımın eşref saatlerinde,

Vurup vurup ötelerine geçiyorum Gayya Kuyuları ‘nın,

Denizleri aşıyorum çöllerde eskimiş ayaklarımla,

Yaratan ‘a sığınıp sığınıp uçurumlardan atlıyorum,

Karasevdasına düşmüşüm bir elkızının,

Aranıyorum.

Nem alacak acılar, şerbetlenmiş gövdemden? 

Nesini alacak alınmış canımın? 

Yüreğim ateşlerde, ciğerlerim alevlerde,

Adanacağı yere çoktan adanmış turfanda ömrüm,

‘Öl’ Desin iki dudak arasında,

Ölmezsem namerdim; 

Ölürüm.

Yıldıramazsınız beni acılarım…

Ben ızdırabı çivili pabuçlarımda bıraktım,

İğneli fıçılarda bıraktım,

Nişan tahtalarına dönmüşüm bir acımasızın elinde,

Boynum cellat kütüklerinde durup durur,

Ne buyurulur? 

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 71-72/100)', 'Yıldıramazsınız beni çilelerim… Yıldıramazsınız beni acılarım… Ayrılıklarım, elemlerim, yıldıramazsınız beni… Ben Kaf Dağları ‘nı aşıyorum a...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yildiramazsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüketirim', 'tuketirim-i-smet-barlioglu-3kvvt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurubu benzetsem yanlış mıdır

Yaralı yüreğime? 

Çiseleyen yağmuru gözyaşlarıma,

Rüzgarı söz dinlemeyen gönlüme

Ve denizi

Dilime? 

Karasevdana kara kara, sevda sevda tutulmuşum,

Dilimde buruk bir türkü olmuş varlığın,

Etimde, kemiklerimde bir ince sızı,

Canımda dile gelen bir ürperiş.

Sevdan avuçlarımda bir dua olmuş; Tanrı ‘ya yükselen,

Bedenimde de

Canveriş.

Başka hiçbir işim-gücüm yok bu evrende,

Varlığımın başka hiçbir nedeni yok,

Varsa bir önemim; sadece senin indinde var,

Sevenler önemimi

Sevdikçe

Anlayacaklar.

Gözümü açar seni ararım, anam-babam,

Soluk alır seni ararım,

Yürürüm, gezerim, dolaşırım,

Dağları, tepeleri, denizleri, yerleri, gökleri aşarım,

Bakar, görür, seni ararım

Ve her şeyi sana benzetirim,

Bana verilmiş bir ömür var nasıl olsa, senin için.

Tüketirim.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 73-74/100)', 'Gurubu benzetsem yanlış mıdır Yaralı yüreğime?  Çiseleyen yağmuru gözyaşlarıma, Rüzgarı söz dinlemeyen gönlüme Ve denizi Dilime?  Karasevdan...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tuketirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mum Işığı Olsa', 'bir-mum-isigi-olsa-i-smet-barlioglu-knyr9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden gecelerle başlıyor bu hüzünler? 

Neden korunaksız buluyorum kendimi gecelerde? 

Neden kurtuluşu arıyorum hayallerde? 

Hayallerin beni mahvetmeye geliyor

Fermanım

Ellerinde.

Geceler karanlık,

Geceler ıslak,

Geceler üstüme kapanan birer kalın perde,

Geceler içinde hayallerin bekliyor beni

Siperde.

Hayallerin zemzemde yıkanmış; duru, beyaz,

Hayallerin gerçeğinden genç,

Gerçeğinden güzel,

Her hayalinle bir anımız cana gelip durmakta,

Hayallerin bana ne kadar yakınsa; 

Gerçeklerin

Bir o kadar

Uzakta.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 75-76/100)', 'Neden gecelerle başlıyor bu hüzünler?  Neden korunaksız buluyorum kendimi gecelerde?  Neden kurtuluşu arıyorum hayallerde?  Hayallerin beni ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-mum-isigi-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olup Gitmesen de', 'var-olup-gitmesen-de-i-smet-barlioglu-c1wl8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek; tefekkür etmek gibi bir şey,

Toprağı sevmek,

Suyu sevmek,

Havayı sevmek,

Enginlere açılıp geri gelememek gibi bir şey,

Boğulacağını bile bile okyanusa açılmak

Ve ormana dalabilmek gibi, dönemeyeceğini bile bile,

Onun için, mum yerine

Zamanı koyup duruyorum

Kandile.

Bir ömür boyu mumlar gibi eritip tükettim zamanı,

Bir ömür boyu enginlere açıldım, açıldım, dönemedim,

Onun için gerilerde bıraktım bedenimi düşüncelerimden,

Yüreğimi bir armağan gibi sana sunmak üzere

İçerimden.

Var olduğumu anlıyorum seni düşündükçe,

Güneş var oluyor,

Toprak var oluyor,

Su var oluyor,

Gündüzler ve denizler,

Geceler ve yıldızlar var oluyor,

Var var oluyor evrenim enginliğince,

Ay bile böylesine var olamaz

Sevilmeyince.

Varlığına yol açtığı için varlığıma şükrolsun…

Şükrolsun sana yönelik düşüncelerime…

Seni düşünerek geçen ömrüme…

Ömrümün bu kadarına şükrolsun…

Daha da ömrüm varsa; yine yaşarsın benimle, anam-babam,

Yine var olursun bende,

Bir büyük karasevda içinde var olup

Gitmesen de.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 77-78/100)', 'Seni düşünmek; tefekkür etmek gibi bir şey, Toprağı sevmek, Suyu sevmek, Havayı sevmek, Enginlere açılıp geri gelememek gibi bir şey, Boğula...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/var-olup-gitmesen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avunamam', 'avunamam-i-smet-barlioglu-35yuj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden bana yıldızlar kadar uzaksın? 

Ve neden bana nabzımdan daha yakın? 

Nasıl bir büyüsün ki; uzaklarımı yakın kılıyorsun

Ve yakınlarımı taşıyorsun en uzaklarıma? 

Nasıl bir büyüsün ki; 

Bazen taşıyorsun beni geçmişe,

Bazen

Yarına.

Dünle yarın arasında sıkışan bugünlerimde kalmışım,

Düne dönemiyor, yarına ulaşamıyorum,

Ellerim düşüncelerimin şakaklarında,

Dünle yarın arasında ayaklarım,

Yüreğimde bitmişliklerin yorgunlukları,

Saçlarımda eriyip gitmişliğim,

Bir büyük karasevdada geçerliğini yitirmiş

Kimliğim.

Eşini-benzerini görmediğim bir telaşla,

Seni arıyorum canla-başla

Tıpkı saman yığınında iğne arar gibi

Yahut su içinde bir cam parçasını ararcasına,

Aradıkça arıyorum,

Bana bir yardım eli uzatsana anam-babam,

Bulamıyorum.

Belli ki; hayallerin olacak tek avuntum,

‘Otur’ Deyince oturan, ‘Kalk’ deyince kalkan,

Bazen güneş altındaki durgun bir deniz gibi,

Bazen yaylada yükselen duman.

Ne yazık ki; hayallerin sen değilsin,

Avunamam.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 79-80/100)', 'Neden bana yıldızlar kadar uzaksın?  Ve neden bana nabzımdan daha yakın?  Nasıl bir büyüsün ki; uzaklarımı yakın kılıyorsun Ve yakınlarımı t...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/avunamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı araba öldü / şaraba hasretinden', 'kirmizi-araba-oldu-saraba-hasretinden-zafer-zengin-etnika-ow5ib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kahrolası sarhoşluğun

Şaraba hasreti

İrkilip irkilip

Öpüyor tanrıları

Değişim başladı

Haşlanan kırıntılar

Doyurmayacak çocukları

Anlatmalı elbet

Kıvrılan yollara

Ormanların ızdırabı

Kafası kopmuş kozalaklar

Yangınlar da kültür 

Su değene dikensi kabukta

Anlatmalı / leylekler terk etti meydan taşlarını

Kim ölebilir

Sigarayı

Erken bitiren

Çocuktan erken

Terör esnedi

Taranmamış saça

Kan gelince ki gülmeyeninden

Kirpiğin kavuşması bitti

Ve hiç kapak olmadı

Çelik levhadan

Koca şehir tele bağlanıp

Binlerin içine sarkıtıldı

Herkes aldı

Çalan durmadı kaçtı

Kırmızı araba kaldırımda kaldı

Kim ölebilir

Sigarayı

Erken bitiren

Çocuktan erken

Erken bırakan çocuk ordaydı

O farkına vardı

Lacivertler yalnızdı

Martılar kurumuş kaburga kadar cansız

Kap taşıyan adam saygısız

Yakın yerde indi 

Köprü çarptı ayaklarına

Çorabını çıkarmamıştı daha

Üzülen yaşlı kadın

Çarpmasın diye bisikletlilere araba

Slalom yaptı

Olacaktı

Herkes bilecekti 

Olmadı

Kurtuldu yayğara

Metal çocuklar döndü

Kadın yaşlıydıya

içmeden  ölmedi

tansiyona muhtaçmış

ona inat kaçarken anlamış

çocuklar kansız olmazmış

laf ebesi sobelendi

oyun bitti

zaten geceydi

çocuklar gece görmezdi

Kim ölebilir

Sigarayı

Erken bitiren

Çocuktan erken

Büyüdüler ya

midesine et girmeli

kahraman yaşına gelen

sancılı büyüyen

büyüdüğünü bilmeyen

hep hüzünlü şarkılar söyleyen

sigarayı sevmeyen

sadece kadın

sadece erkek diyen

şehri kana bulayıp

özür dileyen

kabadayılar değil dikkat

külhanbeyi ayrılık var

drama yapıp orta oyununda

çekildiler sağa sola

oyun bitti

her güzel gibi şiir öldü

satılık

birkaç dize 

ekmek arası hece

olmadı

huzur eve lazım erken büyüyene ne lazım

gidelim

gitmesine de

sevenlerine ne demeli / şehir yandı

öldü deriz

ezberlenen

hissedilmeyen her şarkı

biraz ölüm almaz mı

ozan bulalım

kalabalıklara karışıp

kitapçıları basıp

kültür yuvalarına satalım paraları

oraya başka yalnızlık alamazlardı

biz vardık / bekledik o gelmedi

şimdi de bakayım çoban

tanrı kaval çalar mı

şu keman zehrinden bizi kurtarsa da

afrika işi yağmurlar yağdırsa

deri kaplı bambu çubukla

basit anlatıyorum

okumayı biliyorsun

anlamayı bilmiyorsun

daha mı yavaş

üç gül yaşında

renk kadar karıştın kanıma

bundan gurup kurduk

sarhoş edip acıları

kraker arası paylaştık

yanlıştık ahh yanmıştık

anladın mı 

niye açtık

apaçıktık

niye ağladık

Kim ölebilir

Sigarayı

Erken bitiren

Çocuktan erken

ders başladı arkadaşlar

gülmek öğretilecekmiş satırlara

jerry lewis önce sen başla

dean martin sen ağla

karıştırın biraz suyla

mutlu görünün karşımızda

ama olmuyor

localar boş

ders bitti

gidin koltukları kirletmeyin

gözyaşınızın saflığıyla

tek onlar kaldı

küfre saklanmış sıcak dostluklarda

anlayan anladı

can baba niye vardı

ve niye vardı deniz

neden hep biz

sen ve ikimiz

sadist / canlı balık yakalar ölü denizden

biliyorum üstünde  uçana

yavrusunu kurban eden

dibin var biraz karanlığın

lacivertlerin ve yalnızlığın

| martı kedi peşinde

bir yerden düştü işte

şiirin içine |

öğretmenim siz bilirsiniz

gülmek ölmekten ayıp mı

Gülen tarla kuşlarının ardı sıra

Sevmeyi bilen çocuktan başka

Bir de kırmızı araba

Kim ölebilir

Sigarayı

Erken bitiren

Çocuktan erken

Ep erken

Gün doğmamışken

kırmızı araba ölüyor şimdi...

10.09.2004-09-11', 'Kahrolası sarhoşluğun Şaraba hasreti İrkilip irkilip Öpüyor tanrıları Değişim başladı Haşlanan kırıntılar Doyurmayacak çocukları Anlatmalı e...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/kirmizi-araba-oldu-saraba-hasretinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu yox yollar', 'sonu-yox-yollar-ahmet-hani-9dxoq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarixin çoxdur Alçaq insanı

çürüdük onların quluğunda biz

gel gedek yox olaq gözel bayquşum

sonu yox yolların buruğunda biz.

buludlar doğurlar damcı damcı qem

denizde boğazdı yoldadı matem

azadlıq olmasa yox olsun alem

sonu yox yolların buruğunda biz

çürüdük Tarixin quluğunda biz.

23   december  1995', 'Tarixin çoxdur Alçaq insanı çürüdük onların quluğunda biz gel gedek yox olaq gözel bayquşum sonu yox yolların buruğunda biz. buludlar doğurl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonu-yox-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yazıyorum II', 'seni-yaziyorum-ii-ali-haydar-yurtsever-o83gu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni yazıyorum; 

Ellerimde senden kalma sıcaklık,

Kulaklarımda söylediklerin,

Yüreğimde yokluğundan kalma bir sancı, 

Gözlerimde gidişinin hüznü var.

Odamda yokluğunla savaşıyorum.

Sessizlik işlemiş konuşkanlığıma.

Derken bir cinayet bölüyor sessizliği,

Durgun yüreğime kalemimi saplıyorum,

Durgun yüreğim kanıyor damla damla.

Her damlada daha fazla acıyor, 

Her damlada daha fazla susuyorum, 

Ve ben geceye savrulan her damlada seni yazıyorum.

Seni yazıyorum; 

Serin bir Eylül akşamında, 

Seni tanıdığım akşamda ki gibi hava,

Ama bu sefer kendi şehrimdeyim.

Sokaklar avaz avaz bağırıyor karanlığa,

Karanlık çoktan esir düşmüş,

Adım başı yanan lambalara. 

Bir ben kaldım, 

Bir de karaya bürünmüş yüreğimdeki umutlar, 

Meydan okuyan şehrin ışıklarına. 

Ve o aynı ben, 

Kalemimi boğup fosfora, 

Seni yazıyorum yüreğimin karanlığına.

Seni yazıyorum; 

Senli zamanlar geliyor aklıma: 

Gülmesi gözbebeklerinin,

Anlığına başının omzuma düşmesi,

Kollarıma emanet sıcaklığın,

Dizlerimdeki ağırlığın, 

Dizlerindeki uyuklamalarım,

Ve yaptığım çılgınlıklar… 

Ne karanlık getiriyor bunları aklıma, 

Ne de yalnızlık eseri gece esiri sessizlik.

Tek suçlu sensizlik.

Ben sensizliğinde seni anıyorum, 

Ve ne kadar bilmesen de

Ben senden kalan sensizliğine seni yazıyorum.

Seni yazıyorum; 

Yavaş yavaş geceye dönüyor gün.

Korna seslerini çiğneyen birkaç martı duyuyorum,

Balkon bakışı.

Gün geceye dönüyor,

Ben geceye.

Geceye dönüyorum kâğıtsız kalemsiz.

Yatarken yazmıyorum sanma, 

Sadece onlara ihtiyaç duymuyorum

Çünkü ben uykumda

Seni rüyalarıma yazıyorum.', 'Seni yazıyorum;  Ellerimde senden kalma sıcaklık, Kulaklarımda söylediklerin, Yüreğimde yokluğundan kalma bir sancı,  Gözlerimde gidişinin h...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Yurtsever']::text[], 8.5, '{"poet":"Ali Haydar Yurtsever","poet_slug":"ali-haydar-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/seni-yaziyorum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolaylı Anlatım', 'dolayli-anlatim-akin-tekin-phitn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni sevme diyorsun

Yemek yeme

Su içme

Nefes alma

demek gibi bir şey bu

Öl desene', 'Beni sevme diyorsun Yemek yeme Su içme Nefes alma demek gibi bir şey bu Öl desene...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dolayli-anlatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik', 'caresizlik-erdem-yalcin-t8j3v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O ansızın bırakıp gidişin var ya

Bir sis gibi sardı ruhumu sensizlik

Yaşama dair hiçbir şey kalmadı

Yüreğimde ölüm gibi bir sessizlik

Bir anda yıkıldı sanki dünyam

İçimde kaldı sonsuz bir ümitsizlik

Tat vermiyor artık yaşanan zaman

Senden bana kalan derin bir çaresizlik', 'O ansızın bırakıp gidişin var ya Bir sis gibi sardı ruhumu sensizlik Yaşama dair hiçbir şey kalmadı Yüreğimde ölüm gibi bir sessizlik Bir an...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/caresizlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğsümde Kazılı Adın', 'gogsumde-kazili-adin-esin-ege-op5i9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sensizlik biçildi bana

Birde biçilecek sensiz ölümümde kefenim 

Hangisi reva bana anlamadım yaşarken 

Ne göğün kırılgan mavisinde kuş olmak istedim

Nede mavi derin okyanuslarda yunus balığı 

Uçuk kaçık heveslerimde olmadı hayattan

Senden  öte ne diledim ki yaşarken 

Yalnızlık  yüreğimin en kadim dostu

Her gün kaç kere kesiyorum hesabımı bilsen 

Her defasında gözlerin geliyor aklıma

Dur diyorum deli olma 

Onları bir daha görememek korkusu

Kör bir bıçak gibi saplanıyor yüreğime

Bu sana gelme telaşı var ya

Alıp götürüyor beni dipsiz kuyulara

Deli gibi sarmalıyor bedenimi

Acı çekiyorum ama uslanmıyorum yinede

Adını göğsüme kazıyorum kan damlıyor ciğerime

Günah diyorlar gülüyorum

En büyük günah sensizlik değilmi yaşadığım 

Hiçbir yeis yok içimde senden yana

Sadece bekliyorum geleceğin günü

Geleceksin biliyorum belki çok geç olacak 

Ama bu ihtimal yaşatıyor beni,sen  bilmiyorsun

Anlayacaksın birgün bu deli kızın yüreğini

Kendi utancın getirecek seni bana

Hiç şüphem yok geleceksin

Bu her şeye engelli mahrumiyetim bitecek

Yalnızlığıma gireceksin birden

Merhaba diyeceksin geçmişten bugüne 

Adını göreceksin kazılı göğsümde

Bir bir anlatacağım sensiz günlerimdeki feryatlarımı

Hergün bin kere öldüm ama gömmediler beni diyeceğim

İçin acıyacak bilirim seni 

Islak dudaklarınla öpeceksin

Sakın ağlama sevgili, zaman gülmek zamanı

Ağlarsan işte sonum olur o zaman 

Biçilen kefeni giydirirler bedenime

Gel ki bitsin sensizliğin acıları

Yeterki gel', 'Bir sensizlik biçildi bana Birde biçilecek sensiz ölümümde kefenim  Hangisi reva bana anlamadım yaşarken  Ne göğün kırılgan mavisinde kuş ol...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gogsumde-kazili-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir...', 'kimbilir-erdem-yalcin-q884d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim bilir bir gün hiç ummadığın bir zamanda

Unutuldu bu aşk dediğin bir  anda

Beni bulacaksın karşında

Belki yıllardır özlemini çektiğim

Hasretle beklediğim senmiydin diyeceksin

Ve dönüp arkanı gideceksin hayal kırıklığıyla

Ne yazık bunca yıl boşa geçmiş diyecek

Kederlerle geçen zamana üzüleceksin..

Kim bilir belki sevinçle atılacaksın kollarıma

Belki yılların özlemi taşacak içimizden

Yaşlar süzülecek gözlerimizden 

Çılgınca  sarılacağız  birbirimize 

Ve doyasıya ağlayacağız ayrı geçen günlerimize

Ben her şeye  razıyım bitanem 

Yeter ki o anı yaşamak nasip etsin Yüce  Tanrım bize......', 'Kim bilir bir gün hiç ummadığın bir zamanda Unutuldu bu aşk dediğin bir  anda Beni bulacaksın karşında Belki yıllardır özlemini çektiğim Has...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimbilir-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu yaşayan el, şimdi sıcak ve yetkin', 'bu-yasayan-el-simdi-sicak-ve-yetkin-john-keats-dc7wl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yaşayan el, şimdi sıcak ve yetkin,

istekle kavrayan; eğer soğusaydı,

mezarların buzdan sessizliğinde,

öyle ruhların uğrağı günlerin ve

ürperten düş gecelerin. Kuruyan

kanı kalbinin arzulardı, tekrar 

akmayı damarlarında kızıl ve

vicdanın - durgun - görür buradır.

Durduğum sana doğru.

Çeviren; Gökhan OFLAZOĞLU.', 'Bu yaşayan el, şimdi sıcak ve yetkin, istekle kavrayan; eğer soğusaydı, mezarların buzdan sessizliğinde, öyle ruhların uğrağı günlerin ve ür...', ARRAY['Türk Edebiyatı','Şiir','John Keats']::text[], 8.5, '{"poet":"John Keats","poet_slug":"john-keats","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-yasayan-el-simdi-sicak-ve-yetkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı araba/çalıntı', 'kirmizi-araba-calinti-zafer-zengin-etnika-q9ra4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyutan /

Şarkılar beğen

Kanatlısından

Martı kanadına takılan

İçimizi uyutan

Bayıltan ağlatan

/Demiştik

keman sesi kanser ediyor acemi adamı

insan bağışıklık kazanır mı..  mavi hayat yorar mı /

Türkü /

Bağlama telinde

Türkü sözü 

Sür ellerimi

Bugün Cumartesi

Kim bilir

Nerede ne haberler gizli

İzli mermilerim bile kalmadı şimdi

Kış /

Aşk sürgün yeri

Kış gelmeden

Eldiven elbise dikmeli

Gözlerinden de edinmeli

Bıyık /

Yarım bıyık yüzüm

Yolmaktan

Yorulmaktan

Saçlarım da kısaldı

Gönlümün ayıbı

Çalıntı /

Anlatmasan çatlayacağım

Kırmızı araba çalıntı çıktı

Renk muayenesinde anlaşıldı

kanı tutmadı

10.09.2004', 'Uyutan / Şarkılar beğen Kanatlısından Martı kanadına takılan İçimizi uyutan Bayıltan ağlatan /Demiştik keman sesi kanser ediyor acemi adamı ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kirmizi-araba-calinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur beni', 'vur-beni-erdem-yalcin-vhb98', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün düşüp sevda yollarına 

Varsam sevdiğim kapına

Çalsam kalan dermanımla

Kapını açarmısın? 

Seviyorum seni desem 

Tüm kalbimi önüne sersem

Varlığım senin desem 

Kabul edermisin? 

Ret edersen sevgimi

Senle yanan şu gönlümü

Durdur artık hasretimi 

Desem ki Çek silahı vur beni 

Bu dileği red edermisin...?', 'Bir gün düşüp sevda yollarına  Varsam sevdiğim kapına Çalsam kalan dermanımla Kapını açarmısın?  Seviyorum seni desem  Tüm kalbimi önüne ser...', ARRAY['Türk Edebiyatı','Şiir','Erdem Yalçın']::text[], 8.5, '{"poet":"Erdem Yalçın","poet_slug":"erdem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vur-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlü Çocuk', 'gul-yuzlu-cocuk-orkun-isik-4lgk4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırılır kalem yırtılır artık sayfalar

Hep düşlerinde bir çocuk ağlar

Yitirilmiş okyanusların ortasında

Terk etmez mi gemiyi! o tayfalar

Gül yüzlü çocuk ne zaman gülecek

Ne zaman doğdu ki ne zaman ölecek

Bir düş boyudur yükselirken güneş

Ah! kim bilir kaç kandili sönecek', 'Kırılır kalem yırtılır artık sayfalar Hep düşlerinde bir çocuk ağlar Yitirilmiş okyanusların ortasında Terk etmez mi gemiyi! o tayfalar Gül ...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-yuzlu-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim', 'ben-kimim-talip-kaplan-tfeh6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilse de

Pek çok kimse ismimi

Görseler de

O düşünceli çehremi

Deseler ki; 

İyi tanırız seni

Genede anlayamazlar

İçimde sakladığım beni

Kendime has kişiliğimi.

Bir soruyum ben

Saçma sapan

Yanıtı olmayan

X şıkkında yer alan

Anlamsız bir problemim

Ben benim...

(03 Ağustos 1992)', 'Bilse de Pek çok kimse ismimi Görseler de O düşünceli çehremi Deseler ki;  İyi tanırız seni Genede anlayamazlar İçimde sakladığım beni Kendi...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-kimim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dualar Yerini Buldu Can Dostlar...', 'dualar-yerini-buldu-can-dostlar-i-brahim-ethem-bingul-bs2bl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şükrün sonu gelmez güzelliğinden

Yaradan''a şükrederim gönülden

Mülkün sahibinin kudret elinden

Sağlık bulup zinde olmak ne güzel...

Şefkat nazarından serinlik bulmak

Bağışından canda esenlik bulmak

Sende sağlık görmek ve şenlik bulmak

Seni sevmek, sende durmak ne güzel

Hasta olsan sinemde ateş yanar,

Sen şifa bul, sen şifa sun ey güzel

Dualar yerini buldu can dostlar...', 'Şükrün sonu gelmez güzelliğinden Yaradan''a şükrederim gönülden Mülkün sahibinin kudret elinden Sağlık bulup zinde olmak ne güzel... Şefkat n...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dualar-yerini-buldu-can-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahişem', 'fahisem-i-smail-sahin-pnoum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kalk o beyaz çarşaflardan

o çarşaflar ki kefenim

bir şeyler söyle fahişem

duymadığım lügatlardan

çek gecenin perdesini

açılmayan penceremden

ne isterler yüreğimden

bilmeyenler sevmesini

bir şeyler al üzerine

otur sadece karşıma

fahişecik söyle bana

herşey güzel olacak de', 'kalk o beyaz çarşaflardan o çarşaflar ki kefenim bir şeyler söyle fahişem duymadığım lügatlardan çek gecenin perdesini açılmayan penceremden...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fahisem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Seninle Sevgilim', 'biz-seninle-sevgilim-i-smail-sahin-wifz9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir bilmecenin cevabı gibi 

geleceğim aklına bir gün

anılara soracaksın sevgilim

göremediğin kimliğimi

kimdi toprağımda bu sürgün

neresindeydim bu gönlün

bulacaksın hüzünbaz sevgilim

bulacaksın senliğimi

adanmışlığını sana bir ömrümün

geçmiş olacağız yollardan

biz seninle iki mutsuz

biz seninle sevgilim

mutluluğu soracaksın yıllardan

birbirimize çıkacağız

biz seninle sevgilim

biz seninle...', 'bir bilmecenin cevabı gibi  geleceğim aklına bir gün anılara soracaksın sevgilim göremediğin kimliğimi kimdi toprağımda bu sürgün neresindey...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biz-seninle-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünde hissettiğin kış rüzgarı', 'yuzunde-hissettigin-kis-ruzgari-john-keats-8cea9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzünde hissettiğin kış rüzgarı,

gördüğün kar bulutları karaltılar

arasında ve donan yıldızlar

karaağaçların doruklarında.

Bahar olacak hasat zamanı

ve sen bu kez ışıkla; seni

besleyen yüce karanlık,

geceler sonra Phoebus uzakta,

bahar üç kez sabah sana,

üzgün değil hiç, bildikten sonra

ve şarkım gelir doğal ılıklığıyla,

üzgün değil hiç, bildikten sonra

ve akşam dinler. Üzülür, boşluk

düşüncesiyle; boş olamaz; 

Uyanık, düşünür ki uykuda.

Çeviren; Gökhan OFLAZOĞLU.', 'Yüzünde hissettiğin kış rüzgarı, gördüğün kar bulutları karaltılar arasında ve donan yıldızlar karaağaçların doruklarında. Bahar olacak hasa...', ARRAY['Türk Edebiyatı','Şiir','John Keats']::text[], 8.5, '{"poet":"John Keats","poet_slug":"john-keats","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuzunde-hissettigin-kis-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Işıklar Söner', 'i-cimdeki-isiklar-soner-kamil-aydemir-bvvvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen öğrettin bana

evliliğin yüreğe vurulan zincir

evliliğin yüreğe vurulan kelepçe 

ve arzuların işkencede olduğunu

yanlış evliliklerde insanın boğulduğunu

kocaman vazolarda da çiçeklerin solduğunu

ben de öğreteceğim sana

sevgi kırar kelepçeyi zinciri

sevgi özgürlerştirir insanı

gökyüzündeki kuşlar gibi

ne olursun ayrılığı öğretme

bu sevdayı bana ağu etme

kulak ver gönlümün sesine

adım adım yaklaştıkça sana

yüreğim sığmıyor sol yanımdaki kafesine

bırakmam bu sevdayı hayatın kanlı dişlerine

tepeden tırnağa terleyen bedenim mi

                  dokundukça nefesine

yaralarımın iyileşmesi mi

            yatrıdıkça bal gülüşlerine

çocuksu saflığın 

yüreğinin raflarında tozlanan güzelliklerin mi

hazran’ım olan kadınlığın 

hüzünlerde bıraktığın kanatların mı

sevdamın günlüğünü yazmak istediğim dudakların mı

nedir beni sana akıtan böylesine

hangi gizemindi

bana memleketimi bile unutturan

zulalarımda mutlu yarınlar

ben aşkla koşarken sana

sen misin hâlâ yerinde oturan

seveciğim inadına

hüzün olsa da 

bu aşktan bana kalan

soğukluğunu bilirim

ben ölümü çok öptüm

buğulu gözlerinde zemheriden çıkar vucütüm

yarımdım

çünkü o zaman seni bulmamıştım

ama ben zaten aydınlanmıştım

keşke bedenime değilde

elektriği olmayan evlere verseydiler onca ceriyanı

aşkından kavgasndan ne koparabilir ki insanı

şafakları kanayan memeketimde

eylül saraylarından eğilmeden geçtim

bundandır eylül’lerde kanamam

bundandır koynuna mülteci olmam için

gecenin bir yerinde seni yanımda aramam

aşkım uğruna

senin işkencelerine de direnirim

nasırlı elimde beyaz bir gül

yüreğinin kapısına hep sevgimle varırım

ve bilirim

terk etmemişse seniinsanlığın

sevgimin karşısında çözülür yüreğin

varsın payıma acı düşsun

örseleme bu sevda bende büyüsün

istemem alnında aşka kıymışlığın karası

yüreğimde acımasızlığın yarası

nasıl iyileştireceğim kendimi

mapusluğu tanırım

yurtsuzluğu 

alnımda sürgünlüğün günlüğü

en berbatı sensizlik

nice ölümlerin kıyısından geçtim

senden gelen acıları da katık yaparım yavan hayatıma

yüreğide bir ucu boşta sevda

canın sağ olsun bu sevdanın boştaki ucunu tumasanda

bilirim

insan korktukça kaybeder

gözlerine her varışımda

benimle mutluluk şarkıları söylemek için

gagalarında karanfil

umut yüklü martlar yüreğime döner

kirlendikçe insan azaldı sevdaya yakışan

olmayalım diye çocukların gözyaşlarında perişan

güzel günler için dövüşen

bu ası yürek seni

senden gelen kurşunu bile

gül niyetine alacak kadar

u m m a n   s e v e r

sensiz bırakma beni

içimedki ışıklar söner', 'sen öğrettin bana evliliğin yüreğe vurulan zincir evliliğin yüreğe vurulan kelepçe  ve arzuların işkencede olduğunu yanlış evliliklerde insa...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/icimdeki-isiklar-soner-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehir Göl Oldu', 'nehir-gol-oldu-i-smail-sahin-5jb8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşerim sevdanın kollarına

düşer gibi umutsuzluğa

başım dönüyor sevgilim başım

gömülüyorum Seyhan suyuna

dursaydın uzakta gelmeseydin

sen yaklaştıkça artıyor yaşım

artıyor sevgilim uzaklığın

koşturamam artık savaşlarda

meydanlarında kaldı naaşım

yorgunum sevgili yorgunum

Alp Er Tunga gibi barakamda

bitip yitmişim, dibe vurmuşum

korkuyorum sana yaklaşmaya

kaçışım bundandır, kaçıyorum', 'düşerim sevdanın kollarına düşer gibi umutsuzluğa başım dönüyor sevgilim başım gömülüyorum Seyhan suyuna dursaydın uzakta gelmeseydin sen ya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nehir-gol-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi ört', 'yuregimi-ort-zafer-zengin-etnika-ugao7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlişme 

usta

Can

sağlığıyla

Öleyim

şurada

Nasıl

yorgunum

İhtiyacım

var

uykuya

Taş

biraz 

sıcak

olsa

Uyanmam

bir

daha

| Yaz

çok mu

uzakta |

Titrersem

soğukta

Gözlerimi

ört

önce

usta

Yüreğime

dokunma

Anlatma

ona

Sustuğumu

usta

Su

yok mu

Acıyor

içim

usta

Titrersem

yüzümü

ört

önce

Görmesin

Kimin

yüreği 

daha 

ince

11.09.2004', 'İlişme  usta Can sağlığıyla Öleyim şurada Nasıl yorgunum İhtiyacım var uykuya Taş biraz  sıcak olsa Uyanmam bir daha | Yaz çok mu uzakta | T...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yuregimi-ort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gibi', 'senin-gibi-i-zzet-ertem-0retg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pencereden bakınca,

Karşım da görünür sıradağla,.

Bir gelin gibi süt beyaz gelincik giyinmiş,

Seni aracasına ta uzaklara baktım

Fakat şu güzelim dağlar,

Seni hatırlatıyor bana.

O süt beyaz örtülü dağlarda 

Dalga dalda karanlıklar var ya 

Tıpkı senin o simsiyah saçların gibi,

Esen rüzğarda dalgalanan,

O güzelim saçların gibi,

Kıvrım kıvrım, dalga dalga oluyor.

Bak güzelim! Mapushanenin 

Ufacık penceresinden

O sıra dağları görünce

Hep seni hatırlıyorum...

O beyaz dağlar, bilir misin  bana

Neyi hatırlatıyor güzelim? 

Dedem Korkut’un masallarında

O güzel mısraları hatırladın mı güzelim,

Süt beyaz gelinlik giymiş,

Bir güzel ki tıpkı senin gibi,

Çiçekli kırlarda koşuyor,

Sevgilisinin kollarına atılmak için,

Esen rüzğar da saçları dalgalanıyor,

Mutluluk çığlığı atarak,

İşte o güzelim dağlarda,

Kıvrılan dalgalıklar bana seni hatırlatır.

Mapushanenin ufacık penceresinden,

Dağlara baktıkça seni hatırlıyorum,

Ve hep seni hatırlayacağım...

12.01.1973

Elazığ', 'Pencereden bakınca, Karşım da görünür sıradağla,. Bir gelin gibi süt beyaz gelincik giyinmiş, Seni aracasına ta uzaklara baktım Fakat şu güz...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ertem']::text[], 8.5, '{"poet":"İzzet Ertem","poet_slug":"i-zzet-ertem","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/senin-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm', 'sozum-i-zzet-ertem-7nqa8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kere yükselen bayrak,

bir daha inmez.

yüz milyon Türk esirken,

insan olanın yüzü bile gülmez..', 'Bir kere yükselen bayrak, bir daha inmez. yüz milyon Türk esirken, insan olanın yüzü bile gülmez.....', ARRAY['Türk Edebiyatı','Şiir','İzzet Ertem']::text[], 8.5, '{"poet":"İzzet Ertem","poet_slug":"i-zzet-ertem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezdirir...', 'gezdirir-i-zzet-ertem-i0wq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın uğruna zehir içesim gelir,

Tımarhaneyi yakıp kül edesim gelir,

Hasret oldum sana güzelim, hep göresim gelir,

Aşkın beni tımarhane tımarhane gezdirir...

Bir deli sevmiş aleme zor gelir,

Hiç çıkmaz aklımdan gece rüyama gelir,

Yarin aşkı beni mum gibi yakıp eritir,

Aşkın beni tımarhane tımarhane gezdirir...

Sevdan beni yakar, hayatımdan bezdirir,

Derdin beni güldürmez, öldürür,

Kara sevdan genç ömrünü soldurur,

Aşkın beni tımarhane tımarhane gezdirir...

18.01.1983

Elazığ', 'Aşkın uğruna zehir içesim gelir, Tımarhaneyi yakıp kül edesim gelir, Hasret oldum sana güzelim, hep göresim gelir, Aşkın beni tımarhane tıma...', ARRAY['Türk Edebiyatı','Şiir','İzzet Ertem']::text[], 8.5, '{"poet":"İzzet Ertem","poet_slug":"i-zzet-ertem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gezdirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Ne Mümkün..!', 'ne-mumkun-hasan-basri-kale-8hmgn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülen yüzüne bakıp hayran  olmamak  ne mümkün

sensiz bu âlemde mutluluktan bir zerre  ne mümkün

varlığın yeter,bakışın oynatır dünyamı yerinden 

seninle geçen bir âna,ömür dememek ne mümkün...! 

*sağlıkla geçecek çok uzun ömründe yakınlarında bir yerlerde olmak ümidiyle..!', 'gülen yüzüne bakıp hayran  olmamak  ne mümkün sensiz bu âlemde mutluluktan bir zerre  ne mümkün varlığın yeter,bakışın oynatır dünyamı yerin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-mumkun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimi İnsanlar', 'kimi-i-nsanlar-mehmet-selim-togluk-08ulo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne garip, yaşamak şu yer yüzünde

Kimi bir yar için canını verir

Kimi gider başkasının izinde

Kimi sevda için dağlar devirir

Kimi sonsuzluğa bir yelken açar

Kimi başka limana yükünü alır

Kimi çevresine mutluluk saçar

Kimi insanlara hep azap verir

Kimi aşkı için yarışa girer

Kimisi kendinden hep ödün verir

Kimi merdiven çıkar birer birer

Kimi üçer beşer atlayıverir

Kimi şarkılarla, sözle avunur

Kimi yarışmayla şarkıcı olur

Kimi bir şiirde teselli bulur

Kimi şairlere düşman kesilir

Kimi insanlıktan nasibin almaz

Fakat insanlara baştacı olur

İşte hayatın acı gerçeği budur

Kimi zindanlarda çürüyüverir

		(Batman - 08.09.2004)', 'Ne garip, yaşamak şu yer yüzünde Kimi bir yar için canını verir Kimi gider başkasının izinde Kimi sevda için dağlar devirir Kimi sonsuzluğa ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kimi-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''lün Onikisi', 'eylul-lun-onikisi-i-nan-alver-5310c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eylül''de hep fırtınalar yaşarım,

Serçe kadar ürkek Seni Seviyorum deyişini hep aklımda tutarım,

Dudakların arasından süzülüp,

Kalbime dolan sevgini hep içimde saklarım.

Biliyormusun,yangınsın hala kalbimde,

Başkaldırdım sensiz geçen günlere,

Ayrılıklara,yıllara inat! 

Eylül''lün onikisini yaşarım içimde,

Bir gün düşermi sevgim, seninde aklına,

Bir Ah! çekip, hasret çekermisin geçen yıllara

Gene seni seviyorum dermisin? 

Eylül''de kalan bakışlarınla.

Çocuktuk belkide,sevgimizde çocukca,

Bedenlerimiz büyüdü,ruhumuz hala o yıllarda,

Bir bakışla,bir gülüşle,iki kelimeyle,

Eylül''de gene sevmeliyiz çocukca.

Bir sevgi bıraktın ya,kalbimde

Hala saklarım en derinde,

Yenilmedi mevsimlere,yıllara,

Sevginle,sensizim bu Eylül''de', 'Eylül''de hep fırtınalar yaşarım, Serçe kadar ürkek Seni Seviyorum deyişini hep aklımda tutarım, Dudakların arasından süzülüp, Kalbime dolan ...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eylul-lun-onikisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı Yutulur Mu Dayı', 'gozyasi-yutulur-mu-dayi-tulay-eker-0wyce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdamın dengine dünyanın ilmine 

Varamadan gidiyorum 

Bir yanımda hicran 

Bir yanımda ise 

Yolum karışmış feryadım figan 

Başımı kuma gömsen nefesim durur 

Biraz güneş görsem bedenim kavrulur 

Boyun büker umutlarım 

Heybemde ekmek kırıntılarım 

Hepsi savrulur gamı beni vurur 

Azad etse hayat beni 

Bulamam ben bende beni 

Yer gök karışır 

Şimşekler şahlanır 

Sağnak yağmur yağdırır 

Adını bilemediğim sancı

Kalemimin ucunda saklandı

Sokuldum usulca pencereme

Bir kuş kondu üzerine

Adımın harflerini çizdim

Taşıyamaz dedi dizlerim

Yüreği birden ürktü

Uçtu gökyüzüme küstü.

Bugün hayatın tadı neden bozuk 

Sevinçlerimi üşüttü bu vakitsiz soğuk 

Avuçlarımda yaşlarım ikindi vakti 

Gözyaşı yutulur mu dayı? 

Yaşlarımız Rabbimize giden yol olsun...Miraç kandilimiz mübarek hayırlara vesile olsun.Allah Yar yardımcımız daima yanımızda,yanınızda olsun..Mevlama yakın olalım...', 'Sevdamın dengine dünyanın ilmine  Varamadan gidiyorum  Bir yanımda hicran  Bir yanımda ise  Yolum karışmış feryadım figan  Başımı kuma gömse...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozyasi-yutulur-mu-dayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sansın', 'sen-sansin-ali-galip-sari-grqqr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmaz mı yar bir lahza gel içime,

Buz gibi yüreğim gel de ısınsın...

Bir lahza gün gibi doğ da içime,

Gönül çiçeklerim güneş sen sansın! 

Gel ki seni yazsın tarihçilerim,

Ozanım,şairim seni söylesin..

Lügatler hecesiz kalsın üstelik,

Herkesler tek hece, herkes sen desin! 

                                                                         11.09.2004/ Ankara', 'Olmaz mı yar bir lahza gel içime, Buz gibi yüreğim gel de ısınsın... Bir lahza gün gibi doğ da içime, Gönül çiçeklerim güneş sen sansın!  Ge...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-sansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz', 'umutsuz-fatih-cinar-fr6gg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benden ne köy olur

ne kasaba artık

unutmuşum tüm sevmeleri

yaralanmış içimdeki güvercin

sevda yağmurları ıslatmaz olmuş bedenimi

benden ne köy olur 

ne kasaba artık

unutmuşum

tüm kanlı mürekkepli kavgaları

en önemliside kendimle olanını

geri çekilmeye başlamışım

tüm cephelerimden

yenik bir komutan edasında yüreğim

eli tetiğe bastı basacak

benden ne köy olur 

ne kasaba artık

çekmez olmuş vagonlarımı

başımdaki lokomatif

kömürü bitmiş suyu tükenmiş

sessiz bir köşede

hurdaya gideceği günü bekliyor

benden ne köy olur

ne kasaba artık

bedenim ruhuma dar gelmekte

dar gelmekte yaşadığım ev

giydiğim pantolon ayakkabı

dar gelmekte düşünceme

düşüncemden yıpranmış

düşlerimden çıkmayan şehir', 'benden ne köy olur ne kasaba artık unutmuşum tüm sevmeleri yaralanmış içimdeki güvercin sevda yağmurları ıslatmaz olmuş bedenimi benden ne k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/umutsuz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost'' luğa ve Kardeş'' liğe Muhtacız Çok', 'dost-luga-ve-kardes-lige-muhtaciz-cok-ahmet-refik-tavsanli-co09m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dost’ luğa  ve   Kardeş’ liğe   Muhtâcız  Çok,

*

Pişmân’ lığın    Düşmân’ lığın   Hâcet’i   Yok...

*

Kızma, Kırma, Sabret, Affet, Hoşgör  Çok  Çok

*

Hoş görü’ den  daha   Yüce   Bir   Erdem   Yok.

*

     

                                                                                               Ahretahû', 'Dost’ luğa  ve   Kardeş’ liğe   Muhtâcız  Çok, * Pişmân’ lığın    Düşmân’ lığın   Hâcet’i   Yok... * Kızma, Kırma, Sabret, Affet, Hoşgör  Ço...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dost-luga-ve-kardes-lige-muhtaciz-cok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Gözlerin', 'karanlik-gozlerin-i-smail-baharsen-44bl8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerine karanlıklar çökmesin

elinden gelirse uyma bile

dünyaya güzel gözlerin

hep güzellik saçsın

şehir şehir kent kent

dünya seninle dolsun taşsın', 'gözlerine karanlıklar çökmesin elinden gelirse uyma bile dünyaya güzel gözlerin hep güzellik saçsın şehir şehir kent kent dünya seninle dols...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karanlik-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunu Yaşayamam', 'yoklugunu-yasayamam-i-smail-baharsen-3bk78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni silip unutmak elde değilki

bir an bile boşluğuna dayanamam

varlığına öyle çok alışmışımki

ben senin yokluğunu yaşayamam

ellerim arar seni gözlerim ağlar

sen olmayınca öksüz bu kollar

eritir bedenimi vicdansız yıllar

ben senin yokluğunu yaşayamam

hasretin kabus olur uykularıma

hayalin korku olur duygularıma

özlemin ecel olur yarınlarıma

ben senin yokluğunu yaşayamam

şu perişan halimi düşünde gitme

mutlulukla açılan aramıza girme

yalanı değil bir kere gerçeği dinle

ben senin yokluğunu yaşayamam', 'seni silip unutmak elde değilki bir an bile boşluğuna dayanamam varlığına öyle çok alışmışımki ben senin yokluğunu yaşayamam ellerim arar se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yoklugunu-yasayamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diren', 'diren-caner-bozkurt-uskks', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'titrer uyanırım,

yol uzun ve sürgün

ellerimde çelik halkalar

bileklerimde sızı 

duyamam ayaklarımdaki sancıyı

soğuk: çok soğuk.

ses veririm almaz

almaz dağlar da.

ses de vermez

böyle mi susar toprak 

öyle mi Vartinik? 

hain kurşunun çığlığı mı bozar 

sus''u

pus''u...

bu namussuz korkaklık nasıl düşürür

dağ gibi Ali Haydar''ı.

mavzerim, yoldaşım! 

adımlarımı yakıyor bu buzul yollar.

yüreğimide sevdamın ateşi.

sen şimdi toprağıma bereketsin,

ekeceğim, biçeceğimsin

özgür ülkemi doyuracağımsın 

-günü gelince-

şu vakit toprağın kokusu mayısa çalar

mayıs ki; 

sevdamdır ve ateş mavisi

kavgamdır ve kan kırmızısı.

ahirim olsada kızamam

umudumun bahar yanıdır.

varsın bayrak olsun örtülsün

parçalanmış bedenime

sancıyor arduvaz aralarında 

gülmeye hasret gelincikler

sancıyor gün batımında

güneşi sinesine çeken bu toprak.

mavzerim, yoldaşım! 

uyu şimdi 

fakat kaygısız.

gözün ardına düşmesin.

şimdi borcumdur

kana kana içtiğim andımı 

bu Diyarbakır zindanında

düşmana haykırmak:

heeey en soysuz gericiliğin,

ve faşizmin

ve sömürgeciliğin

ve kör zindanın namussuz bekçisi! 

durma gel 

gel de dar edeyim bı taş duvarları başına

gel de içine tüküreyim çaresiz korkaklığının

bu kadar mı karanlığın,

yeter mi sandın zulmün

yeter mi sandın askın, falakan, topun-tüfeğin.

insanlıkla, namusla, cesaretle mayalandı bizim yüreğimiz.

bilir misin ki halkın silahı yaman olur.

ve unutmaz sormayı hesabını 

çektiği acının,

döktüğü her damla kanın

ve unutmayacak

ve elbet soracak hesabını

ve nihayetinde biz de 

bu nazlı toprakalarda süreücek sonsuz bir baharın

devrim renginde çiçekleri olacağız...', 'titrer uyanırım, yol uzun ve sürgün ellerimde çelik halkalar bileklerimde sızı  duyamam ayaklarımdaki sancıyı soğuk: çok soğuk. ses veririm ...', ARRAY['Türk Edebiyatı','Şiir','Caner Bozkurt']::text[], 8.5, '{"poet":"Caner Bozkurt","poet_slug":"caner-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/diren-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Şiirleri-1', 'sevda-siirleri-1-caner-bozkurt-apnl8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ağır; 

Çatallana çatallana içime büyüyen,

Etime kemiğime hiç ayrılmamacasına saplanan

ve artık benim özüm! 

hareketimin kaynağı,

nihayetinde tek amacım olan

 sevdamın,

 fizikle açıklanamayan,

 inançsal

       yüküdür şimdi.', 'Bu ağır;  Çatallana çatallana içime büyüyen, Etime kemiğime hiç ayrılmamacasına saplanan ve artık benim özüm!  hareketimin kaynağı, nihayeti...', ARRAY['Türk Edebiyatı','Şiir','Caner Bozkurt']::text[], 8.5, '{"poet":"Caner Bozkurt","poet_slug":"caner-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-siirleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-volkan-yoruc-1fhc6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatıralar 

Hatırlanması güzel olan anlar

Sisli ve eski sabahlarda

Ağaçlardan sarkan yapraklar

Damlara konmuş kumrular

Bacalardan tüten acı dumanlar

Ve aniden canlanır gözlerimizde

Hatırlanması güzel olan anlar

Hatıralar

Gökyüzünde griye bulanmış yağmurlu bulutlar

Kimimiz okulun yolunu tutar

Kimimiz işe gider sessizce

Bozuk yollarda ilerlerken bu zamanlarda

Gözümüzde tüter

Ve kalmak isteriz hatıralarda

Bahara özlem duyanlar gibi

Aşka hasret  gönüller gibi

Bir başkadır hatıralar

Özlemleri yürekten çekilen eski zamanlar

Hatırlanması güzel olan anlar

Hatıralar', 'Hatıralar  Hatırlanması güzel olan anlar Sisli ve eski sabahlarda Ağaçlardan sarkan yapraklar Damlara konmuş kumrular Bacalardan tüten acı d...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatiralar-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Şiirleri-2', 'sevda-siirleri-2-caner-bozkurt-oennq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurutulup kıyılmış bir çay yaprağı

Nasıl özünü yayarsa kaynar suya

yavaş yavaş,

Bende öyle demlendim sana,

                 kurutulup, kıyılmadan', 'Kurutulup kıyılmış bir çay yaprağı Nasıl özünü yayarsa kaynar suya yavaş yavaş, Bende öyle demlendim sana,                  kurutulup, kıyıl...', ARRAY['Türk Edebiyatı','Şiir','Caner Bozkurt']::text[], 8.5, '{"poet":"Caner Bozkurt","poet_slug":"caner-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevda-siirleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızıntı', 'sizinti-kamil-caglar-aksu-ahysg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir sızıntı akıp giderdi ince

karanlık gölgeleriniz bile 

yıkanırken sessizce,

arınmak aptallıktı sizce! 

kaçtınız..

histeriye tutulmuş benliklerinizi alıp

şizofren adımlarınızla yok saydınız

yürüyüp ayaklarınızı inkar ederek,

gafletin ucuz sırlarına kadem bastınız..

bir sızıntı silip geçerdi berrak; 

yok olurdu ardınızda murdar izleriniz,

morarmış ölü ayaklarınızı unutarak

tiksinirdiniz,

vicdanlarınızda en kalıcı iniltiler duyarak

size dönüşmeyen içinizde en siz dışı

son parçanızdan,

gizlenirdiniz! 

ardı ardına bekleşen darağacı umarsızlıklarına..

ağlamak yoksulluktu,

zengin gözlerinizde

yoksunluktu kalpten bakışlar.

kanatmak sefillikti kalp yaranızı,

pişmanlık içinize değsin istemezdiniz..

bilir,görürdünüz göz ardı; 

bir sızıntı! 

ardınızda peşi sıra,

siz hep bir adım önde yürürdünüz.

kırıldı kristal kasası,

aslınızı çürüttünüz..

arkanızda kaldı hep diriliş ve kurtuluş.

uygarlık denen kaynayan kazanın,

dibini tutturdunuz! 

yalan gerçeklikler icat ettiniz haksız,

içlerinde umultular buldunuz renk renk,

işte o yöne koştunuz hesapsız,

hilafsız.. 

göz alıcı kırmızı halıları serilince; 

terfi etmekte geç kalmadınız,

önünüze günah makamının,

içinde saklıydı başdöndüren hülyaları..

belirdi bir adım ötenizde; 

bir ihtişamdı aldatan,

hayallerinizin kirli ütopyası! 

bozulmuş aslınızın vahim kopyası! 

sonra; 

gaflet zaferlerinin sefil sarhoşluğu,

vecd ile kalkan kendi yumruklarınızdı,

acemi hırsınızın yapay gerçekliğinde..

haramdı umutlarınız,

afyonlu uykularınızda

zehirli rüyalar tattınız,

her sabah bir sara nöbetinden uyandınız,

umursamadınız! 

ve

cehennemden çalınmış 

ateşten gömlekleri giymekte

çekimser kalmadınız! 

derinlerde akıp dururdu ince

akıp geçerdi sızım sızım,

beni vicdan yaptınız 

ben bir kibritçi kızdım

içinizde kalbinizde

yaşamak için savaştım

soğuktu çok soğuk

tükendi kibritlerim 

donmaktan kurtulamadım..

ömrünüz boyu aktı durdu bir sızıntı, 

insanlık özünüzden..', 'bir sızıntı akıp giderdi ince karanlık gölgeleriniz bile  yıkanırken sessizce, arınmak aptallıktı sizce!  kaçtınız.. histeriye tutulmuş benl...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çağlar Aksu']::text[], 8.5, '{"poet":"Kamil Çağlar Aksu","poet_slug":"kamil-caglar-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sizinti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanem', 'kar-tanem-volkan-yoruc-svv78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sızı var içimde

Uzun yollar ardında

Yüreğimin dağlarında

Bembeyaz bulutlar arasında

Bir kar tanesi konmuş sessizce

Dokunmaya korkarım

Erir sanarım uzanamam sana

Bana gülümserken usulca

İçim gider acıyla

Kar tanem gülüm

Bilirmisin nasılda sızlar içim

Su misali akarken bu ömrüm

Sana dokunamam ya

İşte ben ona ölürüm

Kar tanem

Bir ömre bedel gülümsemen

Gözlerini alma benden

Tutamasamda ellerinden

Hayallerimde avuçlarımdasın

Kan kırmızısı güller feda olsun gönlüne

Kuşlar ötsün pencerende

Gün geçer devran dönerde

Hazan yaprakları düşerde yollarıma

Vazgeçmem yinede kar tanem

Erimez karların en güzelisin sen

Kar tanem', 'Bir sızı var içimde Uzun yollar ardında Yüreğimin dağlarında Bembeyaz bulutlar arasında Bir kar tanesi konmuş sessizce Dokunmaya korkarım Er...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-tanem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
