INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak güneşi ona', 'birak-gunesi-ona-ahmet-atmaca-smdcn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bırak güneşi ona 

ben yüzünü aydınlatan gecelere aşığım

yıldızlar naza çeksin kendini

ay hep bildiğim oyunları oynasın

birde gecenin ritmine eşlik etsin hafiften 

hafiften esen rüzgar

bırak  gündüzü ona

ben loş sokak lanbalarının

gözlerine ördüğü desenlere aşığım.', 'bırak güneşi ona  ben yüzünü aydınlatan gecelere aşığım yıldızlar naza çeksin kendini ay hep bildiğim oyunları oynasın birde gecenin ritmine...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birak-gunesi-ona-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dortler Gecesi', 'dortler-gecesi-mahir-celik-oikky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dörtlerin Gecesi 



(Ateşin ve Güneşin Çocukları)

(...)

Zindanlarda dirence sarılmıştı 

Ve haykıran dudaklar 

Her ihanet vakti çöl çöl yarılmıştı 

...oOo... 

Bir ağıttır belki Ağrı''da Zilan deresi 

Dersim''de Lac deresi bir kanlı şiir 

Oysa bir destandı Diyarbakır kalesi 

Ve Diyarbakır zindanında 

Ateşle sevişen ''dörtlerin gecesi'' 

Ne ki zindan - ne ki tutsak olmak 

Ne ki kavga - ne ki dağlarda vurulmak 

Bir sehpada idam olmak ne ki 

İhanet utancıyla yaşamak var ya hani 

Onursuzluğun lağım çukurunda yok olmak 

Üniformalı bir Dehak önünde durmak 

Ve beyninin içindekileri bir bir kusmak 

Sonra bir et yığınına dönüşüp kalmak 

İşte buydu Diyarbakır zindanında yaşamak 

Sesler ihanete dönüşürdü her gece 

Bir tas çorba - bir dilim ekmek uğruna 

İhanetler acılara dönüşürdü kalleşçe 

Acılar hep türkülere vururdu kendini 

Etten ve kemikten insan olur mu 

Beyinsiz insan ayakta durur mu 

Aynı kavgaya gönlünü verenler 

Dostunu ihanet ile vurur mu 

O zindan ki zincir sesidir şarkısı 

Her sözünde bir çığlık yükselir 

Her notasında bin öfke 

Her dizesinde bin isyan beslenir 

İsyan şiirlere 

Şiirler yüreklere seslenir 

O zindan ki her yemek vakti 

Tutsak ağızları kanla süslenir 

Onur kaleleri yıkılırken birer birer 

Yüreklerde dal budak salar ihanetler 

Ve düşman kasetinde ü''ç önder 

Beyinlerini kusarak düşmana sergiler 

Aynı anda sıradan bir nefer 

Hiç aldırmadan önderlerinin sesine 

Tutsaklık içinde özgürlüğü söyler 

Sus dostum sus - sözün yarıda kalsın 

Özgürlük dilinde kilitli kalsın 

Başlar eğilse de açılsın gözler 

Konuşan önderler geride kalsın 

Ne zaman umutsuzluk çökse direncin kıyısına 

Bir acı saplanır yüreğin tam ortasına 

Koğuşlar susar 

Parmaklıklar durur 

Ranzalarda küllenen umutlar ağlar 

Geriye doğru atılan her adım 

Yakılan ateş üstüne yağmur diye yağar 

Anlatılmaz bir destandır yaşanan 

Ne söze gelir ne saza 

Kırbaçlar sopalara ve zincirlere karışır 

Ölüler ayaklara dolanır geceleri 

Kanlı battaniyelere sarılır 

Her direnişte tabutlarla çıkılır dışarı 

Gözyaşları zılgıt seslerine katılır 

Elleri hep koynunda kalır kızların 

Anaların gözleri dikenli tellere takılır 

Bir acılı sessizlik sarar yürekleri 

Dicle''nin suları susuzluğa çakılır 

Kale burçlarındaki akbabalara 

Ve üniformalar giyinmiş yeni Dehak''lara 

Yalnızca zindanın mazgallarından bakılır 

Bir adam çoğalır bir başına hücresinde 

Yüreği Kawa''dadır gözleri Babek''te 

Ateşler yanarken dağ doruklarında 

İhanet zindan karanlığında kol gezmekte 

Kawa''lara Babek''lere bir yandaş gerek 

Bu zindan karanlığına bir ateş gerek 

Çevrilen ihanet çarkını kırmak için 

Ölümü göğüsleyecek bir yoldaş gerek 

Bir anda yırtılır zindan karanlıkları 

Sessiz bir gürültüyle sarsılır duvarlar 

Patlar bir beyinde Newroz ışıkları 

Ey ateşin ve güneşin çocukları 

Hani bilincin sesi yüreklerimizde 

Gözlerimizde inancın sancakları nerede 

Bu gidişe dur demek gerekir bilirim 

Hücrede her saniyeyi bir yıl eylerim 

Bir ateş yaktık sönmesin diye hiçbir yerde 

O ateş sönerse yaşamayı neylerim 

Bu yüzden ü''ç kibrit ile Newroz günü 

Yüreğimi sizlere armağan eylerim 

Ü''ç kibriti bayrak diye devralan 

Ki dağları delip dostlarına yol kılan 

Haykırdı ölüm haberini önde gidenin 

Özgürlüğü zindan karanlığında güneşleyenin 

Ey bu kavgaya gönül verenler 

Ser yerine sır verenler 

Serden geçip de sır vermeyenler 

Bu zindan karanlığı yırtılsın diye 

Bu ihanet duvarları yıkılsın diye 

Newroz gecesi bir önder 

Ateşi bedeniyle zindanlara taşımıştır 

Ölürken bile hücresinde 

Bizlere kıştan baharı muştulamıştır 

Ateşi saraylara - kömürlerde değil 

Bir ışık uğruna yüreğinde yakmıştır 

Silinmiyordu gözlerden süzülen yaşlar 

Aksın diyordu herkes - aksın 

Ağlamayı unutmuş gözler ağlasın 

Gözyaşları alev alev harlansın 

Dudaklarda tutuşup dillerde şahlansın 

Ölen artık yüreklerde bir bayraktır 

İhanet yolunda durulan bir duraktır 

Karanlıkta bir çingi ateş 

Körlere yol gösteren bir ışıktır 

Atılan zılgıtlar bir başkadır o gün 

Bir bayram günü ölümü sevmek 

Ölümsüzlüğe duyulan bir aşkadır o gün 

Dolaştı ü''ç kibrit elden ele sessizce 

Hücreden hücreye 

Koğuştan koğuşa gizlice 

Konuşuldu uğrun uğrun 

Tartışıldı geceler boyu ince ince 

Zindandan dağlara vurdu şavkını 

Dağlardan en kalabalık kentlere 

Dallarda çiçeklere verdi rengini 

Nehirlerde en coşkulu köpüklere 

Dolaştı yurdunu boydan boya 

Sazda kırılmayan tel 

Dilde susmayan söz oldu türkülere 

Zindanda yürekler yine baskıda 

Eller bağlı - gövdeler askıda 

Ü''ç kibritin ateşi sönsün istenir 

İnançlar ihanete dönsün istenir 

Düşünceler zincire 

Sevgiler prangaya vurulsun istenir 

Yüreklerde çağlayan özgürlük suyu 

Bulana bulana durulsun istenir 

Üniformalı bir Dehak''ın şahsında 

Zalimin zulmü kurulsun istenir 

Baskılar yetmezse itirafta bulunmalara 

Yapılan itiraflar dinletilir tutsaklara 

İşte biri - biri daha - biri daha 

Susardı bütün koğuşlar 

Dönerdi bir anda sessiz mezarlara 

Ve çığlık çığlığa o sessizlik 

Binlerce öfkeyi 

Binlerce isyanı doldururdu bakışlara 

Ü''ç kibriti dörtlemek derdi bir ses 

Dört kibriti beslemek 

Ve ölümü isyan ateşleriyle düşlemek 

Bir koğuş vardı koğuşlar içinde 

Ü''ç kibriti dörtleyenler yatardı içinde 

Dört yıldız gibiydiler yıldızlar içinde 

Teslimiyete gönül verilirken önlerinde 

Ateşi çoğaltarak yakmak gerek dediler 

Ölüme yaşamak diye bakmak gerek dediler 

Sönüyorsa yakılan ateşler birer birer 

Ateşi bedenlerde çoğaltmak gerek dediler 

Oturdular her gece diz dize 

Önce ölümü sevmeyi öğrendiler 

Ve ölümde ölümsüzlüğün rengini gördüler 

Karardan Önce yurtlarında kalanlarını 

Çiçeklerinde açanlarını sordular 

Düş değildi yaşayıp gördükleri 

Sözlerini gelecek adına bir düş diye 

Dördü bir ağızdan hayra yordular 

Binlerce tutsak içinde 

Ve en kanlı kudurmuşluğunda vahşetin 

Ölüm cehenneminde bir cennet kurdular 

Havasızlık içinde veremler yaratılırken 

Gardiyan hakimler ve savcı çavuşlarla 

Her gece mahkemeler kurulurken 

İnsanlar soyundurulup makatlar aranırken 

Hangi kuş konardı zindan penceresine 

Ve makatlara sigara takılıp yakılırken 

İnsanlar dört ayak ile yürütülürken 

Hangi bayrak çekilirdi onur kalesine 

Ü''ç kibriti yüreklerinde dörtleyenler 

Açlığın ve yoksulluğun kötülüğünü gördüler 

Ama hiçbir şeyin 

Boyun eğmekten daha kötü olmadığını 

Ve boyun eğenlerin 

Yarınlara kalmadığını bildiler 

Her kötülüğün daha kötüsünü tartışıp 

Gözlerinde bütün korkuları sildiler 

Binlerce baskıdan ve küfürden sonra 

Newroz ateşi yakıp şiirler söylediler 

O günün adını milat koyup 

Ü''ç kibrit öncesi 

Ve ü''ç kibrit sonrası dediler 

Ötsün diye kendi yuvasında kuş 

Açsın diye kendi dalında çiçek 

Gördüler ki yepyeni kibritler gerek 

Ateş olup yanmaktaysa bütün gerçek 

Yanarken türkü söyleyen canlar gerek 

Ateşi kanıyla tutuşturanlar gerek 

Patladı zindanlarda yepyeni bir isyan seli 

Ölümdür sınayan insan yiğitliğini 

Ölümü bedenimizde boğmak gerek 

Ölümsüzlüğe varıp ölümlerde 

Dağlarda kır çiçeklerince çoğalmak gerek 

Ölümü gamzelerde çiçeklemek ve gülmek 

Gülmek ki yaşama bilenmek demek 

İlle de insan sıcağı kokarken koğuşlar 

Gülmek ki 

Kurumuş derelerde sellenmek demek 

Çol kuraklığında güllenmek demek 

Var git dostum var git 

Kendin al bu gece nöbeti 

Bu gece ölmek 

Sonsuz bir ölümsüzlüğe yürümek demek 

Aylardan mayıs ki dallarda çiçektir 

Toprakta bereket ve doğada renktir 

İnançta güzellik ve zamanda gelecektir 

Dört yoldaş o gün baharın koynuna girdiler 

Ölümün alçaldığını gözleriyle gördüler 

Gömleklerini - kalemlerini ve saatlerini 

Anılsınlar diye sevdiklerine verdiler 

Ve dört ağızdan ü''ç kibritin ışıklı sesini 

Gök gürültüsünü çıldırtarak gürlediler 

Bu ihanet girdabında boğulmadan 

Şahsımızda davamız son bulmadan 

Ve geriye dönüşler virus gibi çoğalmadan 

Canımızla bu ihanet çarkına dur demeliyiz 

Onur bayraklarını göğsümüze dikmeliyiz 

Kawa''nın örsüne koyup davamızı 

Yüreklerimizi körüklenen ateşlere sürmeliyiz 

Bu zindanda yolumuz aydınlıktır artık 

Ü''ç kibriti dörtle çarpıp bu gece 

Bütün şehitlere konuk gitmeliyiz 

Saat dörtte dört canın etrafı dört duvar 

Duvarların ötesi mayıs gülleri ve bahar 

Analar ve bacılar ağlayacakmış ne çıkar 

Bu gece ''dörtlerin gecesi'' 

Dört göğüste yar diye yalnızca ateş yanar 

Biri nöbet tutar - biri bildiri yazar 

Diğerleri dört kişilik bir ateş kurar 

Zindan sessiz - zindan canlı bir mezar 

Gökyüzünde bir anda dört yıldız kayar 

Bütün dostlar uykuda 

Dörtlerin gözlerinde yalnız ateş var 

Dimdik başlarla 

Emin ve kararlı bakışlarla 

İhaneti durdurmak için ateşe yürüyorlar 

Dördü de yaşamaya sevdalı 

Özgürlüğe nişanlıydılar 

Tutsaklık kesmişti mutluluk yollarını 

Bu zindanda ölüme nikahlıydılar 

Bu ölüm ki özgürlüğün ilk adımı 

Tutsaklığın ve ihanetin kırılma anı 

Takvimde on yedi mayıs kalkar 

On sekiz mayıs dörtlere bakar 

Dışarda güne hazırlanırken tomurcuklar 

Dört candan başka uykudadır bütün tutsaklar 

Dağ - taş ve zindan uykudadır 

Yalnızca dört özgürlük yolcusu 

O gece ölüme hesap sormaktadır 

Yıllar boyu işkenceler içinde 

İhanetler ve direnmeler içinde 

Beklediler - beklediler de gelmedi ölüm 

Tuttular yakasından koydular önlerine 

Konuş be ölüm - konuş dediler 

Biz büyürüz sen böyle küçüldükçe 

Seninle kavgamız insanlık tarihiyledir 

Prometheus''tan Spartakus''e 

Bruna''dan Che Guewera''ya 

Vr Kawa''dan bizlere dek ateş iledir 

Gel de bağdaş kur soframıza ey ölüm 

Senin alçaldığını görmek 

Özgürlük adına sunulan canlar iledir 

Zindan sessiz - zindan canlı bir mezar 

Dört can el ele bir demire sarıldılar 

Tinerler - neftler ve boyalar 

Zindanda dört can 

Kazan altında betona çakılmış birer çiviydiler 

Demirin beline sarılmış dört perçindiler 

Ve bir potada erimeye hazır cevherdiler 

Haykırdı ü''ç kibrit yolunda önde giden 

Ateşi zindanlardan kentlere götüren 

Tamam mıyız 

Ü''ç yerine dört kibrit çıkarıp cebinden 

Yaktı yüreğindeki korlanan ateşten 

Tutuşan ateş 

Patlayan tinerlerin ve neftlerin sesi 

Dokunmasın hiç kimse 

Bu gece dörtlerin özgürlük gecesi 

Dört bin yılda yazılmış bir destanın 

Güneş diliyle söylenmiş ilk hecesi 

Böyle tutuşur - böyle yanar ancak 

Uzay çağında bir zindan gecesi 

...oOo... 

Bir havar yükseldi zindandan kırlara 

Dört ateşten dört kıvılcım düştü dağlara 

Dağlar tutuşup indi bağlara 

Dört ayrı ses yükseldi her ateşten 

Söndürmeyin ateşi 

Üfleyin korlara - üfleyin korlara 

(...)

Yak artık canlarla yakılan ateşleri 

Yak ki açılsın dünyanın körelmiş gözleri 

Yak ki yırtılsın geceler ışığınla 

Yak ki tarihi yeniden başlatsın 

Kawa''nın -ü''ç kibritin ve dörtlerin sözleri 

Yak ki yayılsın dünyaya 

Ateşin ve güneşin ölümsüz sesi', 'Dörtlerin Gecesi  (Ateşin ve Güneşin Çocukları) (...) Zindanlarda dirence sarılmıştı  Ve haykıran dudaklar  Her ihanet vakti çöl çöl yarılmı...', ARRAY['Türk Edebiyatı','Şiir','Mahir Celik']::text[], 8.5, '{"poet":"Mahir Celik","poet_slug":"mahir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":304,"source_url":"https://www.antoloji.com/dortler-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Bulutu, Beter Ol', 'huzun-bulutu-beter-ol-zulfikar-yapar-kaleli-8hzh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklı zayi eden, yufka düşüren 

Kendini bitiren dertten beter ol 

Dostun boynu bükük, yürek pişiren 

Bir tadımlık haram fırt tan beter ol 

Bela başa gelir fütursuz dilden 

Bilinçsiz toplumdan, destursuz yelden 

Yükledin çekerim, ne gelir elden 

Konturu tükenmiş karttan beter ol 

Hayret ırmağında, medet çayında 

Doksan yedi yılı, mayıs ayında 

Bir orman içinde, dere boyunda 

Yarayı kemiren kurttan beter ol 

Ham toprak, ham ahlat olduğun yaygın 

Bu muydu düşüncen, ne idi kaygın? 

O yüce insana bu muydu saygın? 

Tezekle kızaran şurttan, beter ol 

Hasretle ararken sonsuz visali 

Gökyüzü hüzünlü, hilâl tasalı 

Sahibi çıkmayan mektup misali 

Baykuşlar tüneği yurttan beter ol 

“Bir insan fedakâr olmazsa şayet 

Nefsi onu ezer” dese de ayet! 

Zamansız eriyen kar gibi evet 

Bağını sel almış fertten beter ol 

Güne hazan düştü, budur görülen 

Liyakati defter gibi dürülen 

Yusuf gibi diyar diyar sürülen 

Mazlum pazarında mertten beter ol 

Ufka yelken açmış, hülyalar kurmuş 

Lakin, haksızlığa lâl gibi durmuş 

Deryada boğulmuş, karaya vurmuş 

Şu cinli doruktan, karttan beter ol 

Olgunluk beklemek olur mu kaldan? 

Ne anlar hatırdan, ne bilir halden 

Arslanlara çoban olmaz çakaldan 

Bir ömür yatalak sırttan beter ol', 'Aklı zayi eden, yufka düşüren  Kendini bitiren dertten beter ol  Dostun boynu bükük, yürek pişiren  Bir tadımlık haram fırt tan beter ol  Be...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/huzun-bulutu-beter-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutursun', 'unutursun-ahmet-atmaca-69yi8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'meyhaneler meskanim diye arama 

bir köşe başında rastlarsın belki

incitme kalbini sakın ağlama

gün gelir benide unutursun yar', 'meyhaneler meskanim diye arama  bir köşe başında rastlarsın belki incitme kalbini sakın ağlama gün gelir benide unutursun yar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutursun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Dönünce', 'sen-donunce-i-smet-barlioglu-bqtpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dönmeni neden bu kadar çok istiyorum, biliyor musun? 

Döndüğünde mucizeler olacak sanıyorum da, ondan,

Böylesine koşullandırmışım kendimi anam-babam,

Böylesine inandırmışım.

Sensizlikten ölüp kaldığım zaman ıssız bir yerde,

Sen döndüğün an dirilirmişim sanki,

Sanki yeniden başlarmışım yaşama,

Ben böyle koşullanmışım, böyle inanmışım işte,

Sen ister inan,

İster

İnanma.

Döndüğünde bayram bayram olacak günlerim,

Taklar altından geçeceğim; gökkuşaklarını andıran,

İdamlıklar iplerden, sehpalardan kurtulacak,

Kapıları açılacak ardına kadar tutukevlerinin,

Şifa bulacak tüm hastalar yataklarında,

Ağlayanlar gülecek kahkahalarla,

Kerem Aslı ‘ya, Ferhat Şirin ‘e,

Ve Mecnun da kavuşacak

Leyla ‘ya.

Çatlayıp açılacak tohumlar, çekirdekler,

Su sesleri gelecek kurumuş derelerden,

Yoksullar varsıllaşacak,

Derman bulacak dertliler dertlerine,

Garipler unutacak garipliğini,

Her gülde bir bülbül öterek karşılayacak

Seni.

Sen dönersen; toprak can bulacak, deniz güzellik,

Çileler çözülecek yumaklardan iplik iplik,

Bulutlar özürler dileyecek güneşten,

Çam kokusu denizi, yosun kokusu ormanı saracak,

Yüreğim ayaklarına diz çöküp

Ağlayacak.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 81-82/100)', 'Dönmeni neden bu kadar çok istiyorum, biliyor musun?  Döndüğünde mucizeler olacak sanıyorum da, ondan, Böylesine koşullandırmışım kendimi an...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-donunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün de Sevgiler, Saygılar', 'bugun-de-sevgiler-saygilar-i-smet-barlioglu-3qt44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün de sevgiler, saygılar sana

Ayaklarıma usulca kapanan bir sabah güneşiyle…

Uykudan uyanan körpe çiçeklerle,

Karasevdama sığınmış renklerle,

Bugün de sevgiler, saygılar sana

Hevenklerle.

Güller senin için açmış, biliyor musun? 

Kuşlar yine senin için ötüyor,

Yine kanatlar çırpıyor martılar senden yana,

Deniz yine seni soruyor bana fısıldayarak

Ve çisilemeye başlayan yağmur

Ağlayarak.

Ah, seni soran benim anam-babam, benim,

Seni gülde, çiçekte, denizde, kuşta gören benim,

Ben soruyorum, ben, seni denizlerden, rüzgarlardan,

Kumsallardan, martılardan,

Her kime rastlasam bu kara kaderimde; 

Ondan.

Bugün de sevgiler, saygılar sana

Sevdamdan, karasevdalarımdan, elkızı,

Garip yüreğimden,

Hüznümden,

Özlemlerimden,

Bir zaman arıyorum; deli-divane olmuş,

Geçsin diye ayrılıkların

Üzerinden.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 83-84/100)', 'Bugün de sevgiler, saygılar sana Ayaklarıma usulca kapanan bir sabah güneşiyle… Uykudan uyanan körpe çiçeklerle, Karasevdama sığınmış renkle...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bugun-de-sevgiler-saygilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırıyorum', 'cagiriyorum-i-smet-barlioglu-8lu5e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçek arıyı özüyle çağırır,

Yem balığı özüyle,

Toprak yağmuru kurumuş dudaklarıyla,

Tohum kuşu varlığıyla çağırır,

Ben de seni yüreğimle çağırıyorum.

Örselenmiş, yaralanmış yüreğimle,

Perperişan olmuş varlığımla.

Hem nasıl bir çağırıyorum iki gözüm iki çeşme,

Her iniltim bir ayrı çığlık dudaklarımda,

Güneş-müneş kalmadı şafaklarımda,

Duymuyor musun,

Nasıl çağırıyorum gökler altında? 

Tanrı ‘nın

Bundan kederli sesi var mı

Kainatında? 

Yağmurla ıslanan gecelerde çağırıyorum anam-babam,

Körpe şafaklarda çağırıyorum,

Sessiz çığlıklarla haykırdıkça haykırıyorum

Bulutlu-bulutsuz gökler altında,

Uzak-yakın denizlere doğru,

Sise bürünmüş ormanlara,

Tozlu-tozaklı yollara,

Sevdası koltuğunda bir suçlu olup gittim

Tanrı ‘ya,

Kullara.

Seni yüreğimle çağırıyorum,

Ruhumla, bedenimle,

Canlar içinde cansız kalmış canımla,

Hüznümle, özlemlerimle çağırıyorum,

Toz toz olup zerrelerine ayrılmışım karasevdanda; 

Dağılıyorum.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 85-86/100)', 'Çiçek arıyı özüyle çağırır, Yem balığı özüyle, Toprak yağmuru kurumuş dudaklarıyla, Tohum kuşu varlığıyla çağırır, Ben de seni yüreğimle çağ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cagiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-i-smet-barlioglu-efcbd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana neden sevdalanmışım,

Neden bağlanmışım,

Neden karasevdalanmışım? Bilmiyorum.

Gözlerin herkeslerdeki gözler,

Saçların, yüzün, kaşların, dudakların,

Ellerin, ayakların,

Boyun-bosun,

Bakışların, gülüşlerin, yürüyüşlerin,

Başını çevirip çevirip gidişlerin

Başka elkızları gibi anam-babam.

Seni güle, sümbüle ben benzetiyorum,

Ağaca, fidana,

Sisler içindeki ormana,

Martı kanatları altındaki denize,

Dalgaların silip parlattığı altın kumlara,

Düşlere, uykulara benzetiyorum.

Saba Melikesi Belkıs değilsin,

Güzeller Güzeli Züleyha değilsin,

Dünya Güzeli Fatma değilsin,

Neden bağlanmışım, neden sevdalanmışım? Bilmiyorum.

Kerem ‘in uğruna yanıp kül olduğu Aslı misali,

Ferhat ‘ın uğrıuna dağlar deldiği Şirin misali,

Kays ‘ın uğruna mecnun olduğu Leyla misali,

Baban padişah, anan sultan değil,

‘Peri kızısın’ desem yanlış,

‘Hurisin’ Desem; hata,

Aklımı deliye divaneye çevirdim ömür boyu

Arata

Arata.

Söz mü dinler yaralı yürek? 

Söz mü dinler akılsız başım? 

Söz mü dinler başında kavak yelleri esen gönlüm? 

‘Sen sev, gerisine karışma’ demişler,

İyi de

Etmişler.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 87-88/100)', 'Sana neden sevdalanmışım, Neden bağlanmışım, Neden karasevdalanmışım? Bilmiyorum. Gözlerin herkeslerdeki gözler, Saçların, yüzün, kaşların, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/neden-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-i-smet-barlioglu-njfhi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne de ağırmış karasevdanın bedeli; 

Anıları birer birer bulup yeniden yeniden yaşamak,

Çıkarıp çıkarıp gözden geçirmek

Gizlendikleri o karanlık yerlerden,

Her anı yüreğe saplanacak bir mızrak gibi doğruluyor

Siperlerden.

Acıları yeniden yeniden yaşamak ne zorlu iş,

Ayni sancıları birer kez daha duymak,

Ayni sızıları birer kez daha yaşamak kemiklerde,

Yeniden yaralanmak,

Yeniden örselenmek, yeniden kırılmak

Ve seni yaralı yürekler içinde

Birer kez daha

Bulmak.

Terazinin bir gözünde tek bir karasevda,

Obirinde sayısız çileler,

Ayrılıklar,

Özlemler,

Acılar,

Serzenişler,

Dualar,

Pişmanlıklar,

Yaralanmış ve bir yana fırlatılmış yürekler,

Acılar içindeki ruhlar,

Hırpalanmış bedenler,

Vefasızlıklar,

Sancılar, kederler,

Seveni sevilene göz bile kırpmadan

Kurban ederler.

Kurbanın olmuşum, anam-babam,

Kurbanın olmuşum,

Kendimi kendimde arıyorum, bulamıyorum; 

Kaybolmuşum.

(DEĞNEKSİZ ÇOBAN isimli Serbest Şiirler ''inden > 89-90/100)', 'Ne de ağırmış karasevdanın bedeli;  Anıları birer birer bulup yeniden yeniden yaşamak, Çıkarıp çıkarıp gözden geçirmek Gizlendikleri o karan...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bedel-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-huseyin-kutup-txgck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan

İnsan dönen bir zemberek 

insan sinsi bir şeytan yahut melek

insan herşeyi eleyen bir elek 

çözemediğim sır insan nedemek?', 'İnsan İnsan dönen bir zemberek  insan sinsi bir şeytan yahut melek insan herşeyi eleyen bir elek  çözemediğim sır insan nedemek?...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kutup']::text[], 8.5, '{"poet":"Hüseyin Kutup","poet_slug":"huseyin-kutup","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Sada', 'kutlu-sada-huseyin-kutup-uxejf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kutlu Sada

Bir devri saadet geçti dünyadan

kutlu bir sada yükseliyor doğudan', 'Kutlu Sada Bir devri saadet geçti dünyadan kutlu bir sada yükseliyor doğudan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kutup']::text[], 8.5, '{"poet":"Hüseyin Kutup","poet_slug":"huseyin-kutup","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kutlu-sada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Gülten Özdemir’in Anısına-', 'gulten-ozdemir-in-anisina-emel-manav-sgnsx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O bir öğretmendi, adı Gülten’di 

Bana hem dost, hem de ustaydı. 

Yanımda oldu hep tırmandığım yokuşta 

Çok şey öğrendim ondan 

Otururdum yanında. 

Otuz yaşımda evet, sevdirdi okumayı. 

Raflar doldu Gülten’im, 

Tozlandığını sanma. 

Her gün beş sayfa derken, 

Çıkardım bir kitaba. 

Ben nasıl unuturum, 

Gülmeyen gözlerini. 

Acı çekerken bile, 

Ayakta zorla duran 

Tazecik bedenini. 

Azmin başaramayacağı iş yoktu, 

Fakat bilmezdim. 

Zaferini mutluluğunu öğrettin bize. 

Kastın neydi kendine, 

Ki yenemedin! 

Neden, neden yenmedin sanki 

O amansız derdini, 

Lanetlik kanserini! ! ! 

Esirgeyen Rabbimden 

Sana merhamet, rahmet 

Ve gufran diliyorum. 

Kabrini donattığım gül kızarır arından 

Senden selam getirir, 

Bu günden ve yarından. 

Mekânın güneş olsun, 

Nur içinde yatasın, 

Can dostum canım benim. 

Nur içinde yatasın, 

Can içre öğretmenim.', 'O bir öğretmendi, adı Gülten’di  Bana hem dost, hem de ustaydı.  Yanımda oldu hep tırmandığım yokuşta  Çok şey öğrendim ondan  Otururdum yan...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gulten-ozdemir-in-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla', 'bir-damla-necmiye-sarpkaya-zqiwj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nicedir anlamsızlık yüklenmiş ruhuma

Eşlik eder adımlarım usul usul

Dalgaların duygu yüklü his yüklü

Sahillere bıraktığı manalı sözler

Kulaklarımda çınlayan

Kulaklarına merhamet fısıldanmış

Bulutlardan dökülen damlalar gibi

Vuslat denizinde yüzer gibi kirpiklerim

Kim bilebilir yüreği bulut bulut

Olmuş gül yüzlü sevgilinin

Dudaklarından dökülen nağmeler gibi

Nicedir çatlamış bir yürek bende

Cehennem sıcağında yanar gibi

Kavrulur ölüm sancılarında

Kimler misafir gönül sarayında

Kimler olmalıydı ev sahibi

Neden yağmaz sevda yağmurları

Neden ıslanamıyorum baştan aşağı

Gökler ötesi alemler sağnağında

Dönmüş viranlara gönül mülkü

Olmalı bir şifa olmalı harabelere

Bir ışık bir sızıntı  bir damla

Bir damlacık gözyaşı...', 'Nicedir anlamsızlık yüklenmiş ruhuma Eşlik eder adımlarım usul usul Dalgaların duygu yüklü his yüklü Sahillere bıraktığı manalı sözler Kulak...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-damla-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Balesi', 'buz-balesi-abdullah-karabag-l3v9g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanötesi işten 

      zamanaşımına uğramıştı sevgi 

Hastalanmıştı aşk virüsü

Katılmasaydı buz balesine

Görmeseydi paten fırtınasını

Duymasıydı balerin çekişmesini

Hastalanmayacaktı 

                          aşk virüsü

Çağın yatalığıydı sevgisi 

              Sonunda 

hekimi atladı 

          eczanenin kapısını çaldı 

–Hastayım dedi sevgiye 

       uyar ilacınız var mı 

–Benim dedi Eczacı Sevgi ellisinde 

               el değmemiş ellime

 –Siz hiç âşık olmadınız mı 

–Hem de nasıl 

–Kime 

–Kendime 

         kendimi bildim bileli 

–Sevgi’yi öldürmüşsünüz dedi 

                 (kaçmalı)  

Oracıkta koşumlandı 

                            aşk virüsü.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Zamanötesi işten        zamanaşımına uğramıştı sevgi  Hastalanmıştı aşk virüsü Katılmasaydı buz balesine Görmeseydi paten fırtınasını Duymas...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/buz-balesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerimiz', 'turkulerimiz-mehmet-zeki-akdag-8sp9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öz suyumdan deniz oldu

Denizimi emdi kıyı

Ağır ağır erittiler

Selçukluyu Osmanlıyı.

Büyük büyük tufanlarda

Yitirdik birbirimizi

Şüphesiz vuslat gününe

Türküler getirdi bizi.

Anacığım çağırıyor

Bir türküde demin beni

Türkülerle doğmuşum ben

Türkülerle gömün beni.', 'Öz suyumdan deniz oldu Denizimi emdi kıyı Ağır ağır erittiler Selçukluyu Osmanlıyı. Büyük büyük tufanlarda Yitirdik birbirimizi Şüphesiz vus...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkulerimiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuz Düş', 'yorumsuz-dus-mehmet-zeki-akdag-danqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mazî denen mutlu masal

Gerçek dışı umut artık

Kırık aynadaki resmi

Ne yap ne et unut artık...

Denizinden yanık kıyı 

Kavgalıdır çağlar boyu

Bu dört dörtlük yanılgıyı

Yarınlara tanıt artık...

Dağa kaçan düzlüklerden

Renk delirten yozluklardan

Eskitilmiş sözlüklerden 

Alınmıyor yanıt artık...

Cüceyi dev yapan ışık

Şimdi zindanla barışık

Gür salkımlı mor sarmaşık

Var mı böyle konut artık...

Sevdalar bir sır mı idi? 

Dünya bunca darmı idi? 

Öyle zaman var mı idi? 

Yok ortada kanıt artık...', 'Mazî denen mutlu masal Gerçek dışı umut artık Kırık aynadaki resmi Ne yap ne et unut artık... Denizinden yanık kıyı  Kavgalıdır çağlar boyu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yorumsuz-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Özleyiş Türküsü', 'en-guzel-ozleyis-turkusu-mehmet-zeki-akdag-ofokm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi aynaya baksam

Yüzünü özlüyorum,

Bir damlayı göl eden 

Gözünü özlüyorum.

Rüyama gelişinden

Ruhuma doluşundan

Kar rengi gülüşünden

Sözünü özlüyorum.

Makbul duam dildaşım

İki cihan yoldaşım

Neredesin haldaşım

İzini özlüyorum.

Firlerin eşiğinden

Yetimin kaşığında

Gönlümün beşiğinde

Nazını özlüyorum.', 'Hangi aynaya baksam Yüzünü özlüyorum, Bir damlayı göl eden  Gözünü özlüyorum. Rüyama gelişinden Ruhuma doluşundan Kar rengi gülüşünden Sözün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/en-guzel-ozleyis-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Gıdıklayan Çocuk', 'kendini-gidiklayan-cocuk-fevzi-gunenc-3j0r1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendini gıdıklayan çocuğum ben

gülmek için...

Gıdıklandıkça gülüyor gülüyordum...

Ama artık

ne kadar gıdıklarsam gıdaklayayım kendimi

gülemiyorum.

Acaba bu güzel şey

yeniden ne zaman olur? ..

Buna takıldı aklım...

Sanırım gülmeye başlarsa

yeniden HALKIM.', 'Kendini gıdıklayan çocuğum ben gülmek için... Gıdıklandıkça gülüyor gülüyordum... Ama artık ne kadar gıdıklarsam gıdaklayayım kendimi gülemi...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kendini-gidiklayan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı Gönül', 'yasakli-gonul-abdullah-karabag-f38mn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül yasaksın

gönülden yasaklı

   Gönül çığlık

çığlıkların yasak

   Gönül gülücük

gülücüklerin yasak

   Gönül türküsün

türkülerin yasak

   Gönül için için gönülsün

gönülden yasaklısın

   Gönül

        gönül bağı için

olmazı olura çıkaramaz mısın? 

Güldestan Gibi, toplu şiirler, 2.baskı', 'Gönül yasaksın gönülden yasaklı    Gönül çığlık çığlıkların yasak    Gönül gülücük gülücüklerin yasak    Gönül türküsün türkülerin yasak    ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasakli-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek İşçisi', 'yurek-i-scisi-abdullah-karabag-dwxy9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalgın bakışlarını gündoğumunda

kaçımsar bulutların kurdelesine 

                   düşür 

Dalgınlığından direnci damıttım 

                 yüreğime

Kargı bakışlarımı düşünü düşürene

                   düşür 

karamsar bakışlar beslenmesin

Yalancı çınarlara teslim edilmiş 

                   umut 

Yeni bir yürekle açılmak istiyorsan 

        düşün bitimsizliğine

Bordo bürgülü avcı bakışlarını

       günbatımında kordona

                  düşür

Balıkçı ağlarının arasında

          yürek işçisiyim

Venüsün ışıltısında martıların

               gözetiminde 

            Görüşmek üzere.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Dalgın bakışlarını gündoğumunda kaçımsar bulutların kurdelesine                     düşür  Dalgınlığından direnci damıttım                  ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yurek-iscisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Ben, Şehrazad...', 'ben-sehrazad-abir-zaki-khj1l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'birbiri ardınca devrilen gecelerce, 

bin bir gece boyunca; 

yeniden doğayım diye ben; 

aklını çeldim, 

ruhunu zaptettim onun… 

özgürlük…özgürlük… 

nakşederken sözcüklerini ruhuma; 

duyardım son tınılarını. 

sözcükler ki uyandırıp benliğimi; 

yükseltirdi mermer bir heykel gibi bedenimi. 

tutsak edici tutkularım; 

ve Zekam; 

masallarımın sihiri; 

şiir denizim; 

zapteyledi kralımın kalbini… 

yoksa… 

ben miydim tutsağı onun? 

Çeviren: Kadir Deniz 

***************************************************************************************

I, Shahrazad

For nights after nights, 

In a thousand and one nights 

Captured his soul 

Got his mind 

To let me reborn…. 

Freedom…freedom 

Carving his words into my soul 

Hearing the end of each word 

Awakening myself 

Holding high as a marble statue…. 

My captive passion 

My cleverness, 

The frame work of my tales 

My sea of poems… 

Captured my king’s heart… 

Or am I the one who is 

en-slaved…? 

September 2003', 'birbiri ardınca devrilen gecelerce,  bin bir gece boyunca;  yeniden doğayım diye ben;  aklını çeldim,  ruhunu zaptettim onun…  özgürlük…özgü...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ben-sehrazad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Secret love / Gizli aşk', 'secret-love-gizli-ask-zafer-zengin-etnika-xf1ty', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu

başka 

bir şey

gittiğinde

unutmanın

yanına takılmış

sarı

şarkılar

gözleri

kapalı dinlenen

nasıl

içli

sesleri

hissediyor musun

geliyor

gidiyor

hayat

gelmiyor

İçim

ölüm

gibi

sessiz

ağlıyor

11.09.2004



Nicos / Secret Love adlı parçasına gönderme...', 'bu başka  bir şey gittiğinde unutmanın yanına takılmış sarı şarkılar gözleri kapalı dinlenen nasıl içli sesleri hissediyor musun geliyor gid...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/secret-love-gizli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulamda Sakladığım Bu Özlemleri', 'zulamda-sakladigim-bu-ozlemleri-karahan-yilmaz-qpczs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Içimde zamansız başlayan ağrılarımı

Seni düşündükçe çoğalan yalnızlıklarımı

Şiirlerime sığdıramadığım mısralarımı

Anlatırım belki bir gün sana ben..

Gülüşüne sığınak olan umutlarımı

Sen gidince arsızlaşan korkularımı

Hayallerine çizdiğin fotoğraflarımı

Anlatırım belki bir gün sana ben..

Aşktaki ulaşılmazlığın gizemlerini

Ruhumda bıraktığın o derin izleri

Zulamda sakladığım bu özlemleri

Anlatırım belki bir gün sana ben

Düşlerinde  yarattığın bu haz’ ları

Sevişirken mırıldandığın şarkıları

Giderken bende unuttuğun aşkları

Anlatırım belki bir gün sana ben

Dokununca başlayan susmalarımı

Gözlerimde açtığın uçurumlarımı

Sevdanı ayartan duruşlarımı

Anlatırım belki bir gün sana ben

12.09.2004', 'Içimde zamansız başlayan ağrılarımı Seni düşündükçe çoğalan yalnızlıklarımı Şiirlerime sığdıramadığım mısralarımı Anlatırım belki bir gün sa...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zulamda-sakladigim-bu-ozlemleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Gitme', 'dur-gitme-talip-kaplan-xot9c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dur dinle sevgilim

Böyle çekip gidemezsin

Bir daha düşün sevgilim

Herşeyi böyle bitiremezsin

Bir gönül sözümüz vardı bizim

Hiç mi değeri yoktu

O büyük aşk yeminimizin

Bir anda hepsini silemezsin

Sarsılmaz bir güvenin vardı

Duymazdın hiç iftiraları

Dur gitme...

Son bir defa kalbimi dinle

(13 Ağustos 1992)', 'Dur dinle sevgilim Böyle çekip gidemezsin Bir daha düşün sevgilim Herşeyi böyle bitiremezsin Bir gönül sözümüz vardı bizim Hiç mi değeri yok...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dur-gitme-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara elveda...', 'bahara-elveda-mehmet-selim-tolay-9jc6h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak gördün mü,

bahar gözüne sürme çekmiş kaçıyor.

yüreğine cennet tohumlu ahu ağacını almış

ellerinde engerek düşlerini saklıyor.

bak gördün mü,

bir sevdiği var onun,

ona doğru uzatıyor

onunla paylaşıyor hallerini...

ey kıskandığım çiçeklerin mevsimi

ey ruhuma neş''e saçan ilk bahar! 

bize yok mu nimetlendiğin nimetlerle nimetlenmek

neden bütün aşklarım seninle başlamasın

seninle tükenmesin,

ey mevsimlerin efendisi...

sen huzurunla hep bir numarasın

bense varlığında kendimi kaybetmiş bir zavallı

sen varsan aşk var nefret var

sen varsan duygu var oluş ve yok oluş var

sen varsan', 'Bak gördün mü, bahar gözüne sürme çekmiş kaçıyor. yüreğine cennet tohumlu ahu ağacını almış ellerinde engerek düşlerini saklıyor. bak gördün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahara-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Bahçe', 'ay-bahce-reyhan-sur-ht6ms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bahçe diktim ay yüzüne

geceden

üç tomurcuk ateş düştü sabaha

biri güneş

biri çiçek

bir çocuk

çocuk deniz kırptı gözüyle

Japonca güldü çiçek

katmerlisinden..

peşpeşe yedi çift fildişi indi 

güneşten…', 'bahçe diktim ay yüzüne geceden üç tomurcuk ateş düştü sabaha biri güneş biri çiçek bir çocuk çocuk deniz kırptı gözüyle Japonca güldü çiçek ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ay-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Baba', 'uyan-baba-sehnaz-baykus-2nzdj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi uyan baba...

 Sabah olmadan çık balığa

 Oltan hasret kaldı sana

 Çaparin paslanacak dura dura 

Hem tam balığa çıkılacak hava 

Hadi uyan baba! 

 Hadi uyan baba...

 Tıraş takımların banyoda 

Aynanın önünde durmakta

 Hepsi bıraktığın yerde

 Uzamıştır sakalların tıraş olsana

 Hadi uyan baba! 

Hadi uyan baba...

 Bak palton eskidi dolapta

 Güz geldi geçti,kış kapıda

 Paltonu giy baba,hastalanma 

Bu soğuk havada,ayazda 

Hadi uyan baba! 

 Hadi baba uyansana...

 Uyansana baba! 

 Üzerinde yeşiller var

 Sen yeşili sevmezsin ki baba

 Baba? 

 Sıkılırsın orada

 O daracık dört duvar arasında

 Baba hadi uyansana

 Uyan baba uyansana

 Uyansana...

(hadi uyanabildiğiniz her günün tadını çıkarın! çıkın balığa...atın oltanızı derin sulara doya doya... çıkın sokağa...kurumuş yapraklar üzerinde dolaşmanın zevkini,kartopu savaşı yapmanın çocukluğunu tadın... hadi uyanın...)', 'Hadi uyan baba...  Sabah olmadan çık balığa  Oltan hasret kaldı sana  Çaparin paslanacak dura dura  Hem tam balığa çıkılacak hava  Hadi uyan...', ARRAY['Türk Edebiyatı','Şiir','Şehnaz Baykuş']::text[], 8.5, '{"poet":"Şehnaz Baykuş","poet_slug":"sehnaz-baykus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uyan-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Sarsıl Sevgimle', 'hadi-sarsil-sevgimle-pinar-yilmaz-z8plf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi sarsıl sevgimle, delirsin yüregin benimle

 Yokolalım tüm yokolmuşların yanından

 Kıskandıralım sevgiden anladıgını sanan yoksunları

 Kaçalım kendini bizden aldıgını sanan ortada oynayanları

 Çıldıralım aşktan,aşık benim diyen aç zavallıları

 Alalım kendimizi birbirimizden..gidelim sevgizlik yerinden', 'Hadi sarsıl sevgimle, delirsin yüregin benimle  Yokolalım tüm yokolmuşların yanından  Kıskandıralım sevgiden anladıgını sanan yoksunları  Ka...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hadi-sarsil-sevgimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum yoklugunda ben neyim?', 'bilmiyorum-yoklugunda-ben-neyim-adulera-ayza-deyq3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin en ortasındayım

Yıldızlar kayıyor ellerimden

Yalnızım,yapayalnızım

Bir sonbahar şarkısıdır dilimde

Hiçbir şey yok ki değişen

Özlemin yerli yerinde

Yüreğimin batı cephesindeyim

Hani insan tanımaz ya kendini

Bilmiyorum yoklugunda ben neyim', 'Gecenin en ortasındayım Yıldızlar kayıyor ellerimden Yalnızım,yapayalnızım Bir sonbahar şarkısıdır dilimde Hiçbir şey yok ki değişen Özlemin...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilmiyorum-yoklugunda-ben-neyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göl-Gemi(dir) ,Gece', 'gol-gemi-dir-gece-erol-dal-pqy1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kartal tüyü taktım saçıma,

Büyü, göl kenarında duran

Ağacın dibinde.

Git buradan gerçek

Toprak harap,

Bende kalan büyü değil

Kırılmış yorgun mızrak.

Uzakta bulanık çığlıklar

Duman ulak, ulak

Alevler karışık, 

Ağaç yanıyor,

Su kor oldu

Gece, 

Yangına alışık. 

Büyü, 

Bu gece bozuldu.

Hüzün, içimizde yanıyor oysa.

Mayalanmalı

Su katmalı biri

Pişmeli emek! 

Gerçek nedir ki? 

Bir tas, yavan yemek.

Dağı pus kapladı 

Gölü de sis

Geceye ulaştı kartal,

Ağaç görünmüyor.

Su, kabardı bu gece.

Ay suya girdi demek ki 

Gizlice.

Yakamoz kartal kayboldu

İz de, karıştı geceye

Çığlıklarını duydum su da,

Bir de seni, 

Buldum.

İz sürdüm bu gece,

Saçımdaki tüy şahit! 

Ay, adımlarımda 

Kartal, kanatlarımda

Saklı artık. 

Bir de ben 

Saklandım! 

Göl benim; 

Herşeyim!', 'Kartal tüyü taktım saçıma, Büyü, göl kenarında duran Ağacın dibinde. Git buradan gerçek Toprak harap, Bende kalan büyü değil Kırılmış yorgun...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gol-gemi-dir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-adulera-ayza-8i32k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu üç günlük dünyada

Üçüncü gün mesai bitimi

Yutkunma güçlüğün senden sonra

Sular seller ses yitimi

Bir kurşun askerim şimdi

Ve karşımda piyanente prusya

Halbuki ben isterim 

Gözlerimin uyarında saçların olsun

Kulagımın kıyısında  sesin

Genç ölümler gibi gitme ne olur? 

Denize dogru bir adım daha atma

Yeter zaten kapı komşum olsan 

GURBET teyimdir', 'Şu üç günlük dünyada Üçüncü gün mesai bitimi Yutkunma güçlüğün senden sonra Sular seller ses yitimi Bir kurşun askerim şimdi Ve karşımda piy...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gurbet-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sız’ı Bol Yaşamlar', 'siz-i-bol-yasamlar-orhan-turhan-g4xrr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşsiz, 

             Parasız,

                             Sağlıksız,

                                               Ve sahipsiz                                               

Bize  “sız”ı bol yaşamlar sunan  devran! 

Bizsiz, “sız”ların içinde boğulacağını bilmeden 

Nasıl da geleceğini karartıyorsun  her an? 

“Sız” zengini insanlar yaratmaksa marifet

Çırpınırken “sız” lar havuzunda,                                  

Arayacaksın geçmişi tüm gücünle dikkat et.

Kalacaksın yapayalnız,

Bilgisiz, 

             İlgisiz, 

                       Önemsiz,

                                 Ve de Sevgisiz… 

Anlayacaksın:

Sen  bizsiz  var olamazsın şüphesiz…', 'İşsiz,               Parasız,                              Sağlıksız,                                                Ve sahipsiz            ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siz-i-bol-yasamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyenisini Beklerken', 'ayyenisini-beklerken-galip-ozdemir-u1rdr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gökte yıldız pır pır eder

cevap verir kalbim…

hüzünlü laciverd bir sükûta düşerim

ayyenisini beklerken…

bilirim; 

sen beni sorarsın 

ay karanlık gecelerden 

beni sorarsın hıyabandan

yakar ellerini zamansız bir sevda 

ki sen bir ikindi çocuğusun…

hüzünlü laciverd bir sukûta düşerim

ayyenisini beklerken…

sonra,

bir bakış düşer yere

havada asılı kalır bir çift söz…

karışıp gider 

sabah yellerine…

bir kuru yaprak olur

kum olur…

ince bir sızı kalır mazide…', 'gökte yıldız pır pır eder cevap verir kalbim… hüzünlü laciverd bir sükûta düşerim ayyenisini beklerken… bilirim;  sen beni sorarsın  ay kara...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayyenisini-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-adulera-ayza-ss8uz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'serçenin kanat çırpışısın sen

tomurcuğun gülümseyişi yeryüzüne

bir çocuğun ayaga kalkışısın sen

ırmağın akışı delicesine

-------------

vurulup da belki bin yerinden

ölmeyişisin sen İNSANIN', 'serçenin kanat çırpışısın sen tomurcuğun gülümseyişi yeryüzüne bir çocuğun ayaga kalkışısın sen ırmağın akışı delicesine ------------- vurul...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insan-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kentime Yazdım Bu Şiiri', 'kentime-yazdim-bu-siiri-serpil-balcik-h6w1x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şehrin ortası, tam ortası,

Denizin en derin olduğu noktası gibi ortası...

Paslanmış çapa''nı

Ellerini parçalayıp kanatmak

Yüreğini dağlamak pahasına

O şehirde toplamaya uzanmak

Tutup çekmek için dokunamamak

Ve attığın yerde daha fazla batmasın diye direnmek

İşte bir kentli

O şehirlerde de akıntı var

Dalga

Köpük

Kayalık

Şehirler de dalgalanır.

Ve aynı kentin ortasında bir başka çırpınış...

Çapa salladığın, hala başka limana demirli

İpini  çekmeye asıldıkça bir hafifleme

İpin ucu geldiğinde ellerin boş

Çapan ipsiz, ipin çapasız artık.

Şehirler de tanıktır tanrı kadar

O kentler de pişmanlaşır

Suçluluk duyar susuşlarına

Aslında şehirler de konuşur

Şehirlerdir terk edilen, yürekler değil

Onlar sevdaların en sadık sırdaşıdır

Taşıyla, toprağıyla, göğüyle

Ama yine de kentlerdir terk edilen.

Bir şehrin tam ortası öyle küçüktürk ki

Sığmaz ayrı iki sevda 

Bu yüzden terk edilir şehirler, yalnız kalırlar

Şehirler hep yalnızdır

Sadece ortasındakiler sever onu

Onlar da bırakıp gider zor bile olsa.

Mahkumdur yalnızlığa şehirler,

Dalgalanmaya ve susmaya gönüllü...

Bir şehrin tam ortası,

Denizin en derin noktası gibi ortası

Küçüktür ve sığmaz iki ayrı sevdalı! 

MAYIS 2002', 'Bir şehrin ortası, tam ortası, Denizin en derin olduğu noktası gibi ortası... Paslanmış çapa''nı Ellerini parçalayıp kanatmak Yüreğini dağlam...', ARRAY['Türk Edebiyatı','Şiir','Serpil Balçık']::text[], 8.5, '{"poet":"Serpil Balçık","poet_slug":"serpil-balcik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kentime-yazdim-bu-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah aşktan esirgesin...', 'allah-asktan-esirgesin-ozgur-aysun-beksari-rj28y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öylesi yalancı bir maske takar ki yüzüne

Ardında onu arayan insanlar bırakır.

Öyle derin işlerki vefasız 

İnsanın yüreğine; 

Çoğu ocağını onun yoluna bırakır...

Yelkeni yırtık bir gemidir aşk 

Bizi hep okyanus ortasında bırakır.

Ve 

Öyle acımasız bir canavar ki o

İnsanda ne haysiyet nede gurur bırakır.

Bazen mutlu eder insanı saatlik yalanıyla

Ardından gözyaşı nefret, acı bırakır..

Amma; 

Öyle bir keskin falçatadır gavur! 

Dikiş tutmaz derin yara bırakır.', 'Öylesi yalancı bir maske takar ki yüzüne Ardında onu arayan insanlar bırakır. Öyle derin işlerki vefasız  İnsanın yüreğine;  Çoğu ocağını on...', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/allah-asktan-esirgesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun..', 'sen-yoksun-i-mdat-cakmak-qa486', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş artık  çıkmaz oldu  dağlara

Sevdan eksik.direnç tutsak  sen yoksun

Bedel  ödeyenler  kaldı  yollarda

Zâlim  atın oynatıyor,dur diyecek sen yoksun

Türküler isyanda sözler ihanet

Sazlar  düzen tutmaz oldu sen yoksun

Dermanı  tüketti dostlar  ne hayret

Ağlamak kader diyorlar,gül diyecek  sen yoksun

Karanlığa yıldızları  saçacak

Eşitliğe kol kanadın açacak

Umut ile  geleceğe bakacak

Savaşın düşmanı olan sen yoksun

Barış için sürgün olan  sen yoksun 

     Kavgam hedefini   seçti

     Başkaldıracak  sen yoksun

     Halklar zülme karşı koydu

     Birleştirecek  sen yoksun', 'Güneş artık  çıkmaz oldu  dağlara Sevdan eksik.direnç tutsak  sen yoksun Bedel  ödeyenler  kaldı  yollarda Zâlim  atın oynatıyor,dur diyecek...', ARRAY['Türk Edebiyatı','Şiir','İmdat Çakmak']::text[], 8.5, '{"poet":"İmdat Çakmak","poet_slug":"i-mdat-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-yoksun-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim derdim kaymakla bal gibidir', 'benim-derdim-kaymakla-bal-gibidir-mutlu-ayar-hsfh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim derdim kaymakla bal gibidir

Dertliler açsın kulağını duysun

Derdimin çoğu ilmihal gibidir

Dertsiz olanlar gülerek avunsun! 

06.05.04 / 22:15', 'Benim derdim kaymakla bal gibidir Dertliler açsın kulağını duysun Derdimin çoğu ilmihal gibidir Dertsiz olanlar gülerek avunsun!  06.05.04 /...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-derdim-kaymakla-bal-gibidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla beni', 'anla-beni-i-mdat-cakmak-cb9q2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara gözlüm senden umut

Bekliyorum,anla beni

Her geçen gün derdime  dert

Ekliyorum, anla beni

Olmaz deme kalbine  sor

Sevda  çekmek elbette  zor

Düşün  ne olur olma bir  kör

Yalvartmadan,anla beni

İhtiyacım  var sevgiye

Döndürme  beni  deliye

Kalbimi  başka kimseye

Kaptırtmadan,anla  beni

Alay etme hislerimle

Yaşıyorum düşlerinle

Yaş dolmadan gözlerime

Ağlatmadan,anla  beni

Yalnızlığım arkadaşım

Yoldaşımdır garib sazım

Bir gün  gelir mezar taşım

Dikilmeden,anla   beni', 'Kara gözlüm senden umut Bekliyorum,anla beni Her geçen gün derdime  dert Ekliyorum, anla beni Olmaz deme kalbine  sor Sevda  çekmek elbette ...', ARRAY['Türk Edebiyatı','Şiir','İmdat Çakmak']::text[], 8.5, '{"poet":"İmdat Çakmak","poet_slug":"i-mdat-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anla-beni-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-zafer-zengin-etnika-rv351', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çekip 

aldılar

aşk''ı

elimden

sizden

habersiz

o yüzden

öldüm 

ben

sövmem

bu

yüzden

bir şey vardı /

iklimdi

eylül

sizden

habersiz

hazan

çekip

aldılar

aşk''ı

o yüzden

şiir

bana 

yabancı

çevirmenlerden

öğrendim

adını

ah

sarı

yaman

sarı

almayacaktın

elimden

aşkımı

şimdi

ağlasam

usta

bana

inanır mı

ah

sarı

gölgen

sesinden

ayrı

almayacaktın

canımı

12.09.2004', 'Çekip  aldılar aşk''ı elimden sizden habersiz o yüzden öldüm  ben sövmem bu yüzden bir şey vardı / iklimdi eylül sizden habersiz hazan çekip ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yabanci-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce tanrım ve ben', 'yuce-tanrim-ve-ben-ozgur-aysun-beksari-nhnc5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sordu bana yüce tanrı

Dedi,'''' ne olmaktır dileğin''''? 

Baktım yukarıdan yeryüzüne 

Kuş olmayı diledim..

Kuş yaptı beni yaradan, süzüldüm yeryüzüne

Daha kanat çırpmadan

Saçma girdi göğsüme..

Bir avcıymış bunu yapan.

Çıktım tekrar gökyüzüne

Neden sıktı anlamadan.....

Yüce tanrım sordu tekrar

''''Ne olmaktır dileğin''''? 

Baktım yukarıdan yeryüzüne

Gül olmayı diledim.

Gül yaptı beni yaradan

Çıktım sulak  topraktan..

Koparıverdi bir el beni

Tomurcuğum açmadan...

Tekrar ölmüştüm işte

Nedendir anlamadan...

Sordu tekrar yüce tanrım

Ne olmaktır dileğim

Sırf vurulmamak için

Sırf koparılmamak için

Hava olmayı diledim.

Hava oldum, sil baştan...

Daha nefese karışmadan; 

Kara bir bulut geldi

Heybetli  fabrikadan..

Ne olduğunu

Tekrar hiç anlamadan....

Sordu son kez yaradan

''''Ne olmaktır dileğin''''

İnsan olmak istemem

Aman insan yapma dedim..

Beni onlara en uzak 

Dokunamayacakları

Bir yere bırak dedim..

Bir yıldız yaptı beni

Aldı gökyüzüne taktı..

Ve o gün bugün 

Beni vuran, koparan, 

Kirleten insanoğlu

Bilmeden hikayemi; 

Her gece bana baktı.', 'Sordu bana yüce tanrı Dedi,'''' ne olmaktır dileğin''''?  Baktım yukarıdan yeryüzüne  Kuş olmayı diledim.. Kuş yaptı beni yaradan, süzüldüm yery...', ARRAY['Türk Edebiyatı','Şiir','Özgür Aysun Beksarı']::text[], 8.5, '{"poet":"Özgür Aysun Beksarı","poet_slug":"ozgur-aysun-beksari","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yuce-tanrim-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahar Olacaksın', 'bir-bahar-olacaksin-mehmet-selim-togluk-uf0o5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutacağım sanma unutmak mümkün değil

Sen hep benim gönlümde taptaze kalacaksın

Yollarımda buz tutan karlı bir mevsim değil

Ömrüme ışık tutan bir bahar olacaksın.

Bende bu deli yürek, sende bu sevda varken

Unutmak mümkün mü ki, böylesine severken

Sigaramı yakıp ta yudum yudum çekerken

Aldığım her nefeste içime dolacaksın

Bu tatlı tebessümün durdukça gül yüzünde

Sen bana uzak değil, hep yakın kalacaksın

Güneşin aydınlığı sönse bile gözümde

Ömrüme ışık tutan bir bahar olacaksın.

		(Ankara - 01.04.1987)', 'Unutacağım sanma unutmak mümkün değil Sen hep benim gönlümde taptaze kalacaksın Yollarımda buz tutan karlı bir mevsim değil Ömrüme ışık tuta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-bahar-olacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsedi bebem', 'gulumsedi-bebem-zafer-zengin-etnika-v67mw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iyi geceler

kokusunu özlediğim deniz

iyi geceler umut

iyi geceler bebek

iyi geceler

bir dilenci

hayattan baska ne bekler

varsın aç olsun martılar

nasılsa hep denizdeler

üşürlerse

üstlerine maviyi çekerler

ya bebekler

kokularıyla dünyayı bekler

anne memesindedir eller

mavi sıcak şimdi

bebem gülümsedi

- baba şaykı söyleysem çabuk büyüyermişim

- söyle guzum

- duy baba.. aklıma gelebilsinde söylebilerim

güldü bebem çocukluğuyla

en acı şarkılarda

mavi sıcak şimdi

bebem gülümsedi

10.09.2004  bebelerime/üç tane', 'iyi geceler kokusunu özlediğim deniz iyi geceler umut iyi geceler bebek iyi geceler bir dilenci hayattan baska ne bekler varsın aç olsun mar...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulumsedi-bebem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-serap-demirturk-atswn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olmazlığında yokluluğunla

Eriyen ben miyim

Şu çocuğun elindeki

Boynu bükük dondurma mı...

Seni aramışım dün

Düşlerimin kafdağında

Bir yamaçta buldum sanıp

Kanmışım ki sorma gitsin.

Yüreğimde korun mu var,

Ellerimde terin mi var,

Gözlerimde izin mi var,

Nedensiz sevdiğim hazan.

Bir gülüş oldu bakışın,

Bir ağıt oldu kahırların,

Bir sevda oldu bu  yangın,

Bırak yandıkça yaksın.', 'Olmazlığında yokluluğunla Eriyen ben miyim Şu çocuğun elindeki Boynu bükük dondurma mı... Seni aramışım dün Düşlerimin kafdağında Bir yamaçt...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yangin-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamım', 'yasamim-serap-demirturk-dl6cm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamımı aldım ellerime,

Şöyle bir baktım da doya doya.

Ne vefalı bir yar buldum,

Ne fedakar dostlar...

Kara saplı bir bıçak gördüm,

Kara kaplı bir defter... 

O kadar... 

Gene de 

Ta uzaklarda bir ışık gördüm 

Ve odur beni yaşatan 

Can gibi 

Canım gibi 

Yaradanım...', 'Yaşamımı aldım ellerime, Şöyle bir baktım da doya doya. Ne vefalı bir yar buldum, Ne fedakar dostlar... Kara saplı bir bıçak gördüm, Kara ka...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasamim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Son Kurşunu Bana Sakla', 'anne-son-kursunu-bana-sakla-mehmet-sukru-kaplan-sebox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'anne son kurşunu bana sakla 

yüzüme buzdan kaleler yapan akrep 

düşlü çocuklar var yattığım gölgede 

ayak izlerini dişleyen poyraz 

ve sırlar sağıyor göğsümdeki utancı 

anne son kurşunu bana sakla 

geceye sığınan ay yüzlü kediler 

tırmalıyor kulak arkamdaki sisi 

ah! ..içimde yedi bıçak yedi cin ağzı 

zaman hırkasız bir yolcudur 

güvertesi küflenmiş bir gemide 

anne son kurşunu bana sakla 

çakmaktaşı anılar var döndüğüm kıblede 

çimen sürgünü geçmişiyle sevişen rüzgar 

kıvrak diliyle dövüyor sırtımdaki sancıyı 

uzayan tırnaklarında taşan gökyüzü 

sonsuz uykusuna çekiyor çıplak etimi 

anne son kurşunu bana sakla 

gece seslerine karışsın nefesim 

mehmet şükrü kaplan 

silifke-eylül 2004', 'anne son kurşunu bana sakla  yüzüme buzdan kaleler yapan akrep  düşlü çocuklar var yattığım gölgede  ayak izlerini dişleyen poyraz  ve sırla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anne-son-kursunu-bana-sakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm Yürü Güz Akşamı Yalnızlıktır', 'omrum-yuru-guz-aksami-yalnizliktir-mehmet-sukru-kaplan-pdhtw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ömrüm yürü güz akşamı yalnızlıktır 

ömrüm yürü güz akşamı yalnızlıktır 

ak kırağı üstünde posteriyle sevişen 

sırtıma yükledim ne varsa acıya dair 

fırtına sonrası yaşanan bir yangında 

sürgüne sığınıyorum her kapı çalmasında 

hangi aşka yatsam gece çıkıyor 

demir kakmalı kemeriyle 

ah! ..insan kendini bir kılabilmeli/sesiyle 

yırtmalı parmak arasındaki geceyi 

bana verecek neyiniz var boynunuzda 

küflenen muska izinden başka 

hangi korku kulesine atar kendini ruhunuz 

gidin suskunluğa düşmeden kireç çığlıkları 

tırnak yarıklarınıza çöl ekerek gidin 

çekin elinizi elma çiçeğine konan sisten 

saat başı cama vuruyor çakıltaşları 

ah! ..bir göçe yazdım adımı katıksız 

iki sonsuz pençe şakaklarımı kavrayan 

ağırlaşır gevşek kaldırımlar ben geçerken 

soğuk ağzını avuçlar göğsümdeki bıçak 

ömrüm yürü güz akşamı yalnızlıktır 

çocuk oyunlarında ebeliği hiç bitmeyen 

mehmet şükrü kaplan 

silifke-eylül 2004', 'ömrüm yürü güz akşamı yalnızlıktır  ömrüm yürü güz akşamı yalnızlıktır  ak kırağı üstünde posteriyle sevişen  sırtıma yükledim ne varsa acıy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/omrum-yuru-guz-aksami-yalnizliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Kara Yıldönümü!', 'eylul-kara-yildonumu-ozan-sah-turna-agdasan-rorej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '12 eylül darbesi

Halkım için zulüm geldi

Yerin dibine batası

Daha beter zalim geldi! 

Zulüm geldi, zulüm geldi

Daha beter zalim geldi! 

Tanklı-toplu yol kesildi

Gecekondular basıldı

Yurtsever gençler asıldı

Salkım için zulüm geldi! 

Umutlu sevdamız pak''tan

Şafaklar doğar ufuktan

Yarasa kaçar ışıktan..! 

Zulüm geldi, zulüm geldi

Daha beter zalim geldi! ..

Ezenlere seyran oldu

Soyanlara bayram oldu

Canlar zindanlara doldu

Halkım için zulüm geldi

Acı acı siren çaldı

Geceler ''Gündüz''ü aldı

ŞahTurna sürgünde kaldı

Baş belası zalim geldi...

Zulüm geldi, zulüm geldi

Daha beter zalim geldi! ...

Söz ve Müzik: Aşık ŞAhturna (Şah Turna9 Şah Turna  Yorum-Müzik yönetmeni: Ozan Şiar

''Halk Düşmanları'' albümü ve ''şakıyan Turna'' kitabı. Can Yayınlar İstanbul-Avrupa

ŞAHTURNA Kültür ve Sanat Evi

www.sahturna.com

Not: Sevgili Dostlar, değerli şiir sevenler...

Bu yapıtımızı, 12 eylül karanlığında, zulümler deryasında, ateş çemberinde yazıp-bestelemiştim. Sanatsevenlerimiz ve geniş Halk kitlelerimiz, pek çok acılar, baskılar, zulümler pahasına bu eserimizi, albüm ve kitaplarımızı yaşattılar yüreklerinde....

Acılara gark olan milyonların anısına...Yarınlarda doğacak güneşde; umut, dostluk, kardeşlik, barışa sevdalı türkülerimizde yansıyan şafaklar adına, karanlıkların inadına...

Sevgiyle kalın, umudunuz solmasın! ...', '12 eylül darbesi Halkım için zulüm geldi Yerin dibine batası Daha beter zalim geldi!  Zulüm geldi, zulüm geldi Daha beter zalim geldi!  Tank...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/eylul-kara-yildonumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ütopya..', 'utopya-kamil-caglar-aksu-08t05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayal

Bir gökkuşağına salıncak kursam,

Berrak huzur meltemleri ritmiyle,

Renkler kayboluncaya dek sallansam..

Bu hırçın rüzgarlara kement atsam,

Deniz taşmasa,yaprak dökülmese,

Hayal burağıyla gerçeğe uçunca,

Güneşten kurtulan ilk ışık olunca,

İlk delen benim tanyerinde karanlığı..

Bir şafak, gecenin sırrını bulsam..

Bir gece en uzak yıldıza varsam,

Dönünce olur mu dünya yerinde,

Orada başka bir yarla  tanışsam.

Dönünce olur mu acep  yerinde ? ...', 'Hayal Bir gökkuşağına salıncak kursam, Berrak huzur meltemleri ritmiyle, Renkler kayboluncaya dek sallansam.. Bu hırçın rüzgarlara kement at...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çağlar Aksu']::text[], 8.5, '{"poet":"Kamil Çağlar Aksu","poet_slug":"kamil-caglar-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/utopya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veriyor', 'veriyor-mumtaz-begen-j0fqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi zâlim, aklı zulme eriyor,

Kimi mazluma, kol- kanat geriyor.

Hüküm sahibinin işi böyledir,

Kime ne lâzımsa, onu veriyor! ...', 'Kimi zâlim, aklı zulme eriyor, Kimi mazluma, kol- kanat geriyor. Hüküm sahibinin işi böyledir, Kime ne lâzımsa, onu veriyor! ......', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/veriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül küçüktü', 'eylul-kucuktu-zafer-zengin-etnika-x3y46', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eylül

küçüktü

bizde

| onların çocukları çalışkan

  herşeyi aldılar..bize direnmek ve umut kaldı |

bilmezdik

neden

ölür

ablalar

abiler

neden

düşer

karanfiller

bir

yerimizde

kurşundan

işkenceden

izler

karabulut

eylül

küçükken

üstümüze

düşer

yüreğimizde

karanfiller

12 Eylül 2004', 'eylül küçüktü bizde | onların çocukları çalışkan   herşeyi aldılar..bize direnmek ve umut kaldı | bilmezdik neden ölür ablalar abiler neden ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/eylul-kucuktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göl Damardan Beslenir', 'gol-damardan-beslenir-erol-dal-e1etl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kartal tüyü taktım saçıma,

Büyü, göl kenarında duran

Ağacın dibinde.

Git buradan gerçek

Toprak harap,

Bende kalan büyü değil

Kırılmış yorgun mızrak.

Uzakta bulanık çığlıklar

Duman ulak, ulak

Alevler karışık, 

Ağaç yanıyor,

Su kor oldu

Gece, 

Yangına alışık. 

Büyü, 

Bu gece bozuldu.

Hüzün, içimizde yanıyor oysa.

Mayalanmalı

Su katmalı biri

Pişmeli emek! 

Gerçek nedir ki? 

Bir tas, yavan yemek.

Dağı pus kapladı 

Gölü de sis

Geceye ulaştı kartal,

Ağaç görünmüyor.

Su, kabardı bu gece.

Ay suya girdi demek ki 

Gizlice.

Yakamoz kartal kayboldu

İz de, karıştı geceye

Çığlıklarını duydum su da,

Bir de seni, 

Buldum.

İz sürdüm bu gece,

Saçımdaki tüy şahit! 

Ay, adımlarımda 

Kartal, kanatlarımda

Saklı artık. 

Bir de ben 

Saklandım! 

Göl benim; 

Herşeyim!', 'Kartal tüyü taktım saçıma, Büyü, göl kenarında duran Ağacın dibinde. Git buradan gerçek Toprak harap, Bende kalan büyü değil Kırılmış yorgun...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gol-damardan-beslenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağacın altında ki sen', 'agacin-altinda-ki-sen-gokay-sofuoglu-7arnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ağacın altına 

		gölgesine sığınmışım

Elimde gazete

	son ölenlere dökülen 

	gözyaşlarının resimlerine bakıyorum

“Emine gel kızım” dedi annesi

		başını öne eğmiş

	yorgunluktan düşme noktasına gelen kızına

...

İşe gideceğim

	resimleri bekliyorum

	kafamda bin bir türlü resim

Karşımda biri sigarasından çekerken 

		gözleri yaşarıyor

Sigaranın dumanı mı, kafasının dumanı mı

				bilinmez

...

Ben seni düşünüyorum

	dizime uzattığın başını

	topladığım saçlarını arabadan

	sevincimi paylaşmak için 

dokundurduğun öpücüğü yanağıma

Aslında başka şey de düsünmüyorum ağacın altında

Çocuğun temiz yorgunluğunda 

Hafif rüzfarın sigara dumanın savurmasında,

Cıvıl cıvıl ötüşen kuşların sevincinde

Seni düsünüyorum,

Ve

Yüzümdeki tebessümün nedenini

		şimdi daha iyi anlıyorum...', 'Bir ağacın altına  		gölgesine sığınmışım Elimde gazete 	son ölenlere dökülen  	gözyaşlarının resimlerine bakıyorum “Emine gel kızım” dedi a...', ARRAY['Türk Edebiyatı','Şiir','Gökay Sofuoglu']::text[], 8.5, '{"poet":"Gökay Sofuoglu","poet_slug":"gokay-sofuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/agacin-altinda-ki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçılar', 'balikcilar-atil-kesmen-ihyie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Balıkçılar..				

Yelken açmış mavi görülmezliğe..				

Dinmiyor dinmek bilmiyor..				

Gönüllerinde umut rüzğarları..				

Estikçe gönüllerinde umut rüzğarları..				

Baktıkça bakıyor dalğın dalğın..				

Masmavi olmuş o gözleri...				

				

				

Gün doğar..				

Gün batar olmaz olamaz onlara derman..				

Maviliktir onların dövdüğü harman..				

Döner döner onlar maviliklerde..				

Umut kokuyordur yürekleri..				

Beklemek  beklemek..				

Yine beklemektir onların hedefleri...				

				

				

Aramaz onlar sormaz onlar..				

Umut olacak sevğilerini başka gönüllerde..				

Maviliktir onların sevği denizi..				

Görmez gözleri duymaz kulakları..				

Mavi''den başka ne bir sesi ne bir renği...', 'Balıkçılar..				 Yelken açmış mavi görülmezliğe..				 Dinmiyor dinmek bilmiyor..				 Gönüllerinde umut rüzğarları..				 Estikçe gönüllerinde...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/balikcilar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sensin Sen', 'o-sensin-sen-atil-kesmen-rzpao', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O sensin sen			

Gönlümün tek sultanı			

Sana bakıpta sen olan gözlerimin			

Vaz geçilmez aşkı...			

			

			

O sensin sen			

Nefes alıp verdiğim			

Sana bakan gözlerimde seni sevdigim			

Hiçbir zaman vaz geçemediğim			

Aşık olup 			

Sen benim aşkımsın diyebilidiğim			

			

			

O sensin sen			

Aşkı bana öğretipte aşık eden			

Adım diye hep seni bilen			

Aşkım diye tastamam sende gezen			

O sensin sen			

			

			

Yemin ediyorum			

O sensin sen			

Sen benim aşkımın son nefesi			

Sana bakan gözlerimin son feri			

Sana tutuklu kalan bedenimin			

Aşk kokan tek terisin....', 'O sensin sen			 Gönlümün tek sultanı			 Sana bakıpta sen olan gözlerimin			 Vaz geçilmez aşkı...			 			 			 O sensin sen			 Nefes alıp verdi...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-sensin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veni Vidi Vici', 'veni-vidi-vici-yusuf-batum-7nskf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geldim

soyunarak ana rahminden

cigerlerime birikmis

ahir zaman cigligi

bastigimda, henuz

ayaklarim yere degmemisti...

gordum

dengeledigimde ayaklarimi

en uzak memleketlerini

ve ahvalini afakin

bulutlari dagitmak istedim

beceremeyince

edebimle sovdum...

fethetmeden gidiyorum

duy beni Caesar! 

takip takistirdim

nerde ne gunah

nerde ne sevap

varsa,

doldurarak bugzedislerimi

yuregimin kumbarasina

cekiliyorum...

reddedisim bundan

kana kana susasam da

iblisin sundugu

son kadehi...', 'geldim soyunarak ana rahminden cigerlerime birikmis ahir zaman cigligi bastigimda, henuz ayaklarim yere degmemisti... gordum dengeledigimde ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Batum']::text[], 8.5, '{"poet":"Yusuf Batum","poet_slug":"yusuf-batum","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/veni-vidi-vici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Hele..', 'bak-hele-tulay-eker-ur87u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlığın arasında doğdu tebessüm 

Munzur esti leylim leylim 

Fırat aktı 

Dicle vurdu göğe 

Oyy oyyy diyesim geldi yine 

Hançer saplanan yüreğime 

Dizginler kaçkın 

Zapteylemek zor 

Hele tutan yokmu uçuyor fırtına 

Uçurtmalar tele takılmamış bu sefer 

Gülümsetiyorum şerefine diyor sol yanım 

Mırra içer misin? 

Şah damarından yakaladım işte 

Bıçağın iki yüzünde gece 

Vurur...vurur tene 

Oyy karasına yandığım gece 

Vur hele vur bir daha vur 

Kemikleşmiştir dokunduğun yer 

Kanamaz..saramaz.. 

Bak bebe kokuyor 

Bak hele süt kokuyor 

Sevgi bu! 

Bir nefes alır mısın 

Herşeye inat koynunda sarar mısın 

Kirpiklerim vurmuş birbirine 

Arasından akar Kızılırmak 

Yedi gök kubbe arası 

Esmişem yine 

Estirmişem........ 

Celladın elinde kılıç 

Elimde bir tek tebessümün sıcacık 

Vursun hele! 

Sakın gitme demeye geldim 

Boyun büker sol yanım 

Sağ yanımsa hiç sorma 

Kalmışam cenderede 

Sakal bıyık hesabı 

Vurmuşam beline beline 

Diz büksün hele 

Şehrim yanık 

Varoşlara konmuş sokaklarım 

Kaldırımlar sen... 

Basamam üstüne 

Sokak lambalarım sen 

Gözlerimi alamam 

Ortasında bir ateş 

Yüreğimi söküp atamam 

İşte sana dize 

Bak hele 

Şiir deme 

Yürek soframdasın 

Tadmışsan,ekmeğini banmışsan 

Yediğin tabağa yüz çevirme 

Bak hele 

Kal..gitme 

Dağlarımı devirme 

Öksüz bırakıp 

Ölümü ellerime verme. 

esereklerden...geldiği gibi geçen yağmur damlalarından... aç avuçlarını dolsun...yanan bir ateşse, külün kalsın...bil hele.', 'Karanlığın arasında doğdu tebessüm  Munzur esti leylim leylim  Fırat aktı  Dicle vurdu göğe  Oyy oyyy diyesim geldi yine  Hançer saplanan yü...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bak-hele-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin...', 'nerdesin-sih-mahmut-kiran-g1pmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilinmezliklerin aşinalığına bel verdiğim

Kaç gün kaç gece geçti seni düşünerek yitirdiğim

Ömrüm:

Viraneliğine,yıkılmışlığın en beter hali

Ömrüm:

Sensizliğin sızısıyla her defasında

Daha bir keşmekeş olduğum

Ve ömrüm:

Neresindedir bunun vuslatı deyip

Başımı nemli duvarlara çaresiz yasladığım

Ömrüm,ömrüm,ömrüm:

Gurbet akşamlarında kibrit aydınlığıyla

Bir melek aradığım

Anlamadın bu çaresizliği

Anlayamazdın zaten

Kendini tanımayan bu serseriyi...

Ama sıyrılıyorum

Sıcak bir kucağın avuntusuna yelken açtım

Sabır taşlarını yeniden dizdim

Bir tek soru var sadece

Meleğim nerdesin?', 'Bilinmezliklerin aşinalığına bel verdiğim Kaç gün kaç gece geçti seni düşünerek yitirdiğim Ömrüm: Viraneliğine,yıkılmışlığın en beter hali Ö...', ARRAY['Türk Edebiyatı','Şiir','Şıh Mahmut Kıran']::text[], 8.5, '{"poet":"Şıh Mahmut Kıran","poet_slug":"sih-mahmut-kiran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdesin-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiz..hayat ve kuru günde yağan.. iç üzerine anlayıp gülmek', 'eskiz-hayat-ve-kuru-gunde-yagan-ic-uzerine-anlayip-gulmek-zafer-zengin-etnika-0aljf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bıraktım elbet

ateşi kendi haline

nazı kaprisi ve 

bir sürü şeyi

ah şu gülmek yok mu

içinden söküyor adımı

hüzne bağlanmışsa elleri

gül yakan dönüyor

ve naz ediyor ayrılıklar

etinden ısırıyorum seni açlık

sevdalı tüm yükseltiler

inişler çıkışlar

farkına varışlar

ayırlıklar

sorarsın derdin ne

açım der gece

ne yersin 

kimse bilmez hecelerde

üç asırdır yollarda 

taş duvarlar ardında

hiç söylenmemiş

sözler var mı aklında

şimdi yaz şu tahtaya

ezberle

ölüm nasıl gelirmiş bekle

bilgenin hasretidir

ölmeden önce

biraz daha düşünce

yoksa kibri yok gercekte

çekip gidecek elbette

belki sabah

belki gece

asıl bilmemek işkence

su içelim

sıcak önce ten yakar

sonra yüreğe ulaşır

içine açlık karışır

dünya tutuşur dizelerde

için görünüyor zalım

şairsin kendince

köpüklensin dillerde

| demiştim..tüm düşler çalınır

hırsızları vardır

paradır

arsızdır

insanı yoldan çıkartır 

bu yüzden sevmem

müsade almadan kalp çalanı |

dilim var mı anlatayım

bir su ver falına bakayım

aslında inanmadığım

görürüm işte

varsa içine sakladığın

Öncelikli şeyler

açlığa bulaşan eller

yemeği yağıyla yerler

çatlamak güze mahsustur

yaşlılıktır adı

önce para 

sonra sağlık

önce sağlık

sonra para

neyle uğraştın

orta da işte

baktığın hayatın

| düşün ki tek değilsin

yinede farklısın

aykırısın

aslında aynısın

aynı yoldasın

her göz gibi

sende ıslanmalısın  |

duvara çivi çak ve bak

zırhın orda

çivinin ucunda

aman ha 

sakın kırılma

hayatın

japon yapıştırıcısı

yok daha

olsaydı

yağmur ormanlarında

ağaç yapıştırırlardı

yağmura bulutu

çatılara  karı

gökyüzüne güneşi

ellere imanı

| sevmek onda baslar |

vardığın kadardır hayat

vardığın kadar

sorduğun kadar

hepsi bu

gülmeye bakar

eni sonu

neydi son güldüğün tarih

o gün işte

ağustos 2004', 'bıraktım elbet ateşi kendi haline nazı kaprisi ve  bir sürü şeyi ah şu gülmek yok mu içinden söküyor adımı hüzne bağlanmışsa elleri gül yaka...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/eskiz-hayat-ve-kuru-gunde-yagan-ic-uzerine-anlayip-gulmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Resmi', 'mutlulugun-resmi-sih-mahmut-kiran-bxed3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hani ‘bir resim çiz’ demiştin bana

‘müstakil bir aşk olsun içinde

ve bir rüzgar essin ki

yüreğim yüreğine kenetleniversin o fırtına...

ve bir yağmur yağsın ardından

toprak kokusu eşikten geçip-merhaba! Desin

sevgiye, çırpınan yüreklere ve geç kalmışlığa Merhaba! ’



ve ‘bir kenara bir düzine çocuk çiz’ demiştin; 

‘her birinin adı birbirine benzeyen

gözleri en az bizim ki kadar parıltılı olan...

şurda burda bir yaramazlık yapsınlar

mesela komşu kızına laf atıp

bizim de yaptığımız gibi

kaçamak bir sevda yaşatsınlar o minik yüreklerinde...’



‘kuşlar öyle içten söylesinler ki bizim şarkımızı

güller daha bi güzel açsın bahçemizde...

gelip geçenler tebessümle baksın halimize

kıskançlık, nefret olmamalı çevremizde...’



olmadı BİR TANEM

çizemedim o dediğin resmi...

ve sen BİR TANEM sen

apansız kaçarken kırmıştın zaten fırçamı...



artık sen de biliyorsun ya! 

Olmayacak hiç... o ev,bahçe ve çocuklar

Ve olmayacak bizim şarkımızı söyleyen kuşlar

Ve tebessümle bakan insanlar

Ve ben mutluluğun resmini çizemeyeceğim

Belki resim çizmeyi de unutmuşumdur.

Kim bilir? 

Zaten hiç niyetim de yok...

Peki sen

Çizdirebilecek misin bakalım

O aptal baytara böyle bir resim

komik gelecek sana ama

olsa olsa

birkaç öküz bir de ahır çizer sana

güzel güzel seyredersiniz siz

mutlu bir aile tablosu gibi gelir önce

yoldan gelip geçenler burunlarını tıkarlar

ve kargalar söyler ancak o iğrenç mırıltınızı

dönmek istersin geriye

kapımı çalar af dilersin belki de

ve dehşete kapılırsın o an

tıpkı sana benzeyen biri açar kapıyı

‘öyle biri yok’ der

‘bir şair var içerde sadece’

ve ben çıkarım karşına

birkaç sözcük fısıldarım kulağına, ağlarsın

sonra sayıklaya sayıklaya dönersin geriye

‘mutluluğun şiirini bilir misin? ’

‘mutluluğun şiirini bilir misin? ’...', 'hani ‘bir resim çiz’ demiştin bana ‘müstakil bir aşk olsun içinde ve bir rüzgar essin ki yüreğim yüreğine kenetleniversin o fırtına... ve bi...', ARRAY['Türk Edebiyatı','Şiir','Şıh Mahmut Kıran']::text[], 8.5, '{"poet":"Şıh Mahmut Kıran","poet_slug":"sih-mahmut-kiran","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/mutlulugun-resmi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-sih-mahmut-kiran-8ot1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yapılmamış birkaç iş kalmıştır geride:

sevgiliye söylenmemiş sözler gibi

yaradana gönül rahatlığıyla gitmek gibi

kim bilir belki de

zirvenin ihtişamı ile

uçurumun dibine meydan okumak gibi

ve yahut inadına tam tersi...



ve yazılmamış, söylenmemiş kelimeler gibi

burukluğunu hissettiren bir duygu kalmıştır:

yarım kalmış şiirler gibi,

ve yahut daha tasarlanmamış romanlar gibi...



ölüm:

insanın kendiyle en içten dertleşmesi

ölüm:

ruhun toprağa veda etmesi

ve ölüm:

yalnız yaşanan ve yine ölüm ki:

kendinden başkasına insafsızca yâr etmeyen', 'yapılmamış birkaç iş kalmıştır geride: sevgiliye söylenmemiş sözler gibi yaradana gönül rahatlığıyla gitmek gibi kim bilir belki de zirvenin...', ARRAY['Türk Edebiyatı','Şiir','Şıh Mahmut Kıran']::text[], 8.5, '{"poet":"Şıh Mahmut Kıran","poet_slug":"sih-mahmut-kiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Gibi Birşey', 'duygu-gibi-birsey-sih-mahmut-kiran-epvtq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yorgun argın bir ruha sarılmışsın,

kadavraları hiçe sayarcasına…

anılardan bunalmış gibisin,

şikarlık korkusuyla kaçan nazlı ceylan gibi ürkek

yahut; 

özlemine yandığın o dost kollara varmak ister gibisin…



zamansız hüzünler…

zamansız aklar…

apansız ayrılıklar…



ama umut ışıklarını hiç söndürmedin ki…

o alaca karanlığı getiren amansız vurguna,

gülüşleri zoraki yapaylığa iten yılgınlıklara,

hiç yenilmedin ki…



hep güleç

hep hayat dolu,



azim dolu

sevda dolu, ne desem bilmem ki? 



“duygu gibi bir şey olmalı… ne dersin? 



(Sadece bir dost için….)', 'yorgun argın bir ruha sarılmışsın, kadavraları hiçe sayarcasına… anılardan bunalmış gibisin, şikarlık korkusuyla kaçan nazlı ceylan gibi ürk...', ARRAY['Türk Edebiyatı','Şiir','Şıh Mahmut Kıran']::text[], 8.5, '{"poet":"Şıh Mahmut Kıran","poet_slug":"sih-mahmut-kiran","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duygu-gibi-birsey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokundugum', 'dokundugum-nazim-ercan-zts0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgun imgelerin fisiltilari yansiyan duslerden

Bir kelebek dokunusu

Tum ask sarkilarindan artakalan

Zincirlenmis duslerin 

Prangalarindan kurtuldugu 

iniltilerin melodisinde duyumsanan

Aci

Selam

Gene o kanli sozcuk

Tarihe sizmis palyacolarin

Katliamlarinin hakli sebeplerini

Anlatiyor bir dil

Bir posta guvercinin kanatlarinda

Agustos boceginin sarkisi

Zamani geldi aci cekmenin

iri gozleriyle bir baykus

iki dal, iki gece arasinda; 

Alaca gozlerle bakiyor sabaha

Gene kanamis gece

Gene; 

Belki de; cigliklardan artakalacak bir zamanin

Tortusuyum ben? 

inancsiz duslerimin kalintilari 

Gozkapaklarimin altinda.

Gene de; kaniyor gece

Sabaha karsi

Yari gunes yari ay ayazinda

Bir enstrumanin sesiyim ben

Dokundugum sabahin teni

Ama sen? 

Gene o kanli sozcugu

Siirin ecesinin

SELAM!', 'Yorgun imgelerin fisiltilari yansiyan duslerden Bir kelebek dokunusu Tum ask sarkilarindan artakalan Zincirlenmis duslerin  Prangalarindan k...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dokundugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Kızım', 'can-kizim-can-ozcan-ozkan-9wt9i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay, 

Kazma-Kürek yaktıran

Yıl,

Milenyumu iki geçe

Saat,

Çarşambaya beş var

Ve Sen 

Bahar yağmurlarına 

Üç kala 

Yağdın dünyama

Hoş geldin...

O minik ellerinle tuttuğun

Göz yaşlarıma...

Can Kızım...

Nazlıcan’ ım

Duru suyum...

Hoş Geldin...', 'Ay,  Kazma-Kürek yaktıran Yıl, Milenyumu iki geçe Saat, Çarşambaya beş var Ve Sen  Bahar yağmurlarına  Üç kala  Yağdın dünyama Hoş geldin......', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/can-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinin Merkezine Yaşama Salıncak Kurdum', 'hasretinin-merkezine-yasama-salincak-kurdum-yuksel-ozbek-t6sp2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretinin merkezine,

Yaşama:

Salıncak kurdum.

Gidiş-gelişlerine odaklandı

Gülümseyen sevdamız.

Gidişinde köreldim,

Küçüldüm,bir yanım boşaldı.

Gelişin şenlikti günüme,

 Nehir oldum 

Okyanusuna! asice taşan,

Ulaştıkça, coşan..

Hiç gidilmemiş yerin,

Yaşanmamış anın,

Ölüm öncesi son istencin,

Müptela içicinin

Son sigarasına bakışıdır

“Salıncakta” sana bakışım.

Güncem akışkanlığını kaybetti,

Sen geldin,zaman durdu.

Sözcüklerin bittiği yerdesin.

Gün yüzünü dönmeden,

Takıver boşvermişliğimi koluna,

Sevgini anımsat gerçeklerime.

Düşlerim açsın geceni,

“Köşemde” düşün beni sevgili.

Zaman dursun,biz geçelim ötesine...', 'Hasretinin merkezine, Yaşama: Salıncak kurdum. Gidiş-gelişlerine odaklandı Gülümseyen sevdamız. Gidişinde köreldim, Küçüldüm,bir yanım boşal...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hasretinin-merkezine-yasama-salincak-kurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğe Ağıt I', 'kucuge-agit-i-zafer-zengin-etnika-8m36l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geldin mi 

küçüğüm

küçük 

ellerinle

hadi

beni

