INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey hayât', 'ey-hay-t-sair-ahrazi-h7io0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avutsan da bahtımı yalancı bir sabahla,

Son akşamın alnına yarınları koysan da,

Nâfilesin ey Hayât,neyin var ki sunacak? 

Fânî kılan miâdı yeni baştan aysan da,

Cân bu yorgun zamânı yaşamak mı sanacak? 

***', 'Avutsan da bahtımı yalancı bir sabahla, Son akşamın alnına yarınları koysan da, Nâfilesin ey Hayât,neyin var ki sunacak?  Fânî kılan miâdı y...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ey-hayat-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşku', 'kusku-ufuk-nazim-l5vtc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşku umudun güvesidir,

Ve ağır ağır 

Sızar içine.

Karanlık ordular gibi

Kuşatır hislerini.

Kuşku güpe gündüz

Güneşi saran bulutlar gibidir.

Sarsar aydınlığa güvenini

Yıkılırsın ışık ışık

Akan suyun yüzünden.', 'Kuşku umudun güvesidir, Ve ağır ağır  Sızar içine. Karanlık ordular gibi Kuşatır hislerini. Kuşku güpe gündüz Güneşi saran bulutlar gibidir....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kusku-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Sen', 'kiz-sen-atil-kesmen-zpdp3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kız sen.... 

Şu dağlara bakar”mısın... 

Ne kadar dumanlı ne kadar endamlı değil”mi... 

Sakın....Sakın imrenme o dağlara... 

Sis bürümüş onların tüm heybetini... 

Kendilerinden korkuyorlar.. 

İçin için çürüdükçe... 

Bir yudum nefes dilenirler.. 

Görünüpte bilinmezliklerinde.......

Dağlar...Dağlar... 

AMA......yaman ağlar bu dağlar... 

Her sabah güneşini bekler bu dağlar.. 

Bir bakımlık gözlerine doğacak... 

Onlara yalnızlığını unutturacak... 

Onlara yıllanmış düşüncelerinde yol gösterecek.. 

Bir avuç sevgi arar bu dağlar............... 

Kız Sen.... 

O dağlar kadar yaşlı değilsin... 

Neden çekiniyorsun... 

Geçmiş yüzyıllarda senin imzan yok... 

Tarih kitapları seni yazmıyor... 

Saçlarına dahi.... daha ak düşmedi.. 

Yüzün kırışmadı.. 

Parladıkça parlıyor gözlerin... 

SEN.......O dağlarla arkadaş olamazsın... 

SEN.......O dağlar gibi sisli dumanlı kalamazsın... 

SEN.......O dağlar gibi gizem dolu.. 

Anlaşılmaz düşüncelerde yol alamazsın............. 

Kız Sen...... 

Yeni doğmuş bir fidansın... 

O dağlar kadar...... yaş kalacaksın... 

O dağlardan.......... can kan alacaksın... 

Dalın narin........... Yaprakların taze... 

Estikçe rüzgar... 

Kımıldadıkça bedenin.... 

Gördükçe gözlerin kendini kendinde..... 

Düşüncelerin... 

O zaman seni büyütecek... 

O zaman seni yüceltecek... 

Bu yaşam sevgisinde..... 

Gün gelecek.... 

Zaman kendinde tükenecek... 

Kız Sen''de bir sabah uyandığında... 

O dağlar gibi.. 

Güneşin doğmasını bekleyeceksin... 

Belki.....bir yudum sevgi diye...', 'Kız sen....  Şu dağlara bakar”mısın...  Ne kadar dumanlı ne kadar endamlı değil”mi...  Sakın....Sakın imrenme o dağlara...  Sis bürümüş onla...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/kiz-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
